(function(){"use strict";var w=window.ScripturaJosephusTexts||(window.ScripturaJosephusTexts={});var a=w.antiguidades||(w.antiguidades={});a[17]={"book":17,"title":"Τάδε ἔνεστιν ἐν τῇ ἑπτακαιδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς Ἀντίπατρος ἐμισήθη ὑπὸ παντὸς τοῦ ἔθνους διὰ τὴν ἀναίρεσιν τῶν ἀδελφῶν αὐτοῦ καὶ ὡς διὰ ταῦτα ἐθεράπευεν τοὺς ἐν Ῥώμῃ πολλοῖς χρήμασιν καὶ τὸν πεπιστευμένον τὴν Συρίαν Σατορνῖνον καὶ τοὺς σὺν αὐτῷ ἡγεμόνας.\n\nὡς Ἡρώδης ὁ βασιλεὺς ἰδὼν τὴν Τραχωνῖτιν χώραν μὴ δυναμένην εὐσταθεῖν διὰ τὰς ἐπιδρομὰς τῶν Ἀράβων, Ζάμαριν Ἰουδαῖον ἐκ Βαβυλῶνος ὑποχωρήσαντα καὶ ἐν Ἀντιοχείᾳ διαιτώμενον μεταπεμψάμενος ἐγκατῴκισεν αὐτῇ, καὶ ἐχρῆτο αὐτῷ προβλήματι πρὸς τοὺς Ἄραβας.\n\nὡς Ἡρώδου τοὺς Ἀλεξάνδρου καὶ Ἀριστοβούλου τῶν υἱῶν αὐτοῦ παῖδας προσποιησαμένου καὶ τὰς Φερώρα θυγατέρας μνηστεύσαντος αὐτοῖς, Ἀντίπατρος ἔπεισεν τὸν πατέρα τὴν μνηστείαν εἰς τοὺς παῖδας μεταθέσθαι τοὺς αὐτοῦ. καὶ ὡς ἐθεράπευσεν Ἀντίπατρος τοὺς περὶ Φερώραν βουλόμενος ἤδη δι' αὐτῶν ἐπιβουλεῦσαι τῷ πατρί.\n\nὡς γνοῦσα ἡ ἀδελφὴ τοῦ βασιλέως Σαλώμη κρυφαίως ἀπήγγειλεν τῷ ἀδελφῷ.\n\nὡς Ἡρώδης παρήγγειλεν Ἀντιπάτρῳ μὴ φοιτᾶν πρὸς Φερώραν μηδὲ ἀπόρρητον μηδὲν ἀπαγγέλλειν αὐτῷ. ὁ δὲ φανερῶς μὲν οὐδὲν ἐποίει, ἀλλὰ κρυπτῶς, καὶ ταῦτα δὲ οὐκ ἐλάνθανεν τὸν Ἡρώδην.\n\nὡς Ἀντίπατρος ἔγραψεν τοῖς ἐν Ῥώμῃ φίλοις παρακαλῶν αὐτοὺς γράψαι τῷ πατρὶ αὐτοῦ πείθοντας, ἵνα πέμψῃ αὐτὸν πρὸς Καίσαρα μετὰ πολλῶν χρημάτων, καὶ πεισθεὶς Ἡρώδης ἐξέπεμψεν τὸν υἱόν.\n\nὡς Ἀντίπατρος ἔπεισεν Φερώραν, ἵνα ἀνέλῃ τὸν πατέρα αὐτοῦ Ἡρώδην φαρμάκῳ δοὺς αὐτὸς τὸ φάρμακον τῷ Φερώρᾳ. καὶ ὡς ὁ βασιλεὺς Ἡρώδης παρήγγειλεν τῷ ἀδελφῷ αὐτοῦ Φερώρᾳ ἐκβαλεῖν τὴν γυναῖκα αὐτοῦ ἢ ἀναχωρῆσαι ἐκ τῆς βασιλείας. ὁ δὲ ἀσμένως ἤκουσεν καὶ ἀνεχώρησεν εἰς τὴν ἰδίαν τετραρχίαν κἀκεῖ μετ' οὐ πολὺ τελευτᾷ.\n\nκατηγορία τῆς γυναικὸς Φερώρα ὑπὸ τῶν ἀδελφῶν Φερώρα ὡς ἀναιρεθέντος φαρμάκῳ. καὶ ὡς Ἡρώδης ἐκζητήσας εὗρε τὸ φάρμακον κατεσκευασμένον ἐπ' αὐτῷ ὑπὸ τοῦ υἱοῦ αὐτοῦ Ἀντιπάτρου, καὶ βασανίσας ἔγνω τὰς Ἀντιπάτρου ἐπιβουλάς.\n\nκατάπλους Ἀντιπάτρου ἐκ Ῥώμης πρὸς τὸν πατέρα. καὶ ὡς κατηγορηθεὶς ὑπὸ Νικολάου τοῦ Δαμασκηνοῦ καὶ καταγνωσθεὶς θάνατον ὑπὸ τοῦ πατρὸς καὶ ὑπὸ Κυντιλλίου Οὐάρου τοῦ τότε πεπιστευμένου τὴν Συρίαν ἐδέθη μέχρι τῆς ἐσομένης διαγνώσεως ὑπὸ Καίσαρος.\n\nπρεσβεία πεμφθεῖσα ὑπὸ Ἡρώδου πρὸς Καίσαρα περὶ Ἀντιπάτρου. καὶ ὡς Καῖσαρ ἀκούσας τὰς κατηγορίας κατέγνω αὐτοῦ θάνατον.\n\nπερὶ τῆς Ἡρώδου νόσου καὶ στάσεως τῶν Ἰουδαίων δι' αὐτήν, καὶ κόλασις τῶν στασιαστῶν.\n\nὡς δόξαντος Ἀντιπάτρου Ἡρώδην τετελευτηκέναι Ἀντίπατρος διαλεχθείη τῷ σωματοφύλακι περὶ ἀφέσεως, καὶ διὰ ταῦτα Ἀντιπάτρου ἀναίρεσις.\n\nἩρώδου τελευτὴ καὶ διαθήκη τοῦ αὐτοῦ πρὸς Καίσαρα καὶ μερισμὸς πρὸς τοὺς τρεῖς υἱοὺς αὐτοῦ. καὶ ὡς Ἀρχέλαον βασιλέα ποιεῖ τῆς Ἰουδαίας.\n\nἐπιστολὴ Ἡρώδου πρὸς τὸν στρατὸν καὶ ἑκάστῳ αὐτῶν δωρεὰ καὶ παράκλησις πίστεως πρὸς τὸν υἱὸν αὐτοῦ Ἀρχέλαον.\n\nταφὴ Ἡρώδου ἐν Ἡρωδίῳ τῷ φρουρίῳ. καὶ ὡς ὁ λαὸς ἐστασίασεν πρὸς τὸν υἱὸν αὐτοῦ Ἀρχέλαον ἐν τῇ ἑορτῇ.\n\nὡς Ἀρχέλαος τρισχιλίους αὐτῶν ἀνεῖλεν, αὐτὸς δὲ ἔπλευσε πρὸς Καίσαρα σὺν τῷ ἀδελφῷ αὐτοῦ Ἡρώδῃ εἰς Ῥώμην πιστεύσας τὴν βασιλείαν αὐτοῦ τῷ ἀδελφῷ Φιλίππῳ.\n\nὡς Σαβῖνος ὁ ἐν τῇ Συρίᾳ Καίσαρος ἐπίτροπος ἀνέβη εἰς Ἱεροσόλυμα βίᾳ αἰτῶν τὰ Ἡρώδου χρήματα καὶ φρούρια παρὰ τῶν Ἀρχελάου ἐπιμελητῶν.\n\nὡς ἔπεισαν οἱ τοῦ Ἀρχελάου ἐπιμεληταὶ τὸν λαὸν χωρεῖν ἐπὶ ὅπλα καὶ πολιορκῆσαι τὸν Σαβῖνον καὶ τὸν στρατὸν ἐν τῇ Ἀντωνίᾳ. καὶ ὡς ταῦτα ἀκούσας ὁ Οὔαρος μετὰ μεγάλης δυνάμεως ἀνέβη εἰς Ἱεροσόλυμα καὶ ῥυσάμενος τὸν Σαβῖνον ἐκ τῆς πολιορκίας τοὺς αἰτίους τῆς στάσεως ἐκόλασεν καὶ καλῶς διαθεὶς τὰ ἐν τῇ Ἰουδαίᾳ ἔγραψε Καίσαρι δηλῶν αὐτῷ τὰ πραχθέντα.\n\nὡς Καῖσαρ τὰς Ἡρώδου διαθήκας βεβαίας ἐποίησεν φυλάξας τοῖς υἱοῖς αὐτοῦ τὴν διαδοχήν. καὶ ὡς κατηγορεῖται Ἀρχέλαος ὑπὸ τῶν συγγενῶν αὐτοῦ ἐπὶ Καίσαρος καὶ νικήσας ἔλαβεν τὴν βασιλείαν, καὶ βασιλεύσας μοχθηρῶς δεκαετίαν πάλιν κατηγορηθεὶς ἐξωρίσθη εἰς Βίενναν, τὴν δὲ βασιλείαν αὐτοῦ μετέθηκεν Καῖσαρ εἰς ἐπαρχίαν.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ιδ."},"chapters":{"1":[{"number":1,"text":"Ἀντιπάτρῳ δὲ ἀραμένῳ τοὺς ἀδελφοὺς ἀσεβείᾳ τε τῇ ὑστάτῃ καὶ ἀλαστορίᾳ τῇ ἐπʼ αὐτοῖς τὸν πατέρα περιβεβληκότι οὔτι κατὰ γνώμας ἡ ἐλπὶς τοῦ αὖθις βίου ἦν· ἀπαλλαγεὶς γὰρ φόβου τοῦ ἐπὶ τῇ ἀρχῇ διὰ τὸ τῶν ἀδελφῶν μὴ ἐπικοινωνῆσον, ἐργωδέστερον καὶ ἄπορον αὐτῷ εὕρισκεν τὸ τῆς βασιλείας περιγενέσθαι· τοσόνδʼ ἐφύη τῷ ἔθνει μῖσος πρὸς αὐτόν."},{"number":2,"text":"ὄντος δὲ αὐτῷ καὶ τοῦδε χαλεποῦ πλειόνως παρελύπει τὸ στρατιωτικὸν ἀλλοτρίως ἔχον τῇ γνώμῃ πρὸς αὐτόν, εἰς οὓς τὰ πάντα ἦν τοῖς βασιλεῦσιν ἀνακείμενα τοῦ οἰκείου ἀσφαλοῦς, ὁπότε τύχοι τὸ ἔθνος νεωτέρων ὀριγνώμενον πραγμάτων· τοσόνδε κίνδυνον ἐμνήστευσεν αὐτῷ ὁ ὄλεθρος τῶν ἀδελφῶν."},{"number":3,"text":"οὐ μὴν ἀλλὰ καὶ συνῆρχέν γε τῷ πατρὶ οὐδὲν ἄλλο ἢ ὡς βασιλεὺς ὢν καὶ ἐπιστεύετο παρʼ αὐτῷ μειζόνως, ἐξ ὧν ἀπολωλέναι καλῶς εἶχεν εὐνοίας βεβαιώματα εὑρημένος, ὡς ἐπʼ ἀσφαλείᾳ σωτηρίας τῆς Ἡρώδου τοὺς ἀδελφοὺς ἐνδεδειχώς, ἀλλʼ οὐκ ἔχθρᾳ τῇ πρὸς ἐκείνους καὶ πρὸ αὐτῶν πρὸς τὸν πατέρα τοιαίδε αὐτὸν περιεσπένδον ἀραί."},{"number":4,"text":"ἅπερ δὴ πάντα μηχαναὶ τῆς ἐπὶ τὸν Ἡρώδην ὁδοῦ ἵσταντο Ἀντιπάτρῳ, ἐρημοῦντι αὐτὸν μὲν κατηγόρων ἐφʼ οἷς πράττειν διενοεῖτο, Ἡρώδην δὲ καταφυγῆς οἳ βοηθοῖεν αὐτῷ τοῦ Ἀντιπάτρου φανερῶς πολεμίου καταστάντος·"},{"number":5,"text":"ὥστε μίσει μὲν τῷ πρὸς τὸν πατέρα ἔπρασσεν τὴν ἐπιβουλὴν τῶν ἀδελφῶν, τὸ δὲ ἥπτετο μειζόνως τοῦ ἐγχειρῶν μὴ ἀφίεσθαι τῆς πράξεως· ἀποθνήσκοντος μὲν γὰρ Ἡρώδου, βεβαίως αὐτῷ περιγενομένης τῆς ἀρχῆς, ἐξικνουμένου δὲ εἰς τὸ πλέον ἔτι ζῆν, κινδύνων ἀντιπεριστάντων ἐξαγγέλτου γενομένης τῆς πράξεως, ἧς συνθέτης γεγονὼς πολέμιον ἠνάγκαζε τὸν πατέρα καταστῆναι."},{"number":6,"text":"καὶ διὰ τοῦ χαρίζεσθαι πολυτελὴς ἦν τοὺς περὶ τὸν πατέρα, κέρδεσι μεγάλοις ἐκπλήσσων τὸ τῶν ἀνθρώπων μῖσος πρὸς αὐτὸν καὶ μάλιστα τοὺς ἐπὶ Ῥώμης φίλους πομπαῖς μεγάλων δωρεῶν εὔνους καθιστάμενος, πρὸ πάντων δὲ Σατορνῖνον τὸν τῆς Συρίας ἐπιμελητήν."},{"number":7,"text":"ὑπάξεσθαί τε ἦν ἐλπὶς αὐτῷ καὶ τὸν Σατορνίνου ἀδελφὸν μεγέθει δώρων, ἃ ἐδίδου, καὶ τὴν ἀδελφὴν τοῦ βασιλέως ἀνδρὶ πρώτῳ τῶν περὶ τὸν Ἡρώδην συνοικοῦσαν τῷ αὐτῷ τρόπῳ χρώμενος. ψευσάμενός τε φιλίαν πρὸς τοὺς ὁμιλοῦντας δεινότατός τις ἦν πεπιστεῦσθαι καὶ μῖσος ἀράμενος ἐφʼ οὕστινας ἐπικρύψασθαι συνετώτατος."},{"number":8,"text":"οὐ μὴν ἠπάτα γε τὴν τηθίδα προκατανενοηκυῖαν ἐκ πλείονος αὐτὸν καὶ μηκέθʼ οἷαν οὖσαν παραλογισθῆναι καὶ διὰ τὸ ἤδη παρασκευῇ τῇ πάσῃ ἀντιτετάχθαι αὐτοῦ πρὸς τὸ κακότροπον."},{"number":9,"text":"καίτοι θυγατρὶ αὐτῆς συνῴκει θεῖος πρὸς μητρὸς Ἀντιπάτρου προνοίᾳ τῇ ἐκείνου καὶ διαπράξει παραλαβὼν τὴν κόρην πρότερον Ἀριστοβούλῳ γεγαμημένην· τὴν δὲ ἑτέραν ὁ ἐκ τοῦ ἀνδρὸς αὐτῆς Καλλέα παῖς γυναῖκα εἶχεν. ἀλλʼ οὐδὲν ἐπὶ τῷ μὴ κατανοεῖσθαι πονηρὸν ὄντα ἦν ἡ ἐπιγαμία τεῖχος, ὥσπερ οὐδʼ ἡ πρότερον συγγένεια πρὸς τὸ οὐ μεμισῆσθαι."},{"number":10,"text":"τὴν δὲ Σαλώμην Ἡρώδης ἐσπουδακυῖαν Συλλαίῳ τῷ Ἄραβι γαμηθῆναι κατʼ ἐρωτικὴν ἐπιθυμίαν βιάζεται τῷ Ἀλεξᾷ συνοικεῖν συμπρασσούσης αὐτῷ Ἰουλίας καὶ πειθούσης τὴν Σαλώμην μὴ ἀνήνασθαι τὸν γάμον, μὴ καὶ ἔχθρα καθίσταιτο αὐτοῖς προύπτως ὀμωμοκότος Ἡρώδου μὴ ἂν εὐνοήσειν Σαλώμῃ μὴ ὑποδεξαμένῃ τὸν Ἀλεξᾶ γάμον. καὶ ἐπείθετο Καίσαρός τε οὔσῃ γυναικὶ τῇ Ἰουλίᾳ καὶ ἄλλως συμβουλευούσῃ πάνυ συμφέροντα."},{"number":11,"text":"ἐν τούτῳ δὲ καὶ τὴν Ἀρχελάου θυγατέρα τοῦ βασιλέως Ἡρώδης ὡς τὸν αὐτῆς πατέρα ἐξέπεμψεν Ἀλεξάνδρῳ συνῳκηκυῖαν ἐκ τῶν αὐτοῦ τὴν προῖκα ἀποδούς, ὥστε ἀμφισβήτημα αὐτοῖς μηδὲν εἶναι."},{"number":12,"text":"Ἀνέτρεφεν δὲ αὐτὸς τῶν παίδων τὰ τέκνα πάνυ ἐπιμελῶς· ἦσαν γὰρ τῷ μὲν Ἀλεξάνδρῳ ἐκ Γλαφύρας ἄρσενες δύο, Ἀριστοβούλῳ δὲ ἐκ Βερενίκης τῆς Σαλώμης θυγατρὸς ἄρσενές τε τρεῖς καὶ θήλειαι δύο."},{"number":13,"text":"καί ποτε παρόντων αὐτῷ τῶν φίλων παραστησάμενος τὰ παιδάρια καὶ τῶν υἱέων ἀνακλαύσας τὴν τύχην ηὔχετο μηδὲν τοιόνδε παισὶν τοῖς ἐκείνων συνελθεῖν, αὐξηθέντας δὲ ἀρετῇ καὶ συμφορᾷ τοῦ δικαίου τὰς τροφὰς ἀμείψασθαι, ἃς ποιοῖτο."},{"number":14,"text":"ἐγγεγύητό τε εἰς γάμον, ὁπότε ἀφικοίατο εἰς ὥραν τὴν ἐπʼ αὐτῷ, τῷ μὲν πρεσβυτέρῳ τῶν Ἀλεξάνδρου παίδων Φερώρου θυγατέρα, τῷ δὲ Ἀριστοβούλου τὴν Ἀντιπάτρου, καὶ θυγατέρα τὴν Ἀριστοβούλου ἐπωνόμαζε παιδὶ τῷ Ἀντιπάτρου, τὴν δὲ ἑτέραν τῶν Ἀριστοβούλου θυγατέρων Ἡρώδῃ παιδὶ τῷ αὑτοῦ· γίνεται δὲ τῷ βασιλεῖ οὗτος ἐκ τῆς τοῦ ἀρχιερέως θυγατρός· πάτριον γὰρ πλείοσιν ἐν ταὐτῷ ἡμῖν συνοικεῖν."},{"number":15,"text":"ἔπρασσε δὲ τὰς μνηστείας τῶν παίδων ὁ βασιλεὺς ἐλέῳ τῶν ὀρφανῶν εἰς εὔνοιαν αὐτῶν διὰ τὴν ἐπιγαμίαν τὸν Ἀντίπατρον προκαλούμενος."},{"number":16,"text":"Ἀντίπατρος δὲ γνώμῃ τῇ πρὸς τοὺς ἀδελφοὺς πολιτεύειν οὐκ ἐνέλιπεν καὶ πρὸς τοὺς παῖδας αὐτοῖς γεγονότας, ἥ τε τοῦ πατρὸς σπουδὴ περὶ αὐτοὺς ἠρέθιζεν αὐτὸν μείζονας ἔσεσθαι τῶν ἀδελφῶν προσδεχόμενον, καὶ μάλιστα ὁπότε ἀνδρωθεῖεν, Ἀρχελάου προσληψομένου τοῖς θυγατριδοῖς βασιλέως ἀνδρὸς καὶ Φερώρου τῷ ληψομένῳ τὴν θυγατέρα· τετράρχης δὲ καὶ οὗτος ἦν."},{"number":17,"text":"ἐπήγειρε δʼ αὐτὸν καὶ τὸ πᾶν πλῆθος ἐλέῳ μὲν τὰ πρὸς τοὺς ὀρφανοὺς χρώμενον, μίσει δὲ πρὸς αὐτὸν τὰ πάντα ἐξαγαγεῖν οὐκ ἀπηλλαγμένον κακοτροπίᾳ τῇ ἐπὶ τοῖς ἀδελφοῖς. ἐμηχανᾶτο οὖν διάλυσιν τῶν τῷ πατρὶ ἐγνωσμένων, ἐν δεινῷ τιθέμενος προσλήψει τοσῆσδε αὐτοὺς ὁμιλῆσαι δυνάμεως."},{"number":18,"text":"καὶ μετέπιπτεν Ἡρώδης εἴκων δεήσει τῇ Ἀντιπάτρου, ὥστε αὐτὸν μὲν τὴν Ἀριστοβούλου θυγατέρα γαμεῖν καὶ τὴν Φερώρου τὸν υἱὸν αὐτοῦ. καὶ τὰ μὲν τῶν ὁμολογιῶν τοῦ γάμου τοῦτον κινεῖται τὸν τρόπον ἄκοντος τοῦ βασιλέως."},{"number":19,"text":"Ἡρώδῃ δὲ τῷ βασιλεῖ κατὰ τοῦτον τὸν χρόνον συνῴκουν ἐννέα γυναῖκες, ἥ τε Ἀντιπάτρου μήτηρ καὶ ἡ θυγάτηρ τοῦ ἀρχιερέως, ἐξ ἧς δὴ καὶ ὁμώνυμος αὐτῷ παῖς γεγόνει· ἦν δὲ καὶ ἀδελφοῦ παῖς αὐτῷ μία γεγαμημένη καὶ ἀνεψιὰ σὺν αὐτῇ. καὶ ταῖσδε μὲν τέκνον οὐδὲν ἐφύη."},{"number":20,"text":"ἦν δʼ ἐν ταῖς γυναιξὶν κἀκ τοῦ Σαμαρέων ἔθνους μία καὶ παῖδες αὐτῆς Ἀντίπας καὶ Ἀρχέλαος καὶ θυγάτηρ Ὀλυμπιάς. καὶ ταύτην μὲν ὕστερον Ἰώσηπος γαμεῖ βασιλέως ἀδελφιδοῦς ὤν, Ἀρχέλαος δὲ καὶ Ἀντίπας ἐπὶ Ῥώμης παρά τινι ἰδίῳ τροφὰς εἶχον."},{"number":21,"text":"Κλεοπάτρα δὲ Ἱεροσολυμῖτις γεγάμητο αὐτῷ καὶ παῖδες ἐξ αὐτῆς Ἡρώδης τε ἐγεγόνεισαν καὶ Φίλιππος, ὃς καὶ αὐτὸς ἐν Ῥώμῃ τροφὰς εἶχεν. καὶ Παλλὰς δὲ ἐν ταῖς γαμεταῖς Φασάηλον πεποιημένη παῖδα αὐτῷ, πρός γε μὴν ταύταις Φαῖδρα καὶ Ἐλπίς, ἐξ ὧν θυγατέρες δύο ἦσαν Ῥωξάνη καὶ Σαλώμη."},{"number":22,"text":"τὰς δὲ πρεσβυτέρας αὐτοῦ θυγατέρας ὁμομητρίας τῶν περὶ Ἀλέξανδρον, ὧν περιεώρα Φερώρας τὸν γάμον, συνῴκουν ἡ μὲν Ἀντιπάτρῳ τοῦ βασιλέως ἀδελφῆς παιδὶ ὄντι, Φασαήλῳ δὲ ἡ ἑτέρα· καὶ οὗτος Ἡρώδου ἀδελφοῦ παῖς ἐγεγόνει. καὶ τοῦτο μὲν Ἡρώδου τὸ γένος ἦν."}],"2":[{"number":23,"text":"Τότε δὲ βουλόμενος πρὸς Τραχωνίτας ἀσφαλὴς εἶναι, κώμην πόλεως μέγεθος οὐκ ἀποδέουσαν ἔγνω Ἰουδαίων κτίσαι ἐν μέσῳ, δυσέμβολόν τε ποιεῖν τὴν αὐτοῦ καὶ τοῖς πολεμίοις ἐξ ἐγγίονος ὁρμώμενος ἐκ τοῦ ὀξέος κακουργεῖν."},{"number":24,"text":"καὶ ἐπιστάμενος ἄνδρα Ἰουδαῖον ἐκ τῆς Βαβυλωνίας σὺν πεντακοσίοις ἱπποτοξόταις πᾶσι καὶ συγγενῶν πλήθει εἰς ἑκατὸν ἀνδρῶν τὸν Εὐφράτην διαβεβηκότα κατὰ τύχας ἐν Ἀντιοχείᾳ τῇ ἐπὶ Δάφνῃ τῆς Συρίας διαιτᾶσθαι Σατορνίνου τοῦ τότε στρατηγοῦντος εἰς ἐνοίκησιν αὐτῷ δεδωκότος χωρίον,"},{"number":25,"text":"Οὐλαθὰ ὄνομα αὐτῷ, μετεπέμπετο τοῦτον σὺν τῷ πλήθει τῶν ἑπομένων, παρέξειν ὑπισχνούμενος γῆν ἐν τοπαρχίᾳ τῇ λεγομένῃ Βαταναίᾳ, ὡρίζετο δὲ αὕτη τῇ Τραχωνίτιδι, βουλόμενος πρόβλημα τὴν κατοίκησιν αὐτοῦ κτᾶσθαι, ἀτελῆ τε τὴν χώραν ἐπηγγέλλετο καὶ αὐτοὺς εἰσφορῶν ἀπηλλαγμένους ἁπασῶν, αἳ εἰωθυῖαι ἐγκατοικεῖν τὴν γῆν ἄπρακτον παρασχόμενος."},{"number":26,"text":"Τούτοις πεισθεὶς ὁ Βαβυλώνιος ἀφικνεῖται καὶ λαβὼν τὴν γῆν φρούρια ᾠκοδομήσατο καὶ κώμην, Βαρθύραν ὄνομα αὐτῇ θέμενος. πρόβλημά τε ἦν οὗτος ὁ ἀνὴρ καὶ τοῖς ἐγχωρίοις τὰ πρὸς τοὺς Τραχωνίτας καὶ Ἰουδαίων τοῖς ἐκ Βαβυλῶνος ἀφικνουμένοις κατὰ θυσίαν ἐπὶ Ἱεροσολύμων τοῦ μὴ λῃστείαις ὑπὸ τῶν Τραχωνιτῶν κακουργεῖσθαι, πολλοί τε ὡς αὐτὸν ἀφίκοντο καὶ ἁπανταχόθεν, οἷς τὰ Ἰουδαίων θεραπεύεται πάτρια."},{"number":27,"text":"καὶ ἐγένετο ἡ χώρα σφόδρα πολυάνθρωπος ἀδείᾳ τοῦ ἐπὶ πᾶσιν ἀτελοῦς, ἃ παρέμεινεν αὐτοῖς Ἡρώδου ζῶντος. Φίλιππος δὲ υἱὸς ἐκείνου παραλαβὼν τὴν ἀρχὴν ὀλίγα τε καὶ ἐπʼ ὀλίγοις αὐτοὺς ἐπράξατο,"},{"number":28,"text":"Ἀγρίππας μέντοι γε ὁ μέγας καὶ ὁ παῖς αὐτοῦ καὶ ὁμώνυμος καὶ πάνυ ἐξετρύχωσαν αὐτούς, οὐ μέντοι τὰ τῆς ἐλευθερίας κινεῖν ἠθέλησαν. παρʼ ὧν Ῥωμαῖοι δεξάμενοι τὴν ἀρχὴν τοῦ μὲν ἐλευθέρου καὶ αὐτοὶ τηροῦσιν τὴν ἀξίωσιν, ἐπιβολαῖς δὲ τῶν φόρων εἰς τὸ πάμπαν ἐπίεσαν αὐτούς. καὶ τάδε μὲν ᾗ καιρὸς ἀκριβώσομαι προϊόντος τοῦ λόγου."},{"number":29,"text":"Τελευτᾷ δὲ Ζάμαρις ὁ Βαβυλώνιος, ὃς ἐπὶ κτήσει τῆσδε τῆς χώρας Ἡρώδῃ προσποιεῖται, ζήσας τε μετὰ ἀρετῆς καὶ παῖδας λειπόμενος ἀγαθούς, Ἰάκειμον μέν, ὃς ἀνδρείᾳ γενόμενος ἐπιφανὴς ἱππεύειν συνεκρότησε τὸ ὑφʼ αὑτῷ Βαβυλώνιον, καὶ ἴλη τῶνδε τῶν ἀνδρῶν ἐδορυφόρει τούσδε τοὺς βασιλέας."},{"number":30,"text":"καὶ Ἰάκειμος δὲ ἐν γήρᾳ τελευτῶν Φίλιππον τὸν υἱὸν κατέλιπεν ἄνδρα κατὰ χεῖρας ἀγαθὸν καὶ τὰ ἄλλα ἀρετῇ χρῆσθαι παρʼ ὁντινοῦν ἀξιόλογον. διόπερ φιλία"},{"number":31,"text":"τε πιστὴ καὶ εὔνοια ἀσφαλὴς αὐτῷ πρὸς Ἀγρίππαν γίνεται τὸν βασιλέα, στρατιάν τε ὁπόσην ὁ βασιλεὺς ἔτρεφεν οὗτος ἀσκῶν διετέλει καὶ ὅπη ἐξοδεύειν δεήσειεν ἡγούμενος."},{"number":32,"text":"Ἡρώδου δʼ ἐν οἷς εἶπον ὄντος ἀφεώρα τὰ πάντα πράγματα εἰς Ἀντίπατρον, κἀφʼ οἷς ὠφελήσειεν κυροῦν οὐκ ἀπήλλακτο ἐξουσίας ἐπικεχωρηκότος τε τοῦ πατρὸς ἐλπίδι εὐνοίας καὶ πίστεως, καὶ περαιτέρω κτᾶσθαι τὴν ἐπʼ αὐτοῖς ἐξουσίαν τολμηρὸς καθιστάμενος διὰ τὸ ἄδηλος τῷ πατρὶ εἶναι κακουργῶν κἀφʼ οἷς εἴπειεν πιστότατος."},{"number":33,"text":"ἦν τε πᾶσιν φοβερὸς οὐχ οὕτως ἰσχύι τῆς ἐξουσίας, ὡς τοῦ κακοτρόπου τῷ προμηθεῖ· μάλιστα δʼ αὐτὸν Φερώρας ἐθεράπευεν καὶ ἀντεθεραπεύετο δεινῶς, πάνυ τοῦ Ἀντιπάτρου περιστοιχίσαντος αὐτὸν καὶ τὴν γυναικωνῖτιν συνισταμένου τὰ πρὸς αὐτόν·"},{"number":34,"text":"ἐδεδούλωτο γὰρ Φερώρας γαμετῇ τε καὶ μητρὶ ταύτης καὶ ἀδελφῇ καὶ ταῦτα μισῶν τὰς ἀνθρώπους ὕβρει θυγατέρων αὐτοῦ παρθένων· ἀλλʼ ὅμως ἠνείχετο, πράσσειν τε οὐδὲν ἦν δίχα τῶν γυναικῶν ἐκπεριωδευκυιῶν τὸν ἄνθρωπον καὶ ἀλλήλαις εὐνοίᾳ συμπράσσειν τὰ πάντα μὴ ἀπηλλαγμένων,"},{"number":35,"text":"ὥστε παντοίως ὁ Ἀντίπατρος ὑπῆκτο αὐτὰς καὶ διʼ αὐτοῦ καὶ διὰ τῆς μητρός· ταὐτὸν γὰρ αἵδε αἱ τέσσαρες γυναῖκες ἔλεγον. καὶ Φερώρᾳ δὲ πρὸς Ἀντίπατρον ἐπʼ οὐδαμινοῖς τισιν αἱ γνῶμαι διήλλασσον."},{"number":36,"text":"ἀντίσπασμα δʼ ἦν αὐτοῖς βασιλέως ἡ ἀδελφὴ περισκοποῦσά τε ἐκ πλείονος τὰ πάντα καὶ τὴν εὔνοιαν αὐτῶν ἐπὶ κακοῖς τοῖς Ἡρώδου πρασσομένην εἰδυῖά τε καὶ μηνύειν οὐκ ἀποτετραμμένη."},{"number":37,"text":"καὶ γνόντες ἐν ἀπεχθείᾳ βασιλεῖ τὴν εὔνοιαν αὐτῶν οὖσαν ἐπινοοῦσιν ὥστε φανερὰν μὲν μὴ εἶναι τὴν πρὸς ἀλλήλους αὐτῶν σύνοδον, μίσους δὲ καὶ λοιδοριῶν ᾗ καιρὸς προσποίησιν, καὶ μάλιστα Ἡρώδου παρατυγχάνοντος ἢ οἳ πρὸς αὐτὸν ἀπαγγέλλειν ἔμελλον, κρυπτῶς δὲ τὰ τῆς εὐνοίας ὀχυρώτερα καθίστασθαι."},{"number":38,"text":"καὶ ἔπρασσον οὕτως. ἐλάνθανεν δὲ τὴν Σαλώμην οὔτε πρῶτον ἡ διάνοια αὐτῶν ἐπὶ τοιοῖσδε ὡρμημένων οὔτε ἐπειδὴ χρῆσθαι οὐκ ἀπήλλακτο αὐτή· πάντα δὲ ἀνίχνευέν τε καὶ πρὸς τὸν ἀδελφὸν μειζόνως ἐκδεινοῦσα ἀπεσήμαινεν συνόδους τε κρυπτὰς καὶ πότους βουλευτήριά τε ἀφανῶς κατεσκευασμένα, ὧν μὴ ἐπʼ ὀλέθρῳ τῷ ἐκείνου συντιθεμένων κἂν πεφανερῶσθαι μὴ κεκωλῦσθαι."},{"number":39,"text":"νῦν δὲ τοὺς μὲν ἐκ τοῦ προὔπτου διαφόρους καὶ τὰ πάντα ἐπὶ βλάβῃ τῇ ἀλλήλων λέγοντας, εἰς δὲ τὸ ἀφανὲς τοῖς πολλοῖς τὴν εὔνοιαν ἀνατιθεμένους καὶ ὁπότε ἀλλήλοις συμμονωθεῖεν φίλια πράσσειν μὴ ἀπηλλαγμένους, ὁμολογεῖν πολεμεῖν πρὸς οὓς λανθάνειν χρώμενοι εὐνοίᾳ τῇ ἀλλήλων ἐσπουδάκοιεν."},{"number":40,"text":"καὶ ἡ μὲν ταῦτʼ ἀνίχνευέν τε καὶ ἀκριβῶν τυγχάνουσα τῷ ἀδελφῷ ἀνέφερεν συνιέντι μὲν ἤδη τὰ πολλὰ καὶ διʼ ἑαυτοῦ, εἰς δὲ τὸ θαρσεῖν οὐ διακενῆς ὑπονοῶν καθισταμένῳ διαβολαῖς τῆς ἀδελφῆς."},{"number":41,"text":"καὶ ἦν γὰρ μόριόν τι Ἰουδαϊκὸν ἀνθρώπων ἐπʼ ἐξακριβώσει μέγα φρονοῦν τοῦ πατρίου καὶ νόμων οἷς χαίρει τὸ θεῖον προσποιουμένων, οἷς ὑπῆκτο ἡ γυναικωνῖτις, Φαρισαῖοι καλοῦνται, βασιλεῖ δυναμένῳ μάλιστα πράσσειν προμηθεῖς κἀκ τοῦ προὔπτου εἰς τὸ πολεμεῖν τε καὶ βλάπτειν ἐπηρμένοι."},{"number":42,"text":"παντὸς γοῦν τοῦ Ἰουδαϊκοῦ βεβαιώσαντος διʼ ὅρκων ἦ μὴν εὐνοήσειν Καίσαρι καὶ τοῖς βασιλέως πράγμασιν, οἵδε οἱ ἄνδρες οὐκ ὤμοσαν ὄντες ὑπὲρ ἑξακισχίλιοι, καὶ αὐτοὺς βασιλέως ζημιώσαντος χρήμασιν ἡ Φερώρου γυνὴ τὴν ζημίαν ὑπὲρ αὐτῶν εἰσφέρει."},{"number":43,"text":"οἱ δὲ ἀμειβόμενοι τὴν εὔνοιαν αὐτῆς, πρόγνωσιν δὲ ἐπεπίστευντο ἐπιφοιτήσει τοῦ θεοῦ, προύλεγον, ὡς Ἡρώδῃ μὲν καταπαύσεως ἀρχῆς ὑπὸ θεοῦ ἐψηφισμένης αὐτῷ τε καὶ γένει τῷ ἀπʼ αὐτοῦ, τῆς δὲ βασιλείας εἴς τε ἐκείνην περιηξούσης καὶ Φερώραν παῖδάς τε οἳ εἶεν αὐτοῖς."},{"number":44,"text":"καὶ τάδε, οὐ γὰρ ἐλάνθανεν τὴν Σαλώμην, ἐξάγγελτα βασιλεῖ ἦν, καὶ ὅτι τῶν περὶ τὴν αὐλὴν διαφθείροιέν τινας. καὶ βασιλεὺς τῶν τε Φαρισαίων τοὺς αἰτιωτάτους ἀναιρεῖ καὶ Βαγώαν τὸν εὐνοῦχον Κᾶρόν τέ τινα τῶν τότε προύχοντα ἀρετῇ τοῦ εὐπρεποῦς καὶ παιδικὰ ὄντα αὐτοῦ. κτείνει δὲ καὶ πᾶν ὅ τι τοῦ οἰκείου συνειστήκει οἷς ὁ Φαρισαῖος ἔλεγεν."},{"number":45,"text":"ἦρτο δὲ ὁ Βαγώας ὑπʼ αὐτῶν ὡς πατήρ τε καὶ εὐεργέτης ὀνομασθησόμενος τοῦ ἐπικατασταθησομένου προρρήσει βασιλέως· κατὰ χεῖρα γὰρ ἐκείνῳ τὰ πάντʼ εἶναι, παρέξοντος αὐτῷ γάμου τε ἰσχὺν καὶ παιδώσεως τέκνων γνησίων."}],"3":[{"number":46,"text":"Ἡρώδης δὲ κολάσας τῶν Φαρισαίων τοὺς ἐπὶ τοῖσδε ἐληλεγμένους συνέδριόν τε ποιεῖται τῶν φίλων καὶ κατηγορίαν τῆς Φερώρου γυναικός, τήν τε ὕβριν τῶν παρθένων τῇ τόλμῃ τῆς γυναικὸς ἀνατιθεὶς καὶ ἔγκλημα ταύτην ἀτιμίαν αὐτῷ ποιούμενος,"},{"number":47,"text":"ὥστε ἀγωνοθετῶν στάσιν αὐτῷ πρὸς τὸν ἀδελφὸν πόλεμον ἐκ φύσεως αὐτοῖς καὶ λόγῳ καὶ διʼ ἔργων ὁπόσα δύναιτο, τήν τε διάλυσιν τῆς ζημίας τῆς ὑπʼ αὐτοῦ ἐπιβληθείσης τέλεσι διαφευχθείσης τοῖς ἐκείνης, τῶν τε νῦν πεπραγμένων οὐδὲν ὅ τι οὐ μετʼ αὐτῆς."},{"number":48,"text":"ἀνθʼ ὧν, ὦ Φερώρα, καλῶς εἶχεν οὐ δεήσει οὐδὲ γνωμῶν εἰσηγήσεως τῶν ἐμῶν αὐτοκέλευστον ἀποπέμπεσθαι γυναῖκα ταύτην ὡς πολέμου τοῦ πρός μέ σοι αἰτίαν ἐσομένην· καὶ νῦν, εἴπερ ἀντιποιῇ συγγενείας τῆς ἐμῆς, ἀπείπασθαι τήνδε τὴν γαμετήν· μενεῖς γὰρ οὕτως ἀδελφός τε καὶ στέργειν οὐκ ἀπηλλαγμένος."},{"number":49,"text":"Φερώρας δὲ καίπερ λόγων ἀρετῇ περιωθούμενος οὔτε συγγενείας τῆς πρὸς τὸν ἀδελφὸν ἔλεγε κινήσειν δίκαιον οὐδὲν οὔτε τῶν πρὸς τὴν γαμετὴν εὐνοιῶν, αἱρεῖσθαί τε πρότερον θανεῖν ἢ ζῶν τολμᾶν ἀπεστερῆσθαι γυναικὸς αὐτῷ κεχαρισμένης."},{"number":50,"text":"Ἡρώδης δὲ Φερώρᾳ μὲν ὑπερεβάλλετο τὴν ἐπὶ τούτοις ὀργὴν καίπερ ἀνήδονον τιμωρίαν εἰσπεπραγμένος, Ἀντιπάτρῳ δὲ ἀπεῖπε καὶ μητρὶ τῇ ἐκείνου Φερώρᾳ τε μὴ ὁμιλεῖν καὶ τῶν γυναικῶν φυλάσσεσθαι τὸ εἰς ταὐτὸν συνεσόμενον."},{"number":51,"text":"οἱ δʼ ὡμολόγουν μέν, συνῄεσαν δὲ ᾗ καιρὸς καὶ συνεκώμαζον Φερώρας καὶ Ἀντίπατρος. ἐφοίτα δὲ λόγος ὁμιλεῖν καὶ Ἀντιπάτρῳ τὴν Φερώρου γυναῖκα συμπρασσούσης αὐτοῖς τὰ εἰς τὴν σύνοδον τῆς Ἀντιπάτρου μητρός."},{"number":52,"text":"Ὑφορώμενος δὲ τὸν πατέρα καὶ δεδιώς, μὴ εἰς πλεῖον προχωροίη τὰ τοῦ μίσους ἐπʼ αὐτῷ, γράφει πρὸς τοὺς ἐν Ῥώμῃ φίλους κελεύων ἐπιστέλλειν Ἡρώδῃ πέμπειν ᾗ τάχος Ἀντίπατρον ὡς Καίσαρα."},{"number":53,"text":"οὗ γενομένου ἔπεμπεν Ἡρώδης Ἀντίπατρον δῶρα συμπέμψας ἀξιολογώτατα καὶ διαθήκην, ἐν ᾗ μετʼ αὐτὸν Ἀντίπατρον ἀπεδείκνυε βασιλέα, ἢ φθάντος τελευτῆσαι Ἡρώδην τὸν ἐκ τῆς τοῦ ἀρχιερέως θυγατρὸς υἱὸν αὐτῷ γεγενημένον."},{"number":54,"text":"συνεξορμᾷ δʼ Ἀντιπάτρῳ καὶ Σύλλαιος ὁ Ἄραψ μηδὲν ὧν προσέταξε Καῖσαρ διαπεπραγμένος, καὶ Ἀντίπατρος αὐτοῦ κατηγορεῖ ἐπὶ Καίσαρος περὶ ὧν πρότερον Νικόλαος. κατηγορεῖτο δὲ καὶ ὑπὸ Ἀρέτα Σύλλαιος, ὡς πολλοὺς ἀπεκτονὼς τῶν ἐν Πέτρᾳ ἀξιολόγων παρὰ γνώμην τὴν αὐτοῦ καὶ μάλιστα Σόαιμον ἄνδρα τῇ ἐς πάντα ἀρετῇ τιμᾶσθαι δικαιότατον, ἀνῃρηκέναι δὲ καὶ Φάβατον Καίσαρος δοῦλον."},{"number":55,"text":"καὶ Σύλλαιος αἰτίαν εἶχεν ἐκ τοιῶνδε ἐγκλημάτων· Κόρινθος ἦν Ἡρώδου σωματοφύλαξ τοῦ βασιλέως μάλιστα πιστευόμενος ὑπʼ αὐτοῦ. τοῦτον πείθει Σύλλαιος ἐπὶ χρήμασι μεγάλοις Ἡρώδην ἀποκτεῖναι, καὶ ὑπέσχετο. μαθὼν οὖν Φάβατος Συλλαίου πρὸς αὐτὸν εἰρηκότος διηγεῖται πρὸς τὸν βασιλέα."},{"number":56,"text":"ὁ δὲ τόν τε Κόρινθον βασανίζει συλλαβὼν καὶ πάντα ἀνάπυστα ἦν αὐτῷ. συλλαμβάνει δὲ καὶ δευτέρους Ἄραβας καταγορεύσει τῇ Κορίνθου πειθόμενος τὸν μὲν φύλαρχον ὄντα τὸν δὲ Συλλαίου φίλον."},{"number":57,"text":"οἳ καὐτοί, βασανίζει γὰρ αὐτοὺς ὁ βασιλεύς, ὡμολόγουν ὅτι παρεῖεν ἐξοτρύνοντες μὴ μαλακίζεσθαι Κόρινθον καὶ εἴ που δεήσειεν καὶ συγχειρουργήσοντες αὐτῷ τὸν φόνον. καὶ Σατορνῖνος δηλώσεως αὐτῷ πάντων ὑπὸ Ἡρώδου γενομένης εἰς Ῥώμην ἐξέπεμψεν αὐτούς."},{"number":58,"text":"Φερώραν δὲ ἰσχυρῶς ἐμμένοντα εὐνοίᾳ τῆς γυναικὸς ἀναχωρεῖν εἰς τὴν αὑτοῦ Ἡρώδης κελεύει. ὁ δὲ ἀσμένως ἐπὶ τὴν τετραρχίαν ἀπῆρεν, πολλὰ ὀμόσας οὐ πρότερον ἥξειν ἢ πύθοιτο Ἡρώδην τετελευτηκότα, ὥστε καὶ νοσήσαντος τοῦ βασιλέως ἀξιωθεὶς ἥκειν ἐπί τινων πίστεσιν ἐντολῶν, εἰ μέλλοι τελευτᾶν, οὐχ ὑπήκουσεν ἐπὶ τιμῇ τοῦ ὅρκου."},{"number":59,"text":"οὐ μὴν Ἡρώδης γε μιμεῖται τὸ ἐπὶ τοιοῖσδε ἐκείνου γνώμην προαποφηνάμενον ἣν ἔχει, ἀλλʼ ἧκεν ὡς τὸν Φερώραν, ἐπειδὴ ὕστερον ἄρχεται νοσεῖν, καὶ μετακλήσεως αὐτῷ μὴ γενομένης, θανόντα δὲ περιστείλας ἐπὶ Ἱεροσολύμων ἀγόμενος ταφῆς ἠξίου καὶ πένθος μέγα ἐπʼ αὐτῷ προέθετο."},{"number":60,"text":"τοῦτο Ἀντιπάτρῳ καίτοι γε ἐπὶ Ῥώμης πεπλευκότι κακῶν ἐγένετο ἀρχὴ τῆς ἀδελφοκτονίας αὐτὸν τινυμένου θεοῦ. διηγήσομαι δὲ τὸν πάντα περὶ αὐτοῦ λόγον παράδειγμα τῷ ἀνθρωπείῳ γενησόμενον τοῦ ἀρετῇ πολιτεύσοντος ἐπὶ πᾶσιν."}],"4":[{"number":61,"text":"Ἐπειδὴ Φερώρας τελευτᾷ ταφνίται ἐγεγόνεισαν αὐτοῦ ἀπελεύθεροι δύο τῶν Φερώρᾳ τιμίων οὗτοι προσελθόντες Ἡρώδῃ ἠξίουν μὴ ἀνεκδίκητον καταλιπεῖν τοῦ ἀδελφοῦ τὸν νεκρόν, ἀλλὰ ζήτησιν ποιεῖσθαι τῆς ἀλόγου τε καὶ δυστυχοῦς μεταστάσεως."},{"number":62,"text":"τοῦ δʼ ἐπιστραφέντος τοῖς λόγοις, πιστὰ γὰρ ἐδόκει, δειπνῆσαι μὲν αὐτὸν ἔλεγον παρὰ τῇ γυναικὶ τῇ προτέρᾳ τῆς νόσου, φάρμακον δὲ προσκομισθὲν ἐν βρώματι μὴ πρότερον εἰωθότι ἐμφαγόντα ὑπὸ τούτου τελευτῆσαι· κομιστὸν μέντοι γενέσθαι τὸ φάρμακον ὑπὸ γυναικὸς ἐκ τῆς Ἀραβίας λόγῳ μὲν ἐπὶ προσποιήσεσιν ἐρώτων, φίλτρον γὰρ δὴ ὄνομα αὐτῷ εἶναι, τὸ δʼ ἀληθὲς ἐπὶ τῇ Φερώρου τελευτῇ."},{"number":63,"text":"φαρμακιστόταται δέ εἰσι γυναικῶν αἱ ἐκ τῆς Ἀραβίας· ᾗ δὲ ταῦτα ἐπεκάλουν καὶ τῆς Συλλαίου ἐρωμένης ἐν ταῖς μάλιστα ὡμολόγητο εἶναι φίλη, πείσουσαί τε αὐτὴν ἐπὶ πράσει τοῦ φαρμάκου εἰς τοὺς τόπους ἐληλύθεσαν ἥ τε μήτηρ τῆς τοῦ Φερώρου γυναικὸς καὶ ἡ ἀδελφὴ καὶ ἐπανῆκον αὐτὴν ἀγόμεναι τοῦ δείπνου πρότερον ἡμέρᾳ μιᾷ."},{"number":64,"text":"ὑπὸ τούτων ὁ βασιλεὺς τῶν λόγων παροξυνθεὶς δούλας τε ἐβασάνιζε τῶν γυναικῶν καί τινας καὶ ἐλευθέρας, καὶ ὄντος ἀφανοῦς τοῦ πράγματος διὰ τὸ μηδεμίαν ἐξειπεῖν τελευταία τις περιουσῶν αὐτῆς τῶν ἀλγηδόνων ἄλλο μὲν ἔφη οὐδέν, θεὸν δʼ ἐπικαλεῖσθαι τοιαῖσδε αἰκίαις δώσειν περιβαλεῖν τὴν Ἀντιπάτρου μητέρα κακῶν τῶν ἐπεχόντων αἰτίαν πᾶσιν γενομένην."},{"number":65,"text":"ταῦτα εἰς ἐπίστασιν Ἡρώδην ἄγει, καὶ τὰ πάντα βασάνοις τῶν γυναικῶν ἀνάπυστα ἦν, οἵ τε κῶμοι καὶ κρυπταὶ σύνοδοι καὶ δὴ καὶ λόγων πρὸς μόνον τὸν υἱὸν εἰρημένων ἐξοίσεις πρὸς τὰς Φερώρου γυναῖκας· ἦν δὲ ταλάντων ἑκατὸν δωρεὰς ἐπικρύπτεσθαι φράζειν πρὸς Φερώραν τῷ Ἀντιπάτρῳ κέλευσις ὑπὸ τοῦ πατρός·"},{"number":66,"text":"μῖσός τε πρὸς τὸν πατέρα καὶ ὀλοφυρμοὶ πρὸς τὴν μητέρα, ὡς ἐπὶ μήκιστον τοῦ πατρὸς βιοῦν ἐξηγμένου καὶ αὐτῷ μηδὲν ἐλάσσονος τοῦ γήρως ἐπικειμένου, ὡς μηδʼ ἂν ἐλθοῦσαν τὴν βασιλείαν ὁμοίως εὐφρᾶναί ποτʼ αὐτόν· παρατρέφεσθαί τε πολλοὺς ἐπὶ τῇ βασιλείᾳ καὶ ἀδελφοὺς καὶ ἀδελφῶν παῖδας οὐδαμῶς ἀδεῆ τὴν ἐλπίδα παρεχομένους τἀσφαλοῦς·"},{"number":67,"text":"καὶ γὰρ δὴ καὶ νῦν, εἴ τι πάσχειν, αὐτὸν ἀδελφῷ μᾶλλον ἢ παιδὶ τῷ αὐτοῦ κελεύειν τὴν ἀρχὴν δίδοσθαι. ὠμότητά τε πολλὴν κατηγόρει τοῦ βασιλέως καὶ τὰς σφαγὰς τῶν υἱέων, φόβῳ τε μὴ καὶ αὐτῶν ἅπτοιτο ἤδη τὸν μὲν ἐπὶ Ῥώμης ἄρασθαι τέχνην ἐπινοῆσαι, Φερώραν δὲ ἐπὶ τῆς αὐτοῦ τετραρχίας."},{"number":68,"text":"Ταῦτα συνῇδεν γὰρ τοῖς λόγοις τῆς ἀδελφῆς, καὶ πολὺ τοῦ μὴ ἀπιστίαν ἔτι ὑποπτεύεσθαι συνῆγεν αὐτοῖς, ὁ βασιλεὺς κρατυνάμενος ἐπὶ κακίᾳ τῇ Ἀντιπάτρου τὴν Δῶριν τὴν μητέρα αὐτοῦ πάντα τὸν περὶ αὐτὴν κόσμον ταλάντων πολλῶν ὄντα ἀφελόμενος ἔπειτα αὐτὴν ἀποπέμπεται καὶ ταῖς Φερώρου γυναιξὶν φιλίαν ἐσπείσατο."},{"number":69,"text":"μάλιστα δʼ ἐξώτρυνεν εἰς ὀργὴν κατὰ τοῦ παιδὸς τὸν βασιλέα Σαμαρείτης ἀνὴρ Ἀντίπατρος ἐπιτροπεύων τὸν υἱὸν τοῦ βασιλέως Ἀντίπατρον, ἄλλα τε αὐτοῦ ἐν ταῖς βασάνοις κατειπὼν καὶ ὅτι παρασκευασάμενος φάρμακον θανάσιμον δοίη Φερώρᾳ κελεύσας παρὰ τὴν ἀποδημίαν αὐτοῦ, ἵνʼ ὡς πλεῖστον ἀφεστήκοι τῶν ἐν τοιούτοις ὑποτοπασμῶν, τῷ πατρὶ δοῦναι."},{"number":70,"text":"καὶ κομίσαι μὲν Ἀντίφιλον ἐξ Αἰγύπτου τὸ φάρμακον ἕνα τῶν Ἀντιπάτρου φίλων, σταλῆναι δὲ ὡς Φερώραν διὰ Θευδίωνος μητρὸς Ἀντιπάτρου ἀδελφοῦ τοῦ βασιλέως παιδός, καὶ οὕτως ἐλθεῖν τὸ φάρμακον εἰς τὴν γυναῖκα τὴν Φερώρου δόντος φυλάσσειν τοῦ ἀνδρὸς αὐτῆς."},{"number":71,"text":"ἡ δὲ ὡμολόγει μὲν ἀνακρίναντος τοῦ βασιλέως, καὶ δραμοῦσα ὡς κομίσειεν ῥίπτει κατὰ τέγους ἑαυτήν, οὐ μὴν τελευτᾷ ἐπὶ πόδας τῆς πτώσεως γενομένης."},{"number":72,"text":"καὶ οὕτως ἐπεὶ ἀνεκτήσατο αὐτὴν ἄδειάν τε αὐτῇ ὑπισχνούμενος καὶ τοῖς οἰκείοις μηδὲν ἐπʼ ἀφανισμῷ τἀληθοῦς τρεπομένῃ, τρίψειν γε μὴν κακοῖς τοῖς ὑστάτοις ἀγνωμονεῖν προθεμένην, ὑπισχνεῖται καὶ ὤμοσεν ἦ μὴν ἐρεῖν τὰ πάντα ὃν ἐπράχθη τρόπον, λέγουσα μὲν, ὡς ἔφασαν οἱ πολλοὶ τῶν ἀνθρώπων ἀληθῆ τὰ πάντα."},{"number":73,"text":"κεκόμισται γὰρ ἐκ τῆς Αἰγύπτου τὸ φάρμακον ὑπʼ Ἀντιφίλου, ἀδελφὸς δʼ ἐκείνῳ ἰατρὸς ὢν ἐπόρισεν, καὶ Θευδίωνος ὡς ἡμᾶς κομίσαντος ἐφύλασσον αὐτὴ παρὰ Φερώρου λαβοῦσα ἐπὶ σὲ ἡτοιμασμένον ὑπὸ Ἀντιπάτρου."},{"number":74,"text":"ἐπεὶ οὖν ἐνόσει Φερώρας καὶ ἐθεράπευες αὐτὸν ἀφικόμενος, ὁρῶν σου τὴν εὔνοιαν, ᾗ περὶ αὐτὸν ἐχρῶ, ἐπεκλάσθη τε τῇ διανοίᾳ καὶ μετακαλέσας με, ὦ γύναι, φησίν, περιώδευσέ με Ἀντίπατρος ἐπὶ πατρὶ μὲν τῷ αὐτοῦ, ἀδελφῷ δὲ τῷ ʼμῷ, θανάσιμόν τε γνώμην συνθεὶς καὶ φάρμακον ᾧ διακονήσοιτο αὐτῇ πεπορισμένος."},{"number":75,"text":"νῦν οὖν, ἐπειδὴ ὅ τε ἀδελφὸς οὐδὲν ἀρετῇ πρότερον ᾗ ἐχρῆτο περὶ ἐμοῦ ὑφαιρῶν ὦπται ἐμέ τε ἐλπὶς οὐκ εἰς μακρὰν ἀπέσεσθαι τοῦ βίου, φέρε μὴ γνώμῃ ἀδελφοκτόνῳ ἀποτισοίμην προπάτορας τοὺς ἐμαυτοῦ, τὸ φάρμακον καίειν τε ἐμοῦ βλέποντος,"},{"number":76,"text":"κομίσασά τε οὐδὲν εἰς ἀναβολὰς πράσσειν τοῦ ἀνδρὸς τὰς ἐπιστολάς. καὶ τὸ μὲν πλεῖστον καύσασαν τοῦ φαρμάκου τυχεῖν, ὑπολιπέσθαι δὲ ὀλίγον, ἵνα εἰ Φερώρου μεταστάντος περιέποι κακῶς αὐτὴν ὁ βασιλεύς, μεθίσταιτο αὐτῷ διάδρασιν ποιουμένη τῶν ἀναγκῶν."},{"number":77,"text":"ταῦτα εἰποῦσα τό τε φάρμακον καὶ τὴν πυξίδα εἰς τὸ μέσον παρῆγεν. καὶ ἀδελφὸς δὲ Ἀντιφίλου ἕτερος καὶ μήτηρ αὐτοῦ ἀνάγκαις τε καὶ βασάνων σφοδρότητι ταὐτὰ ἔλεγον καὶ ἐγνώριζον τὴν πυξίδα."},{"number":78,"text":"κατηγορεῖτο δὲ καὶ τοῦ ἀρχιερέως ἡ θυγάτηρ, γυνὴ δὲ τοῦ βασιλέως, ὡς πάντων ἵστωρ τούτων γενομένη κρύπτειν προθυμηθεῖσα αὐτά. καὶ διὰ τάδε Ἡρώδης ἐκείνην τε ἐξέβαλεν καὶ τὸν υἱὸν αὐτῆς ἐξήλειψε τῶν διαθηκῶν εἰς ὃ βασιλεύσοι μενουσῶν, καὶ τὸν πενθερὸν τὴν ἀρχιερωσύνην ἀφείλετο Σίμωνα τὸν τοῦ Βοηθοῦ, καθίσταται δὲ Ματθίαν τὸν Θεοφίλου Ἱεροσολυμίτην γένος."},{"number":79,"text":"Ἐν τούτῳ δὲ καὶ Βάθυλλος ἐκ Ῥώμης ἀπελεύθερος Ἀντιπάτρου παρῆν καὶ βασανισθεὶς εὑρίσκεται φάρμακον κομίζων δώσειν τε τῇ ἑαυτοῦ μητρὶ καὶ Φερώρᾳ, ὡς εἰ τὸ πρότερον μὴ ἅπτοιτο τοῦ βασιλέως, τούτῳ γοῦν μεταχειρίζοιντο αὐτόν."},{"number":80,"text":"ἀφίκετο δὲ γράμματα παρὰ τῶν ἐν Ῥώμῃ φίλων τῷ Ἡρώδῃ γνώμῃ καὶ ὑπαγορεύσει Ἀντιπάτρου ἐπὶ κατηγορίᾳ Ἀρχελάου καὶ Φιλίππου συγκείμενα, ὡς δῆθεν διαβάλλοιέν τε τὸν πατέρα ἐπὶ σφαγῇ τῶν περὶ Ἀριστόβουλον καὶ Ἀλέξανδρον, διʼ οἴκτου δὲ καὶ αὑτοὺς λαμβάνοιεν· ἤδη γὰρ καὶ ἐκαλοῦντο ὑπὸ τοῦ πατρός, οὐχ ὡς ἐφʼ ἑτέροις, ἀλλʼ ἐπὶ τοῖς κἀκείνους προσαπολωλεκόσι κατακλήσεως αὐτῶν γινομένης."},{"number":81,"text":"ταῦτα δὲ μεγάλων μισθῶν οἱ φίλοι τῷ Ἀντιπάτρῳ συνέπρασσον. γράφει δὲ καὐτὸς Ἀντίπατρος τῷ πατρὶ περὶ αὐτῶν ἐπὶ μεγίσταις τῶν αἰτιῶν καὶ παντελὲς ἀπαλλάσσειν φάσκων τὰ μειράκια, τῶν δὲ τῇ ἡλικίᾳ τὴν ἀνάθεσιν ποιούμενος. αὐτὸς δὲ τὰ περὶ Σύλλαιον ἠγωνίζετο καὶ θεραπεία τῶν πρώτων ἀνδρῶν ἐγεγόνει κόσμος τε ἀξιοπρεπὴς ταλάντων ἐώνητο διακοσίων."},{"number":82,"text":"θαυμάσειε δʼ ἄν τις, ὅτι τοσούτων ἐν Ἰουδαίᾳ κατʼ αὐτοῦ κεκινημένων μησὶ πρότερον ἑπτὰ οὐδὲν αὐτῷ δῆλον γένοιτο· αἴτιον δʼ ἦν ἥ τε ἀκρίβεια καὶ φυλακὴ τῶν ὁδῶν καὶ μῖσος τῶν ἀνθρώπων τὰ πρὸς Ἀντίπατρον· οὐδεὶς γὰρ ἦν, ὃς προθύμως κινδύνῳ τῷ αὐτοῦ ποριστὴς τῶν ἐκείνου ἀσφαλειῶν καθίστατο."}],"5":[{"number":83,"text":"Ἡρώδης δὲ Ἀντιπάτρου γεγραφότος πρὸς αὐτόν, ὡς τὰ πάντα ᾗ χρῆν διαπεπραγμένος ἥξοι ἐν τάχει, ἐπικρυψάμενος τὴν ὀργὴν ἀντεπετίθει, κελεύων μὴ ἀπιέναι τῆς εἰς τὴν ὁδὸν, μὴ καί τι πάσχοι παρὰ τὴν ἐκδημίαν αὐτοῦ, καὶ ἅμα τῆς μητρὸς αὐτοῦ κατηγορῶν ὡς ὀλίγον καταθήσεσθαι μέμψεις ἐπαγγελλόμενος τὰς πρὸς αὐτήν,"},{"number":84,"text":"ὁπότε ἐκεῖνος ἀφίκοιτο, παντί τε τρόπῳ φιλότητα τὴν πρὸς αὐτὸν ἐνεδείκνυτο, δεδιὼς μὴ καί τι ὑποτοπηθεὶς ὑπερβάλλοιτο μὲν ὁδοὺς τὰς πρὸς αὐτόν, τῇ δὲ Ῥώμῃ ἐνδιαιτώμενος κτήσεις ἐφεδρεύοι τῇ βασιλείᾳ καὶ δὴ καὶ διαπράσσοι τι αὐτῇ."},{"number":85,"text":"τούτοις ἐν Κιλικίᾳ τοῖς γράμμασιν ἐπιτυγχάνει, τοῖς δὲ τὴν Φερώρου τελευτὴν διασαφοῦσιν ἐν Τάραντι πρότερον, δεινῶς τε ἤνεγκεν οὐκ εὐνοίᾳ τῇ Φερώρου, διότι δὲ τοῦ πατρὸς τὴν ἀναίρεσιν οὐ διαπραξάμενος ὥσπερ ὑπέσχετο ἀπέθανε."},{"number":86,"text":"περὶ δὲ Κελένδεριν τῆς Κιλικίας γενόμενος ἐνεδοίαζεν ἤδη περὶ τοῦ οἴκαδε πλοῦ δεινῶς τῇ ἐκβολῇ τῆς μητρὸς λελυπημένος, καὶ τῶν φίλων οἱ μὲν ἐκέλευον αὐτὸν ταῦτά πῃ καραδοκοῦντα ἀνέχειν, οἱ δὲ μὴ διαμέλλειν τὸν οἴκαδε πλοῦν· λύσειν γὰρ παραγενόμενον αἰτίαν πᾶσαν, ὡς καὶ νῦν οὔτι ἑτέρωθεν, ἀλλὰ διὰ τὴν ἐκείνου ἀπουσίαν ἰσχὺν τοῖς κατηγόροις ὑπογενέσθαι."},{"number":87,"text":"τούτοις πεισθεὶς ἔπλει τε καὶ προσέσχε τῷ Σεβαστῷ λιμένι λεγομένῳ, ὃν κατασκευάσας Ἡρώδης πολλῶν χρημάτων ἐπὶ τιμῇ τῇ Καίσαρος καλεῖ Σεβαστόν."},{"number":88,"text":"ἐν προύπτοις δʼ ἦν Ἀντίπατρος ἤδη τοῖς κακοῖς μήτε προσιόντος αὐτῷ μηδενὸς μήτε προσαγορεύοντος ὥσπερ ὅτʼ ἐξῄει μετʼ εὐχῶν καὶ ἀγαθῶν ἐπιφημισμάτων ταῖς ἐναντιωτάταις ἀραῖς οὐκ ἐκωλύοντο αὐτὸν δέχεσθαι ποινὴν τοῖς ἀδελφοῖς ἀποτίνειν ὑπειληφότες."},{"number":89,"text":"Ἐτύγχανεν δʼ ἐν Ἱεροσολύμοις κατὰ τοῦτον τὸν καιρὸν Οὔαρος Κοϊντίλιος, διάδοχος μὲν Σατορνίνῳ τῆς ἐν Συρίᾳ ἀρχῆς ἀπεσταλμένος, ἥκων δὲ αὐτός τε σύμβουλος Ἡρώδῃ περὶ τῶν ἐνεστηκότων αὐτῷ δεηθέντι."},{"number":90,"text":"καὶ αὐτῶν συνεδρευόντων παρῆν ὁ Ἀντίπατρος οὐδενὸς αὐτῷ ἐκπύστου γεγονότος. εἴσεισιν δὲ εἰς τὸ βασίλειον ἔτι πορφυρίδας ἀμπεχόμενος, καὶ αὐτὸν μὲν δέχονται οἱ ἐπὶ θύραις, ἀνείργουσι δὲ τοὺς φίλους."},{"number":91,"text":"ἐθορυβεῖτο δὲ ἤδη σαφῶς οἷ ἐληλύθει κατανοῶν, ἐπειδὴ καὶ ὁ πατὴρ προσιόντα αὐτὸν ὡς ἀσπάσαιτο ἀπεώσατο, ἀδελφοκτονίαν τε ἐπικαλῶν καὶ βούλευσιν ὀλέθρου τοῦ ἐπʼ αὐτῷ, πάντων τε ἀκροατὴν καὶ δικαστὴν ἔσεσθαι Οὔαρον τῇ αὔριον."},{"number":92,"text":"καὶ ὁ μὲν τοιούτου κακοῦ ἅμα τε ἀκροαθέντος καὶ παρόντος τῷ μεγέθει περιφερόμενος ᾤχετο, ὑπαντιάζουσιν δʼ αὐτὸν ἥ τε μήτηρ καὶ γυνή, αὕτη δὲ ἦν ήδη Ἀντιγόνῳ παῖς τῷ πρὸ Ἡρώδου Ἰουδαίων βεβασιλευκότι, παρʼ ὧν τὰ πάντα ἐκμαθὼν ἐν παρασκευαῖς τοῦ ἀγῶνος ἦν."},{"number":93,"text":"Τῇ δʼ ἑξῆς συνήδρευεν μὲν Οὔαρός τε καὶ ὁ βασιλεύς, εἰσεκλήθησαν δὲ καὶ οἱ ἀμφοῖν φίλοι καὶ οἱ συγγενεῖς βασιλέως Σαλώμη τε ἡ ἀδελφή, εἶτʼ εἴ τινες μηνύσειν ἔμελλον καὶ ὧν βάσανοι γεγόνασιν, δοῦλοί τε μητρῷοι τοῦ Ἀντιπάτρου μικρῷ πρότερον συνειλημμένοι ἢ ʼκεῖνον ἥκειν, ἐπιστολὴν φέροντες, ἧς τὸ κεφάλαιον τῶν γεγραμμένων ἦν μὴ ἐπανιέναι ὡς πάντων τῷ πατρὶ ἡκόντων εἰς πύστιν, μόνην τε ἂν καταφυγὴν αὐτῷ λείπεσθαι Καίσαρα καὶ σὺν αὐτῇ τὸ μὴ πατρὶ ὑποχείριον γενέσθαι."},{"number":94,"text":"Ἀντιπάτρου δὲ προσπεσόντος τῷ πατρὶ πρὸς τὰ γόνατα καὶ ἱκετεύοντος μὴ προδιεγνωσμένην καταστῆναι δίκην, ἀλλʼ ἀκροάσεως αὐτοῦ γενομένης παρὰ τῷ πατρὶ ἀκεραίως μένειν δυναμένῳ, τοῦτον κελεύσας Ἡρώδης ἀπάγειν εἰς μέσον αὐτὸς ὠλοφύρατο τῶν παίδων τῆς ποιήσεως, ἣν ἐπὶ τοιαύταις αὐτῷ τύχαις γενομένην πρότερον ἢ τῆς δυσμενείας ἀνασπάσασθαι τῶν πρότερον εἰς Ἀντίπατρον ἐμβαλεῖν αὐτοῦ τὸ γῆρας, τροφάς τε καὶ παιδεύσεις ἃς ποιήσαιτο αὐτῶν ἐξηγούμενος καὶ πλούτου εὐπορίαν ἐν καιροῖς ὡς θελήσειαν προτεθεῖσαν εἰς πάντα·"},{"number":95,"text":"ὧν οὐδὲν ἐπʼ ἐμποδίσματι γενέσθαι τοῦ μὴ οὐκ ἐπιβουλῇ τῇ ἐκείνων κινδυνεῦσαι τελευτᾶν ὑπὲρ τοῦ θᾶσσον δυσσεβῶς τὴν βασιλείαν παραλαβεῖν ἢ φύσεως νόμῳ μεταστάντος εὐχῇ τε τοῦ πατρὸς καὶ δίκῃ."},{"number":96,"text":"τόν τε Ἀντίπατρον θαυμάζειν, τίνων ἐλπίδι ἐπαρθεὶς θαρσήσειεν ἐπὶ τοιαῦτα χωρεῖν μὴ ἀποτραπῆναι· διάδοχον μὲν γὰρ ἀποφήνασθαι διὰ γραμμάτων τῆς ἀρχῆς, ζῶντος δὲ ἐπʼ οὐδενὶ μειονεκτεῖν ἀξιώματός τε ἐπιφανείᾳ καὶ δυνάμει ἐξουσίας, πεντήκοντα μὲν τάλαντα ἐπέτειον πρόσοδον κομισάμενον, δωρεὰν δʼ εἰληφότα ὁδοῦ τῆς εἰς Ῥώμην τριακοσίων ταλάντων ἀριθμόν."},{"number":97,"text":"ἐπεκάλει δὲ καὶ τῶν ἀδελφῶν εἰ μὲν πονηρῶν γεγονότων κατηγορίαν προθεμένῳ μιμητῇ γεγονότι, διακενῆς δὲ τοιῶνδε ἐπαγωγὰς ἐπάγοντι αὐτῇ τῶν συγγενῶν·"},{"number":98,"text":"τὰ γὰρ πάντα οὐδαμόθεν ἀλλὰ μηνύσει τῇ ἐκείνου μεμαθηκότα πρᾶξαι τὰ ἐπʼ αὐτοῖς πεπραγμένα γνώμῃ τῇ ἐκείνου, οὓς ἀπολύειν κακοῦ παντὸς κληρονόμον τῆς πατροκτονίας αὐτοῖς καθιστάμενον."},{"number":99,"text":"Ταῦθʼ ἅμα λέγων εἰς δάκρυα τρέπεται λέγειν τε ἄπορος ἦν. καὶ Νικόλαος ὁ Δαμασκηνός, φίλος τε ὢν τοῦ βασιλέως καὶ τὰ πάντα συνδιαιτώμενος ἐκείνῳ καὶ τοῖς πράγμασιν ὃν πραχθεῖεν τρόπον παρατετευχώς, δεηθέντι τῷ βασιλεῖ τὰ λοιπὰ εἰπεῖν ὁπόσα ἀποδείξεών τε καὶ ἐλέγχων ἐχόμενα ἦν."},{"number":100,"text":"καὶ τοῦ Ἀντιπάτρου κατὰ δικαιολογίαν πρὸς τὸν πατέρα τετραμμένου καὶ ὁπόσα παραδείγματα τῆς εὐνοίας πρὸς αὐτὸν διεξιόντος, τὰς τιμὰς αἳ ὑπῆρχον αὐτῷ προφερόμενος, ἃς μὴ ἄν ποτε γενέσθαι μὴ οὐκ ἀρετῆς ἀξίῳ περὶ αὐτὸν γεγονότι·"},{"number":101,"text":"καὶ γὰρ ὁπόσα προϊδεῖν δεήσειε πάντων προβεβουλευκέναι σωφρόνως, εἴ τέ τινα ἐδεῖτο χειρῶν, πόνῳ τῷ αὐτοῦ ἐκπεπρᾶχθαι τὰ πάντα, εἰκός τε οὐκ εἶναι τῶν ἀλλαχόθεν ἐπιβουλῶν τὸν πατέρα ἐξελόμενον αὐτὸν ἐπιβουλευτὴν καταστῆναι ἀφανίζοντα ἀρετήν, ἣ ἐπʼ ἐκείνοις ἐμαρτυρεῖτο αὐτῷ, κακίᾳ τῇ ἐπὶ τοῖσδε μελλούσῃ συνεῖναι."},{"number":102,"text":"καίτοι γε τοῦ μέλλοντος διάδοχον προαποδεδεῖχθαι καὶ τοῦ συναπολαυσομένου τιμῶν, αἳ εἰς τὸ παρὸν περιῆσαν, οὐκ ἐπικεκωλῦσθαι· εἰκός τε οὐκ εἶναι τὸν ἁπάντων ἀκινδύνως καὶ μετʼ ἀρετῆς ἔχοντα τὴν ἡμίσειαν μετὰ ψόγων καὶ κινδύνου ἐφίεσθαι τοῦ ὅλου ἄδηλον εἰ δυναμένου περιγενέσθαι, καὶ ταῦτα τεθεαμένον τὴν ζημίαν τῶν ἀδελφῶν καὶ μηνυτὴν μὲν καὶ κατηγορητὴν γενόμενον λανθάνειν δυναμένων, κολαστὴν δʼ ἐπεὶ φανεροὶ κατέστησαν πονηροὶ τὰ πρὸς τὸν πατέρα ὄντες."},{"number":103,"text":"καὶ τάδε μὲν αὐτῷ τῶν ἐνταῦθα ἠγωνισμένων παραδείγματα εἶναι τῶν ἀκράτῳ εὐνοίᾳ πρὸς τὸν πατέρα πεπολιτευμένων· τῶν δʼ ἐπὶ Ῥώμης μάρτυρα εἶναι Καίσαρα ἐπίσης τῷ θεῷ ἀπατηθῆναι μὴ οἷόν τε ὄντα."},{"number":104,"text":"ὧν πίστιν εἶναι τὰ ὑπʼ ἐκείνου γράμματα ἐπεσταλμένα, ὧν οὐ καλῶς ἔχειν ἰσχυροτέρας εἶναι τὰς διαβολὰς τῶν στασιάζειν αὐτοὺς προθεμένων τὰς πλείους ἀποδημίᾳ τῇ αὐτοῦ συντεθῆναι σχολῆς τοῖς ἐχθροῖς ἐγγενομένης, ἣν οὐκ ἂν αὐτοῖς ἐπιδημοῦντος παραγενέσθαι."},{"number":105,"text":"διαβάλλοντος δὲ καὶ τὰς βασάνους εἰς ψευδολογίαν, ὡς τῆς ἀνάγκης φύσιν ἐχούσης διδάσκειν τοὺς ὑποπεσόντας τὰ πολλὰ ἡδονῇ τῶν ἐφεστηκότων λέγειν,"},{"number":106,"text":"καὶ παρέχοντος αὑτὸν εἰς βάσανον, ἐπὶ τούτοις τροπῆς τοῦ συνεδρίου γενομένης, σφόδρα γὰρ ᾤκτειραν τὸν Ἀντίπατρον δάκρυσίν τε καὶ αἰκίαις τοῦ προσώπου χρώμενον, ὥστε καὶ τοῖς ἐχθροῖς διʼ οἴκτου καταστῆναι φανερὸν δὲ ἤδη καὶ Ἡρώδην εἶναι καμπτόμενόν τι τῇ γνώμῃ καίπερ μὴ βουλόμενον ἔκδηλον εἶναι, Νικόλαος ἀρξάμενος οἷς τε ὁ βασιλεὺς κατήρξατο λόγοις παλιλλογεῖ μειζόνως ἐκδεινῶν καὶ ὁπόσα ἐκ βασάνων ἢ μαρτυριῶν συνῆγεν τὴν ἀπόδειξιν τοῦ ἐγκλήματος."},{"number":107,"text":"μάλιστα δὲ τὴν ἀρετὴν ἐπιπολὺ ἐξηγεῖτο τοῦ βασιλέως, ᾗ περί τε τροφὰς καὶ παιδεύματα χρησάμενος τῶν υἱέων οὐδαμόθεν εὕροιτο ὀνησιφόρον αὐτὴν περιπταίων ἑτέροις ἀφʼ ἑτέρων."},{"number":108,"text":"καίτοι γε οὐχ οὕτως θαυμάζειν τῶν προτέρων τὴν ἀβουλίαν, νεωτέρους γὰρ καὶ κακίᾳ συμβούλων διεφθαρμένους ἀπαλεῖψαι τὰ τῆς φύσεως δικαιώματα ἀρχῆς θᾶσσον ἢ χρῆν μεταποιεῖσθαι σπουδάσαντας,"},{"number":109,"text":"Ἀντιπάτρου δʼ ἂν δικαίως τὴν μανίαν καταπλαγῆναι μὴ μόνον οἷς ὑπὸ τοῦ πατρὸς εὐεργετηθείη τὸν λογισμὸν ὥσπερ τὰ ἰοβολώτατα τῶν ἑρπετῶν μὴ μαλαχθέντος, καίτοι γε κἀκείνοις τινὸς ἐγγινομένης μαλακίας τοῦ ἀδικεῖν τοὺς εὐεργέτας, ἀλλὰ μηδὲ τὰς τύχας τῶν ἀδελφῶν πρὸς τὸ οὐ μιμητὴν αὐτῶν καταστῆναι τῆς ὠμότητος ἐμποδὼν στάντος."},{"number":110,"text":"καίτοι γε, ὦ Ἀντίπατρε, τῶν ἀδελφῶν μηνυτής τε ὧν τολμήσειαν αὐτὸς ἦς καὶ ἐρευνητὴς τῶν ἐλέγχων καὶ κολαστὴς πεφωραμένων. καὶ οὐ τοῦ ἐπʼ ἐκείνοις ἐγκαλοῦμεν θυμῷ χρῆσθαι μὴ ἐλλιπόντος, ἀλλὰ τοῦ μιμεῖσθαι τὴν ἀσέλγειαν αὐτῶν σπουδάσαντος ἐκπεπλήγμεθα, εὑρίσκοντες κἀκεῖνά σοι οὐκ ἐπʼ ἀσφαλείᾳ τοῦ πατρός, ἀλλʼ ἐπʼ ὀλέθρῳ τῶν ἀδελφῶν πεπραγμένα, ὅπως μισοπονηρίᾳ τῇ κατʼ αὐτῶν φιλοπάτωρ εἶναι πεπιστευμένος ἀδεεστέραν ἐπʼ αὐτῷ κακουργεῖν παραλάβοις δύναμιν, ὃ δὴ καὶ τοῖς ἔργοις παρέστησας."},{"number":111,"text":"ἅμα γὰρ καὶ τοὺς ἀδελφοὺς ἀνῄρεις ἐφʼ οἷς ἤλεγχες πονηροὺς γεγονότας καὶ τοὺς ὁμοπραγήσαντας αὐτοῖς οὐχ ὑπεδίδους, φανερὸν τοῖς πᾶσιν καθιστάς, ὡς καὶ συνθήκην πρὸς αὐτοὺς κατὰ τοῦ πατρὸς ποιησάμενος ἐπανείλω κατηγορεῖν,"},{"number":112,"text":"βουλόμενος σοὶ τὴν ἐπιβουλὴν τῆς πατροκτονίας κερδαίνεσθαι καταμόνας καὶ δυοῖν ἀγώνοιν εὐφροσύνην καρπούμενος τρόπου τοῦ σοῦ ἀξίαν, φανεροῦ μὲν τοῦ κατὰ τῶν ἀδελφῶν, ᾧ καὶ ἠγάλλου ὡς ἐπὶ τοῖς μεγίστοις, καὶ ἦν ἄξιον οὕτως φρονεῖν,"},{"number":113,"text":"εἰ δὲ μήγε σὺ χείρων ἦς, κρυπτοῦ δέ, ὃν κατὰ τοῦ πατρὸς συντιθεὶς ἐκείνους μὲν οὐχ ὡς τῷ πατρὶ ἐπιβεβουλευκότας μισῶν, οὐ γὰρ ἂν ἐξώκειλας αὐτοῖς ἐπὶ πρᾶξιν παραπλησίαν, ἀλλʼ ὡς διαδόχους τῆς ἡγεμονίας σου δικαιότερον ἂν γενομένους, τὸν δὲ πατέρα ἐπισφάζειν τοῖς ἀδελφοῖς,"},{"number":114,"text":"ἵνα θᾶσσον ὡς ἐκείνων τε ἐπικαταψεύσαιο μὴ ἐλεγχθῇς καὶ ὧν αὐτὸς δίκας παρασχεῖν ἄξιος γένοιο ταύτην παρὰ τοῦ δυστυχοῦς εἰσπράξαιο πατρός, ἐπινοῶν πατροκτονίαν οὐ κοινήν, ἀλλʼ οἵαν μέχρι νῦν οὐχ ἱστόρησεν ὁ βίος."},{"number":115,"text":"οὐχ υἱὸς γὰρ μόνον πατρὶ ἐπεβούλευες, ἀλλὰ καὶ φιλοῦντι καὶ εὐεργετηκότι, κοινωνὸς τῆς βασιλείας ὢν τοῖς ἔργοις καὶ διάδοχος προφανθεὶς καὶ τὴν μὲν ἡδονὴν τῆς ἐξουσίας ἤδη προλαμβάνειν μὴ ἐπικεκωλυμένος, ἐλπίδα δὲ τὴν εἰσαῦθις γνώμῃ τοῦ πατρὸς καὶ γράμμασιν προησφαλισμένος."},{"number":116,"text":"ἀλλʼ οὐκ ἄρα τῇ Ἡρώδου ἀρετῇ τὰ πράγματα, γνώμῃ δὲ καὶ πονηρίᾳ ἔκρινες τῇ σεαυτοῦ, βουλόμενος τοῦ πάντων σοι ὑπακούσαντος πατρὸς καὶ τὸ μέρος ἀφαιρεῖσθαι καὶ ὃν προσεποιοῦ τοῖς λόγοις σώζειν τοῖς ἔργοις τοῦτον ἀφανίσαι ζητῶν,"},{"number":117,"text":"καὶ μὴ μόνον αὐτὸς πονηρὸς καθιστάμενος, ἀλλὰ καὶ τὴν μητέρα ὧν ἐπενόεις πιμπλὰς καὶ στασιοποιῶν τὴν εὔνοιαν τοῖς ἀδελφοῖς καὶ τολμῶν θηρίον ἀποκαλεῖν τὸν πατέρα, παντὸς ἑρπετοῦ χαλεπωτέραν τὴν διάνοιαν κατεσκευασμένος, ᾗ τὸν ἐκείνων ἰὸν ἐπὶ τοὺς συγγενεστάτους καὶ τοὺς ἐπὶ τοσούτοις εὐεργέτας παρεκάλεις ἐπὶ συμμαχίαις φυλάκων καὶ τέχναις ἀνδρῶν καὶ γυναικῶν φρασσόμενος κατὰ τοῦ γέροντος, ὥσπερ οὐκ ἀρκούσης τῆς διανοίας μῖσος τὸ ὑποικουροῦν παραστῆσαι."},{"number":118,"text":"καὶ νῦν ἐλήλυθας μετὰ βασάνους ἐλευθέρων οἰκετῶν ἀνδράσι γυναιξὶν διὰ σὲ γεγονυίας μηνύσεις τῶν συνωμοτῶν ἀντιλογεῖν τῇ ἀληθείᾳ σπεύδων, καὶ μονονουχὶ τὸν πατέρα ἀναιρεῖν μεμελετηκὼς ἐκ τοῦ ἀνθρωπείου, ἀλλʼ ἤδη καὶ νόμον τὸν κατὰ σοῦ γεγραμμένον καὶ τὴν ἀρετὴν τὴν Οὐάρου καὶ τοῦ δικαίου τὴν φύσιν,"},{"number":119,"text":"οὕτως ἄρα τῇ ἀναιδείᾳ πέποιθας, ὥστε καὶ βασανίζεσθαι ἀξιοῖς, καὶ ψευδεῖς λέγων τὰς βασάνους τῶν προβεβασανισμένων, ἵνʼ οἱ μὲν ῥυόμενοί σου τὸν πατέρα ἐκκρουσθῶσιν τοῦ ἠληθευκέναι, αἱ δὲ σαὶ βάσανοι δοκῶσι πισταί;"},{"number":120,"text":"οὐ ῥύσῃ Οὔαρε τὸν βασιλέα τῆς ἐπηρείας τῶν συγγενῶν; οὐδὲ πονηρὸν θηρίον, ἐπʼ ὀλέθρῳ μὲν τῶν ἀδελφῶν εὔνοιαν προσποιούμενον τοῦ πατρός, ἔνθα δὲ μέλλοι καταμόνας ταχέως ἀποίσεσθαι τὴν βασιλείαν πάντων αὐτῷ θανασιμώτατον ἀναφαινόμενον; γνοὺς ὅτι πατροκτονία κοινόν ἐστιν ἀδίκημα καὶ τῆς φύσεως καὶ τοῦ βίου τὴν πεφηνυῖαν ὡς οὐδὲν ἡσσόνως τοῦ βεβουλευμένου καὶ ὁ μὴ κολάζων ἀδικεῖ τὴν φύσιν."},{"number":121,"text":"Προσετίθει δὲ ἤδη τὰ τῆς μητρὸς Ἀντιπάτρου ὁπόσα πρός τινας ἦν κουφολογίᾳ γυναικείῳ εἰρημένα, μαντείας τε καὶ θυσίας ἐπὶ τῷ βασιλεῖ γεγονυίας καὶ ὁπόσα μετὰ τῶν Φερώρου γυναικῶν Ἀντιπάτρῳ ἠσέλγητο μετὰ οἴνου καὶ λύμης ἐρωτικῆς, τῶν τε βασάνων ἀνακρίσεις καὶ ὁπόσα μαρτυριῶν ἐχόμενα· πολλὰ δὲ καὶ παντοῖα ἦν τὰ μὲν προητοιμασμένα, τὰ δὲ πρὸ τοῦ ὀξέως ἀπαγγέλλεσθαί τε καὶ βεβαιοῦσθαι ἐφευρημένα·"},{"number":122,"text":"οἱ γὰρ ἄνθρωποι κἂν εἴ τι κατὰ φόβον τοῦ Ἀντιπάτρου, μὴ διαδρὰς ἀμύνοιτο αὐτούς, σιγῇ παρεδίδοσαν, ὁρῶντες αὐτὸν ἐπιβατὸν ταῖς κατηγορίαις τῶν ἀρξάντων γεγονότα καὶ τὴν ποτὲ πολλὴν αὐτῷ συστᾶσαν τύχην προφανῶς αὐτὸν τοῖς ἐχθροῖς παραδεδωκυῖαν, οἳ καὶ ἀπλήστως μίσους τοῦ πρὸς αὐτὸν ἐνεφοροῦντο·"},{"number":123,"text":"κατέσπευδε δὲ τότε οὔτι τῇ ἔχθρᾳ τῶν ἐπικεχειρηκότων κατηγορεῖν, ὡς μεγέθει τόλμης ὧν ἐπενόησεν κακιῶν καὶ δυσμενείας τῆς πρὸς τὸν πατέρα καὶ τοὺς ἀδελφούς, στάσεως καὶ ἀλληλοφθοριῶν ἀναπεπληκὼς τὸν οἶκον καὶ μήτε μίσει κατὰ δίκην μήτε φιλίᾳ διʼ εὔνοιαν χρώμενος, ἀλλʼ ὡς μελλήσοι αὐτῷ συμφέρειν·"},{"number":124,"text":"ὧν ἁπάντων ἐκ πλέονος αὐτοῖς οἱ πολλοὶ προανεσκοπημένων, οἵπερ δὴ μάλιστα ἀρετῇ κρίνειν πεφύκασιν ἐπὶ τοῖς πράγμασιν διὰ τὸ καὶ ὀργῆς ἀπηλλαγμένως ἐπιψηφίζειν τοῖς γινομένοις, καταβοὰς ἐν τοῖς πρὶν εἱρχθέντες ποιεῖσθαι παραγενομένης ἀδείας ἐξέφερον εἰς μέσον ὁπόσα εἰδεῖεν."},{"number":125,"text":"πολύτροποί τε κακιῶν ἀποδείξεις ἦσαν οὐδαμόθεν ψεύδους αἰτίαν ἐγκαλεῖσθαι δυνάμεναι διὰ τὸ μήτʼ εὐνοίᾳ τῇ πρὸς Ἡρώδην λέγειν τοὺς πολλοὺς μήτε ὑποψίᾳ κινδύνων σιγῆς ἐφʼ οἷς ἔχοιεν εἰπεῖν ἐγκαλουμένης, ἀλλὰ τῷ πονηρά τε ἡγεῖσθαι τὰ πράγματα, καὶ τὸν Ἀντίπατρον οὐκ ἀσφαλείᾳ τῇ Ἡρώδου, πονηρίᾳ δὲ τῇ αὐτοῦ πάσης ἄξιον τιμωρίας."},{"number":126,"text":"πολλά τε ἦν καὶ παρὰ πολλῶν οἷς μὴ παρήγγελτο εἰπεῖν ἀγορευόμενα, ὥστε τὸν Ἀντίπατρον καίπερ ἐπὶ πλεῖστον πάντα δεινότατον ὄντα ψεύσασθαι καὶ ἀπερυθριάσαι μηδὲ ὅσον ἀπὸ φωνῆς ἐπʼ ἀντιλέξει τὴν ἰσχὺν εἰσφέρεσθαι."},{"number":127,"text":"Νικολάου τε παυσαμένου τῶν τε λόγων καὶ τῶν ἐλέγχων Οὔαρος ἐκέλευσεν Ἀντίπατρον ἐπʼ ἀπολογίᾳ τῶν ἐγκλημάτων χωρεῖν, εἴ τινες αὐτῷ παρασκευαὶ τοῦ μὴ ἐνόχῳ τοῖς ἐπιφερομένοις εἶναι, καὶ γὰρ αὐτὸς εὔχεσθαι τὸν πατέρα εἰδέναι τῶν ὁμοίων εὐχόμενον μηδὲν αὐτὸν ἀδικοῦντα φωρᾶν."},{"number":128,"text":"ὁ δʼ ἐπὶ στόμα ἔκειτο ἀνατετραμμένος τε τῷ θεῷ καὶ πᾶσι προτιθεὶς τὸ ἐπιμαρτυρῆσον αὐτῷ μηδὲν ἀδικεῖν, ἢ τεκμηρίοις ἐμφανέσι παραστῆσαι μὴ οὐκ ἐπίβουλον αὐτὸν τοῦ πατρὸς γεγονέναι,"},{"number":129,"text":"εἰωθότες μὲν καὶ πάντες οἷς ἐπιλείπει ἀρετῆς, ὁπότε μὲν ἐγχειρηταί τινα κακῶν εἶεν τοῦ θείου τὸ πᾶσιν παρατυγχάνειν ἀφορίσαντες γνώμῃ τῇ αὐτῶν ἐπὶ τὰ ἔργα χωρεῖν, ὁπότε δὲ φωρώμενοι κινδυνεύοιεν δίκην ὑποσχεῖν, κατʼ ἐπίκλησιν αὐτοῦ μαρτυρῶν τὰ πάντα ἐκτρέπειν."},{"number":130,"text":"ὃ δὴ καὶ τῷ Ἀντιπάτρῳ συμβεβήκει· τὰ πάντα γὰρ ὡς ἐν ἐρημίᾳ τοῦ θείου διαπεπραγμένος, κατειργούσης αὐτὸν πανταχόθεν τῆς δίκης ἀπορίᾳ τῶν ἀλλαχόθεν δικαιωμάτων, οἷς ἀπολύσαιτο τὰ ἐγκεκλημένα, αὖθις ἐνεπαροίνει τῇ ἀρετῇ τοῦ θείου, μαρτυρίαν ἐπισκήπτων αὐτῷ περὶ ἰσχύι τῇ ἐκείνου περιτο ἕως εἰς μέσους παραγαγόντος ὁπόσα ἐπὶ τῷ πατρὶ πράσσειν τολμᾶν οὐκ ἐνέλιπεν."},{"number":131,"text":"Ὁ δὲ Οὔαρος ἐπειδὴ πολλάκις ἀνακρίνων τὸν Ἀντίπατρον οὐδὲν εὑρίσκετο πλέον τῆς ἀνακλήσεως τοῦ θεοῦ, ὁρῶν ἀπέραντον ὂν τὸ γινόμενον ἐκέλευσε τὸ φάρμακον εἰς μέσους ἐνεγκεῖν, ἵνʼ εἰδῇ τὴν περιοῦσαν αὐτῷ δύναμιν."},{"number":132,"text":"καὶ κομισθέντος τῶν ἐπὶ θανάτῳ τις ἑαλωκότων πίνει κελεύσαντος Οὐάρου καὶ παραχρῆμα ἔθανεν. τότε δὲ ἐξαναστὰς ἀπῄει τοῦ συνεδρίου καὶ τῇ ἑξῆς ἐπʼ Ἀντιοχείας, ᾗπερ δὴ καὶ τὸ πλεῖστον ἦσαν αὐτῷ διατριβαὶ διὰ τὸ Σύροις τοῦτο βασίλειον εἶναι. Ἡρώδης δὲ παραχρῆμα μὲν ἔδησε τὸν υἱόν."},{"number":133,"text":"ἄδηλοι δὲ τοῖς πολλοῖς ἦσαν αἱ Οὐάρου πρὸς αὐτὸν ὁμιλίαι καὶ τί εἰπὼν ἀπεληλύθει. εἰκάζετο δὲ τοῖς πολλοῖς γνώμῃ τῇ ἐκείνου πράσσειν ὁπόσα περὶ τὸν Ἀντίπατρον ἔπραξεν. δήσας δὲ αὐτὸν εἰς Ῥώμην ὡς Καίσαρα ἐκπέμπει γράμματα περὶ αὐτοῦ καὶ τοὺς ἀπὸ γλώσσης διδάξοντας τὸν Καίσαρα τὴν κακίαν τοῦ Ἀντιπάτρου καὶ Κωπωνίου γνώμη τὴν Καίσαρος."},{"number":134,"text":"ἁλίσκεται δὲ ὑπὸ τὰς αὐτὰς ἡμέρας καὶ ἐπιστολὴ ὑπὸ Ἀντιφίλου πρὸς Ἀντίπατρον γεγραμμένη, ἐν Αἰγύπτῳ δὲ αὐτὸς διέτριβεν, καὶ λυθεῖσα ὑπὸ τοῦ βασιλέως τάδε ἐδήλου· ἔπεμψά σοι τὴν παρʼ Ἀκμῆς ἐπιστολὴν μὴ φεισάμενος τῆς ἐμῆς ψυχῆς· οἶσθα γὰρ, ὅτι αὖθις κινδυνεύω ὑπὸ δύο οἰκιῶν, εἰ γνωσθείην."},{"number":135,"text":"σὺ δʼ εὐτυχοίης περὶ τὸ πρᾶγμα. καὶ ἡ μὲν ἐπιστολὴ τάδε ἐδήλου. ἐζήτει δὲ ὁ βασιλεὺς καὶ τὴν ἑτέραν ἐπιστολήν, οὐ μὴν φανερά γε ἦν, καὶ τοῦ Ἀντιφίλου δοῦλος ὃς τὴν ἀναγνωσθεῖσαν ἔφερεν ἠρνεῖτο ἑτέραν παραλαβεῖν."},{"number":136,"text":"ἀπορίας οὖν ἐχούσης τὸν βασιλέα τῶν φίλων τις τῶν τοῦ Ἡρώδου θεώμενος ὑπερραμμένον τοῦ δούλου τὸν ἐντὸς χιτῶνα, ἐνεδεδύκει γὰρ δύο, εἴκασεν ἐντὸς τῆς ἐπιπτυχῆς κρύπτεσθαι τὰ γράμματα· καὶ ἦν δὲ οὕτως."},{"number":137,"text":"λαμβάνουσιν οὖν τὴν ἐπιστολὴν ἐγγεγραμμένα τε ἦν ἐν αὐτῇ τάδε· Ἀκμὴ Ἀντιπάτρῳ. ἔγραψα τῷ πατρί σου οἵαν ἤθελες ἐπιστολὴν καὶ ἀντίγραφον ποιήσασα τῇ πρὸς τὴν ἐμὴν κυρίαν ὡς παρὰ Σαλώμης ἔγραψα,"},{"number":138,"text":"ἣν ἀναγνοὺς οἶδʼ ὅτι τιμωρήσεται Σαλώμην ὡς ἐπίβουλον. ἦν δὲ ἡ παρὰ τῆς Σαλώμης δοκοῦσα εἶναι πρὸς τὴν δέσποιναν αὐτῆς ὑπʼ Ἀντιπάτρου ἐπʼ ὀνόματι τῷ Σαλώμης ὅσα γοῦν ἡ διάνοια θέλοι ὑπηγορευμένη, λέξει δὲ συνέκειτο αὐτῆς."},{"number":139,"text":"τὰ δὲ γεγραμμένα ἦν τοιάδε· Ἀκμὴ βασιλεῖ Ἡρώδῃ. ἐγὼ ἔργον ποιουμένη μηδέν σε λανθάνειν τῶν κατὰ σοῦ γινομένων, εὑροῦσα ἐπιστολὴν Σαλώμης πρὸς τὴν ἐμὴν κυρίαν κατὰ σοῦ γεγραμμένην ἐπικινδύνως ἐμαυτῇ σοὶ δὲ ὠφελίμως ἐξεγραψάμην καὶ ἀπέστειλά σοι. ταύτην δὲ ἐκείνη ἔγραψεν γήμασθαι θέλουσα Συλλαίῳ. κατάσχισον οὖν τὴν ἐπιστολήν, ἵνα μὴ κἀγὼ τῷ ζῆν κινδυνεύσω."},{"number":140,"text":"πρὸς δὲ αὐτὸν ἐγέγραπτο Ἀντίπατρον διασαφούσης, ὅτι διακονουμένη κελεύσματι τῷ ἐκείνου αὐτή τε γράψειε πρὸς Ἡρώδην, ὡς Σαλώμης ἐπιβούλως αὐτῷ πράσσειν ἐπειγομένης τὰ πάντα, καὶ ἀντίγραφον τῆς ὡς πρὸς δέσποιναν τὴν αὐτῆς πεμφθείσης ἐπιστολῆς ὑπὸ Σαλώμης ἀποπέμψειεν αὐτῷ."},{"number":141,"text":"ἦν δὲ ἡ Ἀκμὴ Ἰουδαία μὲν τὸ γένος, ἐδούλευε δὲ Ἰουλίᾳ τῇ Καίσαρος γυναικὶ καὶ ἔπρασσε ταῦτα φιλίᾳ τῇ Ἀντιπάτρου ὠνηθεῖσα ὑπʼ αὐτοῦ μεγάλῃ δόσει χρημάτων συγκακουργεῖν κατά τε τοῦ πατρὸς καὶ κατὰ τῆς τηθίδος."},{"number":142,"text":"Ἡρώδης δὲ ἐκπλαγεὶς μεγέθει τῆς Ἀντιπάτρου κακίας ὥρμησεν μὲν καὶ παραχρῆμα αὐτὸν ἀνελεῖν ὡς κύκηθρον μεγάλων γεγονότα πραγμάτων καὶ μὴ μόνον αὐτῷ ἀλλὰ καὶ τῇ ἀδελφῇ ἐπιβεβουλευκότα καὶ τοῦ Καίσαρος διεφθαρκότα τὴν οἰκίαν, ἐξώτρυνεν δʼ αὐτὸν καὶ ἡ Σαλώμη στερνοτυπουμένη καὶ κτείνειν αὐτὴν κελεύουσα, εἴ τινος ἐπὶ τοιοῖσδε πίστεως αἰτίαν ἀξιόχρεων οἵα τε παρασχεῖν γένοιτο."},{"number":143,"text":"Ἡρώδης δὲ μεταπέμψας ἀνέκρινεν τὸν υἱὸν κελεύων εἴ τι ἀντειπεῖν ἔχοι λέγειν μηδὲν ὑπιδόμενον, ἐπεὶ δὲ ἀχανὴς ἦν, ἤρετο αὐτόν, ἐπειδὴ τὰ πάντα πανταχοῦ πεφώραται πονηρὸς ὤν, τοὺς γοῦν συγκακουργήσαντας αὐτῷ τὰ πράγματα μὴ μελλῆσαι κατειπεῖν."},{"number":144,"text":"ὁ δὲ Ἀντιφίλῳ τὴν πάντων αἰτίαν ἀνετίθει, ἕτερον δʼ οὐδένα προυτίθει. Ἡρώδης δὲ περιαλγῶν ὥρμησεν μὲν πέμπειν ἐπὶ Ῥώμης τὸν υἱὸν ὡς Καίσαρα λόγον ὑφέξοντα τῶν ἐπὶ τοῖσδε βουλευμάτων,"},{"number":145,"text":"ἔπειτα δείσας, μὴ καὶ βοηθείᾳ φίλων εὑρίσκοιτο τοῦ κινδύνου διαφυγάς, αὐτὸν μὲν δέσμιον ὡς καὶ πρότερον ἐφύλασσεν, αὖθις δὲ πρέσβεις ἐξέπεμπε καὶ γράμματα ἐπὶ κατηγορίᾳ τοῦ υἱέος ὁπόσα τε Ἀκμὴ συγκακουργήσειεν αὐτῷ καὶ ἀντίγραφα τῶν ἐπιστολῶν."}],"6":[{"number":146,"text":"Καὶ οἱ μὲν πρέσβεις ἐπὶ τῆς Ῥώμης ἠπείγοντο ὁπόσα τε ἀνακρινομένους δεήσοι λέγειν προσεκδιδαχθέντες καὶ τὰ γράμματα φέροντες· εἰς νόσον δὲ ὁ βασιλεὺς ἐμπεσὼν διαθήκας γράφει τῷ νεωτάτῳ τῶν υἱῶν τὴν βασιλείαν διδοὺς μίσει τῷ τε πρὸς τὸν Ἀρχέλαον καὶ Φίλιππον ἐκ τῶν Ἀντιπάτρου διαβολῶν, Καίσαρί τε ταλάντων χιλίων καὶ γυναικὶ Ἰουλίᾳ τῇ Καίσαρος καὶ τέκνοις καὶ φίλοις καὶ ἀπελευθέροις Καίσαρος πεντακοσίων."},{"number":147,"text":"ἔνεμε δὲ καὶ τοῖς υἱέσιν χρήματα καὶ προσόδους καὶ ἀγροὺς καὶ υἱέσι τοῖς ἐκείνων, Σαλώμην δὲ ἐπὶ μέγα ἐπλούτιζεν τὴν ἀδελφὴν εὔνουν τε αὐτῷ ἐπὶ πᾶσιν διαμεμενηκυῖαν καὶ μηδαμόθι θρασυνομένην κακουργεῖν."},{"number":148,"text":"ἀπεγνωκὼς δὲ περιοίσειν, καὶ γὰρ περὶ ἔτος ἑβδομηκοστὸν ἦν, ἐξηγρίωσεν ἀκράτῳ τῇ ὀργῇ καὶ πικρίᾳ εἰς πάντα χρώμενος· αἴτιον δὲ ἦν δόξα τοῦ καταφρονεῖσθαι καὶ ἡδονῇ τὰς τύχας αὐτοῦ τὸ ἔθνος φέρειν· ἄλλως τʼ ἐπειδή τινες τῶν δημοτικωτέρων ἀνθρώπων καὶ ἐπανέστησαν αὐτῷ διὰ τοιαύτην αἰτίαν."},{"number":149,"text":"Ἦν Ἰούδας ὁ Σαριφαίου καὶ Ματθίας ὁ Μεργαλώθου Ἰουδαίων λογιώτατοι καὶ παρʼ οὕστινας ἐξηγηταὶ τῶν πατρίων νόμων, ἄνδρες καὶ δήμῳ προσφιλεῖς διὰ παιδείαν τοῦ νεωτέρου· ὁσημέραι γὰρ διημέρευον αὐτοῖς πάντες οἷς προσποίησις ἀρετῆς ἐπετετήδευτο."},{"number":150,"text":"οἵ τε πυνθανόμενοι τοῦ βασιλέως τὴν νόσον θεραπεύειν ἄπορον οὖσαν ἐξῆραν τὸ νεώτερον, ὥστε ὁπόσα παρὰ νόμον τοῦ πατρίου κατεσκεύαστο ἔργα ὑπὸ τοῦ βασιλέως ταῦτα καθελόντες εὐσεβείας ἀγωνίσματα παρὰ τῶν νόμων φέρεσθαι· καὶ γὰρ δὴ διὰ τὴν τόλμαν αὐτῶν παρʼ ὃ διηγόρευεν ὁ νόμος τῆς ποιήσεως τά τε ἄλλα αὐτῷ συντυχεῖν, οἷς παρὰ τὸ εἰωθὸς τοῦ ἀνθρώπου διετρίβη, καὶ δὴ καὶ τὴν νόσον."},{"number":151,"text":"ἦν γὰρ τῷ Ἡρώδῃ τινὰ πραγματευθέντα παρὰ τὸν νόμον, ἃ δὴ ἐπεκάλουν οἱ περὶ τὸν Ἰούδαν καὶ Ματθίαν. κατεσκευάκει δὲ ὁ βασιλεὺς ὑπὲρ τοῦ μεγάλου πυλῶνος τοῦ ναοῦ ἀνάθημα καὶ λίαν πολυτελές, ἀετὸν χρύσεον μέγαν· κωλύει δὲ ὁ νόμος εἰκόνων τε ἀναστάσεις ἐπινοεῖν καί τινων ζῴων ἀναθέσεις ἐπιτηδεύεσθαι τοῖς βιοῦν κατʼ αὐτὸν προῃρημένοις."},{"number":152,"text":"ὥστε ἐκέλευον οἱ σοφισταὶ τὸν ἀετὸν κατασπᾶν· καὶ γὰρ εἴ τις γένοιτο κίνδυνος τῷ εἰς θάνατον ἀνακειμένῳ, πολὺ τῆς ἐν τῷ ζῆν ἡδονῆς λυσιτελεστέραν φαίνεσθαι τὴν προστιθεμένην ἀρετὴν ὑπʼ αὐτοῦ τοῖς ἐπὶ σωτηρίᾳ καὶ φυλακῇ τοῦ πατρίου μελλήσουσι τελευτᾶν διὰ τὸ ἀίδιον τοῦ ἐπαινεῖσθαι φήμην κατασκευασαμένους ἔν τε τοῖς νῦν ἐπαινεθήσεσθαι καὶ τοῖς ἐσομένοις ἀειμνημόνευτον καταλείπειν τὸν βίον."},{"number":153,"text":"καίτοι γε καὶ τοῖς ἀκινδύνως διαιτωμένοις ἄφυκτον εἶναι τὴν συμφοράν, ὥστε καλῶς ἔχειν τοῖς ἀρετῆς ὀριγνωμένοις τὸ κατεψηφισμένον αὐτοῦ μετʼ ἐπαίνων καὶ τιμῶν δεχομένοις ἀπιέναι τοῦ βίου."},{"number":154,"text":"φέρειν γὰρ κούφισιν πολλὴν τὸ ἐπὶ καλοῖς ἔργοις ὧν μνηστῆρα τὸν κίνδυνον εἶναι τελευτᾶν, καὶ ἅμα υἱέσι τῶν αὐτῶν καὶ ὁπόσοι τοῦ συγγενοῦς καταλείποιντο ἄνδρες γυναῖκες καὶ τοῖσδε περιποιῆσαι ὄφελος εὐκλείᾳ τῇ ἀπʼ αὐτῶν."},{"number":155,"text":"Καὶ οἱ μὲν τοιούτοις λόγοις ἐξῆραν τοὺς νέους. ἀφικνεῖται δὲ λόγος εἰς αὐτοὺς τεθνάναι φράζων τὸν βασιλέα καὶ συνέπραττε τοῖς σοφισταῖς. καὶ μέσης ἡμέρας ἀνελθόντες κατέσπων τε καὶ πελέκεσιν ἐξέκοψαν τὸν ἀετὸν πολλῶν ἐν τῷ ἱερῷ διατριβόντων."},{"number":156,"text":"καὶ ὁ στρατηγὸς τοῦ βασιλέως, ἀγγέλλεται γὰρ ἡ ἐπιχείρησις πρὸς αὐτόν, ἀπὸ μείζονος διανοίας ἢ ἐπράσσετο ὑπολαβὼν ἄνεισι χεῖρα πολλὴν ἀγόμενος, ὁπόσοι ἀνθέξοιεν τῷ πλήθει τῶν πειρωμένων καθαιρεῖν τὸ ἀνάθημα, ἐπιπεσών τε μὴ προσδεχομένοις, ἀλλʼ ὁποῖα ὄχλος φιλεῖ δόξῃ μᾶλλον ἀμαθεῖ ἢ προνοίᾳ ἀσφαλεῖ τετολμηκότας, ἀσυντάκτοις τε καὶ μηδὲν τοῦ ὀνήσοντος προανεσκοπημένοις,"},{"number":157,"text":"τῶν τε νέων οὐκ ἐλάσσους τεσσαράκοντα ἀνδρῶν, οἳ θάρσει ἔμενον ἐπιόντα ἐς φυγὴν τοῦ λοιποῦ πλήθους καταστάντος, λαμβάνει καὶ τοὺς εἰσηγητὰς τοῦ τολμήματος Ἰούδαν καὶ Ματθίαν ἄδοξον ἡγουμένους ὑποχωρεῖν τὴν ἔφοδον αὐτοῦ, καὶ ἀνήγαγεν ἐπὶ τὸν βασιλέα."},{"number":158,"text":"ἐρομένου δὲ ἐπεὶ ἀφίκοντο ἐπʼ αὐτὸν τοῦ βασιλέως, εἰ τολμήσειαν αὐτοῦ τὸ ἀνάθημα καθελεῖν, ἀλλὰ καὶ πεφρόνηταί γε ἡμῖν τὰ φρονηθέντα καὶ πέπρακται τὰ πεπραγμένα μετʼ ἀρετῆς ἀνδράσι πρεπωδεστάτης· τοῦ τε γὰρ θείου τῇ ἀξιώσει βεβοήθηται ὑφʼ ἡμῶν καὶ τοῦ νόμου ἠκρόατο τὸ σῶφρον,"},{"number":159,"text":"θαυμαστόν τε οὐδέν, εἰ τῶν σῶν δογμάτων ἀξιωτέρους τετηρῆσθαι ἡγησάμεθα νόμους, οὓς Μωσῆς ὑπαγορεύσει καὶ διδαχῇ τοῦ θεοῦ γραψάμενος κατέλιπεν. ἡδονῇ τε τὸν θάνατον οἴσομεν καὶ τιμωρίαν ἥντινα ἐπιβάλοις διὰ τὸ μὴ ἐπʼ ἀδίκοις ἔργοις, ἀλλὰ φιλίᾳ τοῦ εὐσεβοῦς μέλλειν συνείσεσθαι τὸ ἐφομιλῆσον αὐτοῦ."},{"number":160,"text":"καὶ οἱ μὲν ταῦτα πάντες ἔλεγον οὐδὲν ἐλλιπεστέρᾳ τῇ τόλμῃ τοῦ λόγου χρώμενοι, ᾗ θαρσήσαντες τὸ ἔργον πράττειν οὐκ ἀπετράποντο. βασιλεὺς δὲ αὐτοὺς καταδήσας μετέπεμπεν εἰς Ἱεριχοῦντα Ἰουδαίων τοὺς ἐν τέλει,"},{"number":161,"text":"καὶ παραγενομένων ἐξεκλησίασεν εἰς τὸ αὐτὸ θέατρον ἐπὶ κλινιδίου κείμενος ἀδυναμίᾳ τοῦ στῆναι, γωνεῖστων τε ἐφόσον αἵτινες ἦσαν ἐπʼ αὐτοὺς γεγονυῖαι ἀνηριθμεῖτο,"},{"number":162,"text":"καὶ τοῦ ναοῦ τὴν κατασκευὴν ὡς μεγάλοις τέλεσι τοῖς αὐτοῦ γένοιτο μὴ δυνηθέντων ἔτεσιν ἑκατὸν εἰκοσιπέντε τῶν Ἀσαμωναίου ἐν οἷς ἐβασίλευον τοιόνδε τι ἐπὶ τιμῇ πρᾶξαι τοῦ θεοῦ, κοσμῆσαι δὲ καὶ ἀναθήμασιν ἀξιολόγοις."},{"number":163,"text":"ἀνθʼ ὧν ἐλπίδα μὲν αὐτῷ γενέσθαι κἂν μεθὸ θάνοι καταλελείψεσθαι μνήμην τε αὐτοῦ καὶ εὔκλειαν. κατεβόα τε ἤδη, διότι μηδὲ ζῶντα ὑβρίζειν ἀπόσχοιντο εἰς αὐτόν, ἀλλʼ ἡμέρας τε καὶ ἐν ὄψει τῆς πληθύος ὕβρει χρωμένους ἅψασθαι τῶν ὑπʼ αὐτοῦ ἀνακειμένων καὶ καθαίρεσιν ὑβρίζοντάς τε ποιεῖσθαι, λόγῳ μὲν εἰς αὐτόν, ἀλήθειαν δὲ εἴ τις ἐξετάζοι τοῦ γεγονότος ἱεροσυλοῦντας."},{"number":164,"text":"Οἱ δὲ διὰ τὴν ὠμότητα αὐτοῦ, μὴ δὴ καὶ κατʼ αὐτῶν ἐξαγριώσας εἰσπράττοιτο τιμωρίαν, οὔτε γνώμῃ ἔφασαν αὐτὰ πεπρᾶχθαι τῇ αὐτῶν, φαίνεσθαί τε αὐτοῖς οὐκ ἀπηλλαγμένα κολάσεως αὐτὰ εἶναι. ὁ δὲ τοῖς μὲν ἄλλοις πραϋτέρως ἔσχεν, Ματθίαν δὲ τὸν ἀρχιερέα παύσας ἱερᾶσθαι ὡς αἴτιον τοῦ μέρους τούτων γεγονότα καθίστα Ἰωάζαρον ἀρχιερέα, ἀδελφὸν γυναικὸς τῆς αὐτοῦ."},{"number":165,"text":"ἐπὶ δὲ τοῦ Μαθθίου τούτου ἱερωμένου συμβαίνει καὶ ἕτερον ἀρχιερέα καταστῆναι πρὸς μίαν ἡμέραν, ἣν Ἰουδαῖοι νηστείαν ἄγουσιν."},{"number":166,"text":"αἰτία δʼ ἐστὶν ἥδε· ὁ Ματθίας ἱερώμενος ἐν νυκτὶ τῇ φερούσῃ εἰς ἡμέραν, ᾗ ἡ νηστεία ἐνίστατο, ἔδοξεν ἐν ὀνείρατι ὡμιληκέναι γυναικί, καὶ διὰ τόδε οὐ δυναμένου ἱερουργεῖν Ἰώσηπος ὁ τοῦ Ἐλλήμου συνιεράσατο αὐτῷ συγγενὴς ὤν."},{"number":167,"text":"Ἡρώδης δὲ τόν τε Ματθίαν ἐπεπαύκει τῆς ἀρχιερωσύνης καὶ τὸν ἕτερον Ματθίαν, ὃς ἐγηγέρκει τὴν στάσιν, καὶ ἄνδρας ἐκ τῶν ἑταίρων αὐτοῦ ἔκαυσεν ζώους. καὶ ἡ σελήνη δὲ τῇ αὐτῇ νυκτὶ ἐξέλιπεν."},{"number":168,"text":"Ἡρώδῃ δὲ μειζόνως ἡ νόσος ἐνεπικραίνετο δίκην ὧν παρανομήσειεν ἐκπρασσομένου τοῦ θεοῦ· πῦρ μὲν γὰρ μαλακὸν ἦν οὐχ ὧδε πολλὴν ἀποσημαῖνον τοῖς ἐπαφωμένοις τὴν φλόγωσιν ὁπόσην τοῖς ἐντὸς προσετίθει τὴν κάκωσιν."},{"number":169,"text":"ἐπιθυμία δὲ δεινὴ τοῦ δέξασθαί τι ἀπʼ αὐτοῦ, οὐ γὰρ ἦν μὴ οὐχ ὑπουργεῖν, καὶ ἕλκωσις τῶν τε ἐντέρων καὶ μάλιστα τοῦ κόλου δειναὶ ἀλγηδόνες, καὶ φλέγμα ὑγρὸν περὶ τοὺς πόδας καὶ διαυγές· παραπλησία δὲ καὶ περὶ τὸ ἦτρον κάκωσις ἦν, ναὶ μὴν καὶ τοῦ αἰδοίου σῆψις σκώληκας ἐμποιοῦσα, πνεύματός τε ὀρθία ἔντασις καὶ αὐτὴ λίαν ἀηδὴς ἀχθηδόνι τε τῆς ἀποφορᾶς καὶ τῷ πυκνῷ τοῦ ἄσθματος, ἐσπασμένος τε περὶ πᾶν ἦν μέρος ἰσχὺν οὐχ ὑπομενητὴν προστιθέμενος."},{"number":170,"text":"ἐλέγετο οὖν ὑπὸ τῶν θειαζόντων καὶ οἷς ταῦτα προαποφθέγγεσθαι σοφίᾳ πρόκειται, ποινὴν τοῦ πολλοῦ δυσσεβοῦς ταύτην ὁ θεὸς εἰσπράσσεσθαι παρὰ τοῦ βασιλέως."},{"number":171,"text":"καίπερ δὲ μειζόνως ἢ ἀντίσχοι ἄν τις ταλαιπωρούμενος ἐν ἐλπίδι τοῦ ἀνασφαλοῦντος ἦν, ἰατρούς τε μεταπέμπων καὶ ὁπόσα ἀρωγὰ ὑπαγορεύσειαν χρῆσθαι μὴ ἀποτετραμμένος, ποταμόν τε περάσας Ἰορδάνην θερμοῖς τοῖς κατὰ Καλλιρρόην αὑτὸν παρεδίδου, ἅπερ σὺν τῇ ἐς πάντα ἀρετῇ καὶ πότιμά ἐστιν· ἔξεισιν δὲ τὸ ὕδωρ τοῦτο εἰς λίμνην τὴν ἀσφαλτοφόρον λεγομένην."},{"number":172,"text":"κἀνταῦθα τοῖς ἰατροῖς δοκῆσαν ὥστε ἀναθάλπειν αὐτόν, καθεθεὶς εἰς πύελον πλέων ἐλαίου δόξαν μεταστάσεως ἐνεποίησεν αὐτοῖς. τῶν δὲ οἰκετῶν οἰμωγῇ χρωμένων περιενεγκὼν καὶ μηδʼ ἥντινα ἀμφὶ τοῦ σωθησομένου ἐλπίδα ἔχων τοῖς στρατιώταις ἀνὰ πεντήκοντα δραχμὰς ἑκάστῳ κελεύει νεμηθῆναι·"},{"number":173,"text":"πολλὰ δὲ καὶ τοῖς ἡγεμόσιν αὐτῶν καὶ φίλοις τοῖς αὐτοῦ ἐδωρεῖτο. καὶ παρῆν αὖθις ἐπὶ Ἱεριχοῦντος μέλαινά τε αὐτὸν ᾕρει χολὴ ἐπὶ πᾶσιν ἐξαγριαίνουσα, ὥστε δὴ τελευτῶν πρᾶξιν τοιάνδε ἐπινοεῖ·"},{"number":174,"text":"ἀφικομένων προστάγματι τῷ αὐτοῦ Ἰουδαίων ἀνδρῶν παντὸς τοῦ ἔθνους ὁποίποτε ἀξιολόγων· πολλοὶ δὲ ἐγένοντο ὡς τοῦ παντὸς ἔθνους κατακεκλημένου καὶ πάντων ἀκροασαμένων τοῦ διατάγματος, εἰς γὰρ θάνατον ἦν ἀνακείμενα τοῖς ἀλογήσασι τῶν ἐπιστολῶν ἐμμαινομένου πᾶσιν τοῦ βασιλέως ὁμοίως τοῖς τε ἀναιτίοις καὶ παρεσχηκόσιν αἰτίαν·"},{"number":175,"text":"συγκλείσας αὐτοὺς πάντας ἐν τῷ ἱπποδρόμῳ τήν τε ἀδελφὴν αὐτοῦ Σαλώμην καὶ τὸν ἄνδρα αὐτῆς Ἀλεξᾶν μεταπέμψας τεθνήξεσθαι μὲν οὐ πόρρω ἔλεγεν ἐπὶ τοσόνδε τῶν ἀλγηδόνων αὐτὸν περιεπουσῶν· καὶ τόδε μὲν οἰστόν τε καὶ πᾶσι φίλον παρατυγχάνειν, τὸ δὲ ὀλοφυρμῶν τε ἄπορον καὶ πένθους ἐνδεᾶ ὁποῖον ἐπὶ βασιλεῖ πράσσοιτο ἂν μάλιστα αὐτῷ λυπηρὸν εἶναι·"},{"number":176,"text":"οὐ γὰρ ἀποσκοποῦν τὴν Ἰουδαίων διάνοιαν, ὡς εὐκτὸς αὐτοῖς καὶ πάνυ κεχαρισμένος ὁ θάνατος αὐτοῦ διὰ τὸ καὶ ζῶντος ἐπὶ ἀποστάσει ἐπείγεσθαι καὶ ὕβρει τῶν ὑπʼ αὐτοῦ προτιθεμένων·"},{"number":177,"text":"ἔργον δʼ ἄρα ἐκείνων εἶναι κούφισίν τινα αὐτῷ ψηφίσασθαι τοῦ ἐπὶ τοιοῖσδε ἀλγεινοῦ· τὰ αὐτὰ γὰρ δὴ φρονῆσαι δόξῃ τῇ αὐτοῦ μὴ ἀπειπαμένων μέγαν τε αὐτοῦ τὸν ἐπιτάφιον γενέσθαι καὶ ὁποῖος οὐδʼ ἄλλοις βασιλέων καὶ πένθος διὰ τοῦ ἔθνους ἅπαντος ἐκ ψυχῆς ὀλοφυραμένων ἐπὶ παιδιᾷ καὶ γέλωτι αὐτοῦ."},{"number":178,"text":"ἐπὰν οὖν θεάσωνται τὴν ψυχὴν ἀφέντα αὐτόν, περιστήσαντας τῷ ἱπποδρόμῳ τὸ στρατιωτικὸν ἀγνοοῦν ἔτι τὸν θάνατον αὐτοῦ, μὴ γὰρ πρότερον εἰς τοὺς πολλοὺς ἐξενεγκεῖν ἢ τάδε πρᾶξαι κελεύειν, ἀκοντίσαι τοὺς ἐγκαθειργμένους, καὶ πάντας τοῦτον ἀνελόντας τὸν τρόπον διχόθεν αὐτὸν οὐχ ἁμαρτήσαντας τοῦ εὐφρανοῦντος, κυρώσει τε ὧν ἐπιστείλειεν αὐτοῖς μέλλων τελευτᾶν καὶ τῷ πένθει ἀξιολόγῳ τετιμῆσθαι."},{"number":179,"text":"καὶ ὁ μὲν μετὰ δακρύων ποτνιώμενος καὶ τοῦ συγγενοῦς τὴν εὔνοιαν καὶ πίστιν τοῦ θείου προσκαλῶν ἐπέσκηπτε μὴ ἠτιμῶσθαι ἀξιῶν, κἀκεῖνοι ὡμολόγουν οὐ παραβήσεσθαι."},{"number":180,"text":"Κατανοήσειεν δʼ ἄν τις τὴν διάνοιαν τοῦ ἀνθρώπου καὶ ὅτῳ τὰ πρότερα ἤρεσκεν ὡς ὑπὸ τοῦ φιλοζωεῖν πράξειε τὰ εἰς τοὺς συγγενεῖς πεπραγμένα, ἐκ γοῦν τῶν ἄρτι ἐπιστολῶν οὐδὲν ἀνθρώπειον εἰσφερομένην,"},{"number":181,"text":"εἴγε καὶ ἀπιὼν τοῦ βίου πρόνοιαν εἶχεν, ὡς ἐν πένθει καὶ ἐρημίᾳ τῶν φιλτάτων τὸ πᾶν καταστήσειεν ἔθνος, ἕνα ἀπὸ ἑκάστου οἴκου κελεύων μεταχειρίσαι μηδὲν ἄδικον μήτε εἰς αὐτὸν δεδρακότας μήτε ἐφʼ ἑτέροις ἐγκλήμασιν κατηγορίας αὐτῶν γενομένης, εἰωθότων οἷς προσποίησις ἀρετῆς καὶ πρὸς τοὺς δίκῃ ἐχθροὺς γεγονότας ἐν τοιοῖσδε καιροῖς τὰ μίση κατατίθεσθαι."}],"7":[{"number":182,"text":"Ταῦτα δὲ ἐπιστέλλοντος αὐτοῦ πρὸς τοὺς συγγενεῖς γράμματα παρῆν ὑπὸ τῶν εἰς Ῥώμην πρέσβεων ἀπεσταλμένων πρὸς Καίσαρα. καὶ ἀναγνωσθέντων τὸ κεφάλαιον ἦν, ὡς τῆς τε Ἀκμῆς ὀργῇ τῇ Καίσαρος ἀνῃρημένης ἐφʼ οἷς Ἀντιπάτρῳ συγκακουργήσειεν, αὐτόν τε Ἀντίπατρον ὡς ἐπὶ γνώμῃ τῇ ἐκείνου ποιοῖτο ὡς πατρὸς καὶ βασιλέως, εἴτε φυγάδα ἐλαύνειν ἐθελήσειεν, εἴτε καὶ κτιννύειν."},{"number":183,"text":"τούτων ἀκροώμενος Ἡρώδης βραχὺ μὲν ἀνήνεγκεν ἡδονῇ τῶν γεγραμμένων θανάτῳ τε τῆς Ἀκμῆς ἐπαιρόμενος καὶ ἐξουσίᾳ τῆς ἐπὶ τῷ παιδὶ τιμωρίας, περιουσῶν δὲ εἰς μέγα τῶν ἀλγηδόνων παρίετο τεταλαιπωρημένος σιτίων· καὶ ᾔτησε μῆλον καὶ μαχαίριον· ἦν γὰρ ἐν ἔθει καὶ πρότερον αὐτῷ περιλέψαντι αὐτὸ διʼ αὐτοῦ καὶ κατʼ ὀλίγον τεμόντι ἐσθίειν."},{"number":184,"text":"λαβὼν δὲ καὶ περισκεψάμενος γνώμην εἶχεν παίσων ἑαυτόν, κἂν ἐπεπράχει μὴ φθάσαντος αὐτοῦ καταλαβεῖν τὴν δεξιὰν Ἀχιάβου· ἀνεψιὸς ἦν αὐτοῦ. καὶ μέγα ἀνακραγόντος οἰμωγή τε αὖθις ἀνὰ τὸ βασίλειον ἦν καὶ θόρυβος μέγας ὡς οἰχομένου τοῦ βασιλέως."},{"number":185,"text":"καὶ ὁ Ἀντίπατρος, πιστεύει γὰρ τέλος ἀληθῶς τὸν πατέρα ἔχειν, θάρσει τε ἐχρῆτο ἐπὶ τοῖς λόγοις ὅλος ὡς ἤδη τῶν δεσμῶν ἀφησόμενος καὶ τὴν βασιλείαν ἀκονιτὶ δεξόμενος εἰς χεῖρας, καὶ τῷ εἱρκτοφύλακι περὶ ἀφέσεως ἦν αὐτοῦ διάλογος μεγάλα ὑπισχνουμένου εἰς τὸ παρὸν καὶ ταὖθις, ὡς ἂν περὶ τοιῶνδε τοῦ ἀγῶνος ἐνεστηκότος."},{"number":186,"text":"ὁ δὲ οὐ μόνον ἀπειθὴς ἦν πράσσειν ἐφʼ οἷς ἠξίου Ἀντίπατρος, ἀλλὰ καὶ τῷ βασιλεῖ ἀποσημαίνει διάνοιαν τὴν ἐκείνου πολλῇ καὶ προσεισφορᾷ παρʼ αὑτοῦ χρώμενος."},{"number":187,"text":"ὁ δὲ Ἡρώδης καὶ πρότερον οὐχ ἡσσώμενος οὐδʼ εὐνοίᾳ τοῦ υἱέος ἐπεὶ ἤκουσε τοῦ εἱρκτοφύλακος ταῦτα εἰρηκότος, ἀνεβόησέν τε ἀνατυψάμενος τὴν κεφαλὴν καίπερ ἐν τῷ ὑστάτῳ ὢν καὶ ἐπὶ τὸν ἀγκῶνα περιάρας ἑαυτὸν κελεύει πέμψας τινὰ τῶν δορυφόρων μηδὲν εἰς ἀναβολὰς ἀλλʼ ἐκ τοῦ ὀξέος κτείνασιν αὐτὸν ἐν Ὑρκανίᾳ ταφὰς ἀσήμους ποιεῖσθαι."}],"8":[{"number":188,"text":"Τὰς δὲ διαθήκας αὖθις μετέγραφεν μεταβολῆς αὐτῷ περὶ τὴν διάνοιαν γενομένης, Ἀντίπαν μέν, ᾧ τὴν βασιλείαν καταλελοίπει, τετράρχην καθιστὰς Γαλιλαίας τε καὶ Περαίας, Ἀρχελάῳ δὲ τὴν βασιλείαν χαριζόμενος,"},{"number":189,"text":"τὴν δὲ Γαυλωνῖτιν καὶ Τραχωνῖτιν καὶ Βαταναίαν καὶ Πανιάδα Φιλίππῳ παιδὶ μὲν τῷ αὐτοῦ Ἀρχελάου δὲ ἀδελφῷ γνησίῳ τετραρχίαν εἶναι, Ἰάμνειαν δὲ καὶ Ἄζωτον καὶ Φασαηλίδα Σαλώμῃ τῇ ἀδελφῇ κατανέμει καὶ ἀργυρίου ἐπισήμου μυριάδας πεντήκοντα."},{"number":190,"text":"προυνόησε δὲ καὶ τῶν λοιπῶν, ὁπόσοι συγγενεῖς ἦσαν αὐτῷ, χρημάτων τε δόσεσι καὶ προσόδων ἀναφοραῖς ἑκάστους ἐν εὐπορίᾳ καθιστάμενος. Καίσαρι δὲ ἀργυρίου μὲν ἐπισήμου μυριάδας χιλίας, χωρὶς δὲ σκεύη τὰ μὲν χρυσοῦ τὰ δʼ ἀργύρου καὶ ἐσθῆτα πάνυ πολλοῦ τέλους, Ἰουλίᾳ δὲ τῇ Καίσαρος γυναικὶ καί τισιν ἑτέροις πεντακοσίας μυριάδας."},{"number":191,"text":"ταῦτα πράξας ἡμέρᾳ πέμπτῃ μεθʼ ὃ Ἀντίπατρον κτείνει τὸν υἱὸν τελευτᾷ, βασιλεύσας μεθʼ ὃ μὲν ἀνεῖλεν Ἀντίγονον ἔτη τέσσαρα καὶ τριάκοντα, μεθʼ ὃ δὲ ὑπὸ Ῥωμαίων ἀπεδέδεικτο ἑπτὰ καὶ τριάκοντα, ἀνὴρ ὠμὸς εἰς πάντας ὁμοίως καὶ ὀργῆς μὲν ἥσσων κρείσσων δὲ τοῦ δικαίου, τύχῃ δὲ εἰ καί τις ἕτερος κεχρημένος εὐμενεῖ."},{"number":192,"text":"ἔκ τε γὰρ ἰδιώτου βασιλεὺς καταστὰς καὶ κινδύνοις περιστοιχιζόμενος μυρίοις πάντων ποιεῖται διάδρασιν καὶ τοῦ ζῆν ἐπὶ μήκιστον ἐξίκετο. ὁπόσα δὲ τὰ κατʼ οἶκον περὶ υἱεῖς τοὺς αὐτοῦ, ὅσα μὲν γνώμῃ τῇ ἐκείνου καὶ πάνυ δεξιᾷ κεχρημένος διὰ τὸ κρίνας ἐχθροὺς κρατεῖν οὐχ ὑστερῆσαι, δοκεῖν δʼ ἐμοὶ καὶ πάνυ δυστυχής."},{"number":193,"text":"Σαλώμη δὲ καὶ Ἀλεξᾶς πρὶν ἔκπυστον γενέσθαι τὸν θάνατον τοῦ βασιλέως τοὺς ἐπὶ τὸν ἱππόδρομον κατακεκλημένους ἐκπέμπονται ἐπὶ τὰ αὐτῶν, φάμενοι βασιλέα κελεύειν ἀπιοῦσιν αὐτοῖς ἐπὶ τοὺς ἀγροὺς νέμεσθαι τὰ οἰκεῖα, πράσσεταί τε αὐτοῖς ἥδε εὐεργεσία μεγίστη εἰς τὸ ἔθνος."},{"number":194,"text":"ἐφανεροῦτο δʼ ἤδη ὁ θάνατος τοῦ βασιλέως, καὶ Σαλώμη καὶ Ἀλεξᾶς συναγαγόντες τὸ στρατιωτικὸν εἰς τὸ ἀμφιθέατρον τὸ ἐν Ἱεριχοῦντι πρῶτον μὲν ἐπιστολὴν ἀνέγνωσαν πρὸς τοὺς στρατιώτας γεγραμμένην ἐπὶ πίστεως εὐχαριστίᾳ καὶ εὐνοίας τῆς εἰς αὐτὸν καὶ παρακλήσει τῶν ὁμοίων παροκωχῆς Ἀρχελάῳ τῷ παιδὶ αὐτοῦ, ὃν βασιλέα καθίσταιτο."},{"number":195,"text":"εἶτα μέντοι Πτολεμαῖος τὸν σημαντῆρα τοῦ βασιλέως πεπιστευμένος τὰς διαθήκας ἀνέλεγεν, αἳ λήψεσθαι κύρωσιν οὐκ ἄλλως ἔμελλον ἢ Καίσαρος ἐντυχόντος αὐταῖς. βοὴ οὖν εὐθὺς ἦν ἐκτιμώντων Ἀρχέλαον βασιλέα, καὶ οἱ στρατιῶται κατὰ στίφη τε αὐτοὶ καὶ οἱ ἡγεμόνες εὔνοιάν τε ὑπισχνοῦνται καὶ προθυμίαν τὴν αὐτῶν καὶ συλλήπτορα τὸν θεὸν παρεκάλουν."},{"number":196,"text":"Ἐντεῦθεν δὲ τάφον ἡτοίμαζον τῷ βασιλεῖ μελῆσαν Ἀρχελάῳ πολυτελεστάτην γενέσθαι τὴν ἐκκομιδὴν τοῦ πατρὸς καὶ πάντα τὸν κόσμον προκομίσαντος εἰς ὃ συμπομπεύσειε τῷ νεκρῷ."},{"number":197,"text":"ἐφέρετο δὲ ἐπὶ κλίνης χρυσέας λίθοις πολυτελέσιν καὶ ποικίλοις διαπεπασμένης, στρωμνή τε ἦν ἁλουργὴς καὶ ἠμπέσχετο πορφυρίσιν ὁ νεκρὸς διαδήματι ἠσκημένος ὑπερκειμένου στεφάνου χρυσέου σκῆπτρόν τε τῇ δεξιᾷ παρακείμενον."},{"number":198,"text":"περί τε τὴν κλίνην οἵ τε υἱεῖς καὶ τὸ πλῆθος ἦν τῶν συγγενῶν, ἐπὶ δὲ τούτοις τὸ στρατιωτικὸν κατὰ οἰκεῖα ἔθνη ἢ προσηγορίας διέκειντο αὐτοῖς νεμηθέντες, πρῶτοι μὲν οἱ δορυφόροι, μετὰ δὲ τὸ Θρᾴκιον, ἐπὶ δὲ τούτοις ὁπόσοι Γερμανῶν, καὶ τὸ Γαλατικὸν μετʼ αὐτούς, ἐν τῷ κόσμῳ πάντες τῷ πολεμιστηρίῳ."},{"number":199,"text":"τούτων δὲ κατόπιν ἤδη πᾶς ὁ στρατὸς ὥσπερ ἐς πόλεμον ἐξοδεύοντες ὥσπερ ὑπὸ λοχαγῶν ἀγόμενοι καὶ τοῖς ταξιαρχοῦσιν αὐτῶν. τούτοις ἐπετετάχατο πεντακόσιοι τῶν οἰκετῶν ἀρωματοφόροι. ᾔεσαν δὲ ἐπὶ Ἡρωδίου στάδια ὀκτώ· τῇδε γὰρ αὐτῷ ἐγένοντο αἱ ταφαὶ κελεύσματι τῷ αὐτοῦ. Ἡρώδης μὲν δὴ τοῦτον ἐτελεύτα τὸν τρόπον."},{"number":200,"text":"Ἀρχέλαος δὲ ἐπὶ μὲν ἑβδόμην ἡμέραν πένθος τὸ ἐπὶ τῷ πατρὶ τιμῶν διετέλει· τόσας γὰρ διαγορεύει τὸ νόμιμον τοῦ πατρίου. ἑστιάσας δὲ τοὺς ὁμίλους καὶ καταλύσας τὸ πένθος ἄνεισιν εἰς τὸ ἱερόν. ἦσάν τε εὐφημίαι καὶ ἔπαινοι καθʼ οὕστινας ἴοι ἑκάστων τὰ πρὸς ἀλλήλους φιλοτιμουμένων εἰς τὸ δοκεῖν μείζοσι χρῆσθαι ταῖς εὐφημίαις."},{"number":201,"text":"ὁ δὲ ἐπὶ ὑψηλὸν βῆμα πεποιημένον ἀνελθὼν καὶ ἱδρυθεὶς εἰς θρόνον χρυσοῦν πεποιημένον ἀντεδεξιοῦτο τοὺς ὁμίλους χάρματι τῶν εὐφημιῶν τὴν εὔνοιαν αὐτῶν ἡδονῇ φέρων, χάριν τε ὡμολόγει, διότι μηδὲν αὐτῷ μνησικακοῖεν ἀνθʼ ὧν ὁ πατὴρ εἰς αὐτοὺς ὑβρίσειεν καὶ πειράσεσθαι μὴ ἐλλείψειν ἀμειβόμενον τὸ πρόθυμον αὐτῶν."},{"number":202,"text":"ἄρτι μέντοι φειδὼ ποιεῖσθαι τοῦ βασιλείου ὀνόματος, τετιμῆσθαι γὰρ αὐτὸν τῇ ἀξιώσει ὅπερ βεβαίως Καῖσαρ ἐπικυρώσειε τὰς διαθήκας, αἳ ὑπὸ τοῦ πατρὸς ἐγράφησαν αὐτοῦ· διʼ ἣν αἰτίαν οὐδὲ τοῦ στρατεύματος ἐν Ἱεριχοῦντι τὸ διάδημα αὐτῷ περιθέσθαι προθυμουμένου δέξασθαι τὸ περιμάχητον τῆς ἐνθένδε τιμῆς διὰ τὸ μηδέπω τὸν κυρίως ἀποδώσοντα φανερὸν εἶναι παρασχόμενον."},{"number":203,"text":"περιιόντων μέν γε εἰς αὐτὸν τῶν πραγμάτων οὐ λείψειν ἀρετῆς τοῦ ἀμειψομένου τὴν εὔνοιαν αὐτῶν· σπουδάσειν γὰρ ἐν πᾶσιν τὰ πρὸς αὐτοὺς φανεῖσθαι τοῦ πατρὸς ἀμείνων τὰ πάντα."},{"number":204,"text":"οἱ δὲ οἷον ὄχλος εἴωθεν, φιλεῖν οἰόμενοι τὰς πρώτας εἶναι τῶν ἡμερῶν τὰς διανοίας ἐμφανίζειν τῶν παριόντων ἐπὶ τοιάσδε ἀρχάς, ὅσῳ πρᾴως καὶ θεραπευτικῶς ὁ Ἀρχέλαος διελέγετο αὐτοῖς, τοσῷδε μειζόνως τε ἐχρῶντο τοῖς ἐπαίνοις καὶ κατὰ αἰτήσεις δωρεῶν ἐτετράφατο, οἱ μὲν εἰσφορὰς ἃς ἐνιαυσίους φέροιεν ἐπικουφίζειν βοῇ χρώμενοι, οἱ δὲ αὖ δεσμωτῶν, οἳ ὑφʼ Ἡρώδου ἐδέδεντο, πολλοὶ δὲ ἦσαν κἀκ πολλῶν χρόνων, ἀπόλυσιν."},{"number":205,"text":"εἰσὶν δὲ οἳ ἄρσεις τῶν τελῶν ἃ ἐπὶ πράσεσιν ἢ ὠναῖς ἐπεβάλλετο πρασσόμενα πικρῶς ᾐτοῦντο. ἀντέλεγέν τε οὐδαμῶς Ἀρχέλαος ἐπειρᾶτο ὁμίλους σπουδαῖος ὢν ποιεῖν πάντα διὰ τὸ νομίζειν μέγα πρᾶγμα εἰς τήρησιν τῆς ἀρχῆς γενήσεσθαι τὴν εὔνοιαν αὐτῷ τῆς πληθύος. ἐντεῦθεν δὲ θύσας τῷ θεῷ κατʼ εὐωχίαν τρέπεται μετὰ τῶν φίλων."}],"9":[{"number":206,"text":"Ἐν τούτῳ δέ τινες τῶν Ἰουδαίων συνελθόντες νεωτέρων ἐπιθυμίᾳ πραγμάτων Ματθίαν καὶ τοὺς σὺν αὐτῷ ὑφʼ Ἡρώδου ἀποθανόντας, οἳ παραχρῆμα τῆς εἰς τὸ πενθεῖσθαι τιμῆς φόβῳ τῷ ἐκείνου ἀπεστέρηντο, ἦσαν δὲ οἱ τῶν ἐπὶ καθαιρέσει τοῦ χρυσοῦ ἀετοῦ δεδικαιωμένων, ἐπὶ μέγα τε τῇ βοῇ καὶ οἰμωγῇ χρώμενοι καί τινα ὡς κούφισιν φέροντα τοῖς τεθνεῶσιν ἀπερρίπτουν εἰς τὸν βασιλέα."},{"number":207,"text":"συνόδου τε αὐτοῖς γενομένης ἠξίουν τιμωρίαν αὐτοῖς ὑπʼ Ἀρχελάου γενέσθαι κολάσεσιν τῶν ὑπὸ Ἡρώδου τιμωμένων, καὶ πάντων γε καὶ πρῶτον καὶ ἐκδηλότατα τὸν ὑπʼ αὐτοῦ ἀρχιερέα καθεστῶτα παύσαντα νομιμώτερόν τε ἅμα καὶ καθαρὸν ἀρχιερᾶσθαι ἄνδρα αἱρεῖσθαι."},{"number":208,"text":"τούτοις Ἀρχέλαος καίπερ δεινῶς φέρων ἐπένευεν τὴν ὁρμὴν αὐτῶν διὰ τὴν ἐπὶ Ῥώμης ὁδὸν ἀνύεσθαι προκείμενον αὐτῷ τάχος ἐπὶ περισκοπήσει τῶν δοξάντων Καίσαρι."},{"number":209,"text":"πέμψας δὲ τὸν στρατηγὸν πειθοῖ χρῆσθαι, καὶ τῆς ἐπὶ τοιούτοις μωρίας ἀποστάντας σκοπεῖν, θάνατόν τε, ὃς τοῖς φίλοις αὐτῶν συνέλθοι, μετὰ νόμων γεγονότα, καὶ τὰς αἰτήσεις ὡς ἐπὶ μέγα τοῦ ὑβρίζειν προΐοιεν, τούς τε καιροὺς οὐκ ἐν τοιοῖσδε εἶναι, μᾶλλον δὲ τοῦ ὁμονοεῖν ἕως καταστησάμενος τὴν ἀρχὴν ἐπινεύσει τῇ Καίσαρος ἀφίκοιτο ὡς αὐτούς· τότε γὰρ κοινῇ βουλεύσειν περὶ ὧν ἀξιοῖεν σὺν αὐτοῖς· ἄρτι δὲ ἀνέχειν, μὴ καὶ στασιάζειν δοκοῖεν."},{"number":210,"text":"Καὶ ὁ μὲν ταῦτα ὑπειπὼν καὶ διδάξας τὸν στρατηγὸν ἐκπέμπει πρὸς αὐτούς. οἱ δὲ βοῶντες λέγειν τε οὐκ εἴων καὶ εἰς κίνδυνον τοῦ ἀπολουμένου ἐκεῖνόν τε καθίστασαν καὶ τῶν ἄλλων ὅστις γε ἐπὶ σωφρονισμῷ καὶ ἀποτροπῇ τοῦ μὴ τοιῶνδε ὀριγνᾶσθαι τολμήσειν φθέγξασθαι φανερὸς ἦν διὰ τὸ πάντα βουλήσει τῇ αὐτῶν μᾶλλον ἢ ἐξουσίᾳ τῶν ἐφεστηκότων συγχωρεῖν,"},{"number":211,"text":"δεινὸν ἡγούμενοι, εἰ ζῶντός τε Ἡρώδου στερηθεῖεν τῶν φιλτάτων καὶ τελευτῆς αὐτῷ γενομένης τιμωριῶν τῶν ἐπʼ αὐτοῖς, ὠργηκότες ταῖς γνώμαις καὶ νόμιμόν τε καὶ δίκαιον ἡγούμενοι ὅ τι μελλήσοι ἡδονὴν αὐτοῖς φέρειν, κίνδυνον δὲ τὸν ἀπʼ αὐτοῦ προϊδέσθαι τε ἀμαθεῖς καὶ εἴ τῳ ὑποπτευθείη, ὑπερβολῆς αὐτῷ γενομένης τῆς παραχρῆμα ἡδονῆς ἐκ τοῦ τιμωρήσασθαι τοὺς ἐχθίστους δοκοῦντας αὐτοῖς."},{"number":212,"text":"πολλῶν δὲ ὑπὸ Ἀρχελάου πεμπομένων, οἳ διαλέξοιντο αὐτοῖς, τῶν τε ἐνεστώτων μὲν ὑπʼ ἐκείνου γνώμῃ δὲ τῇ αὐτῶν δοκεῖν παριόντων, ὅπως εἰς τὸ πραΰτερον καταστήσονται αὐτούς, οὐδενὸς ἠνείχοντο εἰπεῖν ἀνάστασίς τε ἦν δεύειν ὀργῇ χρωμένων, φανεροί τε ἦσαν ἐπὶ μέγα αὐξήσοντες τὴν στάσιν πλήθους ἐπισυρρυέντος αὐτοῖς."},{"number":213,"text":"Ἐνστάσης δὲ κατὰ τόνδε τὸν καιρὸν ἑορτῆς, ἐν ᾗ Ἰουδαίοις ἄζυμα προτίθεσθαι πάτριον· φάσκα δʼ ἡ ἑορτὴ καλεῖται ὑπόμνημα οὖσα τῆς ἐξ Αἰγύπτου ἀπάρσεως αὐτῶν γενομένης, καὶ θύουσιν αὐτὴν προθύμως πλῆθός τε ἱερείων ὡς οὐκ ἐν ἄλλῃ κατακόπτειν ἐστὶν αὐτοῖς νόμιμον·"},{"number":214,"text":"κάτεισιν δὲ πληθὺς ἀναρίθμητος ἐκ τῆς χώρας ἤδη δὲ καὶ ἐκ τῆς ὑπερορίας ἐπὶ θρησκείᾳ τοῦ θεοῦ, καὶ οἱ νεωτερισταὶ τοὺς περὶ τὸν Ἰούδαν τε καὶ Ματθίαν ἐξηγητὰς τῶν νόμων ὀδυρόμενοι συστάντες ἐν τῷ ἱερῷ τροφῆς ηὐποροῦντο τοῖς στασιασταῖς οὐκ ὂν ἐν αἰσχύνῃ μεταιτεῖν αὐτούς."},{"number":215,"text":"καὶ δείσας Ἀρχέλαος, μὴ καί τι δεινὸν βλαστήσειεν αὐτῶν τῇ ἀπονοίᾳ, πέμπει σπεῖράν τε ὁπλιτῶν χιλίαρχόν τε τὴν ὁρμὴν τῶν ἐνεστηκότων πρότερον τὸν πάντα ὅμιλον τοῦ μανιώδους αὐτῶν πλέω καταστῆναι, καὶ εἴ τινες διάδηλοι πολὺ τῶν ἄλλων καθίσταιντο προθυμίᾳ τοῦ στασιάζειν ἐπʼ αὐτὸν ἀγαγεῖν."},{"number":216,"text":"ἐπὶ τούτῳ οἱ στασιῶται τῶν ἐξηγητῶν καὶ τὸ πλῆθος ἐξηγρίωσε βοῇ καὶ διακελευσμῷ χρώμενοι ὥρμησάν τε ἐπὶ τοὺς στρατιώτας καὶ περιστάντες λεύουσιν τοὺς πλείστους αὐτῶν. ὀλίγοι δέ τινες καὶ ὁ χιλίαρχος τραυματίαι διέφυγον. καὶ τοῖς μὲν ταῦτα πράξασιν διὰ χειρῶν αὖθις ἡ θυσία ἦν·"},{"number":217,"text":"Ἀρχελάῳ δὲ ἄπορον ἐδόκει σώζεσθαι τὰ πάντα μὴ οὐκ ἀνακόψειν τὴν ἐπὶ τοιοῖσδε ὁρμὴν τῆς πληθύος, ἐκπέμπει δὲ πᾶν τὸ στρατόπεδον οἳ τούς τε αὐτόθι ἐσκηνωκότας κωλύοιεν τοῖς κατὰ τὸ ἱερὸν βοηθεῖν καὶ τοὺς ἐκπίπτοντας ὑπὸ τῶν πεζῶν δέχοιντο ἀντειλῆφθαι τἀσφαλοῦς ἤδη πεπιστευκότας."},{"number":218,"text":"καὶ εἰς μὲν τρισχιλίους ἄνδρας ἔκτειναν οἱ ἱππεῖς· τὸ δὲ λοιπὸν ᾤχετο ἐπὶ ὄρη τὰ πλησίον ἰόντες. ἐκήρυσσε δʼ Ἀρχέλαος ἀναχωρεῖν ἐπὶ τὰ αὑτῶν πᾶσιν. οἱ δὲ ἀπῄεσαν τὴν ἑορτὴν καταλιπόντες φόβῳ κακοῦ μείζονος καίπερ θρασεῖς ὄντες διὰ τὸ ἀπαίδευτον."},{"number":219,"text":"Ἀρχέλαος δʼ ἐπὶ θαλάσσης κατῄει μετὰ τῆς μητρὸς Νικόλαον καὶ Πτολεμαῖον καὶ Πτόλλαν τῶν φίλων ἐπαγόμενος, Φιλίππῳ τἀδελφῷ τὰ πάντα ἐφεὶς καθίστασθαι τοῦ οἴκου καὶ τῆς ἀρχῆς."},{"number":220,"text":"συνεξῄει δʼ αὐτῷ καὶ Σαλώμη ἡ Ἡρώδου ἀδελφὴ γενεὰν ἀγομένη τὴν αὐτῆς, πολλοί τε τῶν συγγενῶν, λόγῳ μὲν ὡς συναγωνιούμενοι τῷ Ἀρχελάῳ ἐπὶ κτήσει τῆς βασιλείας, ἔργῳ δὲ ἀντιπράξοντες καὶ μάλιστα περὶ τῶν πεπραγμένων ἐν τῷ ἱερῷ ποιησόμενοι καταβοάς."},{"number":221,"text":"ὑπαντιάζει δʼ ἐν Καισαρείᾳ τὸν Ἀρχέλαον Σαβῖνος Καίσαρος ἐπίτροπος τῶν ἐν Συρίᾳ πραγμάτων εἰς Ἰουδαίαν ὡρμημένος ἐπὶ φυλακῇ τῶν Ἡρώδου χρημάτων. καὶ αὐτὸν τῆς ἐπὶ τοῖσδε ὁρμῆς ἔσχεν ὁ Οὔαρος παρελθών· διὰ γὰρ Πτολεμαίου μετάπεμπτος ὑπʼ Ἀρχελάου παρῆν."},{"number":222,"text":"καὶ Οὐάρῳ Σαβῖνος χαριζόμενος οὔτε τὰς ἄκρας, ὅσαι ἐν τοῖς Ἰουδαίοις ἦσαν, παρέλαβεν οὔτε τοὺς θησαυροὺς κατεσημήνατο, εἴα δʼ ἔχειν Ἀρχέλαον μέχρι Καίσαρι δόξειέν τι περὶ αὐτῶν, καὶ ἔμενεν ἐν τῇ Καισαρείᾳ τοῦθʼ ὑποσχόμενος. ἐπεὶ δʼ ἐκπλεῖ μὲν ἐπὶ τῆς Ῥώμης Ἀρχέλαος, Οὐάρῳ δʼ ἐπʼ Ἀντιοχείας ἐγένοντο κομιδαί, Σαβῖνος ἐπὶ Ἱεροσολύμων χωρήσας παραλαμβάνει τὰ βασίλεια."},{"number":223,"text":"μεταπέμψας δὲ τοὺς φρουράρχους καὶ ὁπόσοι διοικηταὶ τῶν πραγμάτων ἦσαν λόγους τε ἀπαιτεῖν πρόδηλος ἦν καὶ τὰς ἄκρας καθίστατο ᾗ αὐτῷ δοκοῖ. οὐ μὴν οἱ φύλακες ἐν ὀλίγῳ τὰς Ἀρχελάου ἐπιστολὰς ἐποιοῦντο, ἀλλʼ ἔμενον σώζοντες τὰ πάντα ᾗ προσετέτακτο αὐτοῖς. Καίσαρι δὲ φυλάσσειν ἕκαστʼ ἦν προσποίησις αὐτοῖς."},{"number":224,"text":"Πλεῖ δὲ κατὰ τοῦτον τὸν καιρὸν ἐπὶ Ῥώμης καὶ Ἀντίπας Ἡρώδου μὲν παῖς, ἐπὶ δʼ ἀντιποιήσει τῆς ἀρχῆς ὑποσχέσεσι Σαλώμης ἠρμένος ἐπὶ τῷ ἄρχειν καὶ πολὺ δικαιότερον Ἀρχελάου παραλήψεσθαι τὰ πράγματα ἠξιωκὼς τῷ κατὰ τὰς προτέρας διαθήκας βασιλεὺς ἀποπεφάνθαι, ἃς ἀσφαλεστέρας εἶναι τῶν ἐπιγραφεισῶν."},{"number":225,"text":"ἐπήγετο δὲ οὗτος τήν τε μητέρα καὶ τὸν ἀδελφὸν τὸν Νικολάου Πτολεμαῖον φίλον τε Ἡρώδῃ τιμιώτατον γεγενημένον καὶ αὐτῷ προσκείμενον."},{"number":226,"text":"μάλιστα δὲ αὐτὸν ἐνῆγεν ἐπʼ ἀντιποιήσει τῆς βασιλείας φρονεῖν Εἰρηναῖος ῥήτωρ ἀνὴρ καὶ δόξῃ δεινότητος τῆς περὶ αὐτῷ τὴν βασιλείαν πεπιστευμένος. διὸ δὴ καὶ τῶν κελευόντων εἴκειν Ἀρχελάῳ πρεσβυτέρῳ τε ὄντι κἀν ταῖς ἐπιδιαθήκαις ὑπὸ τοῦ πατρὸς ἐγγεγραμμένῳ βασιλεῖ οὐκ ἠνείχετο."},{"number":227,"text":"ἐπεὶ δʼ εἰς τὴν Ῥώμην ἀφίκετο, καὶ πάντων τῶν συγγενῶν ἀπόστασις ἦν πρὸς αὐτόν, οὐκ εὐνοίᾳ τῇ ἐκείνου, μίσει δὲ τῷ πρὸς Ἀρχέλαον, μάλιστα μὲν ἐπιθυμοῦντες ἐλευθερίας καὶ ὑπὸ Ῥωμαίων στρατηγῷ τετάχθαι, εἰ δʼ ἄρα τι ἀντισταίη, λυσιτελέστερον Ἀρχελάου τὸν Ἀντίπαν λογιζόμενοι, συνέπραττον Ἀντίπᾳ τὴν βασιλείαν. καὶ Σαβῖνος κατηγόρει παρὰ Καίσαρι τοῦ Ἀρχελάου διὰ γραμμάτων."},{"number":228,"text":"Καῖσαρ δὲ Ἀρχελάου τε εἰσπέμψαντος ὡς αὐτὸν γράμματα, ἐν οἷς τὰ δικαιώματα προετίθει τε αὐτοῦ καὶ τὴν διαθήκην τοῦ πατρὸς καὶ τοὺς λογισμοὺς τῶν Ἡρώδου χρημάτων σὺν τῷ σημαντῆρι κομίζοντα Πτολεμαῖον, ἐκαραδόκει τὸ μέλλον."},{"number":229,"text":"ὁ δὲ ταῦτά τε ἀναγνοὺς τὰ γράμματα καὶ τὰς Οὐάρου καὶ Σαβίνου ἐπιστολὰς ὁπόσα τε χρήματα ἦν καὶ τί ἐπʼ ἔτος ἐφοίτα καὶ ὅσα Ἀντίπας ἐπʼ οἰκειώσει τῆς βασιλείας ἐπεπόμφει γράμματα συνῆγεν ἐπὶ παροκωχῇ γνωμῶν τοὺς φίλους, σὺν οἷς καὶ Γάιον τὸν Ἀγρίππου μὲν καὶ Ἰουλίας τῆς αὐτοῦ θυγατρὸς υἱὸν ποιητὸν δὲ αὐτῷ γεγονότα πρῶτόν τε καθεδούμενον παρέλαβε, καὶ κελεύει λέγειν τοῖς βουλομένοις περὶ τῶν ἐνεστηκότων."},{"number":230,"text":"καὶ πρῶτος ὁ Σαλώμης υἱὸς Ἀντίπατρος δεινότατός τε ὢν εἰπεῖν καὶ τῷ Ἀρχελάῳ ἐναντιώτατος ἔλεγεν Ἀρχελάῳ παιδιὰν τὸν περὶ τῆς ἀρχῆς εἶναι λόγον ἔργῳ τὴν δύναμιν αὐτῆς πρότερον ἢ Καίσαρα συγχωρῆσαι παρειληφότι, ἐπικαλῶν τὰ τετολμημένα ἐπὶ τοῖς ἀπολωλόσι κατὰ τὴν ἑορτήν·"},{"number":231,"text":"ὧν καὶ ἀδικούντων ἄλλως ἔσχεν τὴν τιμωρίαν εἰς τοὺς ἔξω χρῆσθαι δυναμένους ἀνακειμένην εἶναι, καὶ μὴ ὑπʼ ἀνδρὸς πεπρᾶχθαι, εἰ μὲν βασιλέως, ἀδικοῦντος τὸ Καίσαρος διαγνοίᾳ περὶ αὐτοῦ ἔτι χρώμενον, εἰ δὲ ἰδιώτου, πολὺ χειρόνως, διὰ τὸ μὴ βασιλείας ἀντιποιουμένῳ καλῶς ἂν συγκεχωρῆσθαι, διὰ τὸ Καίσαρα τῆς ἐπʼ αὐτοῖς ἐξουσίας ἀφαιρεῖσθαι."},{"number":232,"text":"καθήπτετο δὲ αὐτοῦ ἡγεμόνων τινῶν ἐν τῷ στρατιωτικῷ μετάστασιν ἐπικαλῶν καὶ προκάθισιν ἐπὶ θρόνου βασιλείου καὶ δικῶν διάλυσιν ὡς ὑπὸ βασιλέως γενομένην κατανεύσεις τε αἰτήσεων τοῖς δημοσίᾳ αἰτουμένοις καὶ πάντων διάπραξιν, ὧν οὐδὲν ἂν μειζόνως ἐπινοῆσαι καθεσταμένον ὑπὸ τοῦ Καίσαρος εἰς τὴν ἀρχήν."},{"number":233,"text":"ἀνετίθει δὲ αὐτῷ καὶ τῶν ἐκ τοῦ ἱπποδρόμου δεσμωτῶν τὴν ἄφεσιν καὶ πολλὰ τὰ μὲν γεγονότα τὰ δὲ καὶ πιστεύεσθαι δυνάμενα διὰ τὸ φύσιν ἔχειν γίνεσθαι ὑπό τε νεωτέρων καὶ φιλοτιμίᾳ τοῦ ἄρχειν προλαμβανόντων τὴν ἐξουσίαν, πένθους τε τοῦ ἐπὶ τῷ πατρὶ ἀμελείας καὶ κωμασμοὺς αὐτονυκτὶ τῇ ἐκείνου τελευτῇ γεγονότας,"},{"number":234,"text":"ἐφʼ οἷς δὴ καὶ τὴν πληθὺν ἀρχὴν τοῦ στασιάζειν λαβεῖν, εἰ τοιαῦτα εὐεργετήσαντος αὐτὸ τοῦ πατρὸς καὶ οὕτως μεγάλων ἠξιωκότος τοιοῖσδε ἀμείβεσθαι τὸν νέκυν, ὥσπερ ἐπὶ σκηνῆς δακρύειν μὲν προσποιούμενον τὰς ἡμέρας, ἀπολαύοντα δὲ ἡδονῇ τῇ ἐπὶ τῆς ἀρχῆς ὅσαι νύκτες."},{"number":235,"text":"φανεῖσθαί τε καὶ περὶ τὸν Καίσαρα τοιόνδε ὄντα Ἀρχέλαον συγχωροῦντα τὴν βασιλείαν, ὁποῖος γένοιτο καὶ περὶ τὸν πατέρα· χορεύειν γὰρ καὶ ᾄδειν ὥσπερ ἐχθροῦ πεσόντος, ἀλλʼ οὐκ ἀνδρὸς οὕτως μὲν συγγενοῦς, τηλικαῦτα δʼ εὐεργετεῖν ἐξηγμένου."},{"number":236,"text":"δεινότατόν τε πάντων ἀπέφηνε τὸ νῦν ἥκειν ἐπὶ Καίσαρος κατανεύσει τῇ ἐκείνου χρησόμενον τῇ βασιλείᾳ πάντων αὐτῷ προπεποιημένων, ὁπόσα γένοιτο ἂν ὑπὸ σοῦ βεβαίως ἤδη τοῦ αὐτοκράτορος παρεσχηκότος πρασσόμενα."},{"number":237,"text":"μάλιστα δὲ τὴν σφαγὴν τῶν περὶ τὸ ἱερὸν ἐδείνου τῷ λόγῳ καὶ τὴν δυσσέβειαν, ὡς ἑορτῆς τε ἐνεστηκυίας καὶ ἱερείων ἐν τρόπῳ σφαχθεῖεν ἔνιοι μὲν ξένοι οἱ δὲ ἐγχώριοι, πλησθείη δὲ τὸ ἱερὸν νεκρῶν οὐχ ὑπʼ ἀλλοφύλου, ἀλλὰ τοῦ καὶ μετὰ νομίμων ὀνομάτων τῆς βασιλείας ἐφιεμένου τῆς πράξεως, ὅπως δυνηθείη πληρῶσαι τῆς φύσει τυραννίδος τὴν πᾶσιν ἀνθρώποις μεμισημένην ἀδικίαν."},{"number":238,"text":"διʼ ἣν μηδὲ ὄναρ ποτὲ ἑωρᾶσθαι βασιλείας αὐτῷ τὴν διαδοχὴν ἀρετῇ τοῦ πατρός· ἐπίστασθαι γὰρ αὐτοῦ τὸν τρόπον καί τοι ἐχθρὸν αὐτῷ ἐκ τῶν διαθηκῶν ἰσχυρότερον Ἀντιπάτρῳ καθίστασθαι· κληθῆναι γὰρ ὑπὸ τοῦ πατρὸς ἐπὶ τὴν βασιλείαν οὐχὶ νοσοῦντος πρὸς τῷ σώματι καὶ τὴν ψυχήν, ἀλλὰ ἀκραιφνεῖ μὲν τῷ λογισμῷ χρωμένου, ἀλκῇ δὲ σώματος τοῖς πράγμασιν ἐφεστηκότος."},{"number":239,"text":"εἰ δὲ καὶ πρότερον εἰς αὐτὸν ἐπίσης τοῖς νῦν διατεθεῖσθαι τὸν πατέρα, ἀποπεφάνθαι ποταπὸς ἂν γένοιτο βασιλεὺς τὸν μὲν κύριον παρασχεῖν τὴν βασιλείαν Καίσαρα ἀφῃρημένον τοῦ δοῦναι τὴν ἐξουσίαν, τοὺς δὲ πολίτας ἰδιώτην ὄντα ἀκμὴν σφάζειν ἐν ἱερῷ μὴ ἀποτετραμμένον."},{"number":240,"text":"Καὶ Ἀντίπατρος μὲν τοιάδε εἰπὼν καὶ μαρτύρων παραστάσεσιν τὰ εἰρημένα κρατυνάμενος πολλοῖς τῶν συγγενῶν παύεται τοῦ λέγειν. ἀνίσταται δὲ Νικόλαος ὑπὲρ Ἀρχελάου καὶ ἔλεγεν τὰ μὲν ἐν τῷ ἱερῷ γνώμῃ τῶν πεπονθότων ἀναθεὶς μᾶλλον ἢ ἐξουσίᾳ τῇ Ἀρχελάου· τοὺς γὰρ ἐπὶ τοιοῖσδε ἄρχοντας οὐ μόνον τῷ καθʼ αὑτοὺς ὑβρίζοντι εἶναι πονηρούς, ἀλλὰ καὶ τῷ ἀναγκάζοντι εἰς τὴν ἄμυναν τῶν εὐγνωμονεῖν προαιρουμένων."},{"number":241,"text":"ὡς δὲ πολέμια ἔδρων λόγῳ μὲν κατʼ Ἀρχελάου τὸ δὲ ἀληθὲς εἰς Καίσαρα φανερὸν εἶναι· τοὺς γὰρ ὑβριοῦντας κωλυτὰς παραγενομένους ἢ ὑπʼ Ἀρχελάου πεπομφότος κτεῖναι ἐπιθεμένους οὔτε τοῦ θεοῦ οὔτε τοῦ νόμου τῆς ἑορτῆς ἐν φροντίδι γενομένους,"},{"number":242,"text":"ὧν Ἀντίπατρον οὐκ αἰσχύνεσθαι ἐκδικητὴν καθιστάμενον ἐπὶ θεραπείᾳ ἔχθρας τῆς αὐτοῦ πρὸς Ἀρχέλαον ἢ φύσει τοῦ ἀρετῇ δικαίου. οἱ παρελθόντες καὶ μὴ πρὸς διανοουμένους ἄρχοντες ἀδίκων ἔργων, οἵδε εἰσὶν οἱ βιαζόμενοι καὶ μὴ θέλοντας τοὺς ἀμυνομένους ἐφʼ ὅπλα χωρεῖν."},{"number":243,"text":"ἀνετίθει δὲ καὶ τὰ λοιπὰ πᾶσι τοῖς ἐν βουλῇ τῶν κατηγόρων· οὐδὲν γὰρ ὅ τι μὴ οὐ μετὰ γνώμης τῆς αὐτῶν γεγενημένον αἰτίᾳ τοῦ ἀδικεῖν ὑπάγεσθαι, οὐ τῇ φύσει τῇ οὕτως αὐτὰ γεγονότα πονηρὰ εἶναι, ἀλλὰ τῷ βλάψειν ἂν δοκεῖν Ἀρχέλαον. τοσήνδε αὐτοῖς εἶναι βουλὴν τοῦ ὑβριοῦντος εἰς ἄνδρα συγγενῆ, καὶ πατρὸς μὲν εὐεργέτου, συνήθη δὲ αὐτοῖς καὶ διὰ παντὸς οἰκείως πεπολιτευμένον."},{"number":244,"text":"τάς γε μὴν διαθήκας ὑπό τε σωφρονοῦντος γεγράφθαι τοῦ βασιλέως καὶ κυριωτέρας τῶν γεγραμμένων πρότερον διὰ τὸ Καίσαρι δεσπότῃ τῶν ὅλων καταλελεῖφθαι τὴν κρίσιν τῶν ἐν αὐταῖς γεγραμμένων."},{"number":245,"text":"μιμήσεσθαί τε οὐδαμῶς Καίσαρα τὴν ὕβριν αὐτῶν, οἳ τῆς Ἡρώδου παντοίως ἀπολαύσαντες παρʼ ὃν ἔζη καιρὸν δυνάμεως τὰ πάντα ἐπὶ ὕβρει γνώμης ἐπείγοιντο αὐτοῦ, οὐδʼ αὐτῶν περὶ τὸν συγγενῆ τοιούτων γεγονότων."},{"number":246,"text":"οὔκουν Καίσαρά γε ἀνδρὸς ἐπʼ αὐτῷ πεποιημένου τὰ πάντα καὶ φίλου καὶ συμμάχου καταλύσειν τὰς διαθήκας ἐπὶ πίστει τῇ αὐτοῦ γεγραμμένας, οὐδὲ μιμήσεσθαι κακίαν τὴν ἐκείνων τὴν Καίσαρος ἀρετὴν καὶ πίστιν πρὸς ἅπασαν τὴν οἰκουμένην ἀνενδοίαστον γενομένην,"},{"number":247,"text":"καὶ μανίαν καὶ λογισμῶν ἔκστασιν κατακρίνειν ἀνδρὸς βασιλέως, υἱεῖ μὲν ἀγαθῷ τὴν διαδοχὴν καταλελοιπότος, πίστει δὲ τῇ αὐτοῦ προσπεφευγότος· οὔτʼ ἁμαρτάνειν Ἡρώδην ποτὲ περὶ κρίσιν τοῦ διαδόχου σωφροσύνῃ κεχρημένον ἐπὶ τῇ Καίσαρος γνώμῃ τὰ πάντα ποιεῖσθαι."},{"number":248,"text":"Καὶ Νικόλαος μὲν τοιάδε διελθὼν καταπαύει τὸν λόγον· Καῖσαρ δὲ Ἀρχέλαον προσπεσόντα αὐτῷ πρὸς τὰ γόνατα φιλοφρόνως τε ἀνίστη φάμενος ἀξιώτατον εἶναι τῆς βασιλείας πολλήν τε ἀπέφαινε τροπὴν γνώμης τῆς αὐτοῦ οὐκ ἄλλα πράξειν, ἀλλʼ ὁπόσα αἵ τε διαθῆκαι ὑπηγόρευον καὶ Ἀρχελάῳ συνέφερεν."},{"number":249,"text":"οὐ μέντοι γε ἐκεκύρωτο οὐδέν, ὡς ἂν ἐχεγγύῳ παραδείγματι χρώμενον ἐπʼ ἀδείας Ἀρχέλαον εἶναι. καὶ διαλύσεως τῶν ἀνδρῶν γενομένης ἐσκοπεῖτο καθʼ αὑτόν, εἴτε Ἀρχελάῳ τὴν βασιλείαν ἐπικυρωτέον, εἴτε νομὴν αὐτῆς ποιεῖσθαι παντὶ τῷ Ἡρώδου γένει καὶ ταῦτα πάντων πολλῆς ἐπικουρίας δεομένων."}],"10":[{"number":250,"text":"Πρότερον δὲ ἢ κύρωσίν τινα τούτων γενέσθαι Μαλθάκη τε ἡ Ἀρχελάου μήτηρ νόσῳ τελευτᾷ καὶ παρὰ Οὐάρου τοῦ Συρίας στρατηγοῦ παρῆν γράμματα τὴν Ἰουδαίων ἀπόστασιν διασαφοῦντα·"},{"number":251,"text":"τοῦ γὰρ Ἀρχελάου μετὰ τὸν ἔκπλουν ἐθορυβήθη τὸ πᾶν ἔθνος. καὶ Οὔαρος αὐτὸς ἐπεὶ παρὼν ὡς τοὺς αἰτίους τῆς κινήσεως τιμωρίᾳ περιβαλὼν καὶ τοῦ πολλοῦ τῆς στάσεως ἐπίσχεσιν ποιησάμενος πολλῆς γενομένης ἐπʼ Ἀντιοχείας τὴν ἀναζυγὴν ἐποιεῖτο, τάγμα ἓν τῆς στρατιᾶς ἐν Ἱεροσολύμοις λειπόμενος τὴν Ἰουδαίων νεωτεροποιίαν ἐπιστομιοῦντας."},{"number":252,"text":"οὐ μὴν ἐπεραίνετό γε οὐδὲν ἐπὶ παύλῃ τοῦ μὴ οὐ στασιάσοντος αὐτῶν. ὅτε γὰρ Οὔαρος ἀπῄει καὶ Σαβῖνος ὁ ἐπίτροπος τοῦ Καίσαρος ὑπομείνας αὐτόθι μεγάλως τοὺς στασιώτας κατεπόνει, στρατιᾷ τε τῇ καταλελειμμένῃ πιστεύων, ὡς καὶ περιέσοιτο αὐτῶν, καὶ τῷ πλήθει·"},{"number":253,"text":"πολλοὺς δὲ ὄντας ὁπλίσας δορυφόροις ἐχρῆτο αὐτοῖς ἐπείγων τοὺς Ἰουδαίους καὶ ἐκταράσσων ἐπὶ ἀποστάσει· τάς τε γὰρ ἄκρας ἐβιάζετο παραλαμβάνειν καὶ τῶν βασιλικῶν χρημάτων ἐπʼ ἐρεύνῃ προθύμως ὥρμητο βίᾳ διὰ κέρδη καὶ πλεονεξιῶν ἐπιθυμίας."},{"number":254,"text":"Ἐνστάσης δὲ τῆς πεντηκοστῆς, ἑορτὴ δὲ ἡμῶν ἐστιν πάτριος τοῦτο κεκλημένη, οὔτι κατὰ τὴν θρησκείαν μόνον παρῆσαν, ἀλλʼ ὀργῇ φέροντες τὴν παροινίαν τῆς Σαβίνου ὕβρεως μυριάδες συνηθροίσθησαν ἀνθρώπων καὶ πάνυ πολλαὶ Γαλιλαίων τε καὶ Ἰδουμαίων, Ἱεριχουντίων τε ἦν πληθὺς καὶ ὁπόσοι περάσαντι Ἰορδάνην ποταμὸν οἰκοῦσιν, αὐτῶν τε Ἰουδαίων πλῆθος πρὸς πάντας συνειλέχατο καὶ πολὺ προθυμότεροι τῶν ἄλλων ἐπὶ τιμωρίᾳ τῇ Σαβίνου ὡρμήκεσαν."},{"number":255,"text":"καὶ τρία μέρη νεμηθέντες ἐπὶ τοσῶνδε στρατοπεδεύονται χωρίων, οἱ μὲν τὸν ἱππόδρομον ἀπολαβόντες, καὶ τῶν δὲ λοιπῶν δύο μερῶν οἱ μὲν τῷ βορείῳ τοῦ ἱεροῦ πρὸς μεσημβρίαν τετραμμένοι, οἱ δὲ ἑῴαν μοῖραν εἶχον, μοῖρα δὲ αὐτῶν ἡ τρίτη τὰ πρὸς δυόμενον ἥλιον, ἔνθα καὶ τὸ βασίλειον ἦν. ἐπράσσετο δὲ τὰ πάντα αὐτοῖς ἐπὶ πολιορκίᾳ τῶν Ῥωμαίων ἁπανταχόθεν αὐτοῖς ἀποκεκλεισμένων."},{"number":256,"text":"καὶ Σαβῖνος, ἔδεισε γὰρ τό τε πλῆθος αὐτῶν καὶ τὰ φρονήματα ἀνδρῶν ἐν ὀλίγῳ τὸ θανεῖν ποιουμένων ὑπὸ τοῦ ἡττᾶσθαι μὴ ἐθέλειν ἐφʼ οἷς ἀρετὴν κρίνειαν τὸ νικᾶν, παραχρῆμά τε ὡς τὸν Οὔαρον ἔπεμπε γράμματα καὶ τὸ σύνηθες οὐκ ἀνίει κελεύων ἐκ τοῦ ὀξέος βοηθεῖν, ὡς κινδύνου μεγίστου τὸ ἐγκαταλειφθὲν στράτευμα περιεσχηκότος διὰ τὸ μὴ ἐς μακρὰν ἐλπίζειν κατακοπήσεσθαι ληφθέντας αὐτούς."},{"number":257,"text":"αὐτὸς δὲ τοῦ φρουρίου τὸν ὑψηλότατον τῶν πύργων καταλαβόμενος Φασάηλον ἐπὶ τιμῇ τοῦ Ἡρώδου ἀδελφοῦ Φασαήλου ᾠκοδομημένον τε καὶ οὕτως εἰρημένον τελευτῆς ὑπὸ Παρθυαίων αὐτῷ γενομένης, κατέσειε τοῖς Ῥωμαίοις ἐπεξιέναι τοῖς Ἰουδαίοις, αὐτὸς μὲν οὐδʼ εἰς τοὺς φίλους τολμῶν κατιέναι, τοὺς δʼ ἄλλους προαποθνήσκειν αὐτοῦ τῆς πλεονεξίας δικαιῶν."},{"number":258,"text":"τολμησάντων δʼ εἰς τὴν ἔξοδον τῶν Ῥωμαίων μάχη συνῄει καρτερά, καὶ οἱ Ῥωμαῖοι πολλῶν μὲν ἔργων ἐκράτουν, οὐ μὴν τὰ φρονήματά γε τοῖς Ἰουδαίοις ἔκαμνε τῇ ὄψει τοῦ δεινοῦ πολλῶν αὐτοῖς πεπτωκότων,"},{"number":259,"text":"περιοδεύσαντες δʼ ἀνίασιν ἐπὶ τὰς στοάς, αἵπερ ἦσαν τοῦ ἱεροῦ τὸν ἔξω περίβολον περιέχουσαι, καὶ πολλοῖς ἀμάχου γενομένης λίθους τε ἠφίεσαν τοὺς μὲν ἐκ χειρὸς ὑπάραντες, οὓς δὲ σφενδονῶν, ἀθληταὶ τρόπου τοιαύτης μάχης ὄντες."},{"number":260,"text":"καὶ οἱ τοξόται πάντες παρατεταγμένοι μεγάλα ἔβλαπτον τοὺς Ῥωμαίους διὰ τὸ ὑπερδέξιοί τε εἶναι καὶ ἐπιχειρεῖσθαι μὲν ἄποροι διὰ τὸ ἀνέφικτον τοῖς εἰσακοντίζειν πειρωμένοις εἶναι, ῥᾴους δὲ κρατεῖσθαι τοὺς πολεμίους ἔχοντες. καὶ πολὺν μὲν χρόνον ἡ μάχη συνέστη τοιάδε οὖσα."},{"number":261,"text":"ἔπειτα Ῥωμαῖοι δεινῶς φέροντες τοῖς δρωμένοις πῦρ ἐνιᾶσιν ταῖς στοαῖς λαθόντες Ἰουδαίων τοὺς ἀναβεβηκότας ἐπʼ αὐταῖς. καὶ τὸ πῦρ ὑπό τε πολλῶν προστεθειμένον καὶ μετὰ τῶν ἐγείρειν φλόγα δυναμένων ἥπτετο τοῦ ὀρόφου ᾗ τάχος."},{"number":262,"text":"ὁ δὲ ξύλωσιν παρέχων πίσσης τε καὶ κηροῦ πλέον ἔτι δὲ χρυσὸν ἐπαληλιμμένον εὐθέως ήκειν, ἔργα τε μεγάλα ἐκεῖνα καὶ ἀξιολογώτατα ἠφανίζετο. καὶ τοὺς ὑπὲρ τῶν στοῶν ὄλεθρος οὗτος ἀπροσδόκητος κατέλαβεν· οἱ μὲν γὰρ τοῦ ὀρόφου καταρραγέντος συγκατεφέροντο αὐτῷ, τοὺς δὲ περισταδὸν ἔβαλλον οἱ πολέμιοι·"},{"number":263,"text":"πολλοὶ δὲ ἀπορίᾳ σωτηρίας τε καὶ ἐκπλήξει κακοῦ τοῦ περιεστηκότος, οἱ μὲν εἰς τὸ πῦρ ἵεσαν αὑτούς, οἱ δὲ καὶ τοῖς ξίφεσι χρώμενοι διάδρασιν αὐτοῦ ἐποιοῦντο, ὁπόσοι δὲ εἰς τὸ κατόπιν χωρήσαντες ὁδῷ ᾗ ἀναβεβήκεσαν ἐσώζοντο, οἱ Ῥωμαῖοι πάντας ἔκτεινον γυμνούς τε ὄντας καὶ τὰ φρονήματα ἐκλελυμένους, οὐδὲν τῆς ἀπονοίας διὰ τὸ ἄνοπλον βοηθεῖν δυναμένης."},{"number":264,"text":"ἐσώθη τε τῶν ἀνελθόντων ἐπὶ τὸ τέγος οὐδʼ ὁστισοῦν. καὶ οἱ Ῥωμαῖοι διὰ τοῦ πυρὸς ᾗ παρείκοι ὠσθέντες ἐκράτουν τοῦ θησαυροῦ, καθʼ ὃν ἱερὰ ἦν χρήματα. καὶ διεκλάπη μὲν πολλὰ ὑπὸ τῶν στρατιωτῶν, Σαβῖνος δὲ περιεποίησεν εἰς τὸ φανερὸν τετρακόσια τάλαντα."},{"number":265,"text":"Ἰουδαίους δὲ ἐλύπει μὲν τὸ πάθος τῶν φίλων, οἳ ἐν τῇδε ἔπεσον τῇ μάχῃ, ἐλύπει δὲ καὶ τῶν ἀναθημάτων ἡ ἀφαίρεσις, οὐ μὴν ἀλλʼ ὅπερ αὐτῶν ἐτύγχανεν συνεστραμμένον καὶ μαχιμώτατον τούτῳ ἐμπεριέχοντες τὸ βασίλειον ἠπείλουν πῦρ τε ἐνήσειν αὐτῷ καὶ πάντας κτείνειν, κελεύοντες ᾗ τάχος ἀπιέναι καὶ πειθομένοις ὑπισχνούμενοι ἄδειαν καὶ Σαβίνῳ σὺν αὐτοῖς."},{"number":266,"text":"καὶ τῶν βασιλικῶν τὸ πλεῖστον ηὐτομολήκεσαν σὺν αὐτοῖς, Ῥοῦφος δὲ καὶ Γρᾶτος τρισχιλίους τὸ μαχιμώτατον τοῦ Ἡρώδου στρατεύματος ἔχοντες ἄνδρας τοῖς σώμασι δραστηρίους Ῥωμαίοις προστίθενται. καί τι καὶ ἱππικὸν ἦν τῶν ὑπὸ τῷ Ῥούφῳ τεταγμένων, ὃ καὶ αὐτὸ προσθήκη τῶν Ῥωμαίων ἐγεγόνει."},{"number":267,"text":"Ἰουδαίοις δὲ οὐκ ἠμέλητο ἡ πολιορκία, ἀλλὰ καὶ τὰ τείχη μετήλλευον καὶ τοῖς μεταβαλλομένοις ἐκέλευον μὴ ἐμποδισταῖς εἶναι τοῦ ἀποληψομένου χρόνῳ παροῦσαν αὐτοῖς ἐλευθερίαν τὴν πάτριον."},{"number":268,"text":"Σαβίνῳ μὲν οὖν εὐκτὸν ἀπιέναι μετὰ τῶν στρατιωτῶν, πιστεύειν δʼ οὐχ οἷός τε ἦν διὰ τὰ πεπραγμένα καὶ τὸ λίαν εὔγνωμον τῶν πολεμίων ἐπʼ ἀποτροπῇ τοῦ κατασταθησομένου εἶχεν, ἅμα δὲ καὶ τὸν Οὔαρον ἥξειν προσδοκῶν ὑπέμενε τὴν πολιορκίαν."},{"number":269,"text":"Ἐν τούτῳ δὲ καὶ ἕτερα μυρία θορύβων ἐχόμενα τὴν Ἰουδαίαν κατελάμβανεν πολλῶν πολλαχόσε οἳ κατʼ οἰκείων ἐλπίδας κερδῶν καὶ Ἰουδαίων ἔχθρας ἐπὶ τὸ πολεμεῖν ὡρμημένων·"},{"number":270,"text":"δισχίλιοι μὲν τῶν ὑφʼ Ἡρώδῃ ποτὲ στρατευσαμένων καὶ ἤδη καταλελυκότες ἐν αὐτῇ Ἰουδαίᾳ συστάντες προσεπολέμουν τοῖς βασιλικοῖς ἀντιστατοῦντος αὐτοῖς Ἀχιάβου τοῦ Ἡρώδου ἀνεψιοῦ, καὶ τῶν μὲν πεδίων εἰς τὰ μετέωρα ἀνεωσμένου διʼ ἐμπειρίαν τὴν εἰς τὰ πολεμικὰ τῶν ἀνδρῶν, ταῖς δὲ δυσχωρίαις σώζοντος ὁπόσα δυνατά."},{"number":271,"text":"Ἰούδας δὲ ἦν Ἐζεκίου τοῦ ἀρχιλῃστοῦ υἱὸς ἐπὶ μέγα δυνηθέντος ὑφʼ Ἡρώδου δὲ μεγάλοις ληφθέντος πόνοις. οὗτος οὖν ὁ Ἰούδας περὶ Σέπφωριν τῆς Γαλιλαίας συστησάμενος πλῆθος ἀνδρῶν ἀπονενοημένων ἐπιδρομὴν τῷ βασιλείῳ ποιεῖται καὶ ὅπλων κρατήσας ὁπόσα αὐτόθι ἀπέκειτο ὥπλιζε τοὺς περὶ αὐτὸν καὶ ἀποφέρεται χρήματα ὁπόσα κατελήφθη αὐτόθι,"},{"number":272,"text":"φοβερός τε ἅπασιν ἦν ἄγων καὶ φέρων τοὺς προστυγχάνοντας ἐπιθυμίᾳ μειζόνων πραγμάτων καὶ ζηλώσει βασιλείου τιμῆς, οὐκ ἀρετῆς ἐμπειρίᾳ τοῦ δὲ ὑβρίζειν περιουσίᾳ κτήσεσθαι προσδοκῶν τὸ ἐντεῦθεν γέρας."},{"number":273,"text":"Ἦν δὲ καὶ Σίμων δοῦλος μὲν Ἡρώδου τοῦ βασιλέως, ἄλλως δὲ ἀνὴρ εὐπρεπὴς καὶ μεγέθει καὶ ῥώμῃ σώματος ἐπὶ μέγα προύχων τε καὶ πεπιστευμένος. οὗτος ἀρθεὶς τῇ ἀκρισίᾳ τῶν πραγμάτων διάδημά τε ἐτόλμησε περιθέσθαι,"},{"number":274,"text":"καί τινος πλήθους συστάντος καὶ αὐτὸς βασιλεὺς ἀναγγελθεὶς μανίᾳ τῇ ἐκείνων καὶ εἶναι ἄξιος ἐλπίσας παρʼ ὁντινοῦν τό τε ἐν Ἱεριχοῦντι βασίλειον πίμπρησιν διʼ ἁρπαγῆς ἄγων τὰ ἐγκατειλημμένα, πολλάς τε καὶ ἄλλας τῶν βασιλικῶν οἰκήσεων πολλαχοῦ τῆς χώρας πῦρ ἐνιεὶς ἠφάνιζεν, τοῖς συνεστηκόσιν λείαν ἄγειν τὰ ἐγκαταλελειμμένα ἐπιτρέπων."},{"number":275,"text":"ἐπέπρακτο δʼ ἄν τι μεῖζον ὑπʼ αὐτοῦ μὴ ταχείας ἐπιστροφῆς γενομένης· ὁ γὰρ Γρᾶτος ὁ τῶν βασιλικῶν στρατιωτῶν Ῥωμαίοις προστεθειμένος μεθʼ ἧς εἶχεν δυνάμεως ὑπαντιάζει τὸν Σίμωνα,"},{"number":276,"text":"καὶ μάχης αὐτοῖς μεγάλης ἐπὶ πολὺ γενομένης τό τε πολὺ τῶν Περαίων ἀσύντακτοι ὄντες καὶ τόλμῃ μᾶλλον ἢ ἐπιστήμῃ μαχόμενοι ἐφθάρησαν, καὶ αὐτοῦ Σίμωνος διά τινος φάραγγος σώζοντος αὑτὸν Γρᾶτος ἐντυχὼν τὴν κεφαλὴν ἀποτέμνει."},{"number":277,"text":"κατεπρήσθη δὲ καὶ τὰ ἐπʼ Ἰορδάνῃ ποταμῷ ἐν Ἀμμάθοις βασίλεια ὑπό τινων συστάντων ἀνδρῶν Σίμωνι παραπλησίων. οὕτως πολλὴ ἀφροσύνη ἐνεπολίτευσε τῷ ἔθνει διὰ τὸ βασιλέα μὲν οἰκεῖον οὐκ εἶναι τὸν καθέξοντα τὸ πλῆθος ἀρετῇ, τοὺς δʼ ἀλλοφύλους ἐπελθόντας σωφρονιστὰς τοῦ μὴ στασιάσοντος τῶν ἀνθρώπων ὑπέκκαυμα αὐτῶν διά τε τοῦ ὑβρίζειν καὶ πλεονεκτεῖν γενέσθαι."},{"number":278,"text":"Ἐπεὶ καὶ Ἀθρόγγης ἀνὴρ οὔτε προγόνων ἐπιφανὴς ἀξιώματι οὔτε ἀρετῆς περιουσίᾳ ἤ τινων πλήθει χρημάτων, ποιμὴν δὲ καὶ ἀνεπιφανὴς τοῖς πᾶσιν εἰς τὰ πάντα ὤν, ἄλλως δὲ μεγέθει σώματος καὶ τῇ κατὰ χεῖρας ἀλκῇ διαπρέπων, ἐτόλμησεν ἐπὶ βασιλείᾳ φρονῆσαι τῷ κτώμενόν τε αὐτὴν ἡδονῆς πλέον ὑβρίσαι καὶ θνήσκων οὐκ ἐν μεγάλοις τίθεσθαι τῆς ψυχῆς τὸ ἐπὶ τοιοῖσδε ἀνάλωμα γενησόμενον."},{"number":279,"text":"ἦσαν δὲ αὐτῷ καὶ ἀδελφοὶ τέσσαρες μεγάλοι τε καὶ αὐτοὶ καὶ ἐπὶ μέγα προύχειν τῇ κατὰ χεῖρας ἀρετῇ πεπιστευμένοι, πρόεχμα εἶναι τῆς καθέξεως τῆς βασιλείας δοκοῦντες, λόχου τε αὐτῶν ἦρχεν ἕκαστος· συλλέγεται γὰρ μεγάλη πληθὺς πρὸς αὐτούς."},{"number":280,"text":"καὶ οἵδε μὲν στρατηγοὶ ἦσαν καὶ ὑπεστράτευον αὐτῷ ὁπόσα εἰς τὰς μάχας φοιτῶντες διʼ αὐτῶν, ὁ δὲ διάδημα περιθέμενος βουλευτήριόν τε ἦγεν ἐπὶ τοῖς ποιητέοις καὶ τὰ πάντα γνώμῃ ἀνακείμενα εἶχεν τῇ αὐτοῦ."},{"number":281,"text":"διέμενέ τε ἐπὶ πολὺ τῷδε τῷ ἀνδρὶ ἡ ἰσχὺς βασιλεῖ τε κεκλημένῳ καὶ ἃ πράσσειν ἐθέλοι μὴ ἀποστερουμένῳ, φόνῳ τε καὶ αὐτὸς καὶ οἱ ἀδελφοὶ ἦσαν ἐπὶ μέγα προσκείμενοι Ῥωμαίων τε καὶ βασιλικῶν μίσει πολιτεύοντες ὁμοίως πρὸς ἀμφοτέρους, τοῦτο μὲν ὕβρει ᾗ χρήσαιντο ἐπὶ τῆς Ἡρώδου ἀρχῆς, Ῥωμαίους δὲ ὧν τὸ παρὸν ἔδοξαν ἀδικεῖν."},{"number":282,"text":"προϊόντος δὲ χρόνου καὶ ἐπὶ πλέον ὁμοίως ἐξηγριώθησαν διάφευξίς τε οὐκ ἦν τοῖς πᾶσιν ἐμπεσεῖν, τὰ μὲν κέρδους ἐλπίδι, τὰ δὲ καὶ συνηθείᾳ τοῦ φονεύειν. ἐπιτίθενται δέ ποτε καὶ Ῥωμαίων λόχῳ κατὰ Ἐμμαοῦντα, οἳ σῖτόν τε καὶ ὅπλα τῆς στρατιᾶς ἔφερον. καὶ περιστάντες Ἄρειον μὲν τὸν ἑκατόνταρχον, ὃς ἡγεῖτο τοῦ παντὸς καὶ τεσσαράκοντα τῶν περὶ αὐτὸν πεζῶν τοὺς κρατίστους κατηκόντισαν."},{"number":283,"text":"οἱ δὲ λοιποὶ δείσαντες πρὸς τὸ πάθος αὐτῶν Γράτου σὺν τοῖς βασιλικοῖς, οἳ περὶ αὐτὸν ἦσαν, σκέπης αὐτοῖς γενομένης σώζονται τοὺς νεκροὺς καταλιπόντες. καὶ πολὺν μὲν τοιουτοτρόποις χρώμενοι χρόνον μάχαις Ῥωμαίους τε παρελύπησαν οὐκ εἰς ὀλίγα καὶ τὸ ἔθνος ἐκάκωσαν ἐπὶ μέγα."},{"number":284,"text":"χειροῦται δὲ αὐτῶν χρόνῳ ὕστερον ὁ μὲν Γράτῳ συμβαλὼν ὁ δὲ Πτολεμαίῳ, καὶ τὸν πρεσβύτατον Ἀρχελάου λαβόντος ὁ τελευταῖος πάθει τε τῷ ἐκείνου λελυπημένος καὶ ἄπορον ἐπὶ πλέον ὁρῶν τὴν σωτηρίαν ὑπὸ μονώσεως καὶ καμάτου πολλοῦ ψιλωθεὶς τῆς δυνάμεως ἐπὶ δεξιαῖς καὶ πίστει τοῦ θείου Ἀρχελάῳ παραδίδωσιν αὑτόν. καὶ τάδε μὲν ὕστερον γίνεται."},{"number":285,"text":"Λῃστηρίων δὲ ἡ Ἰουδαία πλέως ἦν, καὶ ὃς παρατύχοι τινῶν οἳ συστασιάσοιεν αὐτῷ βασιλεὺς προϊστάμενος ἐπʼ ὀλέθρῳ τοῦ κοινοῦ ἠπείγετο, ὀλίγα μὲν καὶ ἐπʼ ὀλίγοις Ῥωμαίοις λυπηροὶ καθιστάμενοι, τοῦ δὲ ὁμοφύλου φόνον ἐπὶ μήκιστον ἐμποιοῦντες."},{"number":286,"text":"Οὔαρος δὲ ἐπειδὴ τὸ πρῶτον πυνθάνεται τὰ πεπραγμένα Σαβίνου γράψαντος πρὸς αὐτόν, δείσας περὶ τοῦ τάγματος δύο τὰ λοιπὰ ἀναλαβών, τρία γὰρ ἐπὶ Συρίας τὰ πάντα ἦν, καὶ ἴλας ἱππέων τέσσαρας ὁπόσα τε ἐπικουρικὰ καὶ οἱ βασιλεῖς οἵ τινες τετράρχαι τότε παρεῖχον, ἠπείγετο βοηθεῖν τοῖς ἐν Ἰουδαίᾳ τότε πολιορκουμένοις."},{"number":287,"text":"εἴρητο δὲ πᾶσιν εἰς Πτολεμαΐδα ἐπείγεσθαι ὁπόσοι προεξεπέμποντο. διδόασί τε αὐτῷ καὶ Βηρύτιοι διιόντι αὐτῶν τὴν πόλιν ἐπικούρους πεντακοσίους καὶ χιλίους, πέμπει δὲ καὶ Ἀρέτας ὁ Πετραῖος ἔχθει τῷ Ἡρώδου φιλίαν τῶν Ῥωμαίων κτώμενος οὐκ ὀλίγην χεῖρα πεζῶν καὶ ἱππέων."},{"number":288,"text":"σταθείσης δʼ ἐν Πτολεμαΐδι πάσης ἤδη τῆς δυνάμεως μέρος τι ταύτης τῷ υἱῷ παραδοὺς καὶ ἑνὶ τῶν αὐτοῦ φίλων Γαλιλαίους ἐξέπεμπεν πολεμεῖν, οἳ ὑπὲρ τῆς Πτολεμαΐδος ἐχόμενοι κατοικοῦσιν."},{"number":289,"text":"ὃς ἐμβαλὼν τούς τε ἀντικαταστάντας εἰς μάχην τρέπεται καὶ Σέπφωριν ἑλὼν τοὺς μὲν οἰκήτορας ἠνδραποδίσατο, τὴν δὲ πόλιν ἐνέπρησεν. αὐτὸς δὲ Οὔαρος ἐπὶ Σαμαρείας τῷ παντὶ στρατῷ προιὼν τῆς μὲν πόλεως ἀπέσχετο διὰ τὸ ἀνέγκλητον ἐπὶ τοῖς νεωτερισμοῖς εἶναι, στρατοπεδεύεται δὲ ἔν τινι κώμῃ Πτολεμαίου κτήματι, Ἀροὺς ὄνομα αὐτῇ."},{"number":290,"text":"καὶ οἱ Ἄραβες μίσει τῷ Ἡρώδου ἐμπιπρᾶσιν αὐτὴν ἐχθρῶς καὶ πρὸς φίλους τοὺς ἐκείνου ἔχοντες. κἀνθένδε προϊόντες Σαμφὼ κώμην ἑτέραν διήρπασάν τε οἱ Ἄραβες καὶ ἔκαυσαν πάνυ ἐρυμνὴν οὖσαν, καὶ ἔφυγεν ἐν τῇ προόδῳ οὐδὲν αὐτούς,"},{"number":291,"text":"ἀλλὰ πυρὸς καὶ φόνου τὰ πάντα μεστὰ ἦν. πίμπραται δὲ καὶ Ἐμμαοῦς Οὐάρου κελεύσαντος ἐπʼ ἐκδικίᾳ τῶν συντετελευτηκότων προεκλειφθεῖσα ὑπὸ τῶν οἰκητόρων."},{"number":292,"text":"ἐντεῦθεν δὲ καὶ Ἱεροσολύμοις ἤδη συνῆπτε, καὶ Ἰουδαίων οἱ κατὰ πολιορκίαν τοῦ τάγματος τῇδε στρατοπεδευόμενοι τὴν ὄψιν τῆς προσόδου τῶν στρατευμάτων οὐχ ὑπομείναντες ᾤχοντο ἡμίεργον τὴν πολιορκίαν καταλιπόντες."},{"number":293,"text":"οἱ δʼ ἐν τοῖς Ἱεροσολύμοις Ἰουδαῖοι δεινῶς τοῦ Οὐάρου σφίσιν ἐγκαλοῦντος ἀπελύοντο τὰς αἰτίας, ὡς τῆς μὲν συνόδου τῆς πληθύος διὰ τὴν ἑορτὴν γενομένης, τοῦ δὲ πολέμου μηδαμὰ γνώμῃ τῇ αὐτῶν, τόλμῃ δὲ τῶν ἐπηλύδων συνελθόντες αὐτοῖς καὶ συμπολιορκηθέντες Ῥωμαίοις μᾶλλον ἢ πολιορκεῖν προθυμίαν σχόντες."},{"number":294,"text":"προαπηντήκασιν δὲ τῷ Οὐάρῳ Ἰώσηπός τε ἀνεψιὸς Ἡρώδου βασιλέως Γρᾶτος τε καὶ Ῥοῦφος τοὺς ὑπʼ αὐτοῖς τῶν στρατιωτῶν ἄγοντες καὶ τῶν Ῥωμαίων οἱ πολιορκούμενοι. Σαβῖνος δὲ οὐκ ἀφίκετο Οὐάρῳ εἰς ὄψιν, ἀλλʼ ὑπεξῆλθεν τῆς πόλεως ἐπὶ θάλασσαν."},{"number":295,"text":"Οὔαρος δὲ κατὰ τὴν χώραν πέμψας τοῦ στρατοῦ μέρος ἐπεζήτει τοὺς αἰτίους τῆς ἀποστάσεως. καὶ σημαινομένων τοὺς μὲν ἐκόλασεν ὡς αἰτιωτάτους, εἰσὶ δʼ οὓς καὶ ἀφῆκεν· ἐγίνοντο δὲ οἱ διὰ ταύτην τὴν αἰτίαν σταυρωθέντες δισχίλιοι."},{"number":296,"text":"μετὰ δὲ τοῦτο τὴν μὲν αὐτοῦ στρατιὰν ἀποπέμπεται, χρήσιμον μὲν ὁρῶν ἐπʼ οὐδαμοῖς οὖσαν πράγμασιν· πολλὰ δὲ ἠτάκτητο αὐτοῖς καὶ παρήκουστο τῶν δογμάτων καὶ ὧν ἠξίου Οὔαρος ἐφέσει κερδῶν, ἃ ἐκ τοῦ κακουργεῖν περιεγίνοντο αὐτοῖς."},{"number":297,"text":"αὐτὸς δὲ μυρίους Ἰουδαίους συνεστηκέναι πυνθανόμενος ἠπείγετο εἰς κατάληψιν αὐτῶν. οἱ δὲ οὐδʼ ἧκον εἰς χεῖρας, ἀλλὰ παρέδοσαν αὑτοὺς γνώμῃ τῇ Ἀχιάβου συνελθόντες. καὶ Οὔαρος τῷ πλήθει συγχωρῶν τὰς αἰτίας τῆς ἀποστάσεως ἔπεμπεν ἐπὶ Καίσαρα ὁπόσοι ἡγεμόνες ἦσαν αὐτῶν."},{"number":298,"text":"Καῖσαρ δὲ τοὺς μὲν αὐτῶν πολλοὺς διῆκεν, ὁπόσοι δὲ συγγενεῖς ὄντες Ἡρώδου συνεστράτευον αὐτοῖς τούσδε ἐκόλασεν μόνους, εἰ μηδὲν φροντίσαντες τοῦ δικαίου κατὰ τῶν οἰκείων ἐστράτευον."}],"11":[{"number":299,"text":"Οὔαρος μὲν δὴ ταῦτα καταστησάμενος καὶ φρουρὰν Ἱεροσολύμων τὸ καὶ πρότερον καταλιπὼν τάγμα ἐπʼ Ἀντιοχείας ἠπείγετο. Ἀρχελάῳ δʼ ἐπὶ Ῥώμης ἑτέρων πραγμάτων ἐφύοντο ἀρχαὶ κατὰ τοιαύτας αἰτίας."},{"number":300,"text":"ἀφίκετο εἰς τὴν Ῥώμην πρεσβεία Ἰουδαίων Οὐάρου τὸν ἀπόστολον αὐτῶν τῷ ἔθνει ἐπικεχωρηκότος ὑπὲρ αἰτήσεως αὐτονομίας. καὶ ἦσαν οἱ μὲν πρέσβεις οἱ ἀποσταλέντες γνώμῃ τοῦ ἔθνους πεντήκοντα, συνίσταντο δὲ αὐτοῖς τῶν ἐπὶ Ῥώμης Ἰουδαίων ὑπὲρ ὀκτακισχίλιοι."},{"number":301,"text":"Καίσαρός τε συνέδριον φίλων τε τῶν αὐτοῦ καὶ Ῥωμαίων τῶν πρώτων συνάγοντος ἐν ἱερῷ Ἀπόλλωνος μεγάλοις τέλεσιν ὑπʼ αὐτοῦ ἱδρυμένῳ, οἱ μὲν πρέσβεις μετὰ τοῦ πλήθους τῶν αὐτόθι Ἰουδαίων ἀφικνοῦνται, Ἀρχέλαος δὲ μετὰ τῶν φίλων."},{"number":302,"text":"ὁπόσοι δὲ συγγενεῖς τοῦ βασιλέως ἦσαν Ἀρχελάῳ μὲν συντετάχθαι διὰ μῖσος τὸ πρὸς αὐτὸν ὑστέρουν, τοῖς δὲ πρέσβεσιν ὁμοψηφεῖν κατʼ αὐτοῦ δεινὸν ἡγοῦντο ἐν αἰσχύνῃ τῇ αὐτῶν οἰόμενοι γενήσεσθαι παρὰ Καίσαρι κατʼ ἀνδρὸς οἰκείου τοιάδε πράσσειν προθυμεῖσθαι."},{"number":303,"text":"παρῆν δὲ ἤδη καὶ Φίλιππος ἀπὸ Συρίας ἐξοτρύναντος αὐτὸν Οὐάρου τὸ μὲν κεφάλαιον ἐπὶ συνηγορίᾳ τοῦ ἀδελφοῦ, πάνυ γὰρ εὐνόει Οὔαρος αὐτῷ, γινομένης δὲ τῇ βασιλείᾳ μεταπτώσεως, καὶ τάδε ὑπώπτευεν Οὔαρος νέμησιν αὐτῆς γενήσεσθαι διὰ τὸ πολλοὺς εἶναι τοὺς αὐτονομίας γλιχομένους, οὐχ ὑστεριῶν τοῦ κἂν αὐτὸς μοῖραν αὐτῆς τινα φέρεσθαι."},{"number":304,"text":"Λόγου οὖν τοῖς Ἰουδαίων πρέσβεσι δοθέντος, οἳ ἐπὶ καταλύσει τῆς βασιλείας ἤλπιζον λέγειν, ἐπὶ κατηγορίᾳ τῶν Ἡρώδου παρανομιῶν τρέπονται, βασιλέα μὲν ὀνόματι ἀποφαίνοντες αὐτόν, τῶν δʼ ἐν ταῖς τυραννίσιν ἑκάστης τὸ ἀνήκεστον ἀναδεξάμενον εἰς ταὐτὸν ἐπʼ ὀλέθρῳ τῶν Ἰουδαίων συνθέντα χρῆσθαι τὰ πολλὰ καὶ φύσει τῇ αὐτοῦ προσκαινουργεῖν οὐκ ἀπηλλαγμένον."},{"number":305,"text":"πολλῶν γοῦν ὄντων, οἳ ὀλέθροις ἀπολώλοιεν οὐχ ἱστορήσειν πω πρότερον, πολλῷ δὲ δυστυχεστέρους πάθους ἐκείνων τοὺς ζῶντας εἶναι, οὐ μόνον ὧν ὄψει καὶ διανοίᾳ ἐπʼ αὐτοῖς ἀνιαθεῖεν, ἀλλὰ καὶ ὧν ταῖς οὐσίαις."},{"number":306,"text":"πόλεις τε τὰς μὲν περιοικίδας καὶ ὑπὸ ἀλλοφύλων οἰκουμένας κοσμοῦντα ῶν ἐκ παύσασθαι καὶ καταλύσεώς τε καὶ ἀφανισμῷ τῶν ἐν τῇ ἀρχῇ αὐτοῦ κατῳκημένων."},{"number":307,"text":"πενίας δὲ ἀπόρου τὸ ἔθνος ἀναπεπληκέναι σὺν ὀλίγοις εὔδαιμον παρειληφότα, τῶν τε εὐπατριδῶν ὁπότε κτείνειεν αὐτοὺς ἐπʼ ἀλόγοις αἰτίαις τὰς οὐσίας ἀποφερόμενον καὶ οἷς συγχωρήσειε τὴν ἀηδίαν τοῦ ζῆν ψίλωσιν χρημάτων καταδικάζοντα."},{"number":308,"text":"καὶ χωρὶς μὲν πράσσεσθαι φόρους ἐπιβαλλομένους ἑκάστοις τὸ ἐπʼ ἔτος, χωρὶς δὲ εὐπορίας εἶναι παρακαταβολὰς αὐτῷ τε καὶ οἰκείοις καὶ φίλοις καὶ τῶν δούλων οἳ ἐπʼ ἐκπράξει τῶν φόρων ἐξίοιεν διὰ τὸ μὴ εἶναι κτήσει τοῦ ἀνυβρίστως μηδʼ ὅπως μηδʼ ἀργυρίων διδομένων."},{"number":309,"text":"παρθένων μέντοι φθορὰς καὶ γυναικῶν αἰσχύνας, ὁπόσας ἐπὶ παροινίᾳ καὶ ἀπὸ τοῦ ἀνθρωπείου δρώμενα σιγᾶν διὰ τὸ ἡδονὴν ἴσην εἶναι τοῖς πεπονθόσι τοῦ μὴ γεγονέναι τὴν ἐκ τοῦ ἀνέκπυστα αὐτὰ εἶναι· τοσήνδε Ἡρώδην ἐπεισάγεσθαι τὴν ὕβριν αὐτοῖς, ὁπόσην οὐδʼ ἂν θηρίον ἀνθρώπων ἐπιστατεῖν δυνάμεως αὐτῷ παραγενομένης."},{"number":310,"text":"πολλῶν γοῦν ἀναστάσεων καὶ μεταστάσεων παραλαβουσῶν τὸ ἔθνος οὐδεμίαν ἱστορεῖσθαι πώποτε τοιάνδε δυστυχίαν ἐπελθοῦσαν αὐτῷ, παράδειγμά τε κακώσεως ἣν αὐτῷ Ἡρώδης ἐπετίθει τὸ ἔθνος·"},{"number":311,"text":"καὶ ταῦτʼ εἰκότως ἂν γενέσθαι τὸ ἀσμένως Ἀρχέλαον βασιλέα προσειπεῖν οἰήσει τοῦ πάντʼ ὅντινʼ οὖν τὸν ἐπὶ τὴν βασιλείαν ἐσόμενον Ἡρώδου μετριώτερον φαίνεσθαι, καὶ τόν τε πατέρα συνολοφύρεσθαι αὐτῷ θεραπεύοντας, εἴ γε μετρίου τυγχάνειν δυνηθεῖεν, καὶ τἆλλα οἰκειουμένους."},{"number":312,"text":"τοῦ δὲ δείσαντος μὴ οὐχὶ Ἡρώδου γνήσιος πιστεύοιτο υἱός, οὐδὲν εἰς ἀναβολὰς ἀλλʼ ἐκ τοῦ ὀξέος ἐπάξειν ἂν τῷ ἔθνει τὴν διάνοιαν αὐτοῦ καὶ ταῦτα μηδέπω τέλεον κρατυνάμενον ἡγεμονίαν διὰ τὸ ἐπὶ Καίσαρι δοῦναι καὶ μὴ τὴν ἐξουσίαν εἶναι,"},{"number":313,"text":"καὶ παράδειγμα τὴν τῆς εἰς αὖθις ἀρετῆς τιθέναι τοῖς ἀρχθησομένοις μετριότητος καὶ εὐνομίας, ᾗ χρήσαιτο ἂν πρὸς αὐτούς, ἀπὸ τῆς ἐν πρώτοις ἀποδειχθείσης πράξεως ἐπί τε τοῖς πολίταις καὶ τῷ θεῷ τρισχιλίων ὁμοφύλων ἀνδρῶν σφαγὴν ἐν τῷ τεμένει ποιησάμενον. πῶς οὐκ ἂν ἤδη καὶ δικαίῳ μίσει χρῆσθαι κατʼ αὐτῶν πρὸς τῇ λοιπῇ ὠμότητι καὶ ἔγκλημα τῆς ἀντιστάσεως καὶ ἀντιλογίας ἐπὶ τῇ ἀρχῇ προφερόμενον;"},{"number":314,"text":"ἦν δὲ κεφάλαιον αὐτοῖς τῆς ἀξιώσεως βασιλείας μὲν καὶ τοιῶνδε ἀρχῶν ἀπηλλάχθαι, προσθήκη δὲ Συρίας γεγονότες ὑποτάσσεσθαι τοῖς ἐκεῖσε πεμπομένοις στρατηγοῖς· φανερωθήσεσθαι γὰρ οὕτως, εἴτε ἀληθῶς στασιώδεις εἶεν καὶ νεωτερισμοῖς τὰ πολλὰ προσησκημένοι εἴτε καὶ οὔ, μετριωτέρων τυχόντες οἳ ἐπιστήσονται αὐτοῖς."},{"number":315,"text":"Τοιαῦτα δὲ τῶν Ἰουδαίων εἰρηκότων Νικόλαος τούς τε βασιλεῖς ἀπήλλασσε τῶν ἐγκλημάτων, Ἡρώδην μὲν διὰ τὸ παρʼ ὃν ἔζη χρόνον τυχεῖν ἀκατηγόρητον· οὐ γὰρ δὴ τοὺς ἐγκαλεῖν ἔχοντας ἐπὶ μετρίοις παρὰ τοῦ ζῶντος τιμωρίαν λαβεῖν δυναμένους ἐπὶ νεκρῷ κατηγορίαν συντιθέναι·"},{"number":316,"text":"τὰ δὲ ὑπʼ Ἀρχελάου πραχθέντα ὕβρει τῇ ἐκείνων ἀνετίθει, οἳ ὀριγνώμενοι πραγμάτων παρὰ τοὺς νόμους καὶ σφαγῆς ἄρξαντες τῶν κωλύειν ὑβρίζοντας προμηθουμένων ἀμύνης γενομένης ἐγκαλοῖεν. ἐνεκάλει δὲ νεωτεροποιίας αὐτοῖς καὶ τοῦ στασιάζειν ἡδονὴν ἀπαιδευσίᾳ τοῦ πείθεσθαι δίκῃ καὶ νομίμοις ὑπὸ τοῦ θέλειν τὰ πάντα νικᾶν. ταῦτα μὲν οὖν Νικόλαος."},{"number":317,"text":"Καῖσαρ δʼ ἀκούσας διαλύει μὲν τὸ συνέδριον, ὀλίγων δʼ ἡμερῶν ὕστερον Ἀρχέλαον βασιλέα μὲν οὐκ ἀποφαίνεται, τῆς δʼ ἡμίσεως χώρας ἥπερ Ἡρώδῃ ὑπετέλει ἐθνάρχην καθίσταται, τιμήσειν ἀξιώματι βασιλείας ὑπισχνούμενος, εἴπερ τὴν εἰς αὐτὴν ἀρετὴν προσφέροιτο."},{"number":318,"text":"τὴν δʼ ἑτέραν ἡμίσειαν νείμας διχῇ δυσὶν Ἡρώδου παισὶν ἑτέροις παρεδίδου Φιλίππῳ καὶ Ἀντίπᾳ τῷ πρὸς Ἀρχέλαον τὸν ἀδελφὸν ἀμφισβητήσαντι περὶ τῆς ὅλης ἀρχῆς. καὶ τούτῳ μὲν ἥ τε Περαία καὶ τὸ Γαλιλαῖον ὑπετέλουν, φορά τε ἦν τάλαντα διακόσια τὸ ἐπʼ ἔτος."},{"number":319,"text":"Βαταναία δὲ σὺν Τράχωνι καὶ Αὐρανῖτις σύν τινι μέρει οἴκου τοῦ Ζηνοδώρου λεγομένου Φιλίππῳ τάλαντα ἑκατὸν προσέφερεν· τὰ δʼ Ἀρχελάῳ συντελοῦντα Ἰδουμαῖοί τε καὶ Ἰουδαία τό τε Σαμαρειτικόν. τετάρτην μοῖραν οὗτοι τῶν φόρων παραλέλυντο Καίσαρος αὐτοῖς κούφισιν ψηφισαμένου διὰ τὸ μὴ συναποστῆναι τῇ λοιπῇ πληθύι."},{"number":320,"text":"καὶ ἦσαν πόλεις αἳ Ἀρχελάῳ ὑπετέλουν Στράτωνός τε πύργος καὶ Σεβαστὴ σὺν Ἰόππῃ καὶ Ἱεροσολύμοις· Γάζαν γὰρ καὶ Γάδαρα καὶ Ἵππον, Ἑλληνίδες εἰσὶν πόλεις, ἀπορρήξας αὐτοῦ τῆς ἀκροάσεως Συρίας προσθήκην ποιεῖται. προσῄει δὲ Ἀρχελάῳ φορὰ χρημάτων τὸ κατʼ ἐνιαυτὸν εἰς τάλαντα ἑξακόσια ἐξ ἧς παρέλαβεν ἀρχῆς."},{"number":321,"text":"Καὶ τάδε μὲν τοῖς Ἡρώδου υἱέσιν τῶν πατρῴων παρῆν. Σαλώμῃ δὲ πρὸς οἷς ὁ ἀδελφὸς ἐν ταῖς διαθήκαις ἀπονέμει, Ἰάμνεια δὲ ἦν ταῦτα καὶ Ἄζωτος καὶ Φασαηλὶς καὶ ἀργυρίου ἐπισήμου μυριάδες πεντήκοντα, Καῖσαρ χαρίζεται καὶ τὴν ἐν Ἀσκάλωνι βασίλειον οἴκησιν. ἦν δὲ καὶ ταύτῃ πρόσοδος ἐκ πάντων ταλάντων ἑξήκοντα τὸ ἐπʼ ἔτος· καὶ αὐτῆς ὁ οἶκος ἦν ἐν τῇ Ἀρχελάου ἀρχῇ."},{"number":322,"text":"κομίζονται δὲ καὶ οἱ λοιποὶ τοῦ βασιλέως συγγενεῖς ὁπόσα αἱ διαθῆκαι διηγόρευον. δυοῖν δʼ αὐτοῦ θυγατράσιν παρθένοις χωρὶς ὧν ὁ πατὴρ κατέλιπεν Καῖσαρ ἑκατέρᾳ δωρεὰν ἐπετίθει μυριάδων ἀνὰ πέντε καὶ εἴκοσι ἀργυρίου ἐπισήμου καὶ συνῴκισεν αὐτὰς τοῖς Φερώρου υἱέσιν."},{"number":323,"text":"χαρίζεται δὲ καὶ ὁπόσα αὐτῷ καταλέλειπτο τοῖς παισὶν τοῦ βασιλέως ὄντα πεντακοσίων ταλάντων καὶ χιλίων, ὀλίγα τῶν σκευῶν ὑπεξελόμενος οὐχ οὕτως μεγέθει τέλους ὡς μνήμῃ τοῦ βασιλέως αὐτῷ κεχαρισμένα."}],"12":[{"number":324,"text":"Τούτων δὲ ταύτῃ διαπεπραγμένων ὑπὸ Καίσαρος νεανίας Ἰουδαῖος μὲν τὸ γένος, ἐπὶ δὲ τῆς Σιδωνίων τεθραμμένος πόλεως παρά τινι τῶν Ῥωμαϊκῶν ἀπελευθέρων εἰσῴκισεν αὑτὸν εἰς τὴν Ἡρώδου συγγένειαν ὁμοιότητι μορφῆς, ἣ πρὸς Ἀλέξανδρον αὐτῷ τὸν ἀνῃρημένον Ἡρώδου υἱὸν ἐμαρτυρεῖτο παρὰ τοῖς θεωροῦσιν."},{"number":325,"text":"καὶ τοῦτο παρόρμημα ἦν αὐτῷ εἰς τὸ μεταποιεῖσθαι τῆς ἡγεμονίας. καὶ ὁμοπράγμονα παραλαβὼν ὁμόφυλον ἄνδρα, ἔμπειρον δὲ τῶν ἀμφὶ τὸ βασίλειον πονηρόν τε ἄλλως καὶ ταράξαι μεγάλα πράγματα φύσιν ἔχοντα καὶ τοιαύτης κακίας διδάσκαλον αὐτῷ γενόμενον,"},{"number":326,"text":"ἀπέφαινεν αὑτὸν Ἀλέξανδρον καὶ Ἡρώδου παῖδα ὄντα διακεκλεμμένον ὑπὸ τῶν ἀνελεῖν αὐτὸν ἐσταλμένων· κτείναντα γὰρ ἑτέρους, οἳ ἀπατήσειν ἔμελλον τοὺς θεωροῦντας, αὐτόν τε περιποιῆσαι καὶ τὸν ἀδελφὸν Ἀριστόβουλον."},{"number":327,"text":"καὶ τούτοις αὐτός τε ἀνεπτέρωτο, καὶ τοὺς ἐντυγχάνοντας οὐκ ἀπήλλακτο ἀπατᾶν, ἀλλὰ Κρήτῃ προσενεχθεὶς Ἰουδαίων ὁπόσοις εἰς ὁμιλίαν ἀφίκετο ἐπηγάγετο εἰς πίστιν, καὶ χρημάτων εὐπορηθεὶς δόσει τῇ ἐκείνων ἐπὶ Μήλου διῆρεν. πολὺ πλέονα δὲ ἦν ἐντεῦθεν ὁπόσα αὐτῷ προσῄει χρήματα πίστει τῆς βασιλείου συγγενείας καὶ ἐλπίδι τοῦ ἀπολαβεῖν τὴν πάτριον ἀρχὴν καὶ ἀμείψασθαι τοὺς εὐεργέτας."},{"number":328,"text":"ἐπὶ Ῥώμης ἠπείγετο παραπομπῇ τῶν ἰδιοξένων, καὶ Δικαιαρχείᾳ προσβαλὼν οὐκ ἠτύχει καὶ τοὺς τῇδε Ἰουδαίους ἀφʼ ὁμοίας ἀπάτης προσαγαγέσθαι, προσῄεσάν τε ὥσπερ βασιλεῖ οἵ τε ἄλλοι καὶ ὁπόσοις ξενία πρὸς Ἡρώδην καὶ εὔνοια ἦν."},{"number":329,"text":"αἴτιον δὲ ἦν τῶν ἀνθρώπων τὸ ἡδονῇ δεχόμενον τοὺς λόγους σὺν τῷ φερεγγύῳ τῆς μορφῆς· καὶ γὰρ τοῖς πάνυ ὡμιληκόσιν Ἀλεξάνδρῳ πολὺ τὸ πιστὸν ἐνετίθει τοῦ μὴ οὐχ ἕτερος ἀλλʼ αὐτὸς εἶναι, καὶ πρὸς τοὺς πλησίον ὤμνυσαν,"},{"number":330,"text":"ὥστε καὶ προελθόντος εἰς τὴν Ῥώμην λόγου τοῦ περὶ αὐτοῦ πᾶν τὸ τῇδε Ἰουδαίων ἔθνος ὑπαντιάζοντες ἐξῄεσαν τῷ παρὰ δόξαν τῆς σωτηρίας θειάζοντες τὸ ἔργον καὶ χάρμα ποιούμενοι διὰ τὸ μητρῷον αὐτῶν γένος, ὁπότε χωροίη κατὰ τοῦ στενωποῦ διφροφορούμενος·"},{"number":331,"text":"καὶ πάντα βασίλειον περὶ αὐτὸν σχῆμα ἦν ἀναλώμασιν τῶν ἰδιοξένων, μεγάλαι περιστάσεις ἐγίνοντο τῆς πληθύος ἐπιβοήσεις τε εὔφημοι ὁπόσα εἰκὸς τοῖς οὕτω παρʼ ἐλπίδα σωθεῖσιν συντυγχάνειν οὐδὲν ὅ τι οὐκ ἐπράσσετο."},{"number":332,"text":"Καίσαρι δὲ ὡς ἀφίκετο ἀγγελία ἡ περὶ αὐτοῦ, ἠπίστει μὲν διὰ τὸ μὴ ἂν ῥᾳδίως ἀπατηθῆναι Ἡρώδην ἐν πράγμασιν ἐπὶ μέγα ἀνήκουσιν αὐτῷ, διδοὺς δὲ τῇ ἐλπίδι Κέλαδον τῶν αὐτοῦ τινὰ ἐξελευθέρων ὡμιληκότα τοῖς μειρακίοις πέμπει κελεύσας ἀγαγεῖν εἰς ὄψιν αὐτῷ τὸν Ἀλέξανδρον. ὁ δὲ ἀνῆγεν οὐδέν τι βελτίων ἐπὶ τῇ κρίσει τῶν πολλῶν γενόμενος."},{"number":333,"text":"οὐ μὴν Καῖσάρ γε ἠπατᾶτο, ἀλλʼ ἦν μὲν ἐμφερής, οὐ μὴν ὥστε ἀπατῆσαι τοὺς σωφρόνως ἐκλογίζεσθαι δυναμένους· αὐτουργίᾳ τε γὰρ ἐτέτρυτο ὁ ψευδαλέξανδρος καὶ παρὰ τὸ ἐκείνῳ ῥαδαλὸν τοῦ σώματος ὑπὸ τρυφῆς καὶ γενναιότητος συνερχόμενον διὰ τὰ ἐναντία τῷδε ἐπισκληρότερον ἐξεβεβήκει τὸ σῶμα."},{"number":334,"text":"θεασάμενος οὖν συμπνευσμὸν ἐπὶ ψευδολογίᾳ διδασκάλου καὶ μαθητοῦ καὶ λόγων τολμηρῶν συγκρότησιν, ἐξήταζε περὶ Ἀριστοβούλου, τί καὶ γεγόνοι συνεκκλαπεὶς αὐτῷ, καὶ διʼ ἣν αἰτίαν οὐ παραγεγόνοι μεταποιούμενος τῆς ἀξίας, ἧς προσῆκε τυγχάνειν τοὺς οὕτω γεγονότας;"},{"number":335,"text":"φαμένου δʼ ἐπὶ νήσου τῆς Κυπρίων καταλελεῖφθαι κινδύνων ὑφοράσει τῶν κατὰ θάλασσαν, εἰ περὶ αὐτῷ συσταίη τι δεινόν, μὴ παντελὲς ἐξαλείφοιτο τὸ Μαριάμμης γένος ἀλλὰ περιὼν Ἀριστόβουλος μένοι τοὺς ἐπιβεβουλευκότας,"},{"number":336,"text":"ταῦτα διισχυριζομένου καὶ συνεστῶτος αὐτῷ τοῦ μηχανοποιοῦ τῆς πράξεως Καῖσαρ καταμόνας ἀπολαβὼν τὸ μειράκιον ἀλλὰ σοὶ μισθός, ἔφη, προκείσεται τοῦ μὴ καὶ πρὸς ἐμὲ ἀπάτῃ χρησομένου τὸ μὴ ἀπολούμενον τῆς σωτηρίας· φάθι δή μοι αὐτόν τε ὃς ὢν τυγχάνεις καὶ ὅς σε τοιάδε ᾖξε τολμῆσαι διανοεῖσθαι·"},{"number":337,"text":"μεῖζον γὰρ τὸ ἐπιβούλευμα κακίας ἐγκεχείρηκας χρόνων οὓς γεγονὼς τυγχάνεις. καὶ δή, οὐ γὰρ ἦν ἄλλως πράσσειν, φράζει πρὸς τὸν Καίσαρα τὸ ἐπιβούλευμα, ὅν τε τρόπον καὶ ὑφʼ οὗ τυγχάνοι συγκείμενον. καὶ ὁ Καῖσαρ τὸν μὲν ψευδαλέξανδρον, οὐ γὰρ ἐψεύσατο ὁμολογίαν τὴν πρὸς αὐτόν, δραστήριον ὁρῶν αὐτουργῆσαι τῷ σώματι ἐρέσσειν ἐν τοῖς ναύταις καταλέγει, τὸν δὲ ἀναπείσαντα κτείνει."},{"number":338,"text":"καταδίκη δʼ ἤρκει Μηλίοις ὁπόσα ἐτετελέκεσαν εἰς τὸν Ψευδαλέξανδρον διακενῆς ἀναλωκέναι. καὶ τὰ μὲν περὶ τὸν ψευδαλέξανδρον τολμηρῶς συντεθέντα οὕτως ἀκλεῶς ἔσχεν."}],"13":[{"number":339,"text":"Ἀρχέλαος δὲ τὴν ἐθναρχίαν παραλαβὼν ἐπεὶ εἰς Ἰουδαίαν ἀφικνεῖται, Ἰωάζαρον τὸν Βοηθοῦ ἀφελόμενος τὴν ἀρχιερωσύνην ἐπικαλῶν αὐτῷ συστάντι τοῖς στασιώταις Ἐλεάζαρον τὸν ἐκείνου ἐπικαθίσταται ἀδελφόν."},{"number":340,"text":"ἀνοικοδομεῖ δὲ καὶ τὸ ἐν Ἱεριχοῦντι βασίλειον ἐκπρεπῶς, τῶν τε ὑδάτων ὁπόσα Νεαρὰν τὴν κώμην ὠφελεῖ ἐπιρρέοντα ἐξ ἡμισείας ἀπέστρεψεν ἐπαγωγὴν αὐτῷ ποιούμενος τῷ πεδίῳ φοίνιξιν ὑπʼ αὐτοῦ πεφυτευμένῳ, κώμην τε κτίσας Ἀρχελαΐδα ὄνομα αὐτῇ τίθεται."},{"number":341,"text":"καὶ τοῦ πατρίου παράβασιν ποιησάμενος Γλαφύραν τὴν Ἀρχελάου μὲν θυγατέρα, Ἀλεξάνδρου δὲ τοῦ ἀδελφοῦ γαμετὴν γενομένην, ἐξ οὗ καὶ τέκνα ἦν αὐτῇ, ἀπώμοτον ὂν Ἰουδαίοις γαμετὰς ἀδελφῶν ἄγεσθαι, γαμεῖ. διατρίβει δὲ οὐδὲ ὁ Ἑλεάζαρος ἐν τῇ ἱερωσύνῃ ἐπικατασταθέντος αὐτῷ ζῶντι Ἰησοῦ τοῦ Σεὲ παιδός."},{"number":342,"text":"Δεκάτῳ δὲ ἔτει τῆς ἀρχῆς Ἀρχελάου οἱ πρῶτοι τῶν ἀνδρῶν ἔν τε Ἰουδαίοις καὶ Σαμαρεῦσι μὴ φέροντες τὴν ὠμότητα αὐτοῦ καὶ τυραννίδα κατηγοροῦσιν αὐτοῦ ἐπὶ Καίσαρος, καὶ μάλιστα ἐπεὶ ἔγνωσαν αὐτὸν παραβεβηκότα τὰς ἐντολὰς αὐτοῦ, ἵνα ἐπιεικῶς ἀναστραφῇ τὰ πρὸς αὐτούς."},{"number":343,"text":"ὁ τοίνυν Καῖσαρ ὡς ἤκουσεν, ὀργῇ φέρων τὸν ἐπίτροπον τὸν Ἀρχελάου τῶν ἐν Ῥώμῃ πραγμάτων, Ἀρχέλαος δὲ καὶ τούτῳ ὄνομα ἦν, μετακαλέσας γράφειν μὲν Ἀρχελάῳ ταπεινὸν ἡγεῖται, σὺ δὲ παραχρῆμα, φησίν, πλέων μηδὲν εἰς ἀναβολὰς ἐπαναγαγεῖν αὐτὸν πρὸς ἡμᾶς."},{"number":344,"text":"καὶ ὃς ἔκπλουν ἐκ τοῦ ὀξέος ποιησάμενος καὶ ἀφικόμενος εἰς Ἰουδαίαν λαμβάνει τὸν Ἀρχέλαον ἐν εὐωχίαις ὄντα μετὰ τῶν φίλων, τήν τε διάνοιαν ἀποσημαίνει τὴν Καίσαρος καὶ ὥρμησεν αὐτὸν εἰς τὴν ἔξοδον. καὶ ὁ Καῖσαρ ἀφικομένου ἐπί τινων κατηγόρων ἀκροᾶται καὶ αὐτοῦ λέγοντος ἐκεῖνον μὲν φυγάδα ἐλαύνει δοὺς οἰκητήριον αὐτῷ Βίενναν πόλιν τῆς Γαλατίας, τὰ δὲ χρήματα ἀπηνέγκατο."},{"number":345,"text":"Πρότερον δὲ ἢ κληθεὶς ἐπὶ Ῥώμης ἀνελθεῖν Ἀρχέλαος ὄναρ τοιόνδε ἐκδιηγεῖται τοῖς φίλοις θεασάμενος· ἀστάχυας δέκα τὸν ἀριθμὸν πλέους πυροῦ τὴν ἰδίαν ἀκμὴν ἀπειληφότας δόξα ἦν αὐτῷ βιβρωσκομένους ὑπὸ βοῶν θεωρεῖν. καὶ περιεγρόμενος φέρειν εἰς μέγα δόξαν τὴν ὄψιν αὐτῷ μεταστέλλεται τοὺς μάντεις, οἷς περὶ ὀνειράτων ἦσαν αἱ ἀναστροφαί."},{"number":346,"text":"σκιδναμένων δὲ ἑτέρων ἐφʼ ἑτέροις, οὐ γὰρ εἰς ἕνα ἔκειτο πᾶσιν ἀφήγησις, Σίμων ἀνὴρ γένος Ἐσσαῖος ἀσφάλειαν αἰτησάμενος, μεταβολὴν πραγμάτων ἔλεγεν Ἀρχελάῳ φέρειν τὴν ὄψιν οὐκ ἐπʼ ἀγαθοῖς πράγμασιν·"},{"number":347,"text":"βόας μὲν γὰρ κακοπαθείας τε ἀποσαφεῖν διὰ τὸ ἔργοις ἐπιταλαιπωρεῖν τὸ ζῷον, μεταβολὰς δὲ αὖ πραγμάτων διὰ τὸ τὴν γῆν πόνῳ τῷ ἐκείνων ἀρουμένην ἐν ταὐτῷ μένειν οὐ δύνασθαι· τοὺς δὲ ἀστάχυας δέκα ὄντας τοσῶνδε ἀριθμὸν ἐνιαυτῶν ὁρίζειν, περιόδῳ γὰρ ἑνὸς παραγίνεσθαι θέρος, καὶ τὸν χρόνον ἐξήκειν Ἀρχελάῳ τῆς ἡγεμονίας."},{"number":348,"text":"καὶ ὁ μὲν ταύτῃ ἐξηγήσατο τὸν ὄνειρον. πέμπτῃ δὲ ἡμέρᾳ μεθʼ ὃ τὸ πρῶτον αὐτοῦ ἡ ὄψις Ἀρχελάῳ συνῆλθεν ὁ ἀνακαλούμενος Ἀρχέλαος πεμπτὸς εἰς Ἰουδαίαν ἀφίκετο."},{"number":349,"text":"Παραπλήσια δὲ καὶ Γλαφύρᾳ τῇ γυναικὶ αὐτοῦ συντυγχάνει βασιλέως Ἀρχελάου θυγατρὶ οὔσῃ, ᾗ καὶ πρότερον εἶπον συνῴκει παρθένον λαβὼν Ἀλέξανδρος Ἡρώδου μὲν υἱὸς Ἀρχελάου δʼ ἀδελφός. ἐπεὶ δὲ συμβαίνει τὸν Ἀλέξανδρον ὑπὸ τοῦ πατρὸς τελευτῆσαι,"},{"number":350,"text":"Ἰόβᾳ τῷ Λιβύων βασιλεῖ γαμεῖται, μεταστάντος δὲ τοῦ Λίβυος χηρεύουσαν ἐν Καππαδοκίᾳ παρὰ τῷ πατρὶ Ἀρχέλαος ἄγεται τὴν συνοῦσαν αὐτῷ Μαριάμμην ἐκβαλών· τοσόσδε τῆς Γλαφύρας ἀνέστρεψεν ἔρως."},{"number":351,"text":"καὶ συνοικοῦσα τῷ Ἀρχελάῳ τοιόνδε ὄναρ θεᾶται· ἐδόκει τὸν Ἀλέξανδρον ἐπιστάντα θεασαμένη χαίρειν καὶ περιβάλλειν προθύμως, τὸν δὲ κατάμεμψίν τε αὐτῆς ποιεῖσθαι καὶ φάναι·"},{"number":352,"text":"Γλαφύρα, συνηγορεῖς ἄρα λόγῳ, ὃς ἄπιστα ἔλεγεν εἶναι γυναιξίν, εἰ συνομόσασά τέ μοι καὶ συγκατοικισθεῖσα παρθένος παίδων ἡμῖν γεγονότων λήθῃ παραδίδως ἔρωτας τοὺς ἐμοὺς δευτέρων ἐπιθυμίᾳ γάμων. πληθώρα δέ σοι οὐδʼ οὕτως ὕβρεως, ἀλλὰ καὶ τρίτον ἐτόλμησας σαυτῇ παρακατακλῖναι νυμφίον ἀπρεπῶς καὶ ἀναισχύντως ἐπεισιοῦσα οἴκῳ τῷ ἐμῷ, καὶ γάμον συντιθεμένη πρὸς Ἀρχέλαον ἄνδρα μὲν σεαυτῆς ἀδελφὸν δὲ ἡμέτερον."},{"number":353,"text":"ἀλλʼ οὐκ ἔγωγε λήθην ποιήσομαι εὐνοίας τῆς σῆς, ἀπαλλάξω δέ σε παντὸς τοῦ ὀνειδιοῦντος ἐμὴν ὥσπερ ἦν κατασκευασάμενος. ταῦτα διηγησαμένη πρὸς τὰς συνήθεις τῶν γυναικῶν μετʼ ὀλίγας ἡμέρας τελευτᾷ τὸν βίον."},{"number":354,"text":"Ἐγὼ δὲ οὐκ ἀλλότρια νομίσας αὐτὰ τῷδε τῷ λόγῳ εἶναι διὰ τὸ περὶ τῶν βασιλέων αὐτὸν ἐνεστηκέναι καὶ ἄλλως ἐπὶ παραδείγματι φέρειν τοῦ τε ἀμφὶ τὰς ψυχὰς ἀθανασίας ἐμφεροῦς καὶ τοῦ θείου προμηθείᾳ τὰ ἀνθρώπεια περιειληφότος τῇ αὐτοῦ, καλῶς ἔχειν ἐνόμισα εἰπεῖν. ὅτῳ δὲ ἀπιστεῖται τὰ τοιάδε γνώμης ὀνινάμενος τῆς ἑαυτοῦ κώλυμα οὐκ ἂν γένοιτο τῷ ἐπʼ ἀρετὴν αὐτῷ προστιθεμένῳ."},{"number":355,"text":"τῆς δʼ Ἀρχελάου χώρας ὑποτελοῦς προσνεμηθείσης τῇ Σύρων πέμπεται Κυρίνιος ὑπὸ Καίσαρος ἀνὴρ ὑπατικὸς ἀποτιμησόμενός τε τὰ ἐν Συρίᾳ καὶ τὸν Ἀρχελάου ἀποδωσόμενος οἶκον."}]},"count":355};a[18]={"book":18,"title":"Τάδε ἔνεστιν ἐν τῇ ιη τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς Κυρίνιος ὑπὸ Καίσαρος ἐπέμφθη τιμητὴς Συρίας καὶ Ἰουδαίας καὶ ἀποδωσόμενος τὴν Ἀρχελάου οὐσίαν.\n\nὡς Κωπώνιος ἐκ τοῦ ἱππικοῦ τάγματος ἐπέμφθη ἔπαρχος Ἰουδαίας.\n\nὡς Ἰούδας ὁ Γαλιλαῖος ἔπεισεν τὸ πλῆθος μὴ ἀπογράψασθαι τὰς οὐσίας, μέχρις Ἰώζαρος ὁ ἀρχιερεὺς ἔπεισεν αὐτοὺς μᾶλλον ὑπακοῦσαι Ῥωμαίοις.\n\nτίνες αἱρέσεις καὶ ὁπόσαι παρὰ Ἰουδαίοις φιλοσόφων καὶ τίνες οἱ νόμοι.\n\nὡς Ἡρώδης καὶ Φίλιππος οἱ τετράρχαι πόλεις ἔκτισαν εἰς τιμὴν Καίσαρος.\n\nὡς Σαμαρεῖς ὀστᾶ νεκρῶν διαρρίψαντες εἰς τὸ ἱερὸν τὸν λαὸν ἑπτὰ ἡμέρας ἐμίαναν.\n\nὡς Σαλώμη ἡ ἀδελφὴ Ἡρώδου τελευτήσασα τὰ αὐτῆς κατέλιπεν Ἰουλίᾳ τῇ τοῦ Καίσαρος γαμετῇ.\n\nὡς Πόντιος Πιλᾶτος ἠθέλησε κρύφα εἰς Ἱεροσόλυμα εἰσενέγκαι προτομὰς Καίσαρος, ὁ δὲ λαὸς οὐ κατεδέξατο στασιάσας.\n\nτὰ συμβάντα Ἰουδαίοις ἐν Ῥώμῃ κατὰ τοῦτον τὸν καιρὸν ὑπὸ τῶν Σαμαρέων.\n\nκατηγορία ὑπὸ Σαμαρέων Πιλάτου ἐπὶ Οὐιτελλίου καὶ ὡς Οὐιτέλλιος ἠνάγκασεν αὐτὸν ἀναβῆναι εἰς Ῥώμην λόγον τῶν πεπραγμένων ἀποδώσοντα.\n\nπόλεμος Ἡρώδου τοῦ τετράρχου πρὸς Ἀρέταν τὸν Ἀράβων βασιλέα καὶ ἧττα.\n\nὡς Τιβέριος Καῖσαρ ἔγραψεν Οὐιτελλίῳ Ἀρταβάνην μὲν τὸν Πάρθον πεῖσαι ὁμήρους αὐτῷ πέμψαι, πρὸς Ἀρέταν δὲ πολεμεῖν.\n\nτελευτὴ Φιλίππου καὶ ὡς ἡ τετραρχία αὐτοῦ ἐπαρχία ἐγένετο.\n\nἀπόπλους Ἀγρίππα εἰς Ῥώμην καὶ ὡς κατηγορηθεὶς ὑπὸ τοῦ ἰδίου ἀπελευθέρου ἐδέθη.\n\nὃν τρόπον ἐλύθη ὑπὸ Γαΐου μετὰ τὴν Τιβερίου τελευτὴν καὶ ἐγένετο βασιλεὺς τῆς Φιλίππου τετραρχίας.\n\nὡς Ἡρώδης ἀναβὰς εἰς Ῥώμην ἐξωρίσθη καὶ ὡς τὴν τετραρχίαν αὐτοῦ ἐδωρήσατο Γάιος Ἀγρίππᾳ.\n\nστάσις τῶν ἐν Ἀλεξανδρείᾳ Ἰουδαίων καὶ Ἑλλήνων καὶ πρεσβεία ἀφ' ἑκατέρων πρὸς Γάιον.\n\nκατηγορία Ἰουδαίων ὑπὸ Ἀπίωνος καὶ τῶν συμπρέσβεων ἐπὶ τῷ μὴ ἔχειν Καίσαρος ἀνδριάντα.\n\nτὴν συμβᾶσαν φθορὰν τοῖς ἐν Βαβυλῶνι Ἰουδαίοις δι' Ἀσιναῖον καὶ Ἀνιλαῖον τοὺς ἀδελφούς.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν λβ."},"chapters":{"1":[{"number":1,"text":"Κυρίνιος δὲ τῶν εἰς τὴν βουλὴν συναγομένων ἀνὴρ τάς τε ἄλλας ἀρχὰς ἐπιτετελεκὼς καὶ διὰ πασῶν ὁδεύσας ὕπατος γενέσθαι τά τε ἄλλα ἀξιώματι μέγας σὺν ὀλίγοις ἐπὶ Συρίας παρῆν, ὑπὸ Καίσαρος δικαιοδότης τοῦ ἔθνους ἀπεσταλμένος καὶ τιμητὴς τῶν οὐσιῶν γενησόμενος,"},{"number":2,"text":"Κωπώνιός τε αὐτῷ συγκαταπέμπεται τάγματος τῶν ἱππέων, ἡγησόμενος Ἰουδαίων τῇ ἐπὶ πᾶσιν ἐξουσίᾳ. παρῆν δὲ καὶ Κυρίνιος εἰς τὴν Ἰουδαίαν προσθήκην τῆς Συρίας γενομένην ἀποτιμησόμενός τε αὐτῶν τὰς οὐσίας καὶ ἀποδωσόμενος τὰ Ἀρχελάου χρήματα."},{"number":3,"text":"οἱ δὲ καίπερ τὸ κατʼ ἀρχὰς ἐν δεινῷ φέροντες τὴν ἐπὶ ταῖς ἀπογραφαῖς ἀκρόασιν ὑποκατέβησαν τοῦ μὴ εἰς πλέον ἐναντιοῦσθαι πείσαντος αὐτοὺς τοῦ ἀρχιερέως Ἰωαζάρου, Βοηθοῦ δὲ οὗτος υἱὸς ἦν. καὶ οἱ μὲν ἡττηθέντες τοῦ Ἰωαζάρου τῶν λόγων ἀπετίμων τὰ χρήματα μηδὲν ἐνδοιάσαντες·"},{"number":4,"text":"Ἰούδας δὲ Γαυλανίτης ἀνὴρ ἐκ πόλεως ὄνομα Γάμαλα Σάδδωκον Φαρισαῖον προσλαβόμενος ἠπείγετο ἐπὶ ἀποστάσει, τήν τε ἀποτίμησιν οὐδὲν ἄλλο ἢ ἄντικρυς δουλείαν ἐπιφέρειν λέγοντες καὶ τῆς ἐλευθερίας ἐπʼ ἀντιλήψει παρακαλοῦντες τὸ ἔθνος·"},{"number":5,"text":"ὡς παρασχὸν μὲν κατορθοῦν εἰς τὸ εὔδαιμον ἀνακειμένης τῆς κτήσεως, σφαλεῖσιν δὲ τοῦ ταύτης περιόντος ἀγαθοῦ τιμὴν καὶ κλέος ποιήσεσθαι τοῦ μεγαλόφρονος, καὶ τὸ θεῖον οὐκ ἄλλως ἢ ἐπὶ συμπράξει τῶν βουλευμάτων εἰς τὸ κατορθοῦν συμπροθυμεῖσθαι μᾶλλον, ἂν μεγάλων ἐρασταὶ τῇ διανοίᾳ καθιστάμενοι μὴ ἐξαφίωνται πόνου τοῦ ἐπʼ αὐτοῖς."},{"number":6,"text":"καὶ ἡδονῇ γὰρ τὴν ἀκρόασιν ὧν λέγοιεν ἐδέχοντο οἱ ἄνθρωποι, προύκοπτεν ἐπὶ μέγα ἡ ἐπιβολὴ τοῦ τολμήματος, κακόν τε οὐκ ἔστιν, οὗ μὴ φυέντος ἐκ τῶνδε τῶν ἀνδρῶν καὶ περαιτέρω τοῦ εἰπεῖν ἀνεπλήσθη τὸ ἔθνος·"},{"number":7,"text":"πολέμων τε ἐπαγωγαῖς οὐχ οἷον τὸ ἄπαυστον τὴν βίαν ἔχειν, καὶ ἀποστέρησιν φίλων, οἳ καὶ ἐπελαφρύνοιεν τὸν πόνον, λῃστηρίων τε μεγάλων ἐπιθέσεσιν καὶ διαφθοραῖς ἀνδρῶν τῶν πρώτων, δόξα μὲν τοῦ ὀρθουμένου τῶν κοινῶν, ἔργῳ δὲ οἰκείων κερδῶν ἐλπίσιν."},{"number":8,"text":"ἐξ ὧν στάσεις τε ἐφύησαν διʼ αὐτὰς καὶ φόνος πολιτικός, ὁ μὲν ἐμφυλίοις σφαγαῖς μανίᾳ τῶν ἀνθρώπων εἴς τε ἀλλήλους καὶ αὑτοὺς χρωμένων ἐπιθυμίᾳ τοῦ μὴ λείπεσθαι τῶν ἀντικαθεστηκότων, ὁ δὲ τῶν πολεμίων, λιμός τε εἰς ὑστάτην ἀνακείμενος ἀναισχυντίαν, καὶ πόλεων ἁλώσεις καὶ κατασκαφαί, μέχρι δὴ καὶ τὸ ἱερὸν τοῦ θεοῦ ἐνείματο πυρὶ τῶν πολεμίων ἥδε ἡ στάσις."},{"number":9,"text":"οὕτως ἄρα ἡ τῶν πατρίων καίνισις καὶ μεταβολὴ μεγάλας ἔχει ῥοπὰς τοῦ ἀπολουμένου τοῖς συνελθοῦσιν, εἴ γε καὶ Ἰούδας καὶ Σάδδωκος τετάρτην φιλοσοφίαν ἐπείσακτον ἡμῖν ἐγείραντες καὶ ταύτης ἐραστῶν εὐπορηθέντες πρός τε τὸ παρὸν θορύβων τὴν πολιτείαν ἐνέπλησαν καὶ τῶν αὖθις κακῶν κατειληφότων ῥίζας ἐφυτεύσαντο τῷ ἀσυνήθει πρότερον φιλοσοφίας τοιᾶσδε·"},{"number":10,"text":"περὶ ἧς ὀλίγα βούλομαι διελθεῖν, ἄλλως τε ἐπεὶ καὶ τῷ κατʼ αὐτῶν σπουδασθέντι τοῖς νεωτέροις ὁ φθόρος τοῖς πράγμασι συνέτυχε."},{"number":11,"text":"Ἰουδαίοις φιλοσοφίαι τρεῖς ἦσαν ἐκ τοῦ πάνυ ἀρχαίου τῶν πατρίων, ἥ τε τῶν Ἐσσηνῶν καὶ ἡ τῶν Σαδδουκαίων, τρίτην δὲ ἐφιλοσόφουν οἱ Φαρισαῖοι λεγόμενοι. καὶ τυγχάνει μέντοι περὶ αὐτῶν ἡμῖν εἰρημένα ἐν τῇ δευτέρᾳ βίβλῳ τοῦ Ἰουδαϊκοῦ πολέμου, μνησθήσομαι δʼ ὅμως καὶ νῦν αὐτῶν ἐπʼ ὀλίγον."},{"number":12,"text":"Οἵ τε γὰρ Φαρισαῖοι τὴν δίαιταν ἐξευτελίζουσιν οὐδὲν ἐς τὸ μαλακώτερον ἐνδιδόντες, ὧν τε ὁ λόγος κρίνας παρέδωκεν ἀγαθῶν ἕπονται τῇ ἡγεμονίᾳ περιμάχητον ἡγούμενοι τὴν φυλακὴν ὧν ὑπαγορεύειν ἠθέλησεν. τιμῆς γε τοῖς ἡλικίᾳ προήκουσιν παραχωροῦσιν οὐδʼ ἐπʼ ἀντιλέξει τῶν εἰσηγηθέντων ταῦτα οἱ θράσει ἐπαιρόμενοι."},{"number":13,"text":"πράσσεσθαί τε εἱμαρμένῃ τὰ πάντα ἀξιοῦντες οὐδὲ τοῦ ἀνθρωπείου τὸ βουλόμενον τῆς ἐπʼ αὐτοῖς ὁρμῆς ἀφαιροῦνται δοκῆσαν τῷ θεῷ κρίσιν γενέσθαι καὶ τῷ ἐκείνης βουλευτηρίῳ καὶ τῶν ἀνθρώπων τῷ ἐθελήσαντι προσχωρεῖν μετʼ ἀρετῆς ἢ κακίας."},{"number":14,"text":"ἀθάνατόν τε ἰσχὺν ταῖς ψυχαῖς πίστις αὐτοῖς εἶναι καὶ ὑπὸ χθονὸς δικαιώσεις τε καὶ τιμὰς οἷς ἀρετῆς ἢ κακίας ἐπιτήδευσις ἐν τῷ βίῳ γέγονεν, καὶ ταῖς μὲν εἱργμὸν ἀίδιον προτίθεσθαι, ταῖς δὲ ῥᾳστώνην τοῦ ἀναβιοῦν."},{"number":15,"text":"καὶ διʼ αὐτὰ τοῖς τε δήμοις πιθανώτατοι τυγχάνουσιν καὶ ὁπόσα θεῖα εὐχῶν τε ἔχεται καὶ ἱερῶν ποιήσεως ἐξηγήσει τῇ ἐκείνων τυγχάνουσιν πρασσόμενα. εἰς τοσόνδε ἀρετῆς αὐτοῖς αἱ πόλεις ἐμαρτύρησαν ἐπιτηδεύσει τοῦ ἐπὶ πᾶσι κρείσσονος ἔν τε τῇ διαίτῃ τοῦ βίου καὶ λόγοις."},{"number":16,"text":"Σαδδουκαίοις δὲ τὰς ψυχὰς ὁ λόγος συναφανίζει τοῖς σώμασι, φυλακῇ δὲ οὐδαμῶς τινων μεταποίησις αὐτοῖς ἢ τῶν νόμων· πρὸς γὰρ τοὺς διδασκάλους σοφίας, ἣν μετίασιν, ἀμφιλογεῖν ἀρετὴν ἀριθμοῦσιν."},{"number":17,"text":"εἰς ὀλίγους δὲ ἄνδρας οὗτος ὁ λόγος ἀφίκετο, τοὺς μέντοι πρώτους τοῖς ἀξιώμασι, πράσσεταί τε ἀπʼ αὐτῶν οὐδὲν ὡς εἰπεῖν· ὁπότε γὰρ ἐπʼ ἀρχὰς παρέλθοιεν, ἀκουσίως μὲν καὶ κατʼ ἀνάγκας, προσχωροῦσι δʼ οὖν οἷς ὁ Φαρισαῖος λέγει διὰ τὸ μὴ ἄλλως ἀνεκτοὺς γενέσθαι τοῖς πλήθεσιν."},{"number":18,"text":"Ἐσσηνοῖς δὲ ἐπὶ μὲν θεῷ καταλείπειν φιλεῖ τὰ πάντα ὁ λόγος, ἀθανατίζουσιν δὲ τὰς ψυχὰς περιμάχητον ἡγούμενοι τοῦ δικαίου τὴν πρόσοδον."},{"number":19,"text":"εἰς δὲ τὸ ἱερὸν ἀναθήματα στέλλοντες θυσίας ἐπιτελοῦσιν διαφορότητι ἁγνειῶν, ἃς νομίζοιεν, καὶ διʼ αὐτὸ εἰργόμενοι τοῦ κοινοῦ τεμενίσματος ἐφʼ αὑτῶν τὰς θυσίας ἐπιτελοῦσιν. βέλτιστοι δὲ ἄλλως ἄνδρες τὸν τρόπον καὶ τὸ πᾶν πονεῖν ἐπὶ γεωργίᾳ τετραμμένοι."},{"number":20,"text":"ἄξιον δʼ αὐτῶν θαυμάσαι παρὰ πάντας τοὺς ἀρετῆς μεταποιουμένους τόδε διὰ τὸ μηδαμῶς ὑπάρξαν Ἑλλήνων ἢ βαρβάρων τισίν, ἀλλὰ μηδʼ εἰς ὀλίγον, ἐκείνοις ἐκ παλαιοῦ συνελθὸν ἐν τῷ ἐπιτηδεύεσθαι μὴ κεκωλῦσθαι· τὰ χρήματά τε κοινά ἐστιν αὐτοῖς, ἀπολαύει δὲ οὐδὲν ὁ πλούσιος τῶν οἰκείων μειζόνως ἢ ὁ μηδʼ ὁτιοῦν κεκτημένος· καὶ τάδε πράσσουσιν ἄνδρες ὑπὲρ τετρακισχίλιοι τὸν ἀριθμὸν ὄντες."},{"number":21,"text":"καὶ οὔτε γαμετὰς εἰσάγονται οὔτε δούλων ἐπιτηδεύουσιν κτῆσιν, τὸ μὲν εἰς ἀδικίαν φέρειν ὑπειληφότες, τὸ δὲ στάσεως ἐνδιδόναι ποίησιν, αὐτοὶ δʼ ἐφʼ ἑαυτῶν ζῶντες διακονίᾳ τῇ ἐπʼ ἀλλήλοις ἐπιχρῶνται."},{"number":22,"text":"ἀποδέκτας δὲ τῶν προσόδων χειροτονοῦντες καὶ ὁπόσα ἡ γῆ φέροι ἄνδρας ἀγαθούς, ἱερεῖς δὲ ἐπὶ ποιήσει σίτου τε καὶ βρωμάτων. ζῶσι δὲ οὐδὲν παρηλλαγμένως, ἀλλʼ ὅτι μάλιστα ἐμφέροντες Δακῶν τοῖς πλείστοις λεγομένοις."},{"number":23,"text":"Τῇ δὲ τετάρτῃ τῶν φιλοσοφιῶν ὁ Γαλιλαῖος Ἰούδας ἡγεμὼν κατέστη, τὰ μὲν λοιπὰ πάντα γνώμῃ τῶν Φαρισαίων ὁμολογούσῃ, δυσνίκητος δὲ τοῦ ἐλευθέρου ἔρως ἐστὶν αὐτοῖς μόνον ἡγεμόνα καὶ δεσπότην τὸν θεὸν ὑπειληφόσιν. θανάτων τε ἰδέας ὑπομένειν παρηλλαγμένας ἐν ὀλίγῳ τίθενται καὶ συγγενῶν τιμωρίας καὶ φίλων ὑπὲρ τοῦ μηδένα ἄνθρωπον προσαγορεύειν δεσπότην."},{"number":24,"text":"ἑωρακόσιν δὲ τοῖς πολλοῖς τὸ ἀμετάλλακτον αὐτῶν τῆς ἐπὶ τοιούτοις ὑποστάσεως περαιτέρω διελθεῖν παρέλιπον· οὐ γὰρ δέδοικα μὴ εἰς ἀπιστίαν ὑποληφθῇ τι τῶν λεγομένων ἐπʼ αὐτοῖς, τοὐναντίον δὲ μὴ ἐλασσόνως τοῦ ἐκείνων καταφρονήματος δεχομένου τὴν ταλαιπωρίαν τῆς ἀλγηδόνος ὁ λόγος ἀφηγῆται."},{"number":25,"text":"ἀνοίᾳ τε τῇ ἐντεῦθεν ἤρξατο νοσεῖν τὸ ἔθνος Γεσσίου Φλώρου, ὃς ἡγεμὼν ἦν, τῇ ἐξουσίᾳ τοῦ ὑβρίζειν ἀπονοήσαντος αὐτοὺς ἀποστῆναι Ῥωμαίων. καὶ φιλοσοφεῖται μὲν Ἰουδαίοις τοσάδε."}],"2":[{"number":26,"text":"Κυρίνιος δὲ τὰ Ἀρχελάου χρήματα ἀποδόμενος ἤδη καὶ τῶν ἀποτιμήσεων πέρας ἐχουσῶν, αἳ ἐγένοντο τριακοστῷ καὶ ἑβδόμῳ ἔτει μετὰ τὴν Ἀντωνίου ἐν Ἀκτίῳ ἧτταν ὑπὸ Καίσαρος, Ἰωάζαρον τὸν ἀρχιερέα καταστασιασθέντα ὑπὸ τῆς πληθύος ἀφελόμενος τὸ ἀξίωμα τῆς τιμῆς Ἄνανον τὸν Σεθὶ καθίσταται ἀρχιερέα."},{"number":27,"text":"Ἡρώδης δὲ καὶ Φίλιππος τετραρχίαν ἑκάτερος τὴν ἑαυτοῦ παρειληφότες καθίσταντο. καὶ Ἡρώδης Σέπφωριν τειχίσας πρόσχημα τοῦ Γαλιλαίου παντὸς ἠγόρευεν αὐτὴν Αὐτοκρατορίδα· Βηθαραμφθᾶ δέ, πόλις καὶ αὐτὴ τυγχάνει, τείχει περιλαβὼν Ἰουλιάδα ἀπὸ τοῦ αὐτοκράτορος προσαγορεύει τῆς γυναικός."},{"number":28,"text":"Φίλιππος δὲ Πανεάδα τὴν πρὸς ταῖς πηγαῖς τοῦ Ἰορδάνου κατασκευάσας ὀνομάζει Καισάρειαν, κώμην δὲ Βηθσαϊδὰ πρὸς λίμνῃ τῇ Γεννησαρίτιδι πόλεως παρασχὼν ἀξίωμα πλήθει τε οἰκητόρων καὶ τῇ ἄλλῃ δυνάμει Ἰουλίᾳ θυγατρὶ τῇ Καίσαρος ὁμώνυμον ἐκάλεσεν."},{"number":29,"text":"Κωπωνίου δὲ τὴν Ἰουδαίαν διέποντος, ὃν ἔφην Κυρινίῳ συνεκπεμφθῆναι, τάδε πράσσεται. τῶν ἀζύμων τῆς ἑορτῆς ἀγομένης, ἣν πάσχα καλοῦμεν, ἐκ μέσης νυκτὸς ἐν ἔθει τοῖς ἱερεῦσιν ἦν ἀνοιγνύναι τοῦ ἱεροῦ τοὺς πυλῶνας."},{"number":30,"text":"καὶ τότε οὖν ἐπεὶ τὸ πρῶτον γίνεται ἡ ἄνοιξις αὐτῶν, ἄνδρες Σαμαρεῖται κρύφα εἰς Ἱεροσόλυμα ἐλθόντες διάρριψιν ἀνθρωπείων ὀστῶν ἐν ταῖς στοαῖς καὶ διὰ παντὸς τοῦ ἱεροῦ ἤρξαντο μὴ πρότερον ἐπὶ τοιούτοις νομίζοντες τά τε ἄλλα διὰ φυλακῆς μείζονος ἦγον τὸ ἱερόν."},{"number":31,"text":"καὶ Κωπώνιος μετʼ οὐ πολὺ εἰς Ῥώμην ἐπαναχωρεῖ, διάδοχος δʼ αὐτῷ τῆς ἀρχῆς παραγίνεται Μᾶρκος Ἀμβιβουχος, ἐφʼ οὗ καὶ Σαλώμη ἡ τοῦ βασιλέως Ἡρώδου ἀδελφὴ μεταστᾶσα Ἰουλίᾳ μὲν Ἰάμνειάν τε καταλείπει καὶ τὴν τοπαρχίαν πᾶσαν, τήν τʼ ἐν τῷ πεδίῳ Φασαηλίδα καὶ Ἀρχελαΐδα, ἔνθα φοινίκων πλείστη φύτευσις καὶ καρπὸς αὐτῶν ἄριστος."},{"number":32,"text":"διαδέχεται δὲ καὶ τοῦτον Ἄννιος Ῥοῦφος, ἐφʼ οὗ δὴ καὶ τελευτᾷ Καῖσαρ, δεύτερος μὲν Ῥωμαίων αὐτοκράτωρ γενόμενος ἑπτὰ δὲ καὶ πεντήκοντα τῆς ἀρχῆς ἔτη, πρὸς οἷς μῆνες ἓξ ἡμέραι δυοῖν πλείονες, τούτου δὲ αὐτῷ τοῦ χρόνου δεκατέσσαρα ἔτη συνῆρξεν Ἀντώνιος, βιώσας ἔτη ἑβδομηκονταεπτά."},{"number":33,"text":"διαδέχεται δὲ τῷ Καίσαρι τὴν ἡγεμονίαν Τιβέριος Νέρων γυναικὸς αὐτοῦ Ἰουλίας υἱὸς ὤν, τρίτος ἤδη οὗτος αὐτοκράτωρ, καὶ πεμπτὸς ὑπʼ αὐτοῦ παρῆν Ἰουδαίοις ἔπαρχος διάδοχος Ἀννίῳ Ῥούφῳ Οὐαλέριος Γρᾶτος·"},{"number":34,"text":"ὃς παύσας ἱερᾶσθαι Ἄνανον Ἰσμάηλον ἀρχιερέα ἀποφαίνει τὸν τοῦ Φαβί, καὶ τοῦτον δὲ μετʼ οὐ πολὺ μεταστήσας Ἐλεάζαρον τὸν Ἀνάνου τοῦ ἀρχιερέως υἱὸν ἀποδείκνυσιν ἀρχιερέα. ἐνιαυτοῦ δὲ διαγενομένου καὶ τόνδε παύσας Σίμωνι τῷ Καμίθου τὴν ἀρχιερωσύνην παραδίδωσιν."},{"number":35,"text":"οὐ πλείων δὲ καὶ τῷδε ἐνιαυτοῦ τὴν τιμὴν ἔχοντι διεγένετο χρόνος, καὶ Ἰώσηπος ὁ καὶ Καϊάφας διάδοχος ἦν αὐτῷ. καὶ Γρᾶτος μὲν ταῦτα πράξας εἰς Ῥώμην ἐπανεχώρει ἕνδεκα ἔτη διατρίψας ἐν Ἰουδαίᾳ, Πόντιος δὲ Πιλᾶτος διάδοχος αὐτῷ ἧκεν."},{"number":36,"text":"Ἡρώδης δὲ ὁ τετράρχης, ἐπὶ μέγα γὰρ ἦν τῷ Τιβερίῳ φιλίας προελθών, οἰκοδομεῖται πόλιν ἐπώνυμον αὐτῷ Τιβεριάδα τοῖς κρατίστοις ἐπικτίσας αὐτὴν τῆς Γαλιλαίας ἐπὶ λίμνῃ τῇ Γεννησαρίτιδι. θερμά τε οὐκ ἄπωθέν ἐστιν ἐν κώμῃ, Ἀμμαθοὺς ὄνομα αὐτῇ."},{"number":37,"text":"σύγκλυδες δὲ ᾤκισαν, οὐκ ὀλίγον δὲ καὶ τὸ Γαλιλαῖον ἦν, καὶ ὅσοι μὲν ἐκ τῆς ὑπʼ αὐτῷ γῆς ἀναγκαστοὶ καὶ πρὸς βίαν εἰς τὴν κατοικίαν ἀγόμενοι, τινὲς δὲ καὶ τῶν ἐν τέλει. ἐδέξατο δὲ αὐτοῖς συνοίκους καὶ τοὺς πανταχόθεν ἐπισυναγομένους ἄνδρας ἀπόρους,"},{"number":38,"text":"ἔστι δʼ οὓς μηδὲ σαφῶς ἐλευθέρους, πολλά τε αὐτοὺς κἀπὶ πολλοῖς ἠλευθέρωσεν καὶ εὐηργέτησεν ἀνάγκασμα τοῦ μὴ ἀπολείψειν τὴν πόλιν ἐπιθείς, κατασκευαῖς τε οἰκήσεων τέλεσι τοῖς αὐτοῦ καὶ γῆς ἐπιδόσει, εἰδὼς παράνομον τὸν οἰκισμὸν ὄντα καὶ ἀπὸ τοῦ Ἰουδαίοις πατρίου διὰ τὸ ἐπὶ μνήμασιν, ἃ πολλὰ τῇδε ἦν, ἀνῃρημένοις τὴν ἵδρυσιν τῇ Τιβεριάδι γενέσθαι· μιαροὺς δὲ ἐπὶ ἑπτὰ ἡμέρας εἶναι τοὺς οἰκήτορας ἀγορεύει ἡμῖν τὸ νόμιμον."},{"number":39,"text":"Τελευτᾷ δὲ καὶ Φραάτης ὁ Παρθυαίων βασιλεὺς κατὰ τοῦτον τὸν χρόνον ἐπιβουλῆς αὐτῷ γενομένης ὑπὸ Φραατάκου τοῦ υἱέος κατὰ τοιαύτην αἰτίαν."},{"number":40,"text":"Φραάτης παίδων αὐτῷ γενομένων γνησίων Ἰταλικῆς παιδίσκης ὄνομα αὐτῇ Θεσμοῦσα. ταύτῃ ὑπὸ Ἰουλίου Καίσαρος μετʼ ἄλλων δωρεῶν ἀπεσταλμένῃ τὸ μὲν πρῶτον παλλακίδι ἐχρῆτο, καταπλαγεὶς δὲ τῷ πολλῷ τῆς εὐμορφίας προϊόντος τοῦ χρόνου καὶ παιδὸς αὐτῇ τοῦ Φραατάκου γενομένου γαμετήν τε τὴν ἄνθρωπον ἀποφαίνεται καὶ τιμίαν ἦγεν."},{"number":41,"text":"ἐπὶ πᾶσιν οἷς εἴποι πιθανὴ τῷ βασιλεῖ γεγονυῖα καὶ σπεύδουσα τῷ παιδὶ τῷ αὐτῆς γενέσθαι τὴν Πάρθων ἡγεμονίαν ἑώρα μὴ ἄλλως γενησομένην μὴ ἀποσκευῆς αὐτῇ μηχανηθείσης τῶν γνησίων τοῦ Φραάτου παίδων."},{"number":42,"text":"πείθει οὖν αὐτὸν ἐκπέμπειν εἰς Ῥώμην ἐφʼ ὁμηρείᾳ τοὺς γνησίους παῖδας. καὶ οὗτοι μέν, οὐ γὰρ ἀντειπεῖν εὔπορον Φραάτῃ τοῖς Θεσμούσης ἐπιτάγμασιν, ἐπὶ τῆς Ῥώμης ἐξεπέμποντο. Φραατάκης δὲ μόνος ἐπὶ τοῖς πράγμασι τρεφόμενος δεινὸν ἡγεῖτο καὶ ἅμα χρόνιον τοῦ πατρὸς διδόντος τὴν ἀρχὴν λαμβάνειν, ὥστε ἐπεβούλευε τῷ πατρὶ συμπράξει τῆς μητρός, ᾗ δὴ καὶ συνιέναι λόγος εἶχεν αὐτόν."},{"number":43,"text":"καὶ διʼ ἀμφότερα μισηθεὶς οὐδὲν ἡσσόνως τῆς πατροκτονίας τὸ μῦσος τοῦ μητρὸς ἔρωτος τιθεμένων τῶν ὑπηκόων, στάσει περιελαθεὶς πρότερον ἢ φῦναι μέγας ἐξέπεσε τῶν πραγμάτων καὶ οὕτως θνήσκει."},{"number":44,"text":"συμφρονήσαντες δὲ οἱ γενναιότατοι Πάρθων, ὡς ἀβασιλεύτοις μὲν ἀμήχανον πολιτεύεσθαι, οἱ δὲ τοῦ βασιλεύοντος ἐκ τοῦ γένους τῶν Ἀρσακιδῶν, οὐ γὰρ ἑτέροις ἄρχειν νόμιμον, ἀπέχρη δὲ πολλάκις καὶ μέχρι νῦν περιυβρίσθαι τὴν βασιλείαν ἔκ τε γάμων τῆς Ἰταλικῆς παλλακίδος καὶ γενέσεων, Ὀρώδην ἐκάλουν πρεσβεύσαντες εἰς δάν, ἄλλως μὲν ἐπίφθονον τῷ πλήθει καὶ ὑπαίτιον καθʼ ὑπερβολὰς ὠμότητος, πάνυ γὰρ ἦν σκαιὸς καὶ δυσδιάθετος εἰς ὀργήν, ἕνα δὲ τῶν ἐκ τοῦ γένους."},{"number":45,"text":"τοῦτον μὲν δὴ συστάντες ἀποκτείνουσιν, ὡς μὲν ἔνιοί φασιν, ἐν σπονδαῖς καὶ τραπέζαις, μαχαιροφορεῖν γὰρ ἔθος ἅπασιν, ὡς δʼ ὁ πλείων κατέχει λόγος, εἰς θήραν προαγαγόντες."},{"number":46,"text":"πρεσβεύσαντες δὲ εἰς Ῥώμην ᾐτοῦντο βασιλέα τῶν ὁμηρευόντων, καὶ πέμπεται Βονώνης προκριθεὶς τῶν ἀδελφῶν· ἐδόκει γὰρ χωρεῖν τὴν τύχην, ἣν αὐτῷ δύο μέγισται τῶν ὑπὸ τὸν ἥλιον ἡγεμονίαι προσέφερον, ἰδία καὶ ἀλλοτρία."},{"number":47,"text":"ταχεῖα δʼ ἀνατροπὴ τοὺς βαρβάρους ὕπεισιν ἅτε καὶ φύσει σφαλεροὺς ὄντας πρός τε τὴν ἀναξιοπάθειαν, ἀνδραπόδῳ γὰρ ἀλλοτρίῳ ποιήσειν τὸ προστασσόμενον ἠξίουν, τὴν ὁμηρείαν ἀντὶ δουλείας ὀνομάζοντες, καὶ τῆς ἐπικλήσεως τὴν ἀδοξίαν· οὐ γὰρ ἂν πολέμου δικαίῳ δεδόσθαι τὸν βασιλεύσοντα Πάρθοις, ἀλλά, ὃ τῷ παντὶ χεῖρον, εἰρήνης ὕβρει."},{"number":48,"text":"παραχρῆμα δʼ ἐκάλουν Ἀρτάβανον Μηδίας βασιλεύοντα γένος Ἀρσακίδην· πείθεται δʼ Ἀρτάβανος καὶ μετὰ στρατιᾶς ἔπεισιν. ὑπαντιάζει δʼ αὐτῷ Βονώνης· καὶ τὸ μὲν πρῶτον συμφρονήσαντος αὐτῷ τοῦ πλήθους τῶν Πάρθων παραταξάμενος νικᾷ, καὶ φεύγει πρὸς τοὺς ὅρους τῆς Μηδίας Ἀρτάβανος."},{"number":49,"text":"μετʼ οὐ πολὺ δὲ συναγαγὼν συμβάλλει τε Βονώνῃ καὶ νικᾷ, καὶ Βονώνης εἰς Σελεύκειαν ἀφιππάζεται σὺν ὀλίγοις τοῖς περὶ αὐτόν. Ἀρτάβανος δὲ πολὺν τῇ τροπῇ φόνον ἐργασάμενος ὑπὲρ ἐκπλήξεως τῶν βαρβάρων πρὸς Κτησιφῶντα μετὰ τοῦ πλήθους ἀναχωρεῖ."},{"number":50,"text":"κἀκεῖνος μὲν ἐβασίλευεν ἤδη Πάρθοις, Βονώνης δʼ εἰς Ἀρμενίαν διαπίπτει, καὶ κατʼ ἀρχὰς μὲν ἐφίετο τῆς χώρας καὶ πρὸς Ῥωμαίους ἐπρέσβευεν."},{"number":51,"text":"ὡς δʼ αὐτῷ Τιβέριος μὲν ἀπεῖπεν πρός τε τὴν ἀνανδρίαν καὶ τοῦ Πάρθου τὰς ἀπειλάς, ἀναπρεσβεύει γὰρ δὴ πόλεμον ἀνατεινόμενος, μηχανὴ δʼ ἦν ἑτέρας βασιλείας οὐδεμία, καὶ γὰρ οἱ περὶ Νιφάτην δυνατοὶ τῶν Ἀρμενίων Ἀρταβάνῳ προστίθενται,"},{"number":52,"text":"παραδίδωσιν αὑτὸν Σιλανῷ τῷ τῆς Συρίας στρατηγῷ. κἀκεῖνος μὲν κατὰ αἰδῶ τῆς ἐν Ῥώμῃ κομιδῆς ἐν Συρίᾳ παρεφυλάσσετο· τὴν δὲ Ἀρμενίαν Ὀρώδῃ δίδωσιν Ἀρτάβανος ἑνὶ τῶν ἑαυτοῦ παίδων."},{"number":53,"text":"Ἐτελεύτησεν δὲ καὶ ὁ τῆς Κομμαγηνῆς βασιλεὺς Ἀντίοχος, διέστη δὲ τὸ πλῆθος πρὸς τοὺς γνωρίμους καὶ πρεσβεύουσιν ἀφʼ ἑκατέρου μέρους, οἱ μὲν δυνατοὶ μεταβάλλειν τὸ σχῆμα τῆς πολιτείας εἰς ἐπαρχίαν ἀξιοῦντες, τὸ πλῆθος δὲ βασιλεύεσθαι κατὰ τὰ πάτρια."},{"number":54,"text":"καὶ ψηφίζεται ἡ σύγκλητος Γερμανικὸν πέμπειν διορθώσοντα τὰ κατὰ τὴν ἀνατολὴν πραγματευομένης αὐτῷ τῆς τύχης εὐκαιρίαν τοῦ θανάτου· καὶ γὰρ γενόμενος κατὰ τὴν ἀνατολὴν καὶ πάντα διορθώσας ἀνῃρέθη φαρμάκῳ ὑπὸ Πείσωνος, καθὼς ἐν ἄλλοις δεδήλωται."}],"3":[{"number":55,"text":"Πιλᾶτος δὲ ὁ τῆς Ἰουδαίας ἡγεμὼν στρατιὰν ἐκ Καισαρείας ἀγαγὼν καὶ μεθιδρύσας χειμαδιοῦσαν ἐν Ἱεροσολύμοις ἐπὶ καταλύσει τῶν νομίμων τῶν Ἰουδαϊκῶν ἐφρόνησε, προτομὰς Καίσαρος, αἳ ταῖς σημαίαις προσῆσαν, εἰσαγόμενος εἰς τὴν πόλιν, εἰκόνων ποίησιν ἀπαγορεύοντος ἡμῖν τοῦ νόμου."},{"number":56,"text":"καὶ διὰ τοῦτο οἱ πρότερον ἡγεμόνες ταῖς μὴ μετὰ τοιῶνδε κόσμων σημαίαις ἐποιοῦντο εἴσοδον τῇ πόλει. πρῶτος δὲ Πιλᾶτος ἀγνοίᾳ τῶν ἀνθρώπων διὰ τὸ νύκτωρ γενέσθαι τὴν εἴσοδον ἱδρύεται τὰς εἰκόνας φέρων εἰς τὰ Ἱεροσόλυμα."},{"number":57,"text":"οἱ δʼ ἐπεὶ ἔγνωσαν κατὰ πληθὺν παρῆσαν εἰς Καισάρειαν ἱκετείαν ποιούμενοι ἐπὶ πολλὰς ἡμέρας ἐπὶ μεταθέσει τῶν εἰκόνων. καὶ μὴ συγχωροῦντος διὰ τὸ εἰς ὕβριν Καίσαρι φέρειν, ἐπείπερ οὐκ ἐξανεχώρουν λιπαρεῖν κατὰ ἕκτην ἡμέραν ἐν ὅπλοις ἀφανῶς ἐπικαθίσας τὸ στρατιωτικὸν αὐτὸς ἐπὶ τὸ βῆμα ἧκεν. τὸ δʼ ἐν τῷ σταδίῳ κατεσκεύαστο, ὅπερ ἀπέκρυπτε τὸν ἐφεδρεύοντα στρατόν."},{"number":58,"text":"πάλιν δὲ τῶν Ἰουδαίων ἱκετείᾳ χρωμένων ἀπὸ συνθήματος περιστήσας τοὺς στρατιώτας ἠπείλει θάνατον ἐπιθήσειν ζημίαν ἐκ τοῦ ὀξέος, εἰ μὴ παυσάμενοι θορυβεῖν ἐπὶ τὰ οἰκεῖα ἀπίοιεν."},{"number":59,"text":"οἱ δὲ πρηνεῖς ῥίψαντες ἑαυτοὺς καὶ γυμνοῦντες τὰς σφαγὰς ἡδονῇ δέξασθαι τὸν θάνατον ἔλεγον ἢ τολμήσειν τὴν σοφίαν παραβήσεσθαι τῶν νόμων. καὶ Πιλᾶτος θαυμάσας τὸ ἐχυρὸν αὐτῶν ἐπὶ φυλακῇ τῶν νόμων παραχρῆμα τὰς εἰκόνας ἐκ τῶν Ἱεροσολύμων ἐπανεκόμισεν εἰς Καισάρειαν."},{"number":60,"text":"Ὑδάτων δὲ ἐπαγωγὴν εἰς τὰ Ἱεροσόλυμα ἔπραξεν δαπάνῃ τῶν ἱερῶν χρημάτων ἐκλαβὼν τὴν ἀρχὴν τοῦ ῥεύματος ὅσον ἀπὸ σταδίων διακοσίων, οἱ δʼ οὐκ ἠγάπων τοῖς ἀμφὶ τὸ ὕδωρ δρωμένοις πολλαί τε μυριάδες ἀνθρώπων συνελθόντες κατεβόων αὐτοῦ παύσασθαι τοῦ ἐπὶ τοιούτοις προθυμουμένου, τινὲς δὲ καὶ λοιδορίᾳ χρώμενοι ὕβριζον εἰς τὸν ἄνδρα, οἷα δὴ φιλεῖ πράσσειν ὅμιλος."},{"number":61,"text":"ὁ δὲ στολῇ τῇ ἐκείνων πολὺ πλῆθος στρατιωτῶν ἀμπεχόμενον, οἳ ἐφέροντο σκυτάλας ὑπὸ ταῖς στολαῖς, διαπέμψας εἰς ὃ περιέλθοιεν αὐτούς, αὐτὸς ἐκέλευσεν ἀναχωρεῖν. τῶν δὲ ὡρμηκότων εἰς τὸ λοιδορεῖν ἀποδίδωσι τοῖς στρατιώταις ὃ προσυνέκειτο σημεῖον."},{"number":62,"text":"οἱ δὲ καὶ πολὺ μειζόνως ἤπερ ἐπέταξεν Πιλᾶτος ἐχρῶντο πληγαῖς τούς τε θορυβοῦντας ἐν ἴσῳ καὶ μὴ κολάζοντες οἱ δʼ εἰσεφέροντο μαλακὸν οὐδέν, ὥστε ἄοπλοι ληφθέντες ὑπʼ ἀνδρῶν ἐκ παρασκευῆς ἐπιφερομένων πολλοὶ μὲν αὐτῶν ταύτῃ καὶ ἀπέθνησκον, οἱ δὲ καὶ τραυματίαι ἀνεχώρησαν. καὶ οὕτω παύεται ἡ στάσις."},{"number":63,"text":"Γίνεται δὲ κατὰ τοῦτον τὸν χρόνον Ἰησοῦς σοφὸς ἀνήρ, εἴγε ἄνδρα αὐτὸν λέγειν χρή· ἦν γὰρ παραδόξων ἔργων ποιητής, διδάσκαλος ἀνθρώπων τῶν ἡδονῇ τἀληθῆ δεχομένων, καὶ πολλοὺς μὲν Ἰουδαίους, πολλοὺς δὲ καὶ τοῦ Ἑλληνικοῦ ἐπηγάγετο· ὁ χριστὸς οὗτος ἦν."},{"number":64,"text":"καὶ αὐτὸν ἐνδείξει τῶν πρώτων ἀνδρῶν παρʼ ἡμῖν σταυρῷ ἐπιτετιμηκότος Πιλάτου οὐκ ἐπαύσαντο οἱ τὸ πρῶτον ἀγαπήσαντες· ἐφάνη γὰρ αὐτοῖς τρίτην ἔχων ἡμέραν πάλιν ζῶν τῶν θείων προφητῶν ταῦτά τε καὶ ἄλλα μυρία περὶ αὐτοῦ θαυμάσια εἰρηκότων. εἰς ἔτι τε νῦν τῶν Χριστιανῶν ἀπὸ τοῦδε ὠνομασμένον οὐκ ἐπέλιπε τὸ φῦλον."},{"number":65,"text":"Καὶ ὑπὸ τοὺς αὐτοὺς χρόνους ἕτερόν τι δεινὸν ἐθορύβει τοὺς Ἰουδαίους καὶ περὶ τὸ ἱερὸν τῆς Ἴσιδος τὸ ἐν Ῥώμῃ πράξεις αἰσχυνῶν οὐκ ἀπηλλαγμέναι συντυγχάνουσιν. καὶ πρότερον τοῦ τῶν Ἰσιακῶν τολμήματος μνήμην ποιησάμενος οὕτω μεταβιβῶ τὸν λόγον ἐπὶ τὰ ἐν τοῖς Ἰουδαίοις γεγονότα."},{"number":66,"text":"Παυλῖνα ἦν τῶν ἐπὶ Ῥώμης προγόνων τε ἀξιώματι τῶν καθʼ ἑαυτὴν ἐπιτηδεύοντι κόσμον ἀρετῆς ἐπὶ μέγα προϊοῦσα τῷ ὀνόματι, δύναμίς τε αὐτῇ χρημάτων ἦν καὶ γεγονυῖα τὴν ὄψιν εὐπρεπὴς καὶ τῆς ὥρας ἐν ᾗ μάλιστα ἀγάλλονται αἱ γυναῖκες εἰς τὸ σωφρονεῖν ἀνέκειτο ἡ ἐπιτήδευσις τοῦ βίου. ἐγεγάμητο δὲ Σατορνίνῳ τῶν εἰς τὰ πάντα ἀντισουμένων τῷ περὶ αὐτὴν ἀξιολόγῳ."},{"number":67,"text":"ταύτης ἐρᾷ Δέκιος Μοῦνδος τῶν τότε ἱππέων ἐν ἀξιώματι μεγάλῳ, καὶ μείζονα οὖσαν ἁλῶναι δώροις διὰ τὸ καὶ πεμφθέντων εἰς πλῆθος περιιδεῖν ἐξῆπτο μᾶλλον, ὥστε καὶ εἴκοσι μυριάδας δραχμῶν Ἀτθίδων ὑπισχνεῖτο εὐνῆς μιᾶς."},{"number":68,"text":"καὶ μηδʼ ὣς ἐπικλωμένης, οὐ φέρων τὴν ἀτυχίαν τοῦ ἔρωτος ἐνδείᾳ σιτίων θάνατον ἐπιτιμᾶν αὑτῷ καλῶς ἔχειν ἐνόμισεν ἐπὶ παύλῃ κακοῦ τοῦ κατειληφότος. καὶ ὁ μὲν ἐπεψήφιζέν τε τῇ οὕτω τελευτῇ καὶ πράσσειν οὐκ ἀπηλλάσσετο."},{"number":69,"text":"καὶ ἦν γὰρ ὄνομα Ἴδη πατρῷος ἀπελευθέρα τῷ Μούνδῳ παντοίων ἴδρις κακῶν, δεινῶς φέρουσα τοῦ νεανίσκου τῷ ψηφίσματι τοῦ θανεῖν, οὐ γὰρ ἀφανὴς ἦν ἀπολούμενος, ἀνεγείρει τε αὐτὸν ἀφικομένη διὰ λόγου πιθανή τε ἦν ἐλπίδων τινῶν ὑποσχέσεσιν, ὡς διαπραχθησομένων ὁμιλιῶν πρὸς τὴν Παυλῖναν αὐτῷ."},{"number":70,"text":"καὶ δεχομένου τὴν ἱκετείαν ἡδονῇ πέντε μυριάδων δεήσειν αὐτῇ μόνων ἔλεγεν ἐπὶ ἁλώσει τῆς γυναικός. καὶ ἡ μὲν ἐπὶ τούτοις ἀνεγείρασα τὸν νεανίσκον καὶ τὸ αἰτηθὲν λαβοῦσα ἀργύριον οὐ τὰς αὐτὰς ὁδοὺς ἐστέλλετο τοῖς προδεδιακονημένοις ὁρῶσα τῆς γυναικὸς τὸ μηδαμῶς χρημάτων ἁλισκόμενον, εἰδυῖα δὲ αὐτὴν θεραπείᾳ τῆς Ἴσιδος σφόδρα ὑπηγμένην τεχνᾶταί τι τοιόνδε."},{"number":71,"text":"τῶν ἱερέων τισὶν ἀφικομένη διὰ λόγων ἐπὶ πίστεσιν μεγάλαις τὸ δὲ μέγιστον δόσει χρημάτων τὸ μὲν παρὸν μυριάδων δυοῖν καὶ ἡμίσει, λαβόντος δʼ ἔκβασιν τοῦ πράγματος ἑτέρῳ τοσῷδε, διασαφεῖ τοῦ νεανίσκου τὸν ἔρωτα αὐτοῖς, κελεύουσα παντοίως ἐπὶ τῷ ληψομένῳ τὴν ἄνθρωπον σπουδάσαι."},{"number":72,"text":"οἱ δʼ ἐπὶ πληγῇ τοῦ χρυσίου παραχθέντες ὑπισχνοῦντο. καὶ αὐτῶν ὁ γεραίτατος ὡς τὴν Παυλῖναν ὠσάμενος γενομένων εἰσόδων καταμόνας διὰ λόγων ἐλθεῖν ἠξίου. καὶ συγχωρηθὲν πεμπτὸς ἔλεγεν ἥκειν ὑπὸ τοῦ Ἀνούβιδος ἔρωτι αὐτῆς ἡσσημένου τοῦ θεοῦ κελεύοντός τε ὡς αὐτὸν ἐλθεῖν."},{"number":73,"text":"τῇ δὲ εὐκτὸς ὁ λόγος ἦν καὶ ταῖς τε φίλαις ἐνεκαλλωπίζετο τῇ ἐπὶ τοιούτοις ἀξιώσει τοῦ Ἀνούβιδος καὶ φράζει πρὸς τὸν ἄνδρα, δεῖπνόν τε αὐτῇ καὶ εὐνὴν τοῦ Ἀνούβιδος εἰσηγγέλθαι, συνεχώρει δʼ ἐκεῖνος τὴν σωφροσύνην τῆς γυναικὸς ἐξεπιστάμενος."},{"number":74,"text":"χωρεῖ οὖν εἰς τὸ τέμενος, καὶ δειπνήσασα, ὡς ὕπνου καιρὸς ἦν, κλεισθεισῶν τῶν θυρῶν ὑπὸ τοῦ ἱερέως ἔνδον ἐν τῷ νεῷ καὶ τὰ λύχνα ἐκποδὼν ἦν καὶ ὁ Μοῦνδος, προεκέκρυπτο γὰρ τῇδε, οὐχ ἡμάρτανεν ὁμιλιῶν τῶν πρὸς αὐτήν, παννύχιόν τε αὐτῷ διηκονήσατο ὑπειληφυῖα θεὸν εἶναι."},{"number":75,"text":"καὶ ἀπελθόντος πρότερον ἢ κίνησιν ἄρξασθαι τῶν ἱερέων, οἳ τὴν ἐπιβουλὴν ᾔδεσαν, ἡ Παυλῖνα πρωῒ ὡς τὸν ἄνδρα ἐλθοῦσα τὴν ἐπιφάνειαν ἐκδιηγεῖται τοῦ Ἀνούβιδος καὶ πρὸς τὰς φίλας ἐνελαμπρύνετο λόγοις τοῖς ἐπʼ αὐτῷ."},{"number":76,"text":"οἱ δὲ τὰ μὲν ἠπίστουν εἰς τὴν φύσιν τοῦ πράγματος ὁρῶντες, τὰ δʼ ἐν θαύματι καθίσταντο οὐκ ἔχοντες, ὡς χρὴ ἄπιστα αὐτὰ κρίνειν, ὁπότε εἴς τε τὴν σωφροσύνην καὶ τὸ ἀξίωμα ἀπίδοιεν αὐτῆς."},{"number":77,"text":"τρίτῃ δὲ ἡμέρᾳ μετὰ τὴν πρᾶξιν ὑπαντιάσας αὐτὴν ὁ Μοῦνδος Παυλῖνα, φησίν, ἀλλά μοι καὶ εἴκοσι μυριάδας διεσώσω δυναμένη οἴκῳ προσθέσθαι τῷ σαυτῆς διακονεῖσθαί τε ἐφʼ οἷς προεκαλούμην οὐκ ἐνέλιπες. ἃ μέντοι εἰς Μοῦνδον ὑβρίζειν ἐπειρῶ, μηδέν μοι μελῆσαν τῶν ὀνομάτων, ἀλλὰ τῆς ἐκ τοῦ πράγματος ἡδονῆς, Ἀνούβιον ὄνομα ἐθέμην αὐτῷ."},{"number":78,"text":"καὶ ὁ μὲν ἀπῄει ταῦτα εἰπών, ἡ δὲ εἰς ἔννοιαν τότε πρῶτον ἐλθοῦσα τοῦ τολμήματος περιρρήγνυταί τε τὴν στολὴν καὶ τἀνδρὶ δηλώσασα τοῦ παντὸς ἐπιβουλεύματος τὸ μέγεθος ἐδεῖτο μὴ περιῶφθαι βοηθείας τυγχάνειν·"},{"number":79,"text":"ὁ δὲ τῷ αὐτοκράτορι ἐπεσήμηνε τὴν πρᾶξιν. καὶ ὁ Τιβέριος μαθήσεως ἀκριβοῦς αὐτῷ γενομένης ἐξετάσει τῶν ἱερέων ἐκείνους τε ἀνεσταύρωσεν καὶ τὴν Ἴδην ὀλέθρου γενομένην αἰτίαν καὶ τὰ πάντα ἐφʼ ὕβρει συνθεῖσαν τῆς γυναικός, τόν τε ναὸν καθεῖλεν καὶ τὸ ἄγαλμα τῆς Ἴσιδος εἰς τὸν Θύβριν ποταμὸν ἐκέλευσεν ἐμβαλεῖν. Μοῦνδον δὲ φυγῆς ἐτίμησε,"},{"number":80,"text":"κώλυμα τοῦ μὴ μειζόνως κολάζειν τὸ μετὰ ἔρωτος αὐτῷ ἡμαρτῆσθαι τὰ ἡμαρτημένα ἡγησάμενος. καὶ τὰ μὲν περὶ τὸ ἱερὸν τῆς Ἴσιδος τοῖς ἱερεῦσιν ὑβρισμένα τοιαῦτα ἦν. ἐπάνειμι δὲ ἐπὶ τὴν ἀφήγησιν τῶν ἐν Ῥώμῃ Ἰουδαίοις κατὰ τοῦτον τὸν χρόνον συντυχόντων, ὥς μοι καὶ προαπεσήμηνεν ὁ λόγος."},{"number":81,"text":"Ἦν ἀνὴρ Ἰουδαῖος, φυγὰς μὲν τῆς αὐτοῦ κατηγορίᾳ τε παραβάσεων νόμων τινῶν καὶ δέει τιμωρίας τῆς ἐπʼ αὐτοῖς, πονηρὸς δὲ εἰς τὰ πάντα. καὶ δὴ τότε ἐν τῇ Ῥώμῃ διαιτώμενος προσεποιεῖτο μὲν ἐξηγεῖσθαι σοφίαν νόμων τῶν Μωυσέως,"},{"number":82,"text":"προσποιησάμενος δὲ τρεῖς ἄνδρας εἰς τὰ πάντα ὁμοιοτρόπους τούτοις ἐπιφοιτήσασαν Φουλβίαν τῶν ἐν ἀξιώματι γυναικῶν καὶ νομίμοις προσεληλυθυῖαν τοῖς Ἰουδαϊκοῖς πείθουσι πορφύραν καὶ χρυσὸν εἰς τὸ ἐν Ἱεροσολύμοις ἱερὸν διαπέμψασθαι, καὶ λαβόντες ἐπὶ χρείας τοῖς ἰδίοις ἀναλώμασιν αὐτὰ ποιοῦνται, ἐφʼ ὅπερ καὶ τὸ πρῶτον ἡ αἴτησις ἐπράσσετο."},{"number":83,"text":"καὶ ὁ Τιβέριος, ἀποσημαίνει γὰρ πρὸς αὐτὸν φίλος ὢν Σατορνῖνος τῆς Φουλβίας ἀνὴρ ἐπισκήψει τῆς γυναικός, κελεύει πᾶν τὸ Ἰουδαϊκὸν τῆς Ῥώμης ἀπελθεῖν."},{"number":84,"text":"οἱ δὲ ὕπατοι τετρακισχιλίους ἀνθρώπους ἐξ αὐτῶν στρατολογήσαντες ἔπεμψαν εἰς Σαρδὼ τὴν νῆσον, πλείστους δὲ ἐκόλασαν μὴ θέλοντας στρατεύεσθαι διὰ φυλακὴν τῶν πατρίων νόμων. καὶ οἱ μὲν δὴ διὰ κακίαν τεσσάρων ἀνδρῶν ἠλαύνοντο τῆς πόλεως."}],"4":[{"number":85,"text":"Οὐκ ἀπήλλακτο δὲ θορύβου καὶ τὸ Σαμαρέων ἔθνος· συστρέφει γὰρ αὐτοὺς ἀνὴρ ἐν ὀλίγῳ τὸ ψεῦδος τιθέμενος κἀφʼ ἡδονῇ τῆς πληθύος τεχνάζων τὰ πάντα, κελεύων ἐπὶ τὸ Γαριζεὶν ὄρος αὐτῷ συνελθεῖν, ὃ ἁγνότατον αὐτοῖς ὀρῶν ὑπείληπται, ἰσχυρίζετό τε παραγενομένοις δείξειν τὰ ἱερὰ σκεύη τῇδε κατορωρυγμένα Μωυσέως τῇδε αὐτῶν ποιησαμένου κατάθεσιν."},{"number":86,"text":"οἱ δὲ ἐν ὅπλοις τε ἦσαν πιθανὸν ἡγούμενοι τὸν λόγον, καὶ καθίσαντες ἔν τινι κώμῃ, Τιραθανὰ λέγεται, παρελάμβανον τοὺς ἐπισυλλεγομένους ὡς μεγάλῳ πλήθει τὴν ἀνάβασιν εἰς τὸ ὄρος ποιησόμενοι."},{"number":87,"text":"φθάνει δὲ Πιλᾶτος τὴν ἄνοδον αὐτῶν προκαταλαβόμενος ἱππέων τε πομπῇ καὶ ὁπλιτῶν, οἳ συμβαλόντες τοῖς ἐν τῇ κώμῃ προσυνηθροισμένοις παρατάξεως γενομένης τοὺς μὲν ἔκτειναν, τοὺς δʼ εἰς φυγὴν τρέπονται ζωγρίᾳ τε πολλοὺς ἦγον, ὧν τοὺς κορυφαιοτάτους καὶ τοὺς ἐν τοῖς φυγοῦσι δυνατωτάτους ἔκτεινε Πιλᾶτος."},{"number":88,"text":"Καταστάντος δὲ τοῦ θορύβου Σαμαρέων ἡ βουλὴ παρὰ Οὐιτέλλιον ὑπατικὸν ἴασιν ἄνδρα Συρίας τὴν ἡγεμονίαν ἔχοντα καὶ Πιλάτου κατηγόρουν ἐπὶ τῇ σφαγῇ τῶν ἀπολωλότων· οὐ γὰρ ἐπὶ ἀποστάσει τῶν Ῥωμαίων, ἀλλʼ ἐπὶ διαφυγῇ τῆς Πιλάτου ὕβρεως εἰς τὴν Τιραθανὰ παραγενέσθαι."},{"number":89,"text":"καὶ Οὐιτέλλιος Μάρκελλον τῶν αὐτοῦ φίλων ἐκπέμψας ἐπιμελητὴν τοῖς Ἰουδαίοις γενησόμενον Πιλᾶτον ἐκέλευσεν ἐπὶ Ῥώμης ἀπιέναι πρὸς ἃ κατηγοροῖεν οἱ Σαμαρεῖται διδάξοντα τὸν αὐτοκράτορα. καὶ Πιλᾶτος δέκα ἔτεσιν διατρίψας ἐπὶ Ἰουδαίας εἰς Ῥώμην ἠπείγετο ταῖς Οὐιτελλίου πειθόμενος ἐντολαῖς οὐκ ὂν ἀντειπεῖν. πρὶν δʼ ἐν τῇ Ῥώμῃ ἴσχειν αὐτὸν φθάνει Τιβέριος μεταστάς."},{"number":90,"text":"Οὐιτέλλιος δὲ εἰς τὴν Ἰουδαίαν ἀφικόμενος ἐπὶ Ἱεροσολύμων ἀνῄει, καὶ ἦν γὰρ αὐτοῖς ἑορτὴ πάτριος, πάσχα δὲ καλεῖται, δεχθεὶς μεγαλοπρεπῶς Οὐιτέλλιος τὰ τέλη τῶν ὠνουμένων καρπῶν ἀνίησιν εἰς τὸ πᾶν τοῖς ταύτῃ κατοικοῦσιν καὶ τὴν στολὴν τοῦ ἀρχιερέως καὶ τὸν πάντα αὐτοῦ κόσμον συνεχώρησεν ἐν τῷ ἱερῷ κειμένην ὑπὸ τοῖς ἱερεῦσιν ἔχειν τὴν ἐπιμέλειαν, καθότι καὶ πρότερον ἦν αὐτοῖς ἐξουσία."},{"number":91,"text":"τότε δὲ ἐν τῇ Ἀντωνίᾳ, φρούριον δʼ ἐστὶν οὕτως λεγόμενον, ἡ ἀπόθεσις αὐτῆς ἦν διὰ τοιαύτην αἰτίαν· τῶν ἱερέων τις Ὑρκανός, πολλῶν δὲ ὄντων οἳ τόδε ἐκαλοῦντο τὸ ὄνομα ὁ πρῶτος, ἐπεὶ πλησίον τῷ ἱερῷ βᾶριν κατασκευασάμενος ταύτῃ τὰ πολλὰ τὴν δίαιταν εἶχεν καὶ τὴν στολήν, φύλαξ γὰρ ἦν αὐτῆς διὰ τὸ καὶ μόνῳ συγκεχωρῆσθαι τοῦ ἐνδύεσθαι τὴν ἐξουσίαν, ταύτην εἶχεν ἀποκειμένην, ὁπότε εἰς τὴν πόλιν κατιὼν ἀναλαμβάνοι τὴν ἰδιωτικήν."},{"number":92,"text":"καὶ οἵ τε υἱεῖς αὐτοῦ ταῦτα πράσσειν ἐπετήδευσαν καὶ τέκνα ἐκείνων. Ἡρώδης δὲ βασιλεύσας τήν τε βᾶριν ταύτην ἐν ἐπιτηδείῳ κειμένην κατασκευάσας πολυτελῶς Ἀντωνίαν καλεῖ ὀνόματι Ἀντωνίου φίλος ὤν, καὶ τὴν στολὴν ὥσπερ καὶ λαμβάνει τῇδε κειμένην κατεῖχεν, πιστεύων οὐδὲν νεωτεριεῖν ἐπʼ αὐτῷ τὸν λαὸν διὰ τάδε."},{"number":93,"text":"ἔπρασσε δὲ ὅμοια τῷ Ἡρώδῃ καὶ ὁ ἐπικατασταθεὶς αὐτῷ βασιλεὺς Ἀρχέλαος υἱὸς ὤν, οὗ Ῥωμαῖοι παραδεξάμενοι τὴν ἀρχὴν ἐκράτουν τῆς στολῆς τοῦ ἀρχιερέως ἀποκειμένης ἐν οἴκῳ λίθοις οἰκοδομηθέντι ὑπὸ σφραγῖδι τῶν τε ἱερέων καὶ τῶν γαζοφυλάκων τοῦ φρουράρχου τὸ ἐφʼ ἡμέραν ἑκάστην λύχνον ἅπτοντος."},{"number":94,"text":"ἑπτὰ δʼ ἡμέραις πρὸ τῆς ἑορτῆς ἀπεδίδοτο αὐτοῖς ὑπὸ τοῦ φρουράρχου, καὶ ἁγνισθείσῃ χρησάμενος ὁ ἀρχιερεὺς μετὰ μίαν τῆς ἑορτῆς ἡμέραν ἀπετίθετο αὖθις εἰς τὸν οἶκον, ᾗπερ ἔκειτο καὶ πρότερον. τοῦτο ἐπράττετο τρισὶν ἑορταῖς ἑκάστου ἔτους καὶ τὴν νηστείαν."},{"number":95,"text":"Οὐιτέλλιος δὲ ἐπὶ τῷ ἡμετέρῳ πατρίῳ ποιεῖται τὴν στολήν, ᾗ τε κείσοιτο μὴ πολυπραγμονεῖν ἐπισκήψας τῷ φρουράρχῳ καὶ ὁπότε δέοι χρῆσθαι. καὶ ταῦτα πράξας ἐπὶ εὐεργεσίᾳ τοῦ ἔθνους καὶ τὸν ἀρχιερέα Ἰώσηπον τὸν Καϊάφαν ἐπικαλούμενον ἀπαλλάξας τῆς ἱερωσύνης Ἰωνάθην καθίστησιν Ἀνάνου τοῦ ἀρχιερέως υἱόν. ἐπʼ Ἀντιοχείας δʼ αὖθις ἐποιεῖτο τὴν ὁδόν."},{"number":96,"text":"Πέμπει δὲ καὶ Τιβέριος ὡς Οὐιτέλλιον γράμματα, κελεύων αὐτῷ πράσσειν φιλίαν πρὸς Ἀρτάβανον τὸν Πάρθων βασιλέα· ἐφόβει γὰρ αὐτὸν ἐχθρὸς ὢν καὶ Ἀρμενίαν παρεσπασμένος μὴ ἐπὶ πλέον κακουργῇ· πιστεύειν δὲ τῇ φιλίᾳ μόνως ὁμήρων αὐτῷ διδομένων, μάλιστα δὲ τοῦ Ἀρταβάνου υἱέος."},{"number":97,"text":"ταῦτα δὲ γράφων Τιβέριος πρὸς τὸν Οὐιτέλλιον μεγάλαις δόσεσι χρημάτων πείθει καὶ τὸν Ἰβήρων καὶ τὸν Ἀλβανῶν βασιλέα πολεμεῖν Ἀρταβάνῳ μηδὲν ἐνδοιάσαι. οἱ δὲ αὐτοὶ μὲν ἀντεῖχον, Ἀλανοὶ δὲ δίοδον αὐτοῖς διδόντες διὰ τῆς αὐτῶν καὶ τὰς θύρας τὰς Κασπίας ἀνοίξαντες ἐπάγουσι τῷ Ἀρταβάνῳ."},{"number":98,"text":"καὶ ἥ τε Ἀρμενία ἀφῄρητο αὖθις καὶ πλησθείσης πολέμων τῆς Παρθυαίων γῆς οἵ τε πρῶτοι τῶν τῇδε ἐκτείνοντο ἀνδρῶν ἀνάστατά τε ἦν αὐτοῖς τὰ πάντα καὶ τοῦ βασιλέως ὁ υἱὸς ἐκ τουτωνὶ τῶν μαχῶν ἔπεσε μετὰ πολλῶν στρατοῦ μυριάδων."},{"number":99,"text":"καὶ αὐτοῦ τὸν πατέρα Ἀρτάβανον Οὐιτέλλιος πομπῇ χρημάτων εἴς τε συγγενεῖς καὶ φίλους τοὺς ἐκείνου γενομένῃ ἐμέλλησε μὲν κτιννύειν διὰ τῶν τὰ δῶρα εἰληφότων, αἰσθόμενος δὲ τὴν ἐπιβουλὴν ὁ Ἀρτάβανος ἄφυκτον οὖσαν διὰ τὸ ὑπὸ πολλῶν καὶ τῶν πρώτων ἀνδρῶν συντεθεῖσαν μὴ ἀνεῖσθαι τοῦ ἐπὶ πέρας ἐλθεῖν,"},{"number":100,"text":"καὶ νομίζων καὶ ὁπόσον αὐτῷ καθαρῶς συνειστήκει καὶ τόδε ἤτοι ἐφθαρμένον ἐπὶ δόλῳ τὴν εὔνοιαν προσποιεῖσθαι ἢ πείρας αὐτῷ γενομένης μετατάξεσθαι πρὸς τοὺς προαφεστηκότας, εἴς τι τῶν ἄνω σατραπειῶν ἔσωζεν αὑτόν. καὶ πολλὴν μετὰ ταῦτα στρατιὰν ἀθροίσας Δαῶν τε καὶ Σακῶν καὶ πολεμήσας τοὺς ἀνθεστηκότας κατέσχε τὴν ἀρχήν."},{"number":101,"text":"Ταῦτα ἀκούσας ὁ Τιβέριος ἠξίου φιλίαν αὐτῷ γενέσθαι πρὸς τὸν Ἀρτάβανον, ἐπεὶ δὲ κἀκεῖνος προκληθεὶς ἄσμενος ἐδέχετο τὸν περὶ αὐτῶν λόγον, ἐπὶ τὸν Εὐφράτην παρῆσαν ὅ τε Ἀρτάβανος καὶ Οὐιτέλλιος."},{"number":102,"text":"καὶ ζεύξεως τοῦ ποταμοῦ γενομένης κατὰ τὸ μεσαίτατον τῆς γεφύρας ἀλλήλους ὑπηντίαζον μετὰ φυλακῆς ἑκάτερος τῆς περὶ αὐτόν. καὶ λόγων αὐτοῖς συμβατικῶν γενομένων Ἡρώδης ὁ τετράρχης εἱστίασεν αὐτοὺς κατὰ μέσον τὸν πόρον σκηνίδα ἐπισκηψάμενος τῷ πόρῳ πολυτελῆ."},{"number":103,"text":"καὶ Ἀρτάβανος πέμπει Τιβερίῳ ὅμηρον Δαρεῖον τὸν υἱὸν μετὰ πολλῶν δώρων, ἐν οἷς καὶ ἄνδρα ἑπτάπηχυν τὸ μέγεθος Ἰουδαῖον τὸ γένος Ἐλεάζαρον ὄνομα·"},{"number":104,"text":"διὰ μέντοι τὸ μέγεθος Γίγας ἐκαλεῖτο. ἐπὶ τούτοις Οὐιτέλλιος μὲν ἐπʼ Ἀντιοχείας ᾔει, Ἀρτάβανος δὲ ἐπὶ τῆς Βαβυλωνίας. Ἡρώδης δὲ βουλόμενος διʼ αὐτοῦ πρώτου γενέσθαι πύστιν Καίσαρι τῶν ὁμήρων τῆς λήψεως ἐκπέμπει γραμματοφόρους τὰ πάντα ἀκριβῶς γράψας εἰς ἐπιστολὴν καὶ μηδὲν ὑπολιπόμενος ἐπὶ μηνύσει τῷ ὑπατικῷ."},{"number":105,"text":"πρὸς Οὐιτελλίου δὲ ἐπιπεμφθεισῶν ἐπιστολῶν καὶ τοῦ Καίσαρος ἐπισημήναντος πρὸς αὐτόν, ὡς δῆλα αὐτῷ γένοιτο πρότερον πύστιν περὶ αὐτῶν Ἡρώδου προτεθεικότος, ταραχθεὶς ὁ Οὐιτέλλιος μεγάλως καὶ πεπονθέναι μειζόνως ἢ ἐπέπρακτο ὑπολαμβάνων ἄδηλον τὴν ἐπʼ αὐτοῖς ἔκρυπτεν ὀργήν, μέχρι δὴ καὶ μετῆλθε Γαΐου τὴν Ῥωμαίων ἀρχὴν παρειληφότος."},{"number":106,"text":"Τότε δὲ καὶ Φίλιππος, Ἡρώδου δὲ ἦν ἀδελφός, τελευτᾷ τὸν βίον εἰκοστῷ μὲν ἐνιαυτῷ τῆς Τιβερίου ἀρχῆς, ἡγησάμενος δὲ αὐτὸς ἑπτὰ καὶ τριάκοντα τῆς Τραχωνίτιδος καὶ Γαυλανίτιδος καὶ τοῦ Βατανέων ἔθνους πρὸς αὐταῖς, μέτριον δὲ ἐν οἷς ἦρχεν παρασχὼν τὸν τρόπον καὶ ἀπράγμονα·"},{"number":107,"text":"δίαιταν μὲν γὰρ τὸ πᾶν ἐν γῇ τῇ ὑποτελεῖ ἐποιεῖτο, πρόοδοι δʼ ἦσαν αὐτῷ σὺν ὀλίγοις τῶν ἐπιλέκτων, καὶ τοῦ θρόνου εἰς ὃν ἔκρινεν καθεζόμενος ἐν ταῖς ὁδοῖς ἑπομένου, ὁπότε τις ὑπαντιάσας ἐν χρείᾳ γένοιτο αὐτῷ ἐπιβοηθεῖν, οὐδὲν εἰς ἀναβολὰς ἀλλʼ ἐκ τοῦ ὀξέος ἱδρύσεως τοῦ θρόνου ᾗ καὶ τύχοι γενομένης καθεζόμενος ἠκροᾶτο καὶ τιμωρίας τε ἐπετίμα τοῖς ἁλοῦσι καὶ ἠφίει τοὺς ἀδίκως ἐν ἐγκλήμασι γενομένους."},{"number":108,"text":"τελευτᾷ δʼ ἐν Ἰουλιάδι καὶ αὐτοῦ κομισθέντος ἐπὶ τὸ μνημεῖον, ὃ ἔτι πρότερον ᾠκοδόμησεν αὐτός, ταφαὶ γίνονται πολυτελεῖς. τὴν δʼ ἀρχήν, οὐ γὰρ κατελίπετο παῖδας, Τιβέριος παραλαβὼν προσθήκην ἐπαρχίας ποιεῖται τῆς Σύρων, τοὺς μέντοι φόρους ἐκέλευσε συλλεγομένους ἐν τῇ τετραρχίᾳ τῇ ἐκείνου γενομένῃ κατατίθεσθαι."}],"5":[{"number":109,"text":"Ἐν τούτῳ δὲ στασιάζουσιν Ἀρέτας τε ὁ Πετραῖος βασιλεὺς καὶ Ἡρώδης διὰ τοιαύτην αἰτίαν· Ἡρώδης ὁ τετράρχης γαμεῖ τὴν Ἀρέτα θυγατέρα καὶ συνῆν χρόνον ἤδη πολύν. στελλόμενος δὲ ἐπὶ Ῥώμης κατάγεται ἐν Ἡρώδου ἀδελφοῦ ὄντος οὐχ ὁμομητρίου· ἐκ γὰρ τῆς Σίμωνος τοῦ ἀρχιερέως θυγατρὸς Ἡρώδης ἐγεγόνει."},{"number":110,"text":"ἐρασθεὶς δὲ Ἡρωδιάδος τῆς τούτου γυναικός, θυγάτηρ δὲ ἦν Ἀριστοβούλου καὶ οὗτος ἀδελφὸς αὐτῶν, Ἀγρίππου δὲ ἀδελφὴ τοῦ μεγάλου, τολμᾷ λόγων ἅπτεσθαι περὶ γάμου. καὶ δεξαμένης συνθῆκαι γίνονται μετοικίσασθαι παρʼ αὐτόν, ὁπότε ἀπὸ Ῥώμης παραγένοιτο. ἦν δὲ ἐν ταῖς συνθήκαις ὥστε καὶ τοῦ Ἀρέτα τὴν θυγατέρα ἐκβαλεῖν."},{"number":111,"text":"καὶ ὁ μὲν εἰς τὴν Ῥώμην ἔπλει ταῦτα συνθέμενος. ἐπεὶ δὲ ἐπανεχώρει διαπραξάμενος ἐν τῇ Ῥώμῃ ἐφʼ ἅπερ ἔσταλτο, ἡ γυνὴ πύστεως αὐτῇ τῶν πρὸς τὴν Ἡρωδιάδα συνθηκῶν γενομένης πρὶν ἔκπυστος αὐτῷ γενέσθαι τὰ πάντα ἐκμαθοῦσα κελεύει πέμπειν αὐτὴν ἐπὶ Μαχαιροῦντος, μεθόριον δʼ ἐστὶ τῆς τε Ἀρέτα καὶ Ἡρώδου ἀρχῆς, γνώμην οὐκ ἐκφαίνουσα τὴν αὐτῆς."},{"number":112,"text":"καὶ ὁ Ἡρώδης ἐξέπεμψεν μηδὲν ᾐσθῆσθαι τὴν ἄνθρωπον προσδοκῶν. ἡ δέ, προαπεστάλκει γὰρ ἐκ πλείονος εἰς τὸν Μαχαιροῦντα τῷ τε πατρὶ αὐτῆς ὑποτελεῖ, πάντων εἰς τὴν ὁδοιπορίαν ἡτοιμασμένων ὑπὸ τοῦ στρατηγοῦ ἅμα τε παρῆν καὶ ἀφωρμᾶτο εἰς τὴν Ἀραβίαν κομιδῇ τῶν στρατηγῶν ἐκ διαδοχῆς παρῆν τε ὡς τὸν πατέρα ᾗ τάχος καὶ αὐτῷ τὴν Ἡρώδου διάνοιαν ἔφραζεν."},{"number":113,"text":"ὁ δὲ ἀρχὴν ἔχθρας ταύτην ποιησάμενος περί τε ὅρων ἐν γῇ τῇ Γαμαλικῇ, καὶ δυνάμεως ἑκατέρῳ συλλεγείσης εἰς πόλεμον καθίσταντο στρατηγοὺς ἀπεσταλκότες ἀνθʼ ἑαυτῶν."},{"number":114,"text":"καὶ μάχης γενομένης διεφθάρη πᾶς ὁ Ἡρώδου στρατὸς προδοσίας αὐτῷ γενομένης ὑπʼ ἀνδρῶν φυγάδων, οἳ ὄντες ἐκ τῆς Φιλίππου τετραρχίας Ἡρώδῃ συνεστράτευον."},{"number":115,"text":"ταῦτα Ἡρώδης γράφει πρὸς Τιβέριον. ὁ δὲ ὀργῇ φέρων τὴν Ἀρέτα ἐπιχείρησιν γράφει πρὸς Οὐιτέλλιον πόλεμον ἐξενεγκεῖν καὶ ἤτοι ζωὸν ἑλόντα ἀναγαγεῖν δεδεμένον ἢ κτεινομένου πέμπειν τὴν κεφαλὴν ἐπʼ αὐτόν. καὶ Τιβέριος μὲν ταῦτα πράσσειν ἐπέστελλεν τῷ κατὰ Συρίαν στρατηγῷ."},{"number":116,"text":"Τισὶ δὲ τῶν Ἰουδαίων ἐδόκει ὀλωλέναι τὸν Ἡρώδου στρατὸν ὑπὸ τοῦ θεοῦ καὶ μάλα δικαίως τινυμένου κατὰ ποινὴν Ἰωάννου τοῦ ἐπικαλουμένου βαπτιστοῦ."},{"number":117,"text":"κτείνει γὰρ δὴ τοῦτον Ἡρώδης ἀγαθὸν ἄνδρα καὶ τοῖς Ἰουδαίοις κελεύοντα ἀρετὴν ἐπασκοῦσιν καὶ τὰ πρὸς ἀλλήλους δικαιοσύνῃ καὶ πρὸς τὸν θεὸν εὐσεβείᾳ χρωμένοις βαπτισμῷ συνιέναι· οὕτω γὰρ δὴ καὶ τὴν βάπτισιν ἀποδεκτὴν αὐτῷ φανεῖσθαι μὴ ἐπί τινων ἁμαρτάδων παραιτήσει χρωμένων, ἀλλʼ ἐφʼ ἁγνείᾳ τοῦ σώματος, ἅτε δὴ καὶ τῆς ψυχῆς δικαιοσύνῃ προεκκεκαθαρμένης."},{"number":118,"text":"καὶ τῶν ἄλλων συστρεφομένων, καὶ γὰρ ἥσθησαν ἐπὶ πλεῖστον τῇ ἀκροάσει τῶν λόγων, δείσας Ἡρώδης τὸ ἐπὶ τοσόνδε πιθανὸν αὐτοῦ τοῖς ἀνθρώποις μὴ ἐπὶ ἀποστάσει τινὶ φέροι, πάντα γὰρ ἐῴκεσαν συμβουλῇ τῇ ἐκείνου πράξοντες, πολὺ κρεῖττον ἡγεῖται πρίν τι νεώτερον ἐξ αὐτοῦ γενέσθαι προλαβὼν ἀνελεῖν τοῦ μεταβολῆς γενομένης μὴ εἰς πράγματα ἐμπεσὼν μετανοεῖν."},{"number":119,"text":"καὶ ὁ μὲν ὑποψίᾳ τῇ Ἡρώδου δέσμιος εἰς τὸν Μαχαιροῦντα πεμφθεὶς τὸ προειρημένον φρούριον ταύτῃ κτίννυται. τοῖς δὲ Ἰουδαίοις δόξαν ἐπὶ τιμωρίᾳ τῇ ἐκείνου τὸν ὄλεθρον ἐπὶ τῷ στρατεύματι γενέσθαι τοῦ θεοῦ κακῶσαι Ἡρώδην θέλοντος."},{"number":120,"text":"Οὐιτέλλιος δὲ παρασκευασάμενος ὡς εἰς πόλεμον τὸν πρὸς Ἀρέταν δυσὶ τάγμασιν ὁπλιτῶν ὅσοι τε περὶ αὐτὰ ψιλοὶ καὶ ἱππεῖς συμμαχοῦντες ἐκ τῶν ὑπὸ Ῥωμαίοις βασιλειῶν ἀγόμενος, ἐπὶ τῆς Πέτρας ἠπείγετο καὶ ἔσχε Πτολεμαΐδα."},{"number":121,"text":"ὡρμημένῳ δʼ αὐτῷ διὰ τῆς Ἰουδαίων ἄγειν τὸν στρατὸν ὑπαντιάσαντες ἄνδρες οἱ πρῶτοι παρῃτοῦντο τὴν διὰ τῆς χώρας ὁδόν· οὐ γὰρ αὐτοῖς εἶναι πάτριον περιορᾶν εἰκόνας εἰς αὐτὴν φερομένας, πολλὰς δʼ εἶναι σημαίαις ἐπικειμένας."},{"number":122,"text":"καὶ πεισθεὶς μετέβαλέν τε τῆς γνώμης τὸ ἐπὶ τοιούτοις προβουλεῦσαν καὶ διὰ τοῦ μεγάλου πεδίου κελεύσας χωρεῖν τὸ στρατόπεδον αὐτὸς μετὰ Ἡρώδου τοῦ τετράρχου καὶ τῶν φίλων εἰς Ἱεροσόλυμα ἀνῄει θύσων τῷ θεῷ ἑορτῆς πατρίου τοῖς Ἰουδαίοις ἐνεστηκυίας."},{"number":123,"text":"εἰς ἣν ἀπαντήσας καὶ δεχθεὶς ὑπὸ τοῦ τῶν Ἰουδαίων πλήθους ἐκπρεπῶς τρεῖς μὲν ἡμέρας ταύτῃ διατριβὴν ποιεῖται, ἐν αἷς Ἰωνάθην τὴν ἱερωσύνην ἀφελόμενος ἐγχειρίζει τῷ ἀδελφῷ αὐτοῦ Θεοφίλῳ,"},{"number":124,"text":"τῇ τετάρτῃ δὲ γραμμάτων αὐτῷ παραγενομένων, ἃ ἐδήλου τὴν Τιβερίου τελευτήν, ὥρκισεν τὴν πληθὺν ἐπʼ εὐνοίᾳ τῇ Γαΐου. ἀνεκάλει δὲ καὶ τὸ στράτευμα ἐπὶ τὰ οἰκεῖα ἑκάστου χειμαδιᾶν πόλεμον ἐκφέρειν οὐκέθʼ ὁμοίως δυνάμενος διὰ τὸ εἰς Γάιον μεταπεπτωκέναι τὰ πράγματα."},{"number":125,"text":"ἐλέγετο δὲ καὶ τὸν Ἀρέταν οἰωνοσκοπησάμενον πρὸς τὴν ἀγγελίαν τῶν Οὐιτελλίου στρατιωτῶν φάναι μηχανὴν οὐκ εἶναι τῷ στρατῷ τῆς ἐπὶ Πετραίους ὁδοῦ· τεθνήξεσθαι γὰρ τῶν ἡγεμόνων ἢ τὸν πολεμεῖν κελεύσαντα ἢ τὸν γνώμῃ τῇ ἐκείνου ὡρμημένον διακονεῖσθαι ἢ ἐφʼ ὃν γένοιτο ἡ παρασκευὴ τοῦ στρατεύματος."},{"number":126,"text":"καὶ Οὐιτέλλιος μὲν ἐπʼ Ἀντιοχείας ἀνεχώρησεν. Ἀγρίππας δὲ ὁ Ἀριστοβούλου υἱὸς ἐνιαυτῷ πρότερον ἢ τελευτῆσαι Τιβέριον ἐπὶ Ῥώμης ἄνεισι πράξων τι παρὰ τῷ αὐτοκράτορι δυνάμεώς τινος αὐτῷ παραγενομένης."},{"number":127,"text":"βούλομαι οὖν εἰπεῖν ἐπὶ μακρότερον περί τε Ἡρώδου καὶ γένους αὐτοῦ ὡς ἐγένετο, ἅμα μὲν καὶ διὰ τὸ ἀνήκειν τῇ ἱστορίᾳ τὸν περὶ αὐτῶν λόγον, ἅμα δὲ καὶ παράστασιν ἔχειν τοῦ θείου, ὡς οὐδὲν ὠφελεῖ πλῆθος οὐδʼ ἄλλη τις ἀλκὴ τῶν ἐν ἀνθρώποις ἐπιτετευγμένων δίχα τῶν πρὸς τὸ θεῖον εὐσεβειῶν,"},{"number":128,"text":"εἴ γε ἐντὸς ἑκατὸν ἐτῶν ἐξόδου συνέβη πλὴν ὀλίγων, πολλοὶ δʼ ἦσαν, διαφθαρῆναι τοὺς Ἡρώδου ἀπογόνους· φέροι δʼ ἄν τι κἀπὶ σωφρονισμῷ τοῦ ἀνθρωπείου γένους τὸ τὴν δυστυχίαν αὐτῶν μαθεῖν,"},{"number":129,"text":"ἅμα δὲ καὶ τὸν Ἀγρίππαν διηγήσασθαι θαύματος ἀξιώτατον γεγενημένον, ὃς ἐκ πάνυ ἰδιώτου καὶ παρὰ πᾶσαν δόξαν τῶν εἰδότων αὐτὸν ἐπὶ τοσόνδε ηὐξήθη δυνάμεως. εἴρηται μὲν οὖν μοι καὶ πρότερον περὶ αὐτῶν, λεχθήσεται δὲ καὶ νῦν ἀκριβῶς."},{"number":130,"text":"Ἡρώδῃ τῷ μεγάλῳ θυγατέρες ἐκ Μαριάμμης τῆς Ὑρκανοῦ θυγατρὸς γίνονται δύο, Σαλαμψιὼ μὲν ἡ ἑτέρα, ἣ γαμεῖται Φασαήλῳ τῷ αὐτῆς ἀνεψιῷ Φασαήλου παιδὶ ὄντι τοῦ Ἡρώδου ἀδελφοῦ δεδωκότος τοῦ πατρὸς αὐτήν, Κύπρος δὲ Ἀντιπάτρῳ καὶ αὐτὴ ἀνεψιῷ Ἡρώδου παιδὶ τῆς ἀδελφῆς Σαλώμης."},{"number":131,"text":"καὶ Φασαήλῳ μὲν ἐκ Σαλαμψιοῦς γίνονται πέντε παῖδες Ἀντίπατρος Ἀλέξανδρος Ἡρώδης θυγατέρες τε Ἀλεξάνδρα καὶ Κύπρος, ἣν Ἀγρίππας γαμεῖ ὁ Ἀριστοβούλου. Ἀλεξάνδραν δὲ γαμεῖ μὲν Τίμιος Κύπριος ἀνὴρ τῶν ἀξιολόγων, παρʼ ᾧ δὴ ἄτεκνος τελευτᾷ."},{"number":132,"text":"Κύπρῳ δʼ ἐξ Ἀγρίππου μὲν ἄρρενες γίνονται δύο, θυγατέρες δὲ τρεῖς Βερενίκη Μαριάμμη Δρούσιλλα, Ἀγρίππας δὲ καὶ Δροῦσος τοῖς ἄρσεσιν ὀνόματα, ὧν ὁ Δροῦσος πρὶν ἡβῆσαι τελευτᾷ."},{"number":133,"text":"τῷ δὲ πατρὶ τούτων Ἀγρίππας ἐτρέφετο μετὰ καὶ ἑτέρων ἀδελφῶν Ἡρώδης καὶ Ἀριστόβουλος· καὶ Βερενίκη καὶ οἵδε παῖδες Ἡρώδου τοῦ υἱέος τοῦ μεγάλου· ἡ δὲ Βερενίκη Κοστοβάρου καὶ Σαλώμης παῖς τῆς Ἡρώδου ἀδελφῆς."},{"number":134,"text":"τούτους Ἀριστόβουλος νηπίους λείπεται θνήσκων ὑπὸ τοῦ πατρὸς σὺν Ἀλεξάνδρῷ τῷ ἀδελφῷ, καθὰ προειρήκαμεν. ἡβήσαντες δʼ ἄγονται Ἡρώδης μὲν οὗτος ὁ τοῦ Ἀγρίππου ἀδελφὸς Μαριάμμην θυγατέρα Ὀλυμπιάδος τῆς Ἡρώδου βασιλέως θυγατρὸς καὶ Ἰωσήπου τοῦ Ἰωσήπου, ἀδελφὸς δὲ οὗτος Ἡρώδου τοῦ βασιλέως· ἴσχει τε ἐξ αὐτῆς υἱὸν Ἀριστόβουλον."},{"number":135,"text":"ὁ δὲ τρίτος τοῦ Ἀγρίππου ἀδελφὸς Ἀριστόβουλος γαμεῖ Ἰωτάπην Σαμψιγεράμου θυγατέρα τοῦ Ἐμεσῶν βασιλέως, θυγάτηρ τε αὐτοῖς γίνεται κωφή· ὄνομα καὶ τῇδε Ἰωτάπη."},{"number":136,"text":"καὶ τάδε μὲν τῶν ἀρσένων τέκνα. Ἡρωδιὰς δὲ αὐτῶν ἡ ἀδελφὴ γίνεται Ἡρώδῃ Ἡρώδου τοῦ μεγάλου παιδὶ γεγονότι ἐκ Μαριάμμης τῆς τοῦ Σίμωνος τοῦ ἀρχιερέως, καὶ αὐτοῖς Σαλώμη γίνεται, μεθʼ ἧς τὰς γονὰς Ἡρωδιὰς ἐπὶ συγχύσει φρονήσασα τῶν πατρίων Ἡρώδῃ γαμεῖται τοῦ ἀνδρὸς τῷ ὁμοπατρίῳ ἀδελφῷ διαστᾶσα ζῶντος. τὴν δὲ Γαλιλαίων τετραρχίαν οὗτος εἶχεν."},{"number":137,"text":"ἡ δὲ θυγάτηρ αὐτῆς Σαλώμη Φιλίππῳ γαμεῖται Ἡρώδου παιδὶ τῷ τετράρχῃ τῆς Τραχωνίτιδος, καὶ ἄπαιδος τελευτήσαντος Ἀριστόβουλος αὐτὴν ἄγεται Ἡρώδου παῖς τοῦ Ἀγρίππου ἀδελφοῦ. παῖδες δὲ ἐγένοντο αὐτοῖς τρεῖς Ἡρώδης Ἀγρίππας Ἀριστόβουλος."},{"number":138,"text":"τοῦτο μὲν δὴ τὸ Φασαήλου καὶ Σαλαμψιοῦς ἐστι γένος. Κύπρῳ δʼ ἐξ Ἀντιπάτρου θυγάτηρ γίνεται Κύπρος, καὶ αὐτὴν Ἀλεξᾶς ὁ Ἐλκίας γαμεῖ τοῦ Ἀλεξᾶ, καὶ αὐτῆς θυγάτηρ ἦν Κύπρος. Ἡρώδης δὲ καὶ Ἀλέξανδρος, οὓς ἀδελφοὺς ἔφην Ἀντιπάτρου, ἄτεκνοι τελευτῶσιν."},{"number":139,"text":"Ἀλεξάνδρῳ δὲ τῷ Ἡρώδου παιδὶ τοῦ βασιλέως τῷ ὑπὸ τοῦ πατρὸς ἀνῃρημένῳ Ἀλέξανδρος καὶ Τιγράνης ἐγεγόνεισαν υἱεῖς ἐκ τῆς Ἀρχελάου τοῦ Καππαδόκων βασιλέως θυγατρός. καὶ Τιγράνης μὲν βασιλεύων Ἀρμενίας κατηγοριῶν αὐτοῦ ἐπὶ Ῥώμης γενομένων ἄπαις τελευτᾷ."},{"number":140,"text":"Ἀλεξάνδρῳ δὲ Τιγράνης ὁμώνυμος τῷ ἀδελφῷ γίνεται παῖς καὶ βασιλεὺς Ἀρμενίας ὑπὸ Νέρωνος ἐκπέμπεται υἱός τε Ἀλέξανδρος αὐτῷ γίνεται. γαμεῖ δʼ οὗτος Ἀντιόχου τοῦ Κομμαγηνῶν βασιλέως θυγατέρα Ἰωτάπην, ἡσίοδός τε τῆς ἐν Κιλικίᾳ Οὐεσπασιανὸς αὐτὸν ἵσταται βασιλέα."},{"number":141,"text":"καὶ τὸ μὲν Ἀλεξάνδρου γένος εὐθὺς ἅμα τῷ φυῆναι τὴν θεραπείαν ἐξέλιπεν τῶν Ἰουδαίοις ἐπιχωρίων μεταταξάμενοι πρὸς τὰ Ἕλλησι πάτρια· ταῖς δὲ λοιπαῖς θυγατράσιν Ἡρώδου τοῦ βασιλέως ἀτέκνοις τελευτᾶν συνέπεσεν."},{"number":142,"text":"τῶν δὲ γενομένων Ἡρώδου ἀπογόνων οὓς κατέλεξα ἔμενον ἐν ᾧ χρόνῳ Ἀγρίππας ὁ μέγας τὴν βασιλείαν παρέλαβεν. τούτων δέ μοι τοῦ γένους προδεδηλωμένων διέξειμι λοιπόν, ὁπόσαι Ἀγρίππᾳ τύχαι συνέλθοιεν, ὥς τε αὐτῶν διάδρασιν ποιησάμενος ἐπὶ μέγιστον ἀξιώματός τε ἅμα προκόψειεν καὶ δυνάμεως."}],"6":[{"number":143,"text":"Ἡρώδου τοῦ βασιλέως ὀλίγον πρὸ τῆς τελευτῆς Ἀγρίππας ἐν Ῥώμῃ διαιτώμενος καὶ ὁμοτροφίας καὶ συνηθείας αὐτῷ πολλῆς γενομένης πρὸς Δροῦσον τὸν Τιβερίου τοῦ αὐτοκράτορος υἱὸν καὶ Ἀντωνίᾳ τῇ Δρούσου τοῦ μεγάλου γυναικὶ εἰς φιλίαν ἀφίκετο, Βερενίκης τῆς μητρὸς τιμωμένης παρʼ αὐτῇ καὶ προαγωγῶν ἠξιωκυίας τὸν υἱόν."},{"number":144,"text":"φύσει δὲ μέγας ὢν ὁ Ἀγρίππας καὶ δωρεῖσθαι πολυτελὴς ζώσης μὲν τῆς μητρὸς οὐκ ἐξέφαινε τῆς ψυχῆς τὸ θέλον διαδιδράσκειν αὐτῆς ἠξιωκὼς τὴν ἐπὶ τοῖς τοιούτοις γενομένην ὀργήν,"},{"number":145,"text":"ἐπεὶ δὲ Βερενίκη τελευτᾷ, γενόμενος ἐπὶ τῷ αὐτοῦ τρόπῳ, τὰ μὲν εἰς πολυτέλειαν τῆς καθʼ ἡμέραν διαίτης, τὰ δʼ εἰς τῶν δωρεῶν τὸ μὴ μέτρῳ προϊέμενον ἀνάλωσε τῶν χρημάτων, τὰ πλεῖστα δʼ εἰς τοὺς Καίσαρος ἀπελευθέρους ἐτετέλεστο ἐλπίδι πράξεως τῆς αὐτῶν, πενία τε ἐν ὀλίγῳ περὶ αὐτὸν ἦν."},{"number":146,"text":"καὶ τοῦτο ἦν κώλυμα τῆς ἐν Ῥώμῃ διαίτης, καὶ ὁ Τιβέριος τοῖς φίλοις τοῦ υἱέος τετελευτηκότος ἀπειπὼν φοιτᾶν εἰς ὄψιν αὐτῷ, διὰ τὸ ἀνερεθίζεσθαι πρὸς τὸ λυπεῖσθαι μνημονεύων τοῦ παιδὸς θεωρίᾳ τῇ ἐκείνων."},{"number":147,"text":"Διὰ μὲν δὴ ταῦτα ἐπὶ τῆς Ἰουδαίας πλέων ᾤχετο κακοπραγῶν καὶ τεταπεινωμένος ὀλέθρῳ τε ὧν εἶχεν χρημάτων καὶ ἀπορίᾳ τοῦ ἐκτίσοντος τὰ χρέα τοῖς δανεισταῖς πολλοῖς τε οὖσιν καὶ ἀλεωρὰν οὐδʼ ἡντινοῦν ἐνδιδοῦσιν, ὥστε ἀπορίᾳ τῶν ποιητέων καὶ αἰσχύνῃ τῇ ἐπʼ αὐτοῖς ὑποχωρήσας εἴς τινα πύργον ἐν Μαλάθοις τῆς Ἰδουμαίας ἐν περινοίᾳ τοῦ μεταστήσοντος αὑτὸν ἦν."},{"number":148,"text":"αἰσθάνεται δʼ αὐτοῦ τὴν διάνοιαν Κύπρος ἡ γυνὴ παντοία τε ἦν ἀπείργουσα τῶν ἐπὶ τοιούτοις βουλευμάτων. διαπέμπεται δὲ καὶ ὡς τὴν ἀδελφὴν αὐτοῦ Ἡρωδιάδα Ἡρώδῃ τῷ τετράρχῃ συνοικοῦσαν γράμματα, δηλοῦσα τό τε ἐπὶ τοιούτοις τοῦ Ἀγρίππα προβουλεῦσαν καὶ τὴν ἀνάγκην, ἣ ἐπʼ αὐτὰ ἐξήγαγεν·"},{"number":149,"text":"ἐκέλευέν τε συγγενῆ οὖσαν βοηθεῖν θεωροῦσαν, ὡς αὐτὴ παντοίως ὡς κουφίζοι τὸν ἄνδρα καὶ ταῦτα ἐξ ὁμοίων ἀφορμῶν. οἱ δὲ μεταπέμψαντες αὐτὸν οἰκητήριον ἀπέδειξαν Τιβεριάδα καί τι καὶ ἀργύριον ὥρισαν εἰς τὴν δίαιταν, ἀγορανομίᾳ τε τῆς Τιβεριάδος ἐτίμησαν."},{"number":150,"text":"οὐ μὴν ἐπὶ πλεῖόν γε Ἡρώδης ἐνέμεινε τοῖς δεδογμένοις, καίτοι γε οὐδʼ ὣς ἀρκοῦντα ἦν· ἐν γὰρ Τύρῳ παρὰ συνουσίαν ὑπὸ οἴνου γενομένων αὐτοῖς λοιδοριῶν, ἀνεκτὸν οὐχ ἡγησάμενος Ἀγρίππας τοῦ Ἡρώδου τε ἐπονειδίσαντος εἰς ἀπορίαν καὶ τροφῆς ἀναγκαίας μετάδοσιν, ὡς Φλάκκον τὸν ὑπατικὸν εἴσεισιν φίλον ἐπὶ Ῥώμης τὰ μάλιστα αὐτῷ γεγονότα πρότερον· Συρίαν δὲ ἐν τῷ τότε διεῖπεν."},{"number":151,"text":"Καὶ δεξαμένου Φλάκκου παρὰ τούτῳ διῆγεν παρακατεσχηκότος αὐτὸν ἐκεῖ Ἀριστοβούλου, ὃς ἀδελφὸς ὢν Ἀγρίππου διάφορός τʼ ἦν. οὐ μὴν ἐβλάπτοντο ἔχθρᾳ τῇ ἀλλήλων, ὥστε μὴ φιλίᾳ τοῦ ὑπατικοῦ τὰ εἰκότα τιμὴν φέρεσθαι."},{"number":152,"text":"οὐ μὴν ὅ γε Ἀριστόβουλος ἀνίει τι τοῦ πρὸς τὸν Ἀγρίππαν δυσμενοῦς μέχρι καὶ εἰς ἔχθραν αὐτὸν Φλάκκῳ καθίστησιν, αἰτίαν τοιαύτην ἐπὶ τῇ δυσμενείᾳ παραλαβών."},{"number":153,"text":"Δαμασκηνοὶ Σιδωνίοις περὶ ὅρων διάφοροι καθεστῶτες, μέλλοντος Φλάκκου περὶ τούτων ἀκροᾶσθαι μαθόντες τὸν Ἀγρίππαν ὡς παρʼ αὐτῷ μέγα δύναιτʼ ἂν ἠξίουν μερίδος τῆς αὐτῶν γενέσθαι, ἀργύριόν τε πλεῖστον ὡμολογεῖτο αὐτῷ."},{"number":154,"text":"καὶ ὁ μὲν πάντα ἐπὶ τῇ βοηθείᾳ τῶν Δαμασκηνῶν ὥρμητο πράσσειν. Ἀριστόβουλος δέ, οὐ γὰρ ἐλάνθανεν αὐτὸν ἡ ὁμολογία τῶν χρημάτων, καταγορεύει πρὸς τὸν Φλάκκον. καὶ βασανιζομένου τοῦ πράγματος ἐπεὶ φανερὰ ἦν, ἐξωθεῖ τὸν Ἀγρίππαν φιλίας τῆς πρὸς αὐτόν."},{"number":155,"text":"ὁ δὲ εἰς ὑστάτην περιωσμένος ἀπορίαν εἰς Πτολεμαΐδα παρῆν, καὶ κατὰ τὸ ἄπορον τῆς ἀλλαχόθι διαίτης γνώμην ἐποιεῖτο ἐπὶ τῆς Ἰταλίας πλεῖν. εἰργόμενος δὲ χρημάτων ἀπορίᾳ ἠξίου Μαρσύαν ὄντα αὐτοῦ ἀπελεύθερον ποριστὴν γενέσθαι τῶν ἐπὶ τοιούτοις μηχανῶν δανεισάμενον παρά τινος."},{"number":156,"text":"καὶ ὁ Μαρσύας Πρῶτον κελεύει Βερενίκης ὄντα ἀπελεύθερον τῆς Ἀγρίππου μητρός, διαθήκης δὲ τῆς ἐκείνου δικαίῳ ὑποτελοῦντα τῆς Ἀντωνίας, αὐτῷ γοῦν παρασχεῖν ἐπὶ γράμματι καὶ πίστει τῇ αὐτοῦ."},{"number":157,"text":"ὁ δέ, ἐπεκάλει γὰρ τῷ Ἀγρίππᾳ χρημάτων τινῶν ἀποστέρησιν, ἀναγκάζει τὸν Μαρσύαν δύο μυριάδων Ἀτθίδων συμβόλαιον ποιησάμενον πεντακοσίαις καὶ δισχιλίαις ἔλασσον λαμβάνειν. συνεχώρει δʼ ἐκεῖνος κατὰ τὸ μὴ εἶναι ἄλλως ποιεῖν."},{"number":158,"text":"εἰλημμένου δὲ τοῦ χρήματος τούτου Ἀγρίππας εἰς Ἀνθηδόνα παραγενόμενος καὶ λαβὼν ναῦν ἐν ἀναγωγαῖς ἦν. καὶ γνοὺς Ἐρέννιος Καπίτων ὁ τῆς Ἰαμνείας ἐπίτροπος πέμπει στρατιώτας, οἳ εἰσπράξονται αὐτὸν ἀργυρίου τριάκοντα μυριάδας θησαυρῷ τῷ Καίσαρος ὀφειλομένας ἐπὶ Ῥώμης ὑπʼ αὐτοῦ, ἀνάγκας τε ἐπετίθεσαν τοῦ μενοῦντος."},{"number":159,"text":"καὶ τότε μὲν πείσεσθαι τοῖς κεκελευσμένοις προσποιητὸς ἦν, νυκτὸς δʼ ἐπιγενομένης κόψας τὰ ἀπόγεια ᾤχετο ἐπʼ Ἀλεξανδρείας πλέων. ἔνθα Ἀλεξάνδρου δεῖται τοῦ ἀλαβάρχου μυριάδας εἴκοσι δάνειον αὐτῷ δοῦναι. ὁ δʼ ἐκείνῳ μὲν οὐκ ἂν ἔφη παρασχεῖν, Κύπρῳ δὲ οὐκ ἠρνεῖτο τήν τε φιλανδρίαν αὐτῆς καταπεπληγμένος καὶ τὴν λοιπὴν ἅπασαν ἀρετήν."},{"number":160,"text":"ἡ δὲ ὑπισχνεῖτο, καὶ ὁ Ἀλέξανδρος πέντε τάλαντα αὐτοῖς ἐν τῇ Ἀλεξανδρείᾳ δοὺς τὸ λοιπὸν ἐν Δικαιαρχείᾳ γενομένοις παρέξειν ἐπηγγέλλετο, δεδιὼς τοῦ Ἀγρίππου τὸ εἰς τὰ ἀναλώματα ἕτοιμον. καὶ Κύπρος μὲν ἀπαλλάξασα τὸν ἄνδρα ἐπὶ τῆς Ἰταλίας πλευσούμενον αὐτὴ μετὰ τῶν τέκνων ἐπὶ Ἰουδαίας ἀνέζευξεν."},{"number":161,"text":"Ἀγρίππας δὲ εἰς Ποτιόλους παραβαλὼν ἐπιστολὴν ὡς Τιβέριον τὸν Καίσαρα γράφει διαιτώμενον ἐν Καπρέαις, παρουσίαν τε τὴν αὐτοῦ δηλῶν ἐπὶ θεραπείᾳ καὶ ὄψει τῇ ἐκείνου, καὶ ἀξιῶν ἔφεσιν αὐτῷ γενέσθαι εἰς Καπρέας παραβαλεῖν."},{"number":162,"text":"Τιβέριος δὲ οὐδὲν ἐνδοιάσας τά τε ἄλλα αὐτῷ γράφει φιλανθρωπίᾳ χρώμενος, ἐκτίνει τε χάριν ἀποσημαίνων ἐπὶ τῷ σῶν ἐπανήκειν εἰς τὰς Καπρέας, ἐπεὶ δʼ ἀφικνεῖται μηδὲν ὑφελὼν τοῦ ἐν τοῖς γράμμασι προθύμου ἠσπάζετό τε καὶ ἐξένιζεν."},{"number":163,"text":"τῇ δʼ ἑξῆς Καίσαρι γραμμάτων αὐτῷ παρὰ Ἐρεννίου Καπίτωνος ἀφικομένων, ὅτι Ἀγρίππας μυριάδας τριάκοντα δάνεισμα ποιήσας καὶ πρὸς τὰς καταβολὰς ἐκλιπὼν χρόνον τὸν συγκείμενον ἀπαιτήσεως γενομένης οἴχοιτο φυγὰς ἐκ τῶν ὑπʼ αὐτῷ χωρίων ἄκυρον αὐτὸν καθιστὰς τῆς ἐπὶ τῷ εἰσπραξομένῳ ἐξουσίας,"},{"number":164,"text":"ταύτην ἀναγνοὺς τὴν ἐπιστολὴν περιαλγεῖ τε ὁ Καῖσαρ καὶ διάκλεισιν γενέσθαι τῷ Ἀγρίππᾳ κελεύει εἰσόδων τῶν πρὸς αὐτὸν ἄχρι δὴ καταβολῆς τοῦ χρέους. ὁ δὲ μηδὲν τῇ ὀργῇ τοῦ Καίσαρος καταπλαγεὶς Ἀντωνίας δεῖται Γερμανικοῦ μητρὸς καὶ Κλαυδίου τοῦ ὕστερον γενομένου Καίσαρος, δάνεισμα αὐτῷ δοθῆναι τῶν τριάκοντα μυριάδων, ὡς φιλίας μὴ ἁμάρτοι τῆς πρὸς Τιβέριον."},{"number":165,"text":"ἡ δὲ Βερενίκης τε μνήμῃ τῆς μητρὸς αὐτοῦ, σφόδρα γὰρ ἀλλήλαις ἐχρῶντο αἵδε αἱ γυναῖκες, καὶ αὐτῷ ὁμοτροφίας πρὸς τοὺς ἀμφὶ Κλαύδιον γεγενημένης, δίδωσι τὸ ἀργύριον, καὶ αὐτῷ ἀποτίσαντι τὸ χρέος ἀνεπικώλυτος ἦν ἡ φιλία τοῦ Τιβερίου."},{"number":166,"text":"αὖθις δὲ αὐτῷ Τιβέριος ὁ Καῖσαρ συνίστησιν υἱωνὸν τὸν αὐτοῦ κελεύων τὰ πάντα αὐτῷ ταῖς ἐξόδοις παρατυγχάνειν. Ἀγρίππας δὲ φιλίᾳ δεχθεὶς ὑπὸ τῆς Ἀντωνίας κατὰ θεραπείαν τρέπεται τὴν Γαΐου υἱωνοῦ τε ὄντος αὐτῇ καὶ εὐνοίᾳ τοῦ πατρὸς εἰς τὰ πρῶτα τιμωμένου."},{"number":167,"text":"καὶ γὰρ ἦν ἄλλος Σαμαρεὺς γένος Καίσαρος δὲ ἀπελεύθερος· παρὰ τούτου δάνεισμα μυριάδας ἑκατὸν εὑρόμενος τῇ τε Ἀντωνίᾳ καταβάλλει τὸ ὀφειληθὲν χρέος καὶ τῶν λοιπῶν τῷ ἀναλώματι θεραπεύων τὸν Γάιον μειζόνως ἐν ἀξιώματι ἦν παρʼ αὐτῷ."},{"number":168,"text":"Προϊούσης δὲ ἐπὶ μέγα τῷ Ἀγρίππᾳ τῆς πρὸς Γάιον φιλίας αἰωρουμένοις ποτὲ λόγος περὶ τοῦ Τιβερίου γίνεται, καὶ τοῦ Ἀγρίππου κατʼ εὐχὰς τραπομένου, μόνω δʼ ἤστην, ᾗ τάχος Τιβέριον ὑπεκστάντα τῆς ἀρχῆς Γαΐῳ παραχωρεῖν ἀξιωτέρῳ τὰ πάντα ὄντι, τούτων ἀκροᾶται τῶν λόγων Εὔτυχος, Ἀγρίππου δʼ ἦν ἀπελεύθερος ἡνίοχος, καὶ παραχρῆμα μὲν σιγῇ παρεδίδου."},{"number":169,"text":"κλοπῆς δὲ ἱματίων αὐτῷ τοῦ Ἀγρίππου ἐπικαλουμένης, καὶ ἀκριβῶς δὲ ἐκεκλόφει, φυγὼν καὶ ληφθεὶς ἀγωγῆς αὐτοῦ ἐπὶ Πείσωνα γενομένης, ὃς ἦν φύλαξ τῆς πόλεως, ἐρομένου τὴν αἰτίαν τῆς φυγῆς Καίσαρί φησιν ἀπορρήτους ἔχειν λόγους εἰπεῖν ἐπʼ ἀσφαλείᾳ τῆς σωτηρίας αὐτοῦ φέροντας, ὥστε δήσας αὐτὸν ἔστελλεν εἰς τὰς Καπρέας, καὶ Τιβέριος τῷ αὑτοῦ τρόπῳ χρώμενος εἶχεν αὐτὸν δέσμιον, μελλητὴς εἰ καί τις ἕτερος βασιλέων ἢ τυράννων γενόμενος."},{"number":170,"text":"οὔτε γὰρ πρεσβειῶν ὑποδοχὰς ἐκ τοῦ ὀξέος ἐποιεῖτο ἡγεμόσι τε ἢ ἐπιτρόποις ὑπʼ αὐτοῦ σταλεῖσιν οὐδεμία ἦν διαδοχή, ὁπότε μὴ φθαῖεν τετελευτηκότες· ὅθεν καὶ δεσμωτῶν ἀκροάσεως ἀπερίοπτος ἦν."},{"number":171,"text":"ὥστε καὶ τῶν φίλων ἐρομένων τὴν αἰτίαν τοῦ ἐπὶ τοιούτοις ὁλκῇ χρωμένου, ἔφη τὰς μὲν πρεσβείας τρίβειν, ὅπως μὴ ἀπαλλαγῆς αὐταῖς ἐκ τοῦ ὀξέος γενομένης ἕτεροι πρέσβεις ἐπιχειροτονηθέντες ἐπανίοιεν ὄχλος τε αὐτῷ γίγνοιτο ἐπιδοχαῖς αὐτῶν καὶ πομπαῖς προσκειμένῳ."},{"number":172,"text":"τὰς δʼ ἀρχὰς συγχωρεῖν τοῖς ἅπαξ εἰς αὐτὰς ὑπʼ αὐτοῦ καταστᾶσιν αἰδοῦς προμηθείᾳ τῶν ὑποτελῶν· φύσει μὲν γὰρ εἶναι πᾶσαν ἡγεμονίαν οἰκείαν τοῦ πλεονεκτεῖν· τὰς δὲ μὴ πατρίους, ἀλλʼ εἰς ὀλίγον καὶ ἄδηλον ὁπότε ἀφαιρεθεῖεν καὶ μειζόνως ἐξοτρύνειν ἐπὶ κλοπαῖς τοὺς ἔχοντας."},{"number":173,"text":"εἰ μὲν οὖν ἐφεστήκασιν εἰς πλέον, αὐτοὺς ἄδην τῶν κλοπῶν ἕξειν ὑπὸ τοῦ πολλοῦ τῶν κεκερδημένων ἀμβλυτέρως τὸ λοιπὸν αὐταῖς χρωμένους. διαδοχῆς δʼ ἐπιπαραγενομένης ἐκ τοῦ ὀξέος μηδαμῶς ἂν ἀρκέσαι τοὺς ἆθλα τοῖς ἄρχουσι προκειμένους ἀναστροφῆς αὐτοῖς οὐ διδομένης καιρῶν, ἐν οἷς πλήρεις οἱ προειληφότες γενόμενοι ὑποδιδοῖέν τε σπουδῆς τῆς ἐπὶ τῷ λαμβάνειν, διὰ τὸ πρὶν ἐν καιρῷ γενέσθαι μεταστῆναι."},{"number":174,"text":"παράδειγμά τε αὐτοῖς φησι τοῦτον τὸν λόγον· τραυματίᾳ τινὶ κειμένῳ μυῖαι κατὰ πλῆθος τὰς ὠτειλὰς περιέστασαν. καί τις τῶν παρατυχόντων οἰκτείρας αὐτοῦ τὴν δυστυχίαν καὶ νομίσας ἀδυναμίᾳ μὴ βοηθεῖν οἷός τʼ ἦν ἀποσοβεῖν αὐτὰς παραστάς."},{"number":175,"text":"καὶ δεομένου παύσασθαι τῶν ἐπὶ τοιοῖσδε, ὑπολαβὼν ἤρετο τὴν αἰτίαν τοῦ ἀπρομηθοῦς εἰς τὴν διαφυγὴν κακοῦ τοῦ ἐφεστηκότος. μειζόνως γὰρ ἂν ἀδικοῖς με, εἶπε, ταύτας ἀπαγαγών. ταῖς μέν γε ἤδη πληρωθείσαις τοῦ αἵματος οὐκέθʼ ὁμοίως ἔπειξις ὄχλον μοι παρασχεῖν, ἀλλά πῃ καὶ ἀνίσχουσιν. αἱ δʼ ἀκραιφνεῖ τῷ κατʼ αὐτὰς λιμῷ συνελθοῦσαι καὶ τετρυμένον ἤδη παραλαμβάνουσαι κἂν ὀλέθρῳ παραδοῖεν ."},{"number":176,"text":"διὰ τάδε οὖν καὐτὸς ὑπὸ πολλῶν τῶν κλοπῶν διεφθαρμένοις τοῖς ὑποτελέσιν προμηθὲς εἶναι μὴ συνεχὲς ἐξαποστέλλειν τοὺς ἡγησομένους, οἳ ἐν τρόπῳ μυιῶν ἐκπολεμοῖεν αὐτούς, φύσει πρὸς κέρδος ὀρωρεγμένοις σύμμαχον παραλαμβάνοντες τὴν ἐλπίδα τοῦ ταχέως ἀφαιρεθησομένου τὴν ἐνθένδε ἡδονήν."},{"number":177,"text":"μαρτυρήσει δέ μου τῷ λόγῳ περὶ τῆς ἐπὶ τοιούτοις φύσεως Τιβερίου τὸ ἔργον αὐτό· ἔτη γὰρ δύο πρὸς τοῖς εἴκοσιν αὐτοκράτωρ γενόμενος δύο τοὺς πάντας Ἰουδαίοις ἐξέπεμψεν διοικήσοντας τὸ ἔθνος, Γρᾶτον τε καὶ Πιλᾶτον, ὃς αὐτῷ διεδέξατο τὴν ἡγεμονίαν."},{"number":178,"text":"καὶ οὐκ ἐπὶ μὲν Ἰουδαίων τοιοῦτος ἦν, ἑτεροῖος δὲ ἐπὶ τῶν λοιπῶν ὑπηκόων. ἀλλὰ καὶ τῶν δεσμωτῶν τὴν ὑπερβολὴν τῆς ἀκροάσεως ἀπεσήμαινεν ὑπὸ τοῦ δικαιωθεῖσι μὲν θανάτῳ κούφισιν γενέσθαι τῶν ἐνεστηκότων κακῶν, διὰ τὸ μὴ ἐπʼ ἀρετῇ τῶν ἐπὶ τοιούτοις τύχῃ συνελθεῖν, τριβομένοις δὲ ἀχθηδόνι τῇ ἐπικειμένῃ μείζονα προσρέπειν τὴν δυστυχίαν."},{"number":179,"text":"Διὰ μὲν δὴ τάδε καὶ Εὔτυχος ἀκροάσεώς τε οὐκ ἐτύγχανε· καὶ δεσμοῖς ἐνείχετο. χρόνου δὲ ἐγγενομένου Τιβέριός τε ἐκ τῶν Καπρεῶν εἰς Τουσκουλανὸν παραγίνεται ὅσον ἀπὸ σταδίων ἑκατὸν τῆς Ῥώμης, καὶ ὁ Ἀγρίππας ἀξιοῖ τὴν Ἀντωνίαν διαπράξασθαι γενέσθαι τῷ Εὐτύχῳ τὴν ἀκρόασιν ἐφʼ οἷστισι τὴν κατηγορίαν ποιοῖτο αὐτοῦ."},{"number":180,"text":"τιμία δὲ ἦν Ἀντωνία Τιβερίῳ εἰς τὰ πάντα συγγενείας τε ἀξιώματι, Δρούσου γὰρ ἦν ἀδελφοῦ αὐτοῦ γυνή, καὶ ἀρετῇ τοῦ σώφρονος· νέα γὰρ χηρεύειν παρέμεινεν γάμῳ τε ἀπεῖπεν τῷ πρὸς ἕτερον καίπερ τοῦ Σεβαστοῦ κελεύοντός τινι γαμεῖσθαι, καὶ λοιδοριῶν ἀπηλλαγμένον διεσώσατο αὐτῆς τὸν βίον."},{"number":181,"text":"ἰδίᾳ τε εὐεργέτις ἦν εἰς τὰ μέγιστα τοῦ Τιβερίου· ἐπιβουλῆς γὰρ μεγάλης συστάσης ἐπʼ αὐτὸν ὑπὸ Σηιάνου φίλου τε ἀνδρὸς καὶ δύναμιν ἐν τῷ τότε μεγίστην ἔχοντος διὰ τὸ τῶν στρατευμάτων εἶναι ἡγεμονίαν αὐτῷ, καὶ τῆς τε βουλῆς οἱ πολλοὶ καὶ τῶν ἀπελευθέρων προσέθεντο καὶ τὸ στρατιωτικὸν διέφθαρτο, προυκοπτέν τε ἡ ἐπιβουλὴ ἐπὶ μέγα κἂν ἐπέπρακτο Σηιάνῳ τὸ ἔργον μὴ τῆς Ἀντωνίας τόλμῃ χρησαμένης σοφωτέρᾳ τῆς Σηιάνου κακουργίας."},{"number":182,"text":"ἐπεὶ γὰρ μανθάνει τὰ ἐπὶ τῷ Τιβερίῳ συντεθειμένα, γράφει πρὸς αὐτὸν τὰ πάντα ἀκριβῶς καὶ Πάλλαντι ἐπιδοῦσα τὰ γράμματα τῷ πιστοτάτῳ τῶν δούλων αὐτῆς ἐκπέμπει πρὸς Τιβέριον εἰς τὰς Καπρέας. ὁ δὲ μαθὼν τόν τε Σηιᾶνον κτείνει καὶ τοὺς συνεπιβούλους, τήν τε Ἀντωνίαν καὶ πρὶν ἀξιολόγως ἄγων τιμιωτέραν τε ὑπελάμβανεν κἀπὶ τοῖς πᾶσι πιθανήν."},{"number":183,"text":"ὑπὸ δὴ ταύτης τῆς Ἀντωνίας ὁ Τιβέριος παρακαλούμενος ἐξετάσαι τὸν Εὔτυχον, ἀλλʼ εἰ μὲν καταψεύσειε, φησὶν ὁ Τιβέριος, ἔτι δε Ἀγρίππου τὰ εἰρημένα Εὔτυχος, ἀρκοῦσαν κομίζεται παρʼ αὐτοῦ τιμωρίαν, ἣν ἐπιτετίμηκα αὐτός· εἰ δὲ βασανιζομένου ἀληθῆ φανείη τὰ εἰρημένα, μήπου κολάζειν ποθῶν τὸν ἀπελεύθερον ἐπʼ αὐτὸν μᾶλλον καλοίη τὴν δίκην ."},{"number":184,"text":"καὶ ὁ Ἀγρίππας ταῦτα φαμένης πρὸς αὐτὸν Ἀντωνίας πολλῷ μᾶλλον ἐπέκειτο ἀξιῶν ἐξέτασιν γενέσθαι τοῦ πράγματος, καὶ ἡ Ἀντωνία, οὐ γὰρ ἀνίει πολὺς ὢν ὁ Ἀγρίππας ἐπὶ τοῖσδε δεῖσθαι, καιρὸν παραλαβοῦσα τοιοῦτον·"},{"number":185,"text":"αἰωρεῖτο μὲν Τιβέριος ἐπὶ φορείου κείμενος, προϊόντων Γαΐου τε τοῦ ἐκείνης υἱωνοῦ καὶ Ἀγρίππα, ἀπʼ ἀρίστου δʼ ἦσαν, παραπεριπατοῦσα τῷ φορείῳ παρεκάλει καλεῖσθαί τε τὸν Εὔτυχον καὶ ἐξετάζεσθαι."},{"number":186,"text":"ὁ δέ ἀλλʼ ἴστων μὲν Ἀντωνία, εἶπεν, οἱ θεοί, ὅτι μὴ τῇ ἐμαυτοῦ γνώμῃ ἀνάγκῃ δὲ τῆς σῆς παρακλήσεως ἐξαγόμενος πράξω τὰ πραξόμενα. ταῦτα εἰπὼν κελεύει Μάκρωνα, ὃς Σηιανοῦ διάδοχος ἦν, τὸν Εὔτυχον ἀγαγεῖν. καὶ ὁ μὲν οὐδὲν εἰς ἀναβολὰς παρῆν. Τιβέριος δʼ αὐτὸν ἤρετο, τί καὶ ἔχοι λέγειν κατʼ ἀνδρὸς ἐλευθερίαν αὐτῷ παρεσχηκότος."},{"number":187,"text":"ὁ δέ φησιν, ὦ δέσποτα, αἰωροῦντο μὲν ἐφʼ ἁμάξης Γάιός τε οὗτος καὶ Ἀγρίππας σὺν αὐτῷ καί σφων ἑζόμην παρὰ τοῖν ποδοῖν, λόγων δὲ πολλῶν ἀνακυκλουμένων Ἀγρίππας φησὶ πρὸς Γάιον· εἰ γὰρ ἀφίκοιτό ποτε ἡμέρα, ᾗ μεταστὰς ὁ γέρων οὗτος χειροτονοίη σε ἡγεμόνα τῆς οἰκουμένης· οὐδὲν γὰρ ἡμῖν Τιβέριος ὁ υἱωνὸς αὐτοῦ γένοιτʼ ἂν ἐμποδὼν ὑπὸ σοῦ τελευτῶν, καὶ ἥ τε οἰκουμένη γένοιτʼ ἂν μακαρία κἀγὼ πρὸ αὐτῆς."},{"number":188,"text":"Τιβέριος δὲ πιστὰ ἡγησάμενος τὰ εἰρημένα καὶ ἅμα μῆνιν ἀναφέρων τῷ Ἀγρίππᾳ παλαιάν, διότι κελεύσαντος αὐτοῦ θεραπεύειν Τιβέριον υἱωνόν τε αὐτοῦ γεγονότα καὶ Δρούσου παῖδα ὄντα, ὁ Ἀγρίππας ἀτίμως ἦγεν παρακροασάμενος τὰς ἐπιστολὰς καὶ πᾶς ὡς τὸν Γάιον μετεκάθιζεν,"},{"number":189,"text":"τοῦτον μὲν δή, φησί, Μάκρων, δῆσον. Μάκρων δὲ τὰ μὲν οὐ σαφῶς ὅντινα προστάξειεν ἐξεπιστάμενος, τὰ δὲ οὐκ ἂν προσδοκῶν περὶ τῷ Ἀγρίππᾳ αὐτὸν κελεῦσαί τι τοιοῦτον, ἐπανεῖχεν ἀκριβωσόμενος τὰ εἰρημένα."},{"number":190,"text":"ἐπεὶ δʼ ὁ Καῖσαρ περιοδεύσας τὸν ἱππόδρομον λαμβάνει τὸν Ἀγρίππαν ἑστηκότα, καὶ μὴν δή, φησίν, Μάκρων, τοῦτον εἶπον δεθῆναι . τοῦ δὲ ἐπανερομένου ὅντινα, Ἀγρίππαν γε εἶπεν."},{"number":191,"text":"καὶ ὁ Ἀγρίππας τρέπεται μὲν κατὰ δεήσεις, τοῦ τε παιδὸς ᾧ συνετέθραπτο μνημονεύων καὶ τοῦ Τιβερίου τῆς ἐκτροφῆς, οὐ μὴν ἤνυέν γέ τι, ἀλλʼ ἦγον αὐτὸν ἐν πορφυρίσι δέσμιον."},{"number":192,"text":"καὶ καῦμά τε γὰρ σφοδρὸν ἦν καὶ ὑπὸ οἴνου τοῦ ἐπὶ σιτίοις μὴ πολλοῦ γεγονότος δίψος ἐξέκαιεν αὐτόν, καί τι καὶ ἠγωνία καὶ τὸ παρʼ ἀξίαν προσελάμβανεν, θεασάμενός τινα τῶν Γαΐου παίδων Θαυμαστὸν ὄνομα ὕδωρ ἐν ἀγγείῳ κομίζοντα ᾔτησε πιεῖν."},{"number":193,"text":"καὶ ὀρέξαντος προθύμως πιών, ἀλλʼ εἴπερ ἐπʼ ἀγαθοῖς, φησίν, ὦ παῖ, τὰ τῆσδέ σου τῆς διακονίας γέγονεν, διαφυγῆς μοι γενομένης τῶνδε τῶν δεσμῶν οὐκ ἂν βραδύνοιμι ἐλευθερίαν εἰσπρασσόμενός σοι παρὰ Γαΐου, ὃς καὶ δεσμώτῃ μοι γενομένῳ διακονεῖσθαι καθάπερ ἐν τῷ πρότερον καθεστηκότι σχήματι τῆς περὶ ἐμὲ ἀξιώσεως οὐκ ἐνέλιπες. καὶ οὐκ ἐψεύσατο ταῦτα εἰπών, ἀλλὰ δὴ ἠμείψατο·"},{"number":194,"text":"ἐν ὑστέρῳ γὰρ βασιλεύσας τὸν Θαυμαστὸν μειζόνως ἐλεύθερόν τε ἀφῆκε παρὰ Γαΐου Καίσαρος γεγονότος λαβὼν καὶ τῆς οὐσίας ἐπίτροπον καθίστησι, τελευτῶν τε τῷ υἱεῖ Ἀγρίππᾳ καὶ Βερενίκῃ τῇ θυγατρὶ ἐπὶ τοῖς ὁμοίοις διακονησόμενον κατέλιπεν, ἐν τιμῇ τε ὢν ταύτῃ γηραιὸς τελευτᾷ. καὶ ταῦτα μὲν ὕστερον."},{"number":195,"text":"Ἀγρίππας δὲ τότε δεθεὶς εἱστήκει πρὸ τοῦ βασιλείου πρός τινι δένδρῳ κλιθεὶς ὑπὸ ἀθυμίας μετὰ πολλῶν οἳ ἐδέδεντο. καί τινος ὀρνέου καθίσαντος ἐπὶ τοῦ δένδρου, ᾧ Ἀγρίππας προσεκέκλιτο, βουβῶνα δὲ οἱ Ῥωμαῖοι τὸν ὄρνιν τοῦτον καλοῦσιν, τῶν δεσμωτῶν τις Γερμανὸς θεασάμενος ἤρετο τὸν στρατιώτην, ὅστις εἴη ὁ ἐν τῇ πορφυρίδι."},{"number":196,"text":"καὶ μαθὼν μὲν Ἀγρίππαν ὄνομα αὐτῷ, Ἰουδαῖον δὲ τὸ γένος καὶ τῶν ἐκείνῃ ἀξιολογωτάτων, ἠξίωσεν τὸν συνδεδεμένον αὐτῷ στρατιώτην πλησίον ἐλθεῖν διὰ λόγων· βούλεσθαι γάρ τινα ἀμφὶ τῶν πατρίων ἔρεσθαι αὐτόν."},{"number":197,"text":"καὶ τυχών, ἐπεὶ πλησίον ἵσταται, διʼ ἑρμηνέως ὦ νεανία, φησίν, καταχθεῖ μέν σε τὸ αἰφνίδιον τῆς μεταβολῆς πολλήν τε οὕτως καὶ ἀθρόαν ἐπαγαγὸν τὴν τύχην, ἀπιστία δέ σοι λόγων, οἳ ἐπὶ διαφυγῇ κακοῦ τοῦ ἐφεστηκότος διαιροῖντο τοῦ θείου τὴν πρόνοιαν."},{"number":198,"text":"ἴσθι γε μήν, θεοὺς τοὺς ἐμοὶ πατρῴους καὶ τοὺς τοῖσδε ἐγχωρίους, οἳ τόνδε ἐπρυτάνευσαν ἡμῖν τὸν σίδηρον, ἐπομνύμενος λέξω τὰ πάντα οὔτε ἡδονῇ γλωσσάργῳ διδοὺς τὸν ἐπʼ αὐτοῖς λόγον οὔτε διακενῆς εὐθυμεῖν σε ἐσπουδακώς."},{"number":199,"text":"αἱ γὰρ ἐπὶ τοιοῖσδε προαγορεύσεις ὑστερηκότος τοῦ ἀποδείξοντος ἔργου χαλεπωτέραν προστίθενται τὴν ἀχθηδόνα τοῦ μηδʼ εἰ τὴν ἀρχὴν ἀκροάσαιτο αὐτῶν. ἀλλὰ καὶ τὸ ἐμὸν κινδύνοις παραβαλλόμενος δίκαιον ἡγησάμην σοι διασαφῆσαι τὴν προαγόρευσιν τῶν θεῶν."},{"number":200,"text":"οὐκ ἔσθʼ ὅπως οὐκ εὐθέως ἀπαλλαγή τέ σοι τῶνδε τῶν δεσμῶν παρέσται καὶ πρόοδος ἐπὶ μήκιστον ἀξιώματός τε καὶ δυνάμεως, ζηλωτός τε ἂν γένοιο πᾶσιν, οἳ νῦν διʼ οἴκτου τὰς τύχας σου λαμβάνουσιν, εὐδαίμονά τε ἂν ποιοῖο τὴν τελευτὴν παισίν, οἷς ἔσῃ τὸν βίον καταλειπόμενος. μνημονεύειν δέ, ὁπότε εἰσαῦθις τὸν ὄρνιν θεάσαιο τοῦτον, πέντε ἡμέραις σοι τὴν τελευτὴν ἐσομένην."},{"number":201,"text":"ταῦτα πεπράξεται μὲν ᾗπερ ἀποσημαίνει τοῦ θεοῦ τὸ ἐξαποστεῖλαν τουτονὶ τὸν ὄρνιν. προγνώσει τε αὐτῶν σύνεσιν τὴν παραγενομένην ἀποστερεῖν σε ἄδικον ἡγησάμην, ὅπως ἐπιστάμενος ἀγαθοῦ μέλλοντος λυσιτελεῖν ἐν ὀλίγῳ τὴν ἀχθηδόνα τοῦ παρόντος τιθοῖο. μνήμην δὲ ποιεῖσθαι εἰς χεῖράς σου παραγενομένου τοῦ εὐδαίμονος καὶ τοῦ καθʼ ἡμᾶς διαφευξομένου δυστυχίαν, ᾗ τανῦν σύνεσμεν."},{"number":202,"text":"καὶ ὁ μὲν Γερμανὸς τοσάδε προειπὼν εἰς τοσόνδε ὦφλεν τῷ Ἀγρίππᾳ γέλωτα, ἐφʼ ὅσον ἐν τοῖς ὕστερον κατεφάνη τεθαυμάσθαι ἄξιος. ἡ δὲ Ἀντωνία χαλεπῶς φέρουσα τοῦ Ἀγρίππου τὴν δυστυχίαν τὸ μὲν Τιβερίῳ περὶ αὐτοῦ διαλέγεσθαι ἐργωδέστερον ἑώρα καὶ ἄλλως ἐπʼ ἀπράκτοις γενησόμενον,"},{"number":203,"text":"εὑρίσκετο δʼ αὐτῷ παρὰ τοῦ Μάκρωνος στρατιωτῶν τε μετρίων ἀνδρῶν οἳ παραφυλάξειαν αὐτὸν ἐν φροντίσιν καὶ ἑκατοντάρχου τοῦ ἐφεστηξομένου τε ἐκείνοις καὶ συνδέτου ἐσομένου, λουτρά τε καθʼ ἡμέραν συγκεχωρῆσθαι καὶ ἀπελευθέρων καὶ φίλων εἰσόδους τήν τε ἄλλην ῥᾳστώνην, ἣ τῷ σώματι γένοιτʼ ἄν."},{"number":204,"text":"εἰσῄεσάν τε ὡς αὐτὸν φίλος τε Σίλας καὶ τῶν ἀπελευθέρων Μαρσύας καὶ Στοιχεὺς τροφὰς εἰσκομίζοντες αἷς ἔχαιρεν καὶ διʼ ἐπιμελείας πάσης ἔχοντες, ἱμάτιά τε κομίζοντες ἐπὶ προσποιήσει πράσεως ὁπότε νὺξ γένοιτο ὑπεστρώνυσαν αὐτῷ συμπράξει τῶν στρατιωτῶν Μάκρωνος προειρηκότος· καὶ ταῦτα ἐπράσσετο ἐπὶ μῆνας ἕξ. καὶ τὰ μὲν κατὰ Ἀγρίππαν ἐν τούτοις ἦν."},{"number":205,"text":"Τιβέριος δʼ ἐπανελθὼν εἰς τὰς Καπρέας ἐμαλακίζετο τὰ μὲν πρῶτα μετρίως, ἐπιδούσης δʼ εἰς τὸ μᾶλλον τῆς νόσου πονηρὰς ἔχων περὶ αὐτῷ τὰς ἐλπίδας Εὔοδον, ὃς ἦν αὐτῷ τιμιώτατος τῶν ἀπελευθέρων, κελεύει τὰ τέκνα προσαγαγεῖν πρὸς αὐτόν· χρῄζειν γὰρ ἀφικέσθαι σφίσι διὰ λόγων πρὶν ἢ τελευτᾶν."},{"number":206,"text":"ἦσαν δʼ αὐτῷ παῖδες γνήσιοι μὲν οὐκέτι· Δροῦσος γὰρ δὴ ὁ μόνος αὐτῷ γεγονὼς ἐτύγχανεν τεθνεώς· υἱὸς δὲ τούτου κατελείπετο Τιβέριος ἐπικαλούμενος Γέμελλος, Γάιός τε Γερμανικοῦ παῖς, ἀδελφοῦ υἱὸς γεγονώς, νεανίας τε ἤδη καὶ παιδείαν ἐκπεπονηκὼς ἐπὶ πλεῖστον εὐνοίᾳ τε τοῦ δήμου τιμώμενος διὰ τὴν Γερμανικοῦ τοῦ πατρὸς ἀρετήν·"},{"number":207,"text":"ἐπὶ μέγιστον γὰρ δὴ οὗτος προῆλθεν παρὰ τοῖς πλήθεσι τιμῆς εὐσταθείᾳ τρόπου καὶ δεξιότητι τοῦ ὁμιλεῖν ἀνεπαχθὴς ὢν καὶ τὴν ἀξίωσιν κτώμενος τῷ βούλεσθαι ἴσος πᾶσιν εἶναι."},{"number":208,"text":"ἐξ ὧν οὐ μόνον ὁ δῆμος καὶ ἡ βουλὴ μειζόνως ἦγον αὐτόν, ἀλλὰ καὶ τῶν ὑποτελῶν ἕκαστον ἐθνῶν, οἱ μὲν ὡμιληκότες ἁλισκόμενοι τῇ χάριτι τῆς ἐντεύξεως, οἱ δὲ πύστει τῆς ἐκείνων ἀφηγήσεως παραλαμβάνοντες."},{"number":209,"text":"πένθος τε αὐτοῦ τελευτήσαντος προυτέθη πᾶσιν οὐ θεραπείᾳ τῆς ἀρχῆς ἐπιψευδομένων τὴν συμφοράν, λύπῃ δὲ ἀληθεῖ οἰκειουμένων διὰ τὸ ἴδιον τυχεῖν ἑκάστοις τὴν μετάστασιν αὐτοῦ ὑπειλῆφθαι·"},{"number":210,"text":"οὕτως ἀνεπαχθῶς ὡμίλησε τοῖς ἀνθρώποις. ἐξ ὧν μέγα ὄφελος καὶ τῷ παιδὶ αὐτοῦ παρὰ πᾶσιν κατελέλειπτο τοῖς τε ἄλλοις καὶ μάλιστα τὸ στρατιωτικὸν ἦρτο, ἀρετὴν ἀριθμοῦντες τὸ περὶ τῆς ἀρχῆς ἐκείνῳ περιγενησομένης, εἰ δεήσει, καὶ τελευτᾶν."},{"number":211,"text":"Ὁ δὲ Τιβέριος Εὐόδῳ πρόσταγμα ποιησάμενος κατὰ τὴν ὑστεραίαν ὑπὸ τὴν ἕω εἰσαγαγεῖν τοὺς παῖδας εὔχεται τοῖς πατρίοις θεοῖς σημεῖόν τι πρόφαντον αὐτῷ δεῖξαι περὶ τοῦ τὴν ἡγεμονίαν διαδεξομένου, σπεύδων μὲν τῷ υἱεῖ τοῦ παιδὸς αὐτὴν καταλιπεῖν, μεῖζον δὲ δόξης τε καὶ βουλήσεως τῆς αὐτοῦ πεπιστευκὼς τοῦ θεοῦ τὸ ἐπʼ αὐτοῖς ἀποφανούμενον."},{"number":212,"text":"οἰώνισμα δʼ οὖν αὐτῷ προύκειτο, εἰς ἐκεῖνον ἥξειν τὴν ἡγεμονίαν, ὃς ἂν κατὰ τὴν ἐπιοῦσαν ἀφίκοιτο πρότερος πρὸς αὐτόν. ταῦτα διανοηθεὶς πέμπει παρὰ τοῦ υἱωνοῦ τὸν παιδαγωγὸν κελεύων ὑπὸ πρώτην ὥραν ἄγειν τὸν παῖδα ὡς αὐτόν, καταμελήσεσθαι στρατηγίας τὸν θεὸν ὑπολαμβάνων· ὁ δʼ ἀντεψήφιζεν αὐτοῦ τὴν χειροτονίαν."},{"number":213,"text":"ὁ μὲν δὴ ταῦτʼ ἐνθυμησάμενος, ἐπεὶ τάχιστα ἡμέρα ἦν, κελεύει τὸν Εὔοδον εἰσκαλεῖν τῶν παίδων τὸν παρόντα πρότερον. ἐξελθὼν δʼ ἐκεῖνος καὶ τὸν Γάιον πρὸ τοῦ δωματίου καταλαβών, ὁ γὰρ Τιβέριος οὐ παρῆν μετεώρου τῆς τροφῆς αὐτῷ γενομένης, ᾔδει δὲ οὐδὲν ὧν ἐβούλετο ὁ δεσπότης, καλεῖ σε, φησίν, ὁ πατήρ , καὶ εἰσήγαγεν αὐτόν."},{"number":214,"text":"Τιβέριος δὲ ὡς θεᾶται Γάιον, τότε πρῶτον εἰς ἐπίνοιαν ἐλθὼν τοῦ θείου τῆς ἐξουσίας καὶ τὴν κατʼ αὐτὸν ἡγεμονίαν παντελῶς ἀφῃρημένην ἐπικυροῦν οἷς ψηφίσαιτο δυνάμεως ἐκεῖθεν αὐτῷ μὴ παραγενομένης, πολλὰ δὴ κατολοφυράμενος αὑτὸν μὲν τοῦ ἐφʼ οἷς προβουλεύσειε κυροῦν ἀφῃρημένου τὸ κράτος,"},{"number":215,"text":"Τιβέριον δὲ τὸν υἱωνόν, ὡς τῆς τε Ῥωμαίων ἀρχῆς ὁμοῦ διαμάρτοι καὶ τῆς σωτηρίας κεχρημένον διὰ τὸ ἐπʼ ἄλλων κρειττόνων οὐκ ἀνεκτὸν εἰσηγησαμένω τὴν συναναστροφὴν κείσεσθαι τὴν σωτηρίαν αὐτῷ τοῦ συγγενοῦς μὴ ὠφελεῖν δυναμένου, φόβῳ τε καὶ μίσει τοῦ ἐφεστηκότος χρησομένου πρὸς αὐτόν, τὰ μὲν ὡς προσεδρεύοντα τῇ ἀρχῇ, τὰ δὲ ὡς ἀντεπιβουλεύειν ὑπέρ τε τῆς σωτηρίας καὶ τῆς ἀντιλήψεως τῶν πραγμάτων μὴ ἀφησόμενον."},{"number":216,"text":"ἦν δὲ καὶ γενεθλιαλογίᾳ Τιβέριος μάλιστα προσκείμενος καὶ κατορθούμενα αὐτῇ μειζόνως τῶν εἰς τόδε ἀνακειμένων ἑκόντων τὸν βίον ἐξηγμένος. Γάλβαν οὖν ποτε θεασάμενος ὡς αὐτὸν εἰσιόντα φησὶ πρὸς τοὺς ἐπιτηδειοτάτους αὐτῷ, ὡς παραγίνοιτο ἀνὴρ τῇ Ῥωμαίων προτιμησόμενος ἡγεμονίᾳ."},{"number":217,"text":"τά τε πάντα μαντειῶν ὁπόσα ἐχόμενα πιθανὰ ἡγούμενος ἡγεμόνων μάλιστα ἀνὴρ οὗτος ὑπὸ τοῦ ἐπαληθείοντος αὐτῶν ἐπὶ τοῖς πράγμασιν ἐχρῆτο αὐταῖς."},{"number":218,"text":"καὶ τότε ἐν χαλεποῖς ἦν συντυχίᾳ τοῦ γεγονότος, ὡς ἐπʼ ἀπολωλότι τῷ υἱεῖ τοῦ παιδὸς ἀχθεινῶς διατιθέμενος καὶ κατάμεμψιν αὐτοῦ ποιούμενος τοῦ κατὰ τὴν οἰώνισιν προμηθοῦς· παρὸν γὰρ ἂν αὐτῷ λύπης ἀπηλλαγμένῳ τελευτᾶν ἀμαθίᾳ τῶν ἐσομένων, διατρίβεσθαι τῷ προεγνωκὼς τὴν ἐσομένην δυστυχίαν τῶν φιλτάτων τελευτᾶν."},{"number":219,"text":"καίπερ δὲ συντεταραγμένος τῇ παρὰ δόξαν τῆς ἀρχῆς εἰς οὓς οὐκ ἤθελεν περιόδῳ, ἄκων δὲ καὶ μὴ βουλόμενος φησὶ γοῦν πρὸς τὸν Γάιον· ὦ παῖ, καίπερ μοι συγγενεστέρου Τιβερίου ἢ κατὰ σὲ ὄντος δόξῃ τε τῇ ἐμαυτοῦ καὶ τῷ ὁμοψήφῳ ἐπʼ αὐτῇ τῶν θεῶν σοὶ φέρων ἐγχειρίζω τὴν Ῥωμαίων ἡγεμονίαν."},{"number":220,"text":"ἀξιῶ δέ σε μηδὲν ἀμνημονεῖν ὁμιλήσαντα αὐτῇ μήτʼ εὐνοίας τῆς ἐμῆς, ὃς εἰς τοσόνδε ἀξιώματος καθίστημι μέγεθος,"},{"number":221,"text":"μήτε τοῦ πρὸς Τιβέριον συγγενοῦς, ἀλλʼ ἐπιστάμενον, ὡς σύν τε τοῖς θεοῖς καὶ μετʼ αὐτοὺς τοιῶνδέ σοι κατασταίην ἀγαθῶν ποριστής, ἀμείβεσθαί μου τὸ ἐπʼ αὐτοῖς πρόθυμον καὶ ἅμα Τιβερίου φροντίζειν διὰ τὴν συγγένειαν, ἄλλως τε γινώσκειν, ὡς τεῖχός σοι καὶ τῆς ἀρχῆς ὁμοῦ καὶ τῆς σωτηρίας περιὼν γίνοιτο ἂν Τιβέριος, φροίμιον δὲ τοῦ δυστυχοῦς μεθιστάμενος."},{"number":222,"text":"αἵ τε γὰρ μονώσεις ἐπικίνδυνοι τοῖς εἰς τηλικούτων πραγμάτων ὄγκον καταστᾶσιν καὶ θεοῖς οὐκ ἀτιμώρητα ὁπόσα παρὰ δίκην πρασσόμενα ἀφανίζοι τοῦ νόμου τὸ ἑτέρως πράσσειν παρακαλοῦν. ταῦτα μὲν ὁ Τιβέριος ἔλεγεν,"},{"number":223,"text":"οὐ μὴν πιθανὸς ἦν Γαΐῳ καίπερ ὑπισχνουμένῳ, ἀλλὰ καταστὰς εἰς τὴν ἀρχὴν τόν τε Τιβέριον μαντείαις ἀναιρεῖ ταῖς ἐκείνου καὐτὸς ἐπιβουλῶν ἐπʼ αὐτὸν συντεθεισῶν μετʼ οὐ πολὺ τελευτᾷ."},{"number":224,"text":"Τιβέριος δὲ τὸν Γάιον ἀποδείξας διάδοχον τῆς ἡγεμονίας ὀλίγας ἐπιβιοὺς ἡμέρας ἔθανεν σχὼν αὐτὸς τὴν ἀρχὴν ἡμέρας τρεῖς καὶ πέντε μῆνας πρὸς ἐνιαυτοῖν δυοῖν καὶ εἴκοσι. Γάιος δὲ ἦν αὐτοκράτωρ τέταρτος."},{"number":225,"text":"Ῥωμαίοις δʼ ἦν μὲν πύστις τῆς Τιβερίου τελευτῆς εὐφραίνοντό τε τῷ ἀγαθῷ τῆς ἀγγελίας, οὐ μὴν πιστεύειν γε θάρσος ἦν αὐτοῖς, οὐ τῷ μὴ βούλεσθαι, πρὸ πολλῶν γὰρ ἂν ἐτίμησαν χρημάτων τὸ ἐπαληθεῦσαν τῶν λόγων, δέει δὲ μὴ ψευδοῦς τῆς ἀγγελίας γενομένης προεξαναστάντες ἐπὶ δηλώσει τοῦ αὐτῶν χάρματος εἶτʼ ἀπολλύοιντο διαβολῆς αὐτῶν γενομένης·"},{"number":226,"text":"πλεῖστα γὰρ ἀνὴρ εἷς οὗτος Ῥωμαίων τοὺς εὐπατρίδας εἰργάσατο δεινὰ δυσόργητος ἐπὶ πᾶσιν ὢν καὶ ἀνήκεστος εἰς τὸ ἐργάζεσθαι καταστάς, εἰ καὶ χωρὶς λόγου τὴν αἰτίαν ἐπανέλοιτο τοῦ μισεῖν, καὶ ἐπὶ πᾶσι μὲν οἷς κρίνοιεν ἐξαγριοῦν φύσιν ἔχων, εἰς θάνατον δὲ καὶ τῶν κουφοτάτων ἀνατιθεὶς τὴν ζημίαν."},{"number":227,"text":"ὥστε ἡδονῇ τοῦ ἐπʼ αὐτῷ λόγου φέροντος τὴν ἀκρόασιν εἰς ὅσον ἐβούλοντο ἀπολαύσματι χρῆσθαι ἐπεκεκώλυντο δείμασι κακῶν, ἃ προεωρᾶτο ψευσθεῖσι τῆς ἐλπίδος."},{"number":228,"text":"Μαρσύας δὲ τοῦ Ἀγρίππου ὁ ἀπελεύθερος πυθόμενος τοῦ Τιβερίου τὴν τελευτὴν ὠθεῖτο δρομαῖος τὸν Ἀγρίππαν εὐαγγελιούμενος, καὶ καταλαβὼν ἐν ἐξόδοις ὄντα εἰς τὸ βαλανεῖον συννεύσας πρὸς αὐτὸν γλώσσῃ τῇ Ἑβραίων τέθνηκεν ὁ λέων φησίν."},{"number":229,"text":"ὁ δὲ σύνεσίν τε τοῦ λόγου ποιησάμενος καὶ χάρματι τῷ ἐπʼ αὐτῷ περιενεχθείς ἀλλά σοι τῶν ἁπάντων καὶ τῆς ἐπὶ τῷδε εὐαγγελίας χάριτες ἐν ἐμοὶ παντοῖαι γίνοιντο, μόνον ἀληθῆ τὰ λεγόμενα εἴη. καὶ ὁ ἑκατοντάρχης,"},{"number":230,"text":"ὅσπερ τῇ φυλακῇ ἐφειστήκει τοῦ Ἀγρίππου, θεώμενος τήν τε σπουδὴν μεθʼ οἵας ὁ Μαρσύας ἀφίκετο καὶ τὸ ἐκ τῶν λόγων χάρμα τῷ Ἀγρίππᾳ συνελθόν, ὑποτοπήσας καίνωσίν τινα γεγονέναι τῶν λόγων ἤρετό σφας περὶ τοῦ λόγου τοῦ ἐφεστηκότος."},{"number":231,"text":"οἱ δὲ τέως μὲν παρέτρεπον, ἐγκειμένῳ δὲ ἀποσημαίνει ὁ Ἀγρίππας, ἤδη γὰρ φίλος ἦν, μηδὲν ἐνδοιάσας. ὁ δὲ ἐκοινοῦτό τε τὴν ἡδονὴν τοῦ λόγου διὰ τὸ εἰς ἀγαθὰ τῷ Ἀγρίππᾳ φέρειν προυτίθει τε αὐτῷ δεῖπνον. εὐωχουμένων δʼ αὐτῶν καὶ τοῦ πότου προϊόντος παρῆν τις λέγων ζῆν τε τὸν Τιβέριον καὶ ὀλίγων ἡμερῶν ἐπανήξειν εἰς τὴν πόλιν."},{"number":232,"text":"καὶ ὁ ἑκατοντάρχης δεινῶς θορυβηθεὶς τῷ λόγῳ διὰ τὸ εἰς θάνατον ἀνακείμενα πεπραχέναι δεσμώτῃ τε καὶ ἐπʼ ἀγγελίᾳ θανάτου αὐτοκράτορος συνδιῃτῆσθαι μετὰ χάρματος, ἀπωθεῖταί τε τὸν Ἀγρίππαν τοῦ κλινιδίου καί ἦπου, φησίν, λήσειν με ὑπονοεῖς θάνατον τοῦ αὐτοκράτορος κατεψευσμένος, ἀλλʼ οὐ κεφαλῇ τῇ σῇ τοῦτον ἀναμαξόμενος τὸν λόγον;"},{"number":233,"text":"ταῦτα εἰπὼν κελεύει δῆσαι τὸν Ἀγρίππαν λελυκὼς πρότερον αὐτὸν φυλακήν τε ἀκριβεστέραν αὐτοῦ ἢ πρότερον καθίσταται. καὶ νύκτα μὲν ἐκείνην ὁ Ἀγρίππας ἐν τοιούτοις ἦν τοῖς κακοῖς."},{"number":234,"text":"τῇ δὲ ὑστεραίᾳ λόγος τε πλείων ἦν κατὰ τὴν πόλιν ἰσχυριζόμενος ἐπὶ τῇ τελευτῇ τοῦ Τιβερίου, ἐθάρρουν τε οἱ ἄνθρωποι φανερῶς ἤδη θροεῖν καί τινες καὶ θυσίας ἐπετέλουν, ἐπιστολαί τε ἀφίκοντο παρὰ τοῦ Γαΐου, ἡ μὲν πρὸς τὴν σύγκλητον τοῦ Τιβερίου διασαφοῦσα τὴν τελευτὴν καὶ τὴν αὐτοῦ παράληψιν τῆς ἡγεμονίας γενομένην,"},{"number":235,"text":"ἡ δὲ πρὸς Πείσωνα τὸν φύλακα τῆς πόλεως τοῦτό τε ἀγορεύουσα, καὶ τὸν Ἀγρίππαν ἐκέλευεν ἐκ τοῦ στρατοπέδου μεταστῆσαι εἰς τὴν οἰκίαν, ἐν ᾗ πρότερον ἢ δεθῆναι δίαιταν εἶχεν. τότε ἐν θάρσει λοιπὸν ἦγεν τὰ περὶ αὐτῆς· φυλακὴ μὲν γὰρ καὶ τήρησις ἦν, μετὰ μέντοι ἀνέσεως τῆς εἰς τὴν δίαιταν."},{"number":236,"text":"Γάιος δὲ ὡς ἐπὶ Ῥώμης παρῆν ἄγων τοῦ Τιβερίου τὸ σῶμα, ταφάς τε αὐτοῦ ποιεῖται πολυτελεῖς νόμοις τοῖς πατρίοις, Ἀγρίππαν τε αὐθημερὸν λύειν ὄντα πρόθυμον κώλυμα Ἀντωνία ἦν οὔ τι μίσει τῷ πρὸς τὸν δεδεμένον προμηθείᾳ δὲ τοῦ Γαΐου εὐπρεποῦς, μὴ δόξαν ἀπάγοιτο ἡδονῇ δεχομένου τὴν Τιβερίου τελευτὴν ἄνδρα ὑπʼ ἐκείνου δεδεμένον λύων ἐκ τοῦ ὀξέος."},{"number":237,"text":"διελθουσῶν μέντοι οὐ πολλῶν ἡμερῶν μεταπεμψάμενος αὐτὸν εἰς τὸν οἶκον ἀποκείρει τε αὐτὸν καὶ μεταμφιέννυσιν, εἶτα δὲ τὸ διάδημα περιτίθησιν τῇ κεφαλῇ καὶ βασιλέα καθίστησιν αὐτὸν τῆς Φιλίππου τετραρχίας δωρησάμενος αὐτῷ καὶ τὴν Λυσανίου τετραρχίαν, ἀλλάττει τε σιδηρᾷ ἁλύσει χρυσῆν ἰσόσταθμον. ἱππάρχην δὲ ἐπὶ τῆς Ἰουδαίας ἐκπέμπει Μάρυλλον."},{"number":238,"text":"Δευτέρῳ δὲ ἔτει τῆς Γαΐου Καίσαρος ἡγεμονίας Ἀγρίππας ἠξίου συγχώρησιν αὐτῷ γενέσθαι πλεύσαντι τήν τε ἀρχὴν καταστήσασθαι καὶ τὰ ἄλλα εἰς δέον οἰκονομησαμένῳ ἐπανιέναι."},{"number":239,"text":"καὶ συγχωροῦντος τοῦ αὐτοκράτορος παρῆν παρʼ ἐλπίδας τε ὤφθη πᾶσι βασιλεὺς πολλήν τε τῆς τύχης ἐπεδείκνυεν ἐπὶ τοῖς ἀνθρώποις τὴν ἐξουσίαν τοῖς θεωροῦσιν ἐκ λογισμῶν ἀπορίας τε τῆς πρότερον καὶ τοῦ ἐν τῷ παρόντι εὐδαίμονος. καὶ οἱ μὲν ἐμακάριζον τοῦ μὴ διαμαρτίᾳ χρησαμένου τῶν ἐλπίδων, οἱ δʼ ἐν ἀπιστίᾳ περὶ τῶν γεγονότων ἦσαν."}],"7":[{"number":240,"text":"Ἡρωδιὰς δὲ ἡ ἀδελφὴ τοῦ Ἀγρίππου συνοικοῦσα Ἡρώδῃ, τετράρχης δὲ οὗτος ἦν Γαλιλαίας καὶ Περαίας, φθόνῳ τἀδελφοῦ τὴν ἐξουσίαν ἐδέχετο ὁρῶσα ἐν πολὺ μείζονι ἀξιώματι γεγενημένον ἀνδρὸς τοῦ αὐτῆς, διὰ τὸ φυγῇ μὲν ποιήσασθαι τὴν ἔξοδον διαλῦσαι τὰ χρέα μὴ δυνάμενον, κάθοδον δὲ μετʼ ἀξιώματος καὶ οὕτως πολλοῦ τοῦ εὐδαίμονος."},{"number":241,"text":"ἐλυπεῖτο οὖν καὶ βαρέως ἔφερεν τῇ ἐπὶ τοσοῦτον αὐτοῦ μεταβολῇ, καὶ μάλιστα ὁπότε θεάσαιτο μετὰ τῶν εἰωθότων παρασήμων τῆς βασιλείας ἐπιφοιτῶντά τε τοῖς πλήθεσιν, ἐπικρύπτεσθαι οὐκ ἠνείχετο τὴν δυστυχίαν τοῦ φθόνου, ἀλλὰ τὸν ἄνδρα ἐξῆρεν κελεύουσα ἐπὶ τῆς Ῥώμης πλεῖν ἐπὶ μνηστείᾳ τῶν ἴσων·"},{"number":242,"text":"οὐδὲ γὰρ ἀνεκτὸν εἶναι σφίσι τὸ ζῆν, εἰ Ἀγρίππας Ἀριστοβούλου μὲν υἱὸς ὢν θανεῖν ὑπὸ τοῦ πατρὸς κατεγνωσμένου, πενίᾳ δὲ ἀπόρῳ συνιών, ὡς τελέως αὐτῷ ἐπικουφίζεσθαι τἀναγκαῖα τοῦ ἐφʼ ἡμέρας, φυγῇ δὲ τῶν δεδανεικότων τὸν πλοῦν πεποιημένος ἐπανεληλύθοι βασιλεύς, αὐτὸς δέ γε ὢν παῖς βασιλέως καὶ τοῦ συγγενοῦς τῆς ἀρχῆς καλοῦντος αὐτὸν ἐπὶ μεταποιήσει τῶν ἴσων καθέζοιτο ἀγαπῶν ἐν ἰδιωτείᾳ διαβιοῦν."},{"number":243,"text":"ἀλλʼ εἰ καὶ πρότερόν γε, Ἡρώδη, μηδὲν ἐλύπει σε τὸ ἐν ἐλάσσονι τιμῇ πατρὸς οὗ γέγονας εἶναι, νῦν γοῦν ὀρέχθητι συγγενοῦς ἀξιώματος μηδὲ ὑπόμενε ἡσσᾶσθαι προύχοντι τιμῆς ἀνδρὶ πλοῦτον τεθεραπευκότι τὸν σόν, μηδὲ πενίαν ἀποφήνῃς τὴν ἐκείνου τῆς ἡμετέρας εὐπορίας ἀρετῇ μᾶλλον χρῆσθαι δυναμένην, μηδὲ δευτερεύειν ἀνεπαίσχυντον ἡγοῦ τῶν χθές τε καὶ πρῴην ἐλέῳ τῷ σῷ διαβεβιωκότων."},{"number":244,"text":"ἀλλʼ ἐπὶ τῆς Ῥώμης ἴωμεν, καὶ μήτε πόνου φειδώ τις ἔστω μήτε ἀργυρίου δαπάνης καὶ χρυσίου, διὰ τὸ μὴ ἐπʼ οὐδαμινοῖς ἐν βελτίοσιν γενέσθαι τὴν τήρησιν αὐτῶν ἀναλώσεως τῆς ἐπὶ κτήσει βασιλείας ἐσομένης."},{"number":245,"text":"Ὁ δὲ τέως μὲν ἀπεμάχετο ἀγαπῶν τὴν ἡσυχίαν καὶ τῆς Ῥώμης τὸν ὄχλον διʼ ὑποψίας λαμβάνων ἀναδιδάσκειν τε αὐτὴν ἐπειρᾶτο, ἡ δʼ ἐφʼ ὅσον ἐξαναχωροῦντα ἑώρα μειζόνως ἐπέκειτο κελεύουσα μὴ ἀνιέναι πάντα πράσσειν ἐπὶ τῇ βασιλείᾳ."},{"number":246,"text":"καὶ πέρας οὐκ ἀνῆκεν ἕως ἐξενίκησεν αὐτὸν ὁμογνώμονα αὐτῇ ἀκουσίως γενέσθαι διὰ τὸ μὴ εἶναι ἄλλως ἀποφυγεῖν αὐτῆς τὸ ἐπὶ τοιούτοις ψηφισάμενον, παρασκευασάμενός τε ὡς ἐνῆν πολυτελῶς καὶ φειδοῖ μηδενὸς χρώμενος ἀνήγετο ἐπὶ τῆς Ῥώμης ἅμα καὶ τὴν Ἡρωδιάδα ἀγόμενος."},{"number":247,"text":"Ἀγρίππας δὲ τήν τε διάνοιαν αὐτῶν καὶ τὴν παρασκευὴν αἰσθόμενος καὶ αὐτὸς παρεσκευάζετο, ἐπεί τε ἐκπεπλευκότας ἀκούει, πέμπει καὶ αὐτὸς ἐπὶ τῆς Ῥώμης Φορτουνᾶτον αὐτοῦ τῶν ἀπελευθέρων δῶρά τε κομίζοντα τῷ αὐτοκράτορι καὶ ἐπιστολὰς κατὰ τοῦ Ἡρώδου τὰ δὲ καὶ αὐτὸν διδάξοντα ᾗ καιρὸς τὸν Γάιον."},{"number":248,"text":"ὁ δὲ ἐπαναχθεὶς τοῖς ἀμφὶ τὸν Ἡρώδην καὶ δεξιῷ χρησάμενος τῷ πλῷ τοσόνδε ἀπελίπετο τοῦ Ἡρώδου, ὥστε τὸν μὲν ἐντυχεῖν Γαΐῳ, ὁ δὲ ἐπικατάγεται καὶ τὰς ἐπιστολὰς ἀπεδίδου. καὶ προσέπλευσαν ἀμφότεροι Δικαιαρχείᾳ καὶ τὸν Γάιον ἐν Βαΐαις λαμβάνουσιν."},{"number":249,"text":"πολύδριον δʼ ἐστὶ καὶ τοῦτο τῆς Καμπανίας ὅσον ἀπὸ σταδίων πέντε τῆς Δικαιαρχείας κείμενον, βασίλειοί τέ εἰσιν οἰκήσεις αὐτόθι πολυτελέσι κεχρημέναι κατασκευαῖς φιλοτιμηθέντος τῶν αὐτοκρατόρων ἑκάστου τοὺς προγεγονότας ὑπερβάλλεσθαι, λουτρά τε παρέχεται τὸ χωρίον θερμὰ γῆθεν αὐτόματα ἀνιέντα ἀγαθὰ ἐπί τε ἰάσει τοῖς χρωμένοις καὶ ἄλλως τῷ ἀνειμένῳ τῆς διαίτης συμφέροντα."},{"number":250,"text":"Γάιος δὲ ἅμα τε προσαγορεύων τὸν Ἡρώδην, πρῶτον δὲ αὐτῷ ἐνετύγχανεν, ἅμα τε τοῦ Ἀγρίππου τὰς ἐπιστολὰς ἐπιὼν ἐπὶ κατηγορίᾳ τῇ ἐκείνου συγκειμένας, κατηγόρει δὲ αὐτοῦ ὁμολογίαν πρὸς Σηιανὸν κατὰ τῆς Τιβερίου ἀρχῆς καὶ πρὸς Ἀρτάβανον τὸν Πάρθον ἐπὶ τοῦ παρόντος κατὰ τῆς Γαΐου ἀρχῆς,"},{"number":251,"text":"παράδειγμά τε ἦν αὐτῷ τοῦ λόγου μυριάσιν ἑπτὰ ὁπλιτῶν ἀρκέσουσα κατασκευὴ ἐν ταῖς Ἡρώδου ὁπλοθήκαις ἀποκειμένη, ἐκινεῖτό τε ὑπὸ τῶν εἰρημένων καὶ ἤρετο τὸν Ἡρώδην, εἰ ἀληθὴς ὁ περὶ τῶν ὅπλων λόγος."},{"number":252,"text":"τοῦ δέ, οὐ γὰρ ἦν ἕτερα εἰπεῖν διὰ τὸ ἀντιφθέγξασθαι τὴν ἀλήθειαν, εἰπόντος εἶναι τὰ ὅπλα, πιστὰ ἡγούμενος εἶναι τὰ ἐπὶ τῇ ἀποστάσει κατηγορούμενα, τὴν τετραρχίαν ἀφελόμενος αὐτὸν προσθήκην τῇ Ἀγρίππου βασιλείᾳ ποιεῖται καὶ τὰ χρήματα ὁμοίως τῷ Ἀγρίππᾳ δίδωσιν, αὐτὸν δὲ φυγῇ ἀιδίῳ ἐζημίωσεν ἀποδείξας οἰκητήριον αὐτοῦ Λούγδουνον πόλιν τῆς Γαλλίας."},{"number":253,"text":"Ἡρωδιάδα δὲ μαθὼν Ἀγρίππου ἀδελφὴν οὖσαν τά τε χρήματα ἐδίδου ὁπόσα ἐκείνῃ ἰδίᾳ ἦν καὶ τοῦ μὴ κοινωνεῖν νομίσας τῷ ἀνδρὶ τῆς συμφορᾶς τεῖχος αὐτῇ τὸν ἀδελφὸν ἔλεγεν."},{"number":254,"text":"ἡ δέ ἀλλὰ σὺ μέν, αὐτόκρατορ, εἶπεν, μεγαλοφρόνως τε καὶ ἀξιώματι τῷ σαυτοῦ πρεπόντως τάδε λέγεις, κώλυμα δέ μοί ἐστιν χρῆσθαί σου τῇ χάριτι τῆς δωρεᾶς εὔνοια ἡ πρὸς τὸν γεγαμηκότα, οὗ κοινωνόν με τῆς εὐδαιμονίας γενομένην οὐ δίκαιον ἐγκαταλιπεῖν τὸ ἐπὶ ταῖς τύχαις καθεσταμένον."},{"number":255,"text":"ὁ δὲ ὀργῇ τοῦ μεγαλόφρονος αὐτὴν ποιησάμενος συνήλαυνεν καὶ αὐτὴν τῷ Ἡρώδῃ καὶ τὴν οὐσίαν αὐτῆς τῷ Ἀγρίππᾳ δίδωσιν. Ἡρωδιάδι μὲν δὴ φθόνου τοῦ πρὸς τὸν ἀδελφὸν καὶ Ἡρώδῃ γυναικείων ἀκροασαμένῳ κουφολογιῶν δίκην ταύτην ἐπετίμησεν ὁ θεός."},{"number":256,"text":"Γάιος δὲ τὸν μὲν πρῶτον ἐνιαυτὸν καὶ τὸν ἑξῆς πάνυ μεγαλοφρόνως ἐχρῆτο τοῖς πράγμασιν καὶ μέτριον παρέχων αὑτὸν εἰς εὔνοιαν πολλὴν προυχώρει παρά τε Ῥωμαίοις αὐτοῖς καὶ τοῖς ὑπηκόοις. προϊὼν δʼ ἐξίστατο τοῦ ἀνθρωπίνως φρονεῖν ὑπὸ μεγέθους τῆς ἀρχῆς ἐκθειάζων ἑαυτὸν καὶ τὰ πάντα ἐπʼ ἀτιμίᾳ τοῦ θείου πολιτεύειν ἦρτο."}],"8":[{"number":257,"text":"Καὶ δὴ στάσεως ἐν Ἀλεξανδρείᾳ γενομένης Ἰουδαίων τε οἳ ἐνοικοῦσι καὶ Ἑλλήνων τρεῖς ἀφʼ ἑκατέρας τῆς στάσεως πρεσβευταὶ αἱρεθέντες παρῆσαν ὡς τὸν Γάιον. καὶ ἦν γὰρ τῶν Ἀλεξανδρέων πρέσβεων εἷς Ἀπίων, ὃς πολλὰ εἰς τοὺς Ἰουδαίους ἐβλασφήμησεν ἄλλα τε λέγων καὶ ὡς τῶν Καίσαρος τιμῶν περιορῷεν·"},{"number":258,"text":"πάντων γοῦν ὁπόσοι τῇ Ῥωμαίων ἀρχῇ ὑποτελεῖς εἶεν βωμοὺς τῷ Γαΐῳ καὶ νεὼς ἱδρυμένων τά τε ἄλλα πᾶσιν αὐτὸν ὥσπερ τοὺς θεοὺς δεχομένων, μόνους τούσδε ἄδοξον ἡγεῖσθαι ἀνδριᾶσι τιμᾶν καὶ ὅρκιον αὐτοῦ τὸ ὄνομα ποιεῖσθαι."},{"number":259,"text":"πολλὰ δὲ καὶ χαλεπὰ Ἀπίωνος εἰρηκότος, ὑφʼ ὧν ἀρθῆναι ἤλπιζεν τὸν Γάιον καὶ εἰκὸς ἦν, Φίλων ὁ προεστὼς τῶν Ἰουδαίων τῆς πρεσβείας, ἀνὴρ τὰ πάντα ἔνδοξος Ἀλεξάνδρου τε τοῦ ἀλαβάρχου ἀδελφὸς ὢν καὶ φιλοσοφίας οὐκ ἄπειρος, οἷός τε ἦν ἐπʼ ἀπολογίᾳ χωρεῖν τῶν κατηγορημένων. διακλείει δʼ αὐτὸν Γάιος κελεύσας ἐκποδὼν ἀπελθεῖν,"},{"number":260,"text":"περιοργής τε ὢν φανερὸς ἦν ἐργασόμενός τι δεινὸν αὐτούς. ὁ δὲ Φίλων ἔξεισι περιυβρισμένος καί φησι πρὸς τοὺς Ἰουδαίους, οἳ περὶ αὐτὸν ἦσαν, ὡς χρὴ θαρρεῖν, Γαΐου λόγῳ μὲν αὐτοῖς ὠργισμένου, ἔργῳ δὲ ἤδη τὸν θεὸν ἀντιπαρεξάγοντος."},{"number":261,"text":"Γάιος δὲ ἐν δεινῷ φέρων εἰς τοσόνδε ὑπὸ Ἰουδαίων περιῶφθαι μόνων πρεσβευτὴν ἐπὶ Συρίας ἐκπέμπει Πετρώνιον διάδοχον Οὐιτελλίῳ τῆς ἀρχῆς, κελεύων χειρὶ πολλῇ εἰσβαλόντι εἰς τὴν Ἰουδαίαν, εἰ μὲν ἑκόντες δέχοιντο, ἱστᾶν αὐτοῦ ἀνδριάντα ἐν τῷ ναῷ τοῦ θεοῦ, εἰ δʼ ἀγνωμοσύνῃ χρῷντο, πολέμῳ κρατήσαντα τοῦτο ποιεῖν."},{"number":262,"text":"καὶ Πετρώνιος Συρίαν παραλαβὼν ἠπείγετο διακονεῖσθαι ταῖς ἐπιστολαῖς τοῦ Καίσαρος, συμμαχίαν τε πλείστην ὅσην ἠδύνατο ἀθροίσας καὶ τάγματα δύο τῆς Ῥωμαίων δυνάμεως ἄγων ἐπὶ Πτολεμαΐδος παρῆν αὐτόθι χειμάσων ὡς πρὸς ἔαρ τοῦ πολεμεῖν οὐκ ἀφεξόμενος, καὶ πρὸς τὸν Γάιον ἔγραφεν περὶ τῶν ἐπεγνωσμένων. ὁ δὲ ἐπῄνει τῆς προθυμίας αὐτὸν καὶ ἐκέλευεν μὴ ἀνιέναι πολεμεῖν δὲ μὴ πειθομένοις ἐντεταμένως."},{"number":263,"text":"Ἰουδαίων δὲ πολλαὶ μυριάδες παρῆσαν ὡς τὸν Πετρώνιον εἰς Πτολεμαΐδα κατὰ δεήσεις μηδὲν ἐπὶ παρανομίᾳ σφᾶς ἐπαναγκάζειν καὶ παραβάσει τοῦ πατρίου νόμου."},{"number":264,"text":"εἰ δέ σοι πάντως πρόκειται τὸν ἀνδριάντα φέρειν καὶ ἱστᾶν, ἡμᾶς αὐτοὺς πρότερον μεταχειρισάμενος πρᾶσσε τὰ δεδογμένα· οὐδὲ γὰρ δυνάμεθα περιόντες θεωρεῖν πράγματα ἡμῖν ἀπηγορευμένα ἀξιώματί τε τοῦ νομοθέτου καὶ προπατόρων τῶν ἡμετέρων τῶν εἰς ἀρετὴν ἀνήκειν αὐτὰ κεχειροτονηκότων. Πετρώνιος δὲ ὀργὴν λαβὼν εἶπεν·"},{"number":265,"text":"ἀλλʼ εἰ μὲν αὐτοκράτωρ ὢν βουλεύμασι χρῆσθαι τοῖς ἐμαυτοῦ τάδε πράσσειν ἐπενόουν, κἂν δίκαιος ἦν ὑμῖν πρός με οὗτος ὁ λόγος. νυνὶ δέ μοι Καίσαρος ἐπεσταλκότος πᾶσα ἀνάγκη διακονεῖσθαι τοῖς ἐκείνῳ προανεψηφισμένοις διὰ τὸ εἰς ἀνηκεστοτέραν φέρειν ζημίαν τὴν παρακρόασιν αὐτῶν. ἐπεὶ τοίνυν οὕτως φρονεῖς,"},{"number":266,"text":"ὦ Πετρώνιε, φασὶν οἱ Ἰουδαῖοι, ὡς μὴ ἂν ἐπιστολὰς τὰς Γαΐου παρελθεῖν, οὐδʼ ἂν αὐτοὶ παραβαίημεν τοῦ νόμου τὴν προαγόρευσιν θεοῦ πεισθέντες ἀρετῇ καὶ προγόνων πόνοις τῶν ἡμετέρων εἰς νῦν ἀπαράβατοι μεμενηκότες, οὐδʼ ἂν τολμήσαιμεν ἐπὶ τοσοῦτον κακοὶ γενέσθαι, ὥστε ὁπόσα ἐκείνῳ δόξειεν μὴ πρασσόμενα ἀγαθοῦ ῥοπὴν ἡμῖν φέρειν αὐτοὶ παραβαίνειν ποτʼ ἂν θάνατον φοβηθέντες."},{"number":267,"text":"ὑπομενοῦμεν δὲ εἰς τύχας ἰόντες ἐπὶ φυλακῇ τε πατρίων καὶ κινδυνεύειν προθεμένοις ἐλπίδα οὖσαν ἐξεπιστάμενοι κἂν περιγενέσθαι διά τε τοῦ θεοῦ τὸ στησόμενον μεθʼ ἡμῶν ἐπὶ τιμῇ τε τῇ ἐκείνου τὰ δεινὰ ὑποδεχομένων καὶ τῆς τύχης τὸ ἐπʼ ἀμφότερα φιλοῦν τοῖς πράγμασι παρατυγχάνειν,"},{"number":268,"text":"ἐκ δὲ τοῦ σοὶ πείθεσθαι πολλὴν μὲν λοιδορίαν τοῦ ἀνάνδρου προσκεισομένην ὡς διʼ αὐτὸ παράβασιν τοῦ νομίμου προσποιουμένοις, καὶ ἅμα πολλὴν ὀργὴν τοῦ θεοῦ, ὃς καὶ παρὰ σοὶ δικαστῇ γένοιτʼ ἂν βελτίων Γαΐου."},{"number":269,"text":"Καὶ ὁ Πετρώνιος ἐκ τῶν λόγων θεασάμενος δυσνίκητον αὐτῶν τὸ φρονοῦν καὶ μὴ ἂν ἀμαχεὶ δύναμιν αὐτῷ γενέσθαι διακονήσασθαι Γαΐῳ τὴν ἀνάθεσιν τοῦ ἀνδριάντος πολὺν δὲ ἔσεσθαι φόνον, τούς τε φίλους ἀναλαβὼν καὶ θεραπείαν, ἣ περὶ αὐτὸν ἦν, ἐπὶ Τιβεριάδος ἠπείγετο χρῄζων κατανοῆσαι τῶν Ἰουδαίων τὰ πράγματα ὡς ἔχοι."},{"number":270,"text":"καὶ Ἰουδαῖοι μέγαν ἡγούμενοι τὸν ἐκ τοῦ πρὸς Ῥωμαίους πολέμου κίνδυνον, πολὺ μείζονα δὲ κρίνοντες τὸν ἐκ τοῦ παρανομεῖν, αὖθις πολλαὶ μυριάδες ὑπηντίαζον Πετρώνιον εἰς τὴν Τιβεριάδα γενόμενον,"},{"number":271,"text":"καὶ ἱκετείᾳ χρώμενοι μηδαμῶς εἰς ἀνάγκας τοιαύτας αὐτοὺς καθιστᾶν μηδὲ μιαίνειν ἀνδριάντος ἀναθέσει τὴν πόλιν, πολεμήσετε ἄρα Καίσαρι, Πετρώνιος ἔφη, μήτε τὴν ἐκείνου παρασκευὴν λογιζόμενοι μήτε τὴν ὑμετέραν ἀσθένειαν; οἱ δʼ οὐδαμῶς πολεμήσαιμεν, ἔφασαν, τεθνηξόμεθα δὲ πρότερον ἢ παραβῆναι τοὺς νόμους. ἐπί τε τὰ πρόσωπα κείμενοι καὶ τὰς σφαγὰς προδεικνύντες ἕτοιμοι κτιννύεσθαι ἔλεγον εἶναι."},{"number":272,"text":"καὶ ταῦτʼ ἐπράσσετο ἐπὶ ἡμέρας τεσσαράκοντα, καὶ τοῦ γεωργεῖν ἀπερίοπτοι τὸ λοιπὸν ἦσαν καὶ ταῦτα τῆς ὥρας οὔσης πρὸς σπόρῳ, πολλή τε ἦν προαίρεσις αὐτοῖς καὶ τοῦ θνήσκειν ἐπιθυμίας πρόθεσις, ἢ τὴν ἀνάθεσιν θεάσασθαι τοῦ ἀνδριάντος."},{"number":273,"text":"Ἐν τούτοις ὄντων τῶν πραγμάτων Ἀριστόβουλος ὁ Ἀγρίππου τοῦ βασιλέως ἀδελφὸς καὶ Ἑλκίας ὁ μέγας ἄλλοι τε οἱ κράτιστοι τῆσδε τῆς οἰκίας καὶ οἱ πρῶτοι σὺν αὐτοῖς εἰσίασιν ὡς τὸν Πετρώνιον παρακαλοῦντες αὐτόν,"},{"number":274,"text":"ἐπειδὴ τὴν προθυμίαν ὁρᾷ τῆς πληθύος, μηδὲν εἰς ἀπόνοιαν αὐτῆς παρακινεῖν, ἀλλὰ γράφειν πρὸς Γάιον τὸ ἀνήκεστον αὐτῶν πρὸς τὴν ἀποδοχὴν τοῦ ἀνδριάντος, πῶς τε ἀποστάντες τοῦ γεωργεῖν ἀντικαθέζονται, πολεμεῖν μὲν οὐ βουλόμενοι διὰ τὸ μηδʼ ἂν δύνασθαι, θανεῖν δʼ ἔχοντες ἡδονὴν πρὶν παραβῆναι τὰ νόμιμα αὐτοῖς, ὥστε ἀσπόρου τῆς γῆς γενομένης λῃστεῖαι ἂν φύοιντο ἀδυναμίᾳ καταβολῆς τῶν φόρων."},{"number":275,"text":"ἴσως γὰρ ἂν ἐπικλασθέντα τὸν Γάιον μηδὲν ὠμὸν διανοηθῆναι μηδὲ ἐπʼ ἀναστάσει φρονῆσαι τοῦ ἔθνους· ἐμμένοντος δὲ τῇ τότε βουλῇ τοῦ πολεμεῖν τότε δὴ καὐτὸν ἅπτεσθαι τοῦ πράγματος."},{"number":276,"text":"καὶ οἱ μὲν ἀμφὶ τὸν Ἀριστόβουλον ἐπὶ τούτοις τὸν Πετρώνιον παρεκάλουν. Πετρώνιος δὲ τοῦτο μὲν τῶν περὶ τὸν Ἀριστόβουλον παντοίως ἐπικειμένων διὰ τὸ ὑπὲρ μεγάλων ποιεῖσθαι τὴν δέησιν καὶ πάσῃ μηχανῇ χρησαμένων εἰς τὰς ἱκετείας,"},{"number":277,"text":"τοῦτο δὲ τῶν Ἰουδαίων θεώμενος τὴν ἀντιπαράταξιν τῆς γνώμης καὶ δεινὸν ἡγούμενος τοσαῖσδε ἀνθρώπων μυριάσιν μανίᾳ τῇ Γαΐου διακονούμενος ἐπαγαγὼν θάνατον ἐν αἰτίᾳ τὸ πρὸς θεὸν σεβάσμιον ἔχειν καὶ μετὰ πονηρᾶς τὸν μετὰ ταῦτα βίον ἐλπίδος διαιτᾶσθαι, πολὺ κρεῖσσον ἡγεῖτο ἐπιστείλας τῷ Γαΐῳ τὸ ἀνήκεστον αὐτῶν ὀργὴν φέροντος μὴ ἐκ τοῦ ὀξέος δεδιακονημένου αὐτοῦ ταῖς ἐπιστολαῖς·"},{"number":278,"text":"τάχα μὲν γὰρ καὶ πείσειν· καὶ τῇ τὸ πρῶτον μανίᾳ τῆς γνώμης ἐπιμένοντος ἅψεσθαι πολέμου τοῦ πρὸς αὐτούς, εἰ δʼ ἄρα τι καὶ κατʼ αὐτοῦ τρέποι τῆς ὀργῆς, καλῶς ἔχειν τοῖς ἀρετῆς μεταποιουμένοις ὑπὲρ τοσῆσδε ἀνθρώπων πληθύος τελευτᾶν, ἔκρινε πιθανὸν ἡγεῖσθαι τῶν δεομένων τὸν λόγον."},{"number":279,"text":"Συγκαλέσας δὲ εἰς τὴν Τιβεριάδα τοὺς Ἰουδαίους, οἱ δὲ ἀφίκοντο πολλαὶ μυριάδες, καταστὰς ἐπʼ αὐτῶν τήν τε ἐν τῷ παρόντι στρατείαν οὐ γνώμης ἀπέφαινε τῆς αὐτοῦ τοῦ δὲ αὐτοκράτορος τῶν προσταγμάτων, τὴν ὀργὴν οὐδὲν εἰς ἀναβολάς, ἀλλʼ ἐκ τοῦ παραχρῆμα ἐπιφέρεσθαι τοῖς πράγμασιν τοῖς παρακροᾶσθαι θάρσος εἰσφερομένοις· ᾧ καλῶς ἔχον ἐστὶν τόν γε τιμῆς τοσαύτης ἐπιτετευχότα συγχωρήσει τῇ ἐκείνου οὐδὲν ἐναντίον πράσσειν·"},{"number":280,"text":"οὐ μὴν δίκαιον ἡγοῦμαι ἀσφάλειάν τε καὶ τιμὴν τὴν ἐμαυτοῦ μὴ οὐχ ὑπὲρ τοῦ ὑμετέρου μὴ ἀπολουμένου τοσούτων ὄντων ἀναλοῦν διακονούμενον τῇ ἀρετῇ τοῦ νόμου, ὃν πάτριον ὄντα περιμάχητον ἡγεῖσθε, καὶ τῇ ἐπὶ πᾶσιν ἀξιώσει καὶ δυνάμει τοῦ θεοῦ, οὗ τὸν ναὸν οὐκ ἂν περιιδεῖν τολμήσαιμι ὕβρει πεσεῖν τῆς τῶν ἡγεμονευόντων ἐξουσίας."},{"number":281,"text":"στέλλω δὲ ὡς Γάιον γνώμας τε τὰς ὑμετέρας διασαφῶν καί πῃ καὶ συνηγορίᾳ χρώμενος ὑπὲρ τοῦ καθʼ ἡμᾶς παρὰ γνώμην πεισομένην οἷς προύθεσθε ἀγαθοῖς. καὶ συμπράσσοι μὲν ὁ θεός, βελτίων γὰρ ἀνθρωπίνης μηχανῆς καὶ δυνάμεως ἡ κατʼ ἐκεῖνον ἐξουσία, πρυτανεύων ὑμῖν τε τὴν τήρησιν τῶν πατρίων καὶ αὐτῷ τὸ μηδὲν ἀνθρωπείαις παρὰ γνώμην βουλεύσεσι τιμῶν τῶν εἰωθυιῶν ἁμαρτεῖν."},{"number":282,"text":"εἰ δʼ ἐκπικρανθεὶς Γάιος εἰς ἐμὲ τρέψει τὸ ἀνήκεστον τῆς ὀργῆς, τλήσομαι πάντα κίνδυνον καὶ πᾶσαν ταλαιπωρίαν συνιοῦσαν τῷ σώματι καὶ τῇ τύχῃ ὑπὲρ τοῦ μὴ ὑμᾶς τοσούσδε ὄντας ἐπὶ οὕτως ἀγαθαῖς ταῖς πράξεσι διολλυμένους θεωρεῖν."},{"number":283,"text":"ἄπιτε οὖν ἐπὶ ἔργα τὰ αὐτῶν ἕκαστοι καὶ τῇ γῇ ἐπιπονεῖτε. πέμψω δʼ αὐτὸς ἐπὶ Ῥώμης καὶ τὰ πάντα ὑπὲρ ὑμῶν διʼ ἐμαυτοῦ καὶ τῶν φίλων οὐκ ἀποτραπήσομαι διακονεῖν."},{"number":284,"text":"Ταῦτα εἰπὼν καὶ διαλύσας τῶν Ἰουδαίων τὸν σύλλογον προμηθεῖσθαι τῶν εἰς τὴν γεωργίαν ἠξίου τοὺς ἐν τέλει καὶ καθομιλεῖν τὸν λαὸν ἐλπίσι χρησταῖς. καὶ ὁ μὲν εὐθυμεῖν τὸ πλῆθος ἔσπευδεν. ὁ θεὸς δὲ παρρησίαν ἐπεδείκνυτο τὴν αὐτοῦ Πετρωνίῳ καὶ τὴν ἐπὶ τοῖς ὅλοις σύλληψιν·"},{"number":285,"text":"ἅμα τε γὰρ ἐπαύετο τοῦ λόγου, ὃν πρὸς τοὺς Ἰουδαίους εἶπεν, καὶ αὐτίκα ὑετὸν ἠφίει μέγαν παρʼ ἐλπίδα τοῖς ἀνθρώποις γενόμενον διὰ τὸ ἐκείνην τὴν ἡμέραν αἴθριον ἕωθεν οὖσαν οὐδὲν ὄμβριον ἀποσημαίνειν ἐκ τῶν περὶ τὸν οὐρανὸν καὶ τὸ πᾶν ἔτος αὐχμῷ μεγάλῳ κατεσχημένον ἐπʼ ἀπογνώσει ποιεῖν τοὺς ἀνθρώπους ὕδατος τοῦ ἄνωθεν, εἰ καὶ σύννεφόν ποτε θεάσαιντο τὸν οὐρανόν."},{"number":286,"text":"ὥστε δὴ τότε πολλοῦ καὶ παρὰ τὸ εἰωθὸς καὶ παρὰ τὸ ἑτέρῳ δόξαν ἀφιγμένου ὕδατος τοῖς τε Ἰουδαίοις ἐλπὶς ἦν ἐπʼ οὐδαμοῖς ἀτυχήσειν Πετρώνιον ὑπὲρ αὐτῶν δεόμενον, ὅ τε Πετρώνιος κατεπέπληκτο μειζόνως ὁρῶν ἐναργῶς τὸν θεὸν τῶν Ἰουδαίων προμηθούμενον καὶ πολλὴν ἀποσημήναντα τὴν ἐπιφάνειαν, ὡς μηδʼ ἂν τοῖς ἔργῳ προθεμένοις τἀναντία φρονεῖν ἰσχὺν ἀντιλέξεως καταλελεῖφθαι."},{"number":287,"text":"ὡς δὲ καὶ πρὸς τὸν Γάιον σὺν τοῖς λοιποῖς ὁπόσα ἔγραφεν, ἐπαγωγὰ δὲ ἦν τὰ πάντα καὶ παντοίως παρακαλοῦντα μὴ τοσαύτας μυριάδας ἀνθρώπων ἀπονοεῖν, ἃς εἰ κτείνοι, οὐ γὰρ δίχα γε πολέμου παραχωρήσειν τοῦ νομίμου τῆς θρησκείας, προσόδου τε τῆς ἀπʼ αὐτῶν ἀποστερεῖσθαι καὶ τῷ τροπαίῳ τῆς ἀρᾶς ὑποτίθεσθαι τὸν μέλλοντα αἰῶνα."},{"number":288,"text":"κἄλλως θείου τοῦ προεστηκότος αὐτῶν τὴν δύναμιν ὡς ἀκραιφνῆ ἀπέφαινεν καὶ μηδὲν ἐνδοίαστον ἐπὶ δυνάμει τῇ αὐτῆς ἐπιδείκνυσθαι καταλείπουσαν. καὶ Πετρώνιος μὲν ἐν τούτοις ἦν."},{"number":289,"text":"Ἀγρίππας δὲ ὁ βασιλεύς, ἐτύγχανεν γὰρ ἐπὶ Ῥώμης διαιτώμενος, προύκοπτε φιλίᾳ τῇ πρὸς τὸν Γάιον μειζόνως. καί ποτε προθεὶς δεῖπνον αὐτῷ καὶ πρόνοιαν ἔχων πάντας ὑπερβαλέσθαι τέλεσί τε τοῖς εἰς τὸ δεῖπνον καὶ παρασκευῇ τοῦ εἰς ἡδονὴν φέροντος,"},{"number":290,"text":"ὡς μὴ ὅπως ἄν τινα τῶν λοιπῶν, ἀλλὰ μηδʼ αὐτὸν Γάιον πιστεύειν ποτε ἰσωθῆναι θελήσοντα οὐχ ὅπως ὑπερβαλέσθαι· τοσοῦτον ὁ ἀνὴρ τῇ παρασκευῇ πάντας ὑπερῆρεν καὶ τῷ τὰ πάντα ἢ Καίσαρος ἐκφροντίσας παρασχεῖν."},{"number":291,"text":"καὶ ὁ Γάιος ἐκθαυμάσας τήν τε διάνοιαν αὐτοῦ καὶ τὴν μεγαλοπρέπειαν, ὡς ἐπʼ ἀρεσκείᾳ τῇ αὐτοῦ βιάζοιτο καὶ ὑπὲρ δύναμιν τῶν χρημάτων εὐπορίᾳ χρήσασθαι, βουλόμενός τε μιμήσασθαι τὴν Ἀγρίππου φιλοτιμίαν ἐφʼ ἡδονῇ τῇ αὐτοῦ πρασσομένην, ἀνειμένος ὑπὸ οἴνου καὶ τὴν διάνοιαν εἰς τὸ ἱλαρώτερον ἐκτετραμμένος, φησὶν ἐν συμποσίῳ παρακαλοῦντος εἰς πότον·"},{"number":292,"text":"Ἀγρίππα, καὶ πρότερον μέν σοι τιμὴν συνῄδειν ᾗ ἐχρῶ τὰ πρὸς ἐμὲ καὶ πολλὴν εὔνοιαν μετὰ κινδύνων ἀποδειχθεῖσαν, οἷς ὑπὸ Τιβερίου περιέστης διʼ αὐτήν, ἐπιλείπεις τε οὐδὲν καὶ ὑπὲρ δύναμιν ἀρετῇ χρῆσθαι τῇ πρὸς ἡμᾶς. ὅθεν, αἰσχρὸν γὰρ ἡσσᾶσθαί με ὑπὸ τῆς σῆς σπουδῆς, ἀναλαβεῖν βούλομαι τὰ ἐλλελειμμένα πρότερον·"},{"number":293,"text":"ὀλίγον γὰρ πᾶν ὁπόσον σοι δωρεῶν ἐχόμενον ἀπεμοιρασάμην. τὸ πᾶν, ὅπερ σοι ῥοπὴν ἂν προσθείη τοῦ εὐδαίμονος, δεδιακονήσεται γάρ σοι προθυμίᾳ τε καὶ ἰσχύι τῇ ἐμῇ. καὶ ὁ μὲν ταῦτα ἔλεγεν οἰόμενος γῆν τε πολλὴν τῆς προσόδου αἰτήσεσθαι ἢ καί τινων προσόδους πόλεων,"},{"number":294,"text":"ὁ δὲ καίπερ τὰ πάντα ἐφʼ οἷς αἰτήσαι παρασκευασάμενος οὐκ ἐφανέρου τὴν διάνοιαν, ἀλλʼ ἐκ τοῦ ὀξέος ἀμείβεται τὸν Γάιον, ὅτι μήτε πρότερον κέρδος τὸ ἀπʼ αὐτοῦ καραδοκῶν παρὰ τὰς Τιβερίου ἐπιστολὰς θεραπεύσειεν αὐτὸν οὔτε νῦν πράσσειν τι τῶν εἰς χάριν τὴν ἐκείνου κερδῶν οἰκείων ἔν τισι λήψεσι."},{"number":295,"text":"μεγάλα δὲ εἶναι τὰ προδεδωρημένα καὶ περαιτέρω τοῦ θράσει χρωμένου τῶν ἐλπίδων· καὶ γὰρ εἰ τῆς σῆς ἐλάττονα γέγονεν δυνάμεως,"},{"number":296,"text":"τῆς γʼ ἐμοῦ τοῦ εἰληφότος διανοίας τε καὶ ἀξιώσεως μείζονα. καὶ ὁ Γάιος ἐκπλαγεὶς τὴν ἀρετὴν αὐτοῦ πλειόνως ἐνέκειτο εἰπεῖν, ὅ τι χαρίζοιτʼ ἂν αὐτῷ παρασχόμενος. ὁ δέ, ἐπεί περ, ὦ δέσποτα, προθυμίᾳ τῇ σῇ δωρεῶν ἄξιον ἀποφαίνεις, αἰτήσομαι τῶν μὲν εἰς ὄλβον φερόντων οὐδὲν διὰ τὸ μεγάλως με ἐνδιαπρέπειν οἷς ἤδη παρέσχες·"},{"number":297,"text":"ὅ τι δʼ ἂν σοὶ δόξαν προσποιοῖ τοῦ εὐσεβοῦς καὶ τὸ θεῖον σύμμαχον ἐφʼ οἷς θελήσειας παρακαλοῖ κἀμοὶ πρὸς εὐκλείας γένοιτο παρὰ τοῖς πυνθανομένοις, ὡς μηθενὸς ὧν χρησαίμην ὑπὸ τῆς σῆς ἐξουσίας ἀτυχεῖν πώποτε γνόντι· ἀξιῶ γάρ σοι τοῦ ἀνδριάντος τὴν ἀνάθεσιν, ἣν ποιήσασθαι κελεύεις Πετρώνιον εἰς τὸ Ἰουδαίων ἱερόν, μηκέτι πράσσειν διανοεῖσθαι."},{"number":298,"text":"Καὶ ὁ μὲν καίπερ ἐπικίνδυνον τοῦτο ἡγούμενος, εἰ γὰρ μὴ πιθανὰ ἔκρινε Γάιος, οὐδὲν ἄλλο ἢ ἐς θάνατον ἔφερεν, διὰ τὸ μεγάλα νομίζειν τε καὶ εἶναι κύβον ἀναρριπτεῖν τὸν ἐπʼ αὐτοῖς ἡγεῖτο."},{"number":299,"text":"Γάιος δὲ καὶ ἅμα τε τῇ θεραπείᾳ τοῦ Ἀγρίππου ἀνειλημμένος καὶ ἄλλως ἀπρεπὲς ὑπολαμβάνων ἐπὶ τοσῶνδε μαρτύρων ψευδὴς γενέσθαι περὶ ὧν προθύμως ἐβιάζετο αἰτεῖσθαι τὸν Ἀγρίππαν μετὰ τοῦ ὀξέος μεταμέλῳ χρώμενος,"},{"number":300,"text":"ἅμα δὲ καὶ τοῦ Ἀγρίππου τὴν ἀρετὴν θαυμάσας, ἐν ὀλίγῳ αὔξειν τὴν οἰκείαν ἀρχὴν ἤτοι προσόδοις χρημάτων ἢ ἄλλῃ δυνάμει τοῦ κοινοῦ δὲ τῆς εὐθυμίας ἐπιμελοῖτο πρεσβεύων τοὺς νόμους καὶ τὸ θεῖον, συνεχώρει καὶ γράφει πρὸς τὸν Πετρώνιον, ἐκεῖνον τῆς τε ἀθροίσεως τοῦ στρατεύματος ἐπαινῶν καὶ τοῦ πρὸς αὐτὸν περὶ αὐτῶν ἐπεσταλκότος·"},{"number":301,"text":"νῦν οὖν εἰ μὲν φθάνεις τὸν ἀνδριάντα ἑστακώς, ἑστάτω· εἰ δὲ μήπω πεποίησαι τὴν ἀνάθεσιν, μηδὲν περαιτέρω κακοπαθεῖν, ἀλλὰ τόν τε στρατὸν διάλυε καὶ αὐτὸς ἐφʼ ἃ τὸ πρῶτόν σε ἔστειλα ἄπιθι· οὐδὲν γὰρ ἔτι δέομαι τῆς ἀναστάσεως τοῦ ἀνδριάντος Ἀγρίππᾳ χαριζόμενος ἀνδρὶ παρʼ ἐμοὶ τιμωμένῳ μειζόνως ἢ ὥστε με χρείᾳ τῇ ἐκείνου καὶ οἷς κελεύσειεν ἀντειπεῖν."},{"number":302,"text":"Γάιος μὲν δὴ ταῦτα γράφει πρὸς τὸν Πετρώνιον πρότερον ἢ ἐντυχεῖν ἐπὶ ἀποστάσει καταδόξας αὐτοὺς ἐπείγεσθαι, μηδὲν γὰρ ἕτερον ἀποσημαίνειν τὴν διάνοιαν αὐτῶν, ἀλλὰ πόλεμον ἄντικρυς Ῥωμαίοις ἀπειλεῖν."},{"number":303,"text":"καὶ περιαλγήσας ὡς ἐπὶ πείρᾳ τῆς ἡγεμονίας αὐτοῦ τετολμηκότων, ἀνὴρ ἐπὶ πᾶσιν ἥσσων μὲν τοῦ αἰσχροῦ, κρείσσων δὲ τοῦ βελτίστου καὶ ἐφʼ οἷστισι κρίνειεν ὀργῇ χρῆσθαι παρʼ ὁντινοῦν ἐπειγόμενος παίδευσιν αὐτῆς οὐδʼ ἡντινοῦν προστιθείς, ἀλλʼ ἐφʼ ἡδονῇ τιθεὶς τῇ ἐκείνης τὴν κρίσιν τοῦ εὐδαίμονος, γράφει πρὸς τὸν Πετρώνιον·"},{"number":304,"text":"ἐπειδὴ δῶρα ὁπόσα σοι οἱ Ἰουδαῖοι παρέσχον ἐν μείζονι λόγῳ τῶν ἐμῶν πεποίησαι ἐντολῶν διακονεῖσθαι τὰ πάντα ἡδονῇ τῇ ἐκείνων ἀρθεὶς ἐπὶ παραβάσει τῶν ἐμῶν ἐντολῶν, κελεύω σε σαυτῷ. κριτὴν γενόμενον λογίσασθαι περὶ τοῦ ποιητέου σοι ὑποστάντα ὀργῇ τῇ ἐμῇ, ἐπεί τοι παράδειγμα ποιοῖντό σε οἵ τε νῦν πάντες καὶ ὁπόσοι ὕστεροι γένοιντʼ ἄν, μηδαμῶς ἀκυροῦν αὐτοκράτορος ἀνδρὸς ἐντολάς."},{"number":305,"text":"Ταύτην μὲν γράφει Πετρωνίῳ τὴν ἐπιστολήν, οὐ μὴν φθάνει γε ζῶντος Πετρώνιος δεξάμενος αὐτὴν βραδυνθέντος τοῦ πλοῦ τοῖς φέρουσιν εἰς τοσόνδε, ὥστε Πετρωνίῳ γράμματα πρὸ αὐτῆς ἀφικέσθαι, διʼ ὧν μανθάνει τὴν Γαΐου τελευτήν."},{"number":306,"text":"θεὸς γὰρ οὐκ ἄρʼ ἀμνημονήσειν ἔμελλε Πετρωνίῳ κινδύνων, οὓς ἀνειλήφει ἐπὶ τῇ τῶν Ἰουδαίων χάριτι καὶ τιμῇ τῇ αὐτοῦ, ἀλλὰ τὸν Γάιον ἀποσκευασάμενος ὀργῆς ὧν ἐπὶ σεβασμῷ τῷ αὐτοῦ πράσσειν ἐτόλμησε, τὸν μισθὸν χρεολυτεῖν συνευεργετεῖν τῷ Πετρωνίῳ ἥ τε Ῥώμη καὶ πᾶσα ἡ ἀρχή, μάλιστα δʼ ὁπόσοι τῆς βουλῆς προύχοιεν ἀξιώματι, διὰ τὸ εἰς ἐκείνους ἀκράτῳ τῇ ὀργῇ χρῆσθαι τὸν Γάιον."},{"number":307,"text":"καὶ τελευτᾷ μὲν οὐ μετὰ πολὺν χρόνον ἢ γράψαι τῷ Πετρωνίῳ τὴν ἐπὶ τῷ θανεῖν ἀνακειμένην ἐπιστολήν, τὴν δʼ αἰτίαν, ἐξ ἧς τελευτᾷ, καὶ τῆς ἐπιβουλῆς τὸν τρόπον ἀφηγήσομαι προϊόντος τοῦ λόγου."},{"number":308,"text":"Πετρωνίῳ δὲ προτέρα μὲν παρῆν ἡ διασαφοῦσα τοῦ Γαΐου τὴν τελευτὴν ἐπιστολή, μετʼ οὐ πολὺ δὲ ἡ κελεύουσα αὐτὸν τελευτᾶν αὐτόχειρα, καὶ ἥσθη τε τῇ συντυχίᾳ τοῦ ὀλέθρου, ὃς τὸν Γάιον κατέλαβεν,"},{"number":309,"text":"καὶ τοῦ θεοῦ τὴν πρόνοιαν ἐξεθαύμασεν οὐδὲν εἰς ἀναβολὰς ἀλλʼ ἐκ τοῦ ὀξέος μισθὸν αὐτῷ τιμῆς τε τῆς εἰς τὸν ναὸς καὶ βοηθείας τῆς Ἰουδαίων σωτηρίας παρασχομένου. καὶ Πετρωνίῳ μὲν οὕτως μὴ ἂν τοπασθεὶς διεφεύχθη ῥᾳδίως ὁ κίνδυνος τοῦ θανεῖν."}],"9":[{"number":310,"text":"Γίνεται δὲ καὶ περὶ τοὺς ἐν τῇ Μεσοποταμίᾳ καὶ μάλιστα τὴν Βαβυλωνίαν οἰκοῦντας Ἰουδαίους συμφορὰ δεινὴ καὶ οὐδεμιᾶς ἧστινος ἐλάσσων φόνος τε αὐτῶν πολὺς καὶ ὁπόσος οὐχ ἱστορημένος πρότερον. περὶ ὧν δὴ τὰ πάντα ἐπʼ ἀκριβὲς διηγησάμενος ἐκθήσομαι καὶ τὰς αἰτίας, ἀφʼ ὧν αὐτοῖς τὸ πάθος συνέτυχεν."},{"number":311,"text":"Νέερδα τῆς Βαβυλωνίας ἐστὶ πόλις ἄλλως τε πολυανδροῦσα καὶ χώραν ἀγαθὴν καὶ πολλὴν ἔχουσα καὶ σὺν ἄλλοις ἀγαθοῖς καὶ ἀνθρώπων ἀνάπλεως. ἔστιν δὲ καὶ πολεμίοις οὐκ εὐέμβολος περιόδῳ τε τοῦ Εὐφράτου πᾶσαν ἐντὸς αὐτὴν ἀπολαμβάνοντος καὶ κατασκευαῖς τειχῶν."},{"number":312,"text":"ἔστιν δὲ καὶ Νίσιβις πόλις κατὰ τὸν αὐτὸν τοῦ ποταμοῦ περίρρουν, ὅθεν Ἰουδαῖοι τῇ φύσει τῶν χωρίων πεπιστευκότες τό τε δίδραχμον, ὃ τῷ θεῷ καταβάλλειν ἑκάστοις πάτριον, ταύτῃ κατετίθεντο καὶ ὁπόσα δὲ ἄλλα ἀναθήματα, ἐχρῶντό τε ὥσπερ ταμιείῳ ταῖσδε ταῖς πόλεσιν."},{"number":313,"text":"ἐντεῦθεν δὲ ἐπὶ Ἱεροσολύμων ἀνεπέμπετο ᾗ καιρός, πολλαί τε ἀνθρώπων μυριάδες τὴν κομιδὴν τῶν χρημάτων παρελάμβανον δεδιότες τὰς Παρθυαίων ἁρπαγὰς ὑποτελούσης ἐκείνοις τῆς Βαβυλωνίας."},{"number":314,"text":"καὶ ἦσαν γὰρ Ἀσιναῖος καὶ Ἀνιλαῖος Νεερδᾶται μὲν τὸ γένος, ἀλλήλων δὲ ἀδελφοί. καὶ αὐτούς, πατρὸς δʼ ἦσαν ὀρφανοί, ἡ μήτηρ προσέταξεν ἱστῶν μαθήσει ποιήσεως, οὐκ ὄντος ἀπρεποῦς τοῖς ἐπιχωρίοις ὥστε τοὺς ἄνδρας ταλασιουργεῖν παρʼ αὐτοῖς. τούτοις ὁ τοῖς ἔργοις ἐφεστώς, καὶ γὰρ ἐμεμαθήκεσαν παρʼ αὐτῷ, βραδυτῆτα ἐπικαλέσας τῆς ἀφίξεως ἐκόλασε πληγαῖς."},{"number":315,"text":"οἱ δὲ ἐφʼ ὕβρει τὴν δικαίωσιν λογιζόμενοι, κατασπάσαντες τῶν ὅπλων πολλὰ ὁπόσα ἦν ἐπὶ τῆς οἰκίας φυλασσόμενα ᾤχοντο εἴς τι χωρίον, διάρρηξιν μὲν ποταμῶν λεγόμενον, νομὰς δὲ ἀγαθὰς παρασχεῖν πεφυκὸς καὶ χιλὸν ὁπόσοι εἰς τὸν χειμῶνα ἀποτιθοῖντο. συνῄεσάν τε ὡς αὐτοὺς τῶν νέων οἱ ἀπορώτατοι, καὶ τούτους τοῖς ὅπλοις φραγνύντες στρατηγοί τε ἦσαν καὶ τῶν κακῶν ἡγεμόνες οὐκ ἐκωλύοντο εἶναι."},{"number":316,"text":"προελθόντες γὰρ ἐπὶ τὸ ἄμαχον καὶ κατασκευάσαντες ἀκρόπολιν διέπεμπον πρὸς τοὺς νέμοντας φόρον αὐτοῖς κελεύοντες καταβάλλειν τῶν βοσκημάτων, ἣ ἀρκοῦσα ἐπιτροφὴ γίνοιτʼ ἄν, προστιθέντες φιλίαν τε πειθομένοις καὶ ἄμυναν τῶν ἀλλαχόθεν ποθὲν πολεμίων, σφαγὰς δὲ τῶν ποιμνίων ἀπειθοῦσιν."},{"number":317,"text":"οἱ δέ, οὐ γὰρ ἦν ἕτερα παρʼ αὐτὰ ποιεῖν, ἠκροῶντο καὶ τῶν προβάτων ἔστελλον ὁπόσα κελευσθεῖεν, ὥστε δὴ καὶ πλείων αὐτοῖς συνελέγετο ἰσχὺς κύριοί τε ἦσαν ἐφʼ οἷς βουλεύσειαν ἐκ τοῦ ὀξέος ἐλαύνοντες κακουργεῖν. θεραπεύειν τε αὐτοὺς ἦρκτο πᾶς προστυγχάνων, καὶ ἦσαν φοβεροὶ καὶ τοῖς πειρασομένοις, ὥστʼ ἤδη προύκοπτε λόγος περὶ αὐτῶν κἀπὶ τοῦ Πάρθων βασιλέως."},{"number":318,"text":"Ὁ δὲ τῆς Βαβυλωνίας σατράπης μαθὼν ταῦτα καὶ βουληθεὶς ἔτι φυομένους κωλῦσαι πρίν τι μεῖζον κακὸν ἐξ αὐτῶν ἀναστῆναι, συλλέξας στρατὸν ὅσον ἐδύνατο πλεῖστον καὶ τῶν Παρθυαίων καὶ τῶν Βαβυλωνίων ἤλασε πρὸς αὐτοὺς, φθῆναι θέλων προσβαλὼν ἐξελεῖν πρὶν ἐξάγγελτος γενέσθαι κατασκευάζων τὸν στρατόν."},{"number":319,"text":"περικαθίσας δὲ τὸ ἕλος ἡσύχαζεν, καὶ κατὰ τὴν ἐπιοῦσαν, ἦν δὲ σάββατον ἀργίας παντὸς χρήματος Ἰουδαίοις ἡμέρα, οἰόμενος οὐ τολμήσειν ἀντιστατήσειν αὐτῷ τοὺς πολεμίους, ἀλλὰ ἀμαχεὶ λαβὼν ἄξειν δεδεμένους, κατὰ βραχὺ δὲ προσῄει χρῄζων αἰφνίδιον ποιεῖσθαι τὴν ἐπίπτωσιν."},{"number":320,"text":"Ἀσιναῖος δὲ ἐτύγχανε σὺν τοῖς ἑταίροις καθεζόμενος καὶ τὰ ὅπλα παρέκειτο αὐτοῖς ἄνδρες, φησί, χρεμετισμός μοι ἵππων προσέπεσεν οὐ φορβάδων, ἀλλʼ οἷος γένοιτʼ ἂν ἀνδρῶν αὐτοῖς ἐπιβεβηκότων, ἐπεὶ καί τινος ἀνακρούσεως αἰσθάνομαι χαλινῶν· δέδια, μὴ λελήθασιν ἡμᾶς οἱ πολέμιοι περιστάντες. ἀλλά τις προΐτω κατόπτης ἀπαγγελίαν ἡμῖν σαφῆ τῶν ἐνεστηκότων ποιησόμενος. εἴη δὲ ἐπὶ ψευδέσι μοι λελέχθαι τὰ εἰρημένα. καὶ ὁ μὲν τάδε εἶπεν,"},{"number":321,"text":"καὶ ᾤχοντό τινες προσκοποῦντες τὸ γινόμενον καὶ ᾗ τάχος παρελθόντες, καὶ οὔτε αὐτὸς ψεύδῃ σαφὴς εἰκαστὴς εἶναι τῶν πρασσομένων τοῖς πολεμίοις οὔτε ἐκεῖνοι πλειόνως ἐπιτρέψειν ἤμελλον ἡμῖν ὑβριεῖν."},{"number":322,"text":"περιειλήμμεθα δόλῳ μηδὲν βοσκημάτων διαφέροντες· τοσῆσδε ἵππου πλῆθος ἐπελαύνουσιν ἡμῖν ἐν ἀπορίᾳ χειρῶν κειμένοις διὰ τὸ κατείργεσθαι προαγορεύσει"},{"number":323,"text":"τῶν πατρίων εἰς τὸ ἀργεῖν. Ἀσιναῖος δὲ οὐκ ἄρα γνώμῃ τοῦ κατασκόπου κρίνειν ἔμελλεν ἐπὶ τοῖς ποιητέοις, ἀλλὰ νομιμώτερον ἡγησάμενος τοῦ ἐπʼ ἀπράκτοις τελευτῶντας εὐφραίνειν τοὺς πολεμίους τὸ ἀλκῆς δεξάμενος αὐτοὺς ὑπὲρ τῆς ἀνάγκης εἰς ἣν ἐνεπεπτώκει παρανομεῖν τιμωρίαν ἀπολαμβάνοι, εἰ δέοι τελευτᾶν, αὐτός τε ἀναλαμβάνει τὰ ὅπλα καὶ τοῖς σὺν αὐτῷ θάρσος ἐνεποίει τῆς ἐπὶ τὰ ὅμοια ἀρετῆς."},{"number":324,"text":"ὁμόσε ἴασι τοῖς πολεμίοις, καὶ πολλοὺς κτείναντες αὐτῶν διὰ τὸ καταφρονοῦντας ὡς ἐπὶ τὰ ἕτοιμα χωρεῖν εἰς φυγὴν τρέπονται τὸ λοιπόν."},{"number":325,"text":"Ὁ δὲ τῶν Πάρθων βασιλεύς, ἐπεὶ ἀφίκετο αὐτῷ ἡ ἀγγελία τῆς μάχης, ἐκπλαγεὶς τῷ τολμήματι τῶν ἀδελφῶν ἐπεθύμησεν αὐτοῖς ἐλθεῖν διʼ ὄψεως καὶ λόγων, καὶ πέμπει τὸν πιστότατον τῶν σωματοφυλάκων λέγοντα,"},{"number":326,"text":"ὅτι βασιλεὺς Ἀρτάβανος καίπερ ἠδικημένος ὑφʼ ὑμῶν ἐπιχειρήσεως αὐτοῦ τῇ ἀρχῇ γενομένης ἐν ἐλάσσονι τὴν καθʼ αὑτὸν ὀργὴν τῆς ὑμετέρας ἀρετῆς ποιησάμενος ἀπέστειλέν με δεξιάς τε καὶ πίστιν δώσοντα ὑμῖν, συγχωρῶν ἄδειάν τε καὶ ἀσυλίαν ὁδῶν, χρῄζων ἐπὶ φιλίᾳ προσχωρεῖν πρὸς αὐτὸν δόλου τε καὶ ἀπάτης χωρίς, δῶρά τε δώσειν ὑπισχνεῖται καὶ τιμήν, ἥτις ὑμῖν πρὸς τῇ νῦν οὔσῃ ἀρετῇ μελλήσει δυνάμει τῇ ἐκείνου ὠφελεῖν. Ἀσιναῖος δὲ αὐτὸς μὲν ὑπερβάλλεται ὁδοὺς τὰς ἐκεῖ,"},{"number":327,"text":"τὸν ἀδελφὸν δὲ Ἀνιλαῖον ἐκπέμπει μετὰ δώρων ὁπόσα πορίσαι ἦν. καὶ ὁ μὲν ᾤχετο καὶ εἴσοδος αὐτῷ γίνεται παρὰ βασιλέα. Ἀρτάβανος δὲ ἐπεὶ θεᾶται τὸν Ἀνιλαῖον καταμόνας ἥκοντα, ἤρετο τὴν αἰτίαν τοῦ καὶ τὸν Ἀσιναῖον ἐφυστερηκότος."},{"number":328,"text":"ἐπεὶ δὲ πυνθάνεται αὐτὸν δείσαντα ἐν τῷ ἕλει ὑπομένειν, ὁ δὲ τούς τε πατρῴους θεοὺς ἐπώμνυτο μηδὲν κακὸν δράσειν αὐτοὺς πίστει τῇ αὐτοῦ προσκεχωρηκότας, καὶ τὴν δεξιὰν ἐδίδου, ὅπερ μέγιστον παρὰ πᾶσιν τοῖς ἐκείνῃ βαρβάροις παράδειγμα τοῦ θαρσεῖν γίνεται τοῖς ὁμιλοῦσιν·"},{"number":329,"text":"οὐ γὰρ ἂν ψεύσαιτό τις δεξιῶν ὑπʼ αὐτοῦ δόσεων γενομένων οὐδὲ πιστεύειν ἐνδοιάσειεν, εἰ τοιᾶσδε ἀσφαλείας δόσις γίνοιτο παρὰ τῶν ἐν ὑποψίᾳ ἀδικήσειν καθεστηκότων. καὶ Ἀρτάβανος μὲν ταῦτα πράξας ἐκπέμπει τὸν Ἀνιλαῖον πείσοντα τὸν ἀδελφὸν ἐπανελθεῖν,"},{"number":330,"text":"ἔπρασσεν δὲ ταῦτα βασιλεὺς χρῄζων ἐνστομισμάτων τῇ ἀρετῇ τῶν Ἰουδαίων ἀδελφῶν εἰς φιλίαν κτήσασθαι τῶν ἐκείνου σατραπειῶν ἐν ἀποστάσει τε οὐσῶν καὶ διανοίᾳ τοῦ ἀποστησομένου μέλλων ἐλάσειν ἐπʼ αὐτούς."},{"number":331,"text":"ἐδεδίει γάρ, μὴ καὶ περιεχομένου πολέμῳ τῷ ἐκείνῃ κατὰ χείρωσιν τῶν ἀφεστηκότων αὐξηθῶσιν ἐπὶ μέγα οἱ περὶ τὸν Ἀσιναῖον καὶ τὴν Βαβυλωνίαν ἤτοι γε συστήσονται ἐπʼ ἀκροάσει τῇ αὐτῶν ἢ καὶ τούτου γε ἀποτυχόντες τοῦ κακῶσαι μειζόνως οὐ διαμάρτοιεν."},{"number":332,"text":"Ὁ μὲν δὴ ταῦτα διανοηθεὶς ἐκπέμπει τὸν Ἀνιλαῖον, ὁ δὲ πιθανὸς ἦν τῷ ἀδελφῷ τήν τε ἄλλην προθυμίαν εἰσηγούμενος τοῦ βασιλέως καὶ ὅρκιον τὸ γεγενημένον, ὥστε δὴ ἠπείγοντο ὡς τὸν Ἀρτάβανον."},{"number":333,"text":"ὁ δὲ ἡδονῇ αὐτοὺς δέχεται παραγενομένους ἐθαύμαζεν τε τὸν Ἀσιναῖον τοῦ ἐν ταῖς πράξεσιν εὐψύχου, θεωρῶν παντελῶς ὄντα ὀφθῆναι βραχύν τε καὶ τοῖς τὸ πρῶτον ὄψει συνελθοῦσιν ἐνδοῦναι καταφρονήματος ἀφορμὰς ὡς οὐδενὶ κρίνοιεν αὐτόν, φησί τε πρὸς τοὺς φίλους, ὡς μείζονα ἐν τῇ παραθέσει παρέχοιτο τὴν ψυχὴν τοῦ σώματος, παρά τε πότον δεικνὺς τὸν Ἀσιναῖον Ἀβδαγάσῃ τῷ αὐτοῦ στρατοπεδάρχῃ τό τε ὄνομα διασαφεῖ καὶ τὴν πᾶσαν ἀρετήν, ᾗ χρῷτο εἰς πόλεμον."},{"number":334,"text":"τοῦ δὲ Ἀβδαγάσου κελεύοντος συγχώρημα αὐτῷ γενέσθαι κτείναντα αὐτὸν ἄποινα ἀπολαβεῖν ὑπὲρ ὧν ὑβρίσειεν εἰς τὴν Παρθυαίων ἀρχήν ἀλλʼ οὐκ ἄν, εἶπεν ὁ βασιλεύς, συγχώρημα διδοίην ἐπʼ ἀνδρὶ πίστει τῇ εἰς ἐμὲ τεθαρρηκότι καὶ προσέτι δεξιάν τε πέμψας καὶ θεῶν ὅρκοις πιθανὸς γενέσθαι σπουδάσας."},{"number":335,"text":"εἰ δὲ ἀνὴρ τυγχάνεις τὰ πολέμια ἀγαθός, μηδὲν ἐπιορκίας χρῄζων τῆς ἐμῆς Παρθυαίων ἐκδίκει τὴν ἀρχὴν περιυβρισμένην· ἐπαναχωροῦντι γὰρ ἐπιθέμενος περιγίνου κράτει τῷ περὶ σὲ καὶ μετʼ ἀγνοίας τῆς ἐμῆς."},{"number":336,"text":"ἕωθεν δὲ μετακαλέσας τὸν Ἀσιναῖον ὥρα σοι, φησίν, ὦ νεανία, χωρεῖν ἐπὶ τὰ σαυτοῦ, μὴ καὶ πλείοσιν τῶν ἐνθάδε στρατηγῶν τὴν ὀργὴν ἐρεθίσειας ἐπιχειρεῖν σου τῇ σφαγῇ καὶ δίχα γνώμης τῆς ἐμῆς."},{"number":337,"text":"παρακαταθήκην δέ σοι δίδωμι τὴν Βαβυλωνίαν γῆν ἀλῄστευτόν τε καὶ ἀπαθῆ κακῶν ἐσομένην ὑπὸ τῶν σῶν φροντίδων. ἄξιον δέ μοι τυγχάνειν σου χρηστοῦ ἀνεπίκλητόν σοι παρασχόμενος τὴν ἐμαυτοῦ πίστιν, οὐκ ἐπὶ κούφοις ἀλλʼ ἐπὶ τοῖς εἰς σωτηρίαν ἀνακειμένοις."},{"number":338,"text":"ταῦτα εἰπὼν καὶ δῶρα δοὺς τοτηνίκα ἐκπέμπει τὸν Ἀσιναῖον. ὁ δὲ εἰς τὴν οἰκείαν παραγενόμενος φρούρια κατασκευάζει καὶ ὁπόσα πρότερον ὠχύρου, μέγας τε ἐν ὀλίγῳ γεγόνει καὶ οἷος οὐκ ἄλλος τῶν πρότερον ἐκ τοιαύτης ἀφορμῆς ἅψασθαι πραγμάτων ἐν τόλμῃ γεγονότων,"},{"number":339,"text":"Παρθυαίων τε αὐτὸν ἐθεράπευον οἱ ταύτῃ καταπεμπόμενοι στρατηγοί· μικρὸν γὰρ ἐδόκει καὶ τῆς κατʼ αὐτὸν ἧσσον ἀρετῆς ἡ ἐκ Βαβυλωνίων προϊοῦσα τιμή. ἦν τε ἐν ἀξιώματι καὶ δυνάμει, πάντα τε ἤδη τὰ ἐπὶ τῆς Μεσοποταμίας πρὸς αὐτὸν ἦρτο πράγματα, προύκοπτέν τε αὐτῶν ἡ εὐδαιμονία ἐπὶ ἔτη πεντεκαίδεκα."},{"number":340,"text":"Ἀκμαζόντων δὲ αὐτοῖς τῶν ἀγαθῶν ἀρχὴ αὐτοὺς ἐπικαταλαμβάνει κακῶν ἐκ τοιᾶσδε αἰτίας, ἐπειδὴ τὴν ἀρετήν, ᾗ προύκοψαν ἐπὶ μέγα δυνάμεως, ἐκτρέπουσιν εἰς ὕβριν ἐπὶ παραβάσει τῶν πατρίων ὑπὸ ἐπιθυμιῶν καὶ ἡδονῆς ἐμπεσόντες τῶν Πάρθων τινί, στρατηγὸς δὲ ἀφίκετο τῶν ταύτῃ χωρίων,"},{"number":341,"text":"ᾧ δὴ καὶ εἵπετο γαμετὴ τά τε ἄλλα καὶ εἰς τὸ ἐπαινεῖσθαι προειληφυῖα πασῶν καὶ μείζονα ῥοπὴν ἐπʼ αὐτῷ λαμβάνουσα θαύματι τοῦ εὐπρεποῦς."},{"number":342,"text":"ταύτης εἴτε ἀκοῇ τῆς εὐπρεπείας ἐκμαθὼν εἴτε καὶ ἄλλως αὐτόπτης γενόμενος Ἀνιλαῖος ὁ τοῦ Ἀσιναίου ἀδελφὸς ἐραστής τε ἐγεγόνει καὶ πολέμιος, τὸ μὲν ὑπὸ τοῦ μὴ ἄλλως ἐλπίζειν ἐκπράσσεσθαι τὴν σύνοδον τῆς γυναικὸς μὴ τὴν ἐξουσίαν ὡς ἐπʼ αὐτῇ κτηθείσῃ παραλαβών, τὸ δὲ ὑπὸ τοῦ δυσαντίλεκτον κρίνειν τὴν ἐπιθυμίαν."},{"number":343,"text":"ἅμα τε οὖν πολέμιος ἐπʼ αὐτῆς ἀνὴρ κεχειροτόνητο κτείνων κιτιῶν καὶ μάχης ἐπάκτου γενομένης πεσόντος ἀνῃρημένου ἁλοῦσα ἐγεγάμητο τῷ ἐραστῇ. οὐ μὴν δίχα γε μεγάλων δυστυχιῶν Ἀνιλαίῳ τε ἅμα αὐτῷ καὶ Ἀσιναίῳ ἡ γυνὴ ἀφίκετο εἰς τὸν οἶκον αὐτῶν, ἀλλὰ σύν τινι μεγάλῳ κακῷ διὰ τοιαύτην αἰτίαν·"},{"number":344,"text":"ἐπεὶ γὰρ τἀνδρὸς τεθνηκότος αἰχμάλωτος ἤγετο, τὰ ἀφιδρύματα τῶν θεῶν, ἅπερ τῷ ἀνδρὶ καὶ αὐτῇ πατρῷα ἦν, ἐπιχώριον δὲ τοῖς ἐκείνῃ πᾶσίν ἐστιν ἐπί τε τῆς οἰκίας ἔχειν σεβάσματα καὶ ἰοῦσιν ἐπὶ ξένης συνεπάγεσθαι, περιστέλλουσα καὶ ταύτῃ τοῦ πατρίου τὸ ἐπʼ αὐτοῖς ἔθος συναπήγετο, καὶ τὸ μὲν πρῶτον λεληθότως αὐτῶν θρησκείαν ἐποιεῖτο, γαμετὴ δὲ ἀποδειχθεῖσα ἤδη τρόπῳ τῷ αὐτῆς εἰωθότι καὶ μεθʼ οἵων νομίμων ἐπὶ τοῦ προτέρου ἀνδρὸς ἐθεράπευεν αὐτούς."},{"number":345,"text":"καὶ τῶν ἑταίρων οἱ μάλιστα τιμώμενοι παρʼ αὐτοῖς τὸ μὲν πρῶτον οὐδαμῶς πράσσοι Ἑβραϊκὰ οὐδὲ ὁπόσα νόμοις τοῖς αὐτῶν πρόσφορα γυναῖκα ἠγμένος ἀλλόφυλον καὶ παραβαίνουσαν θυσιῶν καὶ σεβασμῶν τῶν αὐτοῖς εἰωθότων τὴν ἀκρίβειαν· ὁρᾶν οὖν, μὴ τὰ πολλὰ τῇ ἡδονῇ τοῦ σώματος συγχωρῶν ἀπολέσειε τὴν ἀρχὴν τοῦ εὐπρεποῦς καὶ τὴν εἰς νῦν ὑπὸ τοῦ θείου προελθοῦσαν ἐξουσίαν."},{"number":346,"text":"ἐπεὶ δὲ οὐδὲν ἐπέραινον, ἀλλὰ καί τινα αὐτῶν τὸν μάλιστα τιμώμενον ὅτι πλέονι παρρησίᾳ χρήσαιτο ἀπέκτεινε, καὶ ὃς θεώμενος εὐνοίας τε τῶν νόμων καὶ τοῦ κτείνοντος αὐτὸν τιμωρίαν ἐπηράσατο αὐτῷ τε Ἀνιλαίῳ καὶ Ἀσιναίῳ καὶ πᾶσιν ἑταίροις ὁμοίαν ὑπὸ τῶν ἐχθρῶν ἐπαχθεῖσαν γενέσθαι τελευτήν,"},{"number":347,"text":"τοῖς μὲν ὡς ἡγεμόσι παρανομιῶν γεγονόσι, τοῖς δέ, ὅτι μὴ βοηθοῖεν αὐτῷ τοιάδε πάσχοντι διὰ τὸ ἐκδικεῖν τοῖς νόμοις, οἱ δὲ ἐβαρύνοντο μέν, ἠνείχοντο δέ, μνημονεύοντες οὐκ ἐξ ἄλλης αἰτίας ἀλλʼ ἰσχύι τῇ ἐκείνων τῇ εὐδαιμονίᾳ συνελθόντες."},{"number":348,"text":"ἐπεὶ δὲ καὶ τὴν θεραπείαν ἀκροῶνται τῶν θεῶν τῶν Παρθυαίοις τιμωμένων, οὐκέτι ἀνεκτὸν ἡγούμενοι τοῦ Ἀνιλαίου τὸ ὑβρίζον εἰς τοὺς νόμους ἐπὶ τὸν Ἀσιναῖον ἐλθόντες καὶ πλέονες ἤδη κατεβόων τοῦ Ἀνιλαίου,"},{"number":349,"text":"φάμενοι καλῶς ἔχειν, εἰ μὴ πρότερον κατʼ αὐτὸν ἑώρα τὸ ὠφελοῦν ἀλλὰ νῦν γοῦν ἐπιστροφὴν ποιεῖσθαι τοῦ γεγονότος πρὶν ἢ τὴν ἁμαρτίαν ἐκείνῳ τε καὶ πᾶσι τοῖς ἄλλοις γενέσθαι εἰς ὄλεθρον ἀνακειμένην, τόν τε γάμον τῆς ἀνθρώπου λέγοντες οὐ μετʼ αὐτῶν οὐδʼ αὐτοῖς εἰωθότων τεθεῖσθαι νόμων καὶ τὴν θρησκείαν ἣν ἐπιτηδεύοι ἡ γυνὴ ἐπʼ ἀτιμώσει θεοῦ τοῦ αὐτοῖς σεβασμίου πράσσεσθαι."},{"number":350,"text":"ὁ δὲ καὐτὸς ᾔδει μὲν τὴν ἁμαρτάδα τοῦ ἀδελφοῦ μεγάλων αἰτίαν οὖσαν κακῶν καὶ ἐσομένην, οὐ μὴν ἀπείχετό γε εὐνοίᾳ τοῦ συγγενοῦς νικώμενος καὶ συγγνώμην νέμων ὡς ὑπὸ κρείσσονος κακοῦ τῆς ἐπιθυμίας νικωμένου."},{"number":351,"text":"ἐπεὶ δὲ πλείους τε ὁσημέραι συνεστρέφοντο καὶ πλείους ἦσαν αἱ καταβοαί, τηνικαῦτα δή φησιν περὶ αὐτῶν πρὸς Ἀνιλαῖον τοῖς τε πρῶτον γεγονόσιν ἐπιτιμῶν καὶ παύσασθαι τὸ λοιπὸν κελεύων τὴν ἄνθρωπον ἀποπεμψάμενον εἰς τοὺς συγγενεῖς."},{"number":352,"text":"ἐπράσσετο δὲ οὐδὲν ἐκ τῶν λόγων· καὶ ἡ γυνὴ δὲ αἰσθανομένη μὲν τοῦ θροῦ τοῦ κατέχοντος τοὺς λαοὺς διʼ αὐτήν, δεδοικυῖα δὲ περὶ τοῦ Ἀνιλαίου, μὴ καί τι πάθοι ἔρωτι τῷ πρὸς αὐτήν, φάρμακον τῷ Ἀσιναίῳ δοῦσα ἐν τοῖς σιτίοις μεθίστατο τὸν ἄνθρωπον ἀδεής τε ἦν ἐπὶ κριτῇ τῶν περὶ αὐτὴν πραχθησομένων τῷ ἐραστῇ γενομένη."},{"number":353,"text":"Ἀνιλαῖος δὲ καταμόνας ἤδη τὴν ἡγεμονίαν παραλαβὼν ἐξάγει στρατιὰν ἐπὶ τὰς Μιθριδάτου κώμας ἀνδρὸς πρώτου ἐν τῇ Παρθυηνῇ καὶ βασιλέως Ἀρταβάνου τὴν θυγατέρα γεγαμηκότος, διὰ λείας τε ἦγεν αὐτάς, καὶ πολλὰ μὲν χρήματα καὶ ἀνδράποδα εὑρίσκεται, πολλὰ δὲ πρόβατα ἄλλα τε πολλὰ ὁπόσα ἐπὶ προσλήψει τοῦ εὐδαίμονος ὠφελεῖ τοῖς ἔχουσιν."},{"number":354,"text":"Μιθριδάτης δέ, ἐτύγχανε γὰρ τῇδε ὤν, ἐπειδὴ ἀκούει τῶν κωμῶν τὴν ἅλωσιν ἐν δεινῷ φέρων, ὁπότε μὴ προάρξαντος ἀδικεῖν Ἀνιλαῖος ἄρξαιτο καὶ παρόντος τοῦ ἀξιώματος ὑπεριδών, ἱππέας συναγαγὼν πλείστους ὅσους ἐδύνατο καὶ τῶν πλείστων τοὺς ἐν ἡλικίᾳ παρῆν ὡς προσμίξων τοῖς περὶ τὸν Ἀνιλαῖον καὶ ἔν τινι κώμῃ τῶν αὐτοῦ σχὼν ἡσύχαζεν, ὡς τῇ ἐπιούσῃ μαχησόμενος διὰ τὸ εἶναι σαββάτων ἡμέραν τοῖς Ἰουδαίοις ἐν ἀργίᾳ διαγομένην."},{"number":355,"text":"Ἀνιλαῖος δὲ ταῦτα πυθόμενος παρὰ ἀνδρὸς Σύρου ἀλλοφύλου ἐξ ἑτέρας κώμης τέ τε ἄλλα φράζοντος ἀκριβῶς καὶ τὸ χωρίον, ἔνθα Μιθριδάτης ἤμελλεν δαίνυσθαι, δειπνοποιησάμενος καθʼ ὥραν ἤλαυνε νυκτὸς ἀμαθέσι τῶν ποιουμένων χρῄζων τοῖς Παρθυαίοις ἐπιπεσεῖν."},{"number":356,"text":"καὶ περὶ τετάρτην φυλακὴν ἐπιπεσὼν τοὺς μὲν ἔτι κοιμωμένους ἀναιρεῖ τοὺς δὲ εἰς φυγὴν τρέπει, Μιθριδάτην δὲ ζωγρίᾳ λαβὼν ἦγεν ὡς αὐτὸν ἐπὶ ὄνον γυμνὸν ἀναθέμενος, ἥπερ ἀτιμιῶν μεγίστη νομίζεται παρὰ Παρθυαίοις."},{"number":357,"text":"καταγαγὼν δὲ εἰς τὴν ὕλην μετὰ τοιοῦδε ὁρίσματος, καὶ κελευόντων τῶν φίλων ἀναιρεῖν τὸν Μιθριδάτην ἀνεδίδασκεν αὐτοὺς σπεύδων αὐτὸς ἐναντία· μὴ γὰρ καλῶς ἔχειν ἀναιρεῖν ἄνδρα γένους τε ὄντα τοῦ πρώτου παρὰ Παρθυαίοις καὶ ἐπιγαμίᾳ τῇ πρὸς τὸν βασιλέα μειζόνως τιμώμενον·"},{"number":358,"text":"νῦν μὲν γὰρ ἀνεκτὰ εἶναι τὰ πεπραγμένα· καὶ γὰρ εἰ περιύβρισται Μιθριδάτης, ἀλλʼ οὖν σωτηρίᾳ τῆς ψυχῆς εὐεργετούμενον χάριτος μνήσεσθαι τοῖς τὰ τοιάδε παρασχοῦσιν,"},{"number":359,"text":"παθόντος δέ τι ἀνήκεστον οὐκ ἀτρεμήσειν βασιλέα μὴ οὐ μεγάλην σφαγὴν Ἰουδαίων τῶν ἐν Βαβυλῶνι ποιησάμενον, ὧν φείδεσθαι καλῶς ἔχειν διά τε τὴν συγγένειαν καὶ διὰ τὸ μὴ ἀναστροφὴν εἶναι ἂν αὐτοῖς πταίσματός τινος γενομένου τὸ κατʼ ἐκείνους ἀκμῆς πληθύι χρώμενον."},{"number":360,"text":"καὶ ὁ μὲν ταῦτα διανοηθεὶς καὶ φράσας ἐν τῷ συλλόγῳ πιθανὸς ἦν ἀφίεταί τε Μιθριδάτης, ἐλθόντα δὲ αὐτὸν ὠνείδιζεν ἡ γυνή, εἰ μὴ προμηθήσεται βασιλέως τε γαμβρὸς ὢν καὶ ταύτῃ τιμωρῶν τιμωρηθήσεσθαι τοὺς ὑβρίσαντας εἰς αὐτὸν περιορώμενος,"},{"number":361,"text":"ἀγαπῶν δὲ τὴν σωτηρίαν μετὰ αἰχμαλωσίαν ὑπὸ Ἰουδαίων ἀνδρῶν γενομένην· καὶ νῦν ἐπανάδραμε τὴν ἀρετήν, ἢ θεοὺς ἐπόμνυμι τοὺς βασιλείους ἦ μὴν παραλυθήσεσθαι τῆς πρὸς σὲ ἐπὶ γάμῳ κοινωνίας."},{"number":362,"text":"ὁ δὲ αὖ τοῦτο μὲν τῶν ὀνειδῶν τὴν καθʼ ἡμέραν ἀχθηδόνα μὴ φέρων, τοῦτο δὲ τῆς γυναικὸς τὴν μεγαλοφροσύνην δεδιώς, μὴ παραλύοιτο αὐτοῦ τῶν γάμων, ἄκων μὲν καὶ μὴ βουλόμενος συνάγει δʼ οὖν στρατὸν ὅσον ἐδύνατο πλεῖστον καὶ ἤλαυνεν οὐκ ἀνασχετὸν ὑπολαμβάνων ἔτι καὶ αὐτὸς τὴν σωτηρίαν, εἰ Παρθυαῖος ὢν ὑπὸ Ἰουδαίου περιωθοῖτο ἀντιπολεμοῦντος."},{"number":363,"text":"Ἀνιλαῖος δὲ ὡς μανθάνει προσελαύνοντα δυνάμει πολλῇ τὸν Μιθριδάτην ἄδοξον ἡγησάμενος τὸ μένειν ἐν τοῖς ἕλεσιν, ἀλλὰ μὴ φθάσας ὑπαντιάζειν τοὺς πολεμίους, εὐτυχίᾳ τε τῇ πρότερον ἐλπίζων ὅμοια πράξειν καὶ τήν τε ἀρετὴν τοῖς τολμῶσι καὶ εἰωθόσιν θαρρεῖν παρατυγχάνειν, ἐξῆγε τὴν δύναμιν."},{"number":364,"text":"πολλοί τε πρὸς τῷ οἰκείῳ στρατῷ προσεγεγόνεσαν αὐτῷ καθʼ ἁρπαγὴν τῶν ἀλλοτρίων τραπησόμενοι καὶ ὄψει πᾶν προεκπλήξοντες τοὺς πολεμίους."},{"number":365,"text":"προϊοῦσι δὲ αὐτοῖς εἰς σταδίους ἐνενήκοντα καὶ διὰ τῆς ἀνύδρου τῆς πορείας γενομένης καὶ μεσημβρίας τά τε ἄλλα περιῆν τότε τὸ δίψος καὶ Μιθριδάτης ἐπιφανεὶς προσέβαλε τεταλαιπωρημένοις ἀπορίᾳ τοῦ πιεῖν καὶ διʼ αὐτὸ καὶ τὴν ὥραν φέρειν τὰ ὅπλα μὴ δυναμένοις."},{"number":366,"text":"τροπή τε οὖν γίνεται τῶν περὶ τὸν Ἀνιλαῖον διὰ τὸ ἀπηγορευκότας ἀκραιφνέσι προσφέρεσθαι καὶ φόνος πολὺς πολλαί τε μυριάδες ἔπεσον ἀνδρῶν, Ἀνιλαῖος δὲ καὶ ὅσον περὶ αὐτὸν ἦν συνεστηκὸς ἐπὶ τῆς ὕλης ἐπανεχώρουν φυγῇ μεγάλην νίκης τῆς ἐπʼ αὐτοῖς χαρὰν Μιθριδάτῃ παρεσχηκότες."},{"number":367,"text":"Ἀνιλαίῳ δὲ προσῄει πλῆθος ἄπορον ἀνδρῶν πονηρῶν ἐν ὀλίγῳ τὴν σωτηρίαν ποιουμένων ῥᾳστώνης χάριτι τῆς εἰς τὸ παρόν, ὥστε ἀντανίσωμα τὴν τούτων πρόσοδον γενέσθαι πλῆθος τῶν ἀπολωλότων· οὐ μὴν ὅμοιοί γε ἦσαν τοῖς πεπτωκόσι διὰ τὸ ἀμελέτητον."},{"number":368,"text":"οὐ μὴν ἀλλὰ καὶ ταύταις ἐπιφοιτᾷ ταῖς κώμαις τῶν Βαβυλωνίων ἀνάστατά τε ἦν πάντα ταῦτα ὑπὸ τῆς Ἀνιλαίου ὕβρεως."},{"number":369,"text":"καὶ οἱ Βαβυλώνιοι καὶ οἱ ὄντες ἐν τῷ πολέμῳ πέμπουσιν ἐς τὰ Νέερδα πρὸς τοὺς ἐν αὐτῇ Ἰουδαίους Ἀνιλαῖον ἐξαιτούμενοι, καὶ μὴ δεξομένοις τὸν λόγον τοῦτον, οὐδὲ γὰρ βουλομένοις ἔκδοτον παρασχεῖν δυνηθῆναι, εἰρήνην προυκαλοῦντο· οἱ δὲ καὐτοὶ χρῄζειν ἔλεγον τῶν ἐπὶ τῆς εἰρήνης συμβάσεων καὶ πέμπουσι μετὰ τῶν Βαβυλωνίων ἄνδρας, οἳ διαλέξοιντο πρὸς τὸν Ἀνιλαῖον."},{"number":370,"text":"οἱ δὲ Βαβυλώνιοι κατοπτίας αὐτοῖς γενομένης μαθόντες τὸ χωρίον, ἐν ᾧ ἱδρυμένος ὁ Ἀνιλαῖος ἦν, ἐπιπεσόντες κρύφα νυκτὸς μεθύουσι καὶ καθʼ ὕπνον τετραμμένοις κτείνουσιν ἀδεῶς πάντας ὅσους ἐγκατέλαβον καὶ Ἀνιλαῖον αὐτόν."},{"number":371,"text":"Βαβυλώνιοι δὲ ἀπαλλαγέντες τῆς Ἀνιλαίου βαρύτητος, ἐπιστόμισμα γὰρ ἦν αὐτῶν μίσει τῷ πρὸς τοὺς Ἰουδαίους, ἀεὶ γὰρ ὡς ἐπὶ πολὺ διάφοροι καθεστήκεσαν αἰτίᾳ τῆς ἐναντιώσεως τῶν νόμων καὶ ὁποτέροις παραγένοιτο θαρρεῖν πρότεροι ἀλλήλων ἥπτοντο εἰ μὴ καὶ τότε οὖν ἀπολωλότων τῶν περὶ τὸν Ἀνιλαῖον ἐπετίθεντο τοῖς Ἰουδαίοις οἱ Βαβυλώνιοι."},{"number":372,"text":"οἱ δʼ ἐν δεινῷ τιθέμενοι τὴν ὕβριν τὴν ἐκ τῶν Βαβυλωνίων καὶ μήτε ἀντιτάξασθαι μάχῃ δυνάμενοι μήτε ἀνεκτὸν ἡγούμενοι τὴν συνοικίαν ᾤχοντο εἰς Σελεύκειαν τῶν ἐκείνῃ πόλιν ἀξιολογωτάτην Σελεύκου κτίσαντος αὐτὴν τοῦ Νικάτορος. οἰκοῦσιν δʼ αὐτὴν πολλοὶ μὲν Μακεδόνων, πλεῖστοι δὲ Ἕλληνες, ἔστιν δὲ καὶ Σύρων οὐκ ὀλίγον τὸ ἐμπολιτευόμενον."},{"number":373,"text":"εἰς μὲν δὴ ταύτην καταφεύγουσιν οἱ Ἰουδαῖοι καὶ ἐπὶ μὲν πέντε ἔτη ἀπαθεῖς κακῶν ἦσαν, τῷ δὲ ἕκτῳ ἔτει μετὰ τὸ πρῶτον φθορὰ ἐν Βαβυλῶνι ἐγένετο αὐτῶν καὶ καιναὶ κτίσεις ἐκ τῆς πόλεως καὶ διʼ αὐτὴν ἄφιξις εἰς τὴν Σελεύκειαν ἐκδέχεται μείζων αὐτοὺς συμφορὰ διʼ αἰτίαν, ἣν ἀφηγήσομαι."},{"number":374,"text":"Σελευκέων τοῖς Ἕλλησι πρὸς τοὺς Σύρους ὡς ἐπὶ πολὺ ἐν στάσει καὶ διχονοίᾳ ἐστὶν ὁ βίος καὶ κρατοῦσιν οἱ Ἕλληνες. τότε οὖν συνοικούντων αὐτοῖς Ἰουδαίων γενομένων ἐστασίαζον, καὶ οἱ Σύροι καθυπέρτεροι ἦσαν ὁμολογίᾳ τῇ Ἰουδαίων πρὸς αὐτοὺς φιλοκινδύνων τε ἀνδρῶν καὶ πολεμεῖν προθύμως ἐντεταγμένων."},{"number":375,"text":"καὶ οἱ Ἕλληνες περιωθούμενοι τῇ στάσει καὶ μίαν ὁρῶντες αὐτοῖς ἀφορμὴν τοῦ ἀνασώσασθαι τὸ πρότερον ἀξίωμα, εἰ δυνηθεῖεν παῦσαι ταὐτὸν λέγοντας Ἰουδαίους καὶ Σύρους, διελέγοντο ἕκαστοι πρὸς τῶν Σύρων τοὺς αὐτοῖς συνήθεις πρὸ τοῦ γεγονότας εἰρήνην τε καὶ φιλίαν ὑπισχνούμενοι."},{"number":376,"text":"οἱ δὲ ἐπείθοντο ἄσμενοι. ἐγίνοντο οὖν ἀφʼ ἑκατέρων λόγοι καὶ τῶν πρώτων παρʼ ἑκατέροις ἀνδρῶν προασσόντων ἐπιδιαλλαγὰς τάχιστα ἡ σύμβασις ἐγένετο, ὁμονοήσαντές τε μέγα τεκμήριον ἑκάτεροι εὐνοίας παρʼ ἀλλήλοις ἠξίουν παρασχεῖν τὸ πρὸς τοὺς Ἰουδαίους ἔχθος, ἐπιπεσόντες τε αἰφνίδιον αὐτοῖς κτείνουσι μυριάδας ὑπὲρ πέντε ἀνδρῶν, ἀπώλοντό τε πάντες πλὴν εἴ τινες ἐλέῳ φίλων ἢ γειτόνων ἐπιχωρηθὲν αὐτοῖς ἔφυγον."},{"number":377,"text":"τούτοις δὲ ἦν εἰς Κτησιφῶντα ἀποχώρησις πόλιν Ἑλληνίδα καὶ τῆς Σελευκείας πλησίον κειμένην, ἔνθα χειμάζει τε ὁ βασιλεὺς κατὰ πᾶν ἔτος καὶ πλείστη τῆς ἀποσκευῆς αὐτοῦ τῇδε ἀποκειμένη τυγχάνει. ἀσύνετα δὲ ἦν αὐτοῖς τὴν ἵδρυσιν πεποιημένοις τιμῇ τῆς βασιλείας Σελευκέων πεφροντικότων."},{"number":378,"text":"ἐφοβήθη δὲ καὶ πᾶν τὸ τῇδε Ἰουδαίων ἔθνος τούς τε Βαβυλωνίους καὶ τοὺς Σελευκεῖς, ἐπειδὴ καὶ ὁπόσον ἦν Σύρων ἐμπολιτεῦον τοῖς τόποις ταὐτὸν ἔλεγον τοῖς Σελευκεῦσιν ἐπὶ πολέμῳ τῷ πρὸς τοὺς Ἰουδαίους."},{"number":379,"text":"καὶ συνελέγησαν ὥστε πολὺ εἴς τε τὰ Νέερδα καὶ τὴν Νίσιβιν ὀχυρότητι τῶν πόλεων κτώμενοι τὴν ἀσφάλειαν, καὶ ἄλλως πληθὺς ἅπασα μαχίμων ἀνδρῶν κατοικεῖται. καὶ τὰ μὲν κατὰ Ἰουδαίους τοὺς ἐν τῇ Βαβυλωνίᾳ κατῳκημένους τοιαῦτα ἦν."}]},"count":379};a[19]={"book":19,"title":"Τάδε ἔνεστιν ἐν τῇ ιθ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"ὡς Γάιος Καῖσαρ ἐπιβουλευθεὶς ὑπὸ Κασσίου Χαιρέου ἀνῃρέθη καὶ ὡς Κλαύδιος ὁ θεῖος αὐτοῦ βιασθεὶς ὑπὸ τῶν στρατιωτῶν τὴν ἀρχὴν παρέλαβεν.\n\nστάσις τῆς βουλῆς καὶ τοῦ δήμου πρὸς αὐτὸν καὶ τὰ σὺν αὐτῷ στρατεύματα.\n\nπρεσβεία τοῦ βασιλέως Ἀγρίππα πρὸς τὴν βουλήν, καὶ ὡς συνθέμενοι οἱ στρατιῶται οἱ μετὰ τῆς βουλῆς ἀπεχώρησαν πρὸς Κλαύδιον καὶ κύριον αὐτὸν κατέστησαν τῶν πραγμάτων, ἡ δὲ βουλὴ μονωθεῖσα παρεκάλει Κλαύδιον αὐτῇ διαλλαγῆναι.\n\nὡς Κλαύδιος Καῖσαρ ἀποδίδωσιν Ἀγρίππᾳ τὴν πατρῴαν αὐτοῦ βασιλείαν ἅπασαν προσθεὶς αὐτῷ καὶ τὴν Λυσανίου τετραρχίαν.\n\nπρογράμματα Κλαυδίου Καίσαρος ἐν Ἀλεξανδρείᾳ ὑπὲρ τῶν ἐκεῖ Ἰουδαίων καὶ ἐν πάσῃ αὐτοῦ ἀρχῇ.\n\nἀπόπλους Ἀγρίππα τοῦ βασιλέως εἰς Ἰουδαίαν.\n\nἐπιστολὴ Πουπλίου Πετρωνίου τοῦ Συρίας ἡγεμόνος πρὸς Δωρίτας ὑπὲρ Ἰουδαίων.\n\nὡς βασιλεὺς Ἀγρίππας τὰ Ἱεροσολύμων τείχη πολυτελῶς κατασκευάζων ἀτελῆ τὴν σπουδὴν ἔσχεν μεταξὺ τελευτήσας.\n\nὅσα ἔπραξεν ἐν τρισὶν ἔτεσιν ἄχρι τῆς τελευτῆς αὐτοῦ καὶ ὃν τρόπον τὸν βίον κατέστρεψεν.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν γ μηνῶν ϛ."},"chapters":{"1":[{"number":1,"text":"Γάιος δὲ οὐκ εἰς μόνους Ἰουδαίους τοὺς ἐν Ἱεροσολύμοις καὶ τοὺς ὁπόσοι τῇδε οἰκοῦσιν ἐπεδείκνυτο τῆς ὕβρεως τὴν μανίαν, ἀλλὰ διὰ πάσης ἐσομένην γῆς καὶ θαλάσσης ἔστελλεν αὐτήν, ὁπόση Ῥωμαίοις ὑπακούει, μυρίων τε ἀνέπλησεν αὐτὴν κακῶν ὁπόσα μὴ ἱστόρητο πρότερον."},{"number":2,"text":"μάλιστα δὲ ᾐσθάνετο τοῦ δεινοῦ τῶν πρασσομένων ἡ Ῥώμη κατʼ οὐδὲν αὐτὴν τιμιωτέραν τῶν λοιπῶν πόλεων ἡγουμένου, ἀλλὰ τούς τε ἄλλους ἄγοντος καὶ φέροντος καὶ μάλιστα τὴν σύγκλητον καὶ ὁπόσοι τούτων εὐπατρίδαι καὶ προγόνων ἐπιφανείαις τιμώμενοι."},{"number":3,"text":"μυρία τε εὑρίσκετο καὶ κατὰ τῶν ἱππέων μὲν καλουμένων, ἀξιώματι δὲ καὶ δυνάμει χρημάτων ὅμοια τοῖς συγκλητικοῖς ὑπὸ τῆς πόλεως ἀγομένων διὰ τὸ ἐκ τούτων εἰς τὴν βουλὴν εἶναι κατακλήσεις· ὧν ἀτίμωσις ἦν καὶ μετανάστασις κτεινομένων τε καὶ τὰ χρήματα συλωμένων διὰ τὸ καὶ τὰς σφαγὰς ὡς τὸ πολὺ ἐπʼ ἀφαιρέσει τῶν χρημάτων αὐτοῖς συντυγχάνειν."},{"number":4,"text":"ἐξεθείαζέν τε ἑαυτὸν καὶ τὰς τιμὰς οὐκέτʼ ἀνθρωπίνως ἠξίου γίνεσθαι παρὰ τῶν ὑπηκόων αὐτῷ· εἴς τε τοῦ Διὸς φοιτῶν τὸ ἱερόν, ὃ Καπετώλιον μὲν καλοῦσιν τιμιώτατον δʼ ἄρα αὐτοῖς ἐστιν ἱερῶν, ἀδελφὸν ἐτόλμησε προσαγορεύειν τὸν Δία·"},{"number":5,"text":"καὶ τἆλλα ἔπρασσεν μανίας οὐδὲν ἀπολελειμμένα, ἐπεὶ καὶ ἀπὸ Δικαιαρχείας τῆς πόλεως ἐν Καμπανίᾳ κειμένης εἰς Μισηνοὺς ἑτέραν πόλιν ἐπιθαλάσσιον, καὶ τὴν διάβασιν δεινὸν ἡγούμενος τριήρει περατοῦν,"},{"number":6,"text":"καὶ ἄλλως ἐπιβάλλειν ἡγούμενος αὐτῷ δεσπότῃ ὄντι τῆς θαλάσσης ταῦτα καὶ ὁποῖα καὶ παρὰ γῆς ἀπαιτεῖν, ἀπʼ ἄκρων ἐπʼ ἄκρα σταδίους τριάκοντα μέτρον τῆς θαλάσσης ζεύξας καὶ εἴσω τὸν κόλπον ἀπολαβὼν πάντα ἤλαυνεν ἐπὶ τῇ γεφύρᾳ τὸ ἅρμα· θεῷ γὰρ ὄντι τοιαύτας ποιεῖσθαι καλῶς ἔχειν τὰς ὁδούς."},{"number":7,"text":"τῶν τε ἱερῶν τῶν Ἑλληνικῶν οὐδὲν ἔτι ἀσύλητον κατέλιπεν, ὁπόσα γραφῆς ἢ γλυφῆς ἐχόμενα καὶ τὰς λοιπὰς κατασκευὰς ἀνδριάντων καὶ ἀναθημάτων ἄγεσθαι κελεύσας παρʼ αὐτόν· οὐ γὰρ ἐν ἑτέρῳ τὰ καλὰ κεῖσθαι καλῶς ἔχειν ἢ ἐν τῷ καλλίστῳ, τυγχάνειν δὲ τοῦτο οὖσαν τὴν Ῥωμαίων πόλιν."},{"number":8,"text":"ἐκόσμει τε τοῖς ἐνθένδε ἀγομένοις τήν τε οἰκίαν καὶ τοὺς κήπους ὁπόσαι τε αὐτῷ καταγωγαὶ διὰ γῆς τῆς τῶν Ἰταλῶν. ἐπεὶ καὶ τὸν Ὀλύμπιον τιμώμενον Δία ὑπὸ τῶν Ἑλλήνων καὶ οὕτως ὠνομασμένον Ὀλύμπιον Φειδίου τοῦ Ἀθηναίου πεποιηκότος ἐτόλμησε κελεῦσαι εἰς τὴν Ῥώμην μεταφέρειν."},{"number":9,"text":"οὐ μὴν ἔπραξέν γε τῶν ἀρχιτεκτόνων φαμένων πρὸς Μέμμιον Ῥῆγλον, ὃς ἐπετέτακτο τῇ κινήσει τοῦ Διός, ἀπολεῖσθαι τοὖργον κινήσεως αὐτοῦ γενομένης. λέγεται δὲ Μέμμιον διὰ ταῦτα καὶ σημείων μειζόνων γενομένων, ἢ ὡς ἄν τινα μὴ πιστὰ ἡγεῖσθαι, ὑπερβαλέσθαι τὴν ἀναίρεσιν."},{"number":10,"text":"καὶ γράφει τάδε πρὸς τὸν Γάιον ἐπʼ ἀπολογίᾳ τοῦ ἐκλιπεῖν ἀδιακόνητον τὴν ἐπιστολήν, ἀπολέσθαι τε ἐκ τούτων αὐτῷ κινδύνου γενομένου σώζεται φθάνοντος ἤδη Γαΐου τελευτῆσαι."},{"number":11,"text":"Εἰς τοῦτο δὲ προύβη τὸ μανικὸν αὐτῷ, ὥστε δὴ καὶ θυγατρὸς αὐτῷ γενομένης ἀνακομίσας ἐπὶ τὸ Καπετώλιον ἐπὶ τοῖς γόνασι κατατίθεται τοῦ ἀγάλματος, κοινὸν αὐτῷ τε καὶ τῷ Διὶ γεγονέναι τὸ τέκνον καὶ δύο χειροτονεῖν αὐτῆς πατέρας, ὁπότερον μείζονα φάμενος ἐν μέσῳ τε καταλιμπάνειν."},{"number":12,"text":"καὶ τάδε ἠνείχοντο πράσσοντα αὐτὸν οἱ ἄνθρωποι. ἐπεχείρησε δὲ καὶ τοῖς οἰκέταις κατηγορίας ποιεῖσθαι τῶν δεσποτῶν ἐφʼ οἷστισιν ἐθελήσειαν ἐγκλήμασιν· δεινὰ γὰρ πάντα ἦν, ὁπόσα μέλλοι λέγεσθαι, διὰ τὸ χάριτί τε καὶ ὑπαγορεύσει τῇ ἐκείνου τὰ πολλὰ γίνεσθαι,"},{"number":13,"text":"ὥστε ἤδη καὶ Κλαυδίου ἐτόλμα ποιήσασθαι Πολυδεύκης ὁ δοῦλος κατηγορίαν, καὶ Γάιος ἠνείχετο κατὰ πατρῴου τοῦ αὐτοῦ δίκης θανάτου λεγομένης ἐπʼ ἀκροάσει συνελθεῖν ἐλπίδι τοῦ παραλαβεῖν δύναμιν ἀνελεῖν αὐτόν."},{"number":14,"text":"οὐ μὴν ἐξεγένετό γε αὐτῷ. ἀναπεπληρωκότι δὲ αὐτῷ συκοφαντιῶν καὶ κακῶν πᾶσαν τὴν οἰκουμένην, ἧς ἐπῆρχεν, καὶ πολλὴν τὴν δουλοκρατίαν ἐπῃρμένου τοῖς δεσπόταις ἐπιβουλαὶ τὰ πολλὰ ἤδη συνίσταντο, τῶν μὲν ἐπʼ ἀμύνῃ ὧν πάθοιεν ὀργὴν ποιουμένων, τῶν δὲ πρὶν ἐμπεσόντες κακῶν τυχεῖν μεγάλων τιθεμένων τὸ μεταχειρίσασθαι τὸν ἄνθρωπον."},{"number":15,"text":"ὅθεν, ἐπειδὴ τοῖς τε ἁπάντων νόμοις καὶ τῷ ἀσφαλεῖ μεγάλην συνήνεγκεν εὐδαιμονίας ῥοπὴν ὁ θάνατος αὐτοῦ ἔθνει τε τῷ ἡμετέρῳ οὐδὲ εἰς ὀλίγον ἐξεγεγόνει μὴ οὐκ ἀπολωλέναι μὴ ταχείας αὐτῷ τελευτῆς παραγενομένης, βούλομαι δὲ διʼ ἀκριβείας τὸν πάντα περὶ αὐτοῦ λόγον διελθεῖν,"},{"number":16,"text":"ἄλλως τε ἐπειδὴ καὶ πολλὴν ἔχει πίστιν τοῦ θεοῦ τῆς δυνάμεως καὶ παραμυθίαν τοῖς ἐν τύχαις κειμένοις καὶ σωφρονισμὸν τοῖς οἰομένοις ἀίδιον τὴν εὐτυχίαν, ἀλλὰ μὴ ἐπιμεταφέρειν κακῶς ἀρετῆς αὐτῇ μὴ παραγενομένης."},{"number":17,"text":"Ὁδοὺς μὲν δὴ τρεῖς ὁ θάνατος αὐτοῦ παρεσκευάζετο καὶ τούτων ἑκάστης ἄνδρες ἀγαθοὶ τὴν ἡγεμονίαν εἶχον. Αἰμίλιός τε γὰρ Ῥῆγλος ἐκ Κορδύβης τῆς ἐν Ἰβηρίᾳ γένος συνεῖχέν τινας ἢ διʼ ἐκείνων ἢ διʼ αὐτοῦ πρόθυμος ὢν ἄρασθαι Γάιον."},{"number":18,"text":"ἑτέρα δὲ αὐτοῖς συνεκροτεῖτο, ἧς Χαιρέας Κάσσιος χιλίαρχος ἡγεμὼν ἦν. Μινουκιανὸς δὲ Ἄννιος οὐκ ὀλίγη μοῖρα τῶν ἐπὶ τὴν τυραννίδα παρεσκευασμένων ἦν."},{"number":19,"text":"αἰτία δʼ αὐτοῖς μίσους τοῦ πρὸς Γάιον συνελθεῖν, Ῥήγλῳ μὲν τὸ ἐπὶ πᾶσιν ὀργίλον καὶ μίσει χρώμενον πρὸς τὰ μετʼ ἀδικίας ἐξαγόμενα· καὶ γὰρ ἔχει τι θυμοειδὲς ἐν τῇ διανοίᾳ καὶ ἐλευθέριον, ὑφʼ οὗ μηδὲ στέγειν προστίθεσθαι τῶν βουλευμάτων· πολλοῖς γοῦν ἀνεκοινώσατο καὶ φίλοις καὶ ἄλλοις δοκοῦσιν αὐτῷ δραστηρίοις."},{"number":20,"text":"Μινουκιανὸς δὲ τὰ μὲν Λεπίδου τε ἐκδικία, φίλον γὰρ αὐτῷ τὰ μάλιστα ὄντα τοῦτον καὶ τῶν πολιτῶν σὺν ὀλίγοις ἀναιρεῖ Γάιος, καὶ ἄλλως φοβηθεὶς τὰ περὶ αὐτὸν διὰ τὸ πᾶσιν ὁμοίως τὸν Γάιον ἐπὶ θάνατον ἀνακειμένην ἐπαφιέναι τὴν ὀργὴν ἐπὶ τὴν ἐγχείρησιν ἐλθεῖν."},{"number":21,"text":"Χαιρέαν δὲ αἰσχύνην φέροντα ὀνείδη τε εἰς τὴν ἀνανδρίαν ὑπὸ τοῦ Γαΐου προφερομένου, καὶ ἄλλως τὸ ἐφʼ ἡμέρᾳ κινδυνεύειν φιλίᾳ καὶ θεραπείᾳ τὴν Γαΐου τελευτὴν οὐ πάντʼ ἐλεύθερον ὑπολαμβάνων."},{"number":22,"text":"οἱ δὲ καὶ πᾶσι κοινῇ προτεθῆναι τὴν ἐπὶ τῷ πράγματι σκέψιν τήν τε ὕβριν θεωμένοις καὶ ἐπιθυμοῦσιν ἀκμὴν ἐπʼ ἀλλήλων ἀκμάζουσαν διαφυγεῖν ἀραμένοις τὸν Γάιον· ἴσως μὲν γὰρ ἂν κατορθῶσαι, καλῶς δὲ κατορθοῦσι τηλικούτων ἀγαθῶν σχεῖν ἐπὶ σωτηρίᾳ τῆς τε πόλεως καὶ τῆς ἡγεμονίας πονοῦσι καὶ μετὰ ὀλέθρου ἅπτεσθαι τοῦ πράγματος."},{"number":23,"text":"παρὰ πάντα δὲ Χαιρέαν ἐπείγεσθαι ὀνόματός τε ἐπιθυμίᾳ μείζονος καὶ ἄλλως ὑπὸ τοῦ ἀδεέστερον προσιέναι τῷ Γαΐῳ διὰ τὴν χιλιαρχίαν ῥᾳστώνης αὐτῷ κτείνειν ἐσομένης."},{"number":24,"text":"Ἐν τούτῳ δʼ ἱπποδρομίαι ἦσαν· καὶ σπουδάζεται γὰρ Ῥωμαίοις ἥδε ἡ θεωρία δεινῶς, συνίασίν τε προθύμως εἰς τὸν ἱππόδρομον καὶ ἐφʼ οἷς χρῄζοιεν δέονται τῶν αὐτοκρατόρων κατὰ πλῆθος συνελθόντες, οἱ δὲ ἀναντιλέκτους τὰς δεήσεις κρίνοντες οὐδαμῶς ἀχαριστοῦσιν."},{"number":25,"text":"ἐκέλευον δὴ καὶ τὸν Γάιον ἐκθύμῳ τῇ ἱκετείᾳ χρώμενοι τῶν τε τελῶν ἐπανιέναι καὶ τῶν φόρων ἐπικουφίζειν τι τοῦ ἐπαχθοῦς. ὁ δʼ οὐκ ἠνείχετο, καὶ πλέον τι τῇ βοῇ χρωμένων ἄλλους ἄλλῃ διαπέμψας κελεύει τοὺς βοῶντας λαβεῖν τε καὶ μηδὲν εἰς ἀναβολὰς ἀνελεῖν προαγαγόντας."},{"number":26,"text":"καὶ ὁ μὲν ἐκέλευε ταῦτα καὶ οἷς προσετέτακτο ἔπρασσον, πλεῖστοί τε ἦσαν οἱ ἐπὶ τοιούτοις ἀποθανόντες. καὶ ὁ δῆμος ἑώρα μέν, ἠνείχετο δὲ παυσάμενος τῆς βοῆς, ἐν ὀλίγῳ ἕνεκα τῶν χρημάτων ὀφθαλμοῖς ὁρῶντες τὴν ἐπὶ τοιούτοις παραίτησιν εἰς θάνατον αὐτοῖς φέρουσαν."},{"number":27,"text":"ταῦτα Χαιρέαν ἐνήγαγεν μειζόνως ἅπτεσθαί τε τῆς ἐπιβουλῆς καὶ παύειν κατὰ τῶν ἀνθρώπων ἐξηγριωκότα τὸν Γάιον, καὶ πολλάκις μὲν καὶ παρὰ τὰς ἑστιάσεις ἐμέλλησεν ἐπιχειρεῖν, οὐ μὴν ἀλλʼ ἐπείχετο λογισμῷ, τὸ μὲν κτείνειν οὐκέτʼ ἐνδοιαστὸν κεκρικώς, τὸν δὲ καιρὸν περισκοπῶν, ὅπως μὴ εἰς κενόν, ἀλλʼ ἐπὶ καταπράξει τῶν βεβουλευμένων ταῖς χερσὶ χρῷτο."},{"number":28,"text":"Ἐστρατεύετο δὲ πολὺν ἤδη χρόνον οὐχ ἡδονῇ φέρων Γαΐου τὴν ἀναστροφήν. ἐπεὶ δὲ αὐτὸν ἵσταται Γάιος εἰσπραξόμενον τούς τε φόρους καὶ ὅσα ἄλλα καταβαλλόμενα εἰς τὸν Καίσαρος θησαυρὸν ἐφυστερήκει τοῖς καιροῖς διὰ τὸ ἐπιδιπλασιάζεσθαι τὴν δύναμιν αὐτῶν, χρόνον ἐκεῖ ποιεῖται τῇ εἰσπράξει τρόπῳ τῷ αὐτοῦ χρώμενος μᾶλλον ἢ τῇ Γαΐου προστάξει,"},{"number":29,"text":"διὰ τὸ φειδοῖ χρῆσθαι τὰς τύχας οἴκτῳ λαμβάνων τῶν ὑπὸ τὴν εἴσπραξιν εἰς ὀργὴν προυκαλεῖτο τὸν Γάιον μαλακίαν ἐπικαλοῦντα αὐτῷ τοῦ σχολῇ συνάγεσθαι αὐτῷ τὰ χρήματα. καὶ δὴ τά τε ἄλλα ὕβριζεν εἰς αὐτὸν καὶ ὁπότε τὸ σημεῖον αὐτῷ τὸ τῆς ἡμέρας καθηκούσης εἰς αὐτόν, θήλεά τε ἐδίδου τὰ ὀνόματα,"},{"number":30,"text":"καὶ ταῦτα αἰσχύνης ἀνάπλεα καὶ ταῦτα ἔπρασσεν αὐτὸς οὐκ ἀπηλλαγμένος ἔν τινων τελεταῖς μυστηρίων, ἃς αὐτὸς συνίστατο, στολάς τε ἐνδυόμενος γυναικείους καί τινων περιθέσεις πλοκαμίδων ἐπινοῶν ἄλλα τε ὁπόσα ἐπικαταψεύσασθαι θηλύτητα τῆς ὄψεως ἔμελλεν, αὐτὸς τὴν ἐπὶ τοιούτοις αἰσχύνην ἐτόλμα Χαιρέᾳ προσκαλεῖν."},{"number":31,"text":"Χαιρέᾳ δὲ καὶ ὁπότε μὲν παραλαμβάνοι τὸ σημεῖον ὀργὴ παρίστατο, μειζόνως δʼ ὁπότε παραδιδοίη, γελώμενος ὑπὸ τῶν παραλαμβανόντων, ὥστε καὶ οἱ συγχιλίαρχοι παιδιὰν ἐποιοῦντο αὐτόν· ὁπότε γὰρ αὐτὸς μέλλοι τὸ σημεῖον παρʼ αὐτοῦ Καίσαρος κομίζειν, προύλεγόν τινα τῶν εἰωθότων φέρειν εἰς παιδιάν."},{"number":32,"text":"διὰ ταῦτα δὲ αὐτῷ καὶ θάρσος παρίστατο κοινωνούς τινας παραλαμβάνειν, ὡς οὐκ ἐπʼ ὀλίγοις ὀργῇ χρώμενος. καὶ ἦν γὰρ Πομπήδιος συγκλητικὸς μέν, τὰς ἀρχὰς δὲ διεληλυθὼς σχεδὸν ἁπάσας, Ἐπικούρειος δʼ ἄλλως καὶ διʼ αὐτὸ ἀπράγμονος ἐπιτηδευτὴς βίου."},{"number":33,"text":"τοῦτον ἐνδείκνυσιν Τιμίδιος ἐχθρὸς ὢν ὡς λοιδορίᾳ χρησάμενον ἀπρεπεῖ κατὰ τοῦ Γαΐου μάρτυρα παραλαμβάνων Κυιντιλίαν γυναῖκα τῶν ἐπὶ τῆς σκηνῆς ἐπιφανείᾳ τοῦ ὡραίου περισπούδαστον πολλοῖς τε οὖσαν καὶ τῷ Πομπηδίῳ."},{"number":34,"text":"καὶ τῆς ἀνθρώπου, ψεῦδος γὰρ ἦν, δεινὸν ἡγουμένης μαρτυρίαν ἐπὶ θανάτῳ τοῦ ἐραστοῦ παρασχεῖν, βασάνων ἔχρῃζεν ὁ Τιμίδιος, καὶ Γάιος παρωξυμμένος κελεύει τὸν Χαιρέαν μηδὲν εἰς ἀναβολὰς ἀλλʼ εὐθέως βασανίζειν τὴν Κυιντιλίαν, χρώμενος τῷ Χαιρέᾳ πρός τε τὰ φονικὰ καὶ ὁπόσα στρεβλώσεως δέοιτο ὑπὸ τοῦ νομίζειν ὠμότερον διακονήσεσθαι τὴν λοιδορίαν φεύγοντα τῆς μαλακίας."},{"number":35,"text":"Κυιντιλία δʼ ἐπὶ τὴν βάσανον ἀγομένη τῶν συνιστόρων τινὸς ἐπιβαίνει τῷ ποδὶ ἀποσημαίνουσα θαρσεῖν καὶ μὴ τὰς βασάνους αὐτῆς δεδιέναι· διοίσειν γὰρ μετʼ ἀνδραγαθίας. βασανίζει δʼ αὐτὴν ὠμῶς ὁ Χαιρέας, ἄκων μέν, κατʼ ἀνάγκας δὲ τὰς ὑπὲρ αὐτοῦ, καὶ μηδὲν ἐνδοῦσαν ἦγεν εἰς τὴν ὄψιν τὴν Γαΐου διακειμένην οὐκ ἐν ἡδονῇ τοῖς θεωροῦσι."},{"number":36,"text":"καὶ ὁ Γάιος παθών τι πρὸς τὴν ὄψιν τῆς Κυιντιλίας δεινῶς ὑπὸ τῶν ἀλγηδόνων διακειμένης τοῦ τε ἐγκλήματος ἠφίει καὶ αὐτὴν καὶ τὸν Πομπήδιον, ἐκείνην δὲ καὶ χρημάτων δόσει τιμᾷ παραμυθίας ἐσομένων λώβης τε ἣν ἐλελώβητο εἰς τὴν εὐπρέπειαν τοῦ ἀφορήτου τῶν ἀλγηδόνων."},{"number":37,"text":"Ταῦτα δεινῶς ἠνίασεν τὸν Χαιρέαν ὡς αἴτιον ἀνθρώποις καὶ ὑπὸ Γαΐου παρηγορίας ἀξίοις ἐν αἰτίᾳ κακῶν τὸ ὅσον ἐπʼ αὐτοῖς γεγενημένοις, φησίν τε πρὸς Κλήμεντά τε καὶ Παπίνιον, ὧν Κλήμης μὲν ἦν ἐπὶ τῶν στρατοπέδων, Παπίνιος δὲ καὶ αὐτὸς ἦν χιλιαρχῶν,"},{"number":38,"text":"ἀλλʼ ἐπὶ φυλακῇ γε, ὦ Κλήμης, τὰ πάντα τοῦ αὐτοκράτορος ἡμῖν πράσσειν οὐκ ἐλλέλειπται· τῶν γὰρ συνομωμοκότων αὐτοῦ κατὰ τῆς ἡγεμονίας προνοίᾳ καὶ πόνοις τοὺς μὲν ἀπεκτείναμεν, τοὺς δὲ ἐστρεβλώσαμεν ἐπὶ τοσοῦτον, ὡς ἐλεεινοὺς κἀκείνῳ γενέσθαι, μετὰ πόσης τε ἀρετῆς ἡμῖν ἐξάγεται τῶν στρατιῶν;"},{"number":39,"text":"σιγήσαντος δὲ τοῦ Κλήμεντος καὶ τὸ μὲν αἰσχύνῃ φέρειν τὰ προστασσόμενα καὶ τῷ βλέμματι καὶ τῷ ἐρυθήματι παριστάντος, λόγῳ δὲ αὐτοῖς τὴν μανίαν τοῦ αὐτοκράτορος προσκαλεῖν ἄδικον ἡγουμένου προνοίᾳ τοῦ ἀσφαλοῦς,"},{"number":40,"text":"Χαιρέας ἤδη θάρσει χρώμενος ἐν λόγοις ἦν κινδύνων ἀνειμένοις πρὸς αὐτὸν τὰ κατέχοντα δεινὰ τὴν πόλιν καὶ τὴν ἀρχὴν ἐπεξιών, καὶ ὅτι λόγῳ μὲν εἴη Γάιος ὁ τὴν ἐπὶ τοιούτοις αἰτίαν προτιθέμενος,"},{"number":41,"text":"τοῖς δὲ τἀληθὲς ἐξετάζειν πειρωμένοις ἐγώ τε, ὦ Κλήμης, καὶ οὑτοσὶ ὁ Παπίνιος καὶ πρὸ ἡμῶν σύ, ταύτας Ῥωμαίοις τε καὶ τῷ παντὶ ἀνθρωπείῳ τὰς στρέβλας προσφερόμενοι, οὐκ ἐπιτάγμασιν τοῖς Γαΐου διακονούμενοι, γνώμῃ δὲ τῇ αὐτῶν,"},{"number":42,"text":"εἰ παρὸν παῦσαι τοσαύτῃ ἤδη χρώμενον ὕβρει εἴς τε τοὺς πολίτας καὶ τοὺς ὑπηκόους διακονούμεθα, δορυφόροι καὶ δήμιοι καθεστηκότες ἀντὶ στρατιωτῶν καὶ τὰ ὅπλα ταυτὶ φέροντες οὐχ ὑπὲρ ἐλευθερίας οὐδʼ ἀρχῆς τῶν Ῥωμαίων, ἀλλʼ ἐπὶ σωτηρίᾳ τοῦ δουλουμένου τά τε σώματα αὐτῶν καὶ τὰ φρονήματα, μιαινόμενοι τῷ καθʼ ἡμέραν αἵματι σφαγῆς καὶ βασάνου τῆς ἐκείνων, μέχρι δή τις καὶ καθʼ ἡμῶν διακονήσεται τοιαῦτα Γαΐῳ."},{"number":43,"text":"οὐ γὰρ εὐνοίᾳ γε πολιτεύσει διὰ τάδε πρὸς ἡμᾶς, διʼ ὑφοράσεως δὲ μᾶλλον καὶ ἄλλως τοῦ πολλοῦ τῶν ἀπολλυμένων ἀποδεδωκότος· οὐ γὰρ δὴ στήσεταί ποτε Γαΐῳ τὰ τῆς ὀργῆς διὰ τὸ μὴ δίκην ἀλλʼ ἡδονὴν πέρας αὐτῆς τυγχάνειν· σκοποὶ δὲ προσκεισόμεθα καὐτοί, δέον καὶ τοῖς πᾶσιν τὸ ἀνεπιβούλευτόν τε καὶ ἐλεύθερον βεβαιοῦν καὶ ἡμῖν κινδύνων ἀπαλλαγὰς ψηφίσασθαι."},{"number":44,"text":"Κλήμης δὲ τὴν μὲν διάνοιαν τὴν Χαιρέου φανερὸς ἦν ἐπαινῶν, σιγᾶν δʼ ἐκέλευε, μὴ καὶ φοιτῶντος εἰς πλείονας τοῦ λόγου καὶ διαχεομένων ὁπόσα κρύπτεσθαι καλῶς ἔχοι πρὶν τυχεῖν πράξαντας ἐκπύστου τοῦ ἐπιβουλεύματος γενομένου κολασθεῖεν, χρόνῳ δὲ τῷ αὖθις καὶ τῇ ἀπʼ αὐτοῦ ἐλπίδι παραδιδόναι τὰ πάντα ὡς παραγενησομένης τινὸς αὐτοῖς ἐπικουρίας τυχαίου·"},{"number":45,"text":"αὐτὸν μὲν γὰρ ὑπὸ γήρως ἀφῃρῆσθαι τὴν ἐπὶ τοιοῖσδε τόλμαν, τῶν μέντοι γε ὑπὸ σοῦ, Χαιρέα, συντεθέντων τε καὶ ῥηθέντων ἀσφαλέστερα μὲν ἴσως ἂν ὑποθοίμην, εὐπρεπέστερα δὲ πῶς ἄν τις καὶ δύναιτο;"},{"number":46,"text":"καὶ Κλήμης μὲν ὡς αὑτὸν ἀναλύει διὰ λογισμῶν τῶν τε ἀκροαθέντων καὶ ὁπόσων αὐτὸς εἰρήκει περιφερόμενος. Χαιρέας δὲ δείσας ὡς Κορνήλιον Σαβῖνον ἠπείγετο καὶ αὐτὸν μὲν χιλίαρχον ὄντα, ἀξιόλογον δʼ ἄλλως ἐξεπιστάμενος αὐτὸν καὶ τοῦ ἐλευθέρου ἐραστὴν καὶ διʼ αὐτὸ τῇ καταστάσει τῶν πραγμάτων πολεμίως διακείμενον,"},{"number":47,"text":"χρῄζων ἐκ τοῦ ὀξέος ἔχεσθαι τῶν ἐγνωσμένων τῆς ἐγχειρήσεως ὑπʼ αὐτοῦ καλὰ νομίσας εἶναι προσθέσθαι καὶ δέει, μὴ ὑπὸ Κλήμεντος ἐκφοίτησις γένοιτο αὐτῶν, ἄλλως τε τὰς μελλήσεις καὶ τῶν καιρῶν τὰς ὑπερβολὰς πρὸς τῶν ὑπερβαλλομένων τιθέμενος."},{"number":48,"text":"Ἐπεὶ δὲ ἀσμένῳ καὶ τῷ Σαβίνῳ τὰ πάντα ἦν, ἅτε καὶ αὐτῷ γνώμης μὲν οὐχ ὑστεροῦντι τῆς ἴσης, ἀπορίᾳ δὲ πρὸς ὅντινα εἰπὼν ἀσφαλὴς εἴη τὰ πρὸς ἐκείνους σιγῇ παραδιδόντος, ἐπεί τε ἀνδρὸς ηὐπόρητο οὐ μόνον στέγειν ὧν πύθοιτο προσθησομένου, ἀλλὰ καὶ γνώμην φανεροῦντος τὴν αὐτοῦ, πολλῷ μᾶλλον ἦρτο, καὶ μηδὲν εἰς ἀναβολὰς ἐδεῖτο τοῦ Χαιρέου."},{"number":49,"text":"τρέπονταί τε ὡς Μινουκιανόν, αὐτοῖς μὲν ἐπιτηδεύσει ἀρετῆς καὶ τῷ ὁμοζήλῳ τοῦ μεγαλόφρονος συγγενῆ, Γαΐῳ δʼ ὕποπτον τῆς Λεπίδου τελευτῆς, πάνυ γὰρ δὴ φίλοι ἐγένοντο Μινουκιανός τε καὶ Λέπιδος, καὶ δείματι κινδύνων τῶν καθʼ αὑτόν."},{"number":50,"text":"πᾶσι γὰρ τοῖς ἐν τέλει φοβερὸς ἦν Γάιος, ὡς ἐπʼ αὐτὸν ἕκαστον καὶ πρὸς οὕστινας τῇ μανίᾳ χρῆσθαι μὴ ἀφησόμενος,"},{"number":51,"text":"φανεροί τε ἀλλήλοις ἦσαν τῆς ἐπὶ πράγμασιν ἀχθηδόνος, διασαφεῖν μὲν ἀλλήλοις ἄντικρυς τὴν διάνοιαν καὶ μῖσος τὸ πρὸς Γάιον φόβῳ τε κινδύνων ἀφέμενοι ἄλλως τε αἰσθανόμενοι τοῦ ἀλλήλων μίσους πρὸς τὸν Γάιον καὶ διʼ αὐτὸ εὐνοίᾳ χρῆσθαι τὰ πρὸς ἀλλήλους μὴ ἀπηλλαγμένοι."},{"number":52,"text":"Γενομένων δʼ αὐτοῖς ἀξιώσεων ἐπείπερ συνέβαλον, εἰωθότες καὶ πρότερον ὁπότε συνέλθοιεν τίμιον ἡγεῖσθαι τὸν Μινουκιανὸν ὑπεροχῇ τε ἀξιώματος, γενναιότατος γὰρ ἦν τῶν πολιτῶν, καὶ τῷ ἐπὶ πᾶσιν ἐπαινουμένῳ,"},{"number":53,"text":"μᾶλλον ὡς ἅπτοιτό τινος λόγου φθάσαι κἀκεῖνος εἴ ποτε Χαιρέαν, ὅ τι καὶ παραλάβοι σημεῖον τῆς ἡμέρας ἐκείνης· ἀοίδιμος γὰρ διὰ τῆς πόλεως ἦν ἡ εἰς τὸν Χαιρέαν διὰ τῶν σημείων τῆς δόσεως πρασσομένη ὕβρις."},{"number":54,"text":"ὁ δὲ χάρματι τοῦ λόγου μηδὲν μελλήσας ἠμείβετο τοῦ Μινουκιανοῦ τὸ ἐπὶ τοιοῖσδε πιστεῦσαν ὁμιλίᾳ χρήσασθαι πρὸς αὐτόν, καί σύ μοι δίδως, εἶπεν, σημεῖον ἐλευθερίας, χάρις δέ σοι τοῦ ἀνεγείραντός με μειζόνως ἤπερ εἴωθα ἐμαυτὸν ὁρμᾶν,"},{"number":55,"text":"οὐδέν μοι χρεία πλειόνων ἔτι λόγων, οἵ με θαρσοῖεν, εἰ δὴ καὶ σοὶ ταῦτα δοκεῖ, γνώμης τε τῆς αὐτῆς κοινωνοὶ καὶ πρότερον ἢ συνελθεῖν γεγόναμεν. καὶ ἓν μὲν ὑπέζωμαι ξίφος, ἀμφοῖν δʼ ἂν ἀρκέσειεν."},{"number":56,"text":"ὥστε ἴθι καὶ ἔργων ἐχώμεθα, ἡγεμών τʼ ἴσθι, ᾗ βούλοιο αὐτὸς κελεύων με χωρεῖν, ᾗ καὶ προσοίσομαι, ἐπικουρίᾳ τῇ σῇ συμπράσσοντος τε πίσυνος. οὐδὲ ἀπορία σιδήρου τοῖς τὴν ψυχὴν εἰς τὰ ἔργα προσφερομένοις, διʼ ἣν καὶ ὁ σίδηρος δραστήριος εἴωθεν εἶναι."},{"number":57,"text":"ὥρμηκά τε εἰς τὴν πρᾶξιν οὐχ ὧν ἂν αὐτὸς πάθοιμι ἐλπίδι περιφερόμενος· οὐ γὰρ σχολὴ κινδύνους μοι κατανοεῖν τοὺς ἐμαυτοῦ δουλώσει τε πατρίδος ἐλευθερωτάτης ἐπαλγοῦντι τῶν νόμων τῆς ἀρετῆς ἀφῃρημένης τούς τε πάντας ἀνθρώπους ὀλέθρου διὰ Γάιον κατειληφότος."},{"number":58,"text":"ἄξιος δʼ ἂν εἴην παρὰ σοὶ δικαστῇ πίστεως ἐπὶ τοιούτοις τυγχάνειν ὑπὸ τοῦ ὅμοια φρονεῖν αὐτοῖς καὶ σὲ μὴ ἀπηλλάχθαι."},{"number":59,"text":"Μινουκιανὸς δὲ τὴν ὁρμὴν τῶν λόγων θεασάμενος ἠσπάζετό τε ἀσμένως καὶ προσπαρίστατο τὴν τόλμαν αὐτοῦ ἐπαινέσας τε καὶ ἀσπασάμενος μετʼ εὐχῶν καὶ ἱκετείας ἀπελύοντο."},{"number":60,"text":"καὶ ἰσχυρίζοντό τινες ὡς βεβαιοῦν τὰ εἰρημένα εἰσιόντος γὰρ εἰς τὸ βουλευτήριον Χαιρέου φωνὴν ἐκ τοῦ πλήθους γενέσθαι τινὸς ἐπʼ ἐξορμήσει κελεύοντος περαίνειν μὲν δὴ τὸ πρακτέον καὶ προσλαμβάνειν τὸ δαιμόνιον."},{"number":61,"text":"καὶ τὸν Χαιρέαν τὸ μὲν πρῶτον ὑπιδέσθαι, μὴ καί τινος τῶν συνωμοτῶν προδότου γεγονότος ἁλίσκοιτο, καὶ τέλος συνέντα ἐπὶ προτροπῇ φέρειν πρῶτον εἴτε παραινέσει τῶν συνεγνωκότων ἀντισημαίνοντός τινος, εἴτε δὴ καὶ τοῦ θεοῦ, ὃς ἐφορᾷ τὰ ἀνθρώπινα, αἴροντος αὐτόν."},{"number":62,"text":"διεληλύθει δὲ διὰ πολλῶν τὸ ἐπιβούλευμα καὶ πάντες ἐν ὅπλοις παρῆσαν, οἱ μὲν τῶν βουλευτῶν ὄντες οἱ δὲ ἱππεῖς καὶ ὁπόσοι τοῦ στρατιωτικοῦ συνῄδεσαν· οὐδεὶς γὰρ ἦν, ὃς μὴ ἐν εὐδαιμονίᾳ ἂν ἠρίθμει τὴν Γαΐου μετάστασιν·"},{"number":63,"text":"καὶ διʼ αὐτὸ πάντες ἠπείγοντο ὁποίῳ δύναιτό τις τρόπῳ μηδὲ ἑκὼν εἶναι τῆς ἐπὶ τοιούτοις ἀρετῆς ὑστερεῖν, ἀλλʼ ὡς ἔχοι προθυμίας ἢ δυνάμεως καὶ λόγοις καὶ διʼ ἔργων ἦρτο ἐπὶ τῇ τυραννοκτονίᾳ,"},{"number":64,"text":"ἐπεὶ καὶ Κάλλιστος, ἀπελεύθερος δʼ ἦν Γαΐου πλεῖστά τε ἀνὴρ εἷς οὗτος ἐπὶ μέγιστον δυνάμεως ἀφίκετο καὶ οὐδὲν ἄλλο ἢ ἰσοτύραννον εἶχε τὴν δύναμιν φόβῳ τε τῶν πάντων καὶ μεγέθει χρημάτων, ἅπερ ἐγένετο αὐτῷ·"},{"number":65,"text":"δωροδοκώτατος γὰρ ἦν καὶ ὑβριστότατος παρʼ ὁντινοῦν γίνεται, ἐξουσίᾳ χρησάμενος παρὰ τὸ εἰκός· καὶ ἄλλως τε τοῦ Γαΐου τὴν φύσιν ἐξεπιστάμενος ἀνήκεστον οὖσαν καὶ ἐφʼ οἷστισι κρίνειεν οὐδαμῶς ἀντισπάσματι χρωμένην, αὐτῷ τε πολλὰς μὲν καὶ ἄλλας αἰτίας τοῦ κινδυνεύειν, οὐχ ἥκιστα δὲ τὸ μέγεθος τῶν χρημάτων·"},{"number":66,"text":"ὥστε δὴ καὶ Κλαύδιον ἐθεράπευε κρυπτῶς μετακαθίζων πρὸς αὐτὸν ἐλπίδι τοῦ κἂν εἰς ἐκεῖνον ἥξειν τὴν ἡγεμονίαν Γαΐου μεταστάντος, αὐτῷ τὴν ὑπόθεσιν τῆς τιμῆς τὴν ἐφʼ ὁμοίοις ἰσχὺν προκαταθέμενος χάριν καὶ φιλανθρωπίας λόγον."},{"number":67,"text":"ἐτόλμησεν γοῦν εἰπεῖν, ὡς κελευσθεὶς διαχρήσασθαι φαρμάκῳ τὸν Κλαύδιον μυρίας εὕροιτο τοῦ χρήματος τὰς ὑπερβολάς."},{"number":68,"text":"δοκεῖν δὲ προσεποιεῖτο Κάλλιστος ἐπὶ θήρᾳ τῇ Κλαυδίου τὸν λόγον τοῦτον, ἔπειτα οὔτε Γάιος ὡρμηκὼς μεταχειρίσασθαι Κλαύδιον ἠνείχετο τῶν Καλλίστου προφάσεων οὔτε Κάλλιστος κελευσθείς που τὴν πρᾶξιν εὐκτὸν ὑπελάμβανεν ἢ κακουργῶν εἰς τοῦ δεσπότου τὰς ἐπιστολὰς οὐκ ἂν ἐκ τοῦ παραχρῆμα τὸν μισθὸν ἐκομίζετο."},{"number":69,"text":"ἀλλὰ δὴ Κλαυδίῳ μὲν ἔκ τινος θείας δυνάμεως χρήσασθαι μανιῶν τῶν Γαΐου, Κάλλιστος προσποιήσασθαι χάριτος κατάθεσιν μηδαμῶς ὑπʼ αὐτοῦ γενομένης."},{"number":70,"text":"Τοῖς ἀμφὶ τὸν Χαιρέαν ὑπερβολαὶ τὸ καθʼ ἡμέραν ἦσαν ὀκνούντων πολλῶν οὐ γὰρ Χαιρέας ἔσται ἑκὼν εἶναι τοῦ πράσσειν ἀναβολὴν ἐποιεῖτο, πάντα καιρὸν ἐπιτήδειον τῇ πράξει νομίζων."},{"number":71,"text":"καὶ γὰρ εἰς τὸ Καπετώλιον ἀνιόντα καὶ τὰς θυσίας ὑπὲρ τῆς θυγατρὸς ἐπιτελουμένας ὑπὸ τοῦ Γαΐου παρῆν πολλάκις καιρός, καὶ ὑπὲρ τῆς βασιλικῆς ἱστάμενον καὶ τῷ δήμῳ χρυσίου καὶ ἀργυρίου χρήματα διαρριπτοῦντα ὦσαι κατὰ κεφαλῆς, ὑψηλὸν δʼ ἐστὶ τὸ τέγος εἰς τὴν ἀγορὰν φέρον, ἐπί τε τῶν μυστηρίων ταῖς ποιήσεσιν ἃ συνίστατο·"},{"number":72,"text":"πάντων γὰρ αὐτὸν ἀπερίοπτον εἶναι προνοίᾳ τοῦ ἐν αὐτοῖς εὐπρεπῶς ἀναστραφησομένου καὶ ἀπογνώσει τοῦ ἐν ἐπιχειρήσει τινὶ γενέσθαι πιστεύοντα εἰ δὲ μηδὲν τίμιον ὡς τῶν θεῶν αὐτῷ δύναμιν τοῦ θανάτου παρατυγχάνειν,"},{"number":73,"text":"αὐτῷ δʼ ἂν ἰσχὺν ἐγγενέσθαι καὶ μὴ σιδηροφορουμένῳ διαχρήσασθαι τότε Γάιον. οὕτως εὐχῆς εἶχε τοὺς συνωμότας ὁ Χαιρέας δεδιὼς τοὺς καιροὺς μὴ διαρρυεῖεν."},{"number":74,"text":"οἱ δὲ ἑώρων μὲν νομίμων τε χρῄζοντα καὶ ἐπʼ ἀγαθοῖς τοῖς αὐτῶν ἐπειγόμενον, οὐ μὴν ἀλλʼ ἠξίουν εἰς ὀλίγον γοῦν ὑπερβολῇ χρήσασθαι, μὴ καί πῃ σφάλματος τῇ ἐπιχειρήσει συνελθόντος ταράξαιεν τὴν πόλιν ζητήσεων τῶν συνεγνωκότων τὴν πρᾶξιν γινομένων καὶ τοῖς αὐτοῖς μελλήσουσιν ἐπιχειρεῖν ἄπορον τὴν ἀνδραγαθίαν φραξαμένου Γαΐου πρὸς αὐτοὺς μειζόνως."},{"number":75,"text":"καλῶς οὖν ἔχειν θεωριῶν ἐν τῷ Παλατίῳ ἐπιτελουμένων ἅπτεσθαι τοῦ χρήματος· ἄγονται δὲ ἐπὶ τιμῇ τοῦ πρώτου μεταστησαμένου τὴν ἀρχὴν τοῦ δήμου Καίσαρος εἰς αὐτὸν μικρόν τε πρὸ τοῦ βασιλείου καλύβης πηκτοῦ γενομένης, καὶ Ῥωμαίων τε οἱ εὐπατρίδαι θεωροῦσιν ὁμοῦ παισὶν καὶ γυναιξὶν καὶ ὁ Καῖσαρ·"},{"number":76,"text":"ῥᾳστώνην τε αὐτοῖς ἔσεσθαι πολλῶν μυριάδων ἀνθρώπων εἰς ὀλίγον χωρίον καθειργνυμένων ὥστε εἰσιόντι τὴν ἐπιχείρησιν ποιήσασθαι δυνάμεως τοῖς ὑπασπισταῖς, εἰ καί τινες προθυμοῖντο, μὴ παρατευξομένης αὐτῷ βοηθεῖν."},{"number":77,"text":"Εἴχετο δὲ Χαιρέας, καὶ τῶν θεωριῶν ἐπελθουσῶν τῇ πρώτῃ δεδογμένον ἅπτεσθαι τῆς πράξεως ἰσχυρότερον ἦν τοῦ κατʼ ἐκείνους προβεβουλευκότος τὸ τῆς τύχης συγχωροῦν ὑπερβολάς, καὶ τὰς τρεῖς ὑπερβαλλομένου ταῖς νομίμοις ἡμέραις μόλις κατὰ τὴν τελευταίαν αὐτοῖς ἐπράχθη τὸ ἔργον."},{"number":78,"text":"Χαιρέας δὲ συγκαλέσας τοὺς συνωμότας πολὺς μέν, εἶπεν, καὶ ὁ παρεληλυθὼς χρόνος ὀνειδίσαι τὸ ἐπιμέλλον ἡμῶν ἐπὶ τοῖς οὕτω βουλευθεῖσιν μετʼ ἀρετῆς, δεινὸν δέ, εἰ καὶ μηνύματος γενομένου διαπεσεῖται ἡ πρᾶξις καὶ Γάιος ὑβριεῖ μειζόνως."},{"number":79,"text":"ἢ οὐχ ὁρῶμεν, ὡς τῆς ἐλευθερίας ἀφαιροῦμεν ὁπόσας τῶν ἡμερῶν προσθήκην τῇ Γαΐου τυραννίδι χαριζόμεθα, δέον αὐτούς τʼ ἀδεεῖς τὸ λοιπὸν εἶναι καὶ τοῖς ἄλλοις αἰτίαν τοῦ εὐδαίμονος παρασχόντας διʼ αἰῶνος τοῦ ἅπαντος τοῖς αὖθις ἐν θαύματι μεγάλῳ καὶ τιμῇ καταστῆναι;"},{"number":80,"text":"τῶν δὲ οὔτε ἀντειπεῖν ὡς οὐ πάνυ καλοῖς δυναμένων οὔτε τὴν πρᾶξιν ἄντικρυς δεχομένων σιγῇ δὲ καταπεπληγότων τί, φησίν, ὦ γενναῖοι, διαμέλλομεν; ἢ οὐχ ὁρᾶτε τὴν σήμερον τῶν θεωριῶν ἡμέραν ὑστάτην οὖσαν καὶ Γάιον ἐκπλευσούμενον;"},{"number":81,"text":"ἐπὶ γὰρ Ἀλεξανδρείας παρεσκεύαστο πλεῖν κατὰ θεωρίαν τῆς Αἰγύπτου. καλὸν δὲ ἡμῖν προέσθαι τῶν χειρῶν τὸ ὄνειδος τῇ Ῥωμαίων μεγαλαυχίᾳ πομπεῦσον διά τε γῆς καὶ θαλάσσης."},{"number":82,"text":"πῶς δʼ οὐκ ἂν δικαίως κρίνοιμεν αὐτοὺς αἰσχύνῃ τῶν γενησομένων, εἴ τις αὐτὸν Αἰγύπτιος κτείνειεν τὴν ὕβριν οὐχ ἡγησάμενος ἀνασχετὸν τοῖς ἐλευθέροις γεγονόσιν;"},{"number":83,"text":"ἐγὼ μὲν οὖν οὐκέτι εἰς πλείονα ἀνέξομαι τὰς σκήψεις ὑμῶν, χωρήσω δὲ τοῖς κινδύνοις ὁμοῦ σήμερον ἡδονῇ φέρων πᾶν ὅ τι καὶ γένοιτο ἐξ αὐτῶν, οὐδʼ ἂν ὑπερβαλλοίμην εἴπερ εἴη· τί γὰρ δὴ καὶ γένοιτʼ ἂν ἀνδρὶ φρόνημα ἔχοντι τούτου σχετλιώτερον, ἕτερον Γάιον ἀναιρεῖν ἐμοῦ ζῶντος ἐμὲ τὴν ἐπὶ τῷδε ἀρετὴν ἀφῃρημένον;"},{"number":84,"text":"Καὶ ὁ μὲν ταῦτα εἰπὼν αὐτός τε ὡρμήκει πράξων τὸ ἔργον καὶ τοῖς λοιποῖς ἐνεποίησε θάρσος πᾶσίν τε ἦν ἔρως ἅπτεσθαι τοῦ ἐγχειρήματος μηδὲν ὑπερβαλλομένοις,"},{"number":85,"text":"ἕωθέν τε ἐπὶ τοῦ Παλατίου εἰώθει τὸ ξίφος ὑπεζωσμένος τῶν ἱππικῶν· ἔθος γὰρ δὴ τοῖς χιλιάρχοις τοῦτο ἐζωσμένοις αἰτεῖν παρὰ τοῦ αὐτοκράτορος τὸ σημεῖον, ἦν τε ἡ ἡμέρα καθήκουσα εἰς αὐτὸν τῆς παραλήψεως τοῦ σημείου."},{"number":86,"text":"ἄρτι τε συνῄει πληθὺς εἰς τὸ Παλάτιον ἐπὶ προκαταλήψει θέας πολλῷ θορύβῳ καὶ ὠθισμῷ, χαρᾷ φέροντος Γαΐου τὴν ἐπὶ τοιοῖσδε τῶν πολλῶν σπουδήν, παρὸ καὶ διακέκριτο οὐδὲν οὔτε τῇ συγκλήτῳ χωρίον οὔτε τοῖς ἱππεῦσιν, φύρδην δὲ ἕζοντο καὶ τοῖς ἀνδράσιν ὁμοῦ αἱ γυναῖκες καὶ τῷ δούλῳ ἀναμεμιγμένον τὸ ἐλεύθερον."},{"number":87,"text":"Γάιος δὲ προόδων αὐτῷ γενομένων ἔθυσε τῷ Σεβαστῷ Καίσαρι, ᾧ δὴ καὶ τὰ τῆς θεωρίας ἤγετο, καὶ πίπτοντος τῶν ἱερείων τινὸς συνέβη αἵματι τὴν Ἀσπρήνα στολὴν ἑνὸς τῶν συγκλητικῶν ἀνάπλεων γενέσθαι. τοῦτο Γαΐῳ γέλωτα μὲν παρέσχεν, ἦν δʼ ἄρα εἰς οἰωνὸν τῷ Ἀσπρήνᾳ φανερόν· ἐπικατασφάζεται γὰρ τῷ Γαΐῳ."},{"number":88,"text":"Γάιον δʼ ἱστορεῖται παρὰ φύσιν τὴν ἑαυτοῦ εὐπροσηγορώτατον γενέσθαι κατʼ ἐκείνην τὴν ἡμέραν καὶ δεξιότητι χρώμενον ὁμιλίας πάνθʼ ὁντινοῦν ἐκπλῆξαι τῶν παρατυγχανόντων."},{"number":89,"text":"μετὰ δὲ τὴν θυσίαν ἐπὶ τὴν θεωρίαν τραπεὶς ἐκαθέζετο καὶ περὶ αὐτὸν τῶν ἑταίρων οἱ ἀξιολογώτατοι."},{"number":90,"text":"κατεσκεύαστο δὲ τὸ θέατρον, πηκτὸν δὲ ἐγίνετο κατὰ ἕκαστον ἐνιαυτόν, τοιόνδε τρόπον· θύρας ἔχει δύο φερούσας τὴν μὲν εἰς αἴθριον, τὴν δʼ εἰς στοὰν εἰσόδοις καὶ ἀποχωρήσεσιν, ὅπως μὴ ταράσσοιντο οἱ ἔνδον ἀπειλημμένοι, ἐκ δʼ αὐτῆς τῆς καλύβης ἐνδοτέρω διαφράγμασιν ἑτέραν ἀπειληφυίαις ἐπʼ ἀναστροφῇ τοῖς ἀνταγωνισταῖς καὶ ὁπόσα ἀκροάματα."},{"number":91,"text":"συγκαθημένης δὲ τῆς πληθύος καὶ τοῦ Χαιρέου σὺν τοῖς χιλιάρχοις οὐκ ἄπωθεν τοῦ Γαΐου, δεξιὸν δὲ τοῦ θεάτρου κέρας ὁ Καῖσαρ εἶχεν, Βαθύβιός τις τῶν συγκλητικῶν ἀνὴρ ἐστρατηγηκὼς ἤρετο Κλούιον παρακαθεζόμενον αὐτῷ καὶ τοῦτον ὑπατικόν, εἰ δή τις αὐτῷ νεωτέρων πραγμάτων πέρι ἀφίκοιτο πύστις, προμηθὴς γενόμενος τοῦ μὴ ἐξάκουστος εἶναι τάδε λέγων."},{"number":92,"text":"τοῦ δὲ φαμένου μηδὲν πεπύσθαι σημεῖον τοιγαροῦν, ὦ Κλούιε, τυραννοκτονίας ἀγὼν πρόκειται. καὶ ὁ Κλούιος ὦ γενναῖε, φησίν, σίγα, μή τις τʼ ἄλλος Ἀχαιῶν μῦθον ἀκούσῃ."},{"number":93,"text":"πολλῆς δʼ ὀπώρας ἐπιχεομένης τοῖς θεωροῖς καὶ πολλῶν ὀρνέων ὁπόσα τῷ σπανίῳ τίμια τοῖς κτωμένοις, ὁ Γάιος ἡδονῇ τὰς περὶ αὐτοῖς ἐθεώρει μάχας καὶ διαρπαγὰς οἰκειουμένων αὐτὰ τῶν θεωρῶν."},{"number":94,"text":"ἔνθα δὲ καὶ σημεῖα μανθάνει δύο γενέσθαι· καὶ γὰρ μῖμος εἰσάγεται, καθʼ ὃν σταυροῦται ληφθεὶς ἡγεμών, ὅ τε ὀρχηστὴς δρᾶμα εἰσάγει Κινύραν, ἐν ᾧ αὐτός τε ἐκτείνετο καὶ ἡ θυγάτηρ Μύρρα, αἷμά τε ἦν τεχνητὸν πολὺ καὶ περὶ τὸν σταυρωθέντα ἐκκεχυμένον καὶ τῶν περὶ τὸν Κινύραν."},{"number":95,"text":"ὁμολογεῖται δὲ καὶ τὴν ἡμέραν ἐκείνην γενέσθαι, ἐν ᾗ Φίλιππον τὸν Ἀμύντου Μακεδόνων βασιλέα κτείνει Παυσανίας εἷς τῶν ἑταίρων εἰς τὸ θέατρον εἰσιόντα."},{"number":96,"text":"Γαΐου δʼ ἐνδοιάζοντος, εἴτε παραμείνειεν εἰς τέλος τῇ θεωρίᾳ διὰ τὸ τελευταίαν εἶναι τὴν ἡμέραν εἴτε λουτρῷ χρησάμενος καὶ σίτῳ εἶτα ἐπανίοι καθὰ καὶ οἱ πρότερον, Μινουκιανὸς ὑπὲρ τοῦ Γαΐου καθεζόμενος καὶ δεδιώς, μὴ διαλυθείη τὰ τῶν καιρῶν εἰς κενόν, ἐξαναστὰς ἐπειδὴ καὶ Χαιρέαν ἑώρα προεξεληλυθότα, ἠπείγετο θαρσύνειν αὐτὸν προελθών."},{"number":97,"text":"λαμβάνεται δʼ αὐτοῦ τῆς στολῆς Γάιος κατὰ φιλοφροσύνην δῆθεν καί ποῖ δή, φησίν, ὦ μακάριε; καὶ ὁ μὲν αἰδοῖ δοκεῖν τοῦ Καίσαρος καθίζει, κρείσσων δʼ ὁ φόβος ἦν ὀλίγον τε διαλιπὼν εἶτα διανίσταται."},{"number":98,"text":"καὶ ὁ Γάιος οὐδὲν ἐμποδὼν ἦν ἐξιόντι δοκῶν ἐπί τινι τῶν ἀναγκαίων ποιεῖσθαι τὴν ἔξοδον. Ἀμβρώνας δὲ καὶ αὐτὸς παρῄνει τῷ Γαΐῳ καθὸ πρότερον ὑπεξελθόντι πρός τε λουτρῷ καὶ ἀρίστῳ γενέσθαι καὶ ἔπειτα δὲ εἰσελθεῖν, χρῄζων ἐπὶ πέρας ἀχθῆναι τὰ ἐγνωσμένα."},{"number":99,"text":"Καὶ οἱ περὶ τὸν Χαιρέαν ἔτασσον μὲν ἀλλήλους ᾗ καιρός τε καὶ ἐχρῆν ἕκαστον στάντα ᾗ προσταχθείη μὴ ἀπολιμπάνεσθαι ἐπιπονοῦντες. ἤχθοντο δὲ τῇ διατριβῇ καὶ τῷ μέλλεσθαι τὰ ἐν χερσίν, ἐπεὶ καὶ περὶ ἐνάτην ὥραν ἤδη τὰ τῆς ἡμέρας ἦν."},{"number":100,"text":"καὶ Χαιρέας βραδύνοντος Γαΐου πρόθυμος ἦν ἐπεισελθεῖν ἐν τῇ καθέδρᾳ προσπεσὼν μέντοι προῄδει τοῦτο σὺν πολλῷ φόνῳ τῶν τε βουλευτῶν καὶ ὁπόσοι τῶν ἱππέων παρῆσαν καίπερ δεδιὼς πρόθυμος ἦν, καλῶς ἔχειν ἡγούμενος πᾶσιν ἀσφάλειαν καὶ ἐλευθερίαν ὠνούμενος ἐν ὀλίγῳ τίθεσθαι τὰ κατὰ τοὺς ἀπολουμένους."},{"number":101,"text":"καὶ δὴ τετραμμένων εἰς τὸ θέατρον εἰσόδῳ σημαίνεται Γάιος ἐξαναστὰς καὶ θόρυβος ἦν, ἀνέστρεφον δὲ καὶ οἱ συνωμόται καὶ ἀνεωθοῦντο τὴν πληθύν, λόγῳ μὲν διὰ τὸ δυσχεραίνειν τὸν Γάιον, ἔργῳ δὲ ἐπʼ ἀδείας βουλόμενοι ἐν ἐρημίᾳ τῶν ἀμυνουμένων καταστήσαντες αὐτὸν ἅπτεσθαι τῆς σφαγῆς."},{"number":102,"text":"προεξῄεσαν δὲ Κλαύδιος μὲν ὁ πάτρως αὐτοῦ καὶ Μᾶρκος Βινίκιος ὁ τῆς ἀδελφῆς ἀνὴρ ἔτι δὲ Οὐαλέριος Ἀσιατικός, οὓς οὐδὲ βουλομένοις διακλεῖσαι δύναμις ἦν αἰδοῖ τῆς ἀξιώσεως, εἵπετο δʼ αὐτὸς σὺν Παύλῳ Ἀρουντίῳ."},{"number":103,"text":"ἐπεὶ δʼ ἐντὸς ἦν τοῦ βασιλείου, τὰς μὲν ἐπʼ εὐθείας ὁδοὺς λείπει, καθʼ ἃς διεστήκεσαν τῶν δούλων οἱ θεραπεύοντες αὐτὸν καὶ προῄεσαν οἱ περὶ τὸν Κλαύδιον·"},{"number":104,"text":"τρέπεται δὲ κατὰ στενωπὸν ἠρεμηκότα καὶ ἐπὶ τόπον πρὸς λουτροῖς γενησόμενος ἅμα καὶ παῖδας οἳ ἥκεσαν ἐκ τῆς Ἀσίας κατανοήσων, πομπῆς αὐτῶν ἐκεῖθεν γενομένης ἐπὶ ὕμνοις μυστηρίων ἃ ἐπετέλει, ἔνιοι δὲ κατὰ πυρριχισμούς, οἳ ἐν τοῖς θεάτροις ἔσοιντο."},{"number":105,"text":"ὑπαντιάζει δʼ αὐτὸν Χαιρέας καὶ ᾔτησεν σημεῖον. τοῦ δὲ τῶν εἰς χλεύην ἀνακειμένων εἰπόντος οὐδὲν ἐνδοιάσας λοιδορίαις τε ἐχρᾶτο κατὰ τοῦ Γαΐου καὶ σπασάμενος τὸ ξίφος ἐπάγει πληγὴν σφοδράν· οὐ μήν γε ἦν καίριος."},{"number":106,"text":"καίτοι γέ φασίν τινες προνοίᾳ τοῦ Χαιρέου γενέσθαι τοῦ μὴ μιᾷ πληγῇ διεργάσασθαι τὸν Γάιον, ἀλλὰ τιμωρεῖσθαι μειζόνως πλήθει τραυμάτων."},{"number":107,"text":"οὐ μὴν ἐμοὶ πιθανὸς οὗτος ὁ λόγος διὰ τὸ μὴ ἐπιχωρεῖν ἐν ταῖσδε ταῖς πράξεσιν λογισμῷ χρῆσθαι τὸν φόβον, Χαιρέαν δέ, εἴπερ οὕτως ἐφρόνει, πάντων ἥγημαι μωρίᾳ διαφέρειν ἡδονὴν τῇ ὀργῇ χαριζόμενον μᾶλλον ἢ ἐκ τοῦ ὀξέος ἀπαλλαγὴν αὑτῷ τε καὶ τοῖς συνωμόταις κινδύνων χαριζόμενον, διὰ τὸ πολλὰς ἂν μηχανὰς ἔτι γενέσθαι βοηθειῶν Γαΐῳ μὴ φθάντι τὴν ψυχὴν ἀφεῖναι κἀνταῦθα Χαιρέᾳ λόγον ἂν γενέσθαι οὐ περὶ τῆς Γαΐου τιμωρίας, ἀλλὰ τῆς αὐτοῦ καὶ τῶν φίλων,"},{"number":108,"text":"ὅπου γε καὶ πράξαντι καλῶς ἂν εἶχε σιγῇ χρωμένῳ διαδιδράσκειν τὰς ὀργὰς τῶν ἀμυνομένων, οὐχ ὅπως ἄδηλον εἰ τύχοι κατορθῶν ἐπʼ ἀλόγοις χρῄζειν αὐτόν τε ἀπολέσαι καὶ τὸν καιρόν. καὶ τάδε μὲν εἰκάζειν παρέστω τοῖς βουλομένοις ᾗ καὶ θέλοιεν."},{"number":109,"text":"ὁ δὲ Γάιος ἀλγηδόνι τῆς πληγῆς περιφερόμενος, μεσσηγὺς γὰρ τοῦ τε ὤμου καὶ τοῦ τραχήλου φερόμενον τὸ ξίφος ἐπέσχεν ἡ κλεὶς προσωτέρω χωρεῖν, οὔτε ἀνεβόησεν ὑπʼ ἐκπλήξεως οὔτε ἐπεκαλέσατό τινας τῶν φίλων εἴτε ἀπιστίᾳ εἴτε καὶ ἄλλως ἀφρονήσει, στόνῳ δὲ χρησάμενος πρὸς τῆς ἀλγηδόνος τὸ περιὸν εἰς τὸ πρόσθεν ἵετο φυγῇ."},{"number":110,"text":"καὶ δεξάμενος αὐτὸν Κορνήλιος Σαβῖνος τὴν διάνοιαν ἤδη προκατειργασμένον ὠθεῖ καὶ κλιθέντα ἐπὶ γόνυ πολλοὶ περιστάντες ἀφʼ ἑνὸς ἐγκελεύσματος ἔκοπτον τοῖς ξίφεσιν, παρακελευσμός τε τὰ πρὸς ἀλλήλους καὶ πρὸς ἔρις αὐτοῖς ἦν. τελευταῖα δὲ Ἀκύλας, ὁμολογεῖται δὲ ὑπὸ πάντων πληγὴν ἐπαγαγών, μεθίστησιν αὐτὸν ἀκριβῶς."},{"number":111,"text":"ἀναθείη δʼ ἄν τις τὴν πρᾶξιν Χαιρέᾳ· καὶ γὰρ εἰ σὺν πολλοῖς ἐπράχθη τὸ ἔργον αὐτῷ, ἀλλʼ οὖν πρῶτός τε ἐνεθυμήθη εἶναι μέντοι αὐτῷ ὃς προλαβὼν πολὺ τῶν ἁπάντων,"},{"number":112,"text":"καὶ πρῶτος μὲν τολμηρῶς ἐξεῖπεν τοῖς λοιποῖς, δεχομένων δὲ τὸν ἐπὶ τῷ φόνῳ λόγον σποράδας τε ἤθροισεν καὶ τὰ πάντα φρονίμως συγκροτήσας ἔνθα γνωμῶν εἰσηγήσεως ἐχρῆν πολὺ κρείσσων ἐγίγνετο καὶ λόγοις καθωμίλησεν χρηστοῖς ὡς οὐ τολμῶντας ἠνάγκασέν τε τοὺς ἅπαντας,"},{"number":113,"text":"ἐπεί τε καιρὸς ἐλάμβανεν χειρὶ χρήσασθαι, φαίνεται κἀνταῦθα πρῶτός τε ὁρμήσας καὶ ἁψάμενος ἀρετῇ τοῦ φόνου καὶ τοῖς ἄλλοις εὐεπίβατον παρασχὼν καὶ προτεθνεῶτα Γάιον, ὥστʼ ἂν δικαίως καὶ ὁπόσα τοῖς λοιποῖς εἴη πεπραγμένα τῇ Χαιρέου γνώμῃ τε καὶ ἀρετῇ προστίθεσθαι καὶ πόνῳ τῶν χειρῶν."},{"number":114,"text":"Καὶ Γάιος μὲν τοιούτῳ τρόπῳ χρησάμενος τῆς τελευτῆς ὑπὸ τοῦ πολλοῦ τῶν τραυμάτων ἀποψυχθεὶς ἔκειτο."},{"number":115,"text":"οἱ δὲ περὶ τὸν Χαιρέαν ἐπειδὴ κατείργαστο αὐτοῖς ἤδη Γάιος, ὁδοὺς μὲν τὰς αὐτὰς ἰόντες σώζειν αὑτοὺς ἀμήχανον ἑώρων, ὄκνῳ τε τῶν γεγονότων, οὐ γὰρ μικρὸν ἦν τὸν αὐτοκράτορα ἀνῃρηκόσι τὸ κινδύνευμα ὑπό τε ἀνοίας τοῦ δήμου τιμώμενον καὶ ὄντα προσφιλῆ καὶ τῶν στρατιωτῶν μὴ ἀναιμωτὶ ποιησομένων τὴν ζήτησιν αὐτοῦ,"},{"number":116,"text":"ἄλλως τε στενῶν οὐσῶν τῶν ὁδῶν, καθʼ ἃς ἔπραξαν τὸ ἔργον, καὶ μεγάλου πλήθους ἐμφράξαντος αὐτὰς τῆς τε θεραπείας καὶ ὁπόσοι τῶν στρατιωτῶν ἐπὶ φυλακῇ τοῦ αὐτοκράτορος ἐκείνην παρῆσαν τὴν ἡμέραν,"},{"number":117,"text":"ὁδούς τε ἑτέρας χωροῦντες παρῆσαν εἰς τὴν Γερμανικοῦ μὲν οἰκίαν τοῦ Γαΐου πατρός, ὃν τότε ἀνῃρήκεσαν, συνημμένη δὲ ἐκείνη, διὰ τὸ ἓν τὸ βασίλειον ὂν ἐπʼ οἰκοδομίαις ἑκάστου τῶν ἐν τῇ ἡγεμονίᾳ γεγονότων ἀσκηθὲν ἀπὸ μέρους ὀνόματι τῶν οἰκοδομηθησομένων ἢ καί τι τῶν ἡμερῶν οἰκήσεις ἀρξάντων τὴν ἐπωνυμίαν παρασχέσθαι."},{"number":118,"text":"καὶ διεκπεσόμενοι ἐκ τοῦ πλήθους τὴν ἔφοδον ἐν ἀδείᾳ τὸ παρὸν ἦσαν λανθάνοντος ἀκμὴν κακοῦ τοῦ τὸν αὐτοκράτορα παρειληφότος."},{"number":119,"text":"πρώτους δὲ εἰς τοὺς Γερμανοὺς ἡ αἴσθησις ἀφίκετο τῆς Γαΐου τελευτῆς. δορυφόροι δʼ ἦσαν οὗτοι ὁμώνυμοι τῷ ἔθνει ἀφʼ οὗ κατειλέχατο Κελτικοῦ τάγμα παρεχόμενοι τὸ αὐτῶν."},{"number":120,"text":"θυμῷ δὲ χρῆσθαι πάτριόν ἐστιν αὐτοῖς, ὥσπερ σπάνιον εἴ τισιν ἑτέροις βαρβάρων διὰ τὸ ἡσσόνως λογισμὸν ἐπιδέχεσθαι τῶν ποιουμένων, ῥωμαλέοι τε τοῖς σώμασι καὶ τῇ πρώτῃ ὁρμῇ συνιόντες τοῖς πολεμίοις, οὓς ἂν νομίσωσι, μεγάλα κατορθοῦντες."},{"number":121,"text":"οὗτοι οὖν πυθόμενοι τοῦ Γαΐου τὴν σφαγὴν καὶ περιαλγήσαντες διὰ τὸ μὴ ἀρετῇ κρίνειν ἐπὶ τοῖς ὅλοις, ἀλλὰ συμφέροντι τῷ αὐτῶν, μάλιστα δὲ αὐτοῖς προσφιλὴς ἦν Γάιος δόσεσι χρημάτων τὸ εὔνουν αὑτῷ κτώμενος,"},{"number":122,"text":"σπασάμενοι τὰ ξίφη, προειστήκει δʼ αὐτῶν Σαβῖνος χιλιαρχῶν οὐ διʼ ἀρετὴν καὶ γενναιότητα προγόνων, μονομάχος γὰρ ἦν, ἰσχύι δὲ σώματος τὴν ἐπὶ τοιούτοις κτησάμενος ἄθροισιν ἀρετήν, διεξῄεσαν τῆς οἰκίας ἀνερευνώμενοι τοὺς σφαγέας τοῦ Καίσαρος."},{"number":123,"text":"Ἀσπρήναν τε κρεουργήσασιν αὐτοῖς διὰ τὸ πρώτῳ περιπεσεῖν, οὗ τὴν στολὴν μιᾶναν τὸ αἷμα τῶν θυμάτων, ὥς μοι λέλεκται πρότερον, οὐκ ἐπʼ ἀγαθῷ τὴν συντυχίαν ἀπεσήμαινε τοῦ γεγονότος δεύτερος, Νωρβανὸς ὑπηντίαζεν ἐν τοῖς γενναιοτάτοις τῶν πολιτῶν καὶ πολλοὺς αὐτοκράτορας παρεχόμενος τῶν προπατόρων."},{"number":124,"text":"καὶ μηδὲν αἰδουμένων αὐτοῦ τὴν ἀξίωσιν ἰσχύι προύχων ἀφαιρεῖται τὸ ξίφος τῷ πρώτῳ τῶν ἐπιόντων συμπλακεὶς φανερός τε ἦν οὐκ ἀπραγμόνως τεθνηξόμενος, μέχρι δὴ περισχεθεὶς πολλοῖς τῶν ἐπιφερομένων ἔπεσεν ὑπὸ πλήθους τραυμάτων."},{"number":125,"text":"τρίτος δὲ Ἀντήιος τῶν ἐκ τῆς βουλῆς σὺν ὀλίγοις, οὐ τυχαίως τοῖς Γερμανοῖς καθάπερ οἱ πρότερον περιπεσών, ὑπὸ δὲ φιλοθεαμοσύνης καὶ ἡδονῆς τοῦ αὐτόπτης γενόμενος Γαΐου κειμένου μῖσος εὐφρᾶναι τὸ πρὸς αὐτόν· τὸν γὰρ πατέρα τοῦ Ἀντηίου καὶ ὁμώνυμον φυγάδα ἐλάσας καὶ μὴ ἀρκεσθεὶς κτείνει στρατιώτας ἀποπέμψας."},{"number":126,"text":"καὶ παρῆν μὲν διὰ τάδε εὐφρανούμενος θεωρίᾳ τοῦ νεκροῦ, θορυβουμένης δὲ τῆς οἰκίας κρύπτειν αὑτὸν ἐνθυμησάμενος οὐ διαφυγγάνει τῶν Γερμανῶν τό τε εἰς τὴν ἔρευναν ἀκριβὲς κἀπὶ τοῖς φόνοις ὁμοίως τῶν τε αἰτίων καὶ μὴ ἐξαγριωσάντων. καὶ οἵδε μὲν ταύτῃ τεθνήκεσαν."},{"number":127,"text":"Εἰς δὲ τὸ θέατρον ἐπεὶ ἀφίκετο ὁ λόγος περὶ τῆς Γαΐου τελευτῆς, ἔκπληξίς τε καὶ ἀπιστία ἦν· οἱ μὲν γὰρ καὶ πάνυ ἡδονῇ δεχόμενοι τὸν ὄλεθρον αὐτοῦ κἂν πρὸ πολλοῦ ἡγησάμενοι σφίσιν ἀγαθὸν συνελθεῖν ὑπὸ δέους ἐν ἀπιστίᾳ ἦσαν."},{"number":128,"text":"εἰσὶ δʼ οἷς καὶ πάνυ ἀπʼ ἐλπίδων ἦν διὰ τὸ μὴ ἐθέλειν τι τοιόνδε περὶ τῷ Γαΐῳ γεγονέναι μηδὲ ἀληθείᾳ προστίθεσθαι διὰ τὸ μὴ οἷόν τε ἀνθρώπῳ εἶναι τοιᾷδε ἀρετῇ χρῆσθαι."},{"number":129,"text":"γύναια δʼ ἦν ταῦτα καὶ παῖδες ὁπόσοι τε δοῦλοι καί τινες τοῦ στρατιωτικοῦ, οἱ μὲν διὰ τὸ μισθοφορεῖν καὶ οὐδὲν ἀλλʼ ἢ συντυραννοῦντες καὶ διακονίᾳ τῆς κατʼ ἐκεῖνον ὕβρεως ἐπανασειόμενοι τοῖς κρατίστοις τῶν πολιτῶν τιμῆς τε ἅμα καὶ ὠφελειῶν τυγχάνειν,"},{"number":130,"text":"ἡ δὲ αὖ γυναικωνῖτις καὶ τὸ νεώτερον, ὅπερ ὄχλος φιλεῖ, θεωρίαις τε καὶ μονομαχιῶν δόσεσιν καί τινων κρεανομιῶν ἡδοναῖς ἀνειλημμένοι, ἃ ἐπράσσετο λόγῳ μὲν ἐπὶ θεραπείᾳ τῆς πληθύος, τὸ δʼ ἀληθὲς ἐκπιμπλάντα τῆς μανίας Γαΐου τὴν ὠμότητα·"},{"number":131,"text":"οἱ δὲ δοῦλοι διὰ τὸ ἐν προσηγορίᾳ τε εἶναι καὶ καταφρονήματι τῶν δεσποτῶν, ἀποστροφῆς τῷ ὑβρίζοντι αὐτὴν οὔσης τῆς κατʼ ἐκεῖνον ἐπικουρίας· ῥᾴδιον γὰρ ψευσαμένοις τε κατὰ τῶν κυρίων πεπιστεῦσθαι καὶ τὰ χρήματα ἐνδείξασιν αὐτῶν ἅμα ἐλευθέροις τε εἶναι καὶ πλουσίοις μισθῷ τῶν κατηγοριῶν διὰ τὸ ἆθλα αὐτοῖς προκεῖσθαι τὰς ὀγδόας τῶν οὐσιῶν."},{"number":132,"text":"τῶν δὲ εὐπατριδῶν εἰ καί τισιν πιστὸς ὁ λόγος φανείη, τοῖς μὲν ἐκ τοῦ προειδέναι τὴν ἐπιβουλήν, τοῖς δʼ ὑπὸ τοῦ θέλειν εὐκτὸν ἡγουμένοις, σιγῇ παρεδίδοτο οὐ μόνον ἡ ἐπὶ τοῖς ἠγγελμένοις χαρά, ἀλλὰ καὶ ἡ δόξα τῆς ἀκροάσεως,"},{"number":133,"text":"οἱ μὲν δεδιότες, μὴ καὶ ψευσθεῖσιν ἐλπίδος τιμωρίᾳ συνέλθοιεν ὡς προεξορμήσασιν ἀποφήνασθαι τὴν διάνοιαν ἑαυτῶν, οἱ δʼ ἐξεπιστάμενοι διὰ τὸ τῆς ἐπιβουλῆς μετασχεῖν μειζόνως ἔκρυπτον ἀλλήλων ἀγνοίᾳ καὶ δεδιότες, μὴ πρός τινα εἰπόντες, οἷς ἡ τυραννὶς ἑστῶσα ὠφέλιμος ἦν, ζῶντος Γαΐου κολασθεῖεν ἐνδείξεως γενομένης."},{"number":134,"text":"ἐπεὶ καὶ ἕτερος ἐπεφοιτήκει λόγος ὡμιληκέναι μὲν τραύμασιν, οὐ μὴν ἀποθανεῖν, ἀλλὰ ζῶντα ἐν θεραπείαις ὑπὸ τῶν ἰατρῶν εἶναι."},{"number":135,"text":"ἦν τε πιστὸς οὐθεὶς οὐδενί, ᾧ κἂν θαρσήσας γνώμην ἀποφαίνοιτο τὴν αὐτοῦ· ἢ γὰρ φίλος ὢν ὕποπτος ἐγίνετο εὐνοίᾳ τῆς τυραννίδος ἢ καὶ μίσει πρὸς ἐκεῖνον χρώμενος τῷ πρὸς αὐτὸν οὐδαμόθεν εὐνοίᾳ χρωμένῳ διαφθείρειν τὴν ἐπὶ τοῖς λεγομένοις πίστιν."},{"number":136,"text":"ἐλέγετο δὲ ὑπό τινων, οἳ καὶ μάλιστα τοῖς εὐπατρίδαις ἠφάνιζον τὸ εὐθυμοῦν τῆς ἐλπίδος, ἐν ἀμελείᾳ κινδύνων γεγονότα καὶ ἄφροντιν κομιδῇ τῶν τραυμάτων, ὥσπερ εἶχεν ᾑματωμένον ἐπὶ τῆς ἀγορᾶς διεκπεσεῖν κἀν δημηγορίαις εἶναι."},{"number":137,"text":"καὶ τάδε μὲν εἰκάζετο βουλήσει τῇ ἀλογίστῳ τῶν θροεῖν προθεμένων καὶ ἐπʼ ἀμφότερα δόξῃ τῶν ἀκουόντων λαμβανόμενα· οὐ μὴν τήν γʼ ἐνέδραν ἐξέλιπον δεδιότες τὴν ἐπενεχθησομένην προεξιοῦσιν αἰτίαν· οὐ γὰρ ἐφʼ ἧς ἀξιοῖεν διανοίας γενήσεσθαι περὶ αὐτοῖς τὴν κρίσιν, ἀλλʼ ἀφʼ ἧς εἰκάζειν ἐθελήσειαν τούς τε κατηγορήσοντας καὶ τοὺς δικάζοντας."},{"number":138,"text":"Ἐπεὶ δὲ καὶ πλῆθος τῶν Γερμανῶν περιέσχε τὸ θέατρον ἐσπασμένων τὰ ξίφη, πᾶσι τοῖς θεωροῖς ἐλπὶς ἦν ἀπολεῖσθαι, καὶ πρὸς πᾶσαν οὗτινος εἴσοδον πτοία εἶχεν αὐτούς, ὡς αὐτίκα μάλα συγκοπήσοιντο, ἐν ἀμηχάνοις τε ἦσαν οὔτʼ ἀπιέναι θάρσος εἰσφερόμενοι οὔτε ἀκίνδυνον τὴν διατριβὴν τὴν ἐπὶ τοῦ θεάτρου πεπιστευκότες."},{"number":139,"text":"εἰσπιπτόντων τε ἤδη βοὴ τοῦ θεάτρου ῥήγνυται καθʼ ἱκετείαν τρεπομένου τῶν στρατιωτῶν, ὡς πάντων ἀγνοίας αὐτῇ γενομένης καὶ τῶν βουλευθέντων τοῖς ἐπαναστᾶσιν, εἰ δή τις καὶ γέγονεν ἐπανάστασις, καὶ τῶν γεγονότων."},{"number":140,"text":"φείδεσθαι οὖν καὶ μὴ τόλμης ἀλλοτρίας παρὰ τῶν οὐδʼ ἐν αἰτίᾳ γενομένων ἀπολαμβάνειν τιμωρίαν, παρέντας ἐρεύνην τῶν πεπραχότων ὅ τι καὶ πεπραγμένον εἴη καταστῆναι."},{"number":141,"text":"καὶ οἱ μὲν ταῦτά τε καὶ περαιτέρω μετὰ δακρύων καὶ τύψεως προσώπων ἐπιθειάζοντες καὶ ποτνιώμενοι ὁπόσα ἀνεδίδασκεν αὐτοὺς ὁ κίνδυνος ἑστὼς πλησίον, καὶ ὡς ἄν τις ἀγωνιζόμενος περὶ τῆς ψυχῆς εἴποι τι, ἔλεγον."},{"number":142,"text":"θραύεται δὲ τῶν στρατιωτῶν πρὸς ταῦτα ἡ ὀργὴ καὶ μεταμελῆσαν αὐτοῖς τοῦ ἐπὶ τοῖς θεωροῖς βουλεύματος, ὠμόν τε γὰρ ἦν τοῦτο καὶ ἐκείνοις καίπερ ἐξηγριωκόσιν ἐδόκει, τὰς κεφαλὰς τῶν περὶ τὸν Ἀσπρήναν ἐπὶ τὸν βωμὸν ἀπερεισαμένοις."},{"number":143,"text":"πρὸς ἃς μειζόνως ἔπαθον οἱ θεωροὶ λογισμῷ τε ἀξιώσεως τῶν ἀνδρῶν καὶ ἐλέῳ τοῦ πάθους, ὥστε παρʼ ὀλίγον καὶ αὐτοῖς οὐδὲν ἐλλιπεστέρως τὰ τῶν κινδύνων ὁμιλήσαντα ἐπανασεσεῖσθαι, ὧν ἄδηλον εἶναι τὴν συμφορὰν εἴπερ εἰς τέλος φευχθῆναι δύναιτʼ ἄν."},{"number":144,"text":"ὥστε κἂν εἴ τινες τῶν προθύμως μισούντων καὶ μετὰ δίκης τὸν Γάιον ἀφαιρεῖσθαι τῶν ἐπʼ αὐτῷ εὐφροσυνῶν τῆς χώρας, διὰ τὸ ἐν ῥοπῇ μὲν τοῦ συναπολουμένου γεγονέναι, τὸ δὲ πιστὸν τοῦ περιεῖναι μηδέπω καὶ τότε ἐχέγγυον συνελθεῖν."},{"number":145,"text":"Ἦν δὲ Εὐάρεστος Ἀρούντιος τῶν κηρυσσόντων τὰ πωλούμενα καὶ διʼ αὐτὸ φωνῆς τε μεγέθει χρώμενος καὶ χρήματα περιβεβλημένος ὅμοια τοῖς Ῥωμαίων πλουσιωτάτοις, δύναμίς τε αὐτῷ ἦν ἐφʼ οἷς ἐθελήσειε πράσσειν κατὰ τὴν πόλιν ἔν τε τῷ τότε κἀν τοῖς ὕστερον."},{"number":146,"text":"οὗτος διαθεὶς αὑτὸν ὡς ἐνῆν πενθιμώτατον, καίτοι μίσει καὶ παρʼ ὁντινοῦν ἐχρῆτο πρὸς Γάιον, ἀλλὰ μὴν κρείσσων ἡ διδασκαλία τοῦ φόβου καὶ στρατηγία περὶ τοῦ κερδησομένου τὴν σωτηρίαν τῆς εἰς τὸ παρὸν ἡδονῆς,"},{"number":147,"text":"πάντα κόσμον ἐπιτηδεύσας ὡς ἄν τις ἐπὶ τοῖς τιμιωτάτοις παρεσκεύαστο ἀπολωλόσιν, ἀποσημαίνει τοῦ Γαΐου τὸν θάνατον ἐπὶ τὸ θέατρον παρελθὼν καὶ ἔπαυσεν τοὺς ἀνθρώπους ἐπὶ πλέον ἀγνοίᾳ συμπεριφέρεσθαι τοῦ γεγονότος."},{"number":148,"text":"ἤδη δὲ καὶ Στήλας Ἀρούντιος παρῆν ἀνακαλῶν τοὺς Γερμανοὺς καὶ οἱ χιλίαρχοι σὺν αὐτῷ κελεύοντες κατατίθεσθαι τὸν σίδηρον καὶ διασαφοῦντες Γαΐου τὴν τελευτήν."},{"number":149,"text":"τοῦτο καὶ σαφέστατα ἔσωσεν τοὺς ἐν τῷ θεάτρῳ συνειλεγμένους καὶ πάντας, οἳ καὶ ὁπωσοῦν τοῖς Γερμανοῖς περιτύχοιεν· ἐλπίδος γὰρ αὐτοῖς παραγενομένης ἔμπνουν κεῖσθαι τὸν Γάιον οὐκ ἔσθʼ οὗτινος κακῶν ἂν ἀπέσχοντο."},{"number":150,"text":"τοσόνδε ἐπερίσσευσεν αὐτοῖς εὐνοίας τῆς πρὸς αὐτόν, ὡς κἂν μετὰ τοῦ καθʼ αὑτοὺς ἀπολουμένου τῆς ψυχῆς κτήσασθαι τὸ ἀνεπιβούλευτον αὐτῷ καὶ τοσαύτῃ δυστυχίᾳ συνεσόμενον."},{"number":151,"text":"παύονται δὲ τοῦ ὠργηκότος εἰς τὴν τιμωρίαν μαθήσεως σαφοῦς παραγενομένης αὐτοῖς ἐπὶ τῇ τελευτῇ, διά τε τὸ εἰς ἀχρεῖον ἐπιδείξεσθαι τὸ πρόθυμον τῆς εὐνοίας, ὃς ἀμείψαιτο αὐτοὺς ἀπολωλότος, καὶ δέει, μὴ καὶ περαιτέρω τῇ ὕβρει χρωμένων ἐπιστροφὴ γένοιτο ὑπὸ τῆς βουλῆς, εἴπερ εἰς ἐκείνην περισταίη τὸ κράτος, ἢ ὑπὸ τοῦ ἐπικαταστάντος ἄρχοντος."},{"number":152,"text":"καὶ Γερμανοὶ εἰ καὶ μόλις, ἀλλʼ οὖν ἐπαύσαντο λύσσης τῆς ἐπὶ Γαΐου τῷ θανάτῳ καταλαμβανομένης αὐτούς."},{"number":153,"text":"Χαιρέας δέ, σφόδρα γὰρ περὶ Μινουκιανῷ ἔδεισε, μὴ διαφθαρείη μανίᾳ τῶν Γερμανῶν περιπεσών, ἕκαστόν τε τῶν στρατιωτῶν μετῄει προμηθεῖσθαι τῆς σωτηρίας αὐτοῦ δεόμενος καὶ μὴ ἀπολώλοι πολλὴν ἐξέτασιν ποιούμενος."},{"number":154,"text":"καὶ Μινουκιανὸν μὲν Κλήμης, ἀνάγεται γὰρ ἐπὶ τοῦτον, μεθίησιν πολλῶν μετʼ ἄλλων συγκλητικῶν δικαιοσύνην τῇ πράξει συμμαρτυρῶν καὶ ἀρετὴν τοῖς ἐντεθυμημένοις καὶ πράσσειν μὴ ἀποδεδειλιακόσι·"},{"number":155,"text":"τυραννίδα γὰρ εἰς ὀλίγον μὲν ἐλθεῖν ἡδονῇ τοῦ ὑβρίζειν ἐπαρθεῖσαν, εὐτυχεῖς δὲ οὐκ ἄρα ποιεῖσθαι τὰς ἀπαλλαγὰς τοῦ βίου μίσει τῆς ἀρετῆς πρὸς αὐτὸν χρωμένης,"},{"number":156,"text":"ἀλλὰ μετὰ τοιαύτης δυστυχίας, ὁποίᾳ δὴ Γάιον συνελθεῖν πρὸ τῶν ἐπαναστάντων καὶ συνθέντων τὴν ἐπίθεσιν αὐτὸν ἐπίβουλον αὐτῷ γενόμενον καὶ διδάξαντα οἷς ὑβρίζων ἀφόρητος ἦν ἀφανίζων τοῦ νόμου τὴν πρόνοιαν πολέμῳ πρὸς αὐτὸν χρῆσθαι τοὺς φιλτάτους, καὶ νῦν λόγῳ μὲν εἶναι τούτους οἳ ἀνῃρήκασι Γάιον, ἔργῳ δὲ αὐτὸν ὑφʼ ἑαυτοῦ κεῖσθαι διολωλότα."},{"number":157,"text":"Ἤδη δὲ καὶ τὸ θέατρον ἐξανίστατο τῶν φυλακῶν αἳ τὸ κατʼ ἀρχὰς πάνυ πικραὶ ἐγένοντο ὑπανίσως. αἰτία δʼ ἦν τοῦ προθύμως καὶ διαφευξομένου τῶν θεωρῶν Ἀλκύων ὁ ἰατρός, συναρπασθεὶς μὲν ὡς ἐπὶ θεραπείᾳ τινῶν τραυματιῶν, ἐκπέμψας δὲ τοὺς συνόντας λόγῳ μὲν ὡς καὶ μετελευσομένους ὁπόσα εἰς τὴν ἴασιν τοῖς τραυματίαις πρόσφορα, τὸ δʼ ἀληθὲς ὡς πείσοιντο κινδύνου τοῦ κατειληφότος."},{"number":158,"text":"ἐν τούτῳ δὲ βουλῆς τε γίνεται σύνοδος καὶ ὁ δῆμος ᾗπερ καὶ εἰώθασιν ἐκκλησιάζειν ἐπὶ τῆς ἀγορᾶς καταστὰς ἐν ζητήσει τῶν σφαγέων τῶν Γαΐου ἦσαν, ὁ μὲν δῆμος καὶ πάνυ ἐκθύμως, δοκεῖν δὲ καὶ ἡ βουλή."},{"number":159,"text":"καὶ ἦν γὰρ Ἀσιατικὸς Οὐαλέριος ὑπατικὸς ἀνήρ, οὗτος ἐπὶ τὸν δῆμον καταστάς, θορυβούντων καὶ δεινὸν τιθεμένων τὸ ἔτι λανθάνον τῶν τὸν αὐτοκράτορα ἀπεκτονότων, ἐπεὶ προθύμως πάντες αὐτὸν ἤροντο, τίς ὁ πράξας τυγχάνει, εἴθε γὰρ ἔγωγε φησί."},{"number":160,"text":"καὶ προύθεσαν δὲ καὶ οἱ ὕπατοι διάγραμμα Γαΐου μὲν κατηγορίας ποιούμενοι, κελεύοντες δὲ τῷ τε δήμῳ καὶ τοῖς στρατιώταις ἐπὶ τὰ αὐτῶν ἀπιέναι, τῷ μὲν δήμῳ πολλὴν ἀνέσεως ἐπαγγελλόμενοι ἐλπίδα, τῷ στρατιωτικῷ δὲ τιμῶν, εἰ ἐν κόσμῳ μείνειαν τῷ εἰωθότι μηδὲν ὑβρίζειν ἐξαγόμενοι· δέος γὰρ ἦν, μὴ ἐξαγριωσάντων ἀπολαύσειεν τοῦ κακοῦ ἡ πόλις καθʼ ἁρπαγὰς αὐτῶν καὶ συλήσεις τῶν ἱερῶν τρεπομένων."},{"number":161,"text":"ἐφθάκει δὲ ἤδη τῶν βουλευτῶν τὸ πᾶν πλῆθος συνειλεγμένον καὶ μάλιστα οἱ εἰς τοῦ Γαΐου συνελθόντες τὸν φόνον θράσει τε ἤδη χρώμενοι κἀν καταφρονήματι μεγάλῳ ὄντες ὡς εἰς αὐτοὺς ἀνακειμένων δὴ τῶν πραγμάτων."}],"2":[{"number":162,"text":"Ἐν τούτῳ δὴ ὄντων τῶν πραγμάτων αἰφνίδιον ἀρπάζεται Κλαύδιος ἐκ τῆς οἰκίας· οἱ γὰρ στρατιῶται συνόδου γενομένης αὐτοῖς, ἀλλήλοις καὶ αὑτοῖς λόγον δόντες περὶ τοῖς ποιητέοις ἑώρων δημοκρατίαν ἀδύνατόν τε ὂν ἐν κράτει τοσῶνδε ἄν ποτε γενέσθαι πραγμάτων ἐξικομένην τε οὐκ ἐπʼ ἀγαθῷ τῷ αὐτῶν κτήσασθαι τὴν ἀρχήν,"},{"number":163,"text":"εἴ τέ τις τῶν κατὰ ἕνα σχήσοι τὴν ἡγεμονίαν, εἰς πάντα λυπηρὸν αὐτοῖς εἶναι μὴ οὐ συνεργοῖς τῆς ἀρχῆς καταστᾶσιν."},{"number":164,"text":"καλῶς οὖν ἔχειν ἀκρίτων ἔτι ὄντων τῶν πραγμάτων ἡγεμόνα αἱρεῖσθαι Κλαύδιον, πάτρωά τε ὄντα τοῦ τεθνεῶτος καὶ τῶν εἰς τὴν βουλὴν συλλεγομένων οὐδενὸς οὗτινος οὐκ ἀξιολογώτερον προγόνων τε ἀρετῇ καὶ τῷ κατʼ αὐτὸν παιδείαν μεμελετηκότι,"},{"number":165,"text":"καὶ σταθέντα αὐτοκράτορα τιμήσειν τε τὰ εἰκότα καὶ ἀμείψεσθαι δωρεαῖς. ταῦτα διανοοῦνταί τε καὶ ἔπραξαν ἐκ τοῦ παραχρῆμα."},{"number":166,"text":"ἥρπαστο μὲν δὴ Κλαύδιος ὑπὸ τοῦ στρατιωτικοῦ. Ναῖος δὲ Σέντιος Σατορνῖνος καίτοι πεπυσμένος τὴν Κλαυδίου ἁρπαγήν, καὶ ὡς ἐπιδικάζοιτο τῆς ἀρχῆς ἄκων μὲν δοκεῖν, τὸ δὲ ἀληθὲς καὶ βουλήσει τῇ αὐτοῦ, καταστὰς ἐπὶ τῆς συγκλήτου καὶ μηδὲν ἐκπλαγεὶς ἐλευθέροις τε καὶ γενναίοις ἀνδράσι πρεπόντως ποιεῖται παραίνεσιν τάδε λέγων."},{"number":167,"text":"Εἰ καὶ ἄπιστον, ὦ Ῥωμαῖοι, διὰ τὸ χρόνῳ πολλῷ ἥκειν ἀνέλπιστον οὖσαν ἡμῖν, ἀλλʼ οὖν ἔχομεν τοῦ ἐλευθέρου τὴν ἀξίωσιν, ἄδηλον μὲν ἐφʼ ὁπόσον παρατείνουσαν καὶ γνώμῃ θεῶν οἳ ἐχαρίσαντο αὐτὴν κειμένην, εὐφραίνειν δὲ ἀρκοῦσαν καὶ εἴπερ ἀφαιρεθείημεν αὐτῆς εὐδαιμονίᾳ συνάγουσαν·"},{"number":168,"text":"ἱκανὴ γὰρ καὶ μία ὥρα τοῖς ἀρετῆς αἰσθανομένοις καὶ μετʼ αὐτοτελοῦς τῆς διανοίας ἐν αὐτοδίκῳ τῇ πατρίδι καὶ μετὰ νόμων, οἷς ποτε ἤνθησε, διαιτωμένῃ βιωθεῖσα."},{"number":169,"text":"ἐμοὶ δὲ τῆς μὲν πρότερον ἐλευθερίας ἀμνημονεῖν ἔστι διὰ τὸ κατόπιν αὐτῆς γεγονέναι, τῆς δὲ νῦν ἀπλήστως πιμπλαμένῳ μακαριστούς τε ἡγεῖσθαι τοὺς ἐγγενηθέντας καὶ ἐντραφέντας αὐτῇ καὶ τῶν θεῶν οὐδὲν μειόνως ἀξίους τιμῆς τούσδε τοὺς ἄνδρας, οἳ ὀψὲ γοῦν κἀν τούτῳ τῆς ἡλικίας ἡμᾶς γεύσαντας αὐτῆς."},{"number":170,"text":"καὶ εἴη μὲν εἰς πᾶν τοῦ αἰῶνος τὸ ἐπιὸν παραμεῖναι τὴν ἄδειαν αὐτῆς, ἀρκοῦσα δʼ ἂν γένοιτο καὶ ἥδε ἡ ἡμέρα τοῖς τε νεωτέροις ἡμῶν καὶ ὅσοι γεγηράκαμεν αἰὼν ὑπείληπται, τοῖς πρεσβυτέροις δόντων ἀγαθῶν αὐτῆς ἐν ὁμιλίᾳ γεγονότες μετασταῖεν, τοῖς δὲ"},{"number":171,"text":"νεωτέροις παίδευμα ἀρετῆς καταστάσεως ἀγαθὸν ἀνδράσι τοῖσδε ἀφʼ ὧν γεγόναμεν, νῦν δὲ ἤδη καὶ ἡμῖν διὰ τὴν ἄρτι ὥραν οὐδὲν προυργιαίτερον εἴη τοῦ ζῆν μετὰ ἀρετῆς, ἣ μόνη ἐκφροντίζει τῷ ἀνθρωπείῳ τὸ ἐλεύθερον·"},{"number":172,"text":"ἐγὼ γὰρ τὰ παλαιὰ οἶδα ἀκοῇ παραλαβών, οἷς δὲ ὄψει ὁμιλήσας ᾐσθόμην, οἵων κακῶν τὰς πολιτείας ἀναπιμπλᾶσιν αἱ τυραννίδες, κωλύουσαι μὲν πᾶσαν ἀρετὴν καὶ τοῦ μεγαλόφρονος ἀφαιρούμεναι τὸ ἐλεύθερον, κολακείας δὲ καὶ φόβου διδάσκαλοι καθιστάμεναι διὰ τὸ μὴ ἐπὶ σοφίᾳ τῶν νόμων, ἀλλʼ ἐπὶ τῇ ὀργῇ τῶν ἐφεστηκότων καταλιπεῖν τὰ πράγματα."},{"number":173,"text":"ἀφʼ οὗ γὰρ Ἰούλιος Καῖσαρ φρονήσας ἐπὶ καταλύσει τῆς δημοκρατίας καὶ διαβιασάμενος τὸν κόσμον τῶν νόμων τὴν πολιτείαν συνετάραξεν, κρείσσων μὲν τοῦ δικαίου γενόμενος, ἥσσων δὲ τοῦ κατʼ ἰδίαν ἡδονὴν αὐτῷ κομιοῦντος, οὐκ ἔστιν ὅ τι τῶν κακῶν οὐ διέτριψεν τὴν πόλιν,"},{"number":174,"text":"φιλοτιμηθέντων πρὸς ἀλλήλους ἁπάντων, οἳ ἐκείνῳ διάδοχοι τῆς ἀρχῆς κατέστησαν, ἐπʼ ἀφανισμῷ τοῦ πατρίου καὶ ὡς ἂν μάλιστα τῶν πολιτῶν ἐρημίαν τοῦ γενναίου καταλείποιεν, διὰ τὸ οἴεσθαι πρὸς ἀσφαλείας εἶναι τῆς αὐτῶν τὸ κιβδήλοις ἀνδράσιν ὁμιλεῖν καὶ τῶν ἀρετῇ προύχειν πεπιστευμένων οὐ μόνον ὑφαιρεῖν τι τοῦ αὐχήματος, ἀλλʼ εἰς τὸ πᾶν ἐπιφημίζειν αὐτῷ τοῖς ὀλέθροις"},{"number":175,"text":"τῶν ἁπάντων ἀριθμῷ τε πολλῶν ὄντων καὶ βαρύτητα ἀνύποιστον ἐπιδειξαμένων καθʼ ἃ ἕκαστος ἦρξεν εἷς ὢν ὁ Γάιος ὁ σήμερον τεθνεὼς πλέω τε τῶν πάντων δεινὰ ἀπεδείξατο οὐ μόνον εἰς τοὺς συμπολίτας, ἀλλὰ καὶ εἰς τοὺς συγγενεῖς καὶ φίλους ἀπαίδευτον τὴν ὀργὴν ἐπαφιείς, ὁμοίως τοῖς ἅπασι καὶ μείζω κακὰ ἐντριβόμενος ἀδίκως τὴν τιμωρίαν εἰσπράσσεσθαι, ὠργικότων ὁμοίως εἴς τε ἀνθρώπους ἐξαγριώσας καὶ τοὺς θεούς."},{"number":176,"text":"τυραννίδι γὰρ οὐ κερδαίνεται τὸ ἡδὺ οὐδὲ μεθʼ ὕβρεως ἀποχρῆται, οὐκ εἰς τὰ χρήματα λελυπῆσθαι καὶ γαμετάς, ἀλλὰ τὸ πᾶν κέρδος ἐκ τοῦ πανοικεσίᾳ διοχλουμένου τῶν ἐχθρῶν."},{"number":177,"text":"ἐχθρὸν δὲ τυραννίδι πᾶν τὸ ἐλεύθερον, εἰς εὔνοιάν τε ἐκκαλεῖσθαι αὐτὴν καὶ τοῖς ἐν ὀλίγῳ τιθεμένοις ὁπόσα πεπόνθοιεν οὐκ ἔστιν. ἐξεπιστάμενοι γὰρ ὧν ἀναπλήσειαν κακῶν ἔστιν οὓς κἀκεῖνοι μεγαλοφρόνως καταφρονημάτων τε πρὸς τὴν τύχην, αὐτοὶ λανθάνειν αὐτοὺς ὧν πράξειαν μὴ δυνάμενοι μόνως πιστεύουσιν κτήσεσθαι τοῦ ὑπόπτου τὸ ἀδεές, εἰ παντελὲς αἱρεῖσθαι δυνηθεῖεν αὐτούς."},{"number":178,"text":"τοιούτων δὴ κακῶν ἀπογεγονότες καὶ ὑποτελεῖς ἀλλήλοις καταστάντες, αἵπερ πολιτειῶν ἐχεγγυώταται πρός τε τὸ παρὸν εὔνουν καὶ τὸ αὖθις ἀνεπιβούλευτον καὶ τὸ δόξαν οἰκείαν τῷ ὀρθουμένῳ τῆς πόλεως δικαιοί τε προνοῆσαι διὰ τὸ εἰς κοινὸν αὐτοῦ τὴν ὠφέλειαν ἀπαντᾶν καὶ ἀνταποφήνασθαι γνώμην,"},{"number":179,"text":"οἷς μὴ ἀρέσκοιτο τὰ προεισηγημένα, οὐδαμῶς εἰς κίνδυνον φέρον, διὰ τὸ μὴ δεσπότην εἶναι τὸν ἐφεστηκότα, ᾧ ἀνεύθυνόν τε βλάπτοντι τὴν πόλιν καὶ αὐτοκράτορι μεταστήσασθαι τοὺς εἰρηκότας."},{"number":180,"text":"καὶ τέτροφε τὴν τυραννίδα οὐδὲν νεώτερον πλὴν ἥ τε ἀργία καὶ τὸ πρὸς οὐδὲν τῶν ἐκείνῃ θελομένων ἀντιλογίᾳ χρώμενον·"},{"number":181,"text":"τῆς γὰρ εἰρήνης τοῦ τερπνοῦ ἡσσώμενοι καὶ μεμαθηκότες ἀνδραπόδων ἐν τρόπῳ ζῆν ὁπόσοι τε ἐπαΐομεν συμφορὰς ἀνηκέστους κακοῖς τε τοῖς πέλας ἐπείδομεν φόβῳ τοῦ μετʼ ἀρετῆς τελευτᾶν μετὰ αἰσχύνης τῆς ὑστάτης ὑπομένοντες τὰς τελευτάς."},{"number":182,"text":"πρῶτον δὲ τοῖς ἀραμένοις τὸν τύραννον τιμὰς αἵτινες μέγισται ταύτας εἰσενεγκεῖν, μάλιστα δὲ Χαιρέᾳ τῷ Κασσίῳ· σὺν γὰρ τοῖς θεοῖς εἷς ἀνὴρ οὗτος ποριστὴς ἡμῖν καὶ γνώμῃ καὶ χερσὶ τῆς ἐλευθερίας πέφηνεν."},{"number":183,"text":"οὗ καλὸν μὴ ἀμνημονεῖν, ἀλλʼ ἐπὶ τῆς τυραννίδος ὑπὲρ ἐλευθερίας τῆς ἡμετέρας προβεβουλευκότος τε ἅμα καὶ προκεκινδυνευκότος, ἐπὶ τῆς ἐλευθερίας ψηφίσασθαι τὰς τιμὰς πρῶτόν τε ἀνεπιτάκτους τοῦτο ἂν ἀποφήνασθαι."},{"number":184,"text":"ἔργον δὲ κάλλιστον καὶ ἐλευθέροις ἀνδράσι πρέπον ἀμείβεσθαι τοὺς εὐεργέτας, οἷος δὴ καὶ ἀνὴρ οὗτος περὶ ἡμᾶς πάντας γέγονεν οὐδὲν παραπλήσιος Κασσίῳ καὶ Βρούτῳ τοῖς Γάιον Ἰούλιον ἀνῃρηκόσιν, ἐπεί γε οἱ μὲν στάσεως καὶ πολέμων ἐμφυλίων ἀρχὰς ἐπανερρίπισαν τῇ πόλει, οὗτος δὲ μετὰ τῆς τυραννοκτονίας καὶ τῶν ἐντεῦθεν δεινῶν ἀπήλλαξεν τὴν πόλιν."},{"number":185,"text":"Σέντιος μὲν τοιούτοις ἐχρῆτο τοῖς λόγοις καὶ τῶν βουλευτῶν ἡδονῇ δεχομένων καὶ ὁπόσοι τῶν ἱππέων παρῆσαν. ἀναπηδήσας δέ τις Τρεβέλλιος Μάξιμος περιαιρεῖται τὸν δακτύλιον τοῦ Σεντίου, λίθος δὲ εἰκόνα Γαΐου ἐγγεγλυμμένος ἐδεσμεύετο αὐτῷ, καὶ σπουδῇ τῶν λεγομένων καὶ ὧν ἐπενόει πράξειν, ὅπερ ᾤετο, ἐν λήθῃ γεγονότι καὶ ἡ μὲν γλυφὴ κατάγνυται."},{"number":186,"text":"προεληλύθει δὲ ἡ νὺξ ἐπὶ μέγα, καὶ Χαιρέας δὲ σημεῖον ᾔτει τοὺς ὑπάτους, οἱ δὲ ἐλευθερίαν ἔδοσαν. ἐν θαύματι δὲ ἦν αὐτοῖς καὶ ὅμοια ἀπιστίᾳ τὰ δρώμενα·"},{"number":187,"text":"ἔτει γὰρ ἑκατοστῷ, μεθʼ ὃ τὴν δημοκρατίαν τὸ πρῶτον ἀφῃρέθησαν, ἐπὶ τοὺς ὑπάτους σημείου ἡ παράδοσις· οὗτοι γὰρ πρότερον ἢ τυραννηθῆναι τὴν πόλιν κύριοι τῶν στρατιωτικῶν ἦσαν."},{"number":188,"text":"Χαιρέας δὲ τὸ σημεῖον λαβὼν παρεδίδου τῶν στρατιωτῶν τοῖς πρὸς τὴν σύγκλητον συνεστηκόσιν. ἦσαν δὲ εἰς σπείρας τέσσαρας, οἷς τὸ ἀβασίλευτον τιμιώτερον τῆς τυραννίδος προύκειτο."},{"number":189,"text":"καὶ οἵδε μὲν ἀπῄεσαν μετὰ τῶν χιλιάρχων, ἀνεχώρει δὲ ἤδη καὶ ὁ δῆμος περιχαρὴς καὶ ἐλπίδος καὶ φρονήματος ἐπὶ τῷ κτησαμένῳ τὴν ἡγεμονίαν αὐτοῖς, οὐκέτι ἐπὶ τῷ ἐφεστηκότι. καὶ τὰ πάντα ἦν ὁ Χαιρέας αὐτοῖς."},{"number":190,"text":"Χαιρέας δὲ ἐν δεινῷ τιθέμενος περιεῖναι τὴν θυγατέρα Γαΐου καὶ τὴν γυναῖκα, ἀλλὰ μὴ πανοικὶ τὸν ὄλεθρον αὐτῷ συντυχεῖν, ἐπεὶ καὶ πᾶν ὅ τι ὑπολείποιτο αὐτῶν ἐπʼ ὀλέθρῳ τῆς πόλεως λειφθήσεσθαι καὶ τῶν νόμων, ἄλλως τε πρόθεσιν ἐσπουδακὼς τελειώσασθαι τὴν αὐτοῦ καὶ πάνυ εὐφρᾶναι μῖσος τὸ πρὸς Γάιον, Ἰούλιον ἐκπέμπει Λοῦππον ἕνα τῶν χιλιάρχων κτενοῦντα τήν τε γυναῖκα Γαΐου καὶ τὴν θυγατέρα."},{"number":191,"text":"Κλήμεντος δʼ ὄντι συγγενεῖ τῷ Λούππῳ τὴν ἐπὶ τοιοῖσδε προύθεσαν λειτουργίαν, ὅπως μετασχὼν κἂν ἐπὶ τοιούτοις τῆς τυραννοκτονίας ἀγάλλοιτο ἀρετῇ πρὸς τῶν πολιτικῶν, ὡς καὶ τοῦ παντὸς ἐπιβουλεύματος δόξειε κοινωνεῖν τὸ πρῶτον συνθεμένων."},{"number":192,"text":"ἐνίοις δὲ τῶν συνωμοτῶν καὶ ὠμὸν ἐδόκει τὸ ἐπὶ τῇ γυναικὶ θράσει χρησόμενον αὐτῷ διὰ τὸ Γάιον φύσει τῇ αὐτοῦ χρώμενον ἢ συμβουλῇ τῇ ἐκείνης τὰ πάντα πρᾶξαι, ἐξ ὧν ἥ τε πόλις ἀπηγορεύκει τοῖς κατειληφόσι κακοῖς καὶ τῶν πολιτῶν ὅ τι καὶ ἄνθος ἦν ἀπώλετο."},{"number":193,"text":"οἱ δὲ καὶ τῶν μὲν ἐπὶ τοιούτοις ἐνεκάλουν αὐτῇ γνώμην τὸ δὲ πᾶν καὶ τῶν ὑπὸ Γαΐου πεπραγμένων κακῶν ἐκείνῃ τὴν αἰτίαν ἐπέφερον φάρμακον τῷ Γαΐῳ δοῦσαν ἐννοιῶν δούλωσιν καὶ ἐρώτων ἐπαγωγὰς αὐτῇ ψηφιούμενον, εἰς μανίαν μεταστάντος τὰ πάντα αὐτὴν εἶναι τὴν νεναυπηγημένην ἐπὶ ταῖς Ῥωμαίων τύχαις καὶ τῆς ὑποτελούσης αὐτοῖς οἰκουμένης."},{"number":194,"text":"καὶ πέρας κυρωθὲν ὥστε αὐτὴν τελευτᾶν, οὐδὲν γὰρ οἱ ἀποσπεύδοντες οἷοί τε ὠφελεῖν ἦσαν, ἐστέλλετο ὁ Λοῦππος· ἐβραδύνετο δὲ οὐδὲν μελλήσει τῇ κατʼ αὐτόν, ὥστε μὴ οὐκ εἰς καιρὸν δεδιακονῆσθαι τοῖς ἀπεσταλκόσιν, θέλων ἐπʼ οὐδαμοῖς μεμπτὸς εἶναι τῶν ἐπʼ ὠφελείᾳ τοῦ δήμου πεποιημένων."},{"number":195,"text":"παρελθὼν δὲ ἐπὶ τοῦ βασιλείου λαμβάνει τὴν Καισωνίαν, γυνὴ δʼ ἦν τοῦ Γαΐου, παρακατακειμένην τῷ σώματι τοῦ ἀνδρὸς χαμαιπετεῖ καὶ πάντων ἐν ἀτυχίᾳ ὧν χαρίζοιτʼ ἂν ὁ νόμος τοῖς μεταστᾶσιν, αἵματί τε ἀναπεφυρμένην ἐκ τῶν τραυμάτων καὶ πολλῇ τῇ ταλαιπωρίᾳ συμφερομένην τῆς θυγατρὸς παρερριμμένης· ἠκούετό τε ἐν τοῖς τοιοῖσδε οὐδὲν ἕτερον ἢ κατάμεμψις τοῦ Γαΐου, ὡς πιθανὴν οὐ σχόντος πολλάκις προηγορευκυῖαν αὐτήν."},{"number":196,"text":"ἐπʼ ἀμφότερα δὲ οὗτος ὁ λόγος καὶ τότε εἰκάζετο καὶ νῦν ἐφʼ ὁμοίοις πρόκειται τῇ διανοίᾳ τῶν ἀκροατῶν πρὸς ὅ τι θελήσειαν ῥοπὰς τὰς αὐτοῦ προστιθέμενοι. οἱ μὲν γὰρ ἀποσημαίνειν ἔφασαν τὸν λόγον, ὡς συμβουλευομένης ἀποστάντα μανιῶν καὶ τοῦ εἰς τοὺς πολίτας ὠμοῦ μετρίως καὶ μετʼ ἀρετῆς ἐξηγεῖσθαι τῶν πραγμάτων, καὶ παρʼ αὐτὸν ἀπολέσθαι τρόπῳ τῷ αὐτοῦ χρώμενον."},{"number":197,"text":"οἱ δέ, ὡς λόγου τοῦ περὶ τῶν συνωμοτῶν ἐπιφοιτήσαντος Γαΐῳ κελεύσειεν μηδὲν εἰς ἀναβολὰς ἀλλʼ ἐκ τοῦ ὀξέος πάντας μεταχειρισάμενον αὐτούς, κἂν εἰ μηδὲν ἀδικοῖεν, ἐν ἀδεεῖ κινδύνων καταστῆναι, καὶ τοῦτʼ εἶναι τὸ ἐπονειδιζόμενον, ὡς προηγορευκυίας διαπράξασθαι μαλακῷ γεγονότι."},{"number":198,"text":"καὶ τὰ μὲν λεχθέντα ὑπὸ τῆς Καισωνίας καὶ ὁποῖα οἱ ἄνθρωποι περὶ αὐτῆς ἐφρόνουν ταῦτα ἦν. ἡ δὲ ἐπεὶ θεᾶται τὴν πρόσοδον τοῦ Λούππου τό τε σῶμα τοῦ Γαΐου προυδείκνυεν καὶ ἆσσον ἰέναι παρεκάλει μετʼ ὀλοφυρμοῦ καὶ δακρύων."},{"number":199,"text":"ἐπεὶ δὲ τῇ διανοίᾳ συνεστηκότα ἑώρα τὸν Λοῦππον, καὶ μηδὲν προσιόντα ὡς ἐπὶ πρᾶξιν οὐκ αὐτῷ κεχαρισμένην, γνωρίσασα ἐφʼ ὅ τι ἐχώρει τήν τε σφαγὴν ἐγύμνου καὶ πάνυ προθύμως ποτνιωμένη ὁποῖα εἰκὸς τοὺς οὕτω σαφῶς ἐν ἀπογνώσει τοῦ ζῆν γεγονότας καὶ κελεύουσα μὴ μέλλειν ἐπὶ τελειώσει τοῦ δράματος οὗ ἐπʼ αὐτοῖς συνέθεσαν."},{"number":200,"text":"καὶ ἥδε μὲν εὐψύχως ταύτῃ τελευτᾷ ὑπὸ τοῦ Λούππου καὶ ἐπʼ αὐτῇ τὸ θυγάτριον. καὶ Λοῦππος ταῦτα προαπαγγέλλων ἔσπευδεν τοῖς περὶ τὸν Χαιρέαν."},{"number":201,"text":"Γάιος μὲν δὴ τέταρτον ἐνιαυτὸν ἡγεμονεύσας Ῥωμαίων λείποντα τεσσάρων μηνῶν οὕτως τελευτᾷ, ἀνὴρ καὶ πρότερον ἢ τῇ ἀρχῇ συνῆλθεν σκαιός τε καὶ κακοτροπίας εἰς τὸ ἄκρον ἀφιγμένος, ἡδονῇ τε ἡσσώμενος καὶ φίλος διαβολῇ, καὶ τὰ μὲν φοβερὰ καταπεπληγμένος καὶ διὰ τοῦτο ἐφʼ οἷς θαρσήσειε φονικώτατος, τῆς τε ἐξουσίας ἐφʼ ἑνὶ μόνῳ πιμπλάμενος τῷ ὑβρίζειν, εἰς οὓς ἥκιστα ἐχρῆν ἀλόγῳ μεγαλοψυχίᾳ χρώμενος καὶ ποριστὴς ἐκ τοῦ κτείνειν καὶ παρανομεῖν."},{"number":202,"text":"καὶ τοῦ μὲν θείου καὶ νομίμου μείζων ἐσπουδακὼς εἶναί τε καὶ δοκεῖν, ἡσσώμενος δὲ ἐπαίνων τῆς πληθύος καὶ πάντα, ὁπόσα αἰσχρὰ κρίνας ὁ νόμος ἐπιτιμᾷ τιμωρίαν, ἐνόμισεν ἀρετῆς."},{"number":203,"text":"καὶ φιλίας ἀμνήμων, εἰ καὶ πλείστη τε καὶ διὰ μεγίστων γένοιτο, οἷς τότε ὀργισθείη ἐκπλήξει κολάσεως καὶ ἐλαχίσταις, πολέμιον δὲ ἡγούμενος πᾶν τὸ ἀρετῇ συνερχόμενον, ἀναντίλεκτον ἐπὶ πᾶσιν οἷς κελεύσειε τὴν ἐπιθυμίαν λαμβάνων·"},{"number":204,"text":"ὅθεν καὶ ἀδελφῇ γνησίᾳ συνῆν, ἐξ οὗ καὶ μάλιστα αὐτῷ φύεσθαι παρὰ τοῖς πολίταις ἤρξατο σφοδρότερον τὸ μῖσος διὰ τὸ πολλοῦ χρόνου μὴ ἱστορημένον εἴς τε ἀπιστίαν καὶ ἔχθραν τὴν πρὸς τὸν πράξαντα παρακαλεῖν."},{"number":205,"text":"ἔργον δὲ μέγα ἢ βασίλειον οὐδὲν αὐτῷ πεπραγμένον εἴποι ἄν τις ἢ ἐπʼ ὠφελείᾳ τῶν συνόντων καὶ αὖθις ἀνθρώπων ἐσομένων, πλήν γε τοῦ περὶ Ῥήγιον καὶ Σικελίαν ἐπινοηθέντος ἐν ὑποδοχῇ τῶν ἀπʼ Αἰγύπτου σιτηγῶν πλοίων·"},{"number":206,"text":"τοῦτο δὲ ὁμολογουμένως μέγιστόν τε καὶ ὠφελιμώτατον τοῖς πλέουσιν· οὐ μὴν ἐπὶ τέλος γε ἀφίκετο, ἀλλʼ ἡμίεργον ὑπὸ τοῦ ἀμβλυτέρως αὐτῷ ἐπιπονεῖν κατελείφθη."},{"number":207,"text":"αἴτιον δʼ ἦν ἡ περὶ τὰ ἀχρεῖα σπουδὴ καὶ τὸ δαπανῶντα εἰς ἡδονάς, αἳ καταμόνας ἔμελλον ὠφελεῖν, αὐτῷ ὑφαιρεῖν τῆς ἐπὶ τοῖς κρείσσοσιν ἀνωμολογημένοις φιλοτιμίας."},{"number":208,"text":"ἄλλως δὲ ῥήτωρ τε ἄριστος καὶ γλώσσῃ τῇ Ἑλλάδι καὶ τῇ Ῥωμαίοις πατρίῳ σφόδρα ἠσκημένος συνίει τʼ ἐκ τοῦ παραχρῆμα καὶ τοῖς ὑφʼ ἑτέρων συντεθεῖσίν τε καὶ ἐκ πλείονος προσυγκειμένοις ἀντειπὼν ἐκ τοῦ ὀξέος φανῆναι πιθανώτερος ἐν μεγίστῳ πράγματι παρʼ ὁντινοῦν γενόμενος, εὐκολίᾳ τε εἰς αὐτὸ τῆς φύσεως καὶ τῷ εἰς ἰσχὺν αὐτῇ προσλαβεῖν μελέτην τοῦ ἐπιπονεῖν."},{"number":209,"text":"ἀδελφοῦ γὰρ παιδὸς υἱεῖ γεγονότι Τιβερίου, οὗ καὶ διάδοχος γίνεται, μέγα ἀνάγκασμα παιδείας ἀντέχεσθαι διὰ τὸ καὶ αὐτὸς εἰς τὰ πρῶτα ἐν αὐτῇ κατορθῶν διαπρέπειν, καὶ συνεφιλοκάλει Γάιος συγγενοῦς τε ἀνδρὸς καὶ ἡγεμόνος εἴκων ἐπιστολαῖς ἐπρώτευσέν τε τῶν κατʼ αὐτὸν πολιτῶν."},{"number":210,"text":"οὐ μὴν ἀντισχεῖν οἷά τε ἐγένετο αὐτῷ τὰ ἐκ τῆς παιδείας συλλεγέντα ἀγαθὰ πρὸς τὸν ἐπελθόντα ὄλεθρον αὐτῷ ὑπὸ τῆς ἐξουσίας· οὕτως ἄρα δυσπόριστον ἡ ἀρετὴ τοῦ σωφρονεῖν, οἷς ἀνυπεύθυνον τὸ πράσσειν ῥᾳστώνῃ πάρεστιν."},{"number":211,"text":"φίλοις μὲν κεχρῆσθαι καὶ πάντα ἀξιολόγοις ὑποσπουδασθεὶς τὸ κατʼ ἀρχὰς ὑπό τε παιδείας καὶ δόξης ζήλου τῶν κρειττόνων, μέχρι δὴ τῷ περιόντι τοῦ ὑβρίζειν ἀπαμφίασις εὐνοίᾳ τῇ πρὸς αὐτὸν ἐχρήσαντο μίσους ὑποφυέντος ὑπʼ αὐτῶν ἐπιβουλευθεὶς τελευτᾷ."}],"3":[{"number":212,"text":"Κλαύδιος δέ, καθάπερ ἀνώτερον ἔφην, ἀπορρήξεως αὐτῷ τῶν Γαΐου ὁδῶν γενομένης καὶ τοῦ οἴκου θορυβηθέντος πάθει τῆς Καίσαρος τελευτῆς, ἐν ἀμηχάνοις ὢν περὶ τῆς σωτηρίας ἔν τινι στενωπῷ κατειλημμένος ἔκρυπτεν ἑαυτὸν οὐδεμίαν κινδύνων αἰτίαν πλὴν τῆς γενναιότητος ὑφορώμενος·"},{"number":213,"text":"μέτριον γὰρ ἰδιώτης ὢν ἦγεν αὑτὸν καὶ τοῖς πᾶσιν ἀρκῶν ἦν, παιδείᾳ τε συνιὼν καὶ μάλιστα τῇ Ἑλληνίδι καὶ παντὸς τοῦ εἰς θόρυβον ἀνακειμένου παντοίως ἀπαλλάσσων αὑτόν."},{"number":214,"text":"τότε δὲ πτοίας κατειληφυίας τὸν ὄχλον καὶ τοῦ βασιλείου παντὸς στρατιωτικῆς μανίας ἀνάπλεω γεγονότος καὶ δειλίας καὶ ἀταξίας ἰδιωτῶν οἷον ἀπειληφότων σωματοφυλάκων, οἱ περὶ τὸ στρατηγικὸν καλούμενον, ὅπερ ἐστὶ τῆς στρατιᾶς καθαρώτατον, ἐν βουλῇ περὶ τοῖς πρακτέοις ἦσαν, ὅσοι δὲ καὶ παρετύγχανον, τὴν μὲν Γαΐου τιμωρίαν ἐν ὀλίγῳ τιθέμενοι διὰ τὸ κατὰ δίκην αὐτῷ τὰς τύχας συνελθεῖν,"},{"number":215,"text":"τὰ δὲ περὶ αὐτοὺς ἀνεσκοποῦντο μᾶλλον ὃν τρόπον σχήσοι καλῶς καὶ τῶν Γερμανῶν τε ἐν τιμωρίαις τῶν σφαγέων ὄντων ὠμότητος χάριτι τῆς ἑαυτῶν μᾶλλον ἢ τοῦ συμφέροντος τοῖς πᾶσιν."},{"number":216,"text":"ὑφʼ ὧν ἁπάντων ὁ Κλαύδιος ἐθορυβεῖτο δεδιὼς περὶ τῆς σωτηρίας, ἄλλως τʼ ἐπειδὴ καὶ τῶν περὶ τὸν Ἀσπρήναν ἐτεθέατο τὰς κεφαλὰς παραφερομένας· εἱστήκει δὲ κατά τι προσβατὸν ὀλίγαις βαθμῖσι χωρίον ὑπεσταλκὼς τῷ κατʼ αὐτὸ σκότῳ."},{"number":217,"text":"καὶ Γρᾶτος τῶν περὶ τὸ βασίλειόν τις στρατιωτῶν θεασάμενος καὶ τοῦ μὲν ἀκριβωσομένου τὴν ὄψιν ἀμαθὴς ὢν διὰ τὸν σκότον, τοῦ δὲ ἄνθρωπον εἶναι τὸν ὑπολοχῶντα κριτὴς εἶναι μὴ ἀπηλλαγμένος, προσῄει τε ἐγγύτερον καὶ ὑποχωρεῖν ἠξιωκότος ἐπέκειτο καὶ καταλαβὼν ἐπιγνωρίζει Γερμανικὸς μὲν οὗτος, φησὶν πρὸς τοὺς ἑπομένους, καὶ στησώμεθα τοῦτον ἡγεμόνα φερόμενοι."},{"number":218,"text":"Κλαύδιος δὲ ἐφʼ ἁρπαγῇ παρεσκευασμένους ὁρῶν καὶ δείσας, μὴ κατὰ φωνὴν ἀποθάνοι τὴν Γαΐου, φειδὼ σχεῖν ἠξίου τοῦ κατʼ αὐτὸν ἀνεπαχθοῦς ἀνάμνησιν αὐτοῖς ὑποτιθεὶς καὶ τοῦ ἀπρομηθοῦς τῶν γεγονότων."},{"number":219,"text":"καὶ ὁ Γρᾶτος μειδιάσας ἐπισπᾶται τῆς δεξιᾶς, καί παῦσαι, φησίν, μικρολογούμενος περὶ τῆς σωτηρίας δέον σε μεγαλοφρονεῖσθαι περὶ τῆς ἡγεμονίας, ἣν οἱ θεοὶ Γάιον ἀφῃρημένοι τῇ σῇ συνεχώρησαν ἀρετῇ πρόνοιαν τῆς οἰκουμένης λαβόντες. ἀλλʼ ἴθι καὶ τῶν προγόνων ἀπολάμβανε τὸν θρόνον."},{"number":220,"text":"ἀνεβάσταζέν τε αὐτὸν οὐ πάνυ τοῖς ποσὶ βαίνειν δυνάμενον ὑπό τε φόβου καὶ χάρματος τῶν εἰρημένων."},{"number":221,"text":"Συνεστρέφοντο δὲ περὶ τὸν Γρᾶτον ἤδη καὶ πλείους τῶν σωματοφυλάκων καὶ θεωροῦντες τὸν Κλαύδιον ἀγόμενον δόξῃ τοῦ ἐπὶ κόλασιν ἕλκεσθαι τῶν ἐπὶ τοιοῖσδε ζημιῶν ὡς ἄνδρα ἀπράγμονα διὰ βίου τοῦ παντὸς καὶ κινδύνοις οὔτι μετρίως ἐπὶ τῆς Γαΐου ἀρχῆς ὡμιληκότα, τινὲς δὲ καὶ αὐτῶν τοῖς ὑπάτοις ἐντρέπειν κρίσιν ἠξίουν τὴν περὶ αὐτόν."},{"number":222,"text":"καὶ πλειόνων τοῦ στρατιωτικοῦ συστρεφομένων φυγαί τε ἦσαν τοῦ ὁμίλου καὶ προόδων ἀπορία τῷ Κλαυδίῳ διʼ ἀσθένειαν τοῦ σώματος, ἐπεὶ καὶ οἱ τὸ φορεῖον αὐτοῦ φέροντες περὶ τὴν ἁρπαγὴν αὐτοῦ παραγενομένης φυγῆς ἔσωζον αὑτοὺς ἀπʼ ἐλπίδος θέμενοι τὴν σωτηρίαν τοῦ δεσπότου."},{"number":223,"text":"ἐν εὐρυχωρίᾳ δὲ τοῦ Παλατίου γενομένοις, πρῶτον δὲ οἰκηθῆναι τῆς Ῥωμαίων πόλεως τοῦτο παραδίδωσιν ὁ περὶ αὐτῆς λόγος, καὶ ἤδη τοῦ δημοσίου ἀντιλαμβανομένοις πολὺ πλείων ἡ ἐπιφοίτησις ἦν τῶν στρατιωτῶν χαρᾷ τὴν ὄψιν δεχομένοις τοῦ Κλαυδίου, περὶ πλείστου τε ἦν αὐτοῖς αὐτοκράτορα στήσασθαι τὸν ἄνθρωπον εὐνοίᾳ τε τῇ Γερμανικοῦ, ἀδελφὸς δὲ ἦν αὐτοῦ ἐπὶ μέγα πᾶσιν τοῖς ὡμιληκόσιν καταλελοιπὼς κλέος τὸ αὐτοῦ."},{"number":224,"text":"ἀναλογισμός τε αὐτοὺς εἰσῄει τῆς τε πλεονεξίας τῶν ἐν τῇ συγκλήτῳ δυναστευόντων καὶ ὁπόσα ἐπὶ τῆς πρὶν ἀρχῆς ἡμάρτητο αὐτῇ."},{"number":225,"text":"πρὸς δὲ καὶ τὸ ἀμήχανον τοῦ πράγματος κατενόουν, καὶ πάλιν εἰς ἑνὸς ἀρχὴν μεθισταμένων τῶν ὅλων κινδύνους αὐτοῖς φέρειν διʼ ἑνὸς κτησαμένου τὴν ἀρχὴν μεθισταμένων τῶν ὅλων παρʼ ὃν ἐπιχωρήσει καὶ εὐνοίᾳ τῇ αὐτῶν λαβόντα Κλαύδιον μνημονεύσεις τε χάριτος αὐτοῖς ἀποδιδόντα τιμήν, ἣ ἐπὶ τοιούτοις γένοιτʼ ἂν ἀρκοῦσα."},{"number":226,"text":"Ταῦτα πρός τε ἀλλήλους καὶ διʼ ἑαυτοὺς διεξῄεσαν καὶ τοῖς ἀεὶ προσπίπτουσιν διηγοῦντο. οἱ δὲ πυνθανόμενοι προθύμως ἐδέχοντο τὴν πρόκλησιν, συμφράξαντές τε καὶ περικλάσαντες ἦγον ἐπὶ τοῦ στρατοπέδου φοράδην ἀναβαστάσαντες, ὡς μὴ ἐμποδίζοιτο αὐτοῖς ἡ ἔπειξις."},{"number":227,"text":"διειστήκεσαν δὲ αἱ γνῶμαι τοῦ δήμου καὶ τῶν ἐκ τῆς βουλῆς· οἱ μὲν ἀξιώματός τε τοῦ πρότερον ὀρεγόμενοι καὶ δουλείαν ἔπακτον αὐτοῖς ὕβρει τῶν τυράννων γενομένην φιλοτιμούμενοι διαδιδράσκειν χρόνῳ παρασχόν,"},{"number":228,"text":"ὁ δὲ δῆμος φθόνῳ τε πρὸς ἐκείνην καθιστάμενος καὶ τῶν πλεονεξιῶν αὐτῆς ἐπιστόμισμα τοὺς αὐτοκράτορας εἰδὼς καὶ αὐτοῦ καταφυγὴν ἔχαιρεν Κλαυδίου τῇ ἁρπαγῇ στάσιν τε ἔμφυλον, ὁποία καὶ ἐπὶ Πομπηίου γένοιτο, ἀπαλλάξειν αὐτῶν ὑπελάμβανον τοῦτον αὐτοκράτορα καθισταμένου."},{"number":229,"text":"γνοῦσα δʼ ἡ βουλὴ τὸν Κλαύδιον ὑπὸ τῶν στρατιωτῶν ἀφιγμένον εἰς τὸ στρατόπεδον πέμπει πρὸς ἐκεῖνον ἄνδρας ἀρετῇ τοὺς ἐξ αὐτῶν, οἳ διδάξειαν μὴ δεῖν ἐπὶ καθέξει τῆς ἀρχῆς βιάζεσθαι,"},{"number":230,"text":"παραχωρεῖν δὲ τῇ συγκλήτῳ τοσῶνδε ἀνδρῶν ἕνα ὄντα ἡσσώμενον καὶ τῷ νόμῳ παραχωροῦντα τοῦ ἐπὶ τοῖς κοινοῖς κόσμου τὴν πρόνοιαν, μνημονεύοντα ὧν οἱ πρότεροι τύραννοι κακώσειαν τὴν πόλιν καὶ ὧν ὑπὸ Γαΐου καὶ αὐτὸς κινδυνεύσειεν σὺν αὐτοῖς, μηδὲ μισήσαντα τὴν βαρύτητα τῆς τυραννίδος ὑφʼ ἑτέρων πρασσομένης τῆς ὕβρεως αὐτὸν ἐθελουσίως ἐπὶ παροινίᾳ θαρσεῖν τῆς πατρίδος."},{"number":231,"text":"καὶ πειθομένῳ μὲν τοῦ πρότερον ἀπράγμονος τὴν ἀρετὴν ἐπιδεικνυμένῳ βέβαιον τιμάς τε ὑπάρξειν, αἳ ὑπὸ ἐλευθέρων ψηφισθεῖεν τῶν πολιτῶν, καὶ ἐπιχωρήσει τοῦ νόμου τὸ μέρος ἄρχοντά τε καὶ ἀρχόμενον κερδανεῖν ἔπαινον ἀρετῆς."},{"number":232,"text":"εἰ δὲ ἀπονοοῖτο μηδὲν ἐκ τῆς Γαΐου τελευτῆς σωφρονιζόμενος οὔτι γε αὐτοὶ ἐπιτρέψειν τῆς τε γὰρ στρατιᾶς πολὺ εἶναι τὸ συνεστηκὸς αὐτοῖς ὅπλων τε εὐπορίαν καὶ πληθὺν οἰκετῶν, οἳ χρήσαιντο αὐτοῖς."},{"number":233,"text":"μέγα δὲ μέρος τήν τε ἐλπίδα εἶναι καὶ τὴν τύχην, τούς τε θεοὺς οὐκ ἄλλοις συμμαχεῖν, ἀλλὰ τοῖς μετʼ ἀρετῆς καὶ τοῦ καλοῦ τοὺς ἀγῶνας ποιουμένοις. εἶναι δὲ τούτους, οἳ ἂν περὶ ἐλευθερίας μάχωνται τῆς πατρίδος."},{"number":234,"text":"Καὶ οἱ μὲν πρεσβευταὶ Οὐηράνιός τε καὶ Βρόγχος, δήμαρχοι δὲ ἦσαν ἀμφότεροι, τοῖσδε ἐχρῶντο τοῖς λόγοις καὶ καθικέτευον τοῖς γόνασιν αὐτοῦ προσπεσόντες μηδαμῶς πολέμοις καὶ κακοῖς ἐμβαλεῖν τὴν πόλιν, θεωροῦντες στρατιᾶς πληθύι τὸν Κλαύδιον πεφραγμένον καὶ τὸ μηδὲν τοὺς ὑπάτους ὄντας συγκρίσει τῇ πρὸς αὐτόν."},{"number":235,"text":"εἴ τε τῆς ἀρχῆς ὀρέγοιτο, παρὰ τῆς βουλῆς δέχεσθαι διδομένην· αἰσιώτερον γὰρ καὶ εὐδαιμονέστερον χρῆσθαι τὸν μὴ μετὰ ὕβρεως ἀλλʼ εὐνοίᾳ τῶν διδόντων παραλαμβάνοντα."}],"4":[{"number":236,"text":"Κλαύδιος δέ, ἠπίστατο γὰρ μεθʼ οἵας αὐθαδείας ἀποσταλεῖεν, καὶ πρὸς τὸ παρὸν γνώμῃ τῇ αὐτῶν ἐπὶ τὸ μετριώτερον τρεπόμενος, οὐ μὴν ἀλλὰ καὶ τῷ περὶ αὐτοὺς φόβῳ διαναστὰς ἅμα μὲν θάρσει τῶν στρατιωτῶν ἅμα δὲ Ἀγρίππου τοῦ βασιλέως κελεύοντος μὴ προέσθαι τῶν χειρῶν τηλικαύτην ἀρχὴν ἥκουσαν αὐτόματον."},{"number":237,"text":"πράξας μὲν καὶ περὶ Γάιον οἷον εἰκὸς ἄνδρα ὑπʼ αὐτοῦ διὰ τιμῆς ἠγμένον, καὶ γὰρ τὸν νεκρὸν περιέσπεν τοῦ Γαΐου καὶ ἀναθέμενος ἐπὶ κλίνης καὶ περιστείλας ἐκ τῶν ἐνδεχομένων εἰς τοὺς σωματοφύλακας ὑπεχώρει, ζῆν μὲν τὸν Γάιον ἀπαγγέλλων κακοπαθοῦντί γε ὑπὸ τραυμάτων ἰατροὺς μετέσεσθαι λέγων·"},{"number":238,"text":"πυθόμενος δὲ τοῦ Κλαυδίου τὴν ὑπὸ τῶν στρατιωτῶν ἁρπαγὴν ὠθεῖτο πρὸς αὐτὸν καὶ καταλαβὼν τεταραγμένον καὶ οἷόν τε ἐκχωρεῖν τῇ συγκλήτῳ ἀνήγειρεν ἀντιλαμβάνεσθαι κελεύων τῆς ἡγεμονίας."},{"number":239,"text":"ταῦτα δὲ πρὸς τὸν Κλαύδιον εἰπὼν προσεχώρει πρὸς αὐτόν, καὶ μετακαλούσης αὐτὸν τῆς βουλῆς χρισάμενος μύροις τὴν κεφαλὴν ὡς ἀπὸ συνουσίας γινομένης ἀναλύσεως αὐτῷ παρῆν καὶ ἤρετο τοὺς βουλευτάς, τί πέπραχε Κλαύδιος."},{"number":240,"text":"τῶν δὲ τὰ ὄντα φαμένων καὶ προσανερομένων, ἥντινα γνώμην ἔχοι περὶ τοῖς ὅλοις, τελευτᾶν μὲν ὑπὲρ τοῦ κατʼ ἐκείνην εὐκλεοῦς ἕτοιμος ἦν τοῖς λόγοις, σκοπεῖν δὲ ἐκέλευε περὶ τῷ συμφέροντι πᾶν ὅ τι καὶ εἰς ἡδονὴν φέροι ὑπεξελομένους·"},{"number":241,"text":"χρείαν γὰρ εἶναι τοῖς ἀρχῆς μεταποιουμένοις καὶ ὅπλων καὶ στρατιωτῶν, οἳ φράξαιντο αὐτοῖς, μὴ καὶ ἀπαράσκευοι καταστάντες εἰς τάδε σφαλεῖεν."},{"number":242,"text":"ἀποκριναμένης δὲ τῆς βουλῆς ὅπλων τε εὐπορίαν καὶ χρήματα εἰσοίσειν, καὶ στρατιᾶς τὸ μέν τι αὐτοῖς εἶναι συνεστηκός, τὸ δὲ συγκροτήσειν ἐλευθερώσεως δούλων γενομένης. εἴη μέν, ὦ βουλή, φησὶν ὁ Ἀγρίππας ὑποτυχών, πράσσειν ὁπόσα θυμὸς ὑμῖν, λεκτέον δὲ οὐδὲν ἐνδοιάσαντί μοι διὰ τὸ ἐπὶ σωτηρίᾳ φέρειν τὸν λόγον."},{"number":243,"text":"ἴστε μὴν στρατόν, ὃς ὑπὲρ Κλαυδίου μαχεῖται, πλήθει χρόνου ὁπλιτεύειν μεμελετηκότα, τὰ δʼ ἡμέτερα, συγκλύδων ἀνθρώπων πλῆθος δʼ ἔσται καὶ τῶν παρὰ δόξαν τῆς δουλείας ἀπηλλαγμένων, δυσκράτητα. πρὸς δὲ τεχνίτας μαχούμεθα προαγαγόντες ἄνδρας μηδʼ ὅπως σπάσαι τὰ ξίφη εἰδότας."},{"number":244,"text":"ὥστε μοι δοκεῖ πέμπειν ὡς Κλαύδιον πείσοντας κατατίθεσθαι τὴν ἀρχήν, πρεσβεύειν τε ἕτοιμός εἰμι."},{"number":245,"text":"Καὶ ὁ μὲν ταῦτα εἶπεν, καὶ συγκαταθεμένων πεμφθεὶς σὺν ἑτέροις τήν τε ταραχὴν τῆς βουλῆς διηγεῖται καταμόνας πρὸς τὸν Κλαύδιον ἐδίδασκέν τε ἡγεμονικώτερον ἀποκρίνασθαι καὶ τῷ ἀξιώματι τῆς ἐξουσίας χρώμενον."},{"number":246,"text":"ἔλεγεν οὖν Κλαύδιος, οὐ θαυμάζειν τὴν βουλὴν ἡδονῇ μὴ φέρουσαν ἄρχεσθαι διὰ τὸ ὠμότητι τετρῦσθαι τῶν πρότερον ἐπὶ τὸ ἡγεμονεύειν καταστάντων, γεύσειν τε αὐτοὺς ἐπιεικείᾳ τῇ καθʼ αὑτὸν μετρίων καιρῶν, ὀνόματι μὲν μόνῳ τῆς ἀρχῆς ἐσομένης, ἔργῳ δὲ κοινῆς πᾶσι προκεισομένης εἰς μέσον. διὰ πολλῶν δὲ καὶ ποικίλων ὡδευκότι πραγμάτων ἐν ὄψει τῇ ἐκείνων καλῶς ἔχειν μὴ ἀπιστεῖν."},{"number":247,"text":"καὶ οἱ μὲν πρέσβεις τοιούτων ἀκροάσει λόγων καθομιληθέντες ἐξεπέμποντο. Κλαύδιος δὲ τῷ στρατῷ συλλεχθέντι διελέγετο ὅρκους λαμβάνων ἦ μὴν ἐμμενεῖν πίστει τῇ πρὸς αὐτόν, δωρεῖται τοὺς σωματοφύλακας πεντακισχιλίαις δραχμαῖς κατὰ ἕκαστον ἄνδρα, τοῖς τε ἡγεμόσιν αὐτῶν ἀνάλογον τοῦ ἀριθμοῦ καὶ τοῖς ὅποι ποτὲ στρατοπέδοις ὑπισχνεῖτο τὰ ὅμοια."},{"number":248,"text":"Συνεκάλουν δὲ οἱ ὕπατοι τὴν βουλὴν εἰς τὸ ἱερὸν τοῦ νικηφόρου Διός· ἔτι δὲ νὺξ ἦν. τῶν δὲ οἱ μὲν ἐν τῇ πόλει κλέπτοντες ἑαυτοὺς ἐνεδοίαζον πρὸς τὴν ἀκρόασιν, τοῖς δὲ ἐπὶ τῶν ἰδίων ἀγρῶν ἐγεγόνεισαν ἔξοδοι προορωμένοις ᾗ χωρήσει τὸ πᾶν ἐν ἀπογνώσει τοῦ ἐλευθέρου γεγονότος, καὶ πολὺ κρεῖττον ἐν ἀκινδύνῳ τοῦ δουλεύειν ὑπειληφότες διαβιοῦν ἀργίᾳ τοῦ πονεῖν ἢ κτώμενοι τὸ ἀξίωμα τῶν πατέρων περὶ τῆς σωτηρίας ἀμφίβολοι καταστῆναι."},{"number":249,"text":"συνελέγησαν δʼ ὅμως ἑκατὸν οὐ πλείους, καὶ διαβουλευομένων περὶ τῶν ἐν χερσὶν αἰφνίδιον αἴρεται βοὴ τοῦ συνεστηκότος αὐτοῖς στρατιωτικοῦ στρατηγὸν αὐτοκράτορα κελευόντων τὴν βουλὴν ἑλέσθαι καὶ μὴ φθείρειν πολυαρχίᾳ τὴν ἡγεμονίαν."},{"number":250,"text":"καὶ τὸ μὲν καθʼ ἑαυτοὺς ἀπεφαίνοντο περὶ τοῦ μὴ πᾶσιν, ἀλλʼ ἑνὶ τὴν ἀρχὴν ἐφέσιμον εἶναι, ὁρᾶν δὲ ἐκείνοις ἐπιτρέπειν, ὅστις τοσαύτης προστασίας ἄξιος. ὥστε ἐν ἀνίᾳ τὰ τῶν συγκλητικῶν ἦν πολὺ πλέον διʼ ἁμαρτίαν μὲν τοῦ κατὰ τὴν ἐλευθερίαν αὐχήματος, φόβῳ δὲ τοῦ Κλαυδίου."},{"number":251,"text":"οὐ μὴν ἀλλʼ ἦσαν οἱ ἐφιέμενοι γένους τε ἀξιώματι καὶ οἰκειότησιν γάμου· καὶ γὰρ Μινουκιανὸς Μᾶρκον καὶ τὸ καθʼ αὑτὸν γενναιότητι ἀξιόλογον ὄντα καὶ δὴ ἀδελφὴν Γαΐου γεγαμηκότα Ἰουλίαν, πρόθυμός τε ἦν ἀντιποιεῖσθαι τῶν πραγμάτων, κατεῖχον δὲ οἱ ὕπατοι πρόφασιν ἐκ προφάσεως ἀναρτῶντες."},{"number":252,"text":"Οὐαλέριον δὲ Ἀσιατικὸν Μινουκιανὸς ἐκ τῶν Γαΐου σφαγέων ἀνεῖχε τοιούτων διανοιῶν. ἐγεγόνει δʼ ἂν φόνος οὔ τινος ἐλάσσων ἐπιχωρηθέντων τῶν ἐπιθυμούντων τῆς ἡγεμονίας, ὥστε ἀντιτάξασθαι Κλαυδίῳ, ἄλλως τε καὶ οἱ μονομάχοι,"},{"number":253,"text":"πλῆθος δʼ ἦν αὐτῶν ἀξιόλογον, καὶ τῶν στρατιωτῶν οἱ νυκτοφυλακοῦντες ἐπὶ τῆς πόλεως ἐρέται τε ὁπόσοι συνέρρεον εἰς τὸ στρατόπεδον, ὥστε τῶν μετιόντων τὴν ἀρχὴν οἱ μὲν φειδοῖ τῆς πόλεως, οἱ δὲ καὶ φόβῳ τῷ ὑπὲρ αὐτῶν ἀπέστησαν."},{"number":254,"text":"Ὑπὸ δὲ πρώτην ἀρχὴν τῆς ἡμέρας καὶ Χαιρέας καὶ οἱ σὺν αὐτῷ παρελθόντες ἐν ἐπιχειρήσει λόγων ἦσαν πρὸς τοὺς στρατιώτας. τῶν δὲ τὸ πλῆθος ὡς ὁρᾷ παύοντας αὐτοὺς ταῖς χερσὶ καὶ τοῦ εἰπεῖν οἵους τε ἄρχεσθαι, ἀνεθορύβησεν μὴ ἐφιέναι ὥστε εἰπεῖν διὰ τὸ ὡρμῆσθαι πάντας ἐπὶ τῷ μοναρχεῖσθαι, τὸν δὲ ἡγησόμενον ἐκάλουν ὡς οὐκ ἀνεξόμενοι τὰς τριβάς."},{"number":255,"text":"τῇ συγκλήτῳ δὲ ἀπορία ἄρχειν τε καὶ ὃν ἀρχθεῖεν ἂν τρόπον οὔτε δεχομένων αὐτοὺς τῶν στρατιωτῶν καὶ τῶν Γαΐου σφαγέων συγχωρεῖν τοῖς στρατιώταις οὐκ ἐφιέντων."},{"number":256,"text":"ἐν τοιούτοις δὲ ὄντων Χαιρέας τὴν ὀργὴν οὐκ ἀνασχόμενος πρὸς τὴν αἴτησιν τοῦ αὐτοκράτορος δώσειν ἐπηγγέλλετο στρατηγόν, εἴ τις αὐτῷ σημεῖον παρὰ Εὐτύχου κομίσειεν."},{"number":257,"text":"ἦν δὲ ὁ Εὔτυχος οὗτος ἡνίοχος τοῦ καλουμένου πρασίνου περισπούδαστος Γαΐῳ, καὶ περὶ τὰς οἰκοδομὰς τῶν στάσεων τοῦ περὶ ἐκεῖνον ἱππικοῦ τὸ στρατιωτικὸν ἐτρίβετο ἀτίμοις ἐργασίαις ἐπικείμενον."},{"number":258,"text":"εἰς ἅπερ ὁ Χαιρέας ὠνείδιζεν αὐτοὺς καὶ ἕτερα πολλὰ τοιαῦτα, τήν τε κεφαλὴν κομιεῖν τοῦ Κλαυδίου· δεινὸν γάρ, εἰ μετὰ μανίαν παραφροσύνῃ δώσουσι τὴν ἡγεμονίαν."},{"number":259,"text":"οὐ μὴν διετράπησάν γε ὑπὸ τῶν λόγων, ἀλλὰ σπασάμενοι τὰς μαχαίρας καὶ τὰ σημεῖα ἀράμενοι ᾤχοντο ὡς τὸν Κλαύδιον κοινωνήσοντες τοῖς ὀμνύουσιν αὐτῷ. κατελείπετο δὲ ἥ τε σύγκλητος ἐπʼ ἐρημίας τῶν ἀμυνούντων καὶ οἱ ὕπατοι μηδὲν ἰδιωτῶν διαφέροντες."},{"number":260,"text":"ἔκπληξίς τε καὶ κατήφεια ἦν, οὐδʼ ὅτι χρήσαιντο αὐτοῖς τῶν ἀνθρώπων εἰδότων διὰ τὸ ἀνηρεθίσθαι τὸν Κλαύδιον ἐπʼ αὐτοῖς, ἀλλήλοις τε ἐλοιδοροῦντο, καὶ μετάμελος ἦν αὐτοῖς."},{"number":261,"text":"καὶ Σαβῖνος εἷς τῶν Γαΐου σφαγέων σφάζειν πρότερον αὑτὸν ἠπείλει παρελθὼν εἰς μέσους ἢ Κλαύδιον ἄρχοντα στήσεσθαι καὶ δουλοκρατίαν ἐπόψεσθαι καταλαβοῦσαν, τόν τε Χαιρέαν εἰς φιλοψυχίαν ἐπέπλησσεν, εἰ καταφρονήσας Γαΐου πρῶτος ἀγαθὸν ὑπολαμβάνοι τὸ ζῆν τῆς ἐλευθερίας οὐδʼ οὕτως ἀποδοθῆναι δυναμένης τῇ πατρίδι."},{"number":262,"text":"Χαιρέας δὲ περὶ μὲν τοῦ θνήσκειν ἐνδοιαστὸν οὐδὲν φρονεῖν ἔλεγεν, βούλεσθαι μέντοι διακωδωνίζειν διάνοιαν τὴν Κλαυδίου."},{"number":263,"text":"Καὶ οἱ μὲν ἐν τοῖσδε ἦσαν. ἐπὶ δὲ τοῦ στρατοπέδου πανταχόθεν ὠθεῖτο κατὰ θεραπείαν. καὶ τῶν ὑπάτων ὁ ἕτερος Κόιντος Πομπώνιος διʼ αἰτίας ἦν τῷ στρατιωτικῷ μᾶλλον ὡς ἐπʼ ἐλευθερίᾳ τὴν σύγκλητον παρακαλῶν, ὥρμησάν τε σπασάμενοι τὰ ξίφη, κἂν ἐπέπρακτο αὐτοῖς μὴ Κλαυδίου διακεκωλυκότος."},{"number":264,"text":"παρακαθίζεται δὲ αὐτῷ τὸν ὕπατον ἐξαρπάσας τοῦ κινδύνου, τῶν δὲ συγκλητικῶν ὅσον ἦν σὺν τῷ Κοΐντῳ οὐ μεθʼ ὁμοίας ἐδέχετο τιμῆς· τινὲς δὲ καὶ πληγὰς ἔλαβον αὐτῶν ἀνωθούμενοι τῆς πρὸς αὐτὸν ἐντεύξεως, Ἀπώνιος δὲ τραυματίας ἀνεχώρει, ἦν τε κίνδυνος περὶ πάντας αὐτούς."},{"number":265,"text":"καὶ Ἀγρίππας ὁ βασιλεὺς προσελθὼν τῷ Κλαυδίῳ ἀξιοῖ τοῖς συγκλητικοῖς ἠπιώτερον καταστῆναι· γενομένου γάρ τινος κακοῦ περὶ τὴν βουλὴν οὐχ ἕξειν ὧν ἄρξειεν ἑτέρων."},{"number":266,"text":"πείθεται δὲ Κλαύδιος καὶ συγκαλεῖ τὴν βουλὴν ἐπὶ τοῦ Παλατίου διὰ τῆς πόλεως φερόμενος παραπέμποντος αὐτὸν τοῦ στρατιωτικοῦ σὺν πολλῇ πάνυ κακώσει τῆς πληθύος."},{"number":267,"text":"προεξῄεσαν δὲ τῶν Γαΐου σφαγέων εἰς τὸ φανερώτερον Χαιρέας καὶ Σαβῖνος εἰργόμενοι προόδων κατʼ ἐπιστολὰς Πολλίωνος, ὃν μικρῷ πρότερον Κλαύδιος στρατηγὸν ᾕρητο τῶν σωματοφυλάκων."},{"number":268,"text":"Κλαύδιος δέ, ἐπείπερ εἰς τὸ Παλάτιον ἀφικνεῖται συναγαγὼν τοὺς ἑταίρους ψῆφον ἀνεδίδου περὶ Χαιρέου. τοῖς δὲ τὸ μὲν ἔργον λαμπρὸν ἐδόκει, ἀπιστίαν δʼ ἐπεκάλουν τῷ πεπραχότι καὶ αὐτῷ τιμωρίαν ἐπιβάλλειν δίκαιον ἡγοῦντο ἐπʼ ἀποτροπῇ τοῦ μέλλοντος χρόνου."},{"number":269,"text":"ἀπήγετο οὖν τὴν ἐπὶ θανάτῳ καὶ σὺν αὐτῷ Λοῦππός τε καὶ Ῥωμαίων πλείους. λέγεται δὲ Χαιρέας μεγαλοφρόνως ἐνεγκεῖν τὴν συμφορὰν οὐ μόνον τῷ κατʼ αὐτὸν ἀμεταπτώτῳ τοῦ σχήματος, ἀλλὰ καὶ οἷς ὀνειδίσειεν Λοῦππον εἰς δάκρυα ἐκτετραμμένον."},{"number":270,"text":"ἀποτιθεμένου γέ τοι τὴν στολὴν τοῦ Λούππου καὶ τὸ ῥῖγος αἰτιωμένου φησίν, ὡς οὐκ ἂν ἐναντία τοῦ Λούππου ποιήσαιτο πώποτε ῥῖγος. πλήθους τε ἀνθρώπων ἑπομένου κατὰ θέαν, ὡς ἧκεν ἐπὶ τὸ χωρίον, ἤρετο τὸν στρατιώτην, εἰ διὰ μελέτης αὐτῷ γεγόνοιεν αἱ σφαγαὶ ἢ εἰ πρῶτον ἔχοι τὸ ξίφος ἐκέλευε κομίζειν ᾧ Γάιον μεταχειρίσαιτο αὐτός·"},{"number":271,"text":"θνήσκει δὲ εὐδαιμόνως μιᾶς πληγῆς αὐτῷ γενομένης. Λοῦππος δὲ οὐ πάνυ δεξιῶς ὑπεξῆλθεν ἀθυμίᾳ καὶ πληγῶν πλειόνων γενομένων διὰ τὸ μαλακῶς τὸν τράχηλον παρασχεῖν."},{"number":272,"text":"Ὀλίγαις δὲ ὕστερον ἡμέραις ἐναγισμῶν ἐνεστηκότων Ῥωμαίων τὸ πλῆθος τοῖς αὐτῶν ἐπιφέροντες καὶ Χαιρέαν μοίραις ἐτίμησαν εἰς τὸ πῦρ τιθεμέναις, ἵλεων καὶ ἄμηνιν εἶναι τῆς εἰς αὐτὸν ἀχαριστίας παρακαλοῦντες. καὶ Χαιρέᾳ μὲν τοιαύτη τελευτὴ τοῦ βίου συνέτυχεν."},{"number":273,"text":"Σαβῖνος δὲ Κλαυδίου μὴ μόνον τῆς αἰτίας παραλύοντος αὐτὸν ἀλλὰ καὶ τὴν ἀρχὴν ἣν εἶχεν ἐφιέντος, ἄδικον ἡγεῖτο τὴν ἐκλειπίαν τῆς πρὸς τοὺς συνωμότας πίστεως, σφάζει ἑαυτὸν περιπεσὼν τῷ ξίφει μέχρι δὴ καὶ τὴν κώπην τῷ τραύματι συνελθεῖν."}],"5":[{"number":274,"text":"Κλαύδιος δὲ τοῦ στρατιωτικοῦ πᾶν ὅ τι ἦν ὕποπτον ἐκ τοῦ ὀξέος ἀποσκευασάμενος διάγραμμα προυτίθει τήν τε ἀρχὴν Ἀγρίππα βεβαιῶν, ἣν ὁ Γάιος παρέσχε, καὶ διʼ ἐγκωμίων ἄγων τὸν βασιλέα. προσθήκην τε αὐτῷ ποιεῖται πᾶσαν τὴν ὑπὸ Ἡρώδου βασιλευθεῖσαν, ὃς ἦν πάππος αὐτοῦ, Ἰουδαίαν καὶ Σαμάρειαν."},{"number":275,"text":"καὶ ταῦτα μὲν ὡς ὀφειλόμενα τῇ οἰκειότητι τοῦ γένους ἀπεδίδου· Ἄβιλαν δὲ τὴν Λυσανίου καὶ ὁπόσα ἐν τῷ Λιβάνῳ ὄρει ἐκ τῶν αὐτοῦ προσετίθει, ὅρκιά τε αὐτῷ τέμνεται πρὸς τὸν Ἀγρίππαν ἐπὶ τῆς ἀγορᾶς μέσης ἐν τῇ Ῥωμαίων πόλει."},{"number":276,"text":"Ἀντίοχον δὲ ἣν εἶχεν βασιλείαν ἀφελόμενος Κιλικίας μέρει τινὶ καὶ Κομμαγηνῇ δωρεῖται. λύει δὲ καὶ Ἀλέξανδρον τὸν ἀλαβάρχην φίλον ἀρχαῖον αὐτῷ γεγονότα καὶ Ἀντωνίαν αὐτοῦ ἐπιτροπεύσαντα τὴν μητέρα ὀργῇ τῇ Γαΐου δεδεμένον, καὶ αὐτοῦ υἱὸς Βερενίκην τὴν Ἀγρίππου γαμεῖ θυγατέρα."},{"number":277,"text":"καὶ ταύτην μέν, τελευτᾷ γὰρ Μᾶρκος ὁ τοῦ Ἀλεξάνδρου υἱὸς παρθένον λαβών, ἀδελφῷ τῷ αὐτοῦ Ἀγρίππας Ἡρώδῃ δίδωσιν Χαλκίδος αὐτῷ τὴν βασιλείαν εἶναι αἰτησάμενος παρὰ Κλαυδίου."},{"number":278,"text":"Στασιάζεται δὲ κατʼ αὐτὸν τὸν χρόνον Ἰουδαίων τὰ πρὸς Ἕλληνας ἐπὶ τῆς Ἀλεξανδρέων πόλεως. τελευτήσαντος γὰρ τοῦ Γαΐου τὸ Ἰουδαίων ἔθνος ἐπὶ ἀρχῆς τῆς ἐκείνου τεταπεινωμένον καὶ δεινῶς ὑπὸ τῶν Ἀλεξανδρέων ὑβρισμένον ἀνεθάρσησέ τε καὶ ἐν ὅπλοις εὐθέως ἦν."},{"number":279,"text":"καὶ Κλαύδιος ἐπιστέλλει τῷ ἐπαρχοῦντι κατὰ τὴν Αἴγυπτον ὥστε τὴν στάσιν καταστεῖλαι, πέμπει δὲ καὶ διάγραμμα παρακεκληκότων αὐτὸν Ἀγρίππου τε καὶ Ἡρώδου τῶν βασιλέων εἴς τε τὴν Ἀλεξάνδρειαν καὶ Συρίαν γεγραμμένον τοῦτον τὸν τρόπον·"},{"number":280,"text":"Τιβέριος Κλαύδιος Καῖσαρ Σεβαστὸς Γερμανικὸς δημαρχικῆς ἐξουσίας λέγει."},{"number":281,"text":"ἐπιγνοὺς ἀνέκαθεν τοὺς ἐν Ἀλεξανδρείᾳ Ἰουδαίους Ἀλεξανδρεῖς λεγομένους συγκατοικισθέντας τοῖς πρώτοις εὐθὺ καιροῖς Ἀλεξανδρεῦσι καὶ ἴσης πολιτείας παρὰ τῶν βασιλέων τετευχότας, καθὼς φανερὸν ἐγένετο ἐκ τῶν γραμμάτων τῶν παρʼ αὐτοῖς καὶ τῶν διαταγμάτων,"},{"number":282,"text":"καὶ μετὰ τὸ τῇ ἡμετέρᾳ ἡγεμονίᾳ Ἀλεξάνδρειαν ὑπὸ τοῦ Σεβαστοῦ ὑποταχθῆναι πεφυλάχθαι αὐτοῖς τὰ δίκαια ὑπὸ τῶν πεμφθέντων ἐπάρχων κατὰ διαφόρους χρόνους μηδεμίαν τε ἀμφισβήτησιν περὶ τούτων γενομένην τῶν δικαίων αὐτοῖς,"},{"number":283,"text":"ἅμα καὶ καθʼ ὃν καιρὸν Ἀκύλας ἦν ἐν Ἀλεξανδρείᾳ τελευτήσαντος τοῦ τῶν Ἰουδαίων ἐθνάρχου τὸν Σεβαστὸν μὴ κεκωλυκέναι ἐθνάρχας γίγνεσθαι βουλόμενον ὑποτετάχθαι ἑκάστους ἐμμένοντας τοῖς ἰδίοις ἔθεσιν καὶ μὴ παραβαίνειν ἀναγκαζομένους τὴν πάτριον θρησκείαν,"},{"number":284,"text":"Ἀλεξανδρεῖς δὲ ἐπαρθῆναι κατὰ τῶν παρʼ αὐτοῖς Ἰουδαίων ἐπὶ τῶν Γαΐου Καίσαρος χρόνων τοῦ διὰ τὴν πολλὴν ἀπόνοιαν καὶ παραφροσύνην, ὅτι μὴ παραβῆναι ἠθέλησεν τὸ Ἰουδαίων ἔθνος τὴν πάτριον θρησκείαν καὶ θεὸν προσαγορεύειν αὐτόν, ταπεινώσαντος αὐτούς·"},{"number":285,"text":"βούλομαι μηδὲν διὰ τὴν Γαΐου παραφροσύνην τῶν δικαίων τῷ Ἰουδαίων ἔθνει παραπεπτωκέναι, φυλάσσεσθαι δʼ αὐτοῖς καὶ τὰ πρότερον δικαιώματα ἐμμένουσι τοῖς ἰδίοις ἔθεσιν, ἀμφοτέροις τε διακελεύομαι τοῖς μέρεσι πλείστην ποιήσασθαι πρόνοιαν, ὅπως μηδεμία ταραχὴ γένηται μετὰ τὸ προτεθῆναί μου τὸ διάταγμα."},{"number":286,"text":"Τὸ μὲν οὖν εἰς Ἀλεξάνδρειαν ὑπὲρ τῶν Ἰουδαίων διάταγμα τοῦτον ἦν τὸν τρόπον γεγραμμένον· τὸ δʼ εἰς τὴν ἄλλην οἰκουμένην εἶχεν οὕτως·"},{"number":287,"text":"Τιβέριος Κλαύδιος Καῖσαρ Σεβαστὸς Γερμανικὸς ἀρχιερεὺς μέγιστος δημαρχικῆς ἐξουσίας ὕπατος χειροτονηθεὶς τὸ δεύτερον λέγει."},{"number":288,"text":"αἰτησαμένων με βασιλέως Ἀγρίππα καὶ Ἡρώδου τῶν φιλτάτων μοι, ὅπως συγχωρήσαιμι τὰ αὐτὰ δίκαια καὶ τοῖς ἐν πάσῃ τῇ ὑπὸ Ῥωμαίοις ἡγεμονίᾳ Ἰουδαίοις φυλάσσεσθαι, καθὰ καὶ τοῖς ἐν Ἀλεξανδρείᾳ, ἥδιστα συνεχώρησα οὐ μόνον τοῦτο τοῖς αἰτησαμένοις με χαριζόμενος,"},{"number":289,"text":"ἀλλὰ καὶ αὐτοὺς ὑπὲρ ὧν παρεκλήθην ἀξίους κρίνας διὰ τὴν πρὸς Ῥωμαίους πίστιν καὶ φιλίαν, μάλιστα δὲ δίκαιον κρίνων μηδεμίαν μηδὲ Ἑλληνίδα πόλιν τῶν δικαίων τούτων ἀποτυγχάνειν, ἐπειδὴ καὶ ἐπὶ τοῦ θείου Σεβαστοῦ αὐταῖς ἦν τετηρημένα."},{"number":290,"text":"καλῶς οὖν ἔχειν καὶ Ἰουδαίους τοὺς ἐν παντὶ τῷ ὑφʼ ἡμᾶς κόσμῳ τὰ πάτρια ἔθη ἀνεπικωλύτως φυλάσσειν, οἷς καὶ αὐτοῖς ἤδη νῦν παραγγέλλω μου ταύτῃ τῇ φιλανθρωπίᾳ ἐπιεικέστερον χρῆσθαι καὶ μὴ τὰς τῶν ἄλλων ἐθνῶν δεισιδαιμονίας ἐξουθενίζειν, τοὺς ἰδίους δὲ νόμους φυλάσσειν."},{"number":291,"text":"τοῦτό μου τὸ διάταγμα τοὺς ἄρχοντας τῶν πόλεων καὶ τῶν κολωνιῶν καὶ μουνικιπίων τῶν ἐν τῇ Ἰταλίᾳ καὶ τῶν ἐκτός, βασιλεῖς τε καὶ δυνάστας διὰ τῶν ἰδίων πρεσβευτῶν ἐγγράψασθαι βούλομαι ἐκκείμενόν τε ἔχειν οὐκ ἔλαττον ἡμερῶν τριάκοντα ὅθεν ἐξ ἐπιπέδου καλῶς ἀναγνωσθῆναι δύναται."}],"6":[{"number":292,"text":"Τούτοις μὲν δὴ τοῖς διατάγμασιν εἰς Ἀλεξάνδρειάν τε καὶ τὴν οἰκουμένην πᾶσαν ἀποσταλεῖσιν ἐδήλωσεν ἣν περὶ Ἰουδαίων ἔχοι γνώμην Κλαύδιος Καῖσαρ· αὐτίκα δὲ Ἀγρίππαν κομιούμενον τὴν βασιλείαν ἐπὶ τιμαῖς λαμπροτέραις ἐξέπεμψε τοῖς ἐπὶ τῶν ἐπαρχιῶν ἡγεμόσιν καὶ τοῖς ἐπιτρόποις διὰ γραμμάτων ἐπιστείλας ἐράσμιον ἄγειν αὐτόν."},{"number":293,"text":"ὁ δʼ, ὡς εἰκὸς ἦν τὸν ἐπὶ κρείττοσιν τύχαις ἀνερχόμενον, μετὰ τάχους ὑπέστρεψεν, εἰς Ἱεροσόλυμα δʼ ἐλθὼν χαριστηρίους ἐξεπλήρωσε θυσίας οὐδὲν τῶν κατὰ νόμον παραλιπών."},{"number":294,"text":"διὸ καὶ ναζιραίων ξυρᾶσθαι διέταξε μάλα συχνούς, τὴν δὲ χρυσῆν ἅλυσιν τὴν δοθεῖσαν αὐτῷ ὑπὸ Γαΐου ἰσόσταθμον τῇ σιδηρᾷ, ᾗ τὰς ἡγεμονίδας χεῖρας ἐδέθη, τῆς στυγνῆς εἶναι τύχης ὑπόμνημα καὶ τῆς ἐπὶ τὰ κρείττω μαρτυρίαν μεταβολῆς τῶν ἱερῶν ἐντὸς ἀνεκρέμασεν περιβόλων ὑπὲρ τὸ γαζοφυλάκιον, ἵνʼ ᾖ δεῖγμα καὶ τοῦ τὰ μεγάλα δύνασθαί ποτε πεσεῖν καὶ τοῦ τὸν θεὸν ἐγείρειν τὰ πεπτωκότα·"},{"number":295,"text":"πᾶσι γὰρ τοῦτʼ ἐνεφάνιζεν ἡ τῆς ἁλύσεως ἀνάθεσις, ὅτι βασιλεὺς Ἀγρίππας ἀπὸ μικρᾶς αἰτίας εἰς δεσμώτην ἀπέδυ τὸ πρὶν ἀξίωμα καὶ μετʼ ὀλίγον τῆς πέδης ἐκβὰς εἰς βασιλέα τοῦ πάλαι λαμπρότερον ἠγέρθη."},{"number":296,"text":"διὰ τοῦτʼ οὖν ἐννοεῖσθαι, ὅτι τῆς ἀνθρωπίνης φύσεως καὶ πεσεῖν ὀλισθάνειν τὰ μεγέθη καὶ τὰ κλιθέντα δύναται περιφανὲς λαβεῖν πάλιν ὕψος."},{"number":297,"text":"Ἐντελῶς δʼ οὖν θρησκεύσας τὸν θεὸν Ἀγρίππας Θεόφιλον μὲν τὸν Ἀνάνου τῆς ἀρχιερωσύνης μετέστησεν, τῷ δὲ Βοηθοῦ Σίμωνι, τούτῳ Κανθηρᾶς ἐπίκλησις ἦν, τὴν ἐκείνου προσένειμε τιμήν. δύο δʼ ἦσαν ἀδελφοὶ τῷ Σίμωνι καὶ πατὴρ Βοηθός, οὗ τῇ θυγατρὶ βασιλεὺς συνῴκησεν Ἡρώδης, ὡς ἀνωτέρω δεδήλωται."},{"number":298,"text":"σὺν τοῖς ἀδελφοῖς οὖν τὴν ἱερωσύνην ἔσχεν ὁ Σίμων καὶ σὺν τῷ πατρί, καθὰ καὶ πρότερον ἔσχον οἱ Σίμωνος τοῦ Ὀνία παῖδες τρεῖς ὄντες ἐπὶ τῆς τῶν Μακεδόνων ἀρχῆς, ὅπερ ἐν ταῖς προαγούσαις γραφαῖς παρέδομεν."},{"number":299,"text":"Καταστησάμενος δὲ τὰ περὶ τοὺς ἀρχιερεῖς οὕτως ὁ βασιλεὺς τοὺς Ἱεροσολυμίτας ἠμείψατο τῆς εἰς αὐτὸν εὐνοίας· ἀνῆκε γοῦν αὐτοῖς τὰ ὑπὲρ ἑκάστης οἰκίας, ἐν καλῷ τιθέμενος ἀντιδοῦναι τοῖς ἠγαπηκόσιν στοργήν. ἔπαρχον δὲ ἀπέδειξεν παντὸς τοῦ στρατεύματος Σίλαν ἄνδρα πολλῶν αὐτῷ πόνων συμμετασχόντα."},{"number":300,"text":"παντάπασιν δὲ ὀλίγου χρόνου διελθόντος Δωρῖται νεανίσκοι τῆς ὁσιότητος προτιθέμενοι τόλμαν καὶ πεφυκότες εἶναι παραβόλως θρασεῖς Καίσαρος ἀνδριάντα κομίσαντες εἰς τὴν τῶν Ἰουδαίων συναγωγὴν ἀνέστησαν."},{"number":301,"text":"σφόδρα τοῦτο Ἀγρίππαν παρώξυνεν· κατάλυσιν γὰρ τῶν πατρίων αὐτοῦ νόμων ἐδύνατο. ἀμελλητὶ δὲ πρὸς Πούπλιον Πετρώνιον, ἡγεμὼν δὲ τῆς Συρίας οὗτος ἦν, παραγίνεται καὶ καταλέγει τῶν Δωριτῶν."},{"number":302,"text":"ὁ δʼ οὐχ ἧττον ἐπὶ τῷ πραχθέντι χαλεπήνας, καὶ γὰρ αὐτὸς ἔκρινεν ἀσέβειαν τὴν τῶν ἐννόμων παράβασιν, τοῖς ἀποστᾶσι τῶν Δωριτῶν σὺν ὀργῇ ταῦτʼ ἔγραψεν·"},{"number":303,"text":"Πούπλιος Πετρώνιος πρεσβευτὴς Τιβερίου Κλαυδίου Καίσαρος Σεβαστοῦ Γερμανικοῦ Δωριέων τοῖς πρώτοις λέγει."},{"number":304,"text":"ἐπειδὴ τοσαύτῃ τόλμῃ ἀπονοίας τινὲς ἐχρήσαντο ἐξ ὑμῶν, ὥστε μηδὲ διὰ τὸ προτεθῆναι διάταγμα Κλαυδίου Καίσαρος Σεβαστοῦ Γερμανικοῦ περὶ τοῦ ἐφίεσθαι Ἰουδαίους φυλάσσειν τὰ πάτρια πεισθῆναι ὑμᾶς αὐτῷ,"},{"number":305,"text":"τἀναντία δὲ πάντα πρᾶξαι, συναγωγὴν Ἰουδαίων κωλύοντας εἶναι διὰ τὸ μεταθεῖναι ἐν αὐτῇ τὸν Καίσαρος ἀνδριάντα, παρανομοῦντας οὐκ εἰς μόνους Ἰουδαίους, ἀλλὰ καὶ εἰς τὸν αὐτοκράτορα, οὗ ὁ ἀνδριὰς βέλτιον ἐν τῷ ἰδίῳ ναῷ ἢ ἐν ἀλλοτρίῳ ἐτίθετο καὶ ταῦτα ἐν τῷ τῆς συναγωγῆς τόπῳ, τοῦ φύσει δικαιοῦντος ἕνα ἕκαστον τῶν ἰδίων τόπων κυριεύειν κατὰ τὸ Καίσαρος ἐπίκριμα·"},{"number":306,"text":"τοῦ γὰρ ἐμοῦ ἐπικρίματος μιμνήσκεσθαι γελοῖόν ἐστιν μετὰ τὸ τοῦ αὐτοκράτορος διάταγμα τοῦ ἐπιτρέψαντος Ἰουδαίοις τοῖς ἰδίοις ἔθεσι χρῆσθαι, ἔτι μέντοι γε καὶ συμπολιτεύεσθαι τοῖς Ἕλλησιν κεκελευκότος·"},{"number":307,"text":"τοὺς μὲν παρὰ τὸ διάταγμα τοῦ Σεβαστοῦ τοιαῦτα τετολμηκότας, ἐφʼ ᾧ καὶ αὐτοὶ ἠγανάκτησαν οἱ δοκοῦντες αὐτῶν ἐξέχειν οὐ τῇ ἰδίᾳ προαιρέσει γεγενῆσθαι λέγοντες ἀλλὰ τῇ τοῦ πλήθους ὁρμῇ, ὑπὸ ἑκατοντάρχου Πρόκλου Οὐιτελλίου ἐκέλευσα ἐπʼ ἐμὲ ἀναχθῆναι τῶν πεπραγμένων λόγον ἀποδώσοντας,"},{"number":308,"text":"τοῖς δὲ πρώτοις ἄρχουσι παραινῶ, εἰ μὴ βούλονται δοκεῖν κατὰ τὴν αὐτῶν προαίρεσιν γεγενῆσθαι τὸ ἀδίκημα, ἐπιδεῖξαι τοὺς αἰτίους τῷ ἑκατοντάρχῃ μηδεμιᾶς στάσεως μηδὲ μάχης ἐῶντας ἀφορμὴν γενέσθαι, ἥνπερ δοκοῦσίν μοι θηρεύεσθαι διὰ τῶν τοιούτων ἔργων,"},{"number":309,"text":"κἀμοῦ καὶ τοῦ τιμιωτάτου μοι βασιλέως Ἀγρίππου οὐδενὸς μᾶλλον προνοουμένων, ἢ ἵνα μὴ ἀφορμῆς δραξάμενοι τὸ τῶν Ἰουδαίων ἔθνος ὑπὸ τῆς ἀμύνης προφάσει συναθροισθὲν εἰς ἀπόνοιαν χωρῇ."},{"number":310,"text":"ἵνα δὲ γνωριμώτερον ᾖ, τί καὶ ὁ Σεβαστὸς περὶ ὅλου τοῦ πράγματος ἐφρόνησε, τὰ ἐν Ἀλεξανδρείᾳ αὐτοῦ διατάγματα προτεθέντα προσέθηκα, ἅπερ εἰ καὶ γνώριμα πᾶσιν εἶναι δοκεῖ, τότε καὶ ἐπὶ τοῦ βήματος ἀνέγνω ὁ τιμιώτατός μοι βασιλεὺς Ἀγρίππας δικαιολογησάμενος περὶ τοῦ μὴ δεῖν αὐτοὺς ἀφαιρεθῆναι τῆς τοῦ Σεβαστοῦ δωρεᾶς."},{"number":311,"text":"εἴς τε οὖν τὸ λοιπὸν παραγγέλλω μηδεμίαν πρόφασιν στάσεως μηδὲ ταραχῆς ζητεῖν, ἀλλʼ ἑκάστους τὰ ἴδια ἔθη θρησκεύειν."},{"number":312,"text":"Πετρώνιος μὲν οὖν οὕτω προυνόησε διορθώσεως μὲν τὸ παρανομηθὲν ἤδη τυχεῖν, γενέσθαι δὲ παραπλήσιον μηδὲν εἰς αὐτούς."},{"number":313,"text":"Ἀγρίππας δὲ ὁ βασιλεὺς ἀφείλετο μὲν τὴν ἀρχιερωσύνην τὸν Κανθηρᾶν Σίμωνα, Ἰωνάθην δὲ πάλιν ἐπʼ αὐτὴν ἦγεν τὸν Ἀνάνου τοῦτον ἀξιώτερον τῆς τιμῆς ὁμολογῶν εἶναι. τῷ δὲ οὐκ ἀσμενιστὸν ἐφάνη τὴν τοσαύτην ἀπολαβεῖν τιμήν, παρῃτεῖτο δʼ οὖν ταῦτα λέγων·"},{"number":314,"text":"σοὶ μέν, ὦ βασιλεῦ, τετιμημένος χαίρω διὰ ψυχῆς ἔχων τοῦθʼ ὅ μοι γέρας δίδωσιν ἡ σὴ βουλὴ, καὶ πρὸς οὐδέν με τῆς ἀρχιερωσύνης ἄξιον ἔκρινεν ὁ θεός. ἅπαξ δʼ ἐνδὺς στολισμὸν ἱερὸν ἀρκοῦμαι· τότε γὰρ αὐτὸν ἠμφιασάμην ὁσιώτερον ἢ νῦν ἀπολήψομαι."},{"number":315,"text":"σὺ δʼ, εἰ βούλει τὸν ἀξιώτερον ἐμοῦ νῦν τὸ γέρας λαβεῖν, διδάχθητι· πάσης καὶ πρὸς τὸν θεὸν ἁμαρτίας καὶ πρὸς σέ, βασιλεῦ, καθαρὸς ἀδελφὸς ἔστι μοι· πρέποντα τῇ τιμῇ τοῦτον συνίστημι."},{"number":316,"text":"τούτοις ὁ βασιλεὺς ἡσθεὶς τοῖς λόγοις τὸν Ἰωνάθην μὲν ἠγάσατο τῆς γνώμης, τἀδελφῷ δὲ αὐτοῦ Ματθίᾳ τὴν ἱερωσύνην ἔδωκε. καὶ μετʼ οὐ πολὺ Πετρώνιον μὲν Μάρσος διεδέξατο καὶ διεῖπε Συρίαν."}],"7":[{"number":317,"text":"Σίλας δʼ ὁ τοῦ βασιλέως ἔπαρχος ἐπεὶ διὰ πάσης αὐτῷ τύχης ἐγεγόνει πιστὸς οὐδένα κίνδυνόν ποτε κοινωνεῖν ἀνηνάμενος, ἀλλὰ καὶ τοὺς σφαλερωτάτους ὑποδὺς πολλάκις πόνους, πεποιθήσεως ἦν ἀνάπλεως, προσήκειν ὑπολαμβάνων ἰσοτιμίαν βεβαιότητι φιλίας."},{"number":318,"text":"οὐδαμῆ τοίνυν ὑποκατεκλίνετο βασιλεῖ, παρρησίαν δὲ διὰ πάσης ὁμιλίας ἦγεν, κἀν ταῖς φιλοφρονήσεσιν ἐγίνετο φορτικὸς σεμνύνων ἑαυτὸν ἀμέτρως καὶ πολλάκις τῷ βασιλεῖ τὰ στυγνὰ τῆς τύχης ἄγων εἰς ἀνάμνησιν, ἵνα τὴν ἑαυτοῦ τότε σπουδὴν παραδεικνύῃ, συνεχῶς δʼ ἦν, ὡς ὑπὲρ αὐτοῦ κάμοι, πολλὰ διεξιών."},{"number":319,"text":"τούτων οὖν τὸ πλεονάζον ὀνειδισμὸς ἐδόκει· διὸ προσάντως ὁ βασιλεὺς ἐδέχετο τὴν ἀταμίευτον παρρησίαν τἀνδρός· οὐχ ἡδεῖαι γὰρ αἱ τῶν ἀδόξων χρόνων ἀναμνήσεις, εὐήθης δὲ ὁ διηνεκῶς ἅ ποτε ὠφέλησεν προφέρων."},{"number":320,"text":"τέλος γοῦν ἀνηρέθισε σφόδρα ὁ Σίλας τοῦ βασιλέως τὸν θυμὸν κἀκεῖνος ὀργῇ πλέον ἢ λογισμῷ διδοὺς οὐ τῆς ἐπαρχίας μόνον μετέστησε τὸν Σίλαν, ἀλλὰ καὶ παρέδωκεν δεθησόμενον εἰς τὴν ἐκείνου πατρίδα πέμψας."},{"number":321,"text":"χρόνῳ δὲ τὸν θυμὸν ἠμβλύνθη καὶ λογισμοῖς εἰλικρινέσι τὴν περὶ τἀνδρὸς κρίσιν ἐφῆκεν ἐν νῷ λαμβάνων ὅσους ὑπὲρ ἐκείνου πόνους ἐκεῖνος ἀνέτλη. ἡμέραν οὖν ἑορτάζων αὐτοῦ γενέθλιον, ὅτε πᾶσιν ὧν ἦρχεν εὐφροσύνη ᾗ καθίσταντο θαλίαι, τὸν Σίλαν ἀνεκάλει παραυτίκα συνέστιον αὐτῷ γενησόμενον."},{"number":322,"text":"τῷ δέ, τρόπος γὰρ ἐλευθέριος ἦν, ἐδόκει προσειληφέναι δικαίαν αἰτίαν ὀργῆς, ἣν οὐκ ἀπεκρύπτετο πρὸς τοὺς μετιόντας αὐτὸν λέγων·"},{"number":323,"text":"ἐπὶ ποίαν ὁ βασιλεὺς τιμὴν ἀνακαλεῖ με τὴν μετὰ μικρὸν ἀπολουμένην; οὐδὲ γὰρ τὰ πρῶτά μοι γέρα τῆς εἰς αὐτὸν εὐνοίας ἐτήρησεν, ἀπεσύλησεν δʼ ὑβρίσας."},{"number":324,"text":"ἢ πεπαῦσθαι νενόμικέ με τῆς παρρησίας, ἣν ἀπὸ ποίου συνειδότος ἔχων βοήσομαι μᾶλλον, ὅσων αὐτὸν ἐξελυσάμην δεινῶν, ὅσους ἤνεγκα πόνους ἐκείνῳ ποριζόμενος σωτηρίαν τε καὶ τιμήν, ὧν γέρας ἠνεγκάμην δεσμὰ καὶ σκότιον εἱρκτήν."},{"number":325,"text":"οὐκ ἐγώ ποτε τούτων λήσομαι· τάχα μοι τὴν τῆς ἀριστείας συνεποίσεται μνήμην καὶ μεταστᾶσα τῆς σαρκὸς ἡ ψυχή. ταῦτα ἀνεβόα καὶ διετάττετο τῷ βασιλεῖ λέγειν. ὁ δʼ ὡς ἀνιάτως ἑώρα διακείμενον, πάλιν εἴασεν ἐν φρουρᾷ."},{"number":326,"text":"Τὰ δὲ τῶν Ἱεροσολύμων τείχη τὰ πρὸς τὴν καινὴν νεύοντα πόλιν δημοσίαις ὠχύρου δαπάναις, τῇ μὲν εὐρύνων εἰς πλάτος τῇ δὲ εἰς ὕψος ἐξαίρων, κἂν ἐξειργάσατο ταῦτα πάσης ἀνθρωπίνης κρείττονα βίας, εἰ μὴ Μάρσος ὁ τῆς Συρίας ἡγεμὼν Κλαυδίῳ Καίσαρι διὰ γραμμάτων ἐδήλωσε τὸ πραττόμενον."},{"number":327,"text":"καὶ νεωτερισμόν τινα Κλαύδιος ὑποπτεύσας ἐπέστειλεν Ἀγρίππᾳ μετὰ σπουδῆς παύσασθαι τῆς τῶν τειχῶν ἐξοικοδομήσεως· ὁ δʼ ἀπειθεῖν οὐκ ἔκρινεν."},{"number":328,"text":"Ἐπεφύκει δʼ ὁ βασιλεὺς οὗτος εὐεργετικὸς εἶναι ἐν δωρεαῖς καὶ μεγαλοφρονῆσαι ἔθνη φιλότιμος καὶ πολλοῖς ἀθρόως δαπανήμασιν ἀνιστὰς αὑτὸν εἰς ἐπιφάνειαν ἡδόμενος τῷ χαρίζεσθαι καὶ τῷ βιοῦν ἐν εὐφημίᾳ χαίρων, κατʼ οὐδὲν Ἡρώδῃ τῷ πρὸ ἑαυτοῦ βασιλεῖ τὸν τρόπον συμφερόμενος·"},{"number":329,"text":"ἐκείνῳ γὰρ πονηρὸν ἦν ἦθος ἐπὶ τιμωρίαν ἀπότομον καὶ κατὰ τῶν ἀπηχθημένων ἀταμίευτον, Ἕλλησι πλέον ἢ Ἰουδαίοις οἰκείως ἔχειν ὁμολογούμενος· ἀλλοφύλων γέ τοι πόλεις ἐσέμνυνεν δόσει χρημάτων βαλανείων θεάτρων τε ἄλλοτε κατασκευαῖς, ἔστιν αἷς ναοὺς ἀνέστησε, στοὰς ἄλλαις, ἀλλὰ Ἰουδαίων οὐδεμίαν πόλιν οὐδʼ ὀλίγης ἐπισκευῆς ἠξίωσεν οὐδὲ δόσεως ἀξίας μνημονευθῆναι."},{"number":330,"text":"πραῢς δʼ ὁ τρόπος Ἀγρίππᾳ καὶ πρὸς πάντας τὸ εὐεργετικὸν ὅμοιον. τοῖς ἀλλοεθνέσιν ἦν φιλάνθρωπος κἀκείνοις ἐνδεικνύμενος τὸ φιλόδωρον τοῖς ὁμοφύλοις ἀναλόγως χρηστὸς καὶ συμπαθὴς μᾶλλον."},{"number":331,"text":"ἡδεῖα γοῦν αὐτῷ δίαιτα καὶ συνεχὴς ἐν τοῖς Ἱεροσολύμοις ἦν καὶ τὰ πάτρια καθαρῶς ἐτήρει. διὰ πάσης γοῦν αὑτὸν ἦγεν ἁγνείας οὐδʼ ἡμέρα τις παρώδευεν αὐτῷ τὰ νόμιμα χηρεύουσα θυσίας."},{"number":332,"text":"Καὶ δή τις ἐν τοῖς Ἱεροσολύμοις ἀνὴρ ἐπιχώριος ἐξακριβάζειν δοκῶν τὰ νόμιμα, Σίμων ἦν ὄνομα τούτῳ, πλῆθος εἰς ἐκκλησίαν ἁλίσας τηνικάδε τοῦ βασιλέως εἰς Καισάρειαν ἐκδεδημηκότος ἐτόλμησεν αὐτοῦ κατειπεῖν, ὡς οὐχ ὅσιος εἴη, δικαίως δʼ ἂν εἴργοιτο τοῦ ναοῦ τῆς εἰσόδου προσηκούσης τοῖς ἐγγενέσιν."},{"number":333,"text":"δηλοῦται μὲν δὴ διὰ γραμμάτων ὑπὸ τοῦ στρατηγοῦ τῆς πόλεως τῷ βασιλεῖ δημηγορήσας Σίμων ταῦτα, μεταπέμπεται δὲ αὐτὸν ὁ βασιλεὺς καί, καθέζετο γὰρ ἐν τῷ θεάτρῳ τότε, καθεσθῆναι παρʼ αὐτὸν ἐκέλευσεν. ἠρέμα τε καὶ πρᾴως εἰπέ μοι, φησίν, τί τῶν ἐνθάδε γινομένων ἐστὶ παράνομον;"},{"number":334,"text":"ὁ δὲ εἰπεῖν ἔχων οὐδὲν τυχεῖν ἐδεῖτο συγγνώμης. ἀλλὰ ὁ βασιλεὺς αὐτῷ ἢ προσεδόκησέν τις διηλλάττετο τὴν πρᾳότητα κρίνων βασιλικωτέραν ὀργῆς καὶ πρέπειν εἰδὼς τοῖς μεγέθεσι θυμοῦ πλέον ἐπιείκειαν. τὸν Σίμωνα γοῦν καὶ δωρεᾶς τινος ἀξιώσας ἀπεπέμπετο."},{"number":335,"text":"Πολλοῖς δὲ κατασκευάσας πολλὰ Βηρυτίους ἐξαιρέτως ἐτίμησεν· θέατρον γὰρ αὐτοῖς κατεσκεύασε πολυτελείᾳ τε καὶ κάλλει πολλῶν διαφέρον ἀμφιθέατρόν τε πολλῶν ἀναλωμάτων βαλανεῖα πρὸς τούτοις καὶ στοάς, ἐν οὐδενὶ τῶν ἔργων στενότητι δαπανημάτων ἢ τὸ κάλλος ἀδικήσας ἢ τὸ μέγεθος."},{"number":336,"text":"ἐπεδαψιλεύσατο δʼ αὐτῶν τὴν καθιέρωσιν μεγαλοπρεπῶς, ἐν τῷ θεάτρῳ μὲν θεωρίας ἐπιτελῶν πάνθʼ ὅσα μουσικῆς ἔργα παράγων καὶ ποικίλης ποιητικὰ τέρψεως, ἐν δὲ τῷ ἀμφιθεάτρῳ πλήθει μονομάχων τὴν αὐτοῦ δεικνὺς μεγαλόνοιαν."},{"number":337,"text":"ἔνθα καὶ τὴν κατὰ πλῆθος ἀντίταξιν βουληθεὶς γενέσθαι τῶν θεωμένων τέρψιν ἑπτακοσίους ἄνδρας ἑπτακοσίοις μαχησομένους εἰσέπεμψεν κακούργους ὅσους εἶχεν ἀποτάξας εἰς τήνδε τὴν πρᾶξιν, ἵνʼ οἱ μὲν κολασθῶσιν, τὸ πολέμου δʼ ἔργον γένηται τέρψις εἰρήνης. τούτους μὲν οὖν πασσυδὶ διέφθειρεν."}],"8":[{"number":338,"text":"Ἐν Βηρυτῷ δὲ τελέσας τὰ προειρημένα μετῆλθεν εἰς Τιβεριάδα πόλιν τῆς Γαλιλαίας. ἦν δὲ ἄρα τοῖς ἄλλοις βασιλεῦσιν περίβλεπτος. ἧκε γοῦν παρʼ αὐτὸν Κομμαγηνῆς μὲν βασιλεὺς Ἀντίοχος, Ἐμεσῶν δὲ Σαμψιγέραμος καὶ Κότυς, τῆς μικρᾶς Ἀρμενίας οὗτος ἐβασίλευσεν, καὶ Πολέμων τὴν Πόντου κεκτημένος δυναστείαν Ἡρώδης τε· οὗτος ἀδελφὸς ἦν αὐτοῦ, ἦρχεν δὲ τῆς Χαλκίδος."},{"number":339,"text":"ὡμίλησε δὲ πᾶσιν κατά τε τὰς ὑποδοχὰς καὶ φιλοφρονήσεις ὡς μάλιστα διαδείξας φρονήσεως ὕψος καὶ διὰ τοῦτό γε δοκεῖν δικαίως τῇ τοῦ βασιλέως παρουσίᾳ τετιμῆσθαι."},{"number":340,"text":"ἀλλὰ γὰρ τούτων διατριβόντων ἔτι παρʼ αὐτῷ Μάρσος ὁ τῆς Συρίας ἡγεμὼν παρεγένετο. πρὸς Ῥωμαίους οὖν τιμητικὸν τηρῶν ὑπαντησόμενος αὐτῷ τῆς πόλεως ἀπωτέρω σταδίους ἑπτὰ προῆλθεν ὁ βασιλεύς."},{"number":341,"text":"τοῦτο δὲ ἄρα ἔμελλεν τῆς πρὸς Μάρσον ἀρχὴ γενήσεσθαι διαφορᾶς· συγκαθεζόμενος γὰρ ἐπὶ τῆς ἀπήνης ἐπήγετο τοὺς ἄλλους βασιλέας, Μάρσῳ δʼ ἡ τούτων ὁμόνοια καὶ μέχρι τοσοῦδε φιλία πρὸς ἀλλήλους ὑπωπτεύθη συμφέρειν οὐχ ὑπολαμβάνοντι Ῥωμαίοις δυναστῶν τοσούτων συμφρόνησιν. εὐθὺς οὖν ἑκάστῳ τῶν ἐπιτηδείων τινὰς πέμπων ἐπέστελλεν ἐπὶ τὰ ἑαυτοῦ δίχα μελλήσεως ἀπέρχεσθαι."},{"number":342,"text":"ταῦτα Ἀγρίππας ἀνιαρῶς ἐξεδέχετο· καὶ Μάρσῳ μὲν ἐκ τούτου διαφόρως ἔσχεν, τὴν ἀρχιερωσύνην δὲ Ματθίαν ἀφελόμενος ἀντʼ αὐτοῦ κατέστησεν ἀρχιερέα Ἐλιωναῖον τὸν τοῦ Κιθαίρου παῖδα."},{"number":343,"text":"Τρίτον δὲ ἔτος αὐτῷ βασιλεύοντι τῆς ὅλης Ἰουδαίας πεπλήρωτο, καὶ παρῆν εἰς πόλιν Καισάρειαν, ἣ τὸ πρότερον Στράτωνος πύργος ἐκαλεῖτο. συνετέλει δʼ ἐνταῦθα θεωρίας εἰς τὴν Καίσαρος τιμὴν ὑπὲρ τῆς ἐκείνου σωτηρίας ἑορτήν τινα ταύτην ἐπιστάμενος, καὶ παρʼ αὐτὴν ἤθροιστο τῶν κατὰ τὴν ἐπαρχίαν ἐν τέλει καὶ προβεβηκότων εἰς ἀξίαν πλῆθος."},{"number":344,"text":"δευτέρᾳ δὴ τῶν θεωριῶν ἡμέρᾳ στολὴν ἐνδὺς ἐξ ἀργύρου πεποιημένην πᾶσαν, ὡς θαυμάσιον ὑφὴν εἶναι, παρῆλθεν εἰς τὸ θέατρον ἀρχομένης ἡμέρας. ἔνθα ταῖς πρώταις τῶν ἡλιακῶν ἀκτίνων ἐπιβολαῖς ὁ ἄργυρος καταυγασθεὶς θαυμασίως ἀπέστιλβε μαρμαίρων τι φοβερὸν καὶ τοῖς εἰς αὐτὸν ἀτενίζουσι φρικῶδες."},{"number":345,"text":"εὐθὺς δὲ οἱ κόλακες τὰς οὐδὲ ἐκείνῳ πρὸς ἀγαθοῦ ἄλλος ἄλλοθεν φωνὰς ἀνεβόων, θεὸν προσαγορεύοντες εὐμενής τε εἴης ἐπιλέγοντες, εἰ καὶ μέχρι νῦν ὡς ἄνθρωπον ἐφοβήθημεν,"},{"number":346,"text":"ἀλλὰ τοὐντεῦθεν κρείττονά σε θνητῆς φύσεως ὁμολογοῦμεν. οὐκ ἐπέπληξεν τούτοις ὁ βασιλεὺς οὐδὲ τὴν κολακείαν ἀσεβοῦσαν ἀπετρίψατο. ἀνακύψας δʼ οὖν μετʼ ὀλίγον τὸν βουβῶνα τῆς ἑαυτοῦ κεφαλῆς ὑπερκαθιζόμενον εἶδεν ἐπὶ σχοινίου τινός. ἄγγελον τοῦτον εὐθὺς ἐνόησεν κακῶν εἶναι τὸν καί ποτε τῶν ἀγαθῶν γενόμενον, καὶ διακάρδιον ἔσχεν ὀδύνην, ἄθρουν δʼ αὐτῷ τῆς κοιλίας προσέφυσεν ἄλγημα μετὰ σφοδρότητος ἀρξάμενον."},{"number":347,"text":"ἀναθορὼν οὖν πρὸς τοὺς φίλους, ὁ θεὸς ὑμῖν ἐγώ, φησίν, ἤδη καταστρέφειν ἐπιτάττομαι τὸν βίον, παραχρῆμα τῆς εἱμαρμένης τὰς ἄρτι μου κατεψευσμένας φωνὰς ἐλεγχούσης· ὁ κληθεὶς ἀθάνατος ὑφʼ ὑμῶν ἤδη θανεῖν ἀπάγομαι. δεκτέον δὲ τὴν πεπρωμένην, ᾗ θεὸς βεβούληται· καὶ γὰρ βεβιώκαμεν οὐδαμῇ φαύλως, ἀλλʼ ἐπὶ τῆς μακαριζομένης λαμπρότητος."},{"number":348,"text":"ταῦθʼ ἅμα λέγων ἐπιτάσει τῆς ὀδύνης κατεπονεῖτο· μετὰ σπουδῆς οὖν εἰς τὸ βασίλειον ἐκομίσθη καὶ διῇξε λόγος εἰς πάντας, ὡς ἔχοι τοῦ τεθνάναι παντάπασι μετʼ ὀλίγον."},{"number":349,"text":"ἡ πληθὺς δʼ αὐτίκα σὺν γυναιξὶν καὶ παισὶν ἐπὶ σάκκων καθεσθεῖσα τῷ πατρίῳ νόμῳ τὸν θεὸν ἱκέτευεν ὑπὲρ τοῦ βασιλέως, οἰμωγῆς δὲ πάντʼ ἦν ἀνάπλεα καὶ θρήνων. ἐν ὑψηλῷ δʼ ὁ βασιλεὺς δωματίῳ κατακείμενος καὶ κάτω βλέπων αὐτοὺς πρηνεῖς καταπίπτοντας ἄδακρυς οὐδʼ αὐτὸς διέμενεν."},{"number":350,"text":"συνεχεῖς δʼ ἐφʼ ἡμέρας πέντε τῷ τῆς γαστρὸς ἀλγήματι διεργασθεὶς τὸν βίον κατέστρεψεν, ἀπὸ γενέσεως ἄγων πεντηκοστὸν ἔτος καὶ τέταρτον, τῆς βασιλείας δʼ ἕβδομον."},{"number":351,"text":"τέτταρας μὲν οὖν ἐπὶ Γαΐου Καίσαρος ἐβασίλευσεν ἐνιαυτοὺς τῆς Φιλίππου μὲν τετραρχίας εἰς τριετίαν ἄρξας, τῷ τετάρτῳ δὲ καὶ τὴν Ἡρώδου προσειληφώς, τρεῖς δʼ ἐπιλαβὼν τῆς Κλαυδίου Καίσαρος αὐτοκρατορίας, ἐν οἷς τῶν τε προειρημένων ἐβασίλευσεν καὶ τὴν Ἰουδαίαν προσέλαβεν Σαμάρειάν τε καὶ Καισάρειαν."},{"number":352,"text":"προσωδεύσατο δʼ ὅτι πλείστας αὐτῶν προσφορὰς διακοσίας ἐπὶ χιλίαις μυριάδας, πολλὰ μέντοι προσεδανείσατο· τῷ γὰρ φιλόδωρος εἶναι δαψιλέστερα τῶν προσιόντων ἀνήλισκεν, ἦν δὲ ἀφειδὲς αὐτοῦ τὸ φιλότιμον."},{"number":353,"text":"Ἀγνοουμένης γε μὴν τοῖς πλήθεσιν τῆς ἐκπνοῆς αὐτοῦ συμφρονήσαντες Ἡρώδης τε ὁ τῆς Χαλκίδος δυναστεύων καὶ Ἑλκίας ὁ ἔπαρχος καὶ φίλος τοῦ βασιλέως Ἀρίστωνα ἔπεμψαν τῶν ὑπηρετῶν τὸν ἐπιτήδειον καὶ Σίλαν, ἐχθρὸς γὰρ ἦν αὐτοῖς, ἀπέσφαξαν ὡς δὴ τοῦ βασιλέως κελεύσαντος."}],"9":[{"number":354,"text":"Ἀγρίππας μὲν οὖν ὁ βασιλεὺς τρόπῳ τοιούτῳ κατέστρεψεν τὸν βίον, γένει δὲ αὐτῷ κατελέλειπτο υἱὸς μὲν Ἀγρίππας ἄγων ἔτος ἑπτακαιδέκατον, τρεῖς δὲ θυγατέρες, ὧν ἡ μὲν Ἡρώδῃ τοῦ πατρὸς ἀδελφῷ γεγάμητο Βερενίκη τὸ ἑκκαιδέκατον ἔτος γεγονυῖα, παρθένοι δʼ ἦσαν αἱ δύο Μαριάμμη τε καὶ Δρούσιλλα, δεκαετὴς μὲν ἡ ἑτέρα, ἑξαετὴς δὲ Δρούσιλλα·"},{"number":355,"text":"καθωμολόγηντο δʼ ὑπὸ τοῦ πατρὸς πρὸς γάμον Ἰουλίῳ μὲν Ἀρχελάῳ τοῦ Χελκίου παιδὶ Μαριάμμη, Δρούσιλλα δὲ Ἐπιφανεῖ, τοῦ δὲ τῆς Κομμαγηνῆς βασιλέως Ἀντιόχου υἱὸς ἦν οὗτος."},{"number":356,"text":"ἀλλὰ γὰρ ὅτε ἐγνώσθη τὸν βίον ἐκλιπὼν Ἀγρίππας, Καισαρεῖς καὶ Σεβαστηνοὶ τῶν εὐποιιῶν αὐτοῦ λαθόμενοι τὰ τῶν δυσμενεστάτων ἐποίησαν·"},{"number":357,"text":"βλασφημίας τε γὰρ ἀπερρίπτουν εἰς τὸν κατοιχόμενον ἀπρεπεῖς λέγεσθαι καὶ ὅσοι στρατευόμενοι τότε ἔτυχον, συχνοὶ δʼ ἦσαν, οἴκαδε ἀπῆλθον καὶ τοὺς ἀνδριάντας τῶν τοῦ βασιλέως θυγατέρων ἁρπάσαντες ὁμοθυμαδὸν ἐκόμισαν εἰς τὰ πορνεῖα καὶ στήσαντες ἐπὶ τῶν τεγῶν ὡς δυνατὸν ἦν ἀφύβριζον ἀσχημονέστερα διηγήσεως δρῶντες,"},{"number":358,"text":"ἐπί τε τοῖς δημοσίοις κατακλινόμενοι τόποις πανδήμους ἑστιάσεις ἐπετέλουν στεφανούμενοι καὶ μυριζόμενοι καὶ σπένδοντες τῷ Χάρωνι προπόσεις τῆς τοῦ βασιλέως ἐκπνοῆς ἀλλήλοις ἀνταποδιδόντες."},{"number":359,"text":"ἀμνήμονες δʼ ἦσαν οὐκ Ἀγρίππα μόνον χρησαμένου πολλαῖς εἰς αὐτοὺς φιλοτιμίαις, καὶ τοῦ πάππου δὲ Ἡρώδου· τὰς πόλεις ἐκεῖνος αὐτοῖς ἔκτισεν λιμένας τε καὶ ναοὺς κατεσκεύασεν λαμπροῖς δαπανήμασιν."},{"number":360,"text":"Ὁ δὲ τοῦ τεθνεῶτος υἱὸς Ἀγρίππας ἐπὶ Ῥώμης ἦν ἐν τῷ χρόνῳ τούτῳ τρεφόμενος παρὰ Κλαυδίῳ Καίσαρι."},{"number":361,"text":"πυθόμενός γε μὴν Καῖσαρ, ὅτι τέθνηκεν Ἀγρίππας, Σεβαστηνοὶ δὲ καὶ Καισαρεῖς ὑβρίκασιν εἰς αὐτόν, ἐπʼ ἐκείνῳ μὲν ἤλγησεν, ἐπὶ δὲ τοὺς ἀχαριστήσαντας ὠργίσθη."},{"number":362,"text":"πέμπειν οὖν εὐθέως ὥρμητο τὸν νεώτερον Ἀγρίππαν τὴν βασιλείαν διαδεξόμενον ἅμα βουλόμενος ἐμπεδοῦν τοὺς ὀμωμοσμένους ὅρκους, ἀλλὰ τῶν ἐξελευθέρων καὶ φίλων οἱ πολὺ παρʼ αὐτῷ δυνάμενοι ἀπέτρεψαν, σφαλερὸν εἶναι λέγοντες κομιδῇ νέῳ μηδὲ τοὺς παιδὸς ἐκβεβηκότι χρόνους ἐπιτρέπειν βασιλείας τηλικοῦτον μέγεθος, ᾧ μὴ δυνατὸν τὰς τῆς διοικήσεως φροντίδας ἐνεγκεῖν, καὶ τελείῳ δʼ οὖν εἶναι βαρὺ βάσταγμα βασιλείαν."},{"number":363,"text":"ἔδοξεν οὖν αὐτοὺς εἰκότα λέγειν ὁ Καῖσαρ. ἔπαρχον οὖν τῆς Ἰουδαίας καὶ τῆς ἁπάσης βασιλείας ἀπέστειλεν Κούσπιον Φᾶδον τῷ κατοιχομένῳ διδοὺς τιμὴν τὸ μὴ Μάρσον ἐπαγαγεῖν εἰς βασιλείαν αὐτῷ διάφορον."},{"number":364,"text":"ἐγνώκει δὲ πρὸ πάντων ἐπιστεῖλαι τῷ Φάδῳ Καισαρεῦσιν καὶ Σεβαστηνοῖς ἐπιπλῆξαι τῆς εἰς τὸν κατοιχόμενον ὕβρεως καὶ παροινίας εἰς τὰς ἔτι ζώσας,"},{"number":365,"text":"τὴν ἴλην δὲ τῶν Καισαρέων καὶ τῶν Σεβαστηνῶν καὶ τὰς πέντε σπείρας εἰς Πόντον μεταγαγεῖν, ἵνʼ ἐκεῖ στρατεύοιντο, τῶν δʼ ἐν Συρίᾳ Ῥωμαϊκῶν ταγμάτων ἐπιλέξαι στρατιώτας κατʼ ἀριθμοὺς καὶ τὸν ἐκείνων ἀναπληρῶσαι τόπον."},{"number":366,"text":"οὐ μὴν οἱ κελευσθέντες μετέστησαν· πρεσβευσάμενοι γὰρ Κλαύδιον ἀπεμειλίξαντο καὶ μένειν ἐπὶ τῆς Ἰουδαίας ἐπέτυχον, οἳ καὶ τοῖς ἐπιοῦσι χρόνοις τῶν μεγίστων Ἰουδαίοις ἐγένοντο συμφορῶν ἀρχὴ τοῦ κατὰ Φλῶρον πολέμου σπέρματα βαλόντες. ὅθεν Οὐεσπασιανὸς κρατήσας, ὡς μετʼ ὀλίγον ἐροῦμεν, ἐξήγαγεν αὐτοὺς τῆς ἐπαρχίας."}]},"count":366};a[20]={"book":20,"title":"Τάδε ἔνεστιν ἐν τῇ κ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς Κλαύδιος Καῖσαρ μετὰ τὴν Ἀγρίππου τελευτὴν Φᾶδον ἔπεμψεν εἰς Ἰουδαίαν ἐπίτροπον.\n\nστάσις Φιλαδελφηνῶν πρὸς τοὺς ἐν τῇ Περαίᾳ κατοικοῦντας Ἰουδαίους περὶ ὅρων κώμης μιᾶς, καὶ ὡς ὑπὸ τούτων πολλῶν ἀναιρεθέντων Φιλαδελφηνῶν Φᾶδος ἀγανακτήσας τῶν Περαϊτῶν Ἰουδαίων τοὺς πρώτους τρεῖς ἄνδρας λαβὼν ἀπέκτεινεν.\n\nὡς Θολεμαῖος ὁ ἀρχιλῃστὴς τοὺς Ἄραβας λῃστεύων ληφθεὶς καὶ ἐπὶ Φᾶδον ἀχθεὶς ἀνῃρέθη.\n\nὡς Φᾶδος καὶ Κάσσιος Λογγῖνος ὁ τῆς Συρίας ἡγεμὼν ἀναβάντες εἰς Ἱεροσόλυμα τοῖς πρώτοις τῶν Ἰουδαίων ἐκέλευσαν τὸν ποδήρη καὶ τὴν ἱερὰν στολὴν ἐν τῇ Ἀντωνίᾳ καταθέσθαι ὑπὸ τῇ Ῥωμαίων ἐξουσίᾳ, καθὰ καὶ πρότερον ἦν.\n\nπαράκλησις ἐπὶ τούτῳ τῶν Ἰουδαίων πρὸς Φᾶδον καὶ Λογγῖνον ἀξιούντων αὐτοὺς ἐπιτρέψαι πέμψαι πρεσβείαν πρὸς Καίσαρα Κλαύδιον περὶ τούτου.\n\nὡς Φᾶδος λαβὼν ὁμήρους ἐπέτρεψεν.\n\nὡς Κλαύδιος Καῖσαρ παρακληθεὶς ὑπ' Ἀγρίππα τοῦ νεωτέρου συνεχώρησεν τοῖς Ἰουδαίοις τὰ αἰτήματα καὶ πρὸς Φᾶδον ἔγραψε περὶ τούτων.\n\nὃν τρόπον Ἑλένη ἡ τῶν Ἀδιαβηνῶν βασιλὶς καὶ οἱ παῖδες αὐτῆς Μονόβαζος καὶ Ἰζάτης καὶ τὸ πᾶν γένος αὐτῶν ἐζήλωσαν τὰ Ἰουδαίων ἔθη.\n\nὡς Ἡρώδου τελευτήσαντος τοῦ τῆς Χαλκίδος βασιλέως Ἀγρίππας ὁ νεώτερος τὴν ἀρχὴν ἔλαβεν δόντος αὐτῷ Κλαυδίου Καίσαρος.\n\nὡς Τιβέριος Ἀλέξανδρος ἐπίτροπος εἰς Ἰουδαίαν ἐλθὼν τοὺς υἱοὺς Ἰούδα τοῦ Γαλιλαίου τὸν ὄχλον ἀπατῶντας ἐκόλασεν.\n\nπερὶ τοῦ λιμοῦ τοῦ γενομένου κατὰ τὴν χώραν.\n\nΚουμάνου ἄφιξις εἰς τὴν Ἰουδαίαν ἐπιτρόπου πεμφθέντος ὑπὸ Καίσαρος.\n\nὡς ἐπὶ τούτου πολλοὶ τῶν Ἰουδαίων κατὰ τὸ ἱερὸν ἀπώλοντο.\n\nστάσις Ἰουδαίων πρὸς Σαμαρεῖς καὶ ὡς πολλοὶ διεφθάρησαν τῶν Σαμαρειτῶν.\n\nὡς Μόδιος Κουαδρᾶτος ὁ τῆς Συρίας ἡγεμὼν ἀκούσας ταῦτα καὶ ἀναβὰς εἰς Ἰουδαίαν τοὺς πρώτους τῶν Ἰουδαίων καὶ Σαμαρειτῶν ἐκέλευσεν εἰς Ῥώμην ἀναβῆναι, ὁμοίως καὶ Κούμανον τὸν ἐπίτροπον καὶ Κέλερα τὸν χιλίαρχον λόγον ὑφέξοντας Κλαυδίῳ Καίσαρι περὶ τῶν πεπραγμένων, τινὰς δὲ καὶ Ἰουδαίων αὐτὸς ἐκόλασεν.\n\nὡς Κλαύδιος ἀκούσας αὐτῶν τοὺς μὲν Ἰουδαίους τῆς αἰτίας ἀπέλυσεν παρακληθεὶς ὑπὸ βασιλέως Ἀγρίππα, Κούμανον δὲ ἐξώρισε, Κέλερα δὲ τὸν χιλίαρχον καὶ τοὺς πρώτους τῶν Σαμαρειτῶν ἐκόλασεν.\n\nὡς Φῆλιξ ἐπίτροπος πεμφθεὶς καὶ καταλαβὼν τὴν χώραν κεκακωμένην ὑπὸ τῶν λῃστῶν προυνοήσατο διαφθείρας αὐτοὺς εἰρήνην ἐν τῇ χώρᾳ καταστῆσαι, τὸν δὲ πρῶτον τῶν λῃστῶν Ἐλεάζαρον ὄνομα δήσας εἰς Ῥώμην ἀνέπεμψεν.\n\nὡς ἐπιδημήσαντος Αἰγυπτίου τινὸς γόητος καὶ πολλῶν Ἰουδαίων ὑπ' αὐτοῦ πλανηθέντων Φῆλιξ ἐπεξελθὼν αὐτοῖς πολλοὺς ἀπέκτεινεν.\n\nὡς στασιάζοντας Ἰουδαίων τοὺς πρώτους ἐν Καισαρείᾳ πρὸς τοὺς Σύρους Φῆλιξ ὁ ἐπίτροπος ἔπαυσεν.\n\nὃν τρόπον Κλαυδίου τελευτήσαντος Νέρων τὴν ἀρχὴν διεδέξατο.\n\nὡς Πορκίου Φήστου πεμφθέντος εἰς Ἰουδαίαν ἐπιτρόπου συνέβη κακωθῆναι τὴν χώραν ὑπὸ τῶν σικαρίων.\n\nπερὶ τῆς στοᾶς τοῦ ἔσωθεν ἱεροῦ καὶ ὃν τρόπον ὕψωσαν αὐτὴν οἱ Ἰουδαῖοι.\n\nὡς Φῆστος ἀγανακτήσας ἐπὶ τούτῳ τοὺς πρώτους τῶν Ἰουδαίων εἰς Ῥώμην ἔπεμψεν πρὸς Νέρωνα πείσοντας αὐτὸν περὶ τῶν πεπραγμένων.\n\nὡς τελευτήσαντος Φήστου ἐν τῇ Ἰουδαίᾳ Ἀλβῖνος ἦλθεν διάδοχος.\n\nὡς ἐπὶ τούτου ἐπαύσαντο οἱ σικάριοι τὴν χώραν κακοποιεῖν.\n\nὡς Φλῶρος ἐλθὼν Ἀλβίνῳ διάδοχος τοσαῦτα διέθηκε τοὺς Ἰουδαίους κακά, ὡς ἀναγκάσαι αὐτοὺς ἐφ' ὅπλα χωρῆσαι.\n\nπερὶ Ἰωσήπου καὶ γένους αὐτοῦ καὶ πολιτείας.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν κϛ."},"chapters":{"1":[{"number":1,"text":"Τελευτήσαντος δὲ τοῦ βασιλέως Ἀγρίππα, καθὼς ἐν τῇ πρὸ ταύτης ἀπηγγέλκαμεν βίβλῳ, πέμπει Μάρσῳ διάδοχον Κλαύδιος Καῖσαρ Κάσσιον Λογγῖνον, μνήμῃ τῇ τοῦ βασιλέως τοῦτο χαριζόμενος, πολλὰ διὰ γραμμάτων ὑπʼ αὐτοῦ περιόντος ἀξιωθεὶς μηκέτι Μάρσον τῶν κατὰ τὴν Συρίαν πραγμάτων προΐστασθαι."},{"number":2,"text":"Φᾶδος δὲ ὡς εἰς τὴν Ἰουδαίαν ἐπίτροπος ἀφίκετο, καταλαμβάνει στασιάσαντας τοὺς τὴν Περαίαν κατοικοῦντας Ἰουδαίους πρὸς Φιλαδελφηνοὺς περὶ ὅρων κώμης μιᾶς λεγομένης πολεμίων ἀνδρῶν ἀνάπλεω· καὶ δὴ οἱ τῆς Περαίας χωρὶς γνώμης τῆς τῶν πρώτων παρʼ αὐτοῖς ἀναλαβόντες τὰ ὅπλα πολλοὺς τῶν Φιλαδελφηνῶν διαφθείρουσιν."},{"number":3,"text":"ταῦτα πυθόμενον τὸν Φᾶδον σφόδρα παρώξυνεν, ὅτι μὴ τὴν κρίσιν αὐτῷ παραλίποιεν, εἴπερ ὑπὸ τῶν Φιλαδελφηνῶν ἐνόμιζον ἀδικεῖσθαι, ἀλλʼ ἐφʼ ὅπλα χωρήσειαν."},{"number":4,"text":"λαβὼν οὖν τρεῖς τοὺς πρώτους αὐτῶν τοὺς καὶ τῆς στάσεως αἰτίους δῆσαι προσέταξεν, εἶτα τὸν μὲν αὐτῶν ἀνεῖλεν, Ἀννίβας δʼ ἦν ὄνομα τούτῳ, Ἀμαράμῳ δὲ καὶ Ἐλεαζάρῳ τοῖς δυσὶ φυγὴν ἐπέβαλεν."},{"number":5,"text":"ἀναιρεῖται δὲ καὶ Θολομαῖος ὁ ἀρχιλῃστὴς μετʼ οὐ πολὺν χρόνον ἀχθεὶς ἐπʼ αὐτὸν διατεθεικὼς μέγιστα κακὰ τὴν Ἰδουμαίαν καὶ τοὺς Ἄραβας, ἐκαθάρθη τε λῃστηρίων ἅπασα τοὐντεῦθεν Ἰουδαία προνοίᾳ καὶ φροντίδι τῇ Φάδου·"},{"number":6,"text":"ὃς δὴ καὶ τότε μεταπεμψάμενος τοὺς ἀρχιερεῖς καὶ τοὺς πρώτους τῶν Ἱεροσολυμιτῶν παρῄνεσεν αὐτοῖς τὸν ποδήρη χιτῶνα καὶ τὴν ἱερὰν στολήν, ἣν φορεῖν μόνος ὁ ἀρχιερεὺς ἔθος ἔχει, εἰς τὴν Ἀντωνίαν, ἥπερ ἐστὶ φρούριον, καταθέσθαι κεισομένην ὑπὸ τῇ Ῥωμαίων ἐξουσίᾳ, καθὰ δὴ καὶ πρότερον ἦν."},{"number":7,"text":"οἱ δὲ ἀντιλέγειν μὲν οὐκ ἐτόλμων, παρεκάλουν δʼ ὅμως τόν τε Φᾶδον καὶ τὸν Λογγῖνον, ἀφίκετο γὰρ καὶ αὐτὸς εἰς τὰ Ἱεροσόλυμα πολλὴν ἐπαγόμενος δύναμιν φόβῳ τοῦ μὴ τὰ προστάγματα Φάδου τὸ πλῆθος τῶν Ἰουδαίων νεωτερίζειν ἀναγκάσῃ, πρῶτον μὲν αὐτοῖς ἐπιτρέψαι πρέσβεις ὡς Καίσαρα πέμψαι τοὺς αἰτησομένους παρʼ αὐτοῦ τὴν ἱερὰν στολὴν ὑπὸ τὴν αὐτῶν ἐξουσίαν ἔχειν, εἶτα δὲ περιμεῖναι μέχρις ἂν γνῶσιν, τί πρὸς ταῦτα Κλαύδιος ἀποκρίναιτο."},{"number":8,"text":"οἱ δὲ ἐπιτρέψειν αὐτοῖς ἔφασαν ἀποστεῖλαι τοὺς πρέσβεις, εἰ λάβοιεν τοὺς παῖδας ὁμηρεύσοντας. ὑπακουσάντων δʼ ἑτοίμως ἐκείνων καὶ δόντων ἐξεπέμφθησαν οἱ πρέσβεις."},{"number":9,"text":"παραγενομένων δὲ εἰς τὴν Ῥώμην αὐτῶν γνοὺς ὁ νεώτερος Ἀγρίππας ὁ τοῦ τετελευτηκότος παῖς, καθʼ ἣν ἥκουσιν αἰτίαν, ἐτύγχανεν δὲ ὢν παρὰ Κλαυδίῳ Καίσαρι, καθὼς καὶ πρότερον εἴπομεν, παρακαλεῖ τὸν Καίσαρα συγχωρῆσαι τοῖς Ἰουδαίοις ἅπερ ἠξίουν περὶ τῆς ἱερᾶς στολῆς καὶ Φάδῳ περὶ τούτων ἐπιστεῖλαι."},{"number":10,"text":"Καλέσας δὲ Κλαύδιος τοὺς πρέσβεις ἔφη ταῦτα συγχωρεῖν καὶ ἐκέλευεν αὐτοὺς Ἀγρίππᾳ χάριν εἰδέναι, ταῦτα γὰρ ἐκείνου ποιεῖν ἀξιώσαντος, ἐπί τε ταῖς ἀποκρίσεσιν τοιαύτην ἐπιστολὴν ἔδωκεν·"},{"number":11,"text":"Κλαύδιος Καῖσαρ Γερμανικὸς δημαρχικῆς ἐξουσίας τὸ πέμπτον ὕπατος ἀποδεδειγμένος τὸ τέταρτον αὐτοκράτωρ τὸ δέκατον πατὴρ πατρίδος Ἱεροσολυμιτῶν ἄρχουσι βουλῇ δήμῳ Ἰουδαίων παντὶ ἔθνει χαίρειν."},{"number":12,"text":"Ἀγρίππα τοῦ ἐμοῦ, ὃν ἐγὼ ἔθρεψα καὶ ἔχω σὺν ἐμαυτῷ εὐσεβέστατον ὄντα, προσαγαγόντος μοι τοὺς ὑμετέρους πρέσβεις εὐχαριστοῦντας ἐφʼ ᾗ πεποίημαι τοῦ ἔθνους ὑμῶν κηδεμονίᾳ, καὶ αἰτησαμένων σπουδαίως καὶ φιλοτίμως τὴν ἱερὰν ἐσθῆτα καὶ τὸν στέφανον ὑπὸ τὴν ἐξουσίαν ὑμῶν εἶναι, συγχωρῶ καθὼς ὁ κράτιστος καί μοι τιμιώτατος Οὐιτέλλιος ἐποίησεν."},{"number":13,"text":"συγκατεθέμην δὲ τῇ γνώμῃ ταύτῃ πρῶτον διὰ τὸ ἐμαυτοῦ εὐσεβὲς καὶ τὸ βούλεσθαι ἑκάστους κατὰ τὰ πάτρια θρησκεύειν, ἔπειτα δὲ εἰδώς, ὅτι καὶ αὐτῷ βασιλεῖ Ἡρώδῃ καὶ Ἀριστοβούλῳ τῷ νεωτέρῳ, ὧν τὴν πρὸς ἐμαυτὸν εὐσέβειαν καὶ τὴν περὶ ὑμᾶς γινώσκω σπουδήν ταῦτα ποιήσας, πρὸς οὓς ἔστι μοι πλεῖστα δίκαια φιλίας κρατίστους ὄντας κἀμοὶ τιμίους."},{"number":14,"text":"ἔγραψα δὲ περὶ τούτων καὶ Κουσπίῳ Φάδῳ τῷ ʼμῷ ἐπιτρόπῳ. οἱ τὰ γράμματα κομίζοντες Κορνήλιος Κέρωνος Τρύφων Θευδίωνος Δωρόθεος Ναθαναήλου Ἰωάννης Ἰωάννου. ἐγράφη πρὸ τεσσάρων καλανδῶν ἐπὶ ὑπάτων Ῥούφου καὶ Πομπηίου Σιλουανοῦ."},{"number":15,"text":"Ἠιτήσατο δὲ καὶ Ἡρώδης, ὁ ἀδελφὸς μὲν Ἀγρίππα τοῦ τετελευτηκότος, Χαλκίδος δὲ τὴν ἀρχὴν κατὰ τὸν χρόνον ἐκεῖνον πεπιστευμένος, Κλαύδιον Καίσαρα τὴν ἐξουσίαν τοῦ νεὼ καὶ τῶν ἱερῶν χρημάτων καὶ τὴν τῶν ἀρχιερέων χειροτονίαν, πάντων τε ἐπέτυχεν."},{"number":16,"text":"ἐξ ἐκείνου τε πᾶσι τοῖς ἀπογόνοις αὐτοῦ παρέμεινεν ἡ ἐξουσία μέχρι τῆς τοῦ πολέμου τελευτῆς. καὶ δὴ ὁ Ἡρώδης μεθίστησιν τῆς ἀρχιερωσύνης τὸν ἐπικαλούμενον Κανθήραν Ἰωσήπῳ τῷ Καμεὶ ἀντʼ ἐκείνου τὴν διαδοχὴν τῆς τιμῆς παρασχόμενος."}],"2":[{"number":17,"text":"Κατὰ τοῦτον δὲ τὸν καιρὸν τῶν Ἀδιαβηνῶν βασιλὶς Ἑλένη καὶ ὁ παῖς αὐτῆς Ἰζάτης εἰς τὰ Ἰουδαίων ἔθη τὸν βίον μετέβαλον διὰ τοιαύτην αἰτίαν·"},{"number":18,"text":"Μονόβαζος ὁ τῶν Ἀδιαβηνῶν βασιλεύς, ᾧ καὶ Βαζαῖος ἐπίκλησις ἦν, τῆς ἀδελφῆς Ἑλένης ἁλοὺς ἔρωτι τῇ πρὸς γάμου κοινωνίᾳ ἄγεται καὶ κατέστησεν ἐγκύμονα. συγκαθεύδων δέ ποτε τῇ γαστρὶ τῆς γυναικὸς τὴν χεῖρα προσαναπαύσας ἡνίκα καθύπνωσεν, φωνῆς τινος ἔδοξεν ὑπακούειν κελευούσης αἴρειν ἀπὸ τῆς νηδύος τὴν χεῖρα καὶ μὴ θλίβειν τὸ ἐν αὐτῇ βρέφος θεοῦ προνοίᾳ καὶ ἀρχῆς τυχὸν καὶ τέλους εὐτυχοῦς τευξόμενον."},{"number":19,"text":"ταραχθεὶς οὖν ὑπὸ τῆς φωνῆς εὐθὺς διεγερθεὶς ἔφραζε τῇ γυναικὶ ταῦτα, καί γε τὸν υἱὸν Ἰζάτην ἐπεκάλεσεν."},{"number":20,"text":"ἦν δὲ αὐτῷ Μονόβαζος τούτου πρεσβύτερος ἐκ τῆς Ἑλένης γενόμενος ἄλλοι τε παῖδες ἐξ ἑτέρων γυναικῶν. τὴν μέντοι πᾶσαν εὔνοιαν ὡς εἰς μονογενῆ τὸν Ἰζάτην ἔχων φανερὸς ἦν."},{"number":21,"text":"φθόνος δὲ τοὐντεῦθεν τῷ παιδὶ παρὰ τῶν ὁμοπατρίων ἀδελφῶν ἐφύετο κἀκ τούτου μῖσος ηὔξετο λυπουμένων ἁπάντων, ὅτι τὸν Ἰζάτην αὐτῶν ὁ πατὴρ προτιμῴη."},{"number":22,"text":"ταῦτα δὲ καίπερ σαφῶς αἰσθανόμενος ὁ πατὴρ ἐκείνοις μὲν συνεγίνωσκεν ὡς μὴ διὰ κακίαν αὐτὸ πάσχουσιν ἀλλʼ ἤτοι παρὰ τοῦ πατρὸς αὐτῶν ἕκαστον ἀξιῶν εὐνοίας τυγχάνειν, τὸν δὲ νεανίαν, σφόδρα γὰρ ἐδεδοίκει περὶ αὐτοῦ, μὴ μισούμενος ὑπὸ τῶν ἀδελφῶν πάθοι τι, πολλὰ δωρησάμενος πρὸς Ἀβεννήριγον ἐκπέμπει τὸν Σπασίνου χάρακος βασιλέα, παρακατατιθέμενος ἐκείνῳ τὴν τοῦ παιδὸς σωτηρίαν."},{"number":23,"text":"ὁ δὲ Ἀβεννήριγος ἄσμενός τε δέχεται τὸν νεανίαν καὶ διὰ πολλῆς εὐνοίας ἄγων γυναῖκα μὲν αὐτῷ τὴν θυγατέρα, Σαμαχὼς δʼ ἦν ὄνομα ταύτῃ, δίδωσι· δωρεῖται δὲ χώραν, ἐξ ἧς μεγάλας λήψοιτο προσόδους."},{"number":24,"text":"Μονόβαζος δὲ ἤδη γηραιὸς ὢν καὶ τοῦ ζῆν ὀλίγον αὐτῷ τὸν λοιπὸν ὁρῶν χρόνον ἠθέλησεν εἰς ὄψιν ἀφικέσθαι τῷ παιδὶ πρὸ τοῦ τελευτῆσαι. μεταπεμψάμενος οὖν αὐτὸν ἀσπάζεται φιλοφρονέστατα, καὶ χώραν δίδωσιν Καρρῶν λεγομένην."},{"number":25,"text":"φέρειν δʼ ἡ γῆ πλεῖστον τὸ ἄμωμον ἀγαθή· ἔστι δʼ ἐν αὐτῇ καὶ τὰ λείψανα τῆς λάρνακος, ᾗ Νῶχον ἐκ τῆς ἐπομβρίας διασεσῶσθαι λόγος ἔχει, καὶ μέχρι νῦν ταῦτα τοῖς ἰδεῖν βουλομένοις ἐπιδείκνυται."},{"number":26,"text":"διέτριβεν οὖν ὁ Ἰζάτης ἐν τῇ χώρᾳ ταύτῃ μέχρι τῆς τελευτῆς τοῦ πατρός. ᾗ δʼ ἐξέλιπεν ἡμέρᾳ τὸν βίον ὁ Μονόβαζος ἡ βασιλὶς Ἑλένη μεταπέμπεται πάντας τοὺς μεγιστᾶνας καὶ τῆς βασιλείας σατράπας καὶ τοὺς τὰς δυνάμεις πεπιστευμένους."},{"number":27,"text":"οἷς ἀφικομένοις, ὅτι μὲν ὁ ἐμὸς ἀνήρ, εἶπε, τῆς βασιλείας αὐτῷ διάδοχον Ἰζάτην ηὔξατο γενέσθαι καὶ τοῦτον ἄξιον ἔκρινεν, οὐδʼ ὑμᾶς λεληθέναι δοκῶ, περιμένω δὲ ὅμως καὶ τὴν ὑμετέραν κρίσιν· μακάριος γὰρ οὐχ ὁ παρʼ ἑνός, ἀλλὰ πλειόνων καὶ θελόντων τὴν ἀρχὴν λαμβάνων."},{"number":28,"text":"ἡ μὲν ταῦτʼ εἶπεν ἐπὶ πείρᾳ τοῦ τί φρονοῖεν οἱ συγκληθέντες· οἱ δὲ ἀκούσαντες πρῶτον μὲν προσεκύνησαν τὴν βασιλίδα, καθὼς ἔθος ἐστὶν αὐτοῖς, εἶτʼ ἔφασαν τὴν τοῦ βασιλέως γνώμην βεβαιοῦν καὶ ὑπακούσεσθαι χαίροντες Ἰζάτῃ δικαίως ὑπὸ τοῦ πατρὸς προκριθέντι τῶν ἀδελφῶν κατὰ τὰς εὐχὰς τὰς ἁπάντων."},{"number":29,"text":"βούλεσθαί τʼ ἔφασαν προαποκτεῖναι πρῶτον αὐτοῦ τοὺς ἀδελφοὺς καὶ συγγενεῖς ὑπὲρ τοῦ τὴν ἀρχὴν Ἰζάτην μετʼ ἀσφαλείας κατασχεῖν· φθαρέντων γὰρ ἐκείνων καθαιρεθήσεσθαι πάντα τὸν φόβον τὸν ὑπὸ μίσους τοῦ παρʼ αὐτῶν καὶ φθόνου γινόμενον."},{"number":30,"text":"πρὸς ταῦτα ἡ Ἑλένη χάριν μὲν αὐτοῖς ὡμολόγει τῆς πρὸς αὐτὴν καὶ τὸν Ἰζάτην εὐνοίας ἔχειν, παρεκάλει δʼ ὅμως ἐπισχεῖν τὴν περὶ τῆς ἀναιρέσεως τῶν ἀδελφῶν γνώμην μέχρι ἂν Ἰζάτης παραγενόμενος συνδοκιμάσῃ."},{"number":31,"text":"οἱ δʼ ἐπεὶ ἀνελεῖν συμβουλεύσαντες οὐκ ἔπεισαν, ἀλλὰ φυλάσσειν αὐτοὺς δεσμίους παρῄνουν μέχρι τῆς ἐκείνου παρουσίας ὑπὲρ ἀσφαλείας τῆς ἑαυτῶν. συνεβούλευον δʼ αὐτῇ μεταξὺ προστήσασθαί τινα τῆς ἀρχῆς ἐπίτροπον, ᾧ μάλιστα πιστεύει."},{"number":32,"text":"πείθεται τούτοις ἡ Ἑλένη, καὶ καθίστησι τὸν πρεσβύτατον παῖδα Μονόβαζον βασιλέα περιθεῖσα τὸ διάδημα καὶ δοῦσα τὸν σημαντῆρα τοῦ πατρὸς δακτύλιον τήν τε σαμψηρὰν ὀνομαζομένην παρʼ αὐτοῖς, διοικεῖν τε τὴν βασιλείαν παρῄνεσεν μέχρι τῆς τοῦ ἀδελφοῦ παρουσίας."},{"number":33,"text":"ἧκε δʼ οὗτος ταχέως ἀκούσας τὴν τοῦ πατρὸς τελευτὴν καὶ διαδέχεται τὸν ἀδελφὸν Μονόβαζον ὑπεκστάντος τῆς ἀρχῆς αὐτῷ."},{"number":34,"text":"Καθʼ ὃν δὲ χρόνον ὁ Ἰζάτης ἐν τῷ Σπασίνου χάρακι διέτριβεν Ἰουδαῖός τις ἔμπορος Ἀνανίας ὄνομα πρὸς τὰς γυναῖκας εἰσιὼν τοῦ βασιλέως ἐδίδασκεν αὐτὰς τὸν θεὸν σέβειν, ὡς Ἰουδαίοις πάτριον ἦν,"},{"number":35,"text":"καὶ δὴ διʼ αὐτῶν εἰς γνῶσιν ἀφικόμενος τῷ Ἰζάτῃ κἀκεῖνον ὁμοίως συνανέπεισεν μετακληθέντι τε ὑπὸ τοῦ πατρὸς εἰς τὴν Ἀδιαβηνὴν συνεξῆλθεν κατὰ πολλὴν ὑπακούσας δέησιν· συνεβεβήκει δὲ καὶ τὴν Ἑλένην ὁμοίως ὑφʼ ἑτέρου τινὸς Ἰουδαίου διδαχθεῖσαν εἰς τοὺς ἐκείνων μετακεκομίσθαι νόμους."},{"number":36,"text":"ὁ δʼ Ἰζάτης ὡς παρέλαβεν τὴν βασιλείαν, ἀφικόμενος εἰς τὴν Ἀδιαβηνὴν καὶ θεασάμενος τούς τε ἀδελφοὺς καὶ τοὺς ἄλλους συγγενεῖς δεδεμένους ἐδυσχέρανεν τῷ γεγονότι."},{"number":37,"text":"καὶ τὸ μὲν ἀνελεῖν ἢ φυλάττειν δεδεμένους ἀσεβὲς ἡγούμενος, τὸ δὲ μνησικακοῦντας ἔχειν σὺν αὐτῷ μὴ δεδεμένους σφαλερὸν εἶναι νομίζων, τοὺς μὲν ὁμηρεύσοντας μετὰ τέκνων εἰς τὴν Ῥώμην ἐξέπεμψε Κλαυδίῳ Καίσαρι, τοὺς δὲ πρὸς Ἀρταβάνην τὸν Πάρθον ἐφʼ ὁμοίαις προφάσεσιν ἀπέστειλεν."},{"number":38,"text":"Πυθόμενος δὲ πάνυ τοῖς Ἰουδαίων ἔθεσιν χαίρειν τὴν μητέρα τὴν ἑαυτοῦ ἔσπευσε καὶ αὐτὸς εἰς ἐκεῖνα μεταθέσθαι, νομίζων τε μὴ ἂν εἶναι βεβαίως Ἰουδαῖος, εἰ μὴ περιτέμνοιτο, πράττειν ἦν ἕτοιμος."},{"number":39,"text":"μαθοῦσα δʼ ἡ μήτηρ κωλύειν ἐπειρᾶτο ἐπιφέρειν αὐτῷ κίνδυνον λέγουσα· βασιλέα γὰρ εἶναι, καὶ καταστήσειν εἰς πολλὴν δυσμένειαν τοὺς ὑπηκόους μαθόντας, ὅτι ξένων ἐπιθυμήσειεν καὶ ἀλλοτρίων αὐτοῖς ἐθῶν, οὐκ ἀνέξεσθαί τε βασιλεύοντος αὐτῶν Ἰουδαίου."},{"number":40,"text":"καὶ ἡ μὲν ταῦτʼ ἔλεγεν καὶ παντοίως ἐκώλυεν. ὁ δʼ εἰς τὸν Ἀνανίαν τοὺς λόγους ἀνέφερεν. τοῦ δὲ τῇ μητρὶ συμφάσκοντος καὶ συναπειλήσαντος ὡς εἰ μὴ πείθοι καταλιπὼν ἄπεισιν·"},{"number":41,"text":"δεδοικέναι γὰρ ἔλεγεν, μὴ τοῦ πράγματος ἐκδήλου πᾶσιν γενομένου κινδυνεύσειε τιμωρίαν ὑποσχεῖν ὡς αὐτὸς αἴτιος τούτων καὶ διδάσκαλος τῷ βασιλεῖ ἀπρεπῶν ἔργων γενόμενος, δυνάμενον δʼ αὐτὸν ἔφη καὶ χωρὶς τῆς περιτομῆς τὸ θεῖον σέβειν, εἴγε πάντως κέκρικε ζηλοῦν τὰ πάτρια τῶν Ἰουδαίων· τοῦτʼ εἶναι κυριώτερον τοῦ περιτέμνεσθαι·"},{"number":42,"text":"συγγνώμην δʼ ἕξειν αὐτῷ καὶ τὸν θεὸν φήσαντος μὴ πράξαντι τὸ ἔργον διʼ ἀνάγκην καὶ τὸν ἐκ τῶν ὑπηκόων φόβον, ἐπείσθη μὲν τότε τοῖς λόγοις ὁ βασιλεύς."},{"number":43,"text":"μετὰ ταῦτα δέ, τὴν γὰρ ἐπιθυμίαν οὐκ ἐξεβεβλήκει παντάπασιν, Ἰουδαῖός τις ἕτερος ἐκ τῆς Γαλιλαίας ἀφικόμενος Ἐλεάζαρος ὄνομα πάνυ περὶ τὰ πάτρια δοκῶν ἀκριβὴς εἶναι προετρέψατο πρᾶξαι τοὖργον."},{"number":44,"text":"ἐπεὶ γὰρ εἰσῆλθεν ἀσπασόμενος αὐτὸν καὶ κατέλαβε τὸν Μωυσέος νόμον ἀναγινώσκοντα, λανθάνεις, εἶπεν, ὦ βασιλεῦ, τὰ μέγιστα τοὺς νόμους καὶ διʼ αὐτῶν τὸν θεὸν ἀδικῶν· οὐ γὰρ ἀναγινώσκειν σε δεῖ μόνον αὐτούς, ἀλλὰ καὶ πρότερον τὰ προστασσόμενα ποιεῖν ὑπʼ αὐτῶν."},{"number":45,"text":"μέχρι τίνος ἀπερίτμητος μενεῖς; ἀλλʼ εἰ μήπω τὸν περὶ τούτου νόμον ἀνέγνως, ἵνʼ εἰδῇς τίς ἐστιν ἡ ἀσέβεια, νῦν ἀνάγνωθι."},{"number":46,"text":"ταῦτα ἀκούσας ὁ βασιλεὺς οὐχ ὑπερεβάλετο τὴν πρᾶξιν, μεταστὰς δʼ εἰς ἕτερον οἴκημα καὶ τὸν ἰατρὸν εἰσκαλεσάμενος τὸ προσταχθὲν ἐτέλει καὶ μεταπεμψάμενος τήν τε μητέρα καὶ τὸν διδάσκαλον Ἀνανίαν ἐσήμαινεν αὐτὸν πεπραχέναι τοὖργον."},{"number":47,"text":"τοὺς δʼ ἔκπληξις εὐθὺς ἔλαβεν καὶ φόβος οὔτι μέτριος, μὴ τῆς πράξεως εἰς ἔλεγχον ἐλθούσης κινδυνεύσειεν μὲν ὁ βασιλεὺς τὴν ἀρχὴν ἀποβαλεῖν οὐκ ἀνασχομένων τῶν ὑπηκόων ἄρχειν αὐτῶν ἄνδρα τῶν παρʼ ἑτέροις ζηλωτὴν ἐθῶν, κινδυνεύσειαν δὲ καὶ αὐτοὶ τῆς αἰτίας ἐπʼ αὐτοῖς ἐνεχθείσης."},{"number":48,"text":"θεὸς δʼ ἦν ὁ κωλύσων ἄρα τοὺς ἐκείνων φόβους ἐλθεῖν ἐπὶ τέλος· πολλοῖς γὰρ αὐτόν τε τὸν Ἰζάτην περιπεσόντα κινδύνοις καὶ παῖδας τοὺς ἐκείνου διέσωσεν ἐξ ἀμηχάνων πόρον εἰς σωτηρίαν παρασχών, ἐπιδεικνὺς ὅτι τοῖς εἰς αὐτὸν ἀποβλέπουσιν καὶ μόνῳ πεπιστευκόσιν ὁ καρπὸς οὐκ ἀπόλλυται ὁ τῆς εὐσεβείας. ἀλλὰ ταῦτα μὲν ὕστερον ἀπαγγελοῦμεν."},{"number":49,"text":"Ἑλένη δὲ ἡ τοῦ βασιλέως μήτηρ ὁρῶσα τὰ μὲν κατὰ τὴν βασιλείαν εἰρηνευόμενα, τὸν δὲ υἱὸν αὐτῆς μακάριον καὶ παρὰ πᾶσι ζηλωτὸν καὶ τοῖς ἀλλοεθνέσι διὰ τὴν ἐκ τοῦ θεοῦ πρόνοιαν, ἐπιθυμίαν ἔσχεν εἰς τὴν Ἱεροσολυμιτῶν πόλιν ἀφικομένη τὸ πᾶσιν ἀνθρώποις περιβόητον ἱερὸν τοῦ θεοῦ προσκυνῆσαι καὶ χαριστηρίους θυσίας προσενεγκεῖν, ἐδεῖτό τε τοῦ παιδὸς ἐπιτρέψαι."},{"number":50,"text":"τοῦ δὲ πάνυ προθύμως τῇ μητρὶ παρακαλούσῃ κατανεύσαντος καὶ πολλὴν παρασκευὴν τῶν εἰς τὴν ἀποστολὴν ἑτοιμασαμένου καὶ χρήματα πλεῖστα δόντος, καταβαίνει εἰς τὴν Ἱεροσολυμιτῶν πόλιν προπέμποντος ἐπὶ πολὺ τοῦ παιδός."},{"number":51,"text":"γίνεται δὲ αὐτῆς ἡ ἄφιξις πάνυ συμφέρουσα τοῖς Ἱεροσολυμίταις· λιμοῦ γὰρ αὐτῶν τὴν πόλιν κατὰ τὸν καιρὸν ἐκεῖνον πιεζοῦντος καὶ πολλῶν ὑπʼ ἐνδείας ἀναλωμάτων φθειρομένων ἡ βασιλὶς Ἑλένη πέμπει τινὰς τῶν ἑαυτῆς, τοὺς μὲν εἰς τὴν Ἀλεξάνδρειαν πολλῶν σῖτον ὠνησομένους χρημάτων, τοὺς δʼ εἰς Κύπρον ἰσχάδων φόρτον οἴσοντας."},{"number":52,"text":"ὡς δʼ ἐπανῆλθον ταχέως κομίζοντες τοῖς ἀπορουμένοις διένειμε τροφὴν καὶ μεγίστην αὐτῆς μνήμην τῆς εὐποιίας ταύτης εἰς τὸ πᾶν ἡμῶν ἔθνος καταλέλοιπε."},{"number":53,"text":"πυθόμενος δὲ καὶ ὁ παῖς αὐτῆς Ἰζάτης τὰ περὶ τὸν λιμὸν ἔπεμψε πολλὰ χρήματα τοῖς πρώτοις τῶν Ἱεροσολυμιτῶν. ἀλλὰ γὰρ ἃ τοῖς βασιλεῦσιν εἰς τὴν πόλιν ἡμῶν ἀγαθὰ πέπρακται μετὰ ταῦτα δηλώσομεν."}],"3":[{"number":54,"text":"Ὁ δὲ τῶν Πάρθων βασιλεὺς Ἀρταβάνης αἰσθόμενος τοὺς σατράπας ἐπιβουλὴν ἐπʼ αὐτὸν συντεθεικότας, μένειν παρʼ αὐτοῖς ἀσφαλὲς οὐχ ὁρῶν ἔγνω πρὸς Ἰζάτην ἀπαίρειν, πόρον παρʼ αὐτοῦ βουλόμενος σωτηρίας εὑρέσθαι καὶ κάθοδον εἰς τὴν ἀρχήν, εἰ δυνηθείη."},{"number":55,"text":"καὶ δὴ ἀφικνεῖται συγγενῶν τε καὶ οἰκετῶν περὶ χιλίους τὸν ἀριθμὸν ἐπαγόμενος συντυγχάνει τε τῷ Ἰζάτῃ καθʼ ὁδόν."},{"number":56,"text":"αὐτός τε σαφῶς ἐκεῖνον ἐπιστάμενος, ὑπʼ Ἰζάτου δὲ οὐ γινωσκόμενος, πλησίον καταστὰς πρῶτον μὲν κατὰ τὸ πάτριον προσεκύνησεν αὐτόν, εἶτα βασιλεῦ , φησίν, μὴ περιίδῃς με τὸν σὸν ἱκέτην μηδʼ ὑπερηφανήσῃς δεομένου· ταπεινὸς γὰρ ἐκ μεταβολῆς γενόμενος καὶ ἐκ βασιλέως ἰδιώτης τῆς σῆς ἐπικουρίας χρῄζω."},{"number":57,"text":"βλέψον οὖν εἰς τὸ τῆς τύχης ἄστατον καὶ κοινὴν εἶναι νόμισον καὶ ὑπὲρ σαυτοῦ πρόνοιαν· ἐμοῦ γὰρ ἀνεκδικήτου περιοφθέντος ἔσονται θρασύτεροι πολλοὶ καὶ κατὰ τῶν ἄλλων βασιλέων."},{"number":58,"text":"ὁ μὲν ταῦτʼ ἔλεγεν δακρύων καὶ τῇ κεφαλῇ κάτω νεύων, ὁ δὲ Ἰζάτης ὡς ἤκουσε τοὔνομα καὶ εἶδεν ἱκέτην αὐτῷ παρεστῶτα τὸν Ἀρταβάνην, κατεπήδησεν ἀπὸ τοῦ ἵππου καί θάρσησον,"},{"number":59,"text":"εἶπεν, ὦ βασιλεῦ, μηδέ σε συγχείτω τὸ παρὸν ὡς ἀνήκεστον· ταχεῖα γὰρ ἔσται τῆς λύπης ἡ μεταβολή. φίλον δέ με καὶ σύμμαχον εὑρήσεις κρείττω τῆς ἐλπίδος· ἢ γὰρ εἰς τὴν Πάρθων σε καταστήσω βασιλείαν πάλιν ἢ τῆς ἐμῆς ἐκστήσομαι."},{"number":60,"text":"Ταῦτα εἰπὼν ἀνεβίβαζεν τὸν Ἀρταβάνην ἐπὶ τὸν ἵππον, παρείπετο δʼ αὐτὸς πεζὸς τιμὴν ἀπονέμων ταυτηνὶ ὡς ἂν μείζονι βασιλεῖ. θεασάμενος δʼ Ἀρταβάνης βαρέως ἤνεγκεν καὶ τὴν ἐφεστῶσαν αὐτῷ τύχην καὶ τιμὴν ἐπωμόσατο καταβήσεσθαι μὴ ʼκείνου πάλιν ἀναβάντος καὶ προηγουμένου."},{"number":61,"text":"ὁ δὲ πεισθεὶς ἐπὶ τὸν ἵππον ἥλατο καὶ ἀγαγὼν αὐτὸν εἰς τὴν βασιλείαν πᾶσαν τιμὴν ἀπένειμεν ἔν τε συνεδρίαις καὶ ταῖς περὶ τὰς ἑστιάσεις προκατακλίσεσιν, οὐκ εἰς τὸ παρὸν αὐτοῦ τῆς τύχης ἀποβλέπων, ἀλλʼ εἰς τὸ πρότερον ἀξίωμα, καί τι καὶ λογισμῷ διδούς, ὡς κοιναὶ τοῖς ἀνθρώποις αἱ μεταβολαὶ τῆς τύχης."},{"number":62,"text":"γράφει τε πρὸς τοὺς Πάρθους πείθων αὐτοὺς τὸν Ἀρταβάνην ὑποδέξασθαι, πίστιν προτείνων τῆς τῶν πεπραγμένων ἀμνηστίας δεξιὰν καὶ ὅρκους καὶ μεσιτείαν τὴν αὐτοῦ."},{"number":63,"text":"τῶν δὲ Πάρθων δέξασθαι μὲν αὐτὸν θέλειν οὐκ ἀρνουμένων, μὴ δύνασθαι δὲ λεγόντων διὰ τὸ τὴν ἀρχὴν ἑτέρῳ πεπιστευκέναι, Κίνναμος δʼ ἦν ὄνομα τῷ παρειληφότι, καὶ δεδοικέναι, μὴ στάσις αὐτοὺς ἐκ τούτου καταλάβῃ,"},{"number":64,"text":"μαθὼν τὴν προαίρεσιν αὐτῶν ὁ Κίνναμος ταύτην αὐτὸς γράφει τῷ Ἀρταβάνῃ, τέθραπτο γὰρ ὑπʼ αὐτοῦ καὶ φύσει δʼ ἦν καλὸς καὶ ἀγαθός, παρακαλῶν αὐτῷ πιστεύσαντα παραγενέσθαι τὴν ἀρχὴν ἀποληψόμενον τὴν αὐτοῦ."},{"number":65,"text":"καὶ ὁ Ἀρταβάνης πιστεύσας παρῆν. ὑπαντᾷ δʼ αὐτῷ ὁ Κίνναμος καὶ προσκυνήσας βασιλέα τε προσαγορεύσας περιτίθησιν αὐτοῦ τῇ κεφαλῇ τὸ διάδημα ἀφελὼν τῆς ἑαυτοῦ."},{"number":66,"text":"Καὶ Ἀρταβάνης οὕτω διὰ Ἰζάτου πάλιν εἰς τὴν ἀρχὴν καθίσταται πρότερον αὐτῆς ἐκπεσὼν διὰ τοὺς μεγιστᾶνας. οὐκ ἐγένετο μὴν ἀμνήμων τῶν εἰς αὐτὸν εὐεργεσιῶν, ἀλλʼ ἀντιδωρεῖται τὸν Ἰζάτην ταῖς μεγίσταις τιμαῖς παρʼ αὐτοῖς·"},{"number":67,"text":"τήν τε γὰρ τιάραν ὀρθὴν ἐπέτρεψεν αὐτῷ φορεῖν καὶ ἐπὶ κλίνης χρυσῆς καθεύδειν, ἅπερ μόνων ἐστὶ γέρα καὶ σημεῖα τῶν Πάρθων βασιλέων."},{"number":68,"text":"ἔδωκεν δὲ καὶ χώραν πολλὴν αὐτῷ κἀγαθὴν τοῦ τῶν Ἀρμενίων βασιλέως ἀποτεμόμενος, Νίσιβις δέ ἐστιν ὄνομα τῇ γῇ, καὶ ἐν αὐτῇ πρότερον Μακεδόνες ἐκτίσαντο πόλιν Ἀντιόχειαν, ἣν Ἐπιμυγδονίαν προσηγόρευσαν. ταύταις μὲν δὴ ταῖς τιμαῖς ὁ Ἰζάτης ὑπὸ τοῦ τῶν Πάρθων βασιλέως ἐτιμήθη."},{"number":69,"text":"Μετʼ οὐ πολὺν δὲ χρόνον Ἀρταβάνης τελευτᾷ τὴν βασιλείαν τῷ παιδὶ Οὐαρδάνῃ καταλιπών. οὗτος δὴ πρὸς τὸν Ἰζάτην ἀφικόμενος ἔπειθεν αὐτὸν μέλλων πρὸς Ῥωμαίους πόλεμον ἐκφέρειν συστρατεύεσθαι καὶ συμμαχίαν ἑτοιμάζειν."},{"number":70,"text":"οὐ μὴν ἔπειθεν· ὁ γὰρ Ἰζάτης τὴν Ῥωμαίων δύναμίν τε καὶ τύχην ἐπιστάμενος ἀδυνάτοις αὐτὸν ἐνόμιζεν ἐπιχειρεῖν."},{"number":71,"text":"ἔτι τε πεπομφὼς πέντε μὲν τὸν ἀριθμὸν υἱοὺς τὴν ἡλικίαν νέους γλῶτταν τὴν παρʼ ἡμῖν πάτριον καὶ παιδείαν ἀκριβῶς μαθησομένους, τὴν δὲ μητέρα προσκυνήσουσαν τὸ ἱερόν, ὡς προεῖπον, ὀκνηρότερος ἦν καὶ τὸν Οὐαρδάνην ἐκώλυεν συνεχῶς διηγούμενος τὰς Ῥωμαίων δυνάμεις τε καὶ πράξεις, διὰ τούτων οἰόμενος αὐτὸν φοβήσειν καὶ παύσειν ἐπιθυμοῦντα τῆς ἐπʼ αὐτοὺς στρατείας."},{"number":72,"text":"παροξυνθεὶς δʼ ἐπὶ τούτοις ὁ Πάρθος πόλεμον εὐθὺς πρὸς Ἰζάτην κατήγγειλεν. οὐ μὴν ἔλαβεν οὐδὲ τῆς ἐπὶ τούτῳ στρατείας ὄνησιν τοῦ θεοῦ τὰς ἐλπίδας αὐτοῦ πάσας ὑποτεμόντος·"},{"number":73,"text":"μαθόντες γὰρ οἱ Πάρθοι τὴν διάνοιαν τοῦ Οὐαρδάνου καὶ ὡς ἐπὶ Ῥωμαίους στρατεύειν ἔκρινεν, αὐτὸν μὲν ἀναιροῦσιν, τὴν ἀρχὴν δὲ τῷ ἀδελφῷ Κοτάρδῃ παρέδοσαν."},{"number":74,"text":"καὶ τοῦτον δὲ μετʼ οὐ πολὺν χρόνον ἐξ ἐπιβουλῆς τελευτήσαντα διαδέχεται Οὐολογέσης ὁ ἀδελφός, ὃς δὴ καὶ τοῖς ὁμοπατρίοις δυσὶν ἀδελφοῖς δυναστείας ἐπίστευσεν, Πακόρῳ μὲν τῷ καὶ πρεσβυτέρῳ τὴν Μήδων, Τιριδάτῃ δὲ τῷ νεωτέρῳ τὴν Ἀρμενίαν."}],"4":[{"number":75,"text":"Ὁ δὲ τοῦ βασιλέως ἀδελφὸς Μονόβαζος καὶ οἱ συγγενεῖς θεωροῦντες τὸν Ἰζάτην διὰ τὴν πρὸς τὸν θεὸν εὐσέβειαν ζηλωτὸν παρὰ πᾶσιν ἀνθρώποις γεγενημένον ἔσχον ἐπιθυμίαν καὶ αὐτοὶ τὰ πάτρια καταλιπόντες ἔθεσι χρῆσθαι τοῖς Ἰουδαίων."},{"number":76,"text":"γίνεται δʼ ἡ πρᾶξις αὐτῶν κατάφωρος τοῖς ὑπηκόοις, κἀπὶ τούτῳ χαλεπήναντες οἱ μεγιστᾶνες οὐκ ἐφανέρουν μὲν τὴν ὀργήν, κατὰ νοῦν δὲ ἔχοντες καιρὸν ἐπιτήδειον ἐζήτουν δίκην εἰσπράξασθαι σπεύδοντες παρʼ αὐτῶν."},{"number":77,"text":"καὶ δὴ γράφουσιν πρὸς Ἀβίαν τὸν Ἀράβων βασιλέα χρήματα πολλὰ δώσειν ὑπισχνούμενοι στρατεύσασθαι θελήσαντι κατὰ τοῦ παρʼ αὐτοῖς βασιλέως, ἐπηγγέλλοντο δὲ καὶ περὶ τὴν πρώτην συμβολὴν ἐγκαταλείψειν τὸν βασιλέα· θέλειν γὰρ αὐτὸν τιμωρήσασθαι μισήσαντα τὰ παρʼ αὐτοῖς ἔθη· καὶ ὅρκοις τὴν πρὸς ἀλλήλους ἐνδησάμενοι πίστιν σπεύδειν παρεκάλουν."},{"number":78,"text":"πείθεται δὲ ὁ Ἄραψ, καὶ πολλὴν ἐπαγόμενος δύναμιν ἧκεν ἐπὶ τὸν Ἰζάτην. μελλούσης δὲ τῆς πρώτης συμβολῆς πρὶν εἰς χεῖρας ἐλθεῖν καταλείπουσιν τὸν Ἰζάτην ἐκ συνθήματος πάντες ὡς πανικῷ δείματι κατασχεθέντες, καὶ τὰ νῶτα τοῖς πολεμίοις ἐντρέψαντες ἔφευγον."},{"number":79,"text":"οὐ μὴν ὁ Ἰζάτης κατεπλάγη, νοήσας δὲ προδοσίαν ὑπὸ τῶν μεγιστάνων γεγενῆσθαι καὶ αὐτὸς εἰς τὸ στρατόπεδον ὑπεχώρησεν, καὶ τὴν αἰτίαν ζητήσας ὡς ἔμαθεν συντεταγμένους πρὸς τὸν Ἄραβα, τοὺς μὲν αἰτίους ἀναιρεῖ, τῇ δʼ ἐπιούσῃ συμβαλὼν πλείστους μὲν ἀπέκτεινε,"},{"number":80,"text":"πάντας δὲ φυγεῖν ἠνάγκασεν, αὐτὸν δὲ τὸν βασιλέα διώκων εἴς τι φρούριον συνήλασεν Ἄρσαμον καλούμενον, καὶ προσμαχεσάμενος καρτερῶς εἷλε τὸ φρούριον διαρπάσας τε τὴν ἐν αὐτῷ λείαν πᾶσαν, πολλὴ δὲ ἦν, ὑπέστρεψεν εἰς τὴν Ἀδιαβηνὴν τὸν Ἀβίαν οὐ καταλαβὼν ζῶντα· περικαταλαμβανόμενος γὰρ ἑαυτὸν ἀνεῖλεν."},{"number":81,"text":"Ἀποτυχόντες δὲ οἱ τῶν Ἀδιαβηνῶν μεγιστᾶνες τῆς πρώτης ἐπιχειρήσεως παραδόντος αὐτοὺς τοῦ θεοῦ τῷ βασιλεῖ οὐδʼ ὣς ἠρέμουν, ἀλλὰ γράφουσιν πάλιν Οὐολογέσῃ, βασιλεὺς δὲ Πάρθων οὗτος ἦν, παρακαλοῦντες ἀποκτεῖναι μὲν τὸν Ἰζάτην, καταστῆσαι δʼ αὐτοῖς ἕτερον δυνάστην καὶ τῷ γένει Πάρθον· μισεῖν γὰρ ἔλεγον τὸν ἑαυτῶν βασιλέα καταλύσαντα μὲν τὰ πάτρια, ξένων δʼ ἐραστὴν ἐθῶν γενόμενον."},{"number":82,"text":"ταῦτα ἀκούσας ὁ Πάρθος ἐπήρθη πρὸς τὸν πόλεμον, καὶ προφάσεως δικαίας μηδεμίαν ἀφορμὴν ἔχων τὰς ὑπὸ τοῦ πατρὸς αὐτῷ δοθείσας τιμὰς ἔπεμψεν ἀπαιτῶν, ἀπειθήσαντι δὲ πόλεμον κατήγγελλεν."},{"number":83,"text":"ταράσσεται δὲ τὴν ψυχὴν οὐχὶ μετρίως ὁ Ἰζάτης, ὡς ἤκουσεν ταῦτα, κατάγνωσιν μὲν φέρειν αὐτῷ νομίσας τὸ τῶν δωρεῶν ἐξίστασθαι δοκεῖν διὰ φόβον τοῦτο πράξας."},{"number":84,"text":"εἰδὼς δέ, ὅτι καὶ ἀπολαβὼν ὁ Πάρθος τὰς τιμὰς οὐκ ἂν ἠρεμήσειεν, ἔκρινεν ἐπιτρέψαι τῷ κηδεμόνι θεῷ τὸν ὑπὲρ τῆς ψυχῆς κίνδυνον,"},{"number":85,"text":"καὶ τοῦτον μέγιστον ἡγησάμενος ἔχειν σύμμαχον κατατίθεται μὲν τὰ τέκνα καὶ τὰς γυναῖκας εἰς τὰ τῶν φρουρίων ἀσφαλέστατα, τὸν σῖτον δὲ πάντα μὲν τὸν εἰς τὰς βάρεις ἐμπίπρησιν τόν τε χόρτον καὶ τὰς νομάς, ταῦτά τε προευτρεπισάμενος ἐξεδέχετο τοὺς πολεμίους."},{"number":86,"text":"παραγενομένου δὲ τοῦ Πάρθου μετὰ πολλῆς δυνάμεως πεζῶν τε καὶ ἱππέων θᾶττον ἐλπίδος, ὥδευσε γὰρ συντόνως, βαλλομένου τε χάρακα πρὸς τῷ ποταμῷ τῷ τὴν Ἀδιαβηνὴν καὶ τὴν Μηδίαν ὁρίζοντι, τίθησι καὶ ὁ Ἰζάτης τὸ στρατόπεδον οὐκ ἄπωθεν ἔχων περὶ αὐτὸν ἱππεῖς τὸν ἀριθμὸν ἑξακισχιλίους."},{"number":87,"text":"ἀφικνεῖται δὲ πρὸς τὸν Ἰζάτην ἄγγελος παρὰ τοῦ Πάρθου πεμφθείς, ὃς τὴν Πάρθων δύναμιν ὅση τίς ἐστιν ἤγγελλεν ἀπὸ Εὐφράτου ποταμοῦ μέχρι Βάκτρων τοὺς ὅρους αὐτῆς τιθέμενος καὶ τοὺς ὑπηκόους αὐτῆς βασιλέας καταλέγων."},{"number":88,"text":"ἠπείλει δὲ δώσειν αὐτὸν δίκας ἀχάριστον περὶ δεσπότας τοὺς ἑαυτοῦ γενόμενον, καὶ ῥύεσθαι τῶν βασιλέως αὐτὸν χειρῶν οὐδὲ τὸν θεὸν ὃν σέβει δυνήσεσθαι."},{"number":89,"text":"ταῦτα τοῦ ἀγγέλου φράσαντος ὁ Ἰζάτης εἰδέναι μὲν τὴν Πάρθων δύναμιν ἔφη πολὺ τῆς αὐτοῦ διαφέρουσαν, γινώσκειν δʼ οὖν ἔτι μᾶλλον πάντων ἀνθρώπων ἔλεγεν κρείσσω τὸν θεόν. καὶ τοιαύτην δοὺς τὴν ἀπόκρισιν ἐπὶ τὴν ἱκετείαν ἐτρέπετο τοῦ θεοῦ, χαμαί τε ῥίψας αὑτὸν καὶ σποδῷ τὴν κεφαλὴν καταισχύνας μετὰ γυναικὸς καὶ τέκνων ἐνήστευεν ἀνακαλῶν τὸν θεὸν καὶ λέγων,"},{"number":90,"text":"εἰ μὴ μάτην, ὦ δέσποτα κύριε, τῆς σῆς ἐγενόμην χρηστότητος, τῶν πάντων δὲ δικαίως μόνον καὶ πρῶτον ἥγημαι κύριον, ἐλθὲ σύμμαχος οὐχ ὑπὲρ ἐμοῦ μόνον ἀμυνούμενος τοὺς πολεμίους, ἀλλʼ ὅτι καὶ τῆς σῆς δυνάμεως κατατετολμήκασιν."},{"number":91,"text":"ὁ μὲν ταῦτʼ ἐποτνιᾶτο δακρύων καὶ ὀδυρόμενος, ἐπήκοος δὲ ὁ θεὸς ἐγίνετο, καὶ κατʼ ἐκείνην εὐθὺς τὴν νύκτα δεξάμενος Οὐολογέσης ἐπιστολάς, ἐν αἷς ἐγέγραπτο Δαῶν καὶ Σακῶν χεῖρα μεγάλην καταφρονήσασαν αὐτοῦ τῆς ἀποδημίας ἐπιστρατευσαμένην διαρπάζειν τὴν Παρθυηνῶν, ἄπρακτος ἀνέζευξεν εἰς τοὐπίσω. καὶ Ἰζάτης οὕτω κατὰ θεοῦ πρόνοιαν τὰς ἀπειλὰς τοῦ Πάρθου διαφεύγει."},{"number":92,"text":"Μετʼ οὐ πολὺν δὲ χρόνον πεντηκοστὸν μὲν καὶ πέμπτον ἀπὸ γενεᾶς πληρώσας ἔτος τέταρτον δὲ πρὸς εἰκοστῷ δυναστεύσας, καταλιπὼν παῖδας ἄρρενας εἰκοσιτέσσαρας καὶ θυγατέρας εἰκοσιτέσσαρας καταστρέφει τὸν βίον."},{"number":93,"text":"τὴν μέντοι διαδοχὴν τῆς ἀρχῆς τὸν ἀδελφὸν Μονόβαζον ἐκέλευεν παραλαβεῖν, ἀμειβόμενος αὐτὸν ὅτι κατὰ τὴν ἀποδημίαν αὐτοῦ μετὰ τὸν τοῦ πατρὸς θάνατον πιστῶς φυλάξειεν αὐτῷ τὴν δυναστείαν."},{"number":94,"text":"ἡ δὲ μήτηρ Ἑλένη τὸν τοῦ παιδὸς θάνατον ἀκούσασα βαρέως μὲν ἤνεγκεν ὡς εἰκὸς μητέρα στερομένην εὐσεβεστάτου παιδός, παραμυθίαν δʼ ὅμως εἶχεν τὴν διαδοχὴν ἀκούσασα εἰς τὸν πρεσβύτερον αὐτῆς υἱὸν ἥκουσαν, καὶ πρὸς αὐτὸν ἔσπευδεν. παραγενομένη δὲ εἰς τὴν Ἀδιαβηνὴν οὐ πολὺν Ἰζάτῃ τῷ παιδὶ χρόνον ἐπεβίωσεν."},{"number":95,"text":"ὁ δὲ Μονόβαζος τά τε ἐκείνης ὀστᾶ καὶ τὰ τοῦ ἀδελφοῦ πέμψας εἰς Ἱεροσόλυμα θάψαι προσέταξεν ἐν ταῖς πυραμίσιν, ἃς ἡ μήτηρ κατεσκευάκει τρεῖς τὸν ἀριθμὸν τρία στάδια τῆς Ἱεροσολυμιτῶν πόλεως ἀπεχούσας."},{"number":96,"text":"ἀλλὰ Μονόβαζος μὲν ὁ βασιλεὺς ὅσα κατὰ τὸν τῆς ζωῆς χρόνον ἔπραξεν, ὕστερον ἀπαγγελοῦμεν."}],"5":[{"number":97,"text":"Φάδου δὲ τῆς Ἰουδαίας ἐπιτροπεύοντος γόης τις ἀνὴρ Θευδᾶς ὀνόματι πείθει τὸν πλεῖστον ὄχλον ἀναλαβόντα τὰς κτήσεις ἕπεσθαι πρὸς τὸν Ἰορδάνην ποταμὸν αὐτῷ· προφήτης γὰρ ἔλεγεν εἶναι, καὶ προστάγματι τὸν ποταμὸν σχίσας δίοδον ἔχειν ἔφη παρέξειν αὐτοῖς ῥᾳδίαν."},{"number":98,"text":"καὶ ταῦτα λέγων πολλοὺς ἠπάτησεν. οὐ μὴν εἴασεν αὐτοὺς τῆς ἀφροσύνης ὄνασθαι Φᾶδος, ἀλλʼ ἐξέπεμψεν ἴλην ἱππέων ἐπʼ αὐτούς, ἥτις ἀπροσδόκητος ἐπιπεσοῦσα πολλοὺς μὲν ἀνεῖλεν, πολλοὺς δὲ ζῶντας ἔλαβεν, αὐτὸν δὲ τὸν Θευδᾶν ζωγρήσαντες ἀποτέμνουσι τὴν κεφαλὴν καὶ κομίζουσιν εἰς Ἱεροσόλυμα."},{"number":99,"text":"τὰ μὲν οὖν συμβάντα τοῖς Ἰουδαίοις κατὰ τοὺς Κουσπίου Φάδου τῆς ἐπιτροπῆς χρόνους ταῦτʼ ἐγένετο."},{"number":100,"text":"Ἦλθε δὲ Φάδῳ διάδοχος Τιβέριος Ἀλέξανδρος Ἀλεξάνδρου παῖς τοῦ καὶ ἀλαβαρχήσαντος ἐν Ἀλεξανδρείᾳ γένει τε καὶ πλούτῳ πρωτεύσαντος τῶν ἐκεῖ καθʼ αὑτόν. διήνεγκε καὶ τῇ πρὸς τὸν θεὸν εὐσεβείᾳ τοῦ παιδὸς Ἀλεξάνδρου· τοῖς γὰρ πατρίοις οὐκ ἐνέμεινεν οὗτος ἔθεσιν."},{"number":101,"text":"ἐπὶ τούτου δὲ καὶ τὸν μέγαν λιμὸν κατὰ τὴν Ἰουδαίαν συνέβη γενέσθαι, καθʼ ὃν καὶ ἡ βασίλισσα Ἑλένη πολλῶν χρημάτων ὠνησαμένη σῖτον ἀπὸ τῆς Αἰγύπτου διένειμεν τοῖς ἀπορουμένοις, ὡς προεῖπον."},{"number":102,"text":"πρὸς τούτοις δὲ καὶ οἱ παῖδες Ἰούδα τοῦ Γαλιλαίου ἀνήχθησαν τοῦ τὸν λαὸν ἀπὸ Ῥωμαίων ἀποστήσαντος Κυρινίου τῆς Ἰουδαίας τιμητεύοντος, ὡς ἐν τοῖς πρὸ τούτων δεδηλώκαμεν, Ἰάκωβος καὶ Σίμων, οὓς ἀνασταυρῶσαι προσέταξεν Ἀλέξανδρος."},{"number":103,"text":"ὁ δὲ τῆς Χαλκίδος βασιλεὺς Ἡρώδης μεταστήσας τῆς ἀρχιερωσύνης Ἰώσηπον τὸν τοῦ Καμοιδὶ τὴν διαδοχὴν τῆς τιμῆς Ἀνανίᾳ τῷ τοῦ Νεβεδαίου δίδωσιν. Τιβερίῳ δὲ Ἀλεξάνδρῳ Κουμανὸς ἀφίκετο διάδοχος."},{"number":104,"text":"καὶ τελευτᾷ τὸν βίον Ἡρώδης ὁ τοῦ μεγάλου βασιλέως Ἀγρίππα ἀδελφὸς ὀγδόῳ τῆς Κλαυδίου Καίσαρος ἀρχῆς ἔτει, καταλιπὼν τρεῖς υἱοὺς Ἀριστόβουλον μὲν ὑπὸ τῆς πρώτης αὐτῷ τεχθέντα γυναικός, ἐκ Βερενίκης δὲ τῆς τἀδελφοῦ θυγατρὸς Βερενικιανὸν καὶ Ὑρκανόν. τὴν δʼ ἀρχὴν αὐτοῦ Καῖσαρ Κλαύδιος Ἀγρίππᾳ τῷ νεωτέρῳ δίδωσιν."},{"number":105,"text":"Στάσεως δʼ ἐμπεσούσης τῇ τῶν Ἱεροσολυμιτῶν πόλει Κουμανοῦ τὰ κατὰ τὴν Ἰουδαίαν πράγματα διοικοῦντος ἐφθάρησαν ὑπὸ ταύτης πολλοὶ τῶν Ἰουδαίων. καὶ πρότερον ἀφηγήσομαι τὴν αἰτίαν, διʼ ἣν ταῦτα συνέβη·"},{"number":106,"text":"τῆς πάσχα προσαγορευομένης ἑορτῆς ἐνστάσης, καθʼ ἣν ἔθος ἐστὶν ἡμῖν ἄζυμα προσφέρεσθαι, πολλοῦ καὶ πανταχόθεν πλήθους συναχθέντος ἐπὶ τὴν ἑορτὴν δείσας ὁ Κουμανός, μὴ νεώτερόν τι παρὰ τούτων προσπέσῃ, κελεύει τῶν στρατιωτῶν μίαν τάξιν ἀναλαβοῦσαν τὰ ὅπλα ἐπὶ τῶν τοῦ ἱεροῦ στοῶν ἑστάναι καταστελοῦντας τὸν νεωτερισμόν, εἰ ἄρα τις γένοιτο."},{"number":107,"text":"τοῦτο δὲ καὶ οἱ πρὸ αὐτοῦ τῆς Ἰουδαίας ἐπιτροπεύσαντες ἐν ταῖς ἑορταῖς ἔπραττον."},{"number":108,"text":"τετάρτῃ δὲ ἡμέρᾳ τῆς ἑορτῆς στρατιώτης τις ἀνακαλύψας ἐπεδείκνυε τῷ πλήθει τὰ αἰδοῖα, καὶ πρὸς τοῦτο θεασαμένων ὀργὴ καὶ θυμὸς ἦν οὐχ ἑαυτοὺς ὑβρίσθαι λεγόντων, ἀλλὰ τὸν θεὸν ἠσεβῆσθαι· τινὲς δὲ τῶν θρασυτέρων τὸν Κουμανὸν ἐβλασφήμουν ὑπʼ αὐτοῦ τὸν στρατιώτην καθεῖσθαι λέγοντες."},{"number":109,"text":"Κουμανὸς δʼ ἀκούσας καὶ αὐτὸς οὐ μετρίως ἐρεθίζεται πρὸς τὰς βλασφημίας, παρῄνει μέντοι παύσασθαι νεωτέρων ἐπιθυμοῦντας πραγμάτων μηδὲ στάσεις ἐξάπτειν ἐν ἑορτῇ."},{"number":110,"text":"μὴ πείθων δέ, μᾶλλον γὰρ ἐπέκειντο βλασφημοῦντες, κελεύει τὸ στράτευμα πᾶν τὰς πανοπλίας ἀναλαβὸν ἥκειν εἰς τὴν Ἀντωνίαν, φρούριον δʼ ἦν τοῦτο, καθάπερ καὶ πρότερον εἴπομεν, ἐπικείμενον τῷ ἱερῷ."},{"number":111,"text":"παραγενομένους δὲ τοὺς στρατιώτας θεασάμενον τὸ πλῆθος καὶ φοβηθὲν φεύγειν ὥρμησεν, τῶν δʼ ἐξόδων στενῶν οὐσῶν διώκεσθαι νομίζοντες ὑπὸ τῶν πολεμίων καὶ συνωθούμενοι κατὰ τὴν φυγὴν πολλοὺς ἀλλήλοις ἐν τοῖς στενοῖς θλιβόμενοι διέφθειρον."},{"number":112,"text":"δύο γοῦν μυριάδες ἐξηριθμήθησαν τῶν κατὰ τὴν στάσιν ἐκείνην φθαρέντων. πένθος δʼ ἦν τὸ λοιπὸν ἀντὶ τῆς ἑορτῆς, καὶ πάντες ἐκλαθόμενοι τῶν εὐχῶν καὶ τῶν θυσιῶν ἐπὶ θρήνους καὶ κλαυθμοὺς ἐτράποντο. τοιαῦτα μὲν ἑνὸς ἀσέλγεια στρατιώτου παθήματα γενέσθαι παρεσκεύασεν."},{"number":113,"text":"Οὔπω δʼ αὐτῶν τὸ πρῶτον πένθος ἐπέπαυτο καὶ κακὸν ἄλλο προσέπιπτεν· τῶν γὰρ ἀφεστώτων ἐπὶ νεωτερισμῷ τινες κατὰ τὴν δημοσίαν ὁδὸν ὡς ἑκατὸν σταδίων ἄπωθεν τῆς πόλεως Στέφανον Καίσαρος δοῦλον ὁδοιποροῦντα λῃστεύσαντες ἅπασαν αὐτοῦ τὴν κτῆσιν διαρπάζουσιν."},{"number":114,"text":"ἀκούσας δὲ τὸ πραχθὲν ὁ Κουμανὸς εὐθὺς πέμπει στρατιώτας, κελεύσας αὐτοῖς τὰς πλησίον κώμας διαρπάσαι, τοὺς δʼ ἐπιφανεστάτους αὐτῶν δήσαντας ἐπʼ αὐτὸν ἄγειν."},{"number":115,"text":"τῆς δὲ πορθήσεως γενομένης τῶν στρατιωτῶν τις τοὺς Μωυσέως νόμους ἔν τινι κώμῃ λαβὼν κειμένους προκομίσας εἰς τὴν πάντων ὄψιν διέσχισεν ἐπιβλασφημῶν καὶ πολλὰ κατακερτομῶν."},{"number":116,"text":"Ἰουδαῖοι δὲ ταῦτα ἀκούσαντες καὶ πολλοὶ συνδραμόντες καταβαίνουσιν εἰς Καισάρειαν, ἐκεῖ γὰρ ἐτύγχανεν ὁ Κουμανὸς ὤν, ἱκετεύοντες μὴ αὐτοὺς ἀλλὰ τὸν θεὸν οὗπερ οἱ νόμοι καθυβρίσθησαν ἐκδικῆσαι· ζῆν γὰρ οὐχ ὑπομένειν τῶν πατρίων αὐτοῖς οὕτως περιυβρισμένων. καὶ Κουμανὸς δείσας,"},{"number":117,"text":"μὴ πάλιν νεωτερίσειεν τὸ πλῆθος, συμβουλευσάντων καὶ τῶν φίλων τὸν ἐνυβρίσαντα τοῖς νόμοις στρατιώτην πελεκίσας ἔπαυσεν τὴν στάσιν ἐκ δευτέρου μέλλουσαν ἐξάπτεσθαι."}],"6":[{"number":118,"text":"Γίνεται δὲ καὶ Σαμαρείταις πρὸς Ἰουδαίους ἔχθρα διʼ αἰτίαν τοιαύτην· ἔθος ἦν τοῖς Γαλιλαίοις ἐν ταῖς ἑορταῖς εἰς τὴν ἱερὰν πόλιν παραγινομένοις ὁδεύειν διὰ τῆς Σαμαρέων χώρας. καὶ τότε καθʼ ὁδὸν αὐτοῖς κώμης Γιναῆς λεγομένης τῆς ἐν μεθορίῳ κειμένης Σαμαρείας τε καὶ τοῦ μεγάλου πεδίου τινὲς συνάψαντες μάχην πολλοὺς αὐτῶν ἀναιροῦσιν."},{"number":119,"text":"πυθόμενοι δὲ τὰ πραχθέντα τῶν Γαλιλαίων οἱ πρῶτοι πρὸς Κουμανὸν ἀφίκοντο καὶ παρεκάλουν αὐτὸν μετιέναι τῶν ἀνῃρημένων τὸν φόνον. ὁ δὲ χρήμασι πεισθεὶς ὑπὸ τῶν Σαμαρέων ὠλιγώρησεν."},{"number":120,"text":"ἀγανακτήσαντες δὲ ἐπὶ τούτῳ Γαλιλαῖοι τὸ πλῆθος τῶν Ἰουδαίων ἔπειθον ἐφʼ ὅπλα χωρῆσαι καὶ τῆς ἐλευθερίας ἀντέχεσθαι· δουλείαν γὰρ καὶ καθʼ αὑτὴν μὲν πικρὰν ἔλεγον εἶναι, τὴν ἐφʼ ὕβρει δὲ παντάπασιν ἀφόρητον."},{"number":121,"text":"τῶν δʼ ἐν τέλει καταπραΰνειν αὐτοὺς πειρωμένων καὶ πείσειν τὸν Κουμανὸν ἐπαγγελλομένων δίκας εἰσπράξασθαι παρὰ τῶν ἀνῃρηκότων, ἐκείνοις μὲν οὐ προσέσχον, ἀναλαβόντες δὲ τὰ ὅπλα καὶ βοηθεῖν Ἐλεάζαρον τὸν τοῦ Δειναίου παρακαλέσαντες, λῃστὴς δʼ οὗτος ἦν ἔτη πολλὰ τὴν διατριβὴν ἐν ὄρει πεποιημένος, κώμας τινὰς τῶν Σαμαρέων ἐμπρήσαντες διαρπάζουσι."},{"number":122,"text":"Κουμανὸς δὲ τῆς πράξεως εἰς αὐτὸν ἀφικομένης ἀναλαβὼν τὴν τῶν Σεβαστηνῶν ἴλην καὶ πεζῶν τέσσαρα τάγματα τούς τε Σαμαρεῖς καθοπλίσας ἐξῆλθεν ἐπὶ τοὺς Ἰουδαίους, καὶ συμβαλὼν πολλοὺς μὲν αὐτῶν ἀπέκτεινεν πλείους δὲ ζῶντας ἔλαβεν."},{"number":123,"text":"οἱ δὲ πρῶτοι κατὰ τιμὴν καὶ γένος τῶν Ἱεροσολυμιτῶν, ὡς εἶδον εἰς οἷον κακῶν μέγεθος ἥκουσιν, μετενδυσάμενοι σάκκους καὶ σποδοῦ τὰς κεφαλὰς ἀναπλήσαντες παντοῖοι τοὺς ἀφεστῶτας παρακαλοῦντες ἦσαν καὶ πείθοντες πρὸ ὀφθαλμῶν θεμένους κατασκαφησομένην μὲν αὐτῶν τὴν πατρίδα, τὸ δὲ ἱερὸν πυρποληθησόμενον, αὐτῶν δὲ καὶ γυναικῶν σὺν τέκνοις ἀνδραποδισμοὺς ἐσομένους, μεταθέσθαι τὸν λογισμὸν καὶ τὰ ὅπλα ῥίψαντας ἠρεμεῖν εἰς τὸ λοιπὸν ἀποχωρήσαντας εἰς τὰ αὑτῶν."},{"number":124,"text":"ταῦτα δὲ εἰπόντες ἔπεισαν. καὶ οἱ μὲν διελύθησαν, οἱ λῃσταὶ δὲ ἐπὶ τοὺς ἐχυροὺς τόπους πάλιν ἀπῆλθον. ἐξ ἐκείνου τε ἡ σύμπασα Ἰουδαία λῃστηρίων ἐπληρώθη."},{"number":125,"text":"Σαμαρέων δὲ οἱ πρῶτοι πρὸς Οὐμμίδιον Κοδρᾶτον τῆς Συρίας προεστηκότα κατὰ τὸν καιρὸν ἐκεῖνον ἐν Τύρῳ τυγχάνοντα παραγενόμενοι κατηγόρουν τῶν Ἰουδαίων, ὡς τὰς κώμας αὐτῶν ἐμπρήσειαν καὶ διαρπάσειαν,"},{"number":126,"text":"καὶ περὶ μὲν ὧν αὐτοὶ πεπόνθασιν οὐχ οὕτως ἀγανακτεῖν ἔφασκον, ὡς ὅτι Ῥωμαίων καταφρονήσειαν, ἐφʼ οὓς κριτὰς ἐχρῆν αὐτοὺς εἴπερ ἠδίκουν παραγενέσθαι, ἢ νῦν ὡς οὐκ ἐχόντων ἡγεμόνας Ῥωμαίους καταδραμεῖν· ἥκειν οὖν ἐπʼ αὐτὸν ἐκδικίας τευξόμενοι."},{"number":127,"text":"ταῦτα μὲν οὖν οἱ Σαμαρεῖς κατηγόρουν. Ἰουδαῖοι δὲ καὶ τῆς στάσεως καὶ τῆς μάχης αἰτίους γεγονέναι Σαμαρεῖς ἔφασαν, πρὸ πάντων δὲ Κουμανὸν δώροις ὑπʼ αὐτῶν φθαρέντα καὶ παρασιωπήσαντα τὸν τῶν ἀνῃρημένων φόνον."},{"number":128,"text":"καὶ Κουαδρᾶτος ἀκούσας ὑπερτίθεται τὴν κρίσιν, εἰπὼν ἀποφανεῖσθαι, ἐπειδὰν εἰς τὴν Ἰουδαίαν παραγενόμενος ἀκριβέστερον ἐπιγνῷ τὴν ἀλήθειαν."},{"number":129,"text":"καὶ οἱ μὲν ἀπῄεσαν ἄπρακτοι. μετʼ οὐ πολὺν δὲ χρόνον ὁ Κουαδρᾶτος ἧκεν εἰς Σαμάρειαν, ἔνθα διακούσας αἰτίους τῆς ταραχῆς ὑπέλαβε γεγονέναι τοὺς Σαμαρεῖς. Σαμαρέων δὲ καὶ Ἰουδαίων οὕστινας νεωτερίσαντας ἔμαθεν ἀνεσταύρωσεν οὓς Κουμανὸς ἔλαβεν αἰχμαλώτους."},{"number":130,"text":"κἀκεῖθεν εἰς κώμην τινὰ παραγενόμενος Λύδδαν πόλεως τὸ μέγεθος οὐκ ἀποδέουσαν καθίσας ἐπὶ βήματος κἀκ δευτέρου τῶν Σαμαρέων διακούσας διδάσκεται παρά τινος Σαμαρέως, ὅτι τῶν Ἰουδαίων τις πρῶτος ὄνομα Δόητος καί τινες σὺν αὐτῷ νεωτερισταὶ τέσσαρες τὸν ἀριθμὸν πείσειαν τὸν ὄχλον ἐπὶ τῇ Ῥωμαίων ἀποστάσει."},{"number":131,"text":"κἀκείνους μὲν ὁ Κουαδρᾶτος ἀνελεῖν προσέταξεν, τοὺς δὲ περὶ Ἀνανίαν τὸν ἀρχιερέα καὶ τὸν στρατηγὸν Ἄνανον δήσας εἰς Ῥώμην ἀνέπεμψεν περὶ τῶν πεπραγμένων λόγον ὑφέξοντας Κλαυδίῳ Καίσαρι."},{"number":132,"text":"κελεύει δὲ καὶ τοῖς τῶν Σαμαρέων πρώτοις καὶ τοῖς Ἰουδαίοις Κουμανῷ τε τῷ ἐπιτρόπῳ καὶ Κέλερι, χιλίαρχος δʼ ἦν οὗτος, ἐπʼ Ἰταλίας ἀπιέναι πρὸς τὸν αὐτοκράτορα κριθησομένους ἐπʼ αὐτοῦ περὶ τῶν πρὸς ἀλλήλους ζητήσεων."},{"number":133,"text":"αὐτὸς δὲ δείσας, μὴ τὸ πλῆθος πάλιν τῶν Ἰουδαίων νεωτερίσειεν, εἰς τὴν τῶν Ἱεροσολυμιτῶν πόλιν ἀφικνεῖται· καταλαμβάνει δʼ αὐτὴν εἰρηνευομένην καὶ πάτριον ἑορτὴν τῷ θεῷ τελοῦσαν. πιστεύσας οὖν μηδένα νεωτερισμὸν παρʼ αὐτῶν γενήσεσθαι καταλιπὼν ἑορτάζοντας ὑπέστρεψεν εἰς Ἀντιόχειαν."},{"number":134,"text":"Οἱ περὶ Κουμανὸν δὲ καὶ τοὺς πρώτους τῶν Σαμαρέων ἀναπεμφθέντες εἰς Ῥώμην λαμβάνουσι παρὰ τοῦ αὐτοκράτορος ἡμέραν, καθʼ ἣν περὶ τῶν πρὸς ἀλλήλους ἀμφισβητήσεων λέγειν ἔμελλον."},{"number":135,"text":"σπουδὴ δὲ μεγίστη τῷ Κουμανῷ καὶ τοῖς Σαμαρεῦσιν ἦν παρὰ τῶν Καίσαρος ἀπελευθέρων καὶ φίλων, κἂν περιεγένοντο τῶν Ἰουδαίων, εἰ μή περ Ἀγρίππας ὁ νεώτερος ἐν τῇ Ῥώμῃ τυγχάνων κατασπευδομένους ἰδὼν τοὺς τῶν Ἰουδαίων πρώτους ἐδεήθη πολλὰ τῆς τοῦ αὐτοκράτορος γυναικὸς Ἀγριππίνης πεῖσαι τὸν ἄνδρα διακούσαντα πρεπόντως τῇ ἑαυτοῦ δικαιοσύνῃ τιμωρήσασθαι τοὺς αἰτίους τῆς ἀποστάσεως."},{"number":136,"text":"καὶ Κλαύδιος τῇ δεήσει ταύτῃ προευτρεπισθεὶς καὶ διακούσας, ὡς εὗρε τῶν κακῶν ἀρχηγοὺς τοὺς Σαμαρείτας γενομένους, τοὺς μὲν ἀναβάντας πρὸς αὐτὸν ἐκέλευσεν ἀναιρεθῆναι, τῷ Κουμανῷ δὲ φυγὴν ἐπέβαλεν, Κέλερα δὲ τὸν χιλίαρχον ἐκέλευσεν ἀγαγόντας εἰς τὰ Ἱεροσόλυμα πάντων ὁρώντων ἐπὶ τὴν πόλιν πᾶσαν σύραντας οὕτως ἀποκτεῖναι."}],"7":[{"number":137,"text":"Πέμπει δὲ καὶ Κλαύδιον Φήλικα Πάλλαντος ἀδελφὸν τῶν κατὰ τὴν Ἰουδαίαν προστησόμενον πραγμάτων."},{"number":138,"text":"τῆς δʼ ἀρχῆς δωδέκατον ἔτος ἤδη πεπληρωκὼς δωρεῖται τὸν Ἀγρίππαν τῇ Φιλίππου τετραρχίᾳ καὶ Βαταναίᾳ προσθεὶς αὐτῷ τὴν Τραχωνῖτιν σὺν Ἀβέλλᾳ· Λυσανία δʼ αὕτη γεγόνει τετραρχία· τὴν Χαλκίδα δʼ αὐτὸν ἀφαιρεῖται δυναστεύσαντα ταύτης ἔτη τέσσαρα."},{"number":139,"text":"λαβὼν δὲ τὴν δωρεὰν παρὰ τοῦ Καίσαρος Ἀγρίππας ἐκδίδωσι πρὸς γάμον Ἀζίζῳ τῷ Ἐμεσῶν βασιλεῖ περιτέμνεσθαι θελήσαντι Δρούσιλλαν τὴν ἀδελφήν· Ἐπιφανὴς γὰρ ὁ Ἀντιόχου τοῦ βασιλέως παῖς παρῃτήσατο τὸν γάμον μὴ βουληθεὶς τὰ Ἰουδαίων ἔθη μεταλαβεῖν καίπερ τοῦτο ποιήσειν προϋπεσχημένος αὐτῆς τῷ πατρί."},{"number":140,"text":"καὶ Μαριάμμην δʼ ἐξέδωκεν Ἀρχελάῳ τῷ Ἑλκίου παιδὶ πρότερον ὑπὸ Ἀγρίππα τοῦ πατρὸς ἁρμοσθεῖσαν αὐτῷ, καὶ γίνεται θυγάτηρ αὐτοῖς ὄνομα Βερενίκη."},{"number":141,"text":"Διαλύονται δὲ τῇ Δρουσίλλῃ πρὸς τὸν Ἄζιζον οἱ γάμοι μετʼ οὐ πολὺν χρόνον τοιαύτης ἐμπεσούσης αἰτίας·"},{"number":142,"text":"καθʼ ὃν χρόνον τῆς Ἰουδαίας ἐπετρόπευε Φῆλιξ θεασάμενος ταύτην, καὶ γὰρ ἦν κάλλει πασῶν διαφέρουσα, λαμβάνει τῆς γυναικὸς ἐπιθυμίαν, καὶ Ἄτομον ὀνόματι τῶν ἑαυτοῦ φίλων Ἰουδαῖον, Κύπριον δὲ τὸ γένος, μάγον εἶναι σκηπτόμενον πέμπων πρὸς αὐτὴν ἔπειθεν τὸν ἄνδρα καταλιποῦσαν αὐτῷ γήμασθαι, μακαρίαν ποιήσειν ἐπαγγελλόμενος μὴ ὑπερηφανήσασαν αὐτόν."},{"number":143,"text":"ἡ δὲ κακῶς πράττουσα καὶ φυγεῖν τὸν ἐκ τῆς ἀδελφῆς Βερενίκης βουλομένη φθόνον αὑτῇ διὰ τὸ κάλλος παρεκάλει παρʼ ἐκείνης οἰόμενος οὐκ ἐν ὀλίγοις ἔβλαπτεν, παραβῆναί τε τὰ πάτρια νόμιμα πείθεται καὶ τῷ Φήλικι γήμασθαι."},{"number":144,"text":"τεκοῦσα δʼ ἐξ αὐτοῦ παῖδα προσηγόρευσεν Ἀγρίππαν. ἀλλʼ ὃν μὲν τρόπον ὁ νεανίας οὗτος σὺν τῇ γυναικὶ κατὰ τὴν ἐκπύρωσιν τοῦ Βεσβίου ὄρους ἐπὶ τῶν Τίτου Καίσαρος χρόνων ἠφανίσθη, μετὰ ταῦτα δηλώσω."},{"number":145,"text":"Βερενίκη δὲ μετὰ τὴν Ἡρώδου τελευτήν, ὃς αὐτῆς ἀνὴρ καὶ θεῖος ἐγεγόνει, πολὺν χρόνον ἐπιχηρεύσασα, φήμης ἐπισχούσης, ὅτι τἀδελφῷ συνείη, πείθει Πολέμωνα, Κιλικίας δὲ ἦν οὗτος βασιλεύς, περιτεμόμενον ἀγαγέσθαι πρὸς γάμον αὐτήν· οὕτως γὰρ ἐλέγξειν ᾤετο ψευδεῖς τὰς διαβολάς."},{"number":146,"text":"καὶ ὁ Πολέμων ἐπείσθη μάλιστα διὰ τὸν πλοῦτον αὐτῆς· οὐ μὴν ἐπὶ πολὺ συνέμεινεν ὁ γάμος, ἀλλʼ ἡ Βερενίκη διʼ ἀκολασίαν, ὡς ἔφασαν, καταλείπει τὸν Πολέμωνα. ὁ δʼ ἅμα τοῦ τε γάμου καὶ τοῦ τοῖς ἔθεσι τῶν Ἰουδαίων ἐμμένειν ἀπήλλακτο."},{"number":147,"text":"τῷ αὐτῷ δὲ καιρῷ καὶ Μαριάμμη παραιτησαμένη τὸν Ἀρχέλαον συνῴκησε Δημητρίῳ τῶν ἐν Ἀλεξανδρείᾳ Ἰουδαίων πρωτεύοντι γένει τε καὶ πλούτῳ· τότε δὴ καὶ τὴν ἀλαβαρχίαν αὐτὸς εἶχεν. γενόμενον δʼ αὐτῇ παιδίον ἐξ ἐκείνου Ἀγριππῖνον προσηγόρευσεν. ἀλλὰ περὶ μὲν ἑκάστου τούτων μετὰ ἀκριβείας ὕστερον ἀπαγγελοῦμεν."}],"8":[{"number":148,"text":"Τελευτᾷ δὲ Κλαύδιος Καῖσαρ βασιλεύσας ἔτη δεκατρία καὶ μῆνας ὀκτὼ πρὸς ἡμέραις εἴκοσι, καὶ λόγος ἦν παρά τινων, ὡς ὑπὸ τῆς γυναικὸς Ἀγριππίνης φαρμάκοις ἀνῄρητο. ταύτης πατὴρ μὲν ἦν Γερμανικὸς ὁ Καίσαρος ἀδελφός, ἀνὴρ δὲ γενόμενος Δομέτιος Ἠνόβαρβος ὁ τῶν ἐπισήμων κατὰ τὴν Ῥωμαίων πόλιν."},{"number":149,"text":"οὗ τελευτήσαντος χηρεύουσαν αὐτὴν ἐπὶ πολὺν χρόνον Κλαύδιος ἄγεται πρὸς γάμον ἐπαγομένην καὶ παῖδα Δομέτιον ὁμώνυμον τῷ πατρί. προανῃρήκει δὲ τὴν γυναῖκα Μεσσαλῖναν διὰ ζηλοτυπίαν, ἐξ ἧς αὐτῷ καὶ παῖδες ἐγεγόνεσαν Βρεττανικός τε καὶ Ὀκταουία."},{"number":150,"text":"ἦν γὰρ Ἀντωνιανὴ καὶ πρεσβυτάτη τῶν ἀδελφῶν, ἣν ἐκ Πετίνης τῆς πρώτης γυναικὸς εἶχεν. καὶ δὴ τὴν Ὀκταουίαν ἥρμοσεν τῷ Νέρωνι· τοῦτο γὰρ ὕστερον αὐτὸν ἐκάλεσεν εἰσποιησάμενος υἱὸν ὁ Καῖσαρ."},{"number":151,"text":"Δεδοικυῖα δʼ ἡ Ἀγριππῖνα, μὴ ὁ Βρεττανικὸς ἀνδρωθεὶς αὐτὸς παρὰ τοῦ πατρὸς τὴν ἀρχὴν παραλάβοι, τῷ δὲ αὐτῆς παιδὶ προαρπάσαι βουλομένη τὴν ἡγεμονίαν τά τε περὶ τὸν θάνατον τοῦ Κλαυδίου,"},{"number":152,"text":"καθάπερ ἦν λόγος, διεπράξατο, καὶ παραχρῆμα πέμπει τὸν τῶν στρατευμάτων ἔπαρχον Βοῦρρον καὶ σὺν αὐτῷ τοὺς χιλιάρχους τῶν τε ἀπελευθέρων τοὺς πλεῖστον δυναμένους ἀπάξοντας εἰς τὴν παρεμβολὴν τὸν Νέρωνα καὶ προσαγορεύσοντας αὐτὸν αὐτοκράτορα."},{"number":153,"text":"Νέρων δὲ τὴν ἀρχὴν οὕτως παραλαβὼν Βρεττανικὸν μὲν ἀδήλως τοῖς πολλοῖς ἀναιρεῖ διὰ φαρμάκων, φανερῶς δʼ οὐκ εἰς μακρὰν τὴν μητέρα τὴν ἑαυτοῦ φονεύει, ταύτην ἀμοιβὴν ἀποτίσας αὐτῇ οὐ μόνον τῆς γενέσεως ἀλλὰ καὶ τοῦ ταῖς ἐκείνης μηχαναῖς τὴν Ῥωμαίων ἡγεμονίαν παραλαβεῖν. κτείνει δὲ καὶ τὴν Ὀκταουίαν, ᾗ συνῴκει, πολλούς τε ἐπιφανεῖς ἄνδρας ὡς ἐπʼ αὐτὸν ἐπιβουλὰς συντιθέντας."},{"number":154,"text":"Ἀλλὰ περὶ μὲν τούτων ἐῶ πλείω γράφειν· πολλοὶ γὰρ τὴν περὶ Νέρωνα συντετάχασιν ἱστορίαν, ὧν οἱ μὲν διὰ χάριν εὖ πεπονθότες ὑπʼ αὐτοῦ τῆς ἀληθείας ἠμέλησαν, οἱ δὲ διὰ μῖσος καὶ τὴν πρὸς αὐτὸν ἀπέχθειαν οὕτως ἀναιδῶς ἐνεπαρῴνησαν τοῖς ψεύσμασιν, ὡς ἀξίους αὐτοὺς εἶναι καταγνώσεως."},{"number":155,"text":"καὶ θαυμάζειν οὐκ ἔπεισί μοι τοὺς περὶ Νέρωνος ψευσαμένους, ὅπου μηδὲ τῶν πρὸ αὐτοῦ γενομένων γράφοντες τὴν ἀλήθειαν τῆς ἱστορίας τετηρήκασιν, καίτοι πρὸς ἐκείνους αὐτοῖς οὐδὲν μῖσος ἦν ἅτε μετʼ αὐτοὺς πολλῷ χρόνῳ γενομένοις."},{"number":156,"text":"ἀλλὰ γὰρ τοῖς μὲν οὐ προνοουμένοις τῆς ἀληθείας ἐξέστω γράφειν ὡς θέλουσιν, τούτῳ γὰρ χαίρειν ἐοίκασιν,"},{"number":157,"text":"ἡμεῖς δὲ σκοπὸν προθέμενοι τὴν ἀλήθειαν τὰ μὲν ἀπηρτημένα τῆς προκειμένης ἡμῖν πραγματείας ἐπʼ ὀλίγον μνήμης ἀξιοῦμεν, τὰ δʼ ἡμῖν τοῖς Ἰουδαίοις συμπεσόντα δηλοῦμεν οὐ παρέργως μήτε τὰς συμφορὰς μήτε τὰς ἁμαρτίας διασαφεῖν ὀκνοῦντες. ἐπανήξω τοίνυν ἐπὶ τὴν τῶν οἰκείων πραγμάτων διήγησιν."},{"number":158,"text":"Τῷ γὰρ πρώτῳ τῆς Νέρωνος ἀρχῆς ἔτει τελευτήσαντος τοῦ Ἐμέσων δυνάστου Ἀζίζου Σόεμος ἀδελφὸς τὴν ἀρχὴν διαδέχεται. τὴν δὲ τῆς μικρᾶς Ἀρμενίας προστασίαν Ἀριστόβουλος Ἡρώδου τῆς Χαλκίδος βασιλέως παῖς ὑπὸ Νέρωνος ἐγχειρίζεται."},{"number":159,"text":"καὶ τὸν Ἀγρίππαν δὲ δωρεῖται μοίρᾳ τινὶ τῆς Γαλιλαίας ὁ Καῖσαρ Τιβεριάδα καὶ Ταριχέας ὑπακούειν αὐτῷ κελεύσας, δίδωσι δὲ καὶ Ἰουλιάδα πόλιν τῆς Περαίας καὶ κώμας τὰς περὶ αὐτὴν δεκατέσσαρας."},{"number":160,"text":"Τὰ δὲ κατὰ τὴν Ἰουδαίαν πράγματα πρὸς τὸ χεῖρον ἀεὶ τὴν ἐπίδοσιν ἐλάμβανεν· λῃστηρίων γὰρ ἡ χώρα πάλιν ἀνεπλήσθη καὶ γοήτων ἀνθρώπων, οἳ τὸν ὄχλον ἠπάτων."},{"number":161,"text":"ἀλλὰ τούτους μὲν ὁ Φῆλιξ πολλοὺς καθʼ ἑκάστην ἡμέραν σὺν τοῖς λῃσταῖς λαμβάνων ἀνῄρει, καὶ Ἐλεάζαρον δὲ τὸν Διναίου παῖδα τὸν συστησάμενον τῶν λῃστῶν τὸ σύνταγμα διʼ ἐνέδρας εἷλεν ζῶντα· πίστιν γὰρ αὐτῷ προτείνας ὑπὲρ τοῦ μηδὲν πείσεσθαι κακὸν πείθει πρὸς αὐτὸν ἀφικέσθαι καὶ δήσας ἀνέπεμψεν εἰς Ῥώμην."},{"number":162,"text":"ἔχων δὲ καὶ ἀπεχθῶς πρὸς τὸν ἀρχιερέα Ἰωνάθην ὁ Φῆλιξ διὰ τὸ πολλάκις ὑπʼ αὐτοῦ νουθετεῖσθαι περὶ τοῦ κρειττόνως προΐστασθαι τῶν κατὰ τὴν Ἰουδαίαν πραγμάτων, μὴ καὶ μέμψιν αὐτὸς ὀφλοίη παρὰ τοῖς πλήθεσιν αἰτησάμενος ἐκεῖνον παρὰ τοῦ Καίσαρος πεμφθῆναι τῆς Ἰουδαίας ἐπίτροπον, πρόφασιν ἐπενόει διʼ ἧς μεταστήσεται τὸν συνεχῶς ὀχληρὸν αὐτῷ γινόμενον· βαρὺ γὰρ τοῖς ἀδικεῖν θέλουσιν τὸ συνεχῶς νουθετοῦν."},{"number":163,"text":"καὶ δὴ διὰ τοιαύτης αἰτίας ὁ Φῆλιξ τὸν πιστότατον τῶν Ἰωνάθου φίλων Ἱεροσολυμίτην τὸ γένος Δωρᾶν ὀνόματι πείθει πολλὰ χρήματα δώσειν ὑπισχνούμενος ἐπαγαγεῖν τῷ Ἰωνάθῃ τοὺς λῃστὰς ἀναιρήσοντας, κἀκεῖνος ὑπακούσας ἐμηχανήσατο διὰ τῶν λῃστῶν πραχθῆναι τοιούτῳ τρόπῳ τὸν φόνον·"},{"number":164,"text":"ἀνέβησάν τινες αὐτῶν εἰς τὴν πόλιν ὡς προσκυνήσοντες τὸν θεὸν ὑπὸ τὰς ἐσθῆτας ἔχοντες ξιφίδια καὶ συναναμιγέντες τῷ Ἰωνάθῃ κτείνουσιν αὐτόν."},{"number":165,"text":"ἀνεκδικήτου δὲ τούτου τοῦ φόνου μεμενηκότος μετὰ πάσης τὸ λοιπὸν ἀδείας ἀναβαίνοντες ἐν ταῖς ἑορταῖς οἱ λῃσταὶ καὶ τὸν σίδηρον ὁμοίως κεκρυμμένον ἔχοντες συναναμιγνύμενοι τοῖς πλήθεσιν ἀνῄρουν μέν τινας ἑαυτῶν ἐχθρούς, οὓς δʼ ἐπὶ χρήμασιν ἄλλοις ὑπηρετοῦντες, οὐ μόνον κατὰ τὴν ἄλλην πόλιν ἀλλὰ καὶ κατὰ τὸ ἱερὸν ἐνίους· καὶ γὰρ ἐκεῖ σφάττειν ἐτόλμων, οὐδʼ ἐν τούτῳ δοκοῦντες ἀσεβεῖν."},{"number":166,"text":"διὰ τοῦτʼ οἶμαι καὶ τὸν θεὸν μισήσαντα τὴν ἀσέβειαν αὐτῶν ἀποστραφῆναι μὲν ἡμῶν τὴν πόλιν, τὸ δὲ ἱερὸν οὐκέτι καθαρὸν οἰκητήριον αὐτῷ κρίναντα Ῥωμαίους ἐπαγαγεῖν ἡμῖν καὶ τῇ πόλει καθάρσιον πῦρ καὶ δουλείαν ἐπιβαλεῖν σὺν γυναιξὶν καὶ τέκνοις σωφρονίσαι ταῖς συμφοραῖς βουλόμενον ἡμᾶς."},{"number":167,"text":"Τὰ μὲν οὖν τῶν λῃστῶν ἔργα τοιαύτης ἀνοσιότητος ἐπλήρου τὴν πόλιν, οἱ δὲ γόητες καὶ ἀπατεῶνες ἄνθρωποι τὸν ὄχλον ἔπειθον αὐτοῖς εἰς τὴν ἐρημίαν ἕπεσθαι·"},{"number":168,"text":"δείξειν γὰρ ἔφασαν ἐναργῆ τέρατα καὶ σημεῖα κατὰ τὴν τοῦ θεοῦ πρόνοιαν γινόμενα. καὶ πολλοὶ πεισθέντες τῆς ἀφροσύνης τιμωρίας ὑπέσχον· ἀναχθέντας γὰρ αὐτοὺς Φῆλιξ ἐκόλασεν."},{"number":169,"text":"ἀφικνεῖται δέ τις ἐξ Αἰγύπτου κατὰ τοῦτον τὸν καιρὸν εἰς Ἱεροσόλυμα προφήτης εἶναι λέγων καὶ συμβουλεύων τῷ δημοτικῷ πλήθει σὺν αὐτῷ πρὸς ὄρος τὸ προσαγορευόμενον ἐλαιῶν, ὃ τῆς πόλεως ἄντικρυς κείμενον ἀπέχει στάδια πέντε·"},{"number":170,"text":"θέλειν γὰρ ἔφασκεν αὐτοῖς ἐκεῖθεν ἐπιδεῖξαι, ὡς κελεύσαντος αὐτοῦ πίπτοι τὰ τῶν Ἱεροσολυμιτῶν τείχη, διʼ ὧν καὶ τὴν εἴσοδον αὐτοῖς παρέξειν ἐπηγγέλλετο."},{"number":171,"text":"Φῆλιξ δʼ ὡς ἐπύθετο ταῦτα, κελεύει τοὺς στρατιώτας ἀναλαβεῖν τὰ ὅπλα καὶ μετὰ πολλῶν ἱππέων τε καὶ πεζῶν ὁρμήσας ἀπὸ τῶν Ἱεροσολύμων προσβάλλει τοῖς περὶ τὸν Αἰγύπτιον, καὶ τετρακοσίους μὲν αὐτῶν ἀνεῖλεν, διακοσίους δὲ ζῶντας ἔλαβεν."},{"number":172,"text":"ὁ δʼ Αἰγύπτιος αὐτὸς διαδρὰς ἐκ τῆς μάχης ἀφανὴς ἐγένετο. πάλιν δʼ οἱ λῃσταὶ τὸν δῆμον εἰς τὸν πρὸς Ῥωμαίους πόλεμον ἠρέθιζον μηδὲν ὑπακούειν αὐτοῖς λέγοντες, καὶ τὰς τῶν ἀπειθούντων κώμας ἐμπιπράντες διήρπαζον."},{"number":173,"text":"Γίνεται δὲ καὶ τῶν Καισάρειαν οἰκούντων Ἰουδαίων στάσις πρὸς τοὺς ἐν αὐτῇ Σύρους περὶ ἰσοπολιτείας· οἱ μὲν γὰρ Ἰουδαῖοι πρωτεύειν ἠξίουν διὰ τὸ τὸν κτίστην τῆς Καισαρείας Ἡρώδην αὐτῶν βασιλέα γεγονέναι τὸ γένος Ἰουδαῖον, Σύροι δὲ τὰ μὲν περὶ τὸν Ἡρώδην ὡμολόγουν, ἔφασκον δὲ τὴν Καισάρειαν Στράτωνος πύργον τὸ πρότερον καλεῖσθαι καὶ τότε μηδένα γεγονέναι τῆς πόλεως αὐτῶν Ἰουδαῖον οἰκήτορα."},{"number":174,"text":"ταῦτα ἀκούσαντες οἱ τῆς χώρας ἔπαρχοι λαβόντες ἀμφοτέρωθεν τοὺς αἰτίους τῆς στάσεως πληγαῖς ᾐκίσαντο καὶ τὴν ταραχὴν οὕτω κατέστειλαν πρὸς ὀλίγον."},{"number":175,"text":"πάλιν γὰρ οἱ κατὰ τὴν πόλιν Ἰουδαῖοι τῷ πλούτῳ θαρροῦντες καὶ διὰ τοῦτο καταφρονοῦντες τῶν Σύρων ἐβλασφήμουν εἰς αὐτοὺς ἐρεθίσειν προσδοκῶντες."},{"number":176,"text":"οἱ δὲ χρήμασιν μὲν ἡττώμενοι, μέγα δὲ φρονοῦντες ἐπὶ τῷ τοὺς πλείστους τῶν ὑπὸ Ῥωμαίοις ἐκεῖ στρατευομένων Καισαρεῖς εἶναι καὶ Σεβαστηνοὺς μέχρι μέν τινος καὶ αὐτοὶ τοὺς Ἰουδαίους λόγῳ ὕβριζον, εἶτα λίθοις ἀλλήλους ἔβαλλον, ἕως πολλοὺς παρʼ ἀμφότερα τρωθῆναί τε καὶ πεσεῖν συνέβη· νικῶσί γε μὴν Ἰουδαῖοι."},{"number":177,"text":"Φῆλιξ δʼ ὡς ἐθεάσατο φιλονεικίαν ἐν πολέμου τρόπῳ γενομένην προπηδήσας παύεσθαι τοὺς Ἰουδαίους παρεκάλει, μὴ πειθομένοις δὲ τοὺς στρατιώτας ὁπλίσας ἐπαφίησι καὶ πολλοὺς μὲν αὐτῶν ἀνεῖλεν, πλείους δὲ ζῶντας ἔλαβεν, οἰκίας δέ τινας τῶν ἐν τῇ πόλει πολλῶν πάνυ χρημάτων γεμούσας διαρπάζειν ἐφῆκεν."},{"number":178,"text":"οἱ δὲ τῶν Ἰουδαίων ἐπιεικέστεροι καὶ προύχοντες κατὰ τὴν ἀξίωσιν δείσαντες περὶ ἑαυτῶν παρεκάλουν τὸν Φήλικα τοὺς στρατιώτας ἀνακαλέσασθαι τῇ σάλπιγγι καὶ φείσασθαι τὸ λοιπὸν αὐτῶν δοῦναί τε μετάνοιαν ἐπὶ τοῖς πεπραγμένοις. καὶ Φῆλιξ ἐπείσθη."},{"number":179,"text":"Κατὰ τοῦτον τὸν καιρὸν ὁ βασιλεὺς Ἀγρίππας δίδωσιν τὴν ἀρχιερωσύνην Ἰσμαήλῳ· Φαβεῖ παῖς οὗτος ἦν."},{"number":180,"text":"ἐξάπτεται δὲ καὶ τοῖς ἀρχιερεῦσι στάσις πρὸς τοὺς ἱερεῖς καὶ τοὺς πρώτους τοῦ πλήθους τῶν Ἱεροσολυμιτῶν, ἕκαστός τε αὐτῶν στῖφος ἀνθρώπων τῶν θρασυτάτων καὶ νεωτεριστῶν ἑαυτῷ ποιήσας ἡγεμὼν ἦν, καὶ συρράσσοντες ἐκακολόγουν τε ἀλλήλους καὶ λίθοις ἔβαλλον. ὁ δʼ ἐπιπλήξων ἦν οὐδὲ εἷς, ἀλλʼ ὡς ἐν ἀπροστατήτῳ πόλει ταῦτʼ ἐπράσσετο μετʼ ἐξουσίας."},{"number":181,"text":"τοσαύτη δὲ τοὺς ἀρχιερεῖς κατέλαβεν ἀναίδεια καὶ τόλμα, ὥστε καὶ πέμπειν δούλους ἐτόλμων ἐπὶ τὰς ἅλωνας τοὺς ληψομένους τὰς τοῖς ἱερεῦσιν ὀφειλομένας δεκάτας, καὶ συνέβαινεν τοὺς ἀπορουμένους τῶν ἱερέων ὑπʼ ἐνδείας τελευτᾶν. οὕτως ἐκράτει τοῦ δικαίου παντὸς ἡ τῶν στασιαζόντων βία."},{"number":182,"text":"Πορκίου δὲ Φήστου διαδόχου Φήλικι πεμφθέντος ὑπὸ Νέρωνος οἱ πρωτεύοντες τῶν τὴν Καισάρειαν κατοικούντων Ἰουδαίων εἰς τὴν Ῥώμην ἀναβαίνουσιν Φήλικος κατηγοροῦντες, καὶ πάντως ἂν ἐδεδώκει τιμωρίαν τῶν εἰς Ἰουδαίους ἀδικημάτων, εἰ μὴ πολλὰ αὐτὸν ὁ Νέρων τἀδελφῷ Πάλλαντι παρακαλέσαντι συνεχώρησεν μάλιστα δὴ τότε διὰ τιμῆς ἄγων ἐκεῖνον."},{"number":183,"text":"καὶ τῶν ἐν Καισαρείᾳ δὲ οἱ πρῶτοι Σύρων Βήρυλλον, παιδαγωγὸς δʼ ἦν οὗτος τοῦ Νέρωνος τάξιν τὴν ἐπὶ τῶν Ἑλληνικῶν ἐπιστολῶν πεπιστευμένος, πείθουσι πολλοῖς χρήμασιν αἰτήσασθαι παρὰ τοῦ Νέρωνος αὐτοῖς ἐπιστολὴν ἀκυροῦσαν τὴν Ἰουδαίων πρὸς αὐτοὺς ἰσοπολιτείαν."},{"number":184,"text":"καὶ Βήρυλλος τὸν αὐτοκράτορα παρακαλέσας ἐπέτυχε γραφῆναι τὴν ἐπιστολήν. αὕτη τῷ ἔθνει ἡμῶν τῶν μετὰ ταῦτα κακῶν τὰς αἰτίας παρέσχεν· πυθόμενοι γὰρ οἱ κατὰ τὴν Καισάρειαν Ἰουδαῖοι τὰ γραφέντα τῆς πρὸς τοὺς Σύρους στάσεως μᾶλλον εἴχοντο μέχρι δὴ τὸν πόλεμον ἐξῆψαν."},{"number":185,"text":"Ἀφικομένου δὲ εἰς τὴν Ἰουδαίαν Φήστου συνέβαινεν τὴν Ἰουδαίαν ὑπὸ τῶν λῃστῶν κακοῦσθαι τῶν κωμῶν ἁπασῶν ἐμπιπραμένων τε καὶ διαρπαζομένων."},{"number":186,"text":"καὶ οἱ σικάριοι δὲ καλούμενοι, λῃσταὶ δέ εἰσιν οὗτοι, τότε μάλιστα ἐπλήθυον χρώμενοι ξιφιδίοις παραπλησίοις μὲν τὸ μέγεθος τοῖς τῶν Περσῶν ἀκινάκαις, ἐπικαμπέσι δὲ καὶ ὁμοίαις ταῖς ὑπὸ Ῥωμαίων σίκαις καλουμέναις, ἀφʼ ὧν καὶ τὴν προσηγορίαν οἱ λῃστεύοντες ἔλαβον πολλοὺς ἀναιροῦντες."},{"number":187,"text":"ἀναμιγνύμενοι γὰρ ἐν ταῖς ἑορταῖς, καθὼς καὶ πρότερον εἴπομεν, τῷ πλήθει τῶν πανταχόθεν εἰς τὴν πόλιν ἐπὶ τὴν εὐσέβειαν συρρεόντων οὓς βουληθεῖεν ῥᾳδίως ἀπέσφαττον, πολλάκις δὲ καὶ μεθʼ ὅπλων ἐπὶ τὰς κώμας τῶν ἐχθρῶν ἀφικόμενοι διήρπαζον καὶ ἐνεπίμπρασαν."},{"number":188,"text":"πέμπει δὲ Φῆστος δύναμιν ἱππικήν τε καὶ πεζικὴν ἐπὶ τοὺς ἀπατηθέντας ὑπό τινος ἀνθρώπου γόητος σωτηρίαν αὐτοῖς ἐπαγγελλομένου καὶ παῦλαν κακῶν, εἰ βουληθεῖεν ἕπεσθαι μέχρι τῆς ἐρημίας αὐτῷ, καὶ αὐτόν τε ἐκεῖνον τὸν ἀπατήσαντα καὶ τοὺς ἀκολουθήσαντας διέφθειραν οἱ πεμφθέντες."},{"number":189,"text":"Κατὰ δὲ τὸν καιρὸν τοῦτον ὁ βασιλεὺς Ἀγρίππας ᾠκοδομήσατο μεγέθει διαφέρον οἴκημα ἐν τῷ βασιλείῳ ἐν Ἱεροσολύμοις πλησίον τοῦ ξυστοῦ."},{"number":190,"text":"τὸ δὲ βασίλειον ἐγεγόνει πάλαι ὑπὸ τῶν Ἀσαμωναίου παίδων, ἐφʼ ὑψηλοῦ δὲ τόπου κείμενον τοῖς κατοπτεύειν ἀπʼ αὐτοῦ βουλομένοις τὴν πόλιν ἐπιτερπεστάτην παρεῖχεν τὴν θέαν, ἧς ἐφιέμενος ὁ βασιλεὺς ἐκεῖθεν ἀφεώρα κατακείμενος τὰ κατὰ τὸ ἱερὸν πρασσόμενα."},{"number":191,"text":"ταῦτα δὲ θεασάμενοι τῶν Ἱεροσολυμιτῶν οἱ προύχοντες δεινῶς ἐχαλέπαινον· οὐ γὰρ ἦν πάτριον τὰ κατὰ τὸ ἱερὸν δρώμενα κατοπτεύεσθαι καὶ μάλιστα τὰς ἱερουργίας. τοῖχον οὖν ἐγείρουσιν ἐπὶ τῆς ἐξέδρας ὑψηλόν, ἥτις ἦν ἐν τῷ ἔσωθεν ἱερῷ τετραμμένη πρὸς δύσιν."},{"number":192,"text":"οὐ μόνον δὲ τοῦ βασιλικοῦ τρικλίνου τὴν ἄποψιν οὗτος οἰκοδομηθεὶς ἀπετέμνετο, ἀλλὰ καὶ τῆς δυτικῆς στοᾶς τῆς κατὰ τὸ ἔξωθεν ἱερὸν οὔσης, ἔνθα τὰς φυλακὰς οἱ Ῥωμαῖοι ταῖς ἑορταῖς ἐποιοῦντο διὰ τὸ ἱερόν."},{"number":193,"text":"ἐπὶ τούτοις ἠγανάκτησεν ὅ τε βασιλεὺς Ἀγρίππας, μάλιστα δὲ Φῆστος ὁ ἔπαρχος, καὶ προσέταξεν αὐτοῖς καθελεῖν. οἱ δὲ παρεκάλεσαν ἐξουσίαν αὐτοῖς δοῦναι πρεσβεῦσαι περὶ τούτου πρὸς Νέρωνα· ζῆν γὰρ οὐχ ὑπομένειν καθαιρεθέντος τινὸς μέρους τοῦ ἱεροῦ."},{"number":194,"text":"συγχωρήσαντος δὲ τοῦ Φήστου πέμπουσιν ἐξ αὑτῶν πρὸς Νέρωνα τοὺς πρώτους δέκα καὶ Ἰσμάηλον τὸν ἀρχιερέα καὶ Ἑλκίαν τὸν γαζοφύλακα."},{"number":195,"text":"Νέρων δὲ διακούσας αὐτῶν οὐ μόνον συνέγνω περὶ τοῦ πραχθέντος, ἀλλὰ καὶ συνεχώρησεν ἐᾶν οὕτως τὴν οἰκοδομίαν, τῇ γυναικὶ Ποππαίᾳ, θεοσεβὴς γὰρ ἦν, ὑπὲρ τῶν Ἰουδαίων δεηθείσῃ χαριζόμενος, ἣ τοῖς μὲν δέκα προσέταξεν ἀπιέναι, τὸν δʼ Ἑλκίαν καὶ τὸν Ἰσμάηλον ὁμηρεύσοντας παρʼ ἑαυτῇ κατέσχεν."},{"number":196,"text":"ὁ δὲ βασιλεὺς ταῦθʼ ὡς ἐπύθετο δίδωσιν τὴν ἀρχιερωσύνην Ἰωσήπῳ τῷ Σίμωνος παιδὶ ἀρχιερέως ἐπικαλουμένῳ δὲ Καβί."}],"9":[{"number":197,"text":"Πέμπει δὲ Καῖσαρ Ἀλβῖνον εἰς τὴν Ἰουδαίαν ἔπαρχον Φήστου τὴν τελευτὴν πυθόμενος. ὁ δὲ βασιλεὺς ἀφείλετο μὲν τὸν Ἰώσηπον τὴν ἱερωσύνην, τῷ δὲ Ἀνάνου παιδὶ καὶ αὐτῷ Ἀνάνῳ λεγομένῳ τὴν διαδοχὴν τῆς ἀρχῆς ἔδωκεν."},{"number":198,"text":"τοῦτον δέ φασι τὸν πρεσβύτατον Ἄνανον εὐτυχέστατον γενέσθαι· πέντε γὰρ ἔσχε παῖδας καὶ τούτους πάντας συνέβη ἀρχιερατεῦσαι τῷ θεῷ, αὐτὸς πρότερος τῆς τιμῆς ἐπὶ πλεῖστον ἀπολαύσας, ὅπερ οὐδενὶ συνέβη τῶν παρʼ ἡμῖν ἀρχιερέων."},{"number":199,"text":"ὁ δὲ νεώτερος Ἄνανος, ὃν τὴν ἀρχιερωσύνην ἔφαμεν εἰληφέναι, θρασὺς ἦν τὸν τρόπον καὶ τολμητὴς διαφερόντως, αἵρεσιν δὲ μετῄει τὴν Σαδδουκαίων, οἵπερ εἰσὶ περὶ τὰς κρίσεις ὠμοὶ παρὰ πάντας τοὺς Ἰουδαίους, καθὼς ἤδη δεδηλώκαμεν."},{"number":200,"text":"ἅτε δὴ οὖν τοιοῦτος ὢν ὁ Ἄνανος, νομίσας ἔχειν καιρὸν ἐπιτήδειον διὰ τὸ τεθνάναι μὲν Φῆστον, Ἀλβῖνον δʼ ἔτι κατὰ τὴν ὁδὸν ὑπάρχειν, καθίζει συνέδριον κριτῶν καὶ παραγαγὼν εἰς αὐτὸ τὸν ἀδελφὸν Ἰησοῦ τοῦ λεγομένου Χριστοῦ, Ἰάκωβος ὄνομα αὐτῷ, καί τινας ἑτέρους, ὡς παρανομησάντων κατηγορίαν ποιησάμενος παρέδωκε λευσθησομένους."},{"number":201,"text":"ὅσοι δὲ ἐδόκουν ἐπιεικέστατοι τῶν κατὰ τὴν πόλιν εἶναι καὶ περὶ τοὺς νόμους ἀκριβεῖς βαρέως ἤνεγκαν ἐπὶ τούτῳ καὶ πέμπουσιν πρὸς τὸν βασιλέα κρύφα παρακαλοῦντες αὐτὸν ἐπιστεῖλαι τῷ Ἀνάνῳ μηκέτι τοιαῦτα πράσσειν· μηδὲ γὰρ τὸ πρῶτον ὀρθῶς αὐτὸν πεποιηκέναι."},{"number":202,"text":"τινὲς δʼ αὐτῶν καὶ τὸν Ἀλβῖνον ὑπαντιάζουσιν ἀπὸ τῆς Ἀλεξανδρείας ὁδοιποροῦντα καὶ διδάσκουσιν, ὡς οὐκ ἐξὸν ἦν Ἀνάνῳ χωρὶς τῆς ἐκείνου γνώμης καθίσαι συνέδριον."},{"number":203,"text":"Ἀλβῖνος δὲ πεισθεὶς τοῖς λεγομένοις γράφει μετʼ ὀργῆς τῷ Ἀνάνῳ λήψεσθαι παρʼ αὐτοῦ δίκας ἀπειλῶν. καὶ ὁ βασιλεὺς Ἀγρίππας διὰ τοῦτο τὴν Ἀρχιερωσύνην ἀφελόμενος αὐτὸν ἄρξαντα μῆνας τρεῖς Ἰησοῦν τὸν τοῦ Δαμναίου κατέστησεν."},{"number":204,"text":"Ἐπεὶ δʼ ἧκεν ὁ Ἀλβῖνος εἰς τὴν τῶν Ἱεροσολυμιτῶν πόλιν, πᾶσαν εἰσηνέγκατο σπουδὴν καὶ πρόνοιαν ὑπὲρ τοῦ τὴν χώραν εἰρηνεύεσθαι τοὺς πολλοὺς τῶν σικαρίων διαφθείρας."},{"number":205,"text":"ὁ δὲ ἀρχιερεὺς Ἀνανίας καθʼ ἑκάστην ἡμέραν ἐπὶ μέγα προύκοπτε δόξης καὶ τῆς παρὰ τῶν πολιτῶν εὐνοίας τε καὶ τιμῆς ἠξιοῦτο λαμπρῶς· ἦν γὰρ χρημάτων ποριστικός· καθʼ ἡμέραν γοῦν τὸν Ἀλβῖνον καὶ τὸν ἀρχιερέα δώροις ἐθεράπευεν."},{"number":206,"text":"εἶχεν δʼ οἰκέτας πάνυ μοχθηρούς, οἳ συναναστρεφόμενοι τοῖς θρασυτάτοις ἐπὶ τὰς ἅλωνας πορευόμενοι τὰς τῶν ἱερέων δεκάτας ἐλάμβανον βιαζόμενοι καὶ τοὺς μὴ διδόντας οὐκ ἀπείχοντο τύπτειν,"},{"number":207,"text":"οἵ τε ἀρχιερεῖς ὅμοια τοῖς ἐκείνου δούλοις ἔπρασσον μηδενὸς κωλύειν δυναμένου. καὶ τῶν ἱερέων τοὺς πάλαι ταῖς δεκάταις τρεφομένους τότε συνέβαινε θνήσκειν τροφῆς ἀπορίᾳ."},{"number":208,"text":"Πάλιν δʼ οἱ σικάριοι κατὰ τὴν ἑορτήν, ἐνειστήκει γὰρ αὕτη, διὰ νυκτὸς εἰς τὴν πόλιν παρελθόντες συλλαμβάνουσι ζῶντα τὸν γραμματέα τοῦ στρατηγοῦντος Ἐλεαζάρου, παῖς δʼ ἦν οὗτος Ἀνανίου τοῦ ἀρχιερέως, καὶ δήσαντες ἐξήγαγον."},{"number":209,"text":"εἶτα πέμψαντες πρὸς τὸν Ἀνανίαν ἀπολύσειν ἔφασαν τὸν γραμματέα πρὸς αὐτόν, εἰ πείσειεν τὸν Ἀλβῖνον δέκα δεσμώτας τοὺς ἐξ αὐτῶν ληφθέντας ἀπολῦσαι. καὶ ὁ Ἀνανίας διὰ τὴν ἀνάγκην πείσας τὸν Ἀλβῖνον τῆς ἀξιώσεως ἐπέτυχεν."},{"number":210,"text":"τοῦτο μειζόνων κακῶν ἦρξεν· οἱ γὰρ λῃσταὶ παντοίως ἐπεμηχανῶντο τῶν Ἀνανίου τινὰς συλλαμβάνειν οἰκείων καὶ συνεχῶς ζωγροῦντες οὐκ ἀπέλυον πρὶν ἤ τινας τῶν σικαρίων ἀπολάβοιεν γενόμενοί τε πάλιν ἀριθμὸς οὐκ ὀλίγος ἀναθαρρήσαντες τὴν χώραν ἅπασαν ἐκάκουν."},{"number":211,"text":"Κατὰ τοῦτον δὲ τὸν καιρὸν ὁ βασιλεὺς Ἀγρίππας μείζονα τὴν Φιλίππου καλουμένην Καισάρειαν κατασκευάσας εἰς τιμὴν τοῦ Νέρωνος Νερωνιάδα προσηγόρευσεν, καὶ Βηρυτίοις δὲ θέατρον ἀπὸ πολλῶν χρημάτων κατεσκευασμένον ταῖς κατʼ ἔτος θέαις ἐδωρεῖτο πολλὰς εἰς τοῦτο μυριάδας ἀναλίσκων·"},{"number":212,"text":"σῖτον γὰρ ἐδίδου τῷ δήμῳ καὶ ἔλαιον διένεμεν καὶ τὴν πᾶσαν δὲ πόλιν ἀνδριάντων ἀναθέσεσιν καὶ ταῖς τῶν ἀρχαίων ἀποτύποις εἰκόσιν ἐκόσμει καὶ μικροῦ δεῖν πάντα τὸν τῆς βασιλείας κόσμον ἐκεῖ μετήνεγκεν. μῖσος οὖν αὐτῷ παρὰ τῶν ὑπηκόων ηὔξετο διὰ τὸ περιαιρούμενον τὰ ἐκείνων εἰς ξένην πόλιν κοσμεῖν."},{"number":213,"text":"λαμβάνει δὲ καὶ Ἰησοῦς ὁ τοῦ Γαμαλιήλου τὴν διαδοχὴν τῆς ἀρχιερωσύνης παρὰ τοῦ βασιλέως Ἰησοῦν ἀφελομένου τὸν τοῦ Δαμναίου, καὶ διὰ τοῦτο στάσις αὐτῶν πρὸς ἀλλήλους ἐγένετο· σύστημα γὰρ τῶν θρασυτάτων ποιησάμενοι πολλάκις μέχρι λίθων βολῆς ἀπὸ τῶν βλασφημιῶν ἐξέπιπτον. ὑπερεῖχεν δὲ Ἀνανίας τῷ πλούτῳ προσαγόμενος τοὺς λαμβάνειν ἑτοίμους."},{"number":214,"text":"Κοστόβαρος δὲ καὶ Σαοῦλος αὐτοὶ καθʼ αὑτοὺς μοχθηρὰ πλήθη συνῆγον γένους μὲν ὄντες βασιλικοῦ καὶ διὰ τὴν πρὸς Ἀγρίππαν συγγένειαν εὐνοίας τυγχάνοντες, βίαιοι δὲ καὶ ἁρπάζειν τὰ τῶν ἀσθενεστέρων ἕτοιμοι. ἐξ ἐκείνου μάλιστα τοῦ καιροῦ συνέβη τὴν πόλιν ἡμῶν νοσεῖν προκοπτόντων πάντων ἐπὶ τὸ χεῖρον."},{"number":215,"text":"Ὡς δʼ ἤκουσεν Ἀλβῖνος διάδοχον αὐτῷ Γέσσιον Φλῶρον ἀφικνεῖσθαι, βουλόμενος δοκεῖν τι τοῖς Ἱεροσολυμίταις παρεσχῆσθαι προαγαγὼν τοὺς δεσμώτας, ὅσοι ἦσαν αὐτῶν προδήλως θανεῖν ἄξιοι, τούτους προσέταξεν ἀναιρεθῆναι, τοὺς δʼ ἐκ μικρᾶς καὶ τῆς τυχούσης αἰτίας εἰς τὴν εἱρκτὴν κατατεθέντας χρήματα λαμβάνων αὐτὸς ἀπέλυεν. καὶ οὕτως ἡ μὲν φυλακὴ τῶν δεσμωτῶν ἐκαθάρθη, ἡ χώρα δὲ λῃστῶν ἐπληρώθη."},{"number":216,"text":"Τῶν δὲ Λευιτῶν, φυλὴ δʼ ἐστὶν αὕτη, ὅσοιπερ ἦσαν ὑμνῳδοὶ πείθουσι τὸν βασιλέα καθίσαντα συνέδριον φορεῖν αὐτοῖς ἐπίσης τοῖς ἱερεῦσιν ἐπιτρέψαι λινῆν στολήν· πρέπειν γὰρ αὐτοῦ τοῖς τῆς ἀρχῆς χρόνοις ἔφασκον ἀφʼ ὧν μνημονευθήσεται καινοποιεῖν."},{"number":217,"text":"καὶ τῆς ἀξιώσεως οὐ διήμαρτον· ὁ γὰρ βασιλεὺς μετὰ γνώμης τῶν εἰς τὸ συνέδριον ἐποιχομένων συνεχώρησεν τοῖς ὑμνῳδοῖς ἀποθεμένους τὴν προτέραν ἐσθῆτα φορεῖν λινῆν οἵαν ἠθέλησαν."},{"number":218,"text":"μέρους δέ τινος τῆς φυλῆς λειτουργοῦντος κατὰ τὸ ἱερὸν καὶ τούτοις ἐπέτρεψεν τοὺς ὕμνους ἐκμαθεῖν, ὡς παρεκάλουν. πάντα δʼ ἦν ἐναντία ταῦτα τοῖς πατρίοις νόμοις, ὧν παραβαθέντων οὐκ ἐνῆν μὴ οὐχὶ δίκας ὑποσχεῖν."},{"number":219,"text":"Ἤδη δὲ τότε καὶ τὸ ἱερὸν ἐτετέλεστο. βλέπων οὖν ὁ δῆμος ἀργήσαντας τοὺς τεχνίτας ὑπὲρ μυρίους καὶ ὀκτακισχιλίους ὄντας καὶ μισθοφορίας ἐνδεεῖς ἐσομένους διὰ τὸ τὴν τροφὴν ἐκ τῆς κατὰ τὸ ἱερὸν ἐργασίας πορίζεσθαι,"},{"number":220,"text":"καὶ χρήματα μὲν ἀπόθετα διὰ τὸν ἐκ Ῥωμαίων φόβον ἔχειν οὐ θέλων, προνοούμενος δὲ τῶν τεχνιτῶν καὶ εἰς τούτους ἀναλοῦν τοὺς θησαυροὺς βουλόμενος, καὶ γὰρ εἰ μίαν τις ὥραν τῆς ἡμέρας ἐργάσαιτο, τὸν μισθὸν ὑπὲρ ταύτης εὐθέως ἐλάμβανεν, ἔπειθον τὸν βασιλέα τὴν ἀνατολικὴν στοὰν ἀνεγεῖραι."},{"number":221,"text":"ἦν δὲ ἡ στοὰ τοῦ μὲν ἔξωθεν ἱεροῦ, κειμένη δʼ ἐν φάραγγι βαθείᾳ τετρακοσίων πηχῶν τοὺς τοίχους ἔχουσα ἐκ λίθου τετραγώνου κατεσκεύαστο καὶ λευκοῦ πάνυ, τὸ μὲν μῆκος ἑκάστου λίθου πήχεις εἴκοσι, τὸ δὲ ὕψος ἕξ, ἔργον Σολόμωνος τοῦ βασιλέως πρώτου δειμαμένου τὸ σύμπαν ἱερόν."},{"number":222,"text":"ὁ βασιλεὺς δʼ, ἐπεπίστευτο γὰρ ὑπὸ Κλαυδίου Καίσαρος τὴν ἐπιμέλειαν τοῦ ἱεροῦ, λογισάμενος παντὸς μὲν ἔργου τὴν καθαίρεσιν εἶναι ῥᾳδίαν δυσχερῆ δὲ τὴν κατασκευήν, ἐπὶ δὲ τῆς στοᾶς ταύτης καὶ μᾶλλον, χρόνου τε γὰρ καὶ πολλῶν χρημάτων εἰς τοὖργον δεήσειν, ἠρνήσατο μὲν περὶ τούτου δεομένοις, καταστορέσαι δὲ λευκῷ λίθῳ τὴν πόλιν οὐκ ἐκώλυσεν."},{"number":223,"text":"Ἰησοῦν δὲ τὸν τοῦ Γαμαλιήλου τὴν ἀρχιερωσύνην ἀφελόμενος ἔδωκεν αὐτὴν Ματθίᾳ τῷ Θεοφίλου, καθʼ ὃν καὶ ὁ πρὸς Ῥωμαίους πόλεμος Ἰουδαίοις ἔλαβε τὴν ἀρχήν."}],"10":[{"number":224,"text":"Ἀναγκαῖον δʼ εἶναι νομίζω καὶ τῇ ἱστορίᾳ ταύτῃ προσῆκον διηγήσασθαι περὶ τῶν ἀρχιερέων, πῶς ἀρξάμενοι καὶ τίσιν ἔξεστι τῆς τιμῆς ταύτης μεταλαμβάνειν καὶ πόσοι γεγόνασιν μέχρι τῆς τοῦ πολέμου τελευτῆς."},{"number":225,"text":"πρῶτον μὲν οὖν πάντων λέγουσιν Ἀαρῶνα τὸν Μωυσέως ἀδελφὸν ἀρχιερατεῦσαι τῷ θεῷ, τελευτήσαντος δὲ ἐκείνου διαδέξασθαι τοὺς παῖδας εὐθὺς κἀπʼ ἐκείνων τοῖς ἐγγόνοις αὐτῶν διαμεῖναι τὴν τιμὴν ἅπασιν."},{"number":226,"text":"ὅθεν καὶ πάτριόν ἐστι μηδένα τοῦ θεοῦ τὴν ἀρχιερωσύνην λαμβάνειν ἢ τὸν ἐξ αἵματος τοῦ Ἀαρῶνος, ἑτέρου δὲ γένους οὐδʼ ἂν βασιλεὺς ὢν τύχῃ τεύξεται τῆς ἀρχιερωσύνης."},{"number":227,"text":"ἐγένοντο οὖν πάντες τὸν ἀριθμὸν ἀπὸ Ἀαρῶνος, ὡς ἔφαμεν, τοῦ πρώτου γενομένου μέχρι Φανάσου τοῦ κατὰ τὸν πόλεμον ὑπὸ τῶν στασιαστῶν ἀρχιερέως ἀναδειχθέντος ὀγδοήκοντα τρεῖς."},{"number":228,"text":"ἐκ τούτων κατὰ τὴν ἔρημον ἐπὶ τῶν Μωυσέως χρόνων τῆς σκηνῆς ἑστώσης, ἣν Μωυσῆς τῷ θεῷ κατεσκεύασεν, μέχρι τῆς εἰς Ἰουδαίαν ἀφίξεως, ἔνθα Σολόμων ὁ βασιλεὺς τῷ θεῷ τὸν ναὸν ἤγειρεν, ἀρχιεράτευσαν δεκατρεῖς."},{"number":229,"text":"τὸ γὰρ πρῶτον ἕως τοῦ βίου τελευτῆς τὰς ἀρχιερωσύνας εἶχον, ὕστερον δὲ καὶ παρὰ ζώντων διεδέχοντο. οἱ τοίνυν δεκατρεῖς οὗτοι τῶν δύο παίδων Ἀαρῶνος ὄντες ἔγγονοι κατὰ διαδοχὴν τὴν τιμὴν παρελάμβανον. ἐγένετο δὲ αὐτῶν ἀριστοκρατικὴ μὲν ἡ πρώτη πολιτεία, μετὰ ταύτην δὲ μοναρχία, βασιλέων δὲ τρίτη."},{"number":230,"text":"γίνεται δὲ τῶν ἐτῶν ἀριθμὸς ὧν ἦρξαν οἱ δεκατρεῖς ἀφʼ ἧς ἡμέρας οἱ πατέρες ἡμῶν ἐξέλιπον Αἴγυπτον Μωυσέως ἄγοντος μέχρι τῆς τοῦ ναοῦ κατασκευῆς, ὃν Σολόμων ὁ βασιλεὺς ἐν Ἱεροσολύμοις ἀνήγειρεν, ἔτη δώδεκα πρὸς τοῖς ἑξακοσίοις."},{"number":231,"text":"Μετὰ δὲ τοὺς δεκατρεῖς ἀρχιερέας ἐκείνους οἱ δέκα καὶ ὀκτὼ τὴν ἀρχιερωσύνην ἔσχον ἀπὸ Σολόμωνος βασιλέως ἐν Ἱεροσολύμοις αὐτὴν διαδεξάμενοι, μέχρι οὗ Ναβουχοδονόσορος ὁ τῶν Βαβυλωνίων βασιλεὺς ἐπιστρατεύσας τῇ πόλει τὸν μὲν ναὸν ἐνέπρησεν, τὸ δὲ ἔθνος ἡμῶν εἰς Βαβυλῶνα μετήνεγκεν καὶ τὸν ἀρχιερέα Ἰωσαδάκην αἰχμάλωτον ἔλαβεν."},{"number":232,"text":"τούτων χρόνος τῆς ἱερωσύνης τετρακοσίων ἑξηκονταὲξ ἐτῶν ἐστι μηνῶν ἓξ ἡμερῶν δέκα ἤδη βασιλευομένων Ἰουδαίων."},{"number":233,"text":"μετὰ δὲ χρόνον ἐτῶν ἁλώσεως ἑβδομήκοντα τῆς ὑπὸ Βαβυλωνίων γενομένης Κῦρος ὁ Περσῶν βασιλεὺς ἀπέλυσεν τοὺς ἐκ Βαβυλῶνος Ἰουδαίους ἐπὶ τὴν οἰκείαν γῆν πάλιν καὶ συνεχώρησεν τὸν ναὸν ἀνεγεῖραι."},{"number":234,"text":"τότε δὴ τῶν ὑποστρεψάντων αἰχμαλώτων Ἰησοῦς ὁ τοῦ Ἰωσεδὲκ εἷς ὢν τὴν ἀρχιερωσύνην λαμβάνει. λαμβάνει δʼ οὗτος αὐτὸς καὶ οἱ ἔγγονοι αὐτοῦ πεντεκαίδεκα συνάπαντες μέχρι βασιλέως Ἀντιόχου τοῦ Εὐπάτορος, ἐπολιτεύοντο δὲ δημοκρατικῶς ἔτη τετρακόσια δεκατέσσαρα."},{"number":235,"text":"Πρῶτος δʼ Ἀντίοχος ὁ προειρημένος καὶ ὁ στρατηγὸς αὐτοῦ Λυσίας τὸν Ὀνίαν, ᾧ Μενέλαος ἐπίκλην, παύουσι τῆς ἀρχιερωσύνης ἀνελόντες αὐτὸν ἐν Βεροίᾳ καὶ καθιστᾶσιν Ἰάκιμον ἀρχιερέα, γένους μὲν τοῦ Ἀαρῶνος, οὐκ ὄντα δὲ τῆς οἰκίας ταύτης."},{"number":236,"text":"διὰ τοῦτο καὶ Ὀνίας ὁ τοῦ τετελευτηκότος Ὀνίου ἐξάδελφος ὁμώνυμος τῷ πατρὶ παραγενόμενος εἰς Αἴγυπτον καὶ διὰ φιλίας ἀφικόμενος Πτολεμαίῳ τῷ Φιλομήτορι καὶ Κλεοπάτρᾳ τῇ γυναικὶ αὐτοῦ, πείθει τούτους κατὰ τὸν Ἡλιοπολίτην νομὸν δειμαμένους τῷ θεῷ ναὸν παραπλήσιον τῷ ἐν Ἱεροσολύμοις αὐτὸν ἀρχιερέα καταστῆσαι."},{"number":237,"text":"ἀλλὰ περὶ μὲν τοῦ ἱεροῦ τοῦ κατασκευασθέντος ἐν Αἰγύπτῳ πολλάκις ἐδηλώσαμεν. ὁ δὲ Ἰάκιμος ἔτη τρία τὴν ἀρχιερωσύνην κατασχὼν ἐτελεύτησεν. διεδέξατο δʼ αὐτὸν οὐδείς, ἀλλὰ διετέλεσεν ἡ πόλις ἐνιαυτοὺς ἑπτὰ χωρὶς ἀρχιερέως οὖσα."},{"number":238,"text":"πάλιν δὲ οἱ τῶν Ἀσαμωναίου παίδων ἔγγονοι τὴν προστασίαν τοῦ ἔθνους πιστευθέντες καὶ πολεμήσαντες Μακεδόσιν Ἰωνάθην ἀρχιερέα καθιστᾶσιν, ὃς ἦρξεν ἐνιαυτοὺς ἑπτά."},{"number":239,"text":"τελευτήσαντος δὲ ἐξ ἐπιβουλῆς αὐτοῦ καὶ ἐνέδρας τῆς ὑπὸ Τρύφωνος μηχανηθείσης, ὡς ἀνωτέρω που προειρήκαμεν, λαμβάνει τὴν ἀρχιερωσύνην Σίμων ἀδελφὸς αὐτοῦ."},{"number":240,"text":"καὶ τοῦτον δὲ δόλῳ παρὰ συμπόσιον ὑπὸ τοῦ γαμβροῦ διαφθαρέντα διεδέξατο παῖς Ὑρκανὸς ὄνομα ὃν κατασχόντα τὴν ἱερωσύνην πλείονα τἀδελφοῦ χρόνον ἐνιαυτῷ, τριακονταὲν ἔτη τῆς τιμῆς Ὑρκανὸς ἀπολαύσας τελευτᾷ γηραιὸς Ἰούδᾳ τῷ καὶ Ἀριστοβούλῳ κληθέντι τὴν διαδοχὴν καταλιπών."},{"number":241,"text":"κληρονομεῖ δὲ καὶ τοῦτον ἀδελφὸς Ἀλέξανδρος, ὑπὸ νόσου μὲν τελευτήσαντα, τὴν ἱερωσύνην δὲ κατασχόντα μετὰ βασιλείας, καὶ γὰρ διάδημα πρῶτος περιέθετο ὁ Ἰούδας, ἐνιαυτὸν ἕνα."},{"number":242,"text":"Βασιλεύσας δὲ ὁ Ἀλέξανδρος καὶ ἱερατεύσας ἔτη εἰκοσιεπτὰ καταστρέφει τὸν βίον Ἀλεξάνδρᾳ τῇ γυναικὶ καταστῆσαι τὸν ἀρχιερατευσόμενον ἐπιτρέψας. ἡ δὲ τὴν μὲν ἀρχιερωσύνην Ὑρκανῷ δίδωσιν, αὐτὴ δὲ τὴν βασιλείαν ἔτη ἐννέα κατασχοῦσα τελευτᾷ τὸν βίον· τὸν ἴσον δὲ χρόνον τὴν ἀρχιερωσύνην ὁ παῖς αὐτῆς Ὑρκανὸς ἔσχεν·"},{"number":243,"text":"μετὰ γὰρ τὸν θάνατον αὐτῆς πολεμήσας πρὸς αὐτὸν ὁ ἀδελφὸς Ἀριστόβουλος καὶ νικήσας ἀφαιρεῖται μὲν ἐκεῖνον τὴν ἀρχήν, αὐτὸς δʼ ἐβασίλευέ τε καὶ ἀρχιεράτευεν τοῦ ἔθνους."},{"number":244,"text":"ἔτει δὲ τρίτῳ τῆς βασιλείας καὶ πρὸς μησὶν τοῖς ἴσοις Πομπήιος ἐλθὼν καὶ τὴν τῶν Ἱεροσολυμιτῶν πόλιν κατὰ κράτος ἑλὼν αὐτὸν μὲν εἰς Ῥώμην μετὰ τῶν τέκνων δήσας ἔπεμψεν, τῷ δʼ Ὑρκανῷ πάλιν τὴν ἀρχιερωσύνην ἀποδοὺς τὴν μὲν τοῦ ἔθνους προστασίαν ἐπέτρεψεν, διάδημα δὲ φορεῖν ἐκώλυσεν."},{"number":245,"text":"ἦρξεν δὲ πρὸς τοῖς ἐννέα τοῖς πρώτοις ὁ Ὑρκανὸς τέσσαρα καὶ εἴκοσιν. Βαζαφράνης δὲ καὶ Πάκορος οἱ τῆς Παρθυηνῆς δυνάσται διαβάντες τὸν Εὐφράτην καὶ πολεμήσαντες Ὑρκανῷ αὐτὸν μὲν ζωγρίᾳ συνέλαβον, τὸν Ἀριστοβούλου δὲ υἱὸν Ἀντίγονον κατέστησαν βασιλέα."},{"number":246,"text":"τρία δʼ ἔτη καὶ τρεῖς μῆνας ἄρξαντα τοῦτον Σόσσιός τε καὶ Ἡρώδης ἐξεπολιόρκησαν, Ἀντώνιος δʼ ἀνεῖλεν εἰς τὴν Ἀντιόχειαν ἀναχθέντα."},{"number":247,"text":"Τὴν δὲ βασιλείαν Ἡρώδης παρὰ Ῥωμαίων ἐγχειρισθεὶς οὐκέτι τοὺς ἐκ τοῦ Ἀσαμωναίου γένους καθίστησιν ἀρχιερεῖς, ἀλλά τισιν ἀσήμοις καὶ μόνον ἐξ ἱερέων οὖσιν πλὴν ἑνὸς Ἀριστοβούλου τὴν τιμὴν ἀπένεμεν."},{"number":248,"text":"τὸν δʼ Ἀριστόβουλον Ὑρκανοῦ τοῦ ὑπὸ Πάρθων ληφθέντος υἱωνὸν ὄντα καταστήσας ἀρχιερέα τῇ ἀδελφῇ αὐτοῦ συνῴκησεν Μαριάμμῃ, τὴν τοῦ πλήθους πρὸς ἑαυτὸν θηρώμενος εὔνοιαν διὰ τὴν Ὑρκανοῦ μνήμην. εἶτα φοβηθείς, μὴ πρὸς τὸν Ἀριστόβουλον πάντες ἀποκλίνωσιν, ἀνεῖλεν αὐτὸν ἐν Ἱεριχοῖ πνιγῆναι μηχανησάμενος κολυμβῶντα, καθὼς ἤδη δεδηλώκαμεν."},{"number":249,"text":"μετὰ τοῦτον οὐκέτι τοῖς ἐγγόνοις τῶν Ἀσαμωναίου παίδων τὴν ἀρχιερωσύνην ἐπίστευσεν. ἔπραξεν δὲ ὅμοια τῷ Ἡρώδῃ περὶ τῆς καταστάσεως τῶν ἱερέων Ἀρχέλαός τε ὁ παῖς αὐτοῦ καὶ μετὰ τοῦτον τὴν ἀρχὴν Ῥωμαῖοι τῶν Ἰουδαίων παραλαβόντες."},{"number":250,"text":"εἰσὶν οὖν οἱ ἀπὸ τῶν Ἡρώδου χρόνων ἀρχιερατεύσαντες μέχρι τῆς ἡμέρας, ἧς τὸν ναὸν καὶ τὴν πόλιν Τίτος ἑλὼν ἐπυρπόλησεν, οἱ πάντες εἴκοσι καὶ ὀκτώ, χρόνος δὲ τούτων ἔτη πρὸς τοῖς ἑκατὸν ἑπτά."},{"number":251,"text":"καὶ τινὲς μὲν αὐτῶν ἐπολιτεύσαντο ἐπί τε Ἡρώδου βασιλεύοντος καὶ ἐπὶ Ἀρχελάου τοῦ παιδὸς αὐτοῦ, μετὰ δὲ τὴν τούτων τελευτὴν ἀριστοκρατία μὲν ἦν ἡ πολιτεία, τὴν δὲ προστασίαν τοῦ ἔθνους οἱ ἀρχιερεῖς ἐπεπίστευντο. περὶ μὲν οὖν τῶν ἀρχιερέων ἱκανὰ ταῦτα."}],"11":[{"number":252,"text":"Γέσσιος δὲ Φλῶρος ὁ πεμφθεὶς Ἀλβίνου διάδοχος ὑπὸ Νέρωνος πολλῶν ἐνέπλησε κακῶν Ἰουδαίους. Κλαζομένιος μὲν ἦν τὸ γένος οὗτος, ἐπήγετο δὲ γυναῖκα Κλεοπάτραν, διʼ ἣν φίλην οὖσαν Ποππαίας τῆς Νέρωνος γυναικὸς καὶ πονηρίᾳ μηδὲν αὐτοῦ διαφέρουσαν τῆς ἀρχῆς ἐπέτυχεν."},{"number":253,"text":"οὕτω δὲ περὶ τὴν ἐξουσίαν ἐγένετο κακὸς καὶ βίαιος, ὥστε διὰ τὴν ὑπερβολὴν τῶν κακῶν Ἀλβῖνον ἐπῄνουν ὡς εὐεργέτην Ἰουδαῖοι·"},{"number":254,"text":"ἐκεῖνος μὲν γὰρ ἐπεκρύπτετο τὴν πονηρίαν καὶ τοῦ μὴ παντάπασιν κατάφωρος εἶναι προυνόει, Γέσσιος δὲ Φλῶρος καθάπερ εἰς ἐπίδειξιν πονηρίας πεμφθεὶς τὰς εἰς τὸ ἔθνος ἡμῶν παρανομίας ἐπόμπευεν, μήτε ἁρπαγῆς παραλιπὼν μηδένα τρόπον μήτε ἀδίκου κολάσεως·"},{"number":255,"text":"ἦν γὰρ ἄτεγκτος μὲν πρὸς ἔλεον, παντὸς δὲ κέρδους ἄπληστος, ᾧ γε μηδὲ τὰ πλεῖστα τῶν ὀλίγων διέφερεν, ἀλλὰ καὶ λῃσταῖς ἐκοινώνησεν· ἀδεῶς γὰρ οἱ πολλοὶ τοῦτʼ ἔπραττον ἐχέγγυον παρʼ ἐκείνου τὴν σωτηρίαν ἐπὶ τοῖς μέρεσιν ἔχειν πεπιστευκότες."},{"number":256,"text":"καὶ τοῦτο μέτριον οὐκ ἦν. ἀλλʼ οἱ δυστυχεῖς Ἰουδαῖοι μὴ δυνάμενοι τὰς ὑπὸ τῶν λῃστῶν γινομένας πορθήσεις ὑπομένειν ἠναγκάζοντο τῶν ἰδίων ἠθῶν ἐξανιστάμενοι φεύγειν ἅπαντες, ὡς κρεῖττον ὁπουδήποτε παρὰ τοῖς ἀλλοφύλοις κατοικήσοντες."},{"number":257,"text":"καὶ τί δεῖ πλείω λέγειν; τὸν γὰρ πρὸς Ῥωμαίους πόλεμον ὁ καταναγκάσας ἡμᾶς ἄρασθαι Φλῶρος ἦν κρεῖττον ἡγουμένους ἀθρόως ἢ κατʼ ὀλίγον ἀπολέσθαι. καὶ δὴ τὴν ἀρχὴν ἔλαβεν ὁ πόλεμος δευτέρῳ μὲν ἔτει τῆς ἐπιτροπῆς Φλώρου, δωδεκάτῳ δὲ τῆς Νέρωνος ἀρχῆς."},{"number":258,"text":"ἀλλʼ ὅσα μὲν δρᾶν ἠναγκάσθημεν ἢ παθεῖν ὑπεμείναμεν, ἀκριβῶς γνῶναι πάρεστιν τοῖς βουλομένοις ἐντυχεῖν ταῖς ὑπʼ ἐμοῦ περὶ τοῦ Ἰουδαϊκοῦ πολέμου βίβλοις γεγραμμέναις."}],"12":[{"number":259,"text":"Παύσεται δʼ ἐνταῦθά μοι τὰ τῆς ἀρχαιολογίας μεθʼ ἣν καὶ τὸν πόλεμον ἠρξάμην γράφειν. περιέχει δʼ αὕτη τὴν ἀπὸ πρώτης γενέσεως ἀνθρώπου παράδοσιν μέχρι ἔτους δωδεκάτου τῆς Νέρωνος ἡγεμονίας τῶν ἡμῖν συμβεβηκότων τοῖς Ἰουδαίοις κατά τε τὴν Αἴγυπτον καὶ Συρίαν καὶ Παλαιστίνην,"},{"number":260,"text":"ὅσα τε πεπόνθαμεν ὑπὸ Ἀσσυρίων τε καὶ Βαβυλωνίων, τίνα τε Πέρσαι καὶ Μακεδόνες διατεθείκασιν ἡμᾶς, καὶ μετʼ ἐκείνους Ῥωμαῖοι· πάντα γὰρ οἶμαι μετʼ ἀκριβείας συντεταχέναι."},{"number":261,"text":"τηρῆσαι δὲ πεπείραμαι καὶ τὴν τῶν ἀρχιερέων ἀναγραφὴν τῶν ἐν δισχιλίοις ἔτεσι γενομένων. ἀπλανῆ δὲ πεποίημαι καὶ τὴν περὶ τοὺς βασιλεῖς διαδοχὴν τὰς πράξεις αὐτῶν καὶ τὰς πολιτείας ἀπαγγέλλων μοναρχῶν τε δυναστείας, ὡς αἱ ἱεραὶ βίβλοι περὶ πάντων ἔχουσι τὴν ἀναγραφήν· τοῦτο γὰρ ποιήσειν ἐν ἀρχῇ τῆς ἱστορίας ἐπηγγειλάμην."},{"number":262,"text":"λέγω δὴ θαρσήσας ἤδη διὰ τὴν τῶν προτεθέντων συντέλειαν, ὅτι μηδεὶς ἂν ἕτερος ἠδυνήθη θελήσας μήτε Ἰουδαῖος μήτε ἀλλόφυλος τὴν πραγματείαν ταύτην οὕτως ἀκριβῶς εἰς Ἕλληνας ἐξενεγκεῖν·"},{"number":263,"text":"ἔχω γὰρ ὁμολογούμενον παρὰ τῶν ὁμοεθνῶν πλεῖστον αὐτῶν κατὰ τὴν ἐπιχώριον παιδείαν διαφέρειν καὶ τῶν Ἑλληνικῶν δὲ γραμμάτων ἐσπούδασα μετασχεῖν τὴν γραμματικὴν ἐμπειρίαν ἀναλαβών, τὴν δὲ περὶ τὴν προφορὰν ἀκρίβειαν πάτριος ἐκώλυσεν συνήθεια."},{"number":264,"text":"παρʼ ἡμῖν γὰρ οὐκ ἐκείνους ἀποδέχονται τοὺς πολλῶν ἐθνῶν διάλεκτον ἐκμαθόντας διὰ τὸ κοινὸν εἶναι νομίζειν τὸ ἐπιτήδευμα τοῦτο μόνον οὐκ ἐλευθέροις τοῖς τυχοῦσιν ἀλλὰ καὶ τῶν οἰκετῶν τοῖς θέλουσι, μόνοις δὲ σοφίαν μαρτυροῦσιν τοῖς τὰ νόμιμα σαφῶς ἐπισταμένοις καὶ τὴν τῶν ἱερῶν γραμμάτων δύναμιν ἑρμηνεῦσαι δυναμένοις."},{"number":265,"text":"διὰ τοῦτο πολλῶν πονησάντων περὶ τὴν ἄσκησιν ταύτην μόλις δύο τινὲς ἢ τρεῖς κατώρθωσαν καὶ τῶν πόνων τὴν ἐπικαρπίαν εὐθὺς ἔλαβον."},{"number":266,"text":"ἴσως δʼ οὐκ ἂν ἐπίφθονον γένοιτο καὶ περὶ γένους τοὐμοῦ καὶ περὶ τῶν κατὰ τὸν βίον πράξεων βραχέα διεξελθεῖν ἕως ἔχω ζῶντας ἢ τοὺς ἐλέγξοντας ἢ τοὺς μαρτυρήσοντας."},{"number":267,"text":"Ἐπὶ τούτοις δὲ καταπαύσω τὴν ἀρχαιολογίαν βιβλίοις μὲν εἴκοσι περιειλημμένην, ἓξ δὲ μυριάσι στίχων, κἂν τὸ θεῖον ἐπιτρέπῃ κατὰ περιδρομὴν ὑπομνήσω πάλιν τοῦ τε πολέμου καὶ τῶν συμβεβηκότων ἡμῖν μέχρι τῆς νῦν ἐνεστώσης ἡμέρας, ἥτις ἐστὶν τρισκαιδεκάτου μὲν ἔτους τῆς Δομετιανοῦ Καίσαρος ἀρχῆς, ἐμοὶ δʼ ἀπὸ γενέσεως πεντηκοστοῦ τε καὶ ἕκτου."},{"number":268,"text":"προῄρημαι δὲ συγγράψαι κατὰ τὰς ἡμετέρας δόξας τῶν Ἰουδαίων ἐν τέσσαρσι βίβλοις περὶ θεοῦ καὶ τῆς οὐσίας αὐτοῦ καὶ περὶ τῶν νόμων, διὰ τί κατʼ αὐτοὺς τὰ μὲν ἔξεστιν ἡμῖν ποιεῖν, τὰ δὲ κεκώλυται."}]},"count":268};})();
